export default [{"id":145,"question":"يُلاحظ أن الجنازة بعدما تخرج من الحرم المكي وهي في طريقها إلى المقبرة عدَّة أمور:الأمر الأول: يقوم بعضُ الأشخاص بالصياح قائلًا: \"وحِّدوه\".ثانيًا: يقف حامل الجنازة عند منطقة تُسمَّى \"مقراة الفاتحة\" ويقرأ فيها بسورة الفاتحة.ثالثًا: تتابع الجنازة سيرها نحو المقبرة وأيضًا يصيح بعضُ الأشخاص: \"وحِّدوه\".ورابعًا: عندما تصل الجنازة إلى باب المقبرة يُوقفها الحاملون لها ويُنزلونها على الأرض، ويصيح أحدُهم: \"ماذا تشهدون عليه؟\" ثم يحملونها مرةً أخرى إلى المقبرة.وخامسًا: وفي المقبرة عندما ينزل الميت وينزل معه بعضُ الأشخاص لتسوية القبر، وبعد أن يُسوَّى القبر يقوم أحدُهم بالأذان في القبر ويُقيم الصلاة.فهل هذا من الشرع في شيءٍ؟","title":"حكم عبارات \"وحِّدوه\" في الجنائز ونحوها","answer":"الجواب: كل هذه بدع: رفع الصوت بـ\"وحِّدوه\" لا أصل له، بل السنة مع الجنازة خفض الصوت، والإنسان يُحاسب نفسه، ويتذكر حال الميت، وماذا يُقال له؟ وماذا يُجيب؟ ولا يقول: \"وحِّدوه\" أو \"اذكروا الله\"، فكل هذا ما له أصل.\nفعلى الإنسان أن يُحاسب نفسه فيما بينه وبين الله وهو ماشٍ مع الجنازة، فيتذكر الموت، ويتذكر عاقبة الموتى، وما يُقال للميت، ويكون عنده خوفٌ وخشوعٌ، ولا يقف عند أي مكانٍ ويقول: \"اقرؤوا الفاتحة\"، لا في مكة، ولا في غير مكة، فهذا بدعة.\nكذلك كونه يضعه ويقول: \"ماذا تشهدون عليه؟\" هذا لا أصل له، يُريدون أن يفضحوه، يقولون: هو فاسق، وإلا هذا غلطٌ، إذا شهد عليه الناسُ من دون طلبٍ لا بأس، إذا قالوا: نعم، جزاه الله خيرًا، وعمل معروفًا، فجزاهم الله خيرًا، والحمد لله أنتم شهداء الله في أرضه، أمَّا أنه يضعها أو يقول: ما تشهدون عليه؟ كل الناس، فلا، هذا بدعة، ما له أصلٌ، وهذا من أسباب الفضيحة أيضًا، أن يفضحه الناسُ إذا كان فاسقًا.\nكذلك الأذان والإقامة في القبر، أو عند قبر؛ لا أصل لها، بل بدعة -نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/3682/حكم-عبارات-وحدوه-في-الجناىز-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0138.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":167,"question":"ما رأي سماحتكم فيمَن يُقيم ما يُسمُّونه بالمولد النبوي؟","title":"حكم من يحتفلون بالمولد النبوي","answer":"الجواب: المولد النبوي ليس له احتفالٌ، ولا يجوز إقامة الاحتفالات به؛ لأنَّ هذا ليس عليه دليلٌ، بل هو بدعة، ولم يفعله النبيُّ ﷺ ولا أصحابه، ولم يأمر بذلك عليه الصلاة والسلام، ولا فعله خلفاؤه الراشدون ، ولا بقية الصَّحابة عليهم رضوان الله، ولا السلف الصَّالح في القرون المفضلة الثلاثة، وإنما أحدثه الرافضةُ في القرن الرابع، ثم تبعهم بعضُ الناس.\nأحدثه الرافضةُ بنو عبيدٍ القداحي يُقال لهم: الفاطميون، أحدثوه في مصر وغيرها، وأحدثوا موالد أخرى لعليٍّ ، وللحسن، والحسين، وفاطمة، ولحاكمهم، ثم تبعهم بعضُ المسلمين جهلًا وغلطًا، وانتشر بين الناس الآن، فلا ينبغي أن يغترّ بالناس في هذا المقام، فالاحتفال بالموالد من البدع المُنكرة، ولا يجوز للمسلمين الاحتفال بالموالد، ولا بمولد النبي عليه الصلاة والسلام، بل كل ذلك بدعة.\nوقد كتب العلماء في ذلك وأوضحوا هذه البدعة، منهم: شيخ الإسلام ابن تيمية رحمه الله، والإمام الشاطبي رحمه الله، وآخرون، بل كتبنا في ذلك عدَّة رسائل وعدَّة مقالات نُشرت وعُمّمت من سنوات كثيرة.\nفالمقصود أنَّ الاحتفال بالمولد النبوي من البدع المُنكرة التي أحدثها بعضُ الناس، وأول مَن أحدثها الرافضة الفاطميون في المئة الرابعة، ثم تبعهم بعضُ الناس تقليدًا وجهلًا.\nوليس حبُّه ﷺ بالموالد والاحتفال، حبُّه ﷺ باتباعه وطاعة أوامره وترك نواهيه والسير على منهاجه عليه الصلاة والسلام، هذا هو الدين، وهذا هو الحب، قال الله تعالى: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31].\nوالصحابة أحبُّ منا للنبي ﷺ وأكمل منا إيمانًا، ولو كان الاحتفال بالمولد أمرًا مشروعًا لفعلوه، وهم خيرٌ منا وأفضل منا، قال فيهم النبيُّ ﷺ: خير الناس قرني، خير أمتي قرني.\nثم هو أنصح الناس ﷺ، وأعلم الناس، ولو كان الاحتفالُ بالمولد أمرًا مشروعًا لعلَّم أمته، وما كتمه، لعلمهم إياه، أو فعله، أو فعله خلفاؤه الراشدون وبيَّنوه.\nفلما لم يقع شيءٌ من هذا ولم يفعله ﷺ ولا أصحابه ولا القرون المفضلة عُرف أنه من البدع، ويقول النبيُّ ﷺ: مَن أحدث في أمرنا هذا –يعني: الدِّين– ما ليس منه فهو ردٌّ يعني: فهو مردودٌ، وقال عليه الصلاة والسلام: مَن عمل عملًا ليس عليه أمرنا فهو ردٌّ يعني: مردودٌ، وقال في خطبته -كما رواه جابرٌ - في خطبة الجمعة كان يقول ﷺ: أما بعد، فإنَّ خير الحديث كتابُ الله، وخير الهدي هديُ محمدٍ ﷺ، وشرَّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة، فأخبر أنَّ شرَّ الأمور مُحدثاتها، وأنَّ كل بدعةٍ ضلالة، زاد النَّسائي: وكل ضلالةٍ في النار، وقال ﷺ في حديث العرباض بن سارية : إياكم ومُحدثات الأمور، فإنَّ كل محدثةٍ بدعة، وكل بدعة ضلالة.\nفالواجب على المسلمين في كل مكانٍ أن يحذروا هذه البدعة، وألا يحتفلوا بالمولد، وأن يحثّوا الناسَ على دراسة السيرة في المدارس والمعاهد والمساجد -سيرة الرسول ﷺ- يتعلَّمون دينه في مساجدهم في جميع الأوقات، وليس في ربيع الأول من كل سنةٍ فقط، لا، يدرسون السيرة النبوية، يتعلمون دين الله في مساجدهم ومدارسهم ومعاهدهم وجامعاتهم في جميع الأوقات في جميع السنة، يتعلمون ويتفقَّهون، لا في ربيع الأول فقط.\nنسأل الله للجميع التوفيق والهداية والفقه في الدين.","link":"https://binbaz.org.sa/fatwas/3705/حكم-من-يحتفلون-بالمولد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross_0161.mp3","categories":["البدع والمحدثات"]},{"id":248,"question":"يا شيخنا، كيف يكون البغضُ في الله على المُبتدعة الذين إن هجرناهم ترتب على هجرنا لهم مفسدة أكبر مما لو خالفناهم ونصحناهم؟","title":"ما الحكمة في هجر أهل البدع والمعاصي؟","answer":"الجواب: الهجر أيُّها الأخ السائل وأيُّها الأخ المُستمع وأيتها الأخت في الله المُستمعة: الهجر علاجٌ ودواءٌ، يُفعل حيث نفع، ويُترك حيث لا ينفع، فالمُبتدع والعاصي المُعلن يستحقّ الهجر بعد أن يُنصح، وبعد أن يُوجَّه إلى الخير، ويُؤْمَر بطاعة الله، ويُنهى عن معصية الله، ويُبَيَّن له غلطه وبدعته، فإذا أصرَّ ولم يقبل النَّصيحة استحقَّ أن يُهجر.\nوقد هجر النبيُّ ﷺ ثلاثةً من خيار الصَّحابة لما تخلَّفوا عن غزوة تبوك بغير عذرٍ، وهم: كعب بن مالك وصاحباه، هجرهم النبيُّ ﷺ والمسلمون خمسين ليلة، ثم تاب الله عليهم فترك هجرهم وسلَّم عليهم الرسولُ ﷺ والمسلمون، وأنزل الله في ذلك قوله تعالى: لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117]، ثم قال بعدها: وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا... الآية [التوبة:118].\nالمقصود أنَّ التوبة علاجٌ، ولهذا هجر النبيُّ ﷺ هؤلاء الثلاثة، وهجرهم المسلمون طاعةً لله ولرسوله؛ لأنَّ في هجرهم مصلحةً، ليتوبوا، وليحذر غيرُهم من التَّخلُّف عن المغازي والجهاد إذا أُمروا بذلك؛ لأنَّ الله أمرهم أن ينفروا فقال: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39]، وقال: انْفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا الآية [التوبة:41]، فإذا أمرهم وليُّ الأمر بالنَّفير وجب النَّفير لقتال الأعداء، فإذا تخلَّفوا استحقُّوا الهجر والعقاب.\nوالرسول ﷺ هجرهم فقط، ولم يبلغنا أنه عاقب أحدًا منهم، ثم تابوا وندموا فتاب الله عليهم، وترك آخرين لم يهجرهم؛ لأنَّ في هجرهم مضرَّةً وشرًّا، ولهذا لم يهجرهم عليه الصلاة والسلام، منهم وعلى رأس: عبدالله بن أبي بن سلول رأس المنافقين، كانت له مواقف خبيثة، كانت له كلمات شنيعة، ومع ذلك تبلغ النبيّ ﷺ ويصفح ويُرشد ويتكلم ويعظ، ولم يُعاقبه، ولم يسجنه، ولم يقتله؛ لأنَّ في قتله وسجنه وطرده من البلاد أو قتله في ذلك خطر كبير على المسلمين؛ لأنه رئيسٌ مطاعٌ في الخزرج، وربما ترتب على قتله أو سجنه أو طرده ما لا تُحمد عقباه، فرأى النبيُّ ﷺ ألا يفعل ذلك، وأن يتألّفه على الخير بالكلمات الطيبة والنصيحة، وله نظائر في المنافقين، له نُظراء، لكنه رأسهم.\nفالمقصود أنَّ الهجر تُراعى فيه المصلحة، فإن كانت المصلحةُ تقتضي الهجر والابتعاد عن الشخص هُجر وتُرك لعله يتوب ويندم، وإن كانت المصلحةُ تقتضي عدم الهجر، بل مُوالاة النَّصيحة، وموالاة التذكير، فعل ذلك، وهذا يعرفه كل أحدٍ بالنظر، فإذا كان صاحبُ المعصية أو صاحبُ البدعة أميرًا، أو ملكًا، أو رئيس الجمهورية، أو ما أشبه ذلك، أو رئيسًا للقبيلة -شيخًا في القبيلة- ترتبت على هجره مفاسد كثيرة؛ فالواجب حينئذٍ أن يتألّف، ويُدعى إلى الله، ويُناصح دائمًا؛ حتى لا يزداد شرُّه، وحتى لا يضرّ الأمة، وهكذا مَن أعلن المعاصي، هذا الحكم في أهل البدع والمعاصي الظَّاهرة.","link":"https://binbaz.org.sa/fatwas/4137/ما-الحكمة-في-هجر-اهل-البدع-والمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0290.mp3","categories":["البدع والمحدثات"]},{"id":381,"question":"نريد تعريفًا ملخصًا ودقيقًا وجامعًا ومانعًا للبدعة وأقسامها، على أنَّ بعض مَن جهل معناها الصحيح يقول: هناك بدعة حسنة، وبدعة سيئة! بل ويقول بعضهم: البدعة تنقسم إلى خمسة أقسام، فالمرجو توضيح هذه المسألة، وجزاكم الله خيرًا.","title":"حكم تقسيم البدعة إلى سيئة وحسنة","answer":"الجواب: هذا نعم، قاله بعضُ أهل العلم، ومثّلوا لذلك بأمثلةٍ لا تُؤيدهم فيما قالوا. والصواب أن البدعة لا تنقسم، وكلها ضلالة كما قاله خيرُ الخلق وأفضلهم وإمامهم عليه الصلاة والسلام، فمَن زعم أنها  تنقسم فقد استدرك على الرسول ﷺ، فالرسول يقول: كل بدعةٍ ضلالةٌ، فهل يجوز لعاقلٍ أو لمكلَّفٍ أو لإنسانٍ يخاف الله ويرجوه أن يقول: لا، ليست كل بدعةٍ ضلالة؟! هذا شيءٌ كبيرٌ وخطيرٌ.\nفالواجب أن يُقال كما قال المصطفى عليه الصلاة والسلام: كل بدعةٍ ضلالة، وأما المسائل التي احتجُّوا بها فليست بدعةً، بل هي من الدين، فاتِّخاذ المدارس واتِّخاذ الرؤوس واتِّخاذ المكتبات وإصلاح الطّرق وغير هذا؛ كله مما جاء به الشرع، ومما دعا إليه الشرع، وليس من البدع، وهو من الدين الذي دعا إليه الرسولُ ﷺ وأمر به، فلا دخل له في البدعة أصلًا.","link":"https://binbaz.org.sa/fatwas/4703/حكم-تقسيم-البدعة-الى-سيىة-وحسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0437.mp3","categories":["البدع والمحدثات"]},{"id":690,"question":"يقول: يا سماحة الشيخ: رأيت البعض من الناس عندما يضعون الميت في اللحد يقومون بالأذان والإقامة فوقه، هل هذا صحيح؟","title":"حكم الأذان والإقامة عند دفن الميت","answer":"الجواب: هذا بدعة، الأذان في القبر والإقامة في القبر بدعة لا تجوز، كل هذا لا يجوز، لا بعد الدفن ولا قبل الدفن، كله لا يجوز.","link":"https://binbaz.org.sa/fatwas/15849/حكم-الاذان-والاقامة-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/58804.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":745,"question":"ما رأيكم فيمَن يُحيون ليلة الخامس عشر من رجب ليلًا بقراءة الحديث والقرآن مجتمعين، نساء ورجالًا في مكانٍ واحدٍ؟","title":"حكم إحياء ليلة الخامس عشر من رجب بعبادة","answer":"الجواب: هذا لا أصل له، بدعة، لا في رجب، ولا في غير رجب، ما هو مشروعٌ إحياء ليلة النصف من رجب، ولا ليلة النصف من شعبان، ولا غيرها، كل هذا ليس عليه دليلٌ، إنما المشروع إحياء ليالي العشر الأخيرة من رمضان، هذا مشروعٌ وجاءت به السنة عن النبي ﷺ: العشر الأخيرة من رمضان، وأما العشرون الأُوَل من رمضان فيُصلي وينام، وأما أن يُحيي ليلةً من رجب أو شعبان أو غيرهما من الشهور فهذا ليس له أصلٌ.","link":"https://binbaz.org.sa/fatwas/20655/حكم-احياء-ليلة-الخامس-عشر-من-رجب-بعبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0573ما حكم أحياء ليلة الخامس عشر من رجب بقراءة القرآن والسنة النبوية نساءاً ورجالاً في مكان واحد؟.mp3","categories":["البدع والمحدثات"]},{"id":746,"question":"يقول: إنَّ والدته أوصته أن يذبح ذبيحةً في خمسة عشر رجب من كل عامٍ، ولكن في هذا العام سمع من بعض الإخوان طلبة العلم أنَّ هذا مُحَرَّمٌ أو مكروهٌ، فامتنعتُ ولم أُنفذ وصية والدتي، فما رأي سماحتكم في تنفيذ هذه الوصية من عدمها؟","title":"حكم تخصيص يوم من رجب للذبح لله تعالى","answer":"الجواب: تخصيصها برجب لا وجهَ له، ولكن إذا نفذتها تارةً كذا، وتارةً في شعبان، وتارةً في رمضان، وتارةً في غيره، تتصدق عنها لا بأس، أما تخصيص رجب فلا وجهَ له، هذا من عمل الجاهلية، ولكن إذا نفذتها في أوقاتٍ أخرى ما تتقيد بشيءٍ، تتصدق بها؛ لا بأس، ومن أحسن ما يكون في رمضان؛ لأن رمضان أفضل الشهور، فإذا نفذتها في رمضان فهذا عملٌ صالحٌ، وإذا نفذتها في وقتٍ آخر: في وقتٍ احتاج فيه الناسُ إلى لحومٍ، أو في وقتٍ وجدتَ فيه فقراء فوزَّعتها بينهم في مكانٍ مناسبٍ فيه فقراء؛ كل هذا حسنٌ.","link":"https://binbaz.org.sa/fatwas/20653/حكم-تخصيص-يوم-من-رجب-للذبح-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0572حكم تخصيص خمسة عشرة من رجب للذبح لله تعالى؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات"]},{"id":765,"question":"هل يجوز مجالسة أهل الفسق والعصيان؟السؤال الثاني: هل مَن سأل الله بأذكارٍ حسنةٍ ثم قال: بجاه نبيك، وبجاه بيتك، ونُصِحَ ولم يستنصح، فما العمل؟","title":"حكم مجالسة العصاة وحكم قول \"بجاه نبيك\"","answer":"الجواب: هذا من التوسل بالجاه والحق وبيت الله العتيق ونحو ذلك، هذه وسيلة غير شرعيةٍ، لم يشرع الله لنا أن نتوسل بجاه فلانٍ، أو حقّ فلانٍ، أو ببيت الله العتيق، أو شبه ذلك، هذه بدعة، ما تكون شركًا، تكون بدعةً، وهي من وسائل الشرك؛ لأنَّ الله قال سبحانه: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ما قال: ادعوه بجاه محمد، أو بجاه الأنبياء، أو بجاه الأولياء، أو بحقِّ بيته العتيق، لا، قال: فَادْعُوهُ بِهَا أي: بأسمائه، فهو يُدعى بأسمائه وصفاته، ويدعي بتوحيده، كما جاءت الأحاديث بذلك، كما في الحديث: اللهم إني أسألك بأني أشهد أنَّك أنت الله، لا إله إلا أنت، هذا توسل بالتوحيد، ومثل أحاديث أهل الغار الذين انطبقت عليهم صخرةٌ لما أووا إلى غارٍ في ليلٍ وفي مطرٍ، فانطبقت عليهم صخرةٌ وسدَّت عليهم فم الغار، فلم يستطيعوا الخروج، فقالوا فيما بينهم: لا يُنجينا من هذا إلا أن نتوسَّل إلى الله بأعمالنا الخالصة، فتوسَّلوا إلى الله: واحد توسَّل ببره لوالديه، والثاني توسَّل بعفَّته عن الزنا، والثالث توسَّل بأدائه الأمانة؛ ففرَّج الله عنهم.\nفإذا توسل الإنسانُ بأسماء الله، أو بتوحيد الله، أو بقوله: \"بإيماني بك، ومحبَّتي لك\"، أو \"بإيماني بنبيك، ومحبتي لنبيك\"، أو \"بأداء ما فرضتَ عليَّ من طاعتك\"، أو \"بترك ما حرمتَ عليَّ\"، هذا توسّل إلى الله بأعمالٍ صالحةٍ، لا بأس.\nوأما مُعاشرة الفُسَّاق ومُجالستهم فلا تجوز؛ لأنهم يجرُّونه إلى فسقهم وضلالهم، لكن إذا خالطهم للدَّعوة إلى الله، وإنكار ما هم عليه من الباطل، وتوجيههم إلى الخير، لهذا القصد: يأمرهم وينهاهم ويُبصرهم؛ فلا بأس، هو مأمورٌ به، أما أن يتَّخذهم أصحابًا وخِلَّانًا يُجالسهم ويأكل معهم فلا؛ لأنَّهم يجرُّونه إلى البلاء.","link":"https://binbaz.org.sa/fatwas/20704/حكم-مجالسة-العصاة-وحكم-قول-بجاه-نبيك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0600هل يجوز مجالسة أهل الفسق والعصيان؟وهل من سأل الله بإذكار حسنة ثم قال بجاه نبيك وبجاه بيتك؟.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":822,"question":"ما حكم التَّكبير الجماعي أو الفردي عند الإعجاب بأمرٍ ما، أو عند تحقيق أمرٍ ما؟","title":"ما حكم التكبير عند الإعجاب بتحقق أمر ما؟","answer":"الجواب: أما التَّكبير الفردي: كونه يُكبّر بنفسه فهذا مشروعٌ، كان النبيُّ ﷺ يُكبِّر إذا رأى ما يُعجبه، ويُكبر إذا انتُهِكَتْ محارم الله عليه الصلاة والسلام، ويقول: سبحان الله!، ويقول: الله أكبر، ولما قال له بعضُ الصحابة: اجعل لنا ذات أنواطٍ كما لهم ذات أنواط، قال: الله أكبر، إنها السنن، ولما قال له بعضُ الناس: نستشفع بالله عليك، وبك على الله، قال: سبحان الله! سبحان الله!، ولما قال للصحابة : إني لأرجو أن تكونوا ربعَ أهل الجنة كبَّروا، ثم قال: إني لأرجو أن تكونوا ثلث أهل الجنة كبَّروا، ثم قال: أرجو أن تكونوا شطر أهل الجنة كبَّروا، هذا هو السنة.\nأما الجماعي بصوتٍ واحدٍ يرفعونه جميعًا، ويُوقفونه جميعًا؛ فلا أصل له فيما نعلم، بل هو فيما نعلم من جملة البدع، كونهم يرفعونه بصوتٍ واحدٍ، وينهونه بصوتٍ واحدٍ كلهم جميعًا؛ هذا لا أصل له. أما كون هذا يُكبِّر، وهذا يُكبِّر، فتلتقي الأصوات في المساجد، أو في الطرقات، كلٌّ يُكبِّر على حاله من دون مراعاةٍ لنغمةٍ واحدةٍ، ولا أسلوبٍ واحدٍ، ولا إنهاء واحدٍ، فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/20848/ما-حكم-التكبير-عند-الاعجاب-بتحقق-امر-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0644ما حكم التكبير الجماعي أو الفردي عند الاستعداد لأمر ما أو عند تحقيق لأمر ما؟ ابن باز.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":833,"question":"ما حكم غرس الأشجار على القبور؟","title":"ما حكم غرس الأشجار على القبور؟","answer":"الجواب: غرس الأشجار على القبور بدعة..؛ لأن النبي ﷺ لم يغرسها على القبور، وإنما غرس على قبرين أطلعه الله على تعذيبهما: أحدهما كان يمشي بالنَّميمة، والآخر كان لا يستتر من البول، فقطع... جريدة، وقال: لعله يُخفف عنهما ما لم تيبسا، ولم يفعل هذا في قبور المسلمين في البقيع، ولا أهل مكة، ولا في غير ذلك...، فلا يُشرع هذا، وهو بدعة.","link":"https://binbaz.org.sa/fatwas/20857/ما-حكم-غرس-الاشجار-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0652حكم غرس الأشجار على القبور؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":901,"question":"ما حكم الموالد في الإسلام؟","title":"ما حكم الموالد في الإسلام؟","answer":"الجواب: الموالد الاحتفال بها كله بدعة، جميع الموالد: بالأنبياء أو بالصَّالحين أو بغيرهم أو بالأمراء أو بالملوك أو بالزعماء؛ الاحتفال بالموالد بدعة لا أساسَ لها، لم يفعلها المصطفى عليه الصلاة والسلام، ولا خلفاؤه الراشدون، وهم أفضل الناس بعد الأنبياء، فما احتفل المسلمون بمولده ﷺ، ولا احتفل هو بمولده، ولا أمر الناسَ بذلك، ولا فعله الصديقُ، ولا عمر، ولا عثمان، ولا علي، ولا الصحابة، ولا القرون المفضلة، والخير كله في اتِّباعهم: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، خير أمتي قرني، ثم الذين يلونهم، ثم الذين يلونهم، ولم يفعله أهلُ هذه القرون، ويقول ﷺ: مَن عمل عملًا ليس عليه أمرُنا فهو ردٌّ، ويقول ﷺ: مَن أحدث في أمرنا هذا ما ليس منه فهو ردٌّ يعني: فهو مردودٌ على مَن أحدثه، وإن كانت فيه صلاةٌ على النبي ﷺ، وإن كان فيه قرآنٌ، لكن لا يجوز إحداث شيءٍ مما شرعه الله، ولو قال إنسانٌ: أنا أُحدث للناس صلاةً سادسةً، أنا ملك، وأنا زعيم، أجعل لهم صلاةً الساعة تسع زوالي نهارًا، يُصلون صلاةً سادسةً ركعتين أو ثلاثًا أو أربع ركعات، أو آمرهم أن يحجُّوا في السنة مرتين، أكثر للأجر، بدلاً من حج في سنة يحجّون سنتين، أو نزيد ركعةً، فبدلًا من أن تكون الفجرُ ثنتين تصير ثلاثًا، والمغرب ثلاثًا تكون أربعًا، والظهر والعصر والعشاء بدل أربع تكون ستًّا!\nهذا مبتدعٌ ضالٌّ ولو قصد الخير، أو قال: أشرع لهم صيامًا خاصًّا مع رمضان، يصومون فيه اثنين وثلاثين أو ثلاثة وثلاثين أو أربعين، بدلًا من ثلاثين يكون أربعين، أكثر للأجر؛ يكون ضالًّا مُبتدعًا ولو قصد الخير، ولا يجوز أن يُطاع في ذلك.\nأو قال في الزكاة: بدل 2,5% اجعلها 5%، الناس عندهم أموال كثيرة ... خمسة في المئة ..\nأما أخذ شعره وريقه وعَرَقِه فعله الصحابةُ معه ﷺ، سنة، جعل الله فيه البركة، أما تتبع الآثار الأرضية -الأمكنة الأرضية- فهذا بدعة، كما أنكر ذلك عمرُ والصحابةُ ، كونه يتتبع المكان الذي صلَّى فيه حتى يُصلي فيه، أو المكان الذي..... فيه، أو المكان الذي بال فيه يبول فيه، هذا كان ابنُ عمر يتحرَّى، وقد أنكر عليه أبوه، وأنكره الصحابةُ، فلا ينبغي هذا، وإن فعله ابنُ عمر اجتهادًا منه فالصواب ما فعله كبارُ الصحابة الذين هم أعلم منه بهذا رضي الله عنهم جميعًا.\nولهذا قطع عمرُ الشجرةَ التي بُويع تحتها، لما بلغه أن ناسًا يقصدونها للصلاة عندها، ولما بلغه أنَّ أناسًا يقصدون المواضع التي صلَّى فيها النبي أنكر عليهم وقال: \"إنما هلك مَن كان قبلكم بمثل هذا، كانوا يتبعون آثار أنبيائهم، مَن أدرك الصلاةَ في هذا فليُصلِّ وإلا فليَمْضِ\".","link":"https://binbaz.org.sa/fatwas/20942/ما-حكم-الموالد-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0738ما حكم الموالد في الإسلام؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات"]},{"id":903,"question":"ما حكم مَن يختم قراءته بالفاتحة؟","title":"حكم مَن يختم قراءته للقرآن بالفاتحة","answer":"الجواب: لا أصلَ لهذا فيما نعلم، بل هو بدعة، لا أصل لهذا، ما كان النبيُّ يفعل هذا ولا أصحابه ، وكل خيرٍ في الاقتداء به عليه الصلاة والسلام واتِّباع سلف هذه الأمة، قال عليه الصلاة والسلام: مَن عمل عملًا ليس عليه أمرُنا فهو ردٌّ.","link":"https://binbaz.org.sa/fatwas/20940/حكم-من-يختم-قراءته-للقران-بالفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0736ما حكم من يختم قراءته بالفاتحة؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات"]},{"id":904,"question":"ما حكم قراءة القرآن عند العزاء؟","title":"ما حكم قراءة القرآن عند العزاء؟","answer":"الجواب: ليس له أصلٌ، ولا نعلم له أصلًا، لكن إذا وقع صدفةً من غير قصدٍ -إذا اجتمعوا وقرأ واحدٌ منهم- فلا بأس، أما أن يُتَّخذ لهذا نظامٌ فهذا ليس له أصلٌ في العزاء، لا وجود القرَّاء، ولا إيجاد المآكل والمطاعم، ولا غير ذلك. لكن أهل الميت إذا نزل بهم الضيفُ لا بأس أن يُكرموه، أو جاءتهم أطعمةٌ كثيرةٌ ودعوا إليها مَن يأكلها لا بأس، أما أن يُقيموا مأتمًا لأجل الميت، فيذبحوا الذَّبائح لأجل الميت، ويدعوا القرَّاء لأجل الميت، هذا ليس له أصلٌ، بل هو من البدع التي أحدثها الناسُ، أما كونهم اجتمعوا وجلسوا في مكانٍ يتذاكرون، أو يُعزِّي بعضُهم بعضًا، وقرأ أحدُهم بعض الآيات، هذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/20939/ما-حكم-قراءة-القران-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0735ما حكم قراءة القرآن عند العزاء؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":929,"question":"يقول: ما حكم تخصيص ليلة سبع وعشرين من رجب بعمرةٍ أو بصيامٍ أو بصدقةٍ؟","title":"حكم تخصيص سبع وعشرين من رجب بعبادة","answer":"الجواب: هذا لا أصلَ له، هذا يُسمونه: ليلة الإسراء والمعراج، هذا غلطٌ، لا أصلَ لهذا، ولم يثبت في هذا شيء، فلا يجوز تخصيصها لا بعمرةٍ ولا باحتفالٍ ولا بغير ذلك؛ لأنها ليس لها تخصيصٌ، ولو ثبت أنها ليلة المعراج والإسراء لم تخصّ بشيءٍ؛ لأن الرسول ما خصَّها بشيءٍ، التَّخصيص عبادة، والعبادة توقيفية، فلا يجوز تخصيص ليلةٍ من رجب أو غيرها بشيءٍ: لا بصلاةٍ، ولا غيرها.","link":"https://binbaz.org.sa/fatwas/20955/حكم-تخصيص-سبع-وعشرين-من-رجب-بعبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0751ما حكم تخصيص ليلة سبع وعشرين من رجب لعمرة أو لصيام أو لصدقة؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات"]},{"id":973,"question":"أُشهد الله على أني أحبُّك في الله، ثم أرجو من سماحتكم التَّعليق على الرَّجبية، حيث أنها بعد أيام قليلةٍ وفَّقكم الله؟","title":"ما حكم تخصيص شهر رجب بعبادات معينة؟","answer":"الجواب: أما ما ذكرتَ من المحبَّة فنقول: أحبَّك الله الذي أحببتنا له، والتَّحابُّ في الله من القُربات التي يُحبُّها الله ، وأهلها من السبعة الذين يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله، كما قال النبيُّ ﷺ سبعةٌ يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمامٌ عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله وهكذا المرأةُ إذا دعاها ذو منصبٍ وجمالٍ فقالت: إني أخاف الله، من السبعة الذين يُظلُّهم الله في ظلِّه يوم لا ظلَّ إلا ظله، وهكذا السادس: رجلٌ تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، والسابع: رجلٌ ذكر الله خاليًا ففاضتْ عيناه، ذكر الله وما عنده أحدٌ فبكى من خشية الله جلَّ وعلا، فهو من السبعة الذين يُظلُّهم الله في ظله يوم لا ظلَّ إلا ظله.\nويقول عليه الصلاة والسلام: يقول الله يوم القيامة على رؤوس الأشهاد: أين المتحابُّون بجلالي؟ اليوم أُظلُّهم في ظلِّي يوم لا ظلَّ إلا ظلي، جعلنا الله وإياكم من المتحابين بجلاله، ورزقنا جميعًا الاستقامة.\nأما ما يتعلق بالرَّجبية: فلا أعلم فيها نصًّا يدل على شرعيتها، يعني: زيارة المسجد النبوي، أما العمرة في رجب فلا بأس بذلك، قد ثبت في \"الصحيحين\" من حديث ابن عمر رضي الله عنهما: أن النبي ﷺ اعتمر في رجب، وقد قال بعضُ أهل العلم: إنه وهم ابن عمر في ذلك، ولكن الأصل عدم الوهم، الأصل في الراوي الثقة: الحفظ وعدم الوهم.\nوثبت عن السلف أنهم كانوا يستحبُّون العمرةَ في رجب: منهم عمر ، ورجب شهرٌ حرامٌ، من الشهور الأربعة الحرم، فالعمرة فيه لا بأس بها، بل هي من عمل السلف.\nأما زيارة المسجد النبوي في رجب فلا أعلم فيها نصًّا، ولا أعلم فيها شيئًا عن السلف الصالح، وهي تابعة للعمرة، مَن جاء العمرة يحب أن يزور المسجد النبوي، وزيارة المسجد النبوي مشروعة دائمًا في كل وقتٍ، فإذا زار المسجد النبوي لأجل أن الله يسَّر له العمرة، أو يسَّر الله له هذه الزيارة في رجب؛ لأنه لم يتيسر له في غيرها فلا بأس بذلك، أما تخصيص الزيارة في رجب فلا أعلم لها أصلًا، لكن إذا فعل ذلك من أجل أنه جاء للعمرة، أو من أجل أنه لا يسمح له إلا في رجب، أو لأسبابٍ أخرى؛ فلا بأس بذلك، ولا كراهةَ في ذلك إن شاء الله.\nس: والصيام؟\nج: والصيام مكروهٌ، إفراد رجب بالصيام مكروهٌ.","link":"https://binbaz.org.sa/fatwas/21009/ما-حكم-تخصيص-شهر-رجب-بعبادات-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0806ارجو من سماحتكم التعليق على الرجبية؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات"]},{"id":1011,"question":"ورد إلينا عددٌ من الأسئلة، يسأل أصحابُها عن حكم القراءة على الميت في حال الدفن في المقبرة، أو بعد الدفن، كنحو قراءة الفاتحة على وجه الخصوص، وعن حكم الأذان والإقامة في أُذن الميت قبل الدفن؟","title":"حكم القراءة على الميت حال الدفن والأذان في أُذُنه","answer":"الجواب: هذا من البدع: القراءة على الميت بعد الدفن، أو عند القبر، أو الأذان في القبر، أو الإقامة في القبر، أو القراءة في القبر، كلها بدع لا تجوز، ليس لها أصلٌ، ولم يفعلها المصطفى ﷺ ولا أصحابه، فلا يجوز للمؤمن أن يقرأ على الميت عند القبور، ولا يقرأ عليه في القبر، ولا وهو موضوعٌ في بيته، أو في القبر، أو عند القبر، ولا يُقيم أو يُؤذن في القبر، كل هذا لا أصلَ له. إنما يُقرأ عند الإنسان المُحْتَضر قبل أن يموت؛ لعله يستفيد وينتفع، وأما بعد الموت فقد انقطع عملُه إلا مما قدَّم، كما في الحديث الصَّحيح: يقول النبيُّ ﷺ: إذا مات ابنُ آدم انقطع عملُه إلا من ثلاثٍ: صدقة جارية –يعني: وقفًا أجراه- أو علم يُنتفع به، أو ولد صالح يدعو له.","link":"https://binbaz.org.sa/fatwas/21065/حكم-القراءة-على-الميت-حال-الدفن-والاذان-في-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0861حكم القراءة على الميت في حال الدفن في المقبرة أوبعد الدفن؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":1034,"question":"ورد في بعض الكتب أنَّ آخر يوم من الأسبوع في شهر صفر يُوصَى فيه ببعض الأدعية وغير ذلك، هل من السنة فعل شيءٍ من ذلك اليوم؟","title":"هل صح شيء من الأدعية في شهر صفر؟","answer":"الجواب: لا، ما له أصل، ما في صفر شيءٌ، ما له أصل، لا في أوله، ولا في آخره. والتَّشاؤم من صفر أيضًا منكر، لا أصلَ له، النبي ﷺ قال: لا عدوى، ولا طيرة، ولا هامَة، ولا صفر. فليس في صفر يومٌ معلومٌ يُدْعَى فيه، أو يُتبرك فيه، كل هذا باطلٌ.","link":"https://binbaz.org.sa/fatwas/21091/هل-صح-شيء-من-الادعية-في-شهر-صفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0887ورد في بعض الكتب أن آخر يوم من شهر صفر يوصى فيه ببعض الأدعية هل هذا صحيح؟ ابن باز.mp3","categories":["البدع والمحدثات"]},{"id":1111,"question":"أنا شابٌّ أُعاني من مشكلةٍ كبيرةٍ متعلقةٍ بالعقيدة، هذه المشكلة جعلتني أعيش في همٍّ وغمٍّ، ألا وهي: إني أعمل هنا في جدَّة، وأهلي في جيزان، وهم يعملون بعض البدع: كالمولد النبوي، وهذا المولد يحدث فيه الحلفُ بغير الله، والاستغاثة بالرسول ﷺ والأولياء والصَّالحين، وغير ذلك من الشرك بالله ، إضافةً إلى أمورٍ لم يُنزل الله بها من سلطانٍ، وكلما نصحتُهم لا يستمعون إليَّ، بل يُقاطعونني، ويغضبون عليَّ، أُريد أن أُنقذ والدتي وإخواني من هذه الهاوية، ولكن لا أدري ماذا أصنع معهم في مُعارضتهم لي؟ فما توجيهكم لي، ونصيحتكم لي بالطريقة المُقنعة لكي يتركوا هذا الشيء؟ وكيف أنصحهم وأنا بعيدٌ عنهم؟ أرجو تفضّلكم بالإجابة، فإنني في همٍّ عميقٍ. جزاك الله خيرًا.","title":"حكم الاحتفال بالمولد النبوي وغيره من الموالد","answer":"الجواب:\nالبدع شرُّها عظيم، وعاقبتها وخيمة، وقد قال النبيُّ ﷺ: مَن أحدث في أمرنا هذا ما ليس منه فهو ردٌّ يعني: فهو مردودٌ، وقال عليه الصلاة والسلام: مَن عمل عملًا ليس عليه أمرُنا فهو ردٌّ يعني: فهو مردودٌ.\nوالشيطان له مع المسلم نزغتان: نزغة إلى البدع، ونزغة إلى التقصير والمعاصي، فأيّتهما أدركها فعلها، فهو يُزين للناس البدع، ويدعوهم إليها، حتى يزيدوا في الدين، ويُزين للناس المعاصي، حتى يقترفوا المعاصي، وينقص دينهم، وينقص إيمانهم.\nوالاحتفال بالموالد من البدع، كما نصَّ على ذلك شيخُ الإسلام ابن تيمية والإمام الشاطبي وجماعةٌ آخرون بيَّنوا ذلك؛ لأنَّ الرسول ﷺ لم يحتفل بالمولد في المدينة في حياته، ولا خلفاؤه الراشدون، ولا أمر بذلك، ولا أرشد إليه، ولم يفعله المسلمون في القرون المفضلة، وهم أعلم الناس، وأفضل الناس، ولو كان خيرًا لسبقونا إليه.\nولأنَّ الاحتفال بالموالد قد يقع فيها الشرك، كما قال السائلُ، قد يقع فيها أيضًا شرك، فالاحتفال بالمولد وكونهم يجتمعون في ليلة اثني عشر، أو في يوم اثني عشر، أو في أي مكانٍ، يذكرون مولد النبي ﷺ، ويحتفلون به، ووضعوا له نظامًا: من مائدةٍ، أو أكلٍ وشربٍ وغير ذلك؛ هذه بدعة لا أساس لها، والنبي عليه الصلاة والسلام قال في خطبته في الجمعة: إنَّ خير الهدي هدي محمدٍ ﷺ، قال: وشرُّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة، وقال: إياكم ومُحدثات الأمور، فإنَّ كل محدثةٍ بدعة، وكل بدعةٍ ضلالة.\nوإذا صار مع الاحتفال الاستغاثة بالرسول ﷺ، أو بالأولياء، يقول: يا رسول الله، أغثني، أو اشفني، أو انصرني، أو انصرنا على عدونا. صار هذا شركًا أكبر مع البدعة، شرك أكبر إذا استغاث بالرسول ﷺ، أو بغيره من الموتى، أو بالأصنام، أو بالنجوم، والكواكب، صار شركًا أكبر.\nوهذا يقع في كثيرٍ من الناس في الموالد: مولد البدوي، ومولد الحسين، ومولد الشيخ عبدالقادر، ومولد النبي، يقع منهم الشركُ في هذا، يستغيثون بالرسول ﷺ، ويستغيثون بالأولياء، ويدعونهم مع الله، هذا شركٌ أكبر، أعظم من بدعة المولد، والله يقول جلَّ وعلا: وَلَا تَدْعُ مِنْ دُونِ اللَّهِ مَا لَا يَنْفَعُكَ وَلَا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝  إِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13- 14]، فسمَّى دعاءهم: شركًا، فالواجب الحذر من ذلك؟\nوعليك أيها السائل أن تستعين بإخوانك الطيبين: من أعمامك، أو جيران والدك الطيبين، حتى ينصحوه، وهكذا مَن يعرفهم من أهل العلم، تقول لهم حتى ينصحوه ويُوجِّهوه إلى الخير، وأنت عليك بالأسلوب الحسن، والكلام الطيب مع والدك، حتى يهديه الله، وحتى يقبل الحقَّ، وحتى يقبل منك ومن غيرك النَّصيحة.\nوقد كتبنا في هذا رسائل، وهي موجودة تُوزَّع، بعنوان \"التحذير من البدع\"، وفيها ما يتعلق بالمولد، وبيان الأدلة على بدعته، وأنه بدعة، وأنه من وسائل الشرك، ودعاء الأموات، والاستغاثة بالأموات، ففي إمكان السائل أن يُراجع المكتب، ويأخذ نسخةً من هذا حتى تُعطيه أباك أو غيره.\nوفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21169/حكم-الاحتفال-بالمولد-النبوي-وغيره-من-الموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0965التحذير من البدع ومنها بدعة المولد.mp3","categories":["البدع والمحدثات"]},{"id":1126,"question":"إنَّ ليلة السابع والعشرين من رجب هي ليلة الإسراء كما يقول بعضُهم، ولكن بعض إخواننا في الله أنكر ذلك، فما رأي فضيلتكم في هذا جزاكم الله خيرًا؟ وهل في هذا الوقت عملٌ مشروعٌ يعمله المرء؟","title":"هل صح شيء في ليلة الإسراء والاحتفال بها؟","answer":"الجواب:\nبعض المؤرخين للسيرة يرون أنَّ ليلة سبعٍ وعشرين هي ليلة الإسراء والمعراج، ويحتفلون بها، وهذا شيءٌ لا أصلَ له، وليلة الإسراء والمعراج لم تُحفظ، وهذا بحكمة الله  أن نسيها الناسُ، وذلك من أسباب عدم الغلو فيها. وهي حقٌّ، فالله جل وعلا أسرى بنبيه إلى المسجد الأقصى، ثم عُرج به إلى السماء، كما قال جلَّ وعلا: سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى [الإسراء:1]، هذا أمرٌ مقطوعٌ به، لا شكَّ فيه، ولكنَّ الليلة التي وقع فيها هذا الأمر غير معروفةٍ، ومَن قال: إنها ليلة سبعٍ وعشرين من رجب فقد غلط، وليس معه دليلٌ، والحديث الوارد في ذلك ضعيفٌ.\nولو عُلمت، ولو تيقَّنَّاها في ليلة سبعٍ وعشرين أو في غيرها؛ لم يُشرع لنا أن نُحييها بعبادةٍ أو باحتفالٍ؛ لأن هذا بدعة، لو كان هذا مشروعًا لفعله النبي ﷺ، واحتفل بها، أو خلفاؤه الراشدون، أو الصحابة، فلما لم يحتفلوا بها: لا في حياته ﷺ، ولا بعد وفاته، دلَّ على أن الاحتفال بها بدعة، ليس لنا أن نُحْدِث شيئًا ما شرعه الله، فالله ذمَّ قومًا فقال: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، وقال الله سبحانه في حقِّ نبيه ﷺ: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ  ۝  إِنَّهُمْ لَنْ يُغْنُوا عَنْكَ مِنَ اللَّهِ شَيْئًا [الجاثية:18- 19]، فالله أمره أن يلزم الشريعة فقط، وأنكر على مَن خالفها أو أحدث شيئًا ما شرعه الله.\nوقال عليه الصلاة والسلام: مَن أحدث في أمرنا –يعني: في ديننا- هذا ما ليس منه فهو ردٌّ يعني: فهو مردودٌ، وقال: خير الحديث كتاب الله، وخير الهدي هدي محمدٍ ﷺ، وشرّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة.\nفلا يجوز الاحتفال بليلة سبعٍ وعشرين على أنها ليلة الإسراء والمعراج، ولا بغيرها من الليالي التي لم يشرع الله الاحتفال بها.\nأما ليالي العشر من رمضان فهذه مشروعٌ فيها قيام الليل والتَّهجد والقراءة والدعاء؛ لأن الرسول فعلها عليه الصلاة والسلام، وفيها ليلة القدر.\nفالواجب الانتباه والحذر من البدع، ولا ينبغي للعاقل أن يغترَّ بالناس، يقول: فعل الناس، لا، لا يغترَّ بفعل الناس، العبرة بالدليل، فلا يغتر بفعل الناس بالموالد، وكون كثيرٍ من الناس يفعله في كثيرٍ من البلدان الإسلامية، لا يغتر بهذا، يقول الله جلَّ وعلا: وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116].\nفالواجب التَّمسك بالدليل، ومَن فعل فعلًا يتعبد به يُقال له: ما دليلك؟ وأيش الدليل؟ لسنا نتعبد بالأهواء، لو قال إنسانٌ: أنا أزيد في الأذان، بدلًا من أن نقول: لا إله إلا الله مرة واحدة، نحطّها مرتين: لا إله إلا الله، لا إله إلا الله، في الأذان، هذا بدعة، ولو أنها كلمة حقٍّ، ولو قال: أحطّ التَّكبير خمس بدل أربع في أوله، خمس بدعة، ولو قال: أحطّ الشهادتين ست شهادات، صارت بدعة، ولو قال: حي على الصلاة، أحطها ثلاثًا، صارت بدعة، لا بد أن تُقيد بالشريعة.\nوهكذا لو قال: الظهر أحطّها خمسًا، والعصر أحطّها خمسًا، والعشاء أحطّها خمسًا، والمغرب أحطّها أربعًا، والفجر أحطّها أربعًا، صارت بدعة، منكر، باطل، الناس عليهم التَّقيد بالشريعة، ليس لهم الزيادة.\nوهكذا لو قال: خمس صلوات ما تكفي، نحطّها ست صلوات، تصير الضحى واحدة، أو وسط الليل، صارت بدعة منكرًا ما يجوز، ليس للناس الزيادة إلا ما شرعه الله أبدًا، لا يزيدون، أو قال: صيام رمضان ما يكفي، نحطّ شهرًا آخر، لازم الناس يصومون ربيع أول أو ربيع ثانٍ زيادة خيرٍ؛ ما يجوز، لا بد من التَّقيُّد بالشريعة وعدم الزيادة.","link":"https://binbaz.org.sa/fatwas/21178/هل-صح-شيء-في-ليلة-الاسراء-والاحتفال-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0974هل ليلة السابع والعشرين من رجب في ليلة الأسراء وهل في هذه الليلة عمل مشروع؟.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":1144,"question":"ما حكم دبلة الخطوبة لكلٍّ من الرجل والمرأة؟","title":"ما حكم دبلة الخطوبة للرجل والمرأة؟","answer":"الجواب:\nهذه لا أصلَ لها، ينبغي تركها، لا أصل لها، بل هذه من المحدثات التي أحدثها الناسُ وتلقوها عن الخارج، تركها هو الذي ينبغي.","link":"https://binbaz.org.sa/fatwas/21188/ما-حكم-دبلة-الخطوبة-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0984ما حكم دبلة الخطوبة للرجل والمراة؟.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":1258,"question":"هناك مَن يذبح في شهر رجب ويُسميها: ذبيحة المعراج؟","title":"ما حكم ما يُسمّى \"ذبيحة المعراج\" في رجب؟","answer":"الجواب:\nهذه ما لها أصلٌ، هذه بدعة، الاحتفال بليلة المعراج ليلة سبعٍ وعشرين بدعة، لا أصل لها، والمعراج غير محفوظٍ زمنه، المعراج ثابتٌ، والإسراء ثابتٌ، ولكن ليلته ويومه غير معروفٍ، ولو عرف اليوم أو الليلة لم يُشرع لنا الاحتفال بها ولا به، إذا كان الرسولُ ﷺ لم يحتفل به، ولا الصحابة، ما نحتفل به، إنما نتبع ولا نبتدع، ليس علينا أن نبتدع، يقول الله جلَّ وعلا ذامًّا لقومٍ ابتدعوا، يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، ويقول ﷺ: مَن أحدث في أمرنا هذا ما ليس منه فهو ردٌّ، وكان يقول في خطبة الجمعة عليه الصلاة والسلام: أما بعد: فإنَّ خير الحديث كتابُ الله، وخير الهدي هدي محمدٍ ﷺ، وشرّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة خرَّجه مسلمٌ في \"الصحيح\".\nفلا يجوز الاحتفال بليلة الإسراء والمعراج، ولا بالمولد، مولد فلان، ولا مولد النبي ﷺ، ولا بمولد البدوي، ولا مولد عبدالقادر، ولا مولد الصديق، ولا علي، ولا فاطمة، لماذا؟ لأنَّ الرسول ما فعله ﷺ، والصحابة ما فعلوه، ولا أمر به النبيُّ، فليس لنا أن نُحدِث شيئًا ما فعله نبينا ﷺ ولا خير القرون، ما نكون كمَن قال الله فيهم: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ، ولا نقع في الحديث: مَن عمل عملًا ليس عليه أمرنا فهو ردٌّ يعني: فهو مردودٌ.\nيكفينا ما شرع الله، نجتهد فيما شرع الله: من الصلاة، والصدقات، والصيام، والحج، والصلاة على النبي ﷺ، والحث على اتباع سنته، وتعظيم أمره، أما الاحتفال فما لنا فيه حاجة، يكفينا ما شرع الله، الإحداث غلطٌ، وتنقص للشريعة، واتهام للنبي ﷺ أنه ما بلَّغ البلاغ المبين.\nس: بعضهم في يوم العيد يُوجِّهون الذَّبيحة إلى القبلة ويقولون أنها تحج؟\nالشيخ: هذا لا أصل له، الأفضل أن الذَّبيحة تُوجَّه إلى القبلة، سواء أضحية أو غيرها، الأفضل أنها تُوجَّه عند الذبح إلى القبلة، ولكن قول \"أنها تحج\" البهائم ما لهم حج، هذه خُرافة من خُرافات العامَّة.","link":"https://binbaz.org.sa/fatwas/21316/ما-حكم-ما-يسمى-ذبيحة-المعراج-في-رجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1059هناك من يذبح في شهر رجب ويسميها ذبيحة المعراج فما الحكم؟ ابن باز.mp3","categories":["البدع والمحدثات"]},{"id":1292,"question":"هناك أناسٌ يقومون باحتفالات بمولد النبي ﷺ، فهل يجوز ذلك؟","title":"ما حكم الاحتفال بمولد النبي عليه الصلاة والسلام؟","answer":"الجواب:\nالاحتفال بالموالد من البدع، سواء كان مولد النبي ﷺ، أو مولد علي، أو الحسين، أو الحسن، أو فاطمة، أو غيرهم، لا يجوز الاحتفال بالموالد؛ لأن الرسول ﷺ ما فعلها ﷺ، لا في حياته، ولا فعلها أصحابه، ولم يأمر بذلك عليه الصلاة والسلام، ولو كان خيرًا لسبقونا إليه، لو كان شيئًا طيبًا لفعله ﷺ، وأرشد أصحابه إلى ذلك وفعلوه في حياته أو بعد وفاته، وما فعله الصحابةُ مع الصديق، ولا مع عمر، ولا مع عثمان، ولا مع علي، ولا مع غيرهم، ولا في القرون المفضلة: الأول والثاني والثالث، إنما حدث في الرابع بواسطة الفاطميين الشيعة، ثم وقع من بعض الملوك بعد ذلك، ثم انتشر في الناس، واقتدى بعضُهم ببعضٍ، وهو بدعة.\nوالنعمة العظيمة ما هي بالمولد، النعمة العظيمة بالمبعث، حين بعثه الله نبيًّا ورسولًا، حتى نفع الله به العباد والبلاد، أما المولد فهو أول البشارة، أول الخير، لكن النعمة العظمى بعثته ﷺ في رمضان، وإنزال القرآن عليه، حتى هدى الله به مَن هدى، وصار نبيًّا رسولًا.\nلكن لا بأس أن يُدرس المولد، وحياة النبي ﷺ، ومغازيه، يُدرس في المدارس، في المساجد، من دون أن يكون احتفال في يومٍ معلومٍ من السنة، يُدرس مثلما تُدرس أحكام الصلاة، وأحكام الغزوات، وأحكام الهجرة، في المدارس، وفي المعاهد، وفي الجامعات، وفي حلقات العلم في المساجد، كل هذا طيِّبٌ، لكن أن يتَّخذ يومًا مولدًا، ما وُضع إلا لاحتفالٍ خاصٍّ؛ فهذا منكر.\nوقد نصَّ على ذلك أهلُ العلم، وبسط ذلك الإمامُ الشاطبي في كتابه \"الاعتصام\"، وكذلك أبو العباس ابن تيمية في كتابه \"اقتضاء الصراط المستقيم\"، وغيرهم من أهل العلم.\nوالذين تساهلوا في ذلك من العلماء ليس عندهم بصيرةٌ في هذا الشيء، وغلب عليهم التَّقليد لغيرهم، فلا يجوز هذا، ولا ينبغي، وليس لهم حُجَّة في قوله ﷺ لما سألوه عن يوم الاثنين قال: ذاك يومٌ وُلدتُ فيه، وأُنزل عليَّ فيه، وقال في الخميس والاثنين: إنهما يومان تُرفع فيهما الأعمال إلى الله، وتُعرض فيهما الأعمال على الله، فأُحبّ أن يُعرض عملي وأنا صائم، ولم يقل: احتفلوا به.\nإنما شُرع لنا صيامه، لا بأس أن تصوموا الاثنين، يوم فاضل، يوم وُلد فيه النبيُّ ﷺ، وأُنزل عليه الوحي فيه، وتُعرض فيه الأعمال على الله، لا، هذا طيب، لكن مَن قال لك: تحتفل به، تحط فيه اجتماع ووليمة، وأكل وشرب وقصائد؟! مَن قال هذا؟! إنما قال النبيُّ ﷺ فيه صيام يوم الاثنين، فصم جزاك الله خيرًا، صم يوم الاثنين لعللٍ ثلاثٍ: لأنه يوم وُلد فيه، ولأنه أُنزل عليه فيه، ولأنه يوم تُعرض فيه الأعمال على الله جلَّ وعلا، كيوم الخميس.\nأما قوله جلَّ وعلا: وَذَكِّرْهُمْ بِأَيَّامِ اللَّهِ [إبراهيم:5] كما يستدل بعضُهم بهذا: التَّذكير بأيام الله ما هو باتِّخاذ البدع، التذكير بأيامه بالنَّصائح، والتذكير بما جرى على نوحٍ وقومه، وما جرى على هود، وما جرى على ثمود، وما جرى على غيرهم، وما جرى على فرعون وإغراقه، وما جرى على غيرهم، تُذكِّر بأيام الله؛ تُحذِّر من عقوبات الله، في المسجد، في خطبة الجمعة، في الدروس، في أيام أخرى؛ لا بأس، مجتمعين في قهوةٍ، على عشاء، تُذكِّرهم، في العرس، تُذكِّرهم.","link":"https://binbaz.org.sa/fatwas/21353/ما-حكم-الاحتفال-بمولد-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم الأحتفال بمولد النبي صلى الله عليه وسلم؟.mp3","categories":["البدع والمحدثات"]},{"id":1309,"question":"يقول السائل: سماحة الشيخ، لقد كثر هجرُ بعض المسلمين لإخوانهم بحجّة أنَّهم ...، ما هي حدود البدعة التي تُوجب الهجر؟ وهل كون الرجل استدلَّ بحديثٍ فيه خلافٌ.......، لكن قد قال به بعضُ السلف، من مُوجبات هجره؟","title":"ما ضابط الهَجِر لأصحاب البدع والعصاة؟","answer":"الجواب:\nالبدع هي ما أحدث على خلاف الشرع، يُقال لها: بدعة؛ لقوله ﷺ: مَن أحدث في أمرنا هذا ما ليس منه فهو ردٌّ، مَن عمل عملًا ليس عليه أمرنا فهو ردٌّ، إيَّاكم ومحدثات الأمور، فالبدع هي المحدثات في الدِّين، مثل: إحداث الاحتفال بالموالد، ومثل: الاحتفال بما يُسمونه ليلة الإسراء والمعراج في آخر رجب، ومثل: الاحتفال بشيءٍ آخر لم يشرعه الله جلَّ وعلا، يُجعل عبادةً وقُربةً، هذا يُسمَّى: بدعة، ومثل: البناء على القبور، تُسمَّى: بدعة، البناء عليها واتِّخاذها قبابًا ومساجد تُسمَّى: بدعة.\nوالواجب النَّصيحة لصاحب البدعة، يُنصح ويُوجَّه إلى الخير، ويُعلَّم، فإذا أصرَّ على البدعة استحقَّ أن يُهجر حتى يتوب، إلا إذا كان الهجر يزيده شرًّا، فإنك لا تهجره، بل تتصل به اتِّصال النَّاهي والآمر والناصح، لا اتِّصال المحب الودود الشَّفيق، لا، تتصل به اتصال الناصح والنَّاهي، والمنكر والمخوّف له من الله عز وجل، لعله ينتهي.\nوإذا كان في البلد وليُّ أمرٍ رُفع الأمر إليه؛ حتى يُزيل البدعة، حتى يُزيلها بالقوة، ويمنع منها، إذا كان في بلادٍ إسلاميةٍ فيها مَن يأمر وينهى.  والنبي ﷺ هجر قومًا لأنَّ الهجر ينفعهم، كما هجر كعب بن مالك وصاحبيه لما تخلَّفوا عن غزوة تبوك خمسين ليلةً، ولم يهجر عبدالله بن أُبي وجماعة المنافقين؛ لأنَّ هجرهم يضرُّ، فلم يهجرهم، بل تألَّفهم على الإسلام، ودعاهم إلى الإسلام ولم يهجرهم.\nفعلى ولاة الأمور وعلى العلماء وطلبة العلم أن يتأسَّوا بالنبي ﷺ، فإذا كان الهجر ينفع العاصي والمبتدع هَجَره، وإذا كان لا ينفع، بل يزيده شرًّا؛ لم يهجره، بل لا يزال يتصل به ويدعوه إلى الله، ويجتهد في توجيهه إلى الخير، لعله يهتدي؛ حتى يسلم الناسُ من شرِّه.","link":"https://binbaz.org.sa/fatwas/21360/ما-ضابط-الهجر-لاصحاب-البدع-والعصاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1103ما هي حدود البدعة التي بسببها يجوز الهجر؟ ابن باز فتاوى.mp3","categories":["البدع والمحدثات"]},{"id":1429,"question":"القول بأن البدع تنقسم إلى قسمين: بدعة ضلالة وبدعة؟","title":"هل يصح تقسيم البدع إلى \"ضلالة\" وغيرها؟","answer":"الجواب:\nلا، كل البدع ضلالة، الانقسام غلط، الرسول ﷺ يقول: كل بدعةٍ ضلالة، ما فيها تقسيم.","link":"https://binbaz.org.sa/fatwas/21524/هل-يصح-تقسيم-البدع-الى-ضلالة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل البدع أقسام.mp3","categories":["البدع والمحدثات"]},{"id":1432,"question":"بالنسبة للبدع: بعض الناس يستدلون بكلام عمر  عندما جمع الصحابة في صلاة التراويح وقال: \"نعم البدعة\"!","title":"ما معنى قول عمر: \"نعمت البدعة\"؟","answer":"الجواب:\nهذا من جهة اللغة، بدعة من جهة اللغة، وإلا فهي سنة فعلها النبيُّ ﷺ وشرعها ودعا إليها، لكن الرسول ﷺ مات وما جمعهم على إمامٍ واحدٍ، فأحدث عمرُ هذا، فجمعهم وسماها بدعة من حيث اللغة –لغة العرب- لا من حيث الشرع.\nس: مَن يستدل بهذا حجته باطلة؟\nج: ثم لو سلَّمنا أن عمر قال ذلك، فعمر ما هو معصوم، عمر واحد من الصحابة، ليس حُجَّةً في قول الله ورسوله، لكن يُحمل كلام عمر على الشيء الحسن؛ حتى لا يُساء به الظن.","link":"https://binbaz.org.sa/fatwas/21527/ما-معنى-قول-عمر-نعمت-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى كلمة نعم البدعة.mp3","categories":["البدع والمحدثات"]},{"id":1649,"question":"ما ضابط البدعة؟","title":"ما ضابط البِدْعة في الدِّين؟","answer":"الجواب:\nكل عبادةٍ تُخترع على خلاف الشرع فهي بدعة، فالعبادات المخترعة التي لا أصل لها في الشرع يقال لها: بدعة، مثل: بدعة الاحتفال بالموالد، والبناء على القبور، وإسراجها، واتِّخاذ المساجد عليها، فهذه تُسَمَّى بِدَعًا.\nس: إدراج بعض الأمور مثل: السِّبْحَة؟\nج: لا، السبحة أمرها سهل، كان بعض الصحابة يُسبِّح بالحصى في عهد النبي ﷺ، ويُسبِّحون بالعقد، لكن بالأصابع أفضل.","link":"https://binbaz.org.sa/fatwas/21754/ما-ضابط-البدعة-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط البدعة في الدين.mp3","categories":["البدع والمحدثات"]},{"id":1747,"question":"هل ما يفعله غيرُ الحاج من الجلوس في المساجد عصر عرفة والدّعاء فيها من السُّنة؟","title":"حكم تخصيص يوم عرفة بشيءٍ في المساجد","answer":"الجواب:\nإذا جاء الإنسانُ إلى المسجد قبل صلاة المغرب وجلس ينتظر المغرب فلا بأس، أما أن يخصَّ عرفة بشيءٍ فلا، فكونه يتقدّم قبل الغروب ويجلس ينتظر الصلاة فهذا فيه فضلٌ كبيرٌ.\nس: للحاج وغير الحاج؟\nج: جميع الصَّلوات، نعم، التقدّم لها كلها مُستحب، أما تخصيص يوم عرفة بشيءٍ في المساجد فلا، فهو بدعة.","link":"https://binbaz.org.sa/fatwas/21854/حكم-تخصيص-يوم-عرفة-بشيء-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تخصيص يوم عرفة بشيءٍ في المساجد.mp3","categories":["البدع والمحدثات","الوقوف بعرفة"]},{"id":1792,"question":"مسألة التَّلفظ بالنية عند الصلاة: هل هناك أحدٌ كتب فيها مستقِلًّا مدعَّمًا بالأدلة والرد عليها؟ لأنها كثرت.","title":"حكم التَّلفظ بالنية عند الصلاة","answer":"الجواب:\nهي من جملة البدع، ما كان يتلفظ بالنية ﷺ ولا أصحابه، يقول: \"نويتُ أن أُصلي كذا\"، أو: \"نويتُ أن أطوف\"، ما لها أصلٌ، النية محلها القلب، إلا في الحج، يقول: \"لبيك عمرة\"، \"لبيك حجًّا\"، يُصرِّح كما صرَّح النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/21899/حكم-التلفظ-بالنية-عند-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة التَّلفظ بالنية عند الصلاة.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":1836,"question":"معنى البِدْعَة؟","title":"ما معنى البِدْعَة في الدين؟","answer":"الجواب:\nالبِدْعَة: الحَدَث في الدين، إحداث عبادةٍ ما شرعها الله، يقال لها: بِدعة، فكلّ عبادةٍ ما شرعها الله يُحدثها الناس تُسمَّى بِدعة، مثل: الطَّواف بالقبور، والبناء على القبور، والصلاة عند القبور، واتِّخاذ الاحتفالات بالموالد، و\"نويت أن أصلي\" هذه من البدع.","link":"https://binbaz.org.sa/fatwas/21945/ما-معنى-البدعة-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/البدعة ومعناها.mp3","categories":["البدع والمحدثات"]},{"id":2049,"question":"هل يجوز أن نقول: علي كَرَّم الله وجهه؟","title":"حكم قول: \"علي كَرَّم الله وجهه\"","answer":"الجواب:\nرضي الله عنه. هذه بدعة مِن بِدع الشيعة، يُقال علي رضي الله عنه، مثل ما يقال: الصديق رضي الله عنه، وعمر رضي الله عنه، وعثمان رضي الله عنه.","link":"https://binbaz.org.sa/fatwas/22167/حكم-قول-علي-كرم-الله-وجهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول علي كرم الله وجهه.mp3","categories":["البدع والمحدثات"]},{"id":2749,"question":"تنفير السلف من أهل البدع والتحذير منهم وعدم حضور مجالسهم وسماع كلامهم: للتنفير منهم أو الخوف من الوقوع فيما وقعوا فيه؟","title":"لماذا نفَّرَ السلف من أهل البدع وحذّروا منهم؟","answer":"الجواب: للتنفير، والخوف من الوقوع فيما وقعوا فيه:  تنفيرًا منهم؛ ليرجعوا ويتوبوا.  ولئلا يقع المُجالِس فيما وقعوا فيه، نسأل الله العافية.  س: دعوتهم...؟  الشيخ: طيب، هذا من باب الدعوة إلى الله، طيب جيد.","link":"https://binbaz.org.sa/fatwas/22897/لماذا-نفر-السلف-من-اهل-البدع-وحذروا-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا نفّر السلف من أهل البدع وحذروا منهم.mp3","categories":["البدع والمحدثات"]},{"id":2912,"question":"مَن يرد أكثر الأحاديث جملة منها بالعقل؟","title":"حكم ردّ الأحاديث النبوية بالعقل","answer":"الجواب: هذا لا يقوله إلا أصحاب الكلام، هذا منكر، نعوذ بالله. بل الواجب أخذ السنة من طرقها الشرعية، من طريق أئمة الحديث والنظر في الأسانيد.  أما العقول وجعلها هي الحاكمة؛ هذا عمل باطل، نعوذ بالله، هذا عمل الجَهْمية وأشباههم.","link":"https://binbaz.org.sa/fatwas/23068/حكم-رد-الاحاديث-النبوية-بالعقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ردّ أكثر الأحاديث بالعقل.mp3","categories":["البدع والمحدثات"]},{"id":3274,"question":"بعض الناس مِن المعاصرين تُوفوا من قريب ولهم بِدَع عظيمة والناس تعظّمهم ويوزّعون كتبهم؟","title":"حكم التحذير مِنْ بِدَع شخص تُوفِّي","answer":"الجواب: يُحَذّر منهم أنهم أهل بِدَع، كما حذر الله من قوم هود وقوم صالح وقوم نوح وقوم شعيب وقوم لوط؛ لخبثهم.","link":"https://binbaz.org.sa/fatwas/23438/حكم-التحذير-من-بدع-شخص-توفي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التحذير من بدع من توفّي.mp3","categories":["البدع والمحدثات"]},{"id":3804,"question":"من يعملون الحفلات في رجب وفي شعبان يكونون متشبهين بأهل الجاهلية؟","title":"هل الاحتفال في رجب من التشبُّه بالجاهلية؟","answer":"الجواب: لا، إذا كان عنده أسباب ما هو داخل في هذا، هم يتشبهون بهم إذا فعلوا كفعلهم.\nس: يذهب بعضهم إلى بعض المقابر؟\nالشيخ: هذا منكر في أي وقت، يذهب عند القبور هذا منكر في كل وقت، ما هو في رجب بس.\nس: نفس الاحتفال في خمسة عشر شعبان، وسبعة وعشرين رجب؟\nالشيخ: هذا بدعة، ما فيه ذبح.\nس: ما زال بعض الناس يعتقدون هذا؟\nالشيخ: الأصل أن يُنهَوا عن ذلك.\nس: هو ما يعتبر أنها جاهلية بس يعتبر أنها عادية؟\nالشيخ: لا يتقيد في رجب، يذبح في أي وقت كان، إذا كان قصده التقرب والصدقة، لا يتقيد برجب.\nس: يعني يوضح له أنه مكروه أو محرم؟\nالشيخ: ظاهره أنه..... أقل أحواله الكراهة لكن... لا فرع ولا عتيرة يُبيّن أن هذا من عمل الجاهلية، ثم نسخه الله في الإسلام.","link":"https://binbaz.org.sa/fatwas/24005/هل-الاحتفال-في-رجب-من-التشبه-بالجاهلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يحتفل في رجب يكونون متشبهين بأهل الجاهلية.mp3","categories":["البدع والمحدثات"]},{"id":4511,"question":"في (بعض) البلاد الإسلامية يقرأ المُؤذن آيات من القرآن بدون تلحين؟","title":"حكم قراءة المُؤذن آيات من القرآن قبل الأذان","answer":"الجواب: هذا بدعة، السُّنة ألا يكون قبله شيء ولا بعده شيء، أذان فقط مجرد، لا يسبق بشيءٍ، ولا يلحق به شيء، حتى الصلاة على النبي ﷺ لا يرفع بها الصوت مع الأذان، بل إذا قال: \"لا إله إلا الله\" قفل المكبِّر وانتهى الأذان، ثم يُصلي على النبي ﷺ بينه وبين نفسه، فيُسمعه لمن حوله؛ حتى لا يكون زائدًا في الأذان.","link":"https://binbaz.org.sa/fatwas/24791/حكم-قراءة-الموذن-ايات-من-القران-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع قراءة المُؤذن آيات من القرآن قبل الأذان.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":4751,"question":"البدع التي تكون في الجنِّ يتلقونها عن الإنس، أو عندهم مُبتدعة تلقَّى بعضُهم عن بعضٍ؟","title":"هل لدى الجن المسلمين بدعٌ؟ ومن أين تلقوها؟","answer":"الذي يظهر -والله أعلم- أنَّ منهم مَن يتلقاها عن الإنس، ومنهم مَن يتلقاها عن الجنِّ؛ لأنهم لهم اتِّصالًا بالإنس، ولهم معرفة بأحوال الإنس، يعلمون بالمجالس، ويقرؤون ويكتبون، فلا مانعَ أن يأخذوا عن الإنس بعض الخير والشرِّ، وعن بعضهم مثل الإنس.","link":"https://binbaz.org.sa/fatwas/25094/هل-لدى-الجن-المسلمين-بدع-ومن-اين-تلقوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل عند الجن المسلمين بدعٌ، ومن أين تلقوها.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":4985,"question":"بعض الناس يدعو لطعام ويُكلّفون قراءة الإخلاص للميت؟","title":"حكم الدعوة لطعام مع قراءة الإخلاص للميّت","answer":"الجواب: ما له أصل، ما له أصل، لا صنع الطعام ولا القراءة، ما له دليل، أما إذا صنع لهم جيرانهم، أهدوا لهم جيرانهم؛ طيب، مثل ما أمر النبي ﷺ أهله أن يُهدوا لآل جعفر، لما مات جعفر؛ لأنه قد أتاهم ما يشغلهم، جيران الميت إذا أهدوا لأهل الميت عشاء أو غداء؛ طيب، أما أهل الميت يصنعون للناس ويضيفون للناس بسبب الموت، لا، هذا من عمل الجاهلية.","link":"https://binbaz.org.sa/fatwas/28497/حكم-الدعوة-لطعام-مع-قراءة-الاخلاص-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعوة لطعام مع قراءة الإخلاص للميت.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":5010,"question":"إن كان بعض الناس يذهب إلى القبر وهو محفور، ثم ينسدحون فيه، هل لهذا أصل؟","title":"حكم الاستلقاء في القبر لترقيق القلوب","answer":"الجواب: لا، ما له أصل، الانسداح في القبور ما لها أصل.\nس: يُرقق القلوب؟\nج: لا، هذا ما له أصل.","link":"https://binbaz.org.sa/fatwas/28812/حكم-الاستلقاء-في-القبر-لترقيق-القلوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاستلقاء في القبر لترقيق القلوب.mp3","categories":["البدع والمحدثات"]},{"id":5249,"question":"ما حكم مَن يختم قراءته بالفاتحة؟","title":"ما حكم مَن يختم قراءته بالفاتحة؟","answer":"الجواب: لا أصلَ لهذا فيما نعلم، بل هو بدعة، لا أصل لهذا، ما كان النبيُّ يفعل هذا ولا أصحابه ، وكل خيرٍ في الاقتداء به عليه الصلاة والسلام واتِّباع سلف هذه الأمة، قال عليه الصلاة والسلام: مَن عمل عملًا ليس عليه أمرُنا فهو ردٌّ.","link":"https://binbaz.org.sa/fatwas/30664/ما-حكم-من-يختم-قراءته-بالفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 736.mp3","categories":["البدع والمحدثات"]},{"id":5257,"question":"كلمة \"الصحابة ليسوا معصومين من البدعة\"، ما وزن هذه الكلمة، وهل وقع منهم بدع؟","title":"ما حكم قول \"الصحابة ليسوا معصومين من البدعة\"؟","answer":"الجواب: يعني الفرد الواحد فيهم ليس بمعصوم، أما هم في الجملة معصومون. س: يقع منهم البدع؟ ج: الفرد الواحد غير معصوم، ما نعرف أنه وقع منهم بدعة، لكن الفرد ليس معصومًا، كل واحد ليس بمعصوم.[1]","link":"https://binbaz.org.sa/fatwas/30864/ما-حكم-قول-الصحابة-ليسوا-معصومين-من-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 005.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":5271,"question":"نسمع بعد نهاية التلاوة في الإذاعة وغيرها يقول: صدق الله العظيم، ما رأي سماحتكم؟","title":"ما حكم قول «صدق الله العظيم» بعد التلاوة؟","answer":"الجواب: هذا القول ليس بمشروع، هذا اعتاده الناس وهو غير مشروع، ما كان يفعله النبي ﷺ ولا الصحابة؛ فتركه أوْلى. س: ما يدخل في البدع؟ ج: محل نظر؛ لأن بعض أهل العلم يحتج بقوله: قُلْ صَدَقَ اللَّهُ فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا [آل عمران: 95] ولكن ليس هذا بحجة؛ لأن الرسول ﷺ ما حُفظ عنه أنه كان إذا تلا أو الصحابة يأتون بهذا، فيُخشى أن يكون بدعة.[1]","link":"https://binbaz.org.sa/fatwas/30888/ما-حكم-قول-صدق-الله-العظيم-بعد-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 016.mp3","categories":["البدع والمحدثات","القرآن وعلومه"]},{"id":5352,"question":"هناك مَن يقول أنَّ من الرافضة مَن بدعته مُكفرة، ومَن بدعته مُفسقة، هذا تقسيمٌ صحيحٌ؟","title":"هل بدعة الرافضة مُكفِّرة أم مُفسِّقة؟","answer":"الجواب: الرافضة أقسام، ذكر الشَّهرستاني أنهم اثنان وعشرون قسمًا، الرافضة أقسام كثيرة، الشيعة، لكن الرافضة الإمامية يغلون في عليٍّ وفي أهل البيت، ويقولون: يعلم الغيب، ويعبدونهم، هؤلاء كفَّار. لكن بعض الشيعة دون ذلك: الذين يُفضلون عليًّا على عثمان، أو على الصديق وعمر، هؤلاء مُبتدعة، لا يكفرون بهذا، كذلك منهم الزيدية، من أقسام الشيعة وفرق الشيعة: يُفضلون عليًّا على عثمان. س: ومَن يُكفِّرهم يُكفِّرهم بأعيانهم أو بالنوع؟ ج: مَن عُرف بعينه أنه يدَّعي علم الغيب، أو يغلو في آل البيت؛ هو كافر بعينه، من جنس مَن عبد عليًّا أو غيره يكون كافرًا، أو زعم أنه يعلم الغيب يكون كافرًا.[1]","link":"https://binbaz.org.sa/fatwas/31052/هل-بدعة-الرافضة-مكفرة-ام-مفسقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 008.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":5371,"question":"لا يلزم من الطواف أن يكون الطائفُ مُشركًا؟","title":"ما حكم مَن يطوف بالقبور؟","answer":"الجواب: إذا كان يقصد التَّقرب إلى الله يكون بدعةً. لكن غالب هؤلاء الذين يطوفون يتقرّبون إلى القبور، هذا الغالب عليهم. لكن لو طاف يقول: إني أتقرب إلى الله، يكون هذا بدعةً ووسيلةً إلى الشرك بصاحب القبر.[1]","link":"https://binbaz.org.sa/fatwas/31103/ما-حكم-من-يطوف-بالقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya001.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5372,"question":"الطواف بغير الكعبة قد يكون شركًا وقد يكون بدعةً؟","title":"هل الطواف بغير الكعبة شرك أو بدعة؟","answer":"الجواب: قد يكون شركًا، وقد يكون بدعةً، نعم، على حسب حال صاحبه؛ إن كان يظن أنَّ الطواف عبادة بهذا الشيء لله سبحانه يكون بدعةً ووسيلةً إلى الشرك، أما إذا كان يطوف يتقرب إليه فهو مثل الصلاة له والسجود له. س: عندنا يطوفون ثم يُصلون تجاه القبر، هذا شرك أم بدعة؟ ج: ماذا؟ س: يطوفون ثم يُصلون ركعتين تجاه القبر؟ ج: يُعلَّمون أنَّ هذا شرك أكبر، الصلاة إلى القبور إذا قصد التَّقرب لصاحب القبر صار شركًا أكبر، وأما إن قصد أنَّ الصلاة عند القبر مُستحبة فهذه بدعة، والطواف بدعة. س: الصلاة تجاهه ولو ضدّ القبلة؟ ج: هذا إذا صلَّى إلى القبر يرى أنه قبلة يُبَيَّن له أنَّ هذا باطل، أما إن كان يتقرب إليها فشرك أكبر. س: يقول: إن الصلاة هنا فيها تقرب إلى الله، يتعبد الله؟ ج: يُعلَّم أنَّ الصلاة عند القبور بدعة، وإذا أراد بها صاحب القبر صار شركًا أكبر، أو الطواف إذا أراد به التَّقرب إلى صاحب القبر صار شركًا أكبر، نسأل الله العافية، أما إذا صلَّى عندها يظنها قربةً، وأن الصلاة عند القبور أو القراءة عندها طيبة فهذه بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31106/هل-الطواف-بغير-الكعبة-شرك-او-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya002.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5373,"question":"الصلاة تجاهه (القبر) ولو ضدّ القِّبلة؟","title":"ما حكم الصلاة عند القبر لغيرالقِبلة؟","answer":"الجواب: هذا إذا صلَّى إلى القبر يرى أنه قبلة: يُبَيَّن له أنَّ هذا باطل، أما إن كان يتقرب إليها فشرك أكبر. س: يقول: إن الصلاة هنا فيها تقرُّب إلى الله، يتعبّد الله؟ ج: يُعلَّم أنَّ الصلاة عند القبور بدعة، وإذا أراد بها صاحب القبر صار شركًا أكبر، أو الطواف إذا أراد به التَّقرب إلى صاحب القبر صار شركًا أكبر، نسأل الله العافية. أما إذا صلَّى عندها يظنها قربةً، وأن الصلاة عند القبور أو القراءة عندها طيبة؛ فهذه بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31107/ما-حكم-الصلاة-عند-القبر-لغيرالقبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya003.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5484,"question":"السؤال الأول: يقول السائل: سماحة الشيخ، دخلت جماعةٌ المسجد، وهي مُسافرة، فوجدت جماعةً أخرى تُصلي المغرب والعشاء جمعًا وقصرًا، ولم تُدرك معهم المغرب، وإنما أدركت معهم العشاء، سؤال: هل يجوز للجماعة الداخلة أن تُصلي معهم ركعتي العشاء، وتنوي بها المغرب، وتقضي بعد ذلك ركعةً ثالثةً، ثم يُصلون العشاء جماعةً وحدهم؟","title":"ما حكم اختلاف النية في صلاة الجماعة؟","answer":"الجواب: الأقرب أن يُصلي معهم العشاء بنية المغرب، وإذا سلموا قاموا وأتوا بواحدةٍ كمال المغرب، ثم صلوا العشاء، وإن صلوا وحدهم كفى، لكن الأفضل حصول الجماعة ..... يُصلي معهم الجماعة، وإذا سلموا -سلَّم الأولون العشاء المقصورة- قام الآخرون وأتوا بركعةٍ؛ لأنهم دخلوا معهم بنية المغرب، ثم يُصلون العشاء بعد ذلك. س: يعني: اختلاف النية ما يضرّ؟ ج: ما يضرّ، لا، ما يضرّ، الصحيح ما يضرّ.[1]","link":"https://binbaz.org.sa/fatwas/31389/ما-حكم-اختلاف-النية-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sharh_alosol 001.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":5512,"question":"إذا نسي شيئًا هل يقرأ سورة الفاتحة؟","title":"ما حكم قراءة سورة الفاتحة عند نسيان أمر ما؟","answer":"الجواب: بدعة، إذا أشكل عليه يذكر الله: لا إله إلا الله، أو سبحان الله، مثل ما قال الله تعالى: وَاذْكُرْ رَبَّكَ إِذَا نَسِيتَ [الكهف:24]، إذا كان قصده ناسيًا يذكر الله، أما إذا كان قصده البحث العلمي يبحث: قال الله، قال الرسول، أيش عندك يا فلان في هذه المسألة؟ أيش الدليل على كذا؟ أيش الدليل على كذا؟[1]","link":"https://binbaz.org.sa/fatwas/31444/ما-حكم-قراءة-سورة-الفاتحة-عند-نسيان-امر-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 027.mp3","categories":["البدع والمحدثات"]},{"id":5537,"question":"مَن تمسَّح بشبابيك أو أبواب الحرم واعتقد أنَّ هذا قُربى لله؟","title":"ما حكم التمسُّك بنوافذ أو أبواب الحرم؟","answer":"الجواب: هذه بدعة، فإذا اعتقدها وطلب منها صار شركًا، أما إذا كان يظن أنها قُربى وطاعة فهذه بدعة ويُعلَّم. س: يُنكر عليه؟ ج: يُنكر عليه ويُعلَّم أنها بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31470/ما-حكم-التمسك-بنوافذ-او-ابواب-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 052.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":5541,"question":"بعض الناس المقلّدين إذا صلَّى وراء مَن لا يقنت يتأخَّر ويقنت في نفسه ويترك الإمامَ يسجد؟","title":"ما حكم مَن تأخرعن الإمام ليقنت لنفسه؟","answer":"الجواب: لا، ما ينبغي هذا: إنما جُعل الإمامُ ليُؤتمَّ به، فلا تختلفوا عليه، إذا صلَّى خلف مَن لا يقنت يفعل مثله، يسجد معه، وليترك القنوت؛ لأنَّ القنوت لا أصلَ له في الدوام، إنما هو في النوازل، النبي ما كان يستمرّ عليه. س: وإذا قنت الإمامُ؟ ج: إذا قنت معه فلا بأس؛ لأنه له شبهة مذهب الشافعي وجماعة.[1]","link":"https://binbaz.org.sa/fatwas/31477/ما-حكم-من-تاخرعن-الامام-ليقنت-لنفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 004.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":5584,"question":"تُشترط نية الجمع قبلها؟","title":"هل تُشترط النية للجمع بين الصلاتين؟","answer":"الجواب: نعم عند التأخير، إذا أراد التأخير بالنية.\nس: في أي وقتٍ أراد أن يُصلي؟\nج: سواء قدَّم أو أخَّر أو بينهما.[1]","link":"https://binbaz.org.sa/fatwas/31542/هل-تشترط-النية-للجمع-بين-الصلاتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 024.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":5645,"question":"في السؤال الأول يعني: في بعض الناس يعملون احتفالًا في ليلة سبعٍ وعشرين رجب، ويُسمونها: فضل المعراج؟","title":"ما حكم الاحتفال بفضل المعراج","answer":"الجواب: هذا بدعة، كتبنا فيه، هذا مكتوبٌ فيه. س: الثاني ما يُسمونه بمولد النبي ﷺ ويعملون حفلات؟ ج: كل هذه الاحتفالات: الاحتفال بالمولد، وليلة المعراج، كلها بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31657/ما-حكم-الاحتفال-بفضل-المعراج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 006.mp3","categories":["البدع والمحدثات"]},{"id":5658,"question":"ما حكم قراءة سورة \"يس\" على قبر الميت؟","title":"ما حكم قراءة سورة {يس} على قبر الميت؟","answer":"الجواب: لا يُقرأ على القبور شيء: لا \"يس\"، ولا غيرها، إنما تُقرأ \"يس\" عند المحتضر قبل أن يموت، تُستحبّ قراءتها عند المحتضر قبل أن يموت؛ لحديثٍ ورد في ذلك، أما بعد الدَّفن فالقبور لا يقرأ عندها لا \"يس\" ولا غيرها، لا يقرأ عندها، ولا يُصلَّى عندها، كل هذا من البدع.[1]","link":"https://binbaz.org.sa/fatwas/31695/ما-حكم-قراءة-سورة-يس-على-قبر-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 004.mp3","categories":["البدع والمحدثات"]},{"id":5719,"question":"..........؟","title":"حكم قراءة القرآن على الميت بعد الدفن","answer":"الجواب: ما نعرف هذا، يسأل عن تلاوة القرآن للموتى، ما له أصل هذا، فالذي يتلو القرآن على الميت بعد ما يموت، أو في القبر، أو على الجنائز في القبر، كل هذا لا أصل له. يعني قراءة القرآن على الموتى في المقابر، أو عند دفنه، أو في الليلة التي مات فيها جلس الناس يقرؤون عليه هذا كله لا أصل له، ولا نعلم له أصلًا في الشريعة.","link":"https://binbaz.org.sa/fatwas/1023/حكم-قراءة-القران-على-الميت-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_45.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":5778,"question":"ذكر بعض المحاضرين أن الرسول ﷺ قال بيتًا من الشعر، فما صحة هذا القول؟","title":"ما صحة حفظ النبي صلى الله عليه وسلم للشعر؟","answer":"الجواب:\n\nهذا البيت صحيح، بس قول الشيخ يغني به، لو أتى بداله قال بيتًا من الشعر وهو قوله:\n\n\n\t\n\t\t\n\t\t\tهل أنتِ إلا إصبع دميت\n\t\t\tوفي سبيل الله ما لقيت\n\t\t\n\t\n\n\nهذا قاله النبي ﷺ ورواه مسلم في الصحيح، رواه مسلم في صحيحه لما حصلت نكبة في إصبعه، ودميت، قال هذا الشعر، عليه الصلاة والسلام.\n\nوقال بعضهم: ولم يحفظ له بيت من الشعر سوى هذا البيت؛ لأن الله قال: وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغِي لَهُ [يس:69] وقال بعض المحدثين: إنه لا يحفظ له بيت من الشعر مستقيم إلا هذا البيت الواحد:\n\n\n\t\n\t\t\n\t\t\tهل أنتِ إلا إصبع دميت ِ\n\t\t\tوفي سبيل الله ما لقيت\n\t\t\n\t\n\nيعني هذا قاله ليظهر صبره، واحتسابه -عليه الصلاة والسلام- وأن هذا الشيء في سبيل الله، فلا بأس عليك أيها الأصبع، ولا يضرك ذلك، وهذا في سبيل الله.","link":"https://binbaz.org.sa/fatwas/1104/ما-صحة-حفظ-النبي-صلى-الله-عليه-وسلم-للشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_110.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":5800,"question":"كيف يجمع بين ما ورد أن عائشة قد زارت القبور، وبين الأحاديث التي تحرم ذلك؟","title":"الجمع بين زيارة عائشة القبور وبين النهي عن زيارتها","answer":"الجواب: عائشة ما كانت تزور القبور، إنما زارت قبر أخيها؛ لأنه مات وهو غائب عنها قرب مكة، فقالت: \"لو شهدتك ما زرتك\" يعني: لو شهدت موتك ما زرتك، فهذا يدل على أن زيارة القبور للنساء ما هي بمشروعة؛ ولهذا قالت: لو شهدتك ما زرتك. فلو كانت الزيارة مشروعة للنساء كانت زارته مطلقًا، ولو شهدته، كما ينبغي أن يزور النساء البقيع، والشهداء؛ فلم يكن النساء في عهد النبي ﷺ ولا في عهد الخلفاء يزرن البقيع، ولا قبور الشهداء، فعلم أنه استقر عندهم أن زيارة النساء للقبور غير مشروعة. والحكمة -والله أعلم- في ذلك أن النساء مثل ما قال مشايخ الندوة قليلات الصبر، ضعيفات البصيرة، فلو زرن القبور لربما وقع منهن من الجزع، والنياحة، والتكشف، والتبرج ما لا يحمد عقباه، وهن فتنة، فمن -رحمة الله- أن منعهن من اتباع الجنائز، ومن زيارة القبور؛ لأنهن لو اتبعن الجنائز لربما حصل فتنة بين الماشي في الجنائز؛ لأنه قل امرأة أن تعتني بالستر، والحجاب، والتحفظ، وهكذا عند زيارة القبور، فيقع فتن في اختلاطهن بالرجال حين الزيارة، وحين تشييع الجنازة. فالحكمة -والله أعلم- مترتبة من كونهن فتنة، قليلات الصبر، قليلات النظر في العواقب، وربما يحن، وينحن على الميت؛ فيضره ذلك، وربما أبدين شيئًا من الفتنة من شعورهن، أو أجسادهن، فيفتن الرجال الأحياء، ويؤذين الأموات بنياحتهن، وقلة صبرهن، وربك حكيم عليم، جل وعلا.","link":"https://binbaz.org.sa/fatwas/1129/الجمع-بين-زيارة-عاىشة-القبور-وبين-النهي-عن-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_135.mp3","categories":["زيارة القبور","البدع والمحدثات"]},{"id":5813,"question":"في بعض البلدان إذا مات الميت، ثم دفن يجتمعون في بيت الميت ثلاث ليال، يصلون ويدعون له، فما حكم هذا؟","title":"حكم اجتماع أهل الميت للصلاة والدعاء له","answer":"الجواب: سبق لكم في كلام الشيخين: أن الاجتماع في بيت الميت للأكل، والشرب، ولقراءة القرآن أن هذا بدعة، وهكذا اجتماعهم يصلون له، ويدعون له، كله بدعة، لا وجه لهذا؛ إنما يؤتى لأهل الميت للتعزية، والدعاء لهم، والترحم على ميتهم، وتسليتهم، وتصبيرهم. أما أنهم يؤتون لإقامة مآتهم، وإقامة دعوات خاصة، وصلوات خاصة، وقراءة، فهذا لا أصل له، ولو كان خيرًا لسبقنا إليه سلفنا الصالح -رضي الله عنهم وأرضاهم- فالرسول ما فعله، وقد دفن جعفر بن أبي طالب، وعبدالله بن رواحة، وزيد بن حارثة في غزوة مؤتة، وجاءه الخبر -عليه الصلاة والسلام- جاءه الوحي بذلك، فنعاهم للصحابة، وأخبرهم بموتهم، وترضى عنهم، ودعا لهم، ولم يتخذ من هذا شيئًا -عليه الصلاة والسلام- لا جمع الناس، ولا اتخذ مأدبة، ولا جعل مأتم الأيتام أيام كل هذا ما فعله ﷺ وهؤلاء من خيرة الصحابة، ومن أفضل الصحابة.  مات الصديق، وما جعلوا مأدبة، وهو أفضل الصحابة، وقتل عمر ما جعلوا مأتمًا، ولا جمعوا الناس ينعون عليه، أو يقرؤون له القرآن، وقتل عثمان بعد ذلك، وقتل علي بعد ذلك، ولا جمع الناس لأيام معدودة بعد الوفاة بالدعاء لهم، والترحم عليهم لا، مثل ما سمعتم في الندوة.  ولكن يستحب لأقارب الميت، أو جيرانه أن يصنعوا طعامًا لأهل الميت، يبعثوا به إليهم، مثل ما فعل النبي ﷺ لما نعى جعفر، قال لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم فأهل الميت مشغولون بالمصيبة، فإذا صنع طعام، وأرسل إليهم، وكفوا المؤنة، هذا هو المشروع. أما أن يحملوا بلاء على بلائهم، ويكلفوا أن يصنعوا للناس طعامًا، فهذا خلاف للسنة؛ بل هو بدعة، قال جرير بن عبدالله البجلي : كنا نعد الاجتماع إلى أهل الميت، وصنع الطعام بعد الدفن من النياحة، فالصحابة يعدونه من النياحة المحرمة، والنياحة رفع الصوت، وهذا محرم، فلا يجوز، ويعد هذا من النياحة، والميت يعذب في قبره بما يناح عليهـ كما قاله النبي -عليه الصلاة والسلام- فيجب الحذر من ذلك، أما البكاء بدمع العين؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1136/حكم-اجتماع-اهل-الميت-للصلاة-والدعاء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_142.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":5845,"question":"ظهر على شاشة التلفاز أحد العلماء، وسئل عن حكم الاحتفال بعيد الزواج؛ فأجاب بأنه لا بأس بذلك ما دام أن هذا الاحتفال لا يأخذ صفة دينية؟","title":"حكم الاحتفال بعيد الزواج ونحوه","answer":"الجواب: الاحتفالات بالأعياد كعيد الأم، وعيد الزواج، أو كذا، أو كذا، هذه منكرات، وحوادث، وبدع لا أساس لها. أما الاحتفال بالزواج نفسه، كأن يقيم وليمة الزواج؛ لأنه بنى بزوجته، أو عقد بها؛ فلا بأس، أما شيء يعتاد في ليلة من الزمان، كلما دار الحول على الزواج؛ يقيم عيدًا كل سنة، هذا منكر، من البدع التي أحدثها الناس، لا وجه لها، ولا أساس لها، أو يقيم عيدًا لولده إذا تمت السنة، هذا عيد فلان، وهذا عيد فلان، هذه ورثوها عن النصارى، واليهود، وأشباههم، ومشابهة لأعداء الله، فلا يجوز هذا، بل هو منكر. ومن أفتى بجوازه؛ فقد غلط، سواء سمي دينًا، أو ما يسمى دينًا؛ فإن الشيء قد يسمى عبادة، وقد لا يسمى عبادة، لكن يمنع؛ لأن فيه تشبهًا بأعداء الله، والنبي -عليه الصلاة والسلام- يقول: من تشبه بقوم فهو منهم فلا يجوز لنا أن نتشبه بأعياد الكفار.","link":"https://binbaz.org.sa/fatwas/1201/حكم-الاحتفال-بعيد-الزواج-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_197.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":5850,"question":"بعض الناس في منطقة الجنوب إذا دفن الميت، أوقدوا نارًا لمدة أسبوع، وذلك خوفًا من سبع يأتي، ويأخذ قلب الجنازة، فكيف تنصحون هؤلاء؟","title":"حكم إيقاد النار بعد دفن الميت خوفاً من السباع","answer":"الجواب: هذا لا  أصل له، هذا يسأل يقول: بعض الناس في الجنوب يوقد نارًا عند القبر بعد الدفن أسبوعًا، يقولون: نخشى أن يأتي سبع يحفر القبر، ويأخذ من الميت شيئًا، وهذا ما سمعنا به إلا في هذا السؤال، ما سمعنا به عن الجنوب إلا من هذا السائل، وعلى كل حال إذا كان وقع هذا؛ فلا يجوز هذا. الواجب عليهم التعميق، يعمقون القبور، ويضعون عليها اللبن، أو الحجارة حتى توارى عن السباع وغيرها، النبي ﷺ قال للحفار: احفروا، وأعمقوا، الحافر يحفر، ويعمق في القبر؛ حتى يكون بعيدًا عن تناول السباع، والكلاب، ونحو ذلك، وإذا كان في أرض صلبة؛ طوى على القبر بالحجارة، وضبطه بالحجارة، ولا حاجة إلى نار، لا حاجة إلى ذلك.","link":"https://binbaz.org.sa/fatwas/1202/حكم-ايقاد-النار-بعد-دفن-الميت-خوفا-من-السباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_198.mp3","categories":["البدع والمحدثات","مسائل متفرقة في الجنائز"]},{"id":5859,"question":"ظهر على شاشة التلفاز أحد العلماء، وسئل عن حكم الاحتفال بعيد الزواج؛ فأجاب بأنه لا بأس بذلك ما دام أن هذا الاحتفال لا يأخذ صفة دينية؟","title":"حكم الاحتفال بعيد الزواج ونحوه","answer":"الجواب: الاحتفالات بالأعياد كعيد الأم، وعيد الزواج، أو كذا، أو كذا، هذه منكرات، وحوادث، وبدع لا أساس لها. أما الاحتفال بالزواج نفسه، كأن يقيم وليمة الزواج؛ لأنه بنى بزوجته، أو عقد بها؛ فلا بأس، أما شيء يعتاد في ليلة من الزمان، كلما دار الحول على الزواج؛ يقيم عيدًا كل سنة، هذا منكر، من البدع التي أحدثها الناس، لا وجه لها، ولا أساس لها، أو يقيم عيدًا لولده إذا تمت السنة، هذا عيد فلان، وهذا عيد فلان، هذه ورثوها عن النصارى، واليهود، وأشباههم، ومشابهة لأعداء الله، فلا يجوز هذا، بل هو منكر. ومن أفتى بجوازه؛ فقد غلط، سواء سمي دينًا، أو ما يسمى دينًا؛ فإن الشيء قد يسمى عبادة، وقد لا يسمى عبادة، لكن يمنع؛ لأن فيه تشبهًا بأعداء الله، والنبي -عليه الصلاة والسلام- يقول: من تشبه بقوم فهو منهم فلا يجوز لنا أن نتشبه بأعياد الكفار.","link":"https://binbaz.org.sa/fatwas/1201/حكم-الاحتفال-بعيد-الزواج-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_197.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":5861,"question":"كثير من الناس يتلفظون بأقوال مثل قولهم: الله الله الله، وهذا ليس بكلام توحيد كما تعلمون، لكن ماذا تقولون في قوله سبحانه: قُلِ اللَّهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ [الأنعام: 91] ؟","title":"حكم ترديد الله الله، أو هو هو عند الأذكار","answer":"الجواب:  هذا من الصوفية، يقولون: الله الله الله، أو هو هو هو، هذا كلام باطل لا يجوز، هذا ليس بشرع، ولا ذكر، الله الله هذا من طرق الصوفية الذين أوجدوا عبادات، وأحدثوا عبادات ما لها أساس في الشرع.  فهؤلاء موجودون في بلاد كثيرة، في الشام، وفي مصر، وفي إفريقيا، وفي كل مكان ولهم أذكار خاصة أحدثوها، وطرق أحدثوها باطلة، لا ينبغي تقليدهم فيها، بل ينبغي أن ينصحوا، ويحذروا منها، فهم إن اجتمعوا ذكرهم هذا الله الله الله الله، أو هو هو هو، هذا منكر.   أما قوله -جل وعلا-: قُلِ اللَّهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ [الأنعام:91] فهذا تابع لما قبله، يعني الله الذي أنزل، خبره محذوف، مبتدأ خبره محذوف، مثل لو قلت: من الذي خلقك؟ تقول: الله، أي الله الذي خلقك، هذا كلام معروف، أو قلت: من يحيي الموتى؟ فتقول: الله، من فعل كذا وكذا؟ من أنزل التوراة، ومن أنزل الإنجيل؟ الله، هذا كلام تام. والقاعدة: أن الخبر يحذف إذا وجد ما يدل عليه، فإذا قال لك إنسان: من الذي قام؟ تقول: زيد يعني قام زيد، حذف الفعل؛ لأن هناك ما يدل عليه.","link":"https://binbaz.org.sa/fatwas/1184/حكم-ترديد-الله-الله-او-هو-هو-عند-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_180.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":5863,"question":"بعض الناس في منطقة الجنوب إذا دفن الميت، أوقدوا نارًا لمدة أسبوع، وذلك خوفًا من سبع يأتي، ويأخذ قلب الجنازة، فكيف تنصحون هؤلاء؟","title":"حكم إيقاد النار بعد دفن الميت خوفاً من السباع","answer":"الجواب: هذا لا  أصل له، هذا يسأل يقول: بعض الناس في الجنوب يوقد نارًا عند القبر بعد الدفن أسبوعًا، يقولون: نخشى أن يأتي سبع يحفر القبر، ويأخذ من الميت شيئًا، وهذا ما سمعنا به إلا في هذا السؤال، ما سمعنا به عن الجنوب إلا من هذا السائل، وعلى كل حال إذا كان وقع هذا؛ فلا يجوز هذا. الواجب عليهم التعميق، يعمقون القبور، ويضعون عليها اللبن، أو الحجارة حتى توارى عن السباع وغيرها، النبي ﷺ قال للحفار: احفروا، وأعمقوا، الحافر يحفر، ويعمق في القبر؛ حتى يكون بعيدًا عن تناول السباع، والكلاب، ونحو ذلك، وإذا كان في أرض صلبة؛ طوى على القبر بالحجارة، وضبطه بالحجارة، ولا حاجة إلى نار، لا حاجة إلى ذلك.","link":"https://binbaz.org.sa/fatwas/1202/حكم-ايقاد-النار-بعد-دفن-الميت-خوفا-من-السباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_198.mp3","categories":["البدع والمحدثات","مسائل متفرقة في الجنائز"]},{"id":6011,"question":"ياشيخ، رفع اليدين بعد الفريضة، والدعاء ياشيخ بعد الفريضة؟","title":"حكم رفع اليدين بالدعاء بعد الصلاة","answer":"الجواب: رفع اليدين بعد الفريضة للدعاء بدعة، من يرفع يديه بعد الفريضة، ويدعو الإمام، أو المأمومين، ما له أصل، هذا بدعة، أما النافلة إذا فعله بعض الأحيان . السؤال: لا بعد الفريضة؟ الجواب: هذا ما يجوز؛ لأنه بدعة بعد الفريضة.","link":"https://binbaz.org.sa/fatwas/1389/حكم-رفع-اليدين-بالدعاء-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_345.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":6074,"question":"يقولون في البدع حسنة، وسيئة، يستدلون بقول عمر  عند التراويح: \"نعمت البدعة هذه\" فما رأيكم في هذا التقسيم؟","title":"معنى قول عمر بن الخطاب: «نعمت هذه البدعة»","answer":"الجواب: ذهب بعض أهل العلم إلى أن البدع تنقسم إلى أقسام خمسة، وأنها تدخلها الأحكام الخمسة: التحريم، والوجوب، والكراهة، والاستحباب، والإباحة، ذهب إلى هذا جماعة، وأنكر هذا آخرون من أهل العلم، وقالوا: ليس في البدعة تقسيم، بل كلها ضلالة، وهكذا قال قائد المسلمين، وإمامهم كل بدعة ضلالة. وليس لأحد أن يخالفه فيقول: لا، ما هي بكلها ضلالة، هذا جرأة على الرسول ﷺ لا يجوز فعلها، والنبي -عليه الصلاة والسلام- قال: كل محدثة بدعة، وكل بدعة ضلالة هكذا قال -عليه الصلاة والسلام- وبين، فلا يجوز لنا، ولا لغيرنا أن نقول: إن البدعة فيها ضلالة، وفيها غير ضلالة، بل كلها ضلالة، وهي ما أحدثه الناس في الدين، كله ضلالة، وما يحتجون به على التقسيم لا حجة لهم فيه.  فالأشياء التي احتجوا بها على البدعة الواجبة من نقط المصاحف، وتشكيل المصاحف، ومن بناء المساجد كل هذا ليس من البدع، بل هذا أمر الله به، ورسوله، أمر الله ببناء المساجد، وأمر بالعناية بالقرآن، وحفظ القرآن، وتلاوته، فما أعان على هذا؛ فهو داخل في الأمر بالحفظ، والعناية. والمقصود: أن ما ذكروه ليس من باب البدع، بل هو من باب الدين، ومن باب حفظ الدين، ومن باب التعاون على البر، والتقوى. وأما قول عمر  لما رأى الناس اجتمعوا على صلاة التراويح بأمره، كان الناس في عهد النبي ﷺ يصلون فرادى، وجماعات، فصلى بهم النبي ﷺ ليال، وجمعهم، صلى بهم قيامًا -عليه الصلاة والسلام- ثلاث ليال، ثم ترك ذلك، وقال: إني أخشى أن تفرض عليكم صلاة الليل وكان شفيقًا على أمته، عليه الصلاة والسلام.  فلما توفي ﷺ شغل الصديق -رضي الله عنه وأرضاه- أهل الردة، وشغل بهم الصحابة -رضي الله عنهم وأرضاهم- فلما جاءت خلافة عمر؛ صار أفرغ لذلك، ومدته طويلة، فنظر في جمع الناس على إمام واحد، بدل ما كانوا يصلون أوزاعًا في المسجد، فجمعهم على إمام واحد، وأمر أُبيًّا أن يصلي بهم، فلما خرج ذات ليلة، ونظر إليهم، قال: \"نعمت هذه البدعة\"سماها بدعة من جهة اللغة، لا من جهة الدين؛ لأن البدعة في اللغة ما كان على غير مثال سابق. فالمعنى: أنهم كانوا في السابق يصلون أوزاعًا، ولم يجتمعوا على إمام واحد، فلما جمعهم؛ قال: \"نعمت البدعة\" التي فعلها هو لهم؛ ليجتمعوا، ويتعاونوا على البر، والتقوى، ولأن الرسول ما استمر عليها، إنما فعلها ثلاث، ثم ترك، فلهذا قال عمر هذه المقالة، فهي مقالة له من جهة اللغة، مقصوده من جهة اللغة، لا من جهة الأمر الشرعي، فليست بدعة من جهة الأمر الشرعي، بل هي سنة، وقربة، فعلها الرسول ﷺ وفعلها الخلفاء الراشدون، عمر، ومن بعده، وفعلها أصحاب النبي ﷺ وفعلها المسلمون، وحث عليها النبي ﷺ قال: من قام رمضان إيمانًا، واحتسابًا؛ غفر له ما تقدم من ذنبه وقال: من قام مع الإمام يعني في رمضان حتى ينصرف؛ كتب له قيام ليلة فدل على شرعية القيام، وأنه يكون له إمام، وجماعة، فليس من البدعة في شيء.","link":"https://binbaz.org.sa/fatwas/1487/معنى-قول-عمر-بن-الخطاب-نعمت-هذه-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_417.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":6083,"question":"يقولون في البدع حسنة، وسيئة، يستدلون بقول عمر  عند التراويح: \"نعمت البدعة هذه\" فما رأيكم في هذا التقسيم؟","title":"معنى قول عمر بن الخطاب: «نعمت هذه البدعة»","answer":"الجواب: ذهب بعض أهل العلم إلى أن البدع تنقسم إلى أقسام خمسة، وأنها تدخلها الأحكام الخمسة: التحريم، والوجوب، والكراهة، والاستحباب، والإباحة، ذهب إلى هذا جماعة، وأنكر هذا آخرون من أهل العلم، وقالوا: ليس في البدعة تقسيم، بل كلها ضلالة، وهكذا قال قائد المسلمين، وإمامهم كل بدعة ضلالة. وليس لأحد أن يخالفه فيقول: لا، ما هي بكلها ضلالة، هذا جرأة على الرسول ﷺ لا يجوز فعلها، والنبي -عليه الصلاة والسلام- قال: كل محدثة بدعة، وكل بدعة ضلالة هكذا قال -عليه الصلاة والسلام- وبين، فلا يجوز لنا، ولا لغيرنا أن نقول: إن البدعة فيها ضلالة، وفيها غير ضلالة، بل كلها ضلالة، وهي ما أحدثه الناس في الدين، كله ضلالة، وما يحتجون به على التقسيم لا حجة لهم فيه.  فالأشياء التي احتجوا بها على البدعة الواجبة من نقط المصاحف، وتشكيل المصاحف، ومن بناء المساجد كل هذا ليس من البدع، بل هذا أمر الله به، ورسوله، أمر الله ببناء المساجد، وأمر بالعناية بالقرآن، وحفظ القرآن، وتلاوته، فما أعان على هذا؛ فهو داخل في الأمر بالحفظ، والعناية. والمقصود: أن ما ذكروه ليس من باب البدع، بل هو من باب الدين، ومن باب حفظ الدين، ومن باب التعاون على البر، والتقوى. وأما قول عمر  لما رأى الناس اجتمعوا على صلاة التراويح بأمره، كان الناس في عهد النبي ﷺ يصلون فرادى، وجماعات، فصلى بهم النبي ﷺ ليال، وجمعهم، صلى بهم قيامًا -عليه الصلاة والسلام- ثلاث ليال، ثم ترك ذلك، وقال: إني أخشى أن تفرض عليكم صلاة الليل وكان شفيقًا على أمته، عليه الصلاة والسلام.  فلما توفي ﷺ شغل الصديق -رضي الله عنه وأرضاه- أهل الردة، وشغل بهم الصحابة -رضي الله عنهم وأرضاهم- فلما جاءت خلافة عمر؛ صار أفرغ لذلك، ومدته طويلة، فنظر في جمع الناس على إمام واحد، بدل ما كانوا يصلون أوزاعًا في المسجد، فجمعهم على إمام واحد، وأمر أُبيًّا أن يصلي بهم، فلما خرج ذات ليلة، ونظر إليهم، قال: \"نعمت هذه البدعة\"سماها بدعة من جهة اللغة، لا من جهة الدين؛ لأن البدعة في اللغة ما كان على غير مثال سابق. فالمعنى: أنهم كانوا في السابق يصلون أوزاعًا، ولم يجتمعوا على إمام واحد، فلما جمعهم؛ قال: \"نعمت البدعة\" التي فعلها هو لهم؛ ليجتمعوا، ويتعاونوا على البر، والتقوى، ولأن الرسول ما استمر عليها، إنما فعلها ثلاث، ثم ترك، فلهذا قال عمر هذه المقالة، فهي مقالة له من جهة اللغة، مقصوده من جهة اللغة، لا من جهة الأمر الشرعي، فليست بدعة من جهة الأمر الشرعي، بل هي سنة، وقربة، فعلها الرسول ﷺ وفعلها الخلفاء الراشدون، عمر، ومن بعده، وفعلها أصحاب النبي ﷺ وفعلها المسلمون، وحث عليها النبي ﷺ قال: من قام رمضان إيمانًا، واحتسابًا؛ غفر له ما تقدم من ذنبه وقال: من قام مع الإمام يعني في رمضان حتى ينصرف؛ كتب له قيام ليلة فدل على شرعية القيام، وأنه يكون له إمام، وجماعة، فليس من البدعة في شيء.","link":"https://binbaz.org.sa/fatwas/1487/معنى-قول-عمر-بن-الخطاب-نعمت-هذه-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_417.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":6111,"question":"يصنعون في بعض البلاد الإسلامية طعامًا يسمونه صدقة للميت، فهل يجوز الأكل منه؟","title":"حكم صناعة الطعام باسم الصدقة على الميت","answer":"الجواب: ما يعتاده بعض البلاد من المأتم، صدقة يسمونها المأتم، في يوم موته، أو في الرابع، أو في السابع، أو في الأربعين هذه بدعة، ما ينبغي أن .. ولا تجاب الدعوة؛ لأن إجابة الدعوة تشجع على البدع. فهذه المآتم التي يصنع فيها الطعام في أيام معدودة، يوم الميت، سواء كان يوم الموت، أو في اليوم السابع، أو في اليوم العاشر، أو في الأربعين، أو في السنة للميت الميت هذه بدعة، لا ينبغي أن يجيب إليها؛ لأن الإجابة إليها فيها نوع من التشجيع على البدع.","link":"https://binbaz.org.sa/fatwas/1540/حكم-صناعة-الطعام-باسم-الصدقة-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_470.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6115,"question":"ما حكم قراءة سورة الفاتحة للميت؟","title":"حكم قراءة سورة الفاتحة للميت","answer":"الجواب: اختلف العلماء في ذلك، بعض أهل العلم يرى أنه لا بأس أن يقرأ القرآن للموتى، ويثوبه للميت، قالوا: إنه كسائر القربات، كما تدعو له، كما تتصدق عنه، كذلك إذا قرأ القرآن .. قالوا: لا بأس أن يثوبها للميت.  وقال آخرون: هذا شيء لم ينقل عن السلف، لا عن الصحابة، ولا عن من بعدهم من السلف المعروفين أنهم فعلوا هذا للميت، ثوبوا له؛ فالأولى تركه، فالأولى ترك ذلك، الأقرب والأولى ترك هذا أن يقرأ لنفسه .. هذا هو الأولى، والأفضل، والأحوط. السؤال:.. الشيخ: ما له أصل، النبي ﷺ دفن كثيرًا من الصحابة، ولم يقرأ عند القبر -عليه الصلاة والسلام- هذا من البدع، عند القبر يكون الوعظ، والتذكير لله، والتذكير بالآخرة، والتذكير بالقبر، وما فيه من الأهوال، هذه السنة، أما أن يقرأ عند القبر لا. النبي ﷺ لما جلس عند القبر، وحوله الناس؛ ذكرهم، ووعظهم، ذكرهم بأمر القبور، وأمر الجنة، والنار؛ حتى يستعدوا للقاء الله، يذكر الأحياء الحاضرين.","link":"https://binbaz.org.sa/fatwas/1541/حكم-قراءة-سورة-الفاتحة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_471.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":6186,"question":"بعض الذين يقيمون الموالد، ويحتفلون بليلة الإسراء، والمعراج، يقولون: نحن نقصد الذكر، والصلاة على الرسول، ويقولون: إن العلماء لم ينكروا على الاحتفال باليوم الوطني، وغيره من هذا القبيل، فكيف نعترض على المولد؟","title":"شبهة في الاحتفال بالمولد والرد عليها","answer":"الجواب: يقال لهم: إن الرسول ﷺ وأصحابه أحرص منكم، وأرغب في الخير، وأولى بكل فضيلة، فلو كان الاحتفال بالموالد، أو بالإسراء، والمعراج أمرًا مشروعًا، وقربة إلى الله  لكانوا إليه أسرع، لكانوا إليه أسبق، وكانوا به أولى، وقد قال -عليه الصلاة والسلام-: إياكم ومحدثات الأمور وقال: شر الأمور محدثاتها، وكل بدعة ضلالة وليس للناس أن يحدثوا بآرائهم عبادات.  فإذا قالوا هذه المقالة؛ أمكن غيرهم أن يقول أيضًا: نحدث صلاة سادسة، ما أردنا إلا الخير، والذكر، نحدث صلاة سادسة، الضحى فريضة، ندعو الناس إليها أربع ركعات، أو ركعتين، تصلى جماعة سادسة، زيادة في الخير، والفضل. أو يقول آخر: يمكن أن نحدث أيضًا عبادة أخرى، وهو أن نحج في العام مرتين، ما يكفي حج واحد، نحج في العام مرتين، فهذا زيادة فضل، وذكر، وطاعة لله، وطواف، وشبه ذلك، والآخر يقول: نحدث أذانين لكل فريضة، الأذان الواحد ما يكفي؛ لأنه ذكر، وطاعة لله، فيؤذن مرتين في كل مسجد؛ لأن هذا زيادة ذكر، أو يقيم مرتين، أو ثلاثًا، أو يؤذن أربع مرات، أو عشر مرات؛ لأن هذا مزيد ذكر، وطاعة لله. فمعنى هذا: أن يكون الدين على الأهواء، والتلاعب بآراء الناس، ومحدثاتهم، وأفكارهم الضالة، والكاسدة، هذا شيء لا حد له، وهذا هو الذي وقع في اليهود والنصارى حتى تلاعبوا بدينهم، واستحسنوا ما لم يشرعه الله  لهم. وأما ما يتعلق باليوم الوطني، فهذا ليس من العبادات؛ بل هذا اخترعوه لأمور أخرى سياسية، ليس من باب العبادات، ولكنه قد ينهى عنه من جهة أنه تشبه باليهود، والنصارى بما أحدثوا من الأيام الوطنية، وأشباهها، والأعياد، فهذا من باب السياسة، ومن باب التشبه بالمشركين فيما أحدثوا من أعياد وطنية، وليس من باب العبادة، بل من باب الأمور السياسية التي أحدثها بعض الناس؛ تقليدًا لغيره، وتشبهًا بمن فعله من الكفرة، فهو ممنوع يجب منعه لما فيه من التشبه بأعداء الله.","link":"https://binbaz.org.sa/fatwas/1654/شبهة-في-الاحتفال-بالمولد-والرد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_538.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6380,"question":"ما حكم من يقرأ الفاتحة لله، ثم على روح النبي ﷺ؟","title":"حكم قراءة الفاتحة لله وإلى روح النبي عليه الصلاة والسلام","answer":"الجواب: لا أصل له، هذا النبي ﷺ له مثل أجورنا -عليه الصلاة والسلام- ولم يفعله الصحابة، وهم خير الناس؛ فلا تقرأ الفاتحة على النبي ﷺ ولا على غيره، ولكن تصلي عليه كثيرًا -عليه الصلاة والسلام- تصلي عليه كثيرًا، وتجتهد في اتباع سنته، وتعظيم أمره، ونهيه، والمسارعة إلى ما شرع، كما قال الله سبحانه: قُلْ إِن كُنتُمْ تُحِبُّونَ اللّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31].  فالمشروع فعل ما شرع لك من: الصلوات، والزكوات، والصيام، والحج، والأمر بالمعروف، والنهي عن المنكر، والجهاد في سبيل الله، وبر الوالدين، وصلة الرحم، والإكثار من ذكر الله، والصلاة والسلام على رسول الله -عليه الصلاة والسلام- هذا المشروع، أما أن تقرأ الفاتحة، أو يس، أو الأعراف، أو كذا فهذا ما هو مشروع.","link":"https://binbaz.org.sa/fatwas/1956/حكم-قراءة-الفاتحة-لله-والى-روح-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_743.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6395,"question":"رأيت ميتًا وفوق صدره القرآن، هل هو جائز، أم لا؟","title":"حكم وضع القرآن على صدر الميت قبل تغسيله","answer":"الجواب: لا، لا يشرع وضع القرآن على الميت، ولكن بعض الناس سمع أن الميت يوضع عليه شيء؛ فظن أن القرآن أولى، وليس المقصود وضع القرآن، المقصود وضع شيء له، ثقل على بطنه؛ حتى لا ينتفخ إلى أن يغسل، وينقل إلى المقبرة، فيوضع عليه حديدة، أو حجر، أو ما أشبه ذلك من شيء ثقيل على بطنه حتى يغسل؛ لأنه قد ينتفخ، فيوضع عليه هذا الشيء الثقيل الذي يناسبه؛ حتى لا ينتفخ إلى أن يغسل، ويفرغ منه، ولا يوضع المصحف. ليس المصحف آلة للتثقيل، إنما المصحف طبع، وختم ليقرأ، وينتفع به، فلا يوضع المصحف على الميت، ولكن يوضع شيء له ثقل من خشب، أو من حديد، أو من حجر على البطن هذا قاله بعض أهل العلم، يقولون: إن وضعه عليه يخفف الانتفاخ، والأمر في هذا سهل، لكن المصحف لا يوضع.","link":"https://binbaz.org.sa/fatwas/1969/حكم-وضع-القران-على-صدر-الميت-قبل-تغسيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_756.mp3","categories":["مسائل متفرقة في الجنائز","البدع والمحدثات"]},{"id":6396,"question":"رأيت ميتًا وفوق صدره القرآن، هل هو جائز، أم لا؟","title":"حكم وضع القرآن على صدر الميت قبل تغسيله","answer":"الجواب: لا، لا يشرع وضع القرآن على الميت، ولكن بعض الناس سمع أن الميت يوضع عليه شيء؛ فظن أن القرآن أولى، وليس المقصود وضع القرآن، المقصود وضع شيء له، ثقل على بطنه؛ حتى لا ينتفخ إلى أن يغسل، وينقل إلى المقبرة، فيوضع عليه حديدة، أو حجر، أو ما أشبه ذلك من شيء ثقيل على بطنه حتى يغسل؛ لأنه قد ينتفخ، فيوضع عليه هذا الشيء الثقيل الذي يناسبه؛ حتى لا ينتفخ إلى أن يغسل، ويفرغ منه، ولا يوضع المصحف. ليس المصحف آلة للتثقيل، إنما المصحف طبع، وختم ليقرأ، وينتفع به، فلا يوضع المصحف على الميت، ولكن يوضع شيء له ثقل من خشب، أو من حديد، أو من حجر على البطن هذا قاله بعض أهل العلم، يقولون: إن وضعه عليه يخفف الانتفاخ، والأمر في هذا سهل، لكن المصحف لا يوضع.","link":"https://binbaz.org.sa/fatwas/1969/حكم-وضع-القران-على-صدر-الميت-قبل-تغسيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_756.mp3","categories":["مسائل متفرقة في الجنائز","البدع والمحدثات"]},{"id":6480,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6495,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6535,"question":"ما حكم الاحتفال باليوم الوطني، وكذلك أيضًا أسبوع الإمام محمد بن عبدالوهاب، وإذا كانت ليست بدعة فما الفرق بينها، وبين البدع؟","title":"حكم الاحتفال باليوم الوطني والأسابيع الدعوية","answer":"الجواب: العيد الوطني بدعة، العيد الوطني بدعة، أما أسبوع العلماء ليس من البدع، هذا أسبوع تعرض فيه كتبهم، ما هو باحتفال، هذا أسبوع تعرض فيه الكتب، إذا قيل أسبوع لكتاب كذا، وأسبوع لكتاب كذا، والأسبوع الذي بعده كذا، والأسبوع الذي بعده كذا، ليس هذا احتفالًا، هذا معرض للكتب، وبيان ما ألفه فلان وما طبع من كتبه، فإذا قيل أسبوع لمحمد، وأسبوع لشيخ الإسلام، وأسبوع للعز بن عبدالسلام، وأسبوع للقرطبي، وأسبوع لكذا، تعرض كتبهم، وتباع بين الناس، ليس هذا بابتداع، هذا إظهار للكتب، وبيع لها، ونشر لها بين الناس . أما اليوم الوطني، والاحتفال بيوم وطني، أو في أي يوم، أو في ليلة الرغائب، كل هذا بدعة، كلها من البدع، ومن التشبه بأعداء الله.","link":"https://binbaz.org.sa/fatwas/2365/حكم-الاحتفال-باليوم-الوطني-والاسابيع-الدعوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_899.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6540,"question":"سماحة شيخي، ما هي الشبه التي يوردها من يقول بسنية أعياد الموالد، وخاصة مولد الرسول ﷺ؟","title":"شبهة من يحتفلون بالموالد والرد عليها","answer":"الجواب: شبهتهم التأسي بأعداء الله، التأسي باليهود، والنصارى، هؤلاء يفعلونه يفعلونه مثلهم، لماذا نعظم نبينا مثل تعظيمهم بالموالد، نبينا معظم -بحمد الله- بما شرعه لنا ربنا على يديه -عليه الصلاة والسلام،- فنعظمه بالصلاة عليه، واتباع سنته، والشهادة له بالرسالة -عليه الصلاة والسلام- والدعوة إلى دينه، والتحذير من مخالفته -عليه الصلاة والسلام- من هذه البدع، وإحداث الموالد.","link":"https://binbaz.org.sa/fatwas/2366/شبهة-من-يحتفلون-بالموالد-والرد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_900.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6572,"question":"وفي قصاصة من مجلة الأخبار المصرية بتاريخ 17/12/83 الاحتفال بمولد النبي ليس بدعة، يقول البعض: إن الاحتفال بالمولد النبوي بدعة، وحجتهم في ذلك: أن النبي -عليه الصلاة والسلام- أو أحد صحابته الكرام لم يحتفلوا بهذه المناسبة، ووجهت هذا السؤال إلى فضيلة الشيخ عطية صقر عضو مجمع البحوث الإسلامية، وتلقيت منه الجواب الآتي: علينا أن نحدد معاني الألفاظ التي نعطيها حقها في الحكم، سواء بالصحة، أو البطلان، لفظ بدعة فهمه البعض على أنه كل شيء مستحدث، بصرف النظر عن كونه نافعًا، أو ضارًا، لفظ البدع ورد في بعض الأحاديث موصوفًا بأنها ضلالة، وتعني كل مستحدث في الدين، ولكنها في الموضوع الذي نحن بصدده معناها لغوي، أي الشيء المبتدع الذي على غير مثال سبق، وبذلك الفهم نتلافى التضارب الموجود في بعض المنقولات إلى آخر المقالة؟","title":"الرد على من ينفي بدعية الاحتفال بمولد النبي","answer":"الجواب: هو اعترف بما يدل على المقصود، الحديث جاء كل بدعة ضلالة فيكون الاحتفال بالمولد ضلالة؛ لأنه بدعة في الدين، ما فعلها الرسول ﷺ ولا أصحابه، ولا القرون المفضلة القرن الأول، والثاني، والثالث، فيكون بدعة ضلالة. وحب الرسول ﷺ لا يكون بالاحتفال، يكون بطاعته، واتباع شريعته، ودراسة ما جاء عنه، والتفقه في دينه، لا بالبدع التي أنكرها العلماء، وأحدثها الجهلة، أو أحدثها الرافضة، أو أشباههم، فالاحتفال بالموالد من بدع الرافضة، أول من أحدثها الرافضة الفاطميون، ثم تبعهم بعض الناس على ذلك، فهذا بدعة في الدين، ومشابهة للنصارى، واليهود، والرافضة فيما عملوا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2390/الرد-على-من-ينفي-بدعية-الاحتفال-بمولد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_921.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6611,"question":"توجد لدينا عادة جارية حتى الآن، عندما ينتهي الإمام من صلاة المغرب يجلس الإمام، ومعه جماعة من الإخوان، ويقرؤون معًا بصوت واحد سورة يس، وسورة تبارك، وآية الكرسي بين وقت المغرب والعشاء، فما حكم ذلك، نرجو الإفادة؟","title":"حكم قراءة يس والملك وآية الكرسي بعد الصلوات","answer":"الجواب:  هذا بدعة لا أصل له، يجلسون بعد صلاة المغرب، الإمام، وجماعة بصوت واحد، يقرؤون سورة يس، وسورة تبارك، وآية الكرسي، هذا بدعة، حتى ولو قرأ سورة الفاتحة.. لا أصل له في الشريعة. السنة بعد الصلاة أن يقول المؤمن: أستغفر الله ثلاثًا، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال، والإكرام، هذا أول شيء، ثم ينصرف الإمام إلى الناس، ثم يقول كل واحد: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، ثبت هذا عن رسول الله ﷺ أنه كان يقول إذا سلم في الظهر، والعصر، والمغرب، والعشاء، والفجر، ويزيد بعد ذلك في الفجر، والمغرب: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي، ويميت، وهو على كل شيء قدير عشر مرات. وجاء عنه ﷺ الحض، والتحريض، والتعليم أن يقول بعد ذلك: سبحان الله، والحمد لله، والله أكبر، ثلاثًا وثلاثين مرة، علمه فقراء المهاجرين، ثم تعلمه الجميع، سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، وفي حديث أبي هريرة عند مسلم، ويقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير فيصير الجميع مائة، إذا قالها؛ غفرت خطاياه، وإن كانت مثل زبد البحر. وقال في حديث أبي هريرة في الصحيحين لما جاءه الفقراء من المهاجرين، قالوا: يا رسول الله، ذهب أهل الدثور -يعني أهل الأموال- بالأجور يصلون كما نصلي، ويصومون كما نصوم، ويتصدقون، ولا نتصدق، ويعتقون، ولا نعتق، ما عندنا أموال؟ قال: أفلا أدلكم على شيء تدركون به من سبقكم، وتسبقون من بعدكم، ولن يكون أحد أفضل منكم إلا من صنع مثلما صنعتم قالوا: بلى يا رسول الله، قال: تسبحون، وتحمدون، وتكبرون دبر كل صلاة ثلاثًا وثلاثين مرة هكذا في الصحيحين .. -عليه الصلاة والسلام- وفي مسلم، ويقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير فرجع الفقراء يقولونها بعد كل صلاة، ثم رجعوا إليه، فقالوا: يا رسول الله، سمع إخواننا أهل الأموال ما فعلنا، ففعلوا مثله -يعني صاروا يسبحون، ويحمدون، ويكبرون مثله- قال النبي ﷺ: ذلك فضل الله يؤتيه من يشاء إذا رزقه الله المال، وأنواع الذكر، والعبادة هذا فضله  يؤتيه لمن يشاء، والله ذو الفضل .  وعلمهم آية الكرسي بعد كل صلاة اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] فقد ثبت فيها الحديث، وهكذا قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] بعد كل صلاة، وفي صلاة المغرب، والفجر زيادة، يقرأ قل هو الله أحد، والمعوذتين ثلاث مرات، هذا هو المشروع بعد الصلوات، وإذا دعا .. دعوات بينه وبين نفسه؛ فلا بأس من دون رفع اليدين، فقد جاء الدعاء بعد الصلاة عنه عليه الصلاة والسلام. أما أنه يقرأ الإمام، والجماعة بصوت واحد، يقرؤون هذا لا أصل له، بل هو بدعة، وهكذا رفع أيديهم بالدعاء بعد الصلوات الخمس بدعة أيضًا، وإنما السنة ما سمعتم من فعل النبي ﷺ وتعليمه عليه الصلاة والسلام.\n... هذا دعاء طيب، لكن الأفضل قبل السلام، علمه النبي معاذ بن جبل، يكون قبل السلام أفضل، وإن دعا به بعد السلام فلا بأس: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك. كذلك: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم، اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر لا إله إلا أنت، اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر، كل هذا الأفضل فيه قبل السلام، في آخر التحيات، وإن دعا ببعض هذا بعد السلام؛ فلا بأس، لكن بينه، وبين نفسه، من دون صوت جماعي، من دون رفع الأيدي مع الإمام، كل هذا لا يفعل، بس دعاء بينه، وبين نفسه، وبينه وبين ربه.","link":"https://binbaz.org.sa/fatwas/2456/حكم-قراءة-يس-والملك-واية-الكرسي-بعد-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_983.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6612,"question":"هل الأذان، والإقامة عند قبر الميت مشروع؟ وهل قراءة القرآن على القبر، أو في بيت الميت الثلاثة أيام له أصل من قرأ، أم لا؟","title":"حكم الأذان والإقامة في القبر وقراءة القرآن في بيت الميت","answer":"الجواب: هذه بدعة ما لها أصل، بعض الناس يأذن في القبر، أو يقيم في القبر، هذه بدعة ما لها أصل، أو يقرأ فيه، بعض القراءة هذه بدعة ما لها أصل، كذلك التجمع في بيت الميت، ويقرؤون فيه أيامًا وليالي، هذه بدعة ما لها أصل. السؤال: هذا منتشر في المقبرة، ولا هناك من يرشدهم؟ الجواب: لا، ينبهون الدعاة، والهيئة -إن شاء الله- تلاحظ، وأنت واحد من الناس إذا شفته؛ أنكر عليه -جزاك الله خيرًا- أنت واحد من الإخوان، تقول لهم: هذا بدعة، وهذا لا يجوز، لأن الدعوة إلى الله ما هي خاصة بأحد دون أحد، من علم شيئًا يبين للناس، والهيئة كذلك، فالواجب التساعد، والتعاون على البر، والتقوى.","link":"https://binbaz.org.sa/fatwas/2440/حكم-الاذان-والاقامة-في-القبر-وقراءة-القران-في-بيت-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_967.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6632,"question":"ما هي أوقات زيارة القبور؟ وما هو الدعاء الذي يدعى للميت في المقبرة؟ وما حكم زيارة أيام الأعياد؟","title":"هل لزيارة القبور وقت معين؟ وحكم الزيارة أيام الأعياد","answer":"الجواب: القبور تسن زيارتها، وليس لها حد محدود، لا في الليل، ولا في النهار، النبي ﷺ زارها ليلًا، وزارها نهارًا -عليه الصلاة والسلام- فليس لها وقت محدود يشرع زيارتها، متى تيسر للعبد زيارتها، فليس لها يوم محدود، لا جمعة، ولا غيرها، متى تيسرت الزيارة، وفرغ للزيارة، أو وفقه الله للزيارة في أي وقت، في يوم العيد، أو في يوم الجمعة، أو في السبت، أو في الليل، أو في النهار. أما أن يخص لها وقتًا يوم العيد راتبًا، أو يوم الجمعة راتبًا، هذا لا أصل له، لكن يزورها متى تيسر، يتذكر بها الآخرة، والموت، ويستعد للآخرة، النبي  قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه، فيقول -عليه الصلاة والسلام- لهم: إذا زرتم القبور؛ قولوا السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا  -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا، والمستأخرين، نسأل الله لنا، ولكم العافية وكان يزور البقيع ﷺ ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غدًا مؤجلون، اللهم اغفر لأهل بقيع الغرقد هذه زيارته -عليه الصلاة والسلام-. والمقصود منها ذكر الآخرة، ذكر الموت، والإحسان للموتى، والدعاء لهم، والترحم عليهم، هذا المقصود حتى يستعد للآخرة، وحتى يستعد للموت قبل نزوله. السؤال: في بعض البلاد يزورنها ليلة العيد إذا أعلن فجأة رمضان، ليلة العيد، أو صباح العيد، زيارة جماعية؟ الجواب: لا نعلم لهذا أصلًا، هذا بدعة، هذا ليس له أصل، كونه يخص ليلة العيد، أو ليلة من الليالي، جماعيًا يقصدونها، لا أصل له، ولا ينبغي له، إذا أراد هذا يكون من البدعة، إذا أراد هذا خاص، وأنه قربة، وهذا ظاهر عمله. السؤال: والميت إذا وضع على عربة مدفع هل هذا جائز؟ الجواب: لماذا؟ السؤال: في بعض الدول الإسلامية يضعونها على عربة مدفع، ويدقون المزيكا يحملون...؟ الجواب: هذا ما له أصل، هذا ما له أصل، أما كونه يحمل في السيارة حتى لا يتعبوا ما في بأس.  السؤال: لا هم يحملونه فوق عربة مدفع؟ الجواب: أما على طريقة.. مالها أصل، إذا كان معه موسيقى؛ صار أقبح. السؤال: وستة خيول سود؟ الجواب: هذا غلط، هذا غلط.","link":"https://binbaz.org.sa/fatwas/2477/هل-لزيارة-القبور-وقت-معين-وحكم-الزيارة-ايام-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1004.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":6636,"question":"ما رأي سماحة الشيخ في تقسيم البدع، كالبدع المستحبة، والبدع المحرمة، ووجه دليل من قال بهذا التقسيم، مع بيان قول الرسول ﷺ: كل بدعة ضلالة؟","title":"حكم تقسيم البدع","answer":"الجواب: ذهب بعض الناس -بعض الفقهاء من المتأخرين- إلى تقسيم البدعة إلى حسنة، وسيئة، وواجبة، ومحرمة، ومباحة، وهذا لا أصل له، هذا التقسيم لا أصل له، فليس في البدع شيء حسن، كلها ضلالة، النبي ﷺ قال: كل بدعة ضلالة فلا يجوز الاعتراض على الرسول ﷺ فالذي يقسمها يقول: بعضها ضلالة، وبعضها ما هو ضلال، معترض على الرسول ﷺ أتى النبي ﷺ بعبارة جامعة، قال: كل بدعة ضلالة فهذا كلام عام جامع، لا يجوز أن يعترض عليه.  وأما ما يظن بعض الناس أنه بدعة، وهو مما شرعه الله، ليس ببدعة، مثل بناء المساجد ليس بدعة ... -عليه الصلاة والسلام- وكذلك نقط المصاحف، وتشكيلها من باب الإيضاح لكلام الله، ليس من البدع، فمن باب الإيضاح لكلام الله، وبيان ما هو مرفوع، وما هو منصوب؛ لأن بعض العامة لا يحسن ذلك، وقد تشتبه عليه بعض الكلمات إذا لم تنقط، وكذلك جمع المصاحف، وكذلك بناء المدارس، كل هذا ما هو من البدع، بل مما شرع الله، ومما دعا إليه رسول الله ﷺ لأن الله أمرنا أن نحفظ كتابه، وأن نعلم أولادنا، وهذا من باب التعليم، والإيضاح، وليس هذا من البدع، هكذا إيجاد الربط، والأوقاف ليس من البدع، بل من باب الصدقات الجارية، والنبي ﷺ قال: لو مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له فإذا أوقف الناس بيوتًا على الأئمة، أو المؤذنين، أو الأربطة، أو غير ذلك للتدريس، والتعليم، والغرباء، والفقراء، والمساكين، هذا من العمل الصالح، والصدقات الجارية الداخلة فيما حث عليه النبي ﷺ من نفع الناس، وإرشادهم، والصدقة عليهم، ومواساتهم، ورحمتهم، هذا كله تشبيه لا وجه. السؤال: وقول: (نعمت هذه البدعة)؟ الجواب: هذا يروى عن عمر، جاء عن عمر في مسألة التراويح من حيث اللغة، مثل ما قال: بَدِيعُ السَّمَاوَاتِ [البقرة:117] يعني من حيث اللغة، أنه جمعهم على إمام، ولم يكونوا مجموعين على إمام سابق في التراويح، وصلى بهم ﷺ ثلاث ليالي، أو أربع، ثم تركهم خوفًا أن تفرض عليهم، فجمعهم عمر على إمام واحد، وخرج ذات ليلة، وهم يصلون، فقال: (نعمت هذه البدعة).  فالمعنى يعني من حيث اللغة، أما هو يعرف أنها سنة، ولهذا فعلها ودعا إليها، وفعلها الرسول ﷺ فهي سنة بلا شك، هي سنة، وقربة، ليست بدعة في الدين، ولكن من في قلبه مرض يتعلق بهذه الكلمة، ولو كانت في غير صفه لما تعلق بها.","link":"https://binbaz.org.sa/fatwas/2475/حكم-تقسيم-البدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1002.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6647,"question":"ما هي أوقات زيارة القبور؟ وما هو الدعاء الذي يدعى للميت في المقبرة؟ وما حكم زيارة أيام الأعياد؟","title":"هل لزيارة القبور وقت معين؟ وحكم الزيارة أيام الأعياد","answer":"الجواب: القبور تسن زيارتها، وليس لها حد محدود، لا في الليل، ولا في النهار، النبي ﷺ زارها ليلًا، وزارها نهارًا -عليه الصلاة والسلام- فليس لها وقت محدود يشرع زيارتها، متى تيسر للعبد زيارتها، فليس لها يوم محدود، لا جمعة، ولا غيرها، متى تيسرت الزيارة، وفرغ للزيارة، أو وفقه الله للزيارة في أي وقت، في يوم العيد، أو في يوم الجمعة، أو في السبت، أو في الليل، أو في النهار. أما أن يخص لها وقتًا يوم العيد راتبًا، أو يوم الجمعة راتبًا، هذا لا أصل له، لكن يزورها متى تيسر، يتذكر بها الآخرة، والموت، ويستعد للآخرة، النبي  قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه، فيقول -عليه الصلاة والسلام- لهم: إذا زرتم القبور؛ قولوا السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا  -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا، والمستأخرين، نسأل الله لنا، ولكم العافية وكان يزور البقيع ﷺ ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غدًا مؤجلون، اللهم اغفر لأهل بقيع الغرقد هذه زيارته -عليه الصلاة والسلام-. والمقصود منها ذكر الآخرة، ذكر الموت، والإحسان للموتى، والدعاء لهم، والترحم عليهم، هذا المقصود حتى يستعد للآخرة، وحتى يستعد للموت قبل نزوله. السؤال: في بعض البلاد يزورنها ليلة العيد إذا أعلن فجأة رمضان، ليلة العيد، أو صباح العيد، زيارة جماعية؟ الجواب: لا نعلم لهذا أصلًا، هذا بدعة، هذا ليس له أصل، كونه يخص ليلة العيد، أو ليلة من الليالي، جماعيًا يقصدونها، لا أصل له، ولا ينبغي له، إذا أراد هذا يكون من البدعة، إذا أراد هذا خاص، وأنه قربة، وهذا ظاهر عمله. السؤال: والميت إذا وضع على عربة مدفع هل هذا جائز؟ الجواب: لماذا؟ السؤال: في بعض الدول الإسلامية يضعونها على عربة مدفع، ويدقون المزيكا يحملون...؟ الجواب: هذا ما له أصل، هذا ما له أصل، أما كونه يحمل في السيارة حتى لا يتعبوا ما في بأس.  السؤال: لا هم يحملونه فوق عربة مدفع؟ الجواب: أما على طريقة.. مالها أصل، إذا كان معه موسيقى؛ صار أقبح. السؤال: وستة خيول سود؟ الجواب: هذا غلط، هذا غلط.","link":"https://binbaz.org.sa/fatwas/2477/هل-لزيارة-القبور-وقت-معين-وحكم-الزيارة-ايام-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1004.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":6670,"question":"أنا شاب أعزب، ومتدين -ولله الحمد- ولكني إذا جئت أتوضأ للصلاة أترجل في إخراج اسم الله عند الوضوء، وأتكلم بالنية في نفسي، فمثلًا، أقول: أتوضأ لصلاة كذا داخل نفسي، ولكن في الآونة الأخيرة صار بيني، ما أدري ماذا يقصد؟","title":"حكم التلفظ بالنية قبل الوضوء","answer":"الجواب: ما يحتاج يا ولدي التكلم بالنية، قلبك يكفي، ما دمت قمت للوضوء، فالنية كافية، أما قول: نويت أن أتوضأ لصلاة الظهر هذه بدعة ما لها أصل، النية في القلب يكفي، الأعمال بالنيات، النية في القلب، والتلفظ بها بدعة، فلا حاجة إلى أن تقولها في نفسك، والتسمية باللسان تقول: بسم الله عند الوضوء، بسم الله، ثم تتوضأ، يعني تبدأ بالمضمضة، والاستنشاق، ونحو ذلك، أو عند غسل يديك ثلاثًا، سمي الله، أما .. للوضوء ما حاجة، فالقلب يكفي، لكن القلب يكفي بنية الوضوء ونية الصلاة، ونية الصيام، ونية الحج يكفي، لكن يقال في الحج: لبيك كذا، وكذا.","link":"https://binbaz.org.sa/fatwas/2536/حكم-التلفظ-بالنية-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1031.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6679,"question":"حكم صنع الطعام لأهل الميت؟","title":"حكم صنع الطعام لأهل الميت","answer":"الجواب: .. لا يصنعون ولائم بعد الموت لا، أما كون جيرانه، أو أقاربه يدفعون لأهل الميت طعامًا فهذا مشروع، وقد ثبت عن النبي ﷺ أنه لما جاء نعي جعفر بن أبي طالب  لما قتل في الشام، أمر النبي ﷺ أهل بيته أن يصنعوا طعامًا لأهل بيت جعفر، فإذا صنع جيرانهم لهم طعامًا، أو بعض أقاربهم لهم طعامًا أيام المصيبة؛ فلا بأس، أما أهل الميت لا يصنعون طعامًا للناس، ولا يقيمون الولائم، قال جرير بن عبدالله البجلي  : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن كنا نعده من النياحة\".","link":"https://binbaz.org.sa/fatwas/2548/حكم-صنع-الطعام-لاهل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1043.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6692,"question":"عندما يموت إنسان مسلم في بلادنا يدفع أهله مبلغًا من المال لشخص، أو أكثر؛ من أجل ختم القرآن للميت، ما رأي فضيلتكم في هذا؟","title":"حكم استئجار من يقرأ القرآن عن الميت","answer":"الجواب: هذا لا أصل له، كونهم يستأجرون من يقرأ القرآن للميت هذا لا أصل له، والقارئ لا أجر له؛ لأنه قرأ بالأجر، فلا أجر له، فلا يستحب هذا، ولا يشرع، وقد مضى النبي ﷺ والصحابة، ولم يفعلوه، وهم أسبق الناس إلى كل خير، وأسبقهم إلى كل طاعة، فلا يجوز كونه يستأجر من يقرأ للميت بعد الموت، أو جماعة يقرؤون أيام العزاء، هذا بدعة لا أصل له.","link":"https://binbaz.org.sa/fatwas/2546/حكم-استىجار-من-يقرا-القران-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1041.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6696,"question":"عندما يموت إنسان مسلم في بلادنا يدفع أهله مبلغًا من المال لشخص، أو أكثر؛ من أجل ختم القرآن للميت، ما رأي فضيلتكم في هذا؟","title":"حكم استئجار من يقرأ القرآن عن الميت","answer":"الجواب: هذا لا أصل له، كونهم يستأجرون من يقرأ القرآن للميت هذا لا أصل له، والقارئ لا أجر له؛ لأنه قرأ بالأجر، فلا أجر له، فلا يستحب هذا، ولا يشرع، وقد مضى النبي ﷺ والصحابة، ولم يفعلوه، وهم أسبق الناس إلى كل خير، وأسبقهم إلى كل طاعة، فلا يجوز كونه يستأجر من يقرأ للميت بعد الموت، أو جماعة يقرؤون أيام العزاء، هذا بدعة لا أصل له.","link":"https://binbaz.org.sa/fatwas/2546/حكم-استىجار-من-يقرا-القران-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1041.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6701,"question":"بعد وفاة الميت -عندنا في مناطق الجنوب- بعد وفاة الميت .. يبنون الخيام بجوار بيت المتوفى، ويقيمون فيها الحفلات، والذبائح؟","title":"حكم بناء الخيام لإقامة المآتم","answer":"الجواب:  هذا بدعة، هذا مأتم، بينَّا كم مرة في الصحف، ورسائل قرئت عليهم في الجنوب، وبُين في الصحف، والمجلات كل هذا بُين، ومنكر، لا يجوز هذا. السؤال: يكون بدعة هذا؟ الجواب:  نعم، بدعة، ما يجوز هذا، نعم. السؤال: يجوز نروح لهم نعزيهم، وهم بهذا الشكل؟ الجواب: لا. السؤال: لكن اجتماعهم من دون خيام، ومن دون محمل، لكن اجتماع الكل يعني ..؟ الجواب: إذا زاروهم للتعزية سنة، أما إقامة حفل لهذا، ومأتم ما يجوز هذا. السؤال: لا هم يجتمعون يأتون .. يردون العزاء، فيستقبلونهم جماعة الميت؟ الجواب: يستقبلونهم في بيوتهم، ما يحتاج إقامة مخيمات، يستقبلوهم في بيوتهم، والحمد لله.. السؤال: ولكن حكم إقامتهم كيف حكم .. الجواب: هذا منكر ما له أصل، هذا مأتم من المآتم. السؤال: أحيانا تضيق البيوت عن استيعاب المعزين؛ لأنهم يأتون بالآلاف، فهم يصنعون مكاناً يقيهم من الحر، أو من البرد، أو من المطر، ويستقبلون فيه المعزين، ويروح؟ الجواب: إذا وجد .. من دون ولائم، من دون شيء .. عند الحاجة إلى ذلك.","link":"https://binbaz.org.sa/fatwas/2580/حكم-بناء-الخيام-لاقامة-الماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1076.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6705,"question":"هل يجوز أن يقرأ أحد الأشخاص القرآن، ويرد الذين يستمعون له بنهاية كل آية بأن يقولوا: الله أكبر، أو اللهم صل على محمد، إذا كان هذا لا يجوز، لماذا نخرج مثل هذه القراءات في إذاعة القرآن الكريم، وقد يكون هذا إقرار لهذا الفعل من جانب الإذاعة؟","title":"حكم التكبير أو الصلاة على النبي من المستمعين للقرآن","answer":"الجواب:\n\n.. لا أعلم لها أصلًا، وإنما المشروع أن ينصتوا، وأن يجدوا، ويتأملوا وقت القراءة؛ لأن الله قال: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا [الأعراف:204].","link":"https://binbaz.org.sa/fatwas/2577/حكم-التكبير-او-الصلاة-على-النبي-من-المستمعين-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1072.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6712,"question":"لقد تكلمتم عن أحكام الأعياد المبتدعة، فما رأيكم فيما يحدث في وقتنا الحاضر من اليوم الوطني، والاحتفال به، والتهنئة له، أفتونا جزاكم الله خيرًا؟","title":"حكم الاحتفال بالأعياد الوطنية","answer":"الجواب: هذا اليوم الوطني هو من التشبه بأعداء الله، الأيام الوطنية هو من التشبه، وقد وقع عن حسن نية، واجتهاد، ولكنه فيما يظهر لنا لا يشرع، وليس مما ينبغي، بل هو فيه تشبه لأعداء الله، وإن لم تقصد العبادة، أما لو قصد العبادة؛ يكون بدعة، لكن إذا لم تقصد العبادة، وإنما قصد بذلك التهانئ، وإظهار ما أنشأته الدولة، وما بذلته الدولة، فهذا يكون معتبرًا من جنس الأيام الأخرى التي يحدثها اليهود، والنصارى، وأشباههم للذكرى، أو لأسباب أخرى، فلا ينبغي التشبه بهم، لا في هذا، ولا في غيره.","link":"https://binbaz.org.sa/fatwas/2592/حكم-الاحتفال-بالاعياد-الوطنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1088.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6715,"question":"قلتم سماحتكم في حديثكم أن الاحتفال بمولد النبي -عليه الصلاة والسلام- بدعة، فما تقول في الأدلة التي استشهد بها من يقيمون الموالد من الكتاب، والسنة، والآثار، والاستنتاجات العقلية؟","title":"الرد على من قال بجواز الاحتفال بالموالد","answer":"الجواب: كل ما ذكروه لا حجة لهم فيه، بل هو حجة عليهم، وقد كتب في هذا محمد علوي المالكي المعروف، كتابًا صغيرًا جمع فيه فوق العشرين، زعم أنها أدلة، وهي كلها تدل على عكس ما قال، كلها تلبيس، وعدم إيضاح للحق، ولكن الهوى يعمي، ويصمي، فهي حجة عليه لا له، وعلى مقتضى أدلته أن كل اجتماع يكون فيه تعظيم للنبي، أو للأنبياء يكون جائزًا، فعلى هذا على قوله، وما سرد من أدلته أن جميع الأيام، والليالي لو جعلت أعيادًا للأنبياء، ولمحمد ﷺ يقرأ فيها، ويذكر فيها موالدهم، لكان ذلك من ذكرهم، ومن تعظيمهم، ومن الصلاة عليهم، كما أنها تكون الأيام، والليالي كلها أعيادًا، وهذا كله باطل، ولا حجة فيه، لا في أول أمره، ولا في آخره، وجميع كُتيبه الذي ذكر، كلها حجة عليه، وقد أوضح الذين ردوا عليه ذلك، وبينوا بطلان ما قال، ونسأل الله له الهداية، فقد لبس عليه، ولبس على أمثاله من الناس، ونسأل الله أن يمن عليهم بالهداية، ويردهم إلى الصواب. ولو كان خيرًا هذا؛ لسبقنا إليه خير القرون  يعني نحن أعلم من أبي بكر، وعمر، وعثمان، وعلي؟ ونحن أعلم من أصحاب النبي ﷺ؟ ونحن نهدى لشيء أفضل مما اهتدوا إليه، فيكون زمانهم محرومًا من هذا الخير، ونحن اهتدينا إليه؟ هذا محال! وقد قال النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة فهم كانوا على الحق في القرن الأول، والثاني، والثالث، كانوا على الحق بلا ريب، وليس عندهم مولد، فكانوا حرموا من هذا الخير، وحرموا من هذا الفضل، وحصل عليه من بعدهم ممن هو أجهل، وأقل فضلًا منهم، وحرم فضله الأولون السابقون، والأخيار، وفاز به المتأخرون، أو الأولون جهلوه، وصار المتأخرون أعلم منهم؟! هذا أيضًا محال، فمن زعم: أن الآخرين أعلم من الأولين؛ فقد ضل ضلالًا بعيدًا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2593/الرد-على-من-قال-بجواز-الاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1089.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6753,"question":"عرفنا من كلام الشيخين مدى حرمة هذه البدعة، ومدى إثمها، فهل من قام بالمولد النبوي بقصد أن يجمع المسلمين لتبيين الدين الصحيح، لا لإشاعة هذه البدعة، بأن يكون مضيقًا عليه، لا يستطيع أن يجمع المسلمين، ويعلمهم دينهم إلا في مثل هذه التجمعات، وهو يعلم بدعيتها، وعدم شرعيتها كذلك، من جاء من عامة المسلمين يعلم ذلك؟","title":"حكم حضور الموالد لبيان الحق والتحذير منها","answer":"الجواب: إذا حضرها لهذا القصد؛ ليبين أمرها، وأنها بدعة، ويبين للناس ما في نفسه من أشياء منكرة، يحذرهم منها ... إلى فعلها، ويبين لهم أن هذه بدعة، وأنه لا يجوز الاحتفال؛ فهذا طيب، أما أنه يقيم الاحتفال لأجل الميتين لا، ما يقيمه لأجل الميتين، يخطب الناس في المساجد، وفي الجمع، ويبين للناس مما شرع الله سبحانه، ومما حرم، لكن إذا حضرها، وإذا أقامها غيره، وجاء إليهم، ونصحهم، وعلمهم أن هذا بدعة؛ فهذا مأجور.","link":"https://binbaz.org.sa/fatwas/2640/حكم-حضور-الموالد-لبيان-الحق-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1136.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6764,"question":"عرفنا من كلام الشيخين مدى حرمة هذه البدعة، ومدى إثمها، فهل من قام بالمولد النبوي بقصد أن يجمع المسلمين لتبيين الدين الصحيح، لا لإشاعة هذه البدعة، بأن يكون مضيقًا عليه، لا يستطيع أن يجمع المسلمين، ويعلمهم دينهم إلا في مثل هذه التجمعات، وهو يعلم بدعيتها، وعدم شرعيتها كذلك، من جاء من عامة المسلمين يعلم ذلك؟","title":"حكم حضور الموالد لبيان الحق والتحذير منها","answer":"الجواب: إذا حضرها لهذا القصد؛ ليبين أمرها، وأنها بدعة، ويبين للناس ما في نفسه من أشياء منكرة، يحذرهم منها ... إلى فعلها، ويبين لهم أن هذه بدعة، وأنه لا يجوز الاحتفال؛ فهذا طيب، أما أنه يقيم الاحتفال لأجل الميتين لا، ما يقيمه لأجل الميتين، يخطب الناس في المساجد، وفي الجمع، ويبين للناس مما شرع الله سبحانه، ومما حرم، لكن إذا حضرها، وإذا أقامها غيره، وجاء إليهم، ونصحهم، وعلمهم أن هذا بدعة؛ فهذا مأجور.","link":"https://binbaz.org.sa/fatwas/2640/حكم-حضور-الموالد-لبيان-الحق-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1136.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6776,"question":"نهتم كثيرًا بقضية الاحتفال بعيد المولد النبوي، والردود عليه، بينما الاحتفال باليوم الوطني، وغيره من الأيام في البلاد الإسلامية تجري على ما هي عليه دون اعتراض، هل لأنها احتفالات سياسية، والمولد ديني، كل هذه الاحتفالات لا شك باطلة، فما تعليق سماحتكم؟","title":"الفرق بين الاحتفال بالمولد النبوي واليوم الوطني","answer":"الجواب: التعليق على هذا: أن الأيام الوطنية هذا تقليد للكفرة، وأشباه الكفرة، وليس من باب الدين، فهو أسهل من جهة العواقب، وهو لا شك، ينبغي تركه، ولا ينبغي فعله؛ لأنه تقليد للكفرة، ولا ينبغي تقليدهم، ولا التشبه بهم، ولكن الموالد التي تقام للأنبياء، أو الأولياء خطرها أعظم، وشرها أكبر؛ لأنها تشبه العبادة، تشبه الدين تشبه الغلو، وتفضي إلى الشرك الأكبر، والمعاصي الكثيرة، ولهذا اهتم بها أهل العلم أكثر من اهتماهم بالأيام الوطنية السياسية، التي يفعلها الملوك، والرؤساء، مع أن هذا قد بذل.. تكلمنا فيه بما يلزم، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2647/الفرق-بين-الاحتفال-بالمولد-النبوي-واليوم-الوطني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1143.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6853,"question":"من هم الأولياء؟ نريد شرحًا مفصلًا؛ لأن في بعض البلاد المجاورة يجب عليك أن تأخذ طريقة من الشيخ حتى يكون واسطة بينك وبين الله، هذا على حد قولهم؟","title":"حقيقة الأولياء","answer":"الجواب: الأولياء هم أهل الإيمان، وأنت منهم إذا كنت مؤمنًا، فأنت منهم، أولياء الله هم أهل الإيمان، والتقوى، قال تعالى: أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ  ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:62، 63]، وقال سبحانه: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [الأنفال:34]. فأولياء الله هم أهل الإيمان والتقوى الذين وحدوا الله، واستقاموا على دينه، فأدوا فرائضه، وتركوا مناهيه، هؤلاء هم أولياء الله، وهم أهل الإيمان، وهم أهل التقوى، وقد تقع منهم معصية، ثم يتوبون، فيتم إيمانهم، قد يقع من الولي المعصية، أو المؤمن، ثم ينتبه، فيتوب؛ فيتوب الله عليه، والذي لم يتب كان مؤمنًا ناقصًا، ووليًا ناقصًا، وإذا تاب تاب الله عليه.  وأما ما تقوله الصوفية: إن الولي هو الذي يكون عنده خوارق، وعنده شعوذة، وعنده دعاوى طويلة، عريضة حتى يقال: إنه شيخ الطريقة، وحتى يقلد، وحتى يتبع فيما يريد، وفيما يهوى، وحتى ينسى كتاب الله، وسنة رسوله -عليه الصلاة والسلام- هذا من عمل الشيطان، هذا من الضلالات، والبدع، والأهواء المنكرة -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/2744/حقيقة-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1244.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6939,"question":"ما حكم الصلاة في مسجد به قبر؟ وما حكمه إذا كان القبر خلف المسجد؟ كما نسألكم عن حكم إهداء الحلوى بمناسبة مولد الرسول ﷺ؟","title":"ما حكم الصلاة في مسجد به قبر لكنه خلف المسجد؟","answer":"الجواب: الصلاة في المساجد التي فيها قبور ما تجوز، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة -رضي الله عنها-: يحذر ما صنعوا، قالت: ولولا ذلك؛ لأبرز قبره، يعني في البقيع، غير أنه خشي أن يتخذ مسجدًا.  وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلم في الصحيحين عن جندب بن عبدالله البجلي. الرسول ﷺ حذر من هذا، وبين أن من قبلنا فعلوا هذا المنكر اتخذوا قبور أنبيائهم، وصالحيهم مساجد ثم نهانها، وحذرنا عن ذلك.  فالصلاة في المساجد التي بنيت على القبور لا تصح، سواء كان القبر في مقدمها، أو عن يمينه، أو شماله، أو خلفه، أما إذا كان خارج المسجد، والمسجد خارج عنه؛ تصح الصلاة. أما ما دام المسجد بني على القبر، سواء جعل أمام المصلين، أو عن يمينهم، أو عن شمالهم، أو خلفهم، فلا يصلى فيه، وإذا كان القبر هو الجديد؛ ينبش، ويخرج رفات القبر إلى المقبرة العامة، ويسوى أرضه، أما إذا كان المسجد هو الجديد، بني على القبر؛ يهدم، ويزال، وتبقى القبور ضاحية للشمس، كما هي ضاحية في عهد النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/2869/ما-حكم-الصلاة-في-مسجد-به-قبر-لكنه-خلف-المسجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1317.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":6945,"question":"في الجنوب إذا مات ولد، أو بنت، أو ماتت بنت، وهو صغير السن؛ يتصدقون على نيته، مع العلم أنه في شهور، ولم يبلغ المتوفي في عمره سنة، وهذه الصدقة لها صفة خاصة، فمثلًا يتصدقون بهدبة.. وهو جلد، وبعض الأشياء العينية، أفتونا باركم الله فيكم؟","title":"حكم الصدقة عن الطفل المتوفى","answer":"الجواب: الصغار لا .. عليهم، الذين ماتوا قبل الحلم لا ذنب عليهم، لكن إذا تصدق عنه أهله؛ فهي تزيده خيرًا، الصدقة تزيده خيرًا، تنفعه، ولو كان صغيرًا، لكن إذا كانت الصدقة على طريقة خاصة، يتعبدون بها، نوع معين يفعلونه في يوم معين؛ فهي بدعة. أما صدقة مطلقة، مثل ما يتصدقون على آبائهم، وأمهاتهم، ويتصدقون على أولادهم، متى تيسرت الصدقة، في أي وقت، في أي مكان؛ لا بأس، أما يخص هذا بيوم معين، أو دراهم معينة، أو طعام معين، هذا يكون بدعة.","link":"https://binbaz.org.sa/fatwas/2875/حكم-الصدقة-عن-الطفل-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1323.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":6946,"question":"هل تعتبر أعياد الميلاد نوعًا من البدع؟ وكذلك الحفلات في أثناء المناسبات؟","title":"حكم الاحتفال بعيد الميلاد","answer":"الجواب: الأعياد كل ما يتكرر في السنة، أو في الشهر، أو في الأسبوع بنية العبادة، والتقرب إلى الله، هذه البدع، فالموالد من هذا الباب.","link":"https://binbaz.org.sa/fatwas/2876/حكم-الاحتفال-بعيد-الميلاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1324.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6947,"question":"ما الفرق بين البدعة الحسنة، والسيئة؟ وكيف نعرف كل منهما؟","title":"حكم تقسيم البدع إلى حسنة وسيئة","answer":"الجواب: الصواب: أن البدعة كلها سيئة، كلها ضلال، ما فيها بدعة حسنة، يقول النبي ﷺ: كل بدعة ضلالة أما قول بعض العلماء: أنها قسمان: حسنة، وسيئة، هذا قول من كيسهم، ما عليه دليل. الصواب: أنه ليس هناك بدعة حسنة، كلها ضلالة، وما سموه حسنة فليس من البدع، بل هو أمر جاء به الشرع، مثل: تنقيط القرآن، وتشكيله؛ لأجل لا يغلط الناس فيه، هذا مما أمرنا الله به، أمرنا بحفظ القرآن، وضبطه. ومثل إقامة المدارس للدراسة، وإن كان ما هي في عهد النبي ﷺ لكن أقيمت للحاجة إليها، وبنيت المساجد على طريقة غير طريقة النبي ﷺ النبي بناه بالجذوع، وبناه الناس بعده بالحجر، أو بغير ذلك مثل ما بناه عثمان، لا بأس بهذا، ليس هذا من البدع، هذا من باب العناية بأمر الدين، وإقامة الشعائر على الوجه الأكمل مهما أمكن.","link":"https://binbaz.org.sa/fatwas/2877/حكم-تقسيم-البدع-الى-حسنة-وسيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1325.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7008,"question":"ما حكم الصلاة خلف من يذهب إلى قبور الصالحين؛ للتبرك بها، وتلاوة القرآن في الموالد وغيرها بأجر على ذلك؟","title":"حكم الصلاة خلف من يذهب إلى قبور الصالحين","answer":"الجواب: \n\nهذا فيه تفصيل، إن كان مجرد الاحتفال بالموالد من دون شرك، هذا مبتدع، فينبغي ألا يكون إمامًا، وصلاته صحيحة.\n\nوأما إذا كان يدعو الأموات، ويستغيث بالأموات، ويدعوهم: يا رسول الله، يا فلان، يا سيدي البدوي، يا سيدي حسين، يا فلان، المدد المدد، يا سيدي عبدالقادر، هذا مشرك، ما يصلى خلفه -نسأل الله العافية-.\n\nأما إذا كان بدعة، يحضر المولد، ولكن ما يأتي بالشرك، أو يقرأ القرآن عند القبور، ولا يأتي بشرك، هذا يكون عنده بدعة، يعلم، يوجه، وصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/2947/حكم-الصلاة-خلف-من-يذهب-الى-قبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1397.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7018,"question":"ما حكم الصلاة خلف من يذهب إلى قبور الصالحين؛ للتبرك بها، وتلاوة القرآن في الموالد وغيرها بأجر على ذلك؟","title":"حكم الصلاة خلف من يذهب إلى قبور الصالحين","answer":"الجواب: \n\nهذا فيه تفصيل، إن كان مجرد الاحتفال بالموالد من دون شرك، هذا مبتدع، فينبغي ألا يكون إمامًا، وصلاته صحيحة.\n\nوأما إذا كان يدعو الأموات، ويستغيث بالأموات، ويدعوهم: يا رسول الله، يا فلان، يا سيدي البدوي، يا سيدي حسين، يا فلان، المدد المدد، يا سيدي عبدالقادر، هذا مشرك، ما يصلى خلفه -نسأل الله العافية-.\n\nأما إذا كان بدعة، يحضر المولد، ولكن ما يأتي بالشرك، أو يقرأ القرآن عند القبور، ولا يأتي بشرك، هذا يكون عنده بدعة، يعلم، يوجه، وصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/2947/حكم-الصلاة-خلف-من-يذهب-الى-قبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1397.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7039,"question":"في بعض البلاد الإسلامية يقنتون في الركعة الثانية وبعد الاعتدال من الركوع في صلاة الفجر من كل يوم وبصفة مستمرة، هل هذا مطابق للسنة؟ وإنني أحضر للصلاة معهم في بعض الأوقات، فهل هذا يؤثر في صلاتي؟","title":"هل الاستمرار على القنوت في الفجر من السنة؟","answer":"الجواب:\n\nهذا ذهب إليه بعض العلماء كالشافعي رحمه الله وجماعة وظنوا واعتقدوا أنه سنة لأحاديث ضعيفة وردت في ذلك، والصواب: أنه ليس بسنة دائمة بل يفعل عند الحاجة، عند حاجة هجوم العدو أو الدعاء على العدو، بعض الأحيان النبي ﷺ فعله تارة وتركه تارة عليه الصلاة والسلام وهو القنوت في صلاة الفجر. \n\nفالذي ينبغي أنه لا يداوم عليه، ولكن إذا كان مع جماعة يداومون يصلي معهم لا يخلي الصلاة، يصلي معهم وينصح الإمام، يقول له: الأفضل والسنة لك أنك تفعله تارة إذا كان يدعو على قوم من الكفار، يقول سعد بن طارق بن أشيم الأشجعي يقول: سألت أبي طارق -وأبوه من الصحابة- ...\n\nلكن إذا كان يدعو على الشيوعية والكفرة، ويدعو الله للمجاهدين الأفغان ونحوهم أن ينصرهم الله هذا من القنوت في النوازل، يعني هذا يسمى قنوات النوازل عند الحاجة، وإن فعله في المغرب أو في العشاء صح.","link":"https://binbaz.org.sa/fatwas/3009/هل-الاستمرار-على-القنوت-في-الفجر-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1416.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7091,"question":"هل ثبت حديث صحيح في فضل صيام يوم الخامس عشر من شعبان؟ وهل ورد حديث صحيح في فضل قيام تلك الليلة؟","title":"حكم تخصيص ليلة النصف من شعبان ويومها بالصيام والقيام","answer":"الجواب:\n\nلا، تخصيص يوم النصف من شعبان بالعبادة، أو الصيام، أو ليلة النصف لا أصل له، بل هو بدعة، الصحيح من أقوال العلماء أنه بدعة، والأحاديث التي فيه ضعيفة، ليلة النصف من شعبان كلها ضعيفة، وبعضها موضوع، لا صحة لها.","link":"https://binbaz.org.sa/fatwas/3103/حكم-تخصيص-ليلة-النصف-من-شعبان-ويومها-بالصيام-والقيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1480.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7123,"question":"الأمل كبير في سماحتكم في أن تشفي حيرة الكثيرين، خاصة من الإخوة في مصر، وذلك في موضوع رأس الحسين بن علي  هل هو فعلًا في مصر، أو في العراق جثته ورأسه؟ وما حكم زيارة ضريح السيدة زينب، أو الحسين، أو غيرهما من قبل الرجال فقط؟","title":"حقيقة وجود رأس الحسين بن علي في مصر","answer":"الجواب:\n\nالمعروف عند المحققين أن الموجود في مصر لا حقيقة له، لا رأس ولا غيره، ليس هناك حسين في مصر، وإنما هو غلط في وجود قبر الحسين هناك، لا أصل له، وإنما الحسين دفن في العراق، وقيل: إن رأسه كان في الشام عند يزيد -والله أعلم-. \n\nالمقصود: لا أصل له في مصر، ووجود القبور في مصر التي تعظم من البلايا العظيمة على مصر وأهلها، لا قبر الحسين ولا قبر البدوي، ولا قبر السيدة زينب، ولا السيدة نفيسة، ولا غيرهم من هؤلاء المعظمين، جروا على مصر شرًا كثيرًا بالغلو فيها، ودعوتها من دون الله، والاستغاثة بها، وطلبها المدد حتى وقع العامة في الشرك الأكبر -نعوذ بالله-.\n\nفالواجب على علماء مصر جميعًا -أعني علماء السنة، علماء الحق- الواجب عليهم أن يتقوا الله، وأن يشمروا عن ساعد الجد، وعن الرغبة فيما عند الله، حتى يبصروا الناس، يبصروا العامة بهذا الشرك الأكبر الذي يفعل عند القبور، وعند الطواف، ودعائها، والاستغاثة بها، وقد تواترت عندنا أن حتى صاحب التاكسي إذا مر وقف عند القبر يقول: المدد المدد، ثم يمشي، هذا مما بلغنا وتواتر عندنا. \n\nفالمقصود: أن هذه بلايا عظيمة وقعت في مصر، ووقعت في الشام، ووقعت في الأردن، ووقعت في العراق، وفي بلدان كثيرة.\n\nفالواجب على أهل العلم أن ينشطوا غاية النشاط في نهي العامة عن هذا الشر، وتبصيرهم بالدين كتابة في الصحف، وكتابة في المؤلفات الصغيرة التي تروج بينهم، وفي خطب الجمعة، وفي الخطب التي تكون في المناسبات، وفي المساجد حتى يكثر هذا الأمر بينهم، وحتى يتعلم الجاهل وحتى يعلم بعضهم بعضًا، ويتداولوا هذه الكلمات، وهذه النصائح بينهم.\n\nوهكذا في التسجيل، يسجل أشرطة توزع بينهم حتى يكثر ذلك فيهم، وحتى ينتهوا عن هذا الباطل العظيم، والشرك الوخيم -نعوذ بالله- نسأل الله للعامة الهداية، وللعلماء التوفيق لأداء الواجب.","link":"https://binbaz.org.sa/fatwas/3153/حقيقة-وجود-راس-الحسين-بن-علي-في-مصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1511.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":7238,"question":"هل في الدين بدعة مباحة؟ وما معنى قول عمر: نعمت البدعة هذه؟","title":"حكم القول بوجود بدعة مباحة في الدين","answer":"الجواب:\n\nما في الدين بدعة مباحة، ولا بدعة مكروهه، بل كلها ضلالة، يقول النبي ﷺ: وكل بدعة ضلالة، هذا كلام رسول الله ﷺ، فليس في الدين بدعة، لا مباحة، ولا مستحبة، بل كل البدع في الدين ضلالة.\n\nوأما ما يسميه بعض الناس بدعًا في المدارس، وفي بناء المنارات، هذه ليست بدعًا، هذه أمور دعت إليها الحاجة؛ فهي قربة، فالمنارة لأجل يعرف الصوت بالأذان حتى يسمعه الناس، والمدارس لأجل تعليم القرآن والسنة، والأربطة لأجل الناس الفقراء، فليس هذه من البدع، بل هذه من الحسنات، والخيرات، والقربات. \n\nوأما قول عمر : (نعمت البدعة) فالمراد به من حيث اللغة، فإنه لما جمعهم على إمام واحد في التراويح، وكان النبي ﷺ فعل ذلك مرات لعدة ليالي، ثم ترك، وخاف أن تفرض عليهم -عليه الصلاة والسلام- فلما توفي النبي ﷺ وتوفي أبو بكر، واستخلف عمر؛ رأى أن يجمعهم على إمام واحد؛ لأنهم يصلون أوزاعًا في المسجد، هذا يصلي لأربعة، وهذا يصلي لثلاثة، وهذا يصلي لنفسه، فرأى أن يجمعهم فجمعهم، كما جمعهم النبي ﷺ وصلى بهم؛ لأنه قد أمن الآن الفرض، وانقطع الوحي، فلهذا جمعهم  وقال: (نعمت البدعة) يعني من حيث اللغة، لأن البدعة في اللغة ما كان على غير مثال سابق، فهذه الصلاة التي جمعهم عليها، واستمروا عليها بدعة من حيث اللغة، لا من حيث الدين، فإن الرسول قد فعلها، ودعا إليها ﷺ وصلى بهم عدة ليال، فلم تكن بدعة، بل هي قربة، وطاعة.","link":"https://binbaz.org.sa/fatwas/3303/حكم-القول-بوجود-بدعة-مباحة-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1628.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7265,"question":"دبلة الخطوبة؟","title":"حكم دبلة الخطوبة","answer":"الجواب:\n\nالدبلة ما لها أصل، غلط، ولا وجه لها، هذه تلقوها عن مشابهة أعداء الله، الشبكة يسمونها الشبكة، هذه ما لها أصل.","link":"https://binbaz.org.sa/fatwas/3330/حكم-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1651.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":7282,"question":"الحكم في قطع الصلاة بالنسبة للكل، سواء كانت امرأة، أو رجلًا؟","title":"حكم قطع الصلاة للضرورة","answer":"الجواب:\n\nإذا دعت الحاجة نعم، إذا دعت الحاجة من قتل إنسان، أو موت إنسان في خطر، أو حريق، أو أشباهه أشياء -يعني مهمة- يخشى من وقوعها؛ فلا بأس أن يقطع ليستبرء الحاجة، ويعرف الأمر، ثم يعود إلى الصلاة.","link":"https://binbaz.org.sa/fatwas/3348/حكم-قطع-الصلاة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1669.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":7437,"question":"ما هو فضل صيام سبعة وعشرين من رجب وليلة النصف من شعبان؟ وهل هناك حديث عن الرسول يحث المؤمنين على صيام تلك الأيام؟ وهل صيام الأيام الثلاثة الأولى من شهر رجب أو شهر شعبان أو شوال وفضلها أكبر من مثيلاتها في الأشهر الأخرى؟","title":"حكم صيام السابع والعشرين من رجب والنصف من شعبان","answer":"الجواب: هذا لا أصل له، فإن بعض أهل العلم يزعم أن سبعة وعشرين رجب أنها ليلة الإسراء والمعراج، وهذا لا أصل له، والحديث المروي في ذلك غير صحيح، فليس لها خصوصية، وليس لصيام ثلاثة أيام من أول رجب أو من أول شعبان أو من أول شوال خصوصية.  إنما شرع صيام ثلاثة من كل شهر عام لكل الشهور، يشرع للمؤمن أن يصوم ثلاثة أيام من كل شهر، لا فرق بين رجب وغيره، كذلك ستة أيام من شوال جاء الشرع بها أيضًا، ما هي بثلاث ستة أيام من شوال، أما الثلاث فهي عامة للشهور كلها، وأما تخصيص صيام سبعة وعشرين من رجب، أو ثلاثة من أوله، أو ليلة النصف من شعبان تقام وحدها هذا لا أصل له، جاء فيه أحاديث غير صحيحة، ليلة النصف من شعبان ليست بصحيحة ولا يعتمد عليها.","link":"https://binbaz.org.sa/fatwas/3542/حكم-صيام-السابع-والعشرين-من-رجب-والنصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1847.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7450,"question":"نريد أن نخبركم أنه سوف تقام غدًا الجمعة في جامع مصنع الجبس في طريق الخرج صلاة الغائب على فضيلة الشيخ إحسان إلهي ظهير -رحمه الله- نرجو منكم ومن الحاضرين الترحم عليه، والدعاء له بالمغفرة والرحمة وذكر شيئًا من سيرته، والتعريف بحياته للحضور، فالغالب فيهم لا يعرفه جيدًا؟","title":"نبذة عن الشيخ إحسان إلهي ظهير","answer":"الجواب: غفر الله له، ورحمنا وإياه، أخونا الشيخ حافظ إحسان معروف عند خواص أهل العلم، فله مؤلفات كثيرة في الرد على الشيعة، والرد على الوثنية، والرد على غيرهم من طوائف الكفر والضلال، فهو مجاهد -رحمه الله- وقد تخرج من الجامعة الإسلامية في المدينة، واشتغل بالدعوة إلى الله في باكستان، وفي غيرها، وهو يتجول للدعوة إلى الله والتعليم، والرد على خصوم الإسلام، فله مآثر جميلة، ومؤلفات قيمة نافعة، فرحمه الله وأكرم مثواه، يصلى عليه هنا، وإذا صلي عليه في مكة فلا بأس.","link":"https://binbaz.org.sa/fatwas/3535/نبذة-عن-الشيخ-احسان-الهي-ظهير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1839.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":7575,"question":"الرسالة هذه من المستمع عبد الله محمد بكر من جامعة الرياض كلية الهندسة، يقول في رسالته هذه: أود أن أشكركم على هذا البرنامج الذي أصبح والحمد الله نوراً يضيء للجميع الطريق، وأرجو أن تزيدوا من وقته، كما أرجو توجيه هذا السؤال إلى فضيلة الشيخ: عبد العزيز بن باز ، يقول: لقد سمعت منكم مؤخراً بأن المولد النبوي الشريف من المنكر والبدع، وأود أن أقول وأسأل هنا: إن في المولد النبوي الشريف يجتمع الناس على الأخوة والتقوى، وقراءة شيء من القرآن الكريم والسنة النبوية الشريفة، وقراءة شيء من الشعر الذي قيل قديماً إما يمدح الإسلام أو الرسول العظيم، وهذا كل ما يحدث، وليس فيه ذلك ما يعارض الشريعة الإسلامية، أرجو توضيح ذلك ولكم كل تقديري واحترامي، ورعاكم الله وسدد خطاكم وجعلكم ذخراً للإسلام والمسلمين؟","title":"هل يجوز الاحتفال بالمولد النبوي بقراءة القرآن والمدائح النبوية؟","answer":"الجواب: لا ريب أن الاحتفال بالمولد النبوي على صاحبه أفضل الصلاة والسلام قد يقع فيه شيء مما ذكره السائل بالنسبة إلى أهل العلم وأهل البصائر، ولكن ينبغي أن يعلم أننا عبيد مأمورون لا مشرعون، علينا أن نمتثل أمر الله وعلينا أن ننفذ شريعة الله، وليس لنا أن نبتدع في ديننا ما لم يأذن به الله، يجب أن نعلم هذا جيداً، الله سبحانه يقول: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]. \nويقول المصطفى عليه الصلاة والسلام في الحديث الصحيح الذي رواه الشيخان عن عائشة رضي الله عنها: من أحدث في أمرنا هذا ما ليس منه فهو رد، يعني: فهو مردود على من أحدثه، وفي لفظ آخر عند مسلم: من عمل عملاً ليس عليه أمرنا فهو رد. \nوجاء في هذا المعنى أحاديث كثيرة تدل على تحريم البدع، وأن البدع هي المحدثات في الدين، وكان النبي يقول في خطبته عليه الصلاة والسلام: أما بعد .. فإن خير الحديث كتاب الله، وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلالة. \nوتعلمون أيها المستمعون من أهل العلم أن الرسول عليه الصلاة والسلام عاش بعد النبوة ثلاثة وعشرين سنة ولم يحتفل بمولده عليه الصلاة السلام، ولم يقل للناس: احتفلوا بالمولد، بدراسة السيرة أو بغير ذلك، ولاسيما بعد الهجرة فإنها وقت التشريع كمال التشريع، فمات ﷺ ولم يقل شيئاً من ذلك. \nوأما حديث: أنه سئل عن صوم يوم الإثنين؟ فقال: ذلك يوم ولدت فيه وبعثت فيه هذا لا يدل على الاحتفال بالموالد كما يظن بعض الناس، وإنما يدل على فضل يوم الإثنين وأنه يوم شريف؛ لأنه أوحي إلى النبي ﷺ فيه، ولأنه ولد فيه عليه الصلاة والسلام، ولأنه يوم تعرض فيه الأعمال على الله ، فإذا صامه الإنسان لما فيه من المزايا هذا حسن، أما أن يزيد شيئاً غير ذلك هذا ما شرعه الله، إنما قال النبي ﷺ: إنه يوم ولدت فيه لبيان فضل صومه، ولما سئل في حديث آخر عن صوم الإثنين والخميس -أعرض عن الولادة- وقال في يوم الخميس والإثنين: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم، وسكت عما يتعلق بالمولد، فعلم بذلك أن كونه يوم المولد جزء من أسباب استحباب صومه مع كونه تعرض فيه الأعمال على الله، وكونه أنزل عليه الوحي فيه، فهذا لا يدل على الاحتفال بالموالد ولكن يدل على فضل صيام يوم الإثنين، وأنه يصام لهذه الأمور؛ لكونه ولد فيه النبي ﷺ، ولكونه أنزل عليه الوحي فيه، ولأنه تعرض فيه الأعمال على الله عز وجل. \nولو كان الاحتفال بالموالد أو بمولده عليه الصلاة والسلام أمراً مشروعاً أو مرغوباً فيه لما سكت عنه النبي ﷺ وهو المبلغ عن الله، وهو أنصح الناس، ولا يجوز أن يظن به أنه يسكت عن أمر ينفع الأمة وينفعه عليه الصلاة والسلام ويرضي الله عز وجل، وهو أنصح الناس، هو ليس بغاش للأمة وليس بخائن ولا كاتم، فقد بلغ البلاغ المبين عليه الصلاة والسلام، وأدى الأمانة، ونصح الأمة، وكل شيء لمن يكن في وقته مشروعاً، فلا يكون بعد وقته مشروعاً، فالتشريع من جهة الرسول صلى الله عليه وسلم، فيما أوحى الله إليه جل وعلا، وصحابته مبلغون عنه، ويحملون عنه ما بلغهم به، فهو لم يبلغ الناس أن الاحتفال بمولده مطلوب، لا فعلاً ولا قول، وصحابته ما فعلوا ذلك، ولا أرشدوا إليه لا بأفعالهم ولا بأقوالهم، وهم أحب الناس إلى النبي ﷺ، هم أحب الناس إلى النبي ﷺ هم أعلم الناس بالسنة، وهم أفقه الناس، وهم أحرص الناس على كل خير فلم يفعلوه، ثم التابعون لهم كذلك، ثم أتباع التابعين حتى مضت القرون المفضلة، فكيف يجوز لنا أن نحدث شيئاً ما فعله هؤلاء الأخيار؟ \nما فعله الرسول ﷺ، ولا أرشد إليه، ولا فعله صحابته رضي الله عنهم، ولا أتباعهم بإحسان، القرون المفضلة، وإنما أحدثه بعض الشيعة بعض الرافضة ، أول من أحدثه شيعة بني عبيد القداح شيعة الفاطميين ، الذين قال فيهم شيخ الإسلام ابن تيمية رحمه الله: ظاهرهم الرفض وباطنهم الكفر المحض، هم الفاطميون الذين ملكوا المغرب ومصر والشام على رأس المائة الثانية وما بعدها إلى القرن الخامس وأول السادس. \nفالمقصود: أن هؤلاء هم الذين أحدثوا الأعياد، والاحتفال بالموالد، كما ذكر جماعة من المؤرخين: أحدثوا ذلك في المائة الرابعة، ثم جاء بعدهم من أحدث هذه الأشياء، أحدثوها للنبي ﷺ، و للحسن ، و الحسين ، و فاطمة ، وحاكمهم، فالمقصود أنهم هم أول من أحدث هذه الموالد، فكيف يتأسى بهم المؤمن في بدعة أحدثها الرافضة ، هذا من البلاء العظيم. \nثم أمر آخر وهو: أنه قد يقع في هذه الاحتفالات في بعض الأحيان في بعض البلدان شرور كثيرة، قد يقع فيها من الشرك بالله، والغلو في النبي ﷺ، ودعائه من دون الله، والاستغاثة به، ومدحه بما لا يليق إلا بالله كما في البردة، فإن صاحب البردة قال فيها:\nيا أكرم الخلق ما لي من ألوذ به سواك عند حلول الحادث العمم\nإن لم تكن في معادي آخذاً بيدي فضلاً وإلا فقل يا زلة القدم\nفإن من جودك الدنيا وضرتها ومن علومك علم اللوح والقلم \nفأي شيء أبقى هذا لله عز وجل؟ هذا الغلو العظيم، وكثير من الناس يأتون بهذه القصيدة في احتفالاتهم وفي اجتماعاتهم، وهي قصيدة خطيرة في هذا الشرك العظيم. \nالمقصود: أن كثيراً من الاحتفالات في بعض البلدان يقع فيها الشرك الأكبر، بسبب الغلو في النبي صلى الله عليه وسلم والغلو في مدحه، وقد قال عليه الصلاة والسلام: لا تطروني كما أطرت النصارى ابن مريم إنما أنا عبد، فقولوا: عبد الله ورسوله، ويقع فيها في بعض الأحيان أيضاً منكرات أخرى من شرب الخمور، ومن الفواحش والزنا، ومن اختلاط الرجال بالنساء، هذا يقع في بعض الأحيان، وقد أخبرنا بهذا من لا نتهمه، وإن كانت بعض الاحتفالات سليمة من هذا. \nوالحاصل: أنه بدعة مطلقة حتى ولو كان على أحسن حالة، لو كان ما فيه إلا مجرد قراءة السيرة، والصلاة على النبي ﷺ فهو بدعة بهذه الطريقة أن يحتفل به في أيام مولده في ربيع الأول على طريقة خاصة كل سنة، أو في يوم يتكرر يعتاد باسم الاحتفال بمولد النبي ﷺ، هذا يكون بدعة، لأن: ليس في ديننا هذا الشيء، وأعيادنا عيدان: عيد النحر، وعيد الفطر، وأيام النحر ويوم عرفة، هذه أعياد المسلمين، فليس لنا أن نحدث شيئاً ما شرعه الله عز وجل. \nوإذا أراد الناس أن يدرسوا سيرته فيدرسوها بغير هذه الطريقة، يدرسونها في المساجد وفي المدارس، سيرة النبي ﷺ مطلوبة، تجب دراستها والتفقه فيها، تدرس في المدارس، في المعاهد، في الكليات، في البيوت، في كل مكان لكن بغير هذه الطريقة، بغير طريقة الاحتفال بالمولد، هذا شيء وهذا شيء، فيجب على أهل العلم التنبه لهذا الأمر، وعلى طالب العلم أن يتنبه لهذا الأمر، وعلى محب الخير أن يتنبه لهذا الأمر، هذه السنة خير وسلامة، والبدعة كلها شر وبلاء، رزق الله الجميع العافية والهدى، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/4581/هل-يجوز-الاحتفال-بالمولد-النبوي بقراءة-القران-والمداىح-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_017/01702.mp3","categories":["البدع والمحدثات"]},{"id":7576,"question":"الرسالة الأخيرة في هذا اللقاء وردتنا من إحدى المدرسات، وهي المرسلة (ن) عبد الحق من مكة من المسفلة، تقول: أنا فتاة أقوم بعمل التدريس في أحد المدارس، وإني على وعي بالأمور الدينية بعض الشيء، وعندما ألتقي بالطالبات في حصص الفراغ أقوم بتوجيههن وإرشادهن، ولكني عندما أنتهي من الحديث أقول في نفسي: يمكن أن أقول شيء ولا أفعله، وإنني خائفة من ذلك ولكني والحمد لله أؤدي واجباتي نحو الله على أكمل وجه، فهل أستمر في دعوتي أم لا؟ وقد علمت من رسول الله ﷺ: من يكتم علماً يعلمه يلجم بلجام من نار، ولكم جزيل الشكر؟","title":"ترك الداعي الدعوة بحجة عدم عمله بما يقول","answer":"الجواب: الأخت السائلة، البنت الكريمة السائلة، أنت على خير عظيم، فإن توجيه الطالبات وإرشادهن إلى الخير أمر مطلوب وفيه خير عظيم، ولا تخافي أنك قد تتأخري عن شيء مما دعوت الطالبات إليه، فالشيطان يبذل جهوده الخبيثة في التثبيط عن الخير وعن الدعوة إلى الخير، ويقول للإنسان: إنك قد تدعو إلى هذا ولا تفعل، ليثبطه، وليس كل داعي أو كل داعية يكون كاملاً ويفعل كل شيء، لكن عليه الاجتهاد وعليه الحرص أن يكون من أسبق الناس إلى ما يدعو إليه، وأن يكون من أبعد الناس عما ينهى عنه، ولكن ليس معنى هذا أنه إذا كان عنده شيء من قصور يتأخر، لا، عليه أن يتقدم ويدعو إلى الله ويرشد، سواء كان ذكراً أو أنثى، على المؤمن وعلى المؤمنة أن يجد في هذا الأمر، بالنصيحة، والتوجيه للطلاب والطالبات، ولغيرهن من غير الطالبات أيضاً من نساء البيت، نساء الجيران، وعند الاجتماعات المناسبة في الأعراس وغيرها تكون مؤمنة مرشدة معلمة، وهكذا المؤمن عند اجتماعه بإخوانه في أي مناسبة، أو في البيت أو في المسجد يكون مرشداً على حسب ما عنده من العلم، ولا يغتر بالشيطان ولا يخدعه الشيطان، ليحذر أن يخدعه الشيطان بأن يقول له: اسكت، فإنك قد تدعو إلى شيء ولا تفعل، وقد تنهى عن شيء وتفعل، فإن هذا من تثبيط الشيطان، ولكن ليجتهد وليحرص على أن يكون من السابقين إلى ما يدعو إليه، وعليه أن يكون من المتباعدين عما ينهى عنه ويستعين بالله ويسأله التوفيق، وليستمر في عمله الصالح ودعوته الراشدة، وهكذا المؤمنة المرأة الطالبة والأستاذة عليهما أن تستمرا في الدعوة والتوجيه، وأن تستعينا بالله على العمل بما يرضيه ، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/4582/ترك-الداعي-الدعوة-بحجة-عدم-عمله-بما-يقول ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_017/01703.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7611,"question":"هذه الرسالة بعث بها للبرنامج المستمع رمضان عبد العظيم يقول في رسالته: السؤال الأول: يوجد لدينا في جميع البلاد في مصر أنهم يحتفلون بمولد سيدنا محمد ﷺ، فما حكم ذلك؟","title":"الاحتفال بالمولد النبوي ليس دليلا على المحبة","answer":"الجواب: هذه المسألة قد وقعت في بلدان كثيرة من بلدان المسلمين، كثير من المسلمين يحتفلون بالمولد النبوي، ورغم وجود ذلك في بلاد كثيرة فهو بدعة، فالبدع لا تنقلب سنناً بكثرة الفاعلين لها، سواء كان في المغرب أو في المشرق أو في مصر أو في غير ذلك، فهذا الاحتفال بالموالد من البدع التي أحدثها الشيعة وتبعهم عليها بعض السنة، وذكر بعض المؤرخين أن أول من أحدثها الفاطميون بنو عبيد بن القداح المعروفون الذين ملكوا مصر والمغرب في القرن الرابع والخامس، هم أول من أحدثها في القرن الرابع، أحدثوا موالد للنبي صلى الله عليه وسلم وللحسن والحسين ولـفاطمة ولحاكمهم، ثم وقع بعد ذلك الاحتفال بالموالد بعدهم، فهو بدعة بلا شك؛ لأن الرسول ﷺ هو المعلم المرشد وأصحابه أفضل الناس بعده بعد الأنبياء، وهو قد بلغ البلاغ المبين، ولم يحتفل بمولده عليه الصلاة والسلام، ولا أرشد إلى ذلك، ولا احتفل به أصحابه وهم أفضل الناس وأحب الناس إلى النبي ﷺ، ولا التابعون لهم بإحسان من القرون المفضلة الثلاثة، فعلم أنه بدعة، وهو وسيلة إلى الغلو والشرك، وهو وسيلة للغلو في الأنبياء والصالحين، فإنه قد يعظمونهم بالغلو والمدائح التي فيها الشرك بالله، الشرك الأكبر، كوصفهم لهم بأنهم يعلمون الغيب أو أنهم يدعون من دون الله، أو يستغاث بهم أو ما أشبه ذلك، فيقعون في هذا الاحتفال في أنواع من الشرك وهم لا يشعرون، أو قد يشعروا. \nفالواجب ترك ذلك، وليست الاحتفالات بالمولد دليلاً على حب المحتفلين بالنبي صلى الله عليه وسلم وعلى اتباعهم له، وإنما الدليل والبرهان على ذلك هو اتباعهم لما جاء به عليه الصلاة والسلام، هذا هو الدليل على حب الله ورسوله، الحب الصادق كما قال عز وجل: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] فمن كان يحب الله ورسوله فعليه باتباع الحق، بأداء فرائض الله وترك محارم الله، والوقوف عند حدود الله، والمسارعة إلى مراضي الله، والحذر من كل ما يغضب الله ، هذا هو الدليل، وهذا هو البرهان، وهذا الذي كان عليه أصحاب رسول الله ﷺ وأتباعهم بإحسان ، أما الاحتفالات بالموالد للنبي ﷺ، أو للشيخ عبد القادر الجيلاني أو للبدوي أو لفلان وفلان فهو كله بدعة وكله منكر يجب تركه؛ لأن الخير في اتباع الرسول ﷺ واتباع أصحابه، والسلف الصالح، والشر في الابتداع والاختراع ومخالفة ما عليه السلف الصالح، هذا هو الذي يجب، وهذا هو الذي نفتي به، وهذا هو الحق الذي عليه سلف الأمة، ولا عبرة بمن خالف ذلك، وتأول في ذلك، فإنما هدم الدين في كثير من البلدان، والتبس أمره على الناس بسبب التأويل والتساهل، وإظهار البدع وإماتة السنن، ولا حول ولا قوة إلا بالله، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4664/الاحتفال-بالمولد-النبوي ليس-دليلا-على-المحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_022/02205.mp3","categories":["البدع والمحدثات"]},{"id":7622,"question":"هذه الرسالة وردتنا من مكة المكرمة ومن المرسل عبد الله إبراهيم بخاري ويقول في رسالته: السلام عليكم ورحمة الله وبركاته، وبعد أرجو الإجابة على بعض الأسئلة الدينية وعرضها على سماحة الشيخ عبد العزيز بن باز وهي: السؤال الأول: حكم المولد النبوي؟ وما حكم الذي يحضره؟ وهل يعذب فاعله إذا مات وهو على هذه الصورة؟","title":"حكم من يصنع ويحضر الاحتفال بالمولد النبوي","answer":"الجواب: المولد لم يرد في الشرع ما يدل على الاحتفال به، لا مولد النبي ﷺ ولا غيره، فالذي نعلم من الشرع المطهر وقرره المحققون من أهل العلم: أن الاحتفال بالموالد بدعة، لا شك في ذلك؛ لأن الرسول ﷺ وهو أنصح الناس وأعلمهم بشرع الله، وهو المبلغ عن الله لم يحتفل بالمولد مولده ﷺ، ولا أصحابه، لا خلفاؤه الراشدون ولا غيرهم، فلو كان حقاً وخيراً وسنة لبادروا إليه ولما تركه النبي ﷺ، ولعلمه أمته وفعله بنفسه، ولفعله أصحابه خلفاؤه ، فلما تركوا ذلك علمنا يقيناً أنه ليس من الشرع، وهكذا القرون المفضلة لم تفعل ذلك، فاتضح بذلك أنه بدعة، وقد قال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد في أحاديث أخرى تدل على ذلك، وبهذا يعلم أن هذه الاحتفالات بالمولد النبوي في ربيع الأول أو في غيره، وهكذا الاحتفالات بالموالد الأخرى كـ البدوي والحسين وغير ذلك كلها من البدع المنكرة التي يجب على أهل الإسلام تركها. \nوقد عوضهم الله بعيدين عظيمين: عيد الفطر وعيد الأضحى، ففيهما الكفاية عن إحداث أعياد واحتفالات منكرة مبتدعة. وليس حب النبي ﷺ يكون بالموالد وإقامتها، وإنما حبه ﷺ يقتضي اتباعه، والتمسك بشريعته، والذب عنها، والدعوة إليها، والاستقامة عليها، هذا هو الحب قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُم [آل عمران:31] فحب الله ورسوله ليس بالموالد ولا بالبدع، ولكن حب الله ورسوله يكون بطاعة الله ورسوله، وبالاستقامة على شريعة الله، بالجهاد في سبيل الله، بالدعوة إلى سنة الرسول ﷺ وتعظيمها والذب عنها والإنكار على من خالفها، هكذا يكون حب الرسول ﷺ، ويكون بالتأسي به في أقواله وأعماله، والسير على منهاجه عليه الصلاة والسلام، والدعوة إلى ذلك. \nهذا هو الحب الصادق الذي يدل عليه العمل الشرعي، والعمل الموافق لشرعه. \nوأما كونه يعذب أو لا يعذب هذا شيء آخر، هذا إلى الله جل وعلا، فالبدع والمعاصي من أسباب العذاب، لكن قد يعذب الإنسان بمعصيته وقد يعفو الله عنه، إما لجهله وإما لأنه قلد من فعل ذلك ظناً منه أنه مصيب، أو لأعمال صالحة قدمها صارت سبباً لعفو الله أو لشفاعة الشفعاء من الأنبياء أو المؤمنين أو الأفراط، فالحاصل أن المعاصي والبدع من أسباب العذاب، وصاحبها تحت مشيئة الله جل وعلا، إذا لم تكن بدعته مكفرة، أما إذا كانت البدعة مكفرة فيها الشرك الأكبر فصاحبها مخلد في النار نعوذ بالله، لكن إذا كانت البدعة ليس فيها شرك أكبر، وإنما هي فروع خلاف الشريعة، من صلوات مبتدعة أو من احتفالات مبتدعة ليس فيها شرك، فهذا تحت مشيئة الله كالمعاصي. نعم.","link":"https://binbaz.org.sa/fatwas/4675/حكم-من-يصنع-ويحضر-الاحتفال-بالمولد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02405.mp3","categories":["البدع والمحدثات"]},{"id":7623,"question":"طيب بالنسبة للأشخاص، هناك أيضاً من يجعل له عيداً لميلاده هو لهذا الشخص ما حكم هذا؟","title":"حكم الاحتفال بأعياد الميلاد","answer":"الجواب: كل هذا منكر، جعل عيداً له أو لأمه أو لبنته أو لولده كل هذه الذي أحدثوها الآن تشبهاً بـالنصارى واليهود، لا أصل لها ولا أساس لها، عيد الأم أو عيد الأب أو عيد العم أو عيد الإنسان نفسه أو عيد بنته، كل هذه منكرات، كلها بدع، كلها تشبه بأعداء الله، لا يجوز شيء منها أبداً، بل يجب سد الباب والحذر من هذه المحدثات، ولكن بعض الناس كثرت عليه النعم واجتمعت عنده الأموال فلا يدري كيف يتصرف فيها، لم يوفق لصرفها في طاعة الله وفي تعمير المساجد ومواساة الفقراء، وصار يلعب بها في هذه الأعياد وأشباهها، وإذا كان المراد إحياء سنة الرسول ﷺ فليس بالموالد، يحييها بالدروس الإسلامية في المدارس والمساجد والمحاضرات، هذا ليس بدعة، بل مشروع مأمور به، يدرس السيرة النبوية، ويبين ما جاء في المولد من الأخبار في الدروس الإسلامية بالمدارس، بالمعاهد، في المساجد، في المحاضرات، أما يجعل لها وقتاً مخصوصاً تقام فيه الاحتفالات في ربيع الأول أو في غيره والمآكل والمشارب وغير ذلك، هذا لا أصل له، بل هو من البدع المحدثة. نعم.","link":"https://binbaz.org.sa/fatwas/4676/حكم-الاحتفال-باعياد-الميلاد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02406.mp3","categories":["البدع والمحدثات"]},{"id":7634,"question":"سماحة الشيخ! هذه رسالة وردتنا من الموصل من حي المثنى بالجمهورية العراقية تقول المسلمة: إن عائلتها يتكلمون في أعراض الناس بحق وبغير حق، وتقوم بمحاولة منعهم من ذلك، إلا أنهم يردون عليها بكلمات نابية، ويطلبون منها الابتعاد عنهم مما يثير أعصابها، ثم تزوج أخوها، وأصبحت زوجته تهين والدتها ولا تساعدها في المنزل، وتشارك في إهانة الناس في الكلام فيهم، فماذا تفعل هذه الفتاة المسلمة تجاه والديها وزوجة أخيها؟","title":"الواجب تجاه من يعيش في بيئة غير صالحة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: \nفهذه السائلة نرجو لها خيراً كثيراً؛ لأن إنكار المنكر مما شرعه الله لعباده؛ ولأن ذلك من صفات المؤمنين والمؤمنات، كما قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ولا شك أن الكلام في أعراض الناس والغيبة للناس من المنكرات، قال الله جل وعلا: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] فالغيبة: ذكرك أخاك بما يكره، ولما سئل النبي عن ذلك عليه الصلاة والسلام قال: إن كان في أخيك ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهته.\nوالخلاصة: أنها مأجورة على إنكارها، وأن هذا هو الواجب عليها إذا حضرت، وقد قال النبي ﷺ في الحديث الآخر: من رد عن عرض أخيه بالغيب رد الله عن وجهه النار يوم القيامة، فإنكار المنكر على من فعله أمر لازم على الرجال والنساء جميعاً، وعليها أن تجتهد وأن تسأل الله لهم الهداية، وتخاطبهم بالتي هي أحسن، تنصح لهم، وتذكر لهم أن هذا فيه خطر وأن هذا من أسباب غضب الله، وأشباه ذلك من الكلام، لعل الله أن يهديهم، وهكذا مع زوجة أخيها التي تهين الوالدة وتتكلم في الأعراض تنصحها أيضاً، وتقول لها: اتق الله، وراقبي الله؛ لعل الله يهديها بأسبابها، هكذا أيها الأخت السائلة ينبغي أن تفعلي هذا، استقيمي على إنكار المنكر واصبري، فلا بد من الصبر كما قال لقمان لابنه: يَا بُنَيَّ أَقِمِ الصَّلاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الأُمُورِ [لقمان:17] فالآمر الناهي لا بد له من أذى، ولا بد له من أن يسمع ما يكره، فعليه أن يصبر، وقد وصف الله الرابحين في كتابه الكريم بأنهم صبر، فقال جل وعلا: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] هذه صفات الرابحين، صفات أهل الإيمان والصدق: إيمان صادق، وعمل صالح، وتواصٍ بالحق، وتواص بالصبر. نعم.","link":"https://binbaz.org.sa/fatwas/4688/الواجب-تجاه-من-يعيش-في-بيىة-غير-صالحة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02601.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7647,"question":"هذه رسالة وردت للبرنامج من جيزان ومن إبراهيم مطر من قرية الجهو، يقول في رسالته: عندنا عادات منها أن ليلة ثلاث من وفاة الميت نقرأ قرآن، ويحضر الناس بكثرة في هذه الليلة، وقد قيل لنا: إن هذا العمل بدعة، فأخذنا أسلوب غيره، فإذا جاءت هذه الليلة ندعو للميت بالمغفرة والرحمة لكي ينفض هذا الموقف، فهل هذا الفعل يجوز من الدعاء للميت؟ وإذا كان العكس فبم تنصحونا وفقكم الله في إقناع الحضور إنهاء التعزية، أرشدونا أرشدكم الله؟","title":"حكم الاجتماع في الليلة الثالثة من دفن الميت للدعاء له","answer":"الجواب: الاجتماع لأهل الميت في الليلة الثالثة من الموت لقراءة القرآن أو للدعاء أو لصنع وليمة كل هذا بدعة لا أصل له، وإنما يعزون، يزورهم الناس في أي وقت، كان في يوم الموت أو في الثاني أو في الثالث أو الرابع، ما في حد محدود، يزورهم الناس في أوقات مناسبة يعزونهم هذا لا بأس به، التعزية مستحبة، أما أنهم يصنعون لهذا شيء من طعام أو قراءة قرآن يعتاد أو ما أشبه ذلك، هذا كله بدعة حتى جلوسهم مع الناس للدعاء للميت والاستغفار له كذلك بدعة، ولكن هذا الوقت يتركونه، يعني: يحلون هذه العادة ويزيلونها بترك الجلوس في هذا الوقت حتى من أرادهم يجدهم في أوقات أخرى، وبهذا تنتهي هذه العادة السيئة في اليوم الثالث، لا يجلسون في اليوم الثالث لا لقراءة ولا للدعاء للميت والاستغفار ولا لغير هذا، بل يدعون هذه العادة بالكلية، ويمكن أن يجدهم المعزون في أوقات أخرى، في اليوم الأول واليوم الثاني واليوم الرابع، حتى لا تبقى هذه العادة السيئة. نعم.\nوهكذا ما يفعل بعض الناس من صنع ولائم في اليوم السابع أو في الأربعين بعد الموت، كل هذه بدع، فأي ترتيب يقع من مأتم للميت في اليوم الثالث أو رابع أو عاشر أو أربعين أو غير ذلك أو شيء غير هذا بحيث يجتمعون لطعام أو قراءة قرآن أو ذبائح أو ولائم كله بدعة، كل هذا بدع، كل هذه المآتم بدع، يجب الحذر منها ولا يجب فعلها.\nوهكذا ما تفعله الشيعة في يوم العاشر من محرم بدعة، من النعي على الحسين ، وما يفعلونه هناك كله من البدع التي نسأل الله أن يهديهم حتى يتركوها، نسأل الله لنا ولهم الهداية؛ لأن هذا شيء لا أصل له، فلا ينبغي لأهل الإسلام أن يفعلوا ذلك أبداً، لا مع كبير ولا مع صغير ولا مع شريف ولا مع وضيع؛ لأن الرسول ﷺ سيد ولد آدم ، ولما توفي ﷺ ما اجتمع الناس بعد وفاته في اليوم الثالث ولا في العاشر وجعلوا وليمة أو قراءة قرآن، وهكذا الصديق لما مات ما اجتمع الناس لصنع طعام أو قراءة قرآن، وهكذا عمر لما قتل، وهكذا عثمان ، وهكذا علي  رابع الخلفاء الراشدين، وهكذا بقية العشرة، وهكذا بقية الصحابة، وهم السادة وهم القدوة، فلو كان هذا شيئاً مستحباً طيباً لفعلوه.. ولاقتدى بهم الناس.\nفالحاصل أن هذا الشيء لا يجوز بل هو من البدع التي يجب تركها على أهل السنة وعلى الشيعة جميعاً، يجب على الجميع ترك هذا البدع، وأن يراقبوا الله  في ذلك، وأن يتأسوا بنبيهم ﷺ وبخلفائه الراشدين الأربعة: الصديق وعمر وعثمان وعلي ، فإنهم هم خيرة الناس، وهم أفضل الناس بعد نبي الله وبعد الأنبياء، وهم القدوة، رزق الله الجميع الهداية.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4795/حكم-الاجتماع-في-الليلة-الثالثة-من-دفن-الميت-للدعاء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03606.mp3","categories":["أحكام التعزية","البدع والمحدثات"]},{"id":7650,"question":"يقول سعد محمد السعيد المالكي من متوسطة العمشان ببلاد بني مالك في رسالته: من بلاد بني مالك إلى من يهمه الأمر، السلام عليكم ورحمة الله وبركاته.. وبعد:نفيدكم أنه يوجد لدينا بمسجدنا نعش لحمل الأموات ودكة غسل مصنوعة من الحديد ومغطاة بألواح بيلوت، ونحن لا نعلم هل هو جائز حمل الميت على هذا النوع من الحديد، أفيدونا جزاكم الله خيراً، والله يحفظكم ويرعاكم؟","title":"حكم حمل الميت على نعش من حديد","answer":"الجواب: لا نعلم في هذا شيئاً، حمله على خشب أو على ألواح من غير الخشب أو على حديد لا نعلم في هذا شيئاً، لكن الأولى أن يتخذ شيء خفيف حتى لا يشق على الحاملين؛ لأن الناس إذا حملوه على الأكتاف قد يشق عليهم ذلك، أما إذا حمل في السيارة فالأمر في هذا واسع، لكن الشيء الخفيف أولى بكل حال، الألواح الخفيفة يوضع عليها الميت ويحمل عليها إلى المقبرة هذا أولى من الشيء الثقيل، أما الحرج فلا حرج إن شاء الله في كونه من حديد أو من خشب، لكن إذا كان حديداً خفيفاً لا يشق على الناس فلا حرج، وإن كان ثقيلاً فينبغي تركه حتى لا يشق على الحاملين. نعم.","link":"https://binbaz.org.sa/fatwas/4788/حكم-حمل-الميت-على-نعش-من-حديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03602.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7712,"question":"المرسل عبد الكريم من الخفجي يسأل عن تلقين المقبور، يقول: السلام عليكم ورحمة الله وبركاته وبعد: أرجو عرض سؤالي هذا على فضيلة الشيخ المجيب، أود لو تعطوني فكرة عن التلقينة، هل هي صحيحة أم بدعة، تلقينة الميت عند نزوله في القبر، أفيدونا جزاكم الله خيراً؟","title":"حكم تلقين الميت بعد الدفن","answer":"الجواب: التلقين اختلف فيه العلماء، وهو أن يقال له: يا فلان! اذكر ما خرجت عليه من الدنيا: شهادة أن لا إله إلا الله وأن محمداً رسول الله.. إلى آخره، وقد جاء فيه بعض الأحاديث لكنها غير صحيحة، جاء في بعض الآثار عن بعض أهل الشام، والصواب أنه بدعة.. التلقين، لا يقال له: يا فلان! اذكر ما خرجت عليه من هذه الدنيا: شهادة أن لا إله إلا الله، وأن محمداً رسول الله، وأنك رضيت بالله رباً وبالإسلام ديناً وبمحمد رسولاً، والقرآن إماماً.. إلى آخره، هذا ليس له أصل يعتمد عليه، فالذي ينبغي تركه، هذا هو المعتمد لعدم الدليل، ولكن يستحب إذا فرغ الناس من دفن الميت يستحب الوقوف عليه، والدعاء له بالمغفرة والثبات، هذا المشروع، إذا فرغ الناس من دفن الميت يوقف عليه ويدعى له بالمغفرة والثبات، هكذا جاءت السنة كان النبي ﷺ إذا فرغ من الدفن وقف عليه وقال: استغفروا لأخيكم، وسلوا له التثبيت فإنه الآن يسأل هذه السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4911/حكم-تلقين-الميت-بعد-الدفن ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7734,"question":"أيضاً يقول المستمع من حضرموت: المولد في المساجد ليلة كل جمعة يوجد كتاب اسمه المولد الدبيعي أو الربيعي يقول: فيه قصائد عدة تمدح الرسول ﷺ، ويكثر فيه الصلاة على النبي والمدح وسيرته من قبل مولده إلى وفاته نرجو توضيح ذلك مع الدليل؟","title":"حكم إقامة الموالد وإلقاء المدائح النبوية","answer":"الجواب: أما الاحتفال بالموالد هذا لا أصل له، وليس عليه دليل ولم يفعله الرسول ﷺ في حياته ولا فعله خلفاؤه الراشدون رضي الله عنهم وهم أعلم الناس به، وأحب الناس له عليه الصلاة والسلام، وهكذا بقية الصحابة لم يفعلوه ولا التابعون في جميع القرون المفضلة، فدل ذلك على أنه بدعة، ولكن دراسة السيرة النبوية كون العالم يدرس السيرة بين الناس في أي وقت في الليل أو في النهار، في الأسبوع مرة أو مرتين أو أكثر أو أقل، هذا كله طيب دراسة السيرة بيان سيرة النبي ﷺ وما كان عليه في أسفاره وإقامته، وبيان أخلاقه وأعماله عليه الصلاة والسلام هذا حق حتى يتأسى به، أما العناية بالقصائد التي فيها غلو، والإطراء وجعل وقت معين لهذا المولد في ربيع الأول في الثاني عشر أو في غيره لقصد دراسة هذا المولد من حين ولد عليه الصلاة والسلام، ويؤتى في ذلك بالقصائد الشركية كالبردة وغيرها، هذا منكر لا أصل له، وإنما المشروع أن يؤتى بالدروس الشرعية التي يقرؤها الناس في البيوت أو في المساجد كسائر الدروس، لبيان سيرته ﷺ وما كان عليه، كيف ولد وكيف عاش ثم بعد بعثته، وهو المهم المهم أعماله بعد البعثة كيف أعماله كيف سيرته حتى يتأسى به المؤمنون وحتى يستفيدوا.\nأما ما اعتاده الناس من إيجاد مولد يحتفل به في ربيع الأول وتذبح فيه الذبائح، وتقام فيه الولائم ويؤتى فيه بالقصائد التي فيها الإطراء والغلو، ويقوم الناس في وقت معين يقولون: إنه حضر عليه الصلاة والسلام، يقومون له، هذا كله لا أصل له، كله من البدع المنكرة ومن وسائل الشرك، لأنهم يقع عندهم في بعض الأحيان غلو كثير وإطراء، يستغيثون فيه بالنبي ﷺ ويسألونه المدد والنصر إلى غير ذلك، وربما وقع في ذلك أحاديث موضوعة مكذوبة لا أساس لها، وفي بعض البلدان يقع اختلاط بين الرجال والنساء ويقع أشياء منكرة في الاجتماع والاحتفال في بعض البلدان، فيجب الحذر من ذلك، ولا يجوز إقامة هذه الموالد وهذه الاحتفالات لأنها خلاف ما شرعه الله عز وجل، ولأنها لو كانت خيراً لسبقنا إليها أصحاب محمد ﷺ والتابعون لهم بإحسان، وإنما أحدثها الفاطميون في القرن الرابع ثم انتشرت بعدهم، فلا ينبغي لعاقل أن يغتر بالفاطميين المعروفين بالرفض والتشيع، وأن يكونوا هم أئمةً في هذا الشيء، نسأل الله للجميع الهداية . نعم.","link":"https://binbaz.org.sa/fatwas/4933/حكم-اقامة-الموالد-والقاء-المداىح-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_033/03302.mp3","categories":["البدع والمحدثات"]},{"id":7735,"question":"أيضاً يقول في رسالته هذا الذي بعثها من حضرموت: يقال: أن هناك بدعة حسنة وبدعة سيئة، فما حقيقة ذلك مع الدليل؟ وإن صحت هذه العبارة نرجو تطبيقها على الأسئلة السابقة؟","title":"حكم تقسيم البدع إلى حسنة وسيئة","answer":"الجواب: هكذا يقول بعض الناس إن البدعة تنقسم إلى أقسامٍ خمسة تدور عليها الأحكام: بدعة حسنة، بدعة محرمة، بدعة مكروهة، بدعة مندوبة، بدعة مباحة، وهذا التقسيم فيه نظر، والرسول ﷺقال: كل بدعة ضلالة ولم يقسمها بل قال: كل بدعة ضلالة فالحق الذي لا ريب فيه أن البدع المخالفة للشرع كلها ضلالة، ومراد النبي ﷺ ما أحدثه الناس، ولهذا قال: إياكم ومحدثات الأمور قال: شر الأمور محدثاتها وكل بدعة ضلالة هكذا يقول ﷺ، فالمحدثات التي تخالف شرع الله فإنها ضلالة، ولهذا قال عليه الصلاة والسلام في الحديث الآخر: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال أيضاً عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد فكل بدعة ضلالة، وكل محدثةٍ بدعة، وكل بدعة ضلالة كما قاله النبي ﷺ ومن ذلك الاحتفال بالموالد فإنها بدعة ضلالة، وهكذا تعظيم القبور بالبناء عليها واتخاذ القباب عليها، والاجتماع عندها للنوح أو لدعائها والاستغاثة بها كل هذا من البدع الضلالة، وبعضها من البدع الشركية، لكن بعض الناس قد يلتبس عليه بعض الأمور فيرى أن ما وقع في المسلمين من بعض الأشياء التي لم تقع في عهد النبي ﷺ أنها بدعة حسنة، وربما يتعلق بقول عمر  في التراويح نعمت البدعة لما جمع الناس على إمامٍ واحد، وهذا ليس مما أراده النبي ﷺ، فإن ما يحدثه الناس مما تدل عليه الشريعة وترشد إليه الأدلة ما يسمى بدعةً منكرة، وإن سمي بدعةً من حيث اللغة فكون المسلمين نقطوا المصاحف وشكلوا القرآن حتى لا يشتبه على القارئ وجمعوه في المصاحف، هذا وإن سمي بدعة لكن هذا شيء واجب شيء يحفظ القرآن ويسهل قراءته على المسلمين، هذا نحن مأمورون به، مأمورون بما يسهل علينا القرآن وبما يحفظه على المسلمين وبما يعين المسلمين على حفظه وقراءته قراءةً مستقيمة، فليس هذا من باب البدعة المنكرة، بل هذا من باب الأوامر الشرعية، من باب الحفظ للدين، من باب العناية بالقرآن، فليس مما نحن فيه بشيء، وكذلك قول عمر نعمت البدعة يعني كونه جمعهم على إمامٍ واحد بعد النبي ﷺ هذا بدعة من حيث اللغة؛ لأن البدعة في اللغة الشيء الذي ليس عليه مثال سبق، ما يحدثه الناس على غير مثال سابق يسمى بدعة عند أهل اللغة، فهذا إنما أراد من حيث اللغة لا من حيث الشرع، فإن التراويح فعلها النبي ﷺ وصلى بالناس ليالي وأرشد إليها أو حثهم عليها، فليست بدعة التراويح، ولكن كونه جمعهم على إمامٍ واحد قال فيه: نعمت البدعة من حيث اللغة فقط.\nفالحاصل أنما أوجده المسلمون مما يدل عليه الشرع ويرشد إليه الشرع بعد النبي صلى الله عليه وسلم لا يسمى بدعة، بل هو مما دعا إليه الشرع وأمر به الشرع من جنس جمع المصحف وشكله ونقطه ونحو ذلك، هذا ليس من البدع في شيء من جنس التراويح جمع عمر لها  وأرضاه ليس من هذا الباب في شيء، وإنما الذي أنكره العلماء وقصده النبي ﷺ هو ما يحدثه الناس مما يخالف شرع الله، ومما يخالف أوامر الله ورسوله مثل: البناء على القبور، مثل: اتخاذ المساجد عليها، مثل: الغلو فيها بدعائها والاستغاثة بها والنذر لها ونحو ذلك، هذه من البدع الشركية، مثل: الاحتفال بالموالد، هذه من البدع المنكرة التي هي من وسائل الشرك وما أشبه ذلك، مثل بدعة الإسراء والمعراج كونهم يحتفلون بليلة سبعة وعشرين من رجب باسم المعراج والإسراء، هذا بدعة لا أصل له؛ لأن النبي صلى الله عليه وسلم لم يحتفل بليلة الإسراء والمعراج ولا أصحابه، ولأنه غير معلومة على الصحيح بل أنسيها الناس ولو علمت لم يجز الاحتفال بها لأن الرسول صلى الله عليه وسلم لم يحتفل بها ولا أصحابه رضي الله عنهم، فدل ذلك على أنها بدعة لقوله ﷺ: من أحدث في أمرنا ما ليس منه فهو رديعني فهو مردود. نعم.","link":"https://binbaz.org.sa/fatwas/4934/حكم-تقسيم-البدع-الى-حسنة-وسيىة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_033/03303.mp3","categories":["البدع والمحدثات"]},{"id":7738,"question":"هذه الرسالة موجهة لكم يقول مرسلها عباس عبد الفتاح من مصر العربية الإسلامية: فضيلة الشيخ عبد العزيز بن عبد الله بن باز السلام عليكم ورحمة الله وبركاته، لقد سمعت لكم إجابة عن سؤال في نور على الدرب بخصوص إقامة الموالد والاحتفال بها مثل المولد النبوي الشريف، وقد تفضلتم بالإجابة بعدم إقامة مثل هذه الموالد وغيرها بما ورد في الكتاب والسنة وعلينا أن نتبع ما أمر به ونهى عنه الله ورسوله، وأنا عن نفسي مقتنع بذلك تمام الاقتناع، ولكن نشاهد في مصر الإسلامية أن أصحاب الفضيلة العلماء والمشايخ يحضرون هذه الاحتفالات والموالد أمثال: الحسين ، السيدة زينب ، البدوي وغيرهم، بل حتى عندنا في صعيد مصر كثير، وسؤالي الأول هو: ما هو الصواب في هذا الموضوع؟","title":"ما حكم إقامة الموالد؟","answer":"الجواب: الصواب هو ما سمعت فيما نقلت عن جوابي السابق وأن هذه الموالد التي يحتفل بها الناس بدعة لا أصل لها، ولا ينبغي للعاقل وطالب العلم أن يغتر بفعل الناس، فإن فعل الناس لا يقاس عليه ولا يحتج به وإنما يحتج بما قاله الله ورسوله، فأقوال الناس وأعمال الناس واحتفالاتهم كلها تعرض على الكتاب والسنة فما وافق كتاب الله أو سنة رسوله الصحيحة عليه الصلاة والسلام فهو المتبع وهو الحق وما خالفهما وجب رده وإن فعله الناس، قال الله تعالى: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، وقال : وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116]، وقال : وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ [سبأ:20]. فالحاصل أن أفعال الناس وأقوال الناس ليست ميزاناً توزن بها الأحكام وتعرف بها الأحكام الشرعية، وإنما الميزان هو ما قال الله جل وعلا: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، وفيما قال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إلى الله [الشورى:10] هذا هو الميزان، الميزان هو ما قاله الله ورسوله، فالاحتفالات بالموالد ليس لها أصل في كتاب الله ولا في سنة الرسول عليه الصلاة والسلام، وقد مضى على المسلمين قرون كثيرة لم يحتفلوا فيها بالموالد، فلم يفعله النبي صلى الله عليه وسلم في حياته وهو خاتم النبيين ليس بعده نبي يعلمنا، هو خاتم النبيين وهو أنصح الناس عليه الصلاة والسلام وهو أعلم الناس وأخشى الناس لله وأتقاهم لله عليه الصلاة والسلام، فلو كان الاحتفال بمولده صلى الله عليه وسلم أو بالموالد أخرى أمراً مشروعاً لبينه للأمة عليه الصلاة والسلام أو فعله بنفسه حتى يقتدى به، ثم لو تركه بنفسه عليه الصلاة والسلام لأنه غير واجب ولكن هو سنة في نفسه لفعله الصحابة أخذاً من فعله أو من قوله عليه الصلاة والسلام، فلم يفعله الرسول ﷺ ولم يدع إليه ولم يأمر به ولم يفعله صحابته لا الخلفاء الراشدون ولا غيرهم، ثم جاء القرن الثاني قرن التابعين وكبار أتباع التابعين فلم يفعلوه، ثم جاء من بعدهم القرن الثالث فلم يفعلوه، فدل ذلك على أنه بدعة لقوله ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد، من أحدث في أمرنا هذا ما ليس منه فهو رد، وكان يقول في خطبته عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة، هكذا كان يقول في خطبته عليه الصلاة والسلام في الجمعة -اللهم صل عليه وسلم-.\nفلو كانت الاحتفالات بالموالد أمراً مطلوباً أو أمراً مشروعاً لما فات على أولئك الأخيار السادة وحضي به ووفق له من بعدهم، فإن القرون السابقة قد اشتملت على الحق ولا يمكن أن يكون الحق في غيرها وتحرم هي من الحق، وقد قال عليه الصلاة والسلام: لا تزال طائفة من أمتي على الحق منصورة وهؤلاء القرون بهذه الطائفة القرون الأولى، القرن الأول ثم الثاني ثم الثالث، وقد قال عليه الصلاة والسلام: خير أمتي قرني، ثم الذين يلونهم، ثم الذين يلونهم الحديث، فلا يجوز أبداً أن يعتقد أحد أن الحق يفوت هذه القرون الفاضلة العظيمة ثم يدركه ويحوزه من بعدهم، هذا لا يقوله من يؤمن بالله واليوم الآخر.\nفالحاصل أن الاحتفالات بالموالد مولد النبي ﷺ ومولد الحسين ومولد فلان ومولد البدوي إلى غير ذلك كلها بدع لا أصل لها، وإنما أحدثها من أحدثها في القرن الرابع وما بعده كما ذكر ذلك صاحب (الإبداع في مضار الابتداع) وذكر أن الذين بدءوا بإحداثها هم حكام مصر الفاطميون حكام المغرب الذين انتسبوا إلى أهل البيت كذباً وليسوا منهم في شيء، وقد قال أبو العباس ابن تيمية شيخ الإسلام رحمة الله عليه: إن ظاهرهم الرفض وباطنهم الكفر محض. \nفالحاصل أنهم هم الذين أحدثوا هذا في القرن الرابع ثم أحدثه بعدهم أناس آخرون من الشيعة ومن غير الشيعة ممن ينتسب إلى السنة، غلطاً وجهلاً، ولا ينبغي لعاقل أن يغتر بهذا الأمر الذي فعله كثير من الناس، فهذه أيضاً المساجد تبنى على القبور والقباب توضع على القبور، فهل يقول: من يؤمن بالله ... أن هذا شرع وإنه سنة وأنه قربة، هو بدعة منكرة ومع ذلك وجدت في الناس، وقد قال النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقد قال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك خرجه مسلم في الصحيح.\nوقال جابر رضي الله عنه: نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه، فأخبر جابر أن الرسول ﷺ نهى عن تجصيص القبور وعن البناء عليها وهي الآن تجصص ويبنى عليها وتوضع عليها القباب والمساجد، فهل يقول من يعرف الحق إن هذا جائز أو أنه مشروع لأن الناس فعلوه بل هو بدعة ومن وسائل الشرك ولو فعله الناس، اتخاذ المساجد قبور والبناء عليها واتخاذ القباب عليها والتجصيص وكل هذا محرم، كله من وسائل الشرك ولو فعله الناس.\nكذلك كثير من الجهلة يأتون القبور المعظمة ويدعونها ويستغيثون بأهلها ويطلبون منها المدد، فهل يقول قائل إن هذا جائز؛ لأن الناس فعلوا هذا أو لأن كثير الناس فعلوا هذا، لا يقول هذا من يعرف الدين، فإن دعاء الأموات والاستغاثة بالأموات وطلب المدد من الأموات هو فعل الجاهلية الأولى، هو فعل في أهل الشرك المعروف سابقاً وهو من الشرك الأكبر، ومع ذلك فعله كثير من الجهال عند القبور عند قبر الحسين وعند قبر غير الحسين وعند قبر البدوي وربما فعله بعض الجهال عند قبر النبي ﷺ في المدينة، فهل يقول من يؤمن بالله إن هذا جائز، أو إن هذا قربة، أو أنه لا بأس به؟! بل هو من الشرك ومن عبادة غير الله ومن عمل الجاهلية الأولى وإن فعله الكثير من الناس، فينبغي لكل مسلم أن يعقل هذا وأن ينتبه لهذا الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/4937/ما-حكم-اقامة-الموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_034/03402.mp3","categories":["البدع والمحدثات"]},{"id":7739,"question":"أيضاً يقول: نشاهد في مصر الإسلامية أن أصحاب الفضيلة العلماء والمشايخ يحضرون هذه الاحتفالات؟","title":"القول في حضور بعض العلماء جلسات الموالد","answer":"الجواب: هذا كذلك، كون بعض العلماء يشهد بعض البدع لا يستنكر هذا، وهل أهلك الناس إلا علماء السوء وعلماء الجهل؟! هل هلكت اليهود إلا بعلماء السوء فيها؟! وهل هلكت النصارى إلا بعلماء السوء فيها وأغلاطهم؟! وهذه الأمة كذلك، إنما هلك أكثرهم بسبب علماء السوء وعلماء الجهل والعالم وإن كان كبيراً وعظيماً فقد يغلط فيغتر بغلطه بعض الناس وزلت العالم لها خطر عظيم كما أوصى الصحابة وغيرهم بالحذر من زلة العالم.\nفإذا زل عالم بفعله أو بقوله وإن كان يشار إليه بالعلم لكن غلط في مسألة من المسائل مثل حضور الاحتفالات تأول في ذلك أو قصد أن ينصحهم أو يبين شيئاً من أمور الدين فحضر، وغاب عنه أن حضوره قد يحتج به فلا يكون هذا حجة إذا حضر العالم بعض الاجتماعات المنكرة أو بعض الاحتفالات المنكرة، لا يكون هذا حجة على جوازها فقد يكون له عذر وقد يكون جهل هذا الأمر وقت حضوره وإن كان عنده علوم وعنده فضل فلا ينبغي أن يغتر بأغلاط العلماء وزلات العلماء لا قولاً ولا فعلاً، نسأل الله للجميع الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/4938/القول-في-حضور-بعض-العلماء-جلسات-الموالد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_034/03403.mp3","categories":["البدع والمحدثات"]},{"id":7740,"question":"أيضاً في سؤاله الأخير يقول عباس عبد الفتاح: لماذا لا يحدث اجتماع مثلاً بين العلماء جميعاً وشرح وجه الحقيقة حتى يغير ما يحدث في جميع البلدان الإسلامية من هذه العادات؟","title":"مقترح باجتماع علماء الأمة على إنكار بدعة الموالد","answer":"الجواب: قد جرى اجتماعات كثيرة وبحث هذا الموضوع في اجتماعات كثيرة ولكن لا تزال العقول تختلف في فهمها، ولا يزال من ينظر في المسائل العلمية يحصل بينهم خلاف في وجهة النظر، بعضهم يستحسنها لأن فيها دراسة لسيرة النبي ﷺ وبعضهم يقول: لأن فيها يعني فرصة لتوعية الناس وتعليمهم بعض أمور الدين، وبعضهم يحتج بأشياء أخرى ولكن من نظر في الأدلة الشرعية عرف أن هذه الأمور التي يحتج بها لا وجه لها وأن الواجب منع هذه الاحتفالات، وفي الإمكان أن يعلم الناس أحكام الشرع في المجالس العلمية والحلقات العلمية وفي دراسة السيرة النبوية من دون حاجة إلى هذه الاحتفالات، فليست هذه الاحتفالات هي الوسيلة للتعليم بل هناك وسائل أخرى من الإذاعة والصحافة والحلقات العلمية التي يوضح فيها أحكام الشرع وتوضح فيها سيرة النبي عليه الصلاة والسلام من دون حاجة إلى هذه البدع.","link":"https://binbaz.org.sa/fatwas/4939/مقترح-باجتماع-علماء-الامة-على-انكار-بدعة-الموالد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_034/03404.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7755,"question":"هذه الرسالة وردت من جمهورية اليمن الديمقراطية، وبعث بها المستمع محفوظ محمد البكري ، يقول فيها محفوظ: من عادات بلدي حينما يموت شخص يقرأ عليه الناس ما تيسر من القرآن الحكيم لمدة ثلاثة أيام، ويؤجر قريب الشخص المتوفى أحد الناس -بإيجاده قراءة القرآن- ويؤجره قراءة كتاب الله بمبلغ معين، ثم توهب وتهدى هذه القراءات إلى روح المتوفى، ما حكم هذه القراءة؟ وهل تصل إلى روح الميت؟ أثابكم الله.","title":"حكم قراءة القرآن بالأجرة وإهداء الأجر إلى المتوفى","answer":"الجواب: هذه قراءة بدعة لا أساس لها في الشرع، ولم يرد في الشرع ما يدل على استحبابها ولا جوازها، فالواجب تركها وعدم فعلها، ثم المستأجر أي ثواب له؛ لأنه لم يقرأ إلا بالأجرة، وقد أجمع العلماء على أنه لا يجوز الاستئجار على تلاوة القرآن، فالذي يستأجر ليتلو للميت أو للحي أي ثواب له وهو لم يقرأ لله إنما قرأ للأجرة! فأي شيء يهدى!\nالمقصود أن هذا منكر ولا يجوز، والمستأجر ليتلو قد أتى منكراً عظيماً ومحرماً بالإجماع، وليس له ثواب حتى يهدى، فلا يجوز فعل هذا بل المشروع الدعاء له وتعزية أهله، أما كونهم يرتبون الناس ليقرءون ويستأجرون الناس ليقرءون للميت ويهدى له ثواب ذلك فليس له أصل، والاستئجار على هذا منكر وباطل. نعم.","link":"https://binbaz.org.sa/fatwas/4958/حكم-قراءة-القران-بالاجرة-واهداء-الاجر-الى-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04405.mp3","categories":["البدع والمحدثات","الإجارة"]},{"id":7756,"question":"أيضاً يقول محفوظ من جمهورية اليمن الديمقراطية: لي زملاء يحتجون بما ابتدع في الدين بأنها سنة، محتجين بقول رسول الله ﷺ: من سن سنة حسنة ... إلى آخر الحديث الشريف، ويكرر دائماً قول عمر بن الخطاب عندما جمع الناس أن يصلوا التراويح على إمام واحد بقوله: «نعم البدعة» من صحيح البخاري، هل يثبت ذلك حجة للزملاء أم لا؟","title":"الرد على من يقول: إن بعض البدع من السنن الحسنة","answer":"الجواب: هذا غلط ومغالطة، ولا يجوز أن يحتج على إيجاد البدع وعلى إقرار البدع بهذا الحديث الصحيح: من سن في الإسلام سنة حسنة لأن المراد من سن في الإسلام المراد بذلك إظهارها وإبرازها والدعوة إليها بعدما أميتت أو جهلها الناس، ليس المراد الابتداع والإحداث؛ لأن هذا يناقض قول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد، من عمل عملاً ليس عليه أمرنا فهو رد إياكم ومحدثات الأمور، شر الأمور محدثاتها، وكل بدعة ضلالة.\nفالأحاديث الصحيحة واضحة في منع البدع والتحذير منها وأنها من المنكر، فلا يجوز لأحد أن يحكم على البدع بأنها حسنة لأجل فهمه السيء من قوله ﷺ: من سن في الإسلام سنة حسنة هذا غلط في فهم السنة وتحريف للمعاني، وإنما المراد إبراز السنن وإظهارها، سنها أي: أظهرها وأبرزها وبينها للناس حتى اقتدوا به فيها وحتى ساروا خلفه فيها بعدما جهلوها وبعدما غفلوا عنها.\nأما إحداث البدع فلا يجوز، بل يجب على الناس أن يسيروا على ما رسمه الله لهم في كتابه وعلى ما رسمه الرسول ﷺ في السنة، وليس لهم أن يحدثوا في الدين ما لم يأذن به الله، قال الله جل وعلا: أَمْ لَهُمْْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] وقال النبي ﷺ: وشر الأمور محدثاتها، وكل بدعة ضلالة وقال: وإياكم ومحدثات الأمور؛ فإن كل محدثة بدعة، وكل بدعة ضلالة وتقدم قوله ﷺ: من عمل عملاً ليس أمرنا عليه فهو رد أي: فهو مردود.\nأما قول عمر: «نعمت البدعة » فقد أوضح أهل العلم أن مراده بذلك من حيث اللغة العربية؛ لأنه رضي الله عنه جمع الناس على إمام واحد وكانوا متفرقين في عهد النبي ﷺ وفي عهد الصديق ، فلما كان عهده رضي الله عنه جمعهم على إمام واحد ومر عليهم ذات ليلة وهم يصلون فقال: «نعمت هذه البدعة »، يعني: جمعه لهم على إمام واحد مستمر منتظم، وكان الرسول صلى الله عليه وسلم قد جمعهم وصلى بهم في ليالي، ثم ترك ذلك خوف أن تفرض عليهم عليه الصلاة والسلام، فأصل التراويح سنة، أصلها سنة؛ فعلها النبي صلى الله عليه وسلم ودعا إليها وحث عليها، لكن خاف أن تفرض على الناس، فترك بعدما صلاها ليالي عليه الصلاة والسلام بالناس جماعة، ثم استمر الترك إلى عهد عمر ، وكان يصلون في المسجد أوزاعاً، يصلي الرجل بنفسه، ويصلي معه الاثنان والثلاثة إلى أشباه ذلك.\nفلما رآهم عمر ذات ليلة قال: «لو جمعناهم على إمام واحد» ثم جمعهم، فلما رآهم بعد ذلك يصلون جميعاً قال: «نعمت هذه البدعة» يعني: التي هي جمعهم على إمام واحد بصفة مستمرة، فهذا من حيث اللغة؛ لأن البدعة: ما كان على غير مثال سابق، فهذا من حيث اللغة العربية، وليس مقصوده أن هذه بدعة في الأساس والأصل، فإنه رضي الله عنه لا يمكن أن يوجد البدع ولا يقر البدع، وهو يعلم أن الرسول نهى عن البدع عليه الصلاة والسلام.\nوهذه سنة وقربة وطاعة معروفة في عهده صلى الله عليه وسلم وبعد ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4961/الرد-على-من-يقول-ان-بعض-البدع-من-السنن-الحسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04406.mp3","categories":["البدع والمحدثات"]},{"id":7788,"question":"سماحة الشيخ! هذه رسالة وردتنا من الطائف يقول مرسلها (ع. م): إلى فضيلة الشيخ عبد العزيز بن باز المحترم، بعد التحية والتقدير: نرجو من فضيلتكم أن تهدونا إلى الصواب بمشيئة الله، تسأل أختكم عن كتاب يسمى: (راتب الحداد) يلزم قرأته كل ليلة، ويبدأ الكتاب بآية من القرآن هي: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا [الأحزاب:41]، وبعدها سورة فاتحة الكتاب، فآيات قرآنية وتسبيح وتكبير وتهليل وتوحيد كثير، وفي آخر الكتاب دعاء يقول: الفاتحة لسيدي محمد بن علي وأصوله وفروعه وآل بعلاوي صغيرهم وكبيرهم إن الله يحمينا بحمايتهم وينورنا بهداهم، وأن نراهم في الدنيا والآخرة.والفاتحة الثانية تقول: الفاتحة لسيدنا وقدوتنا وعمدتنا سيدي عبد الله صاحب الراتب أن الله يقدس روحه في الجنة، ويوجد في آخر الكتاب تسبيح وتهليل وتكبير ودعاء، ويختتم بالصلاة على النبي صلى الله عليه وسلم. والسؤال هو: هل يجوز قراءة هذا الكتاب أم لا، أفيدونا جزاكم الله عنا خيراً؟","title":"حكم قراءة الأوراد البدعية في كتب الصوفية وغيرها","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا السؤال عن (راتب الحداد) الذي بدأه بالآية الكريمة: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا [الأحزاب:41]، وذكر بعد ذلك الفاتحة وآيات، ثم ذكر في آخره الفاتحة لسيده محمد بن علي .. إلى آخره، والفاتحة لفلان صاحب الراتب: عبد الله الحداد ، هذا الكتاب لم أطلع عليه، وهذه الرواتب التي يجيدها كثير من الناس لا تخلو في الغالب من بدع وخرافات لا أساس لها، وهذا الراتب الذي يظهر مما ذكرتيه أيها السائلة! أنه لا يخلو من بدع وخرافات، فلا ينبغي أن يتخذ ورداً بل ينبغي للمؤمن أن يتخذ الورد مما ورد عن النبي ﷺ في الأحاديث الصحيحة، وأهل السنة والحمد لله قد أوضحوا ما ورد عنه صلى الله عليه وسلم من آيات وأشياء يقولها في الصباح والمساء، ينبغي للمؤمن أن ينظر فيها وأن يتحفظ منها ما تيسر من كتاب رياض الصالحين، ومن كتاب الأذكار للنووي ، والوابل الصيب لـابن القيم ، وغيرها من الكتب المؤلفة في أذكار الصباح والمساء، ففيها الكفاية عما أحدثه الناس، واستعمال الفاتحة لفلان أو لفلان بدعة لا أساس لها، فينبغي الحذر من هذه الكتب المؤلفة في أذكار الصباح والمساء إلا ما كان صاحبه يعتني فيه بأحاديث الرسول ﷺ، ويذكر ما كان يفعله ﷺ ويقوله في الصباح والمساء، هذا هو المعتمد، المعتمد هو الذي يثبت عن النبي ﷺ من الدعوات والأذكار في الصباح والمساء، مما يذكره أهل العلم في كتبهم المؤلفة في هذا الشأن مثلما تقدم رياض الصالحين وأذكار للنووي ، كتاب الوابل الصيب لـابن القيم ، وهكذا ما يذكر في الصحيحين في البخاري ومسلم وفي السنن وغيرها، ينتقى من هذا ما ثبت وما صح ويكفي، ولشيخ الإسلام ابن تيمية رحمه الله كتاب يسمى: (الكلم الطيب) ذكر فيه جملة من هذا أيضاً، فينبغي للمؤمن والمؤمنة أن يتوخيا ما صح عن النبي ﷺ في هذا الباب من كتب الحديث، أما الأوراد التي يذكرها الصوفية كـالحداد وغير الحداد فلا ينبغي اعتمادها ولا ينبغي التعويل عليها؛ لأنها لا تخلو في الغالب من أحاديث موضوعة أو أحاديث ضعيفة لا يعول عليها، أو بدع يأتون بها من عند أنفسهم وينظمونها من عند أنفسهم ليس لها أصل، والله المستعان.","link":"https://binbaz.org.sa/fatwas/5132/حكم-قراءة-الاوراد-البدعية-في-كتب-الصوفية-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_049/04900.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":7792,"question":"سماحة الشيخ! هذه رسالة وردتنا من الطائف يقول مرسلها (ع. م): إلى فضيلة الشيخ عبد العزيز بن باز المحترم، بعد التحية والتقدير: نرجو من فضيلتكم أن تهدونا إلى الصواب بمشيئة الله، تسأل أختكم عن كتاب يسمى: (راتب الحداد) يلزم قرأته كل ليلة، ويبدأ الكتاب بآية من القرآن هي: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا [الأحزاب:41]، وبعدها سورة فاتحة الكتاب، فآيات قرآنية وتسبيح وتكبير وتهليل وتوحيد كثير، وفي آخر الكتاب دعاء يقول: الفاتحة لسيدي محمد بن علي وأصوله وفروعه وآل بعلاوي صغيرهم وكبيرهم إن الله يحمينا بحمايتهم وينورنا بهداهم، وأن نراهم في الدنيا والآخرة.والفاتحة الثانية تقول: الفاتحة لسيدنا وقدوتنا وعمدتنا سيدي عبد الله صاحب الراتب أن الله يقدس روحه في الجنة، ويوجد في آخر الكتاب تسبيح وتهليل وتكبير ودعاء، ويختتم بالصلاة على النبي صلى الله عليه وسلم. والسؤال هو: هل يجوز قراءة هذا الكتاب أم لا، أفيدونا جزاكم الله عنا خيراً؟","title":"حكم قراءة الأوراد البدعية في كتب الصوفية وغيرها","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا السؤال عن (راتب الحداد) الذي بدأه بالآية الكريمة: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا [الأحزاب:41]، وذكر بعد ذلك الفاتحة وآيات، ثم ذكر في آخره الفاتحة لسيده محمد بن علي .. إلى آخره، والفاتحة لفلان صاحب الراتب: عبد الله الحداد ، هذا الكتاب لم أطلع عليه، وهذه الرواتب التي يجيدها كثير من الناس لا تخلو في الغالب من بدع وخرافات لا أساس لها، وهذا الراتب الذي يظهر مما ذكرتيه أيها السائلة! أنه لا يخلو من بدع وخرافات، فلا ينبغي أن يتخذ ورداً بل ينبغي للمؤمن أن يتخذ الورد مما ورد عن النبي ﷺ في الأحاديث الصحيحة، وأهل السنة والحمد لله قد أوضحوا ما ورد عنه صلى الله عليه وسلم من آيات وأشياء يقولها في الصباح والمساء، ينبغي للمؤمن أن ينظر فيها وأن يتحفظ منها ما تيسر من كتاب رياض الصالحين، ومن كتاب الأذكار للنووي ، والوابل الصيب لـابن القيم ، وغيرها من الكتب المؤلفة في أذكار الصباح والمساء، ففيها الكفاية عما أحدثه الناس، واستعمال الفاتحة لفلان أو لفلان بدعة لا أساس لها، فينبغي الحذر من هذه الكتب المؤلفة في أذكار الصباح والمساء إلا ما كان صاحبه يعتني فيه بأحاديث الرسول ﷺ، ويذكر ما كان يفعله ﷺ ويقوله في الصباح والمساء، هذا هو المعتمد، المعتمد هو الذي يثبت عن النبي ﷺ من الدعوات والأذكار في الصباح والمساء، مما يذكره أهل العلم في كتبهم المؤلفة في هذا الشأن مثلما تقدم رياض الصالحين وأذكار للنووي ، كتاب الوابل الصيب لـابن القيم ، وهكذا ما يذكر في الصحيحين في البخاري ومسلم وفي السنن وغيرها، ينتقى من هذا ما ثبت وما صح ويكفي، ولشيخ الإسلام ابن تيمية رحمه الله كتاب يسمى: (الكلم الطيب) ذكر فيه جملة من هذا أيضاً، فينبغي للمؤمن والمؤمنة أن يتوخيا ما صح عن النبي ﷺ في هذا الباب من كتب الحديث، أما الأوراد التي يذكرها الصوفية كـالحداد وغير الحداد فلا ينبغي اعتمادها ولا ينبغي التعويل عليها؛ لأنها لا تخلو في الغالب من أحاديث موضوعة أو أحاديث ضعيفة لا يعول عليها، أو بدع يأتون بها من عند أنفسهم وينظمونها من عند أنفسهم ليس لها أصل، والله المستعان.","link":"https://binbaz.org.sa/fatwas/5132/حكم-قراءة-الاوراد-البدعية-في-كتب-الصوفية-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_049/04900.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":7878,"question":"من العراق وردتنا هذه الرسالة من مريم المرسلة مريم تقول فيها: هل أن الصندوق لوضع الموتى حرام على النساء أو الرجال هذا، ولفضيلتكم جزيل الشكر؟","title":"حكم استخدام الصناديق في دفن الموتى","answer":"الجواب: المشروع للموتى أن يدفنوا في التراب ولا يجعلوا في الصناديق، الصندوق ما فعله النبي ﷺ ولا فعله أصحابه رضي الله عنهم وأرضاهم، هذا خلاف السنة فلا ينبغي فعله؛ لأنه خلاف سنة نبينا ﷺ وخلاف ما فعله أصحابه وأهل العلم بعدهم.\nفالسنة أنه يكفن في ثلاثة أثواب بيض للرجل هذا هو الأفضل، وإن كفن في غيرها في سوداء أو خضراء أو زرقاء جاز، وإن كفن في ثوب واحد حتى ستره جميعه فلا بأس، لكن لا يوضع في صندوق بل يوضع على التراب، يوضع في اللحد على التراب ويوضع عليه اللبن الذي يسد اللحد، ثم يهال عليه التراب كما فعله نبينا ﷺ وفعله المسلمون، أما وضع الموتى في التوابيت والصناديق هذا لا أصل له، ولا ينبغي فعله. نعم.","link":"https://binbaz.org.sa/fatwas/5343/حكم-استخدام-الصناديق-في-دفن-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_057/05702.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7894,"question":"أيضاً يقول: إذا توفي إنسان يوم الخميس، بقي عند قبره أصدقاء أقاربه بحجة تسليمه لليلة الجمعة، فما هو الحكم؛ لأنه يقول: إنه إذا توفي عندنا الإنسان قبل الجمعة فإنه لا يترك إلا أن يسلم ليوم الجمعة، نرجو التوضيح في ذلك؟","title":"حكم مكث أقارب الميت عند قبره إلى ليلة الجمعة","answer":"الجواب: جلوس بعض أقارب الميت أو غيرهم عند الميت إذا مات في يوم خميس حتى يسلموه ليلة الجمعة هذا لا أصل له، هذا من البدع.\nبل إنما السنة أن يوقف عليه بعد الدفن يدعى له بالمغفرة والثبات، وقفة ما يسر الله من الوقفة، للدعاء له بالمغفرة والثبات ثم ينصرف الناس، سواء كان في يوم الخميس أو في غيره، أما أن يقف عنده أقارب الميت أو جيرانه، إلى ليلة الجمعة أو في بعض الليالي الأخرى وقفات خاصة، هذا لا أصل له إنما الوقفة بعد الدفن للدعاء له وسؤال الله المغفرة والثبات؛ لأن النبي ﷺ إذا فرغ من دفن الميت وقف عليه، النبي عليه الصلاة والسلام: كان إذا فراغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم وسلوا له التثبيت فإنه الآن يسأل.\nفيقف ويستحب للمشيعين إذا فرغوا من الدفن أن يقفوا على الميت، وأن يدعوا له بالمغفرة والثبات ما شاء الله من الوقفة، ولا يلزمهم ولا يشرع لهم أن يقفوا طويلاً كثيراً حتى يسلموه ليلة الجمعة أو في ليالي أخرى بطريقة خاصة لا، إنما هذه وقفة للدعاء بالمغفرة والثبات فقط بعد الدفن، وقفة ليس لها حد محدود، بل وقفة لا تضرهم ولا تشق عليهم ثم ينصرفون.","link":"https://binbaz.org.sa/fatwas/5375/حكم-مكث-اقارب-الميت-عند-قبره-الى-ليلة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7941,"question":"يقول: في حضرموت يذهب الناس في وقت محدود من كل سنة إلى زيارة أحد القبور يقولون: إنه قبر النبي هود الكائن في شعب هود ، وهناك تتم الصلاة وتتم الزيارة والقراءة والبيع والشراء فما حقيقة ذلك، وهل قبر النبي هود هناك أم لا؟","title":"حكم زيارة القبور والطواف حولها ودعاء أصحابها والبناء عليها","answer":"الجواب: لا شك أن هود عليه الصلاة والسلام كان في الأحقاف وكان منزلهم هناك بعثه الله إلى قومه هناك، ولكن لا يعلم قبره ولا يدرى عنه، وليس هناك ما يدل على وجوده هناك، فالذين يقصدون قبراً هناك ليس معهم حجة على أنه قبر هود ولا يحفظ قبر معلوم للأنبياء سوى قبر نبينا محمد ﷺ فهو المحفوظ في المدينة، وهكذا قبر إبراهيم في المغارة في الشام في محله المعروف هناك من دون أن يعلم عينه لكنه موجود في المغارة المعروفة هناك في الخليل، وأما بقية الأنبياء فلا تعلم قبورهم لا هود ولا صالح ولا نوح ولا غيرهم كلهم لا تعلم قبورهم، فمن زعم أن قبر هود في بقعة معينة هناك وأشار إليه بأنه هذا المحل المعين فليس معه حجة وليس معه دليل، فقبور الأنبياء لا تعرف ما عدا قبر نبينا ﷺ وقبر إبراهيم عليه الصلاة والسلام.\nثم لو فرضنا أنه صحيح وأنه قبر هود فإنه لا يجوز شد الرحال إليه للسلام عليه أو الصلاة عنده أو غير ذلك، لكن لو مر إنسان به وهو يعلم أنه قبره وسلم عليه فلا بأس، كما يسلم على نبينا محمد عليه الصلاة والسلام، أما أن يزار بشد الرحال فلا، قال النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا، والمسجد الأقصى.\nفلا يشد الرحل لقبر أي أحد لا قبر هود ولا غيره، ثم لو فرض أنه مر عليه وزاره فليس له أن يصلي عند القبر، الصلاة لا تجوز عند القبور، الرسول ﷺ نهى عن ذلك قال: ألا وإن من كان قبلكم كانوا يتخذونن قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك، فالصلاة عند القبر اتخاذ له مسجد، فلا يجوز الصلاة عند القبور ولا اتخاذها مساجد.\nلو فرضنا أنه علم أنه قبر هود أو غيره فلا يجوز للمسلمين أن يشدوا الرحال من أجل زيارة القبور لا قبر هود ولا غيره، وليس للمسلمين أيضاً أن يصلوا عند القبور، ولا أن يتخذوا عليها مساجد؛ لأن الرسول زجر عن ذلك عليه الصلاة والسلام فقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا، وقال أيضاً عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك.\nفصرح ﷺ أنه ينهى عن اتخاذ القبور مساجد، والصلاة عندها اتخاذ لها مساجد، فلا يجوز لأي مسلم أن يفعل ذلك، فلا يشد الرحل إلى القبر -أي قبر كان- ولا يصلي عنده، أما إذا مر عليه أو صار في البلد وزاره للسلام على القبور فهذا سنة، النبي عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة، لكن من دون شد رحل، ومن دون أن تتخذ مساجد ويصلى عندها أو تجعل محل قراءة والدعاء لا، يزورها ويسلم على المقبورين ويدعو لهم وينصرف.\nكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي لفظ: يرحم الله المستقدمين منا والمستأخرين، فهذه السنة أن تزار القبور من دون شد رحل، يسلم عليهم ويدعى لهم بالرحمة والمغفرة، ولك معهم، وفي زيارة القبور ذكرى وعبرة، فإن الزائر يتذكر الموت وما بعد الموت ويعتبر ويدعوه هذا إلى إعداد العدة، والتأهب إلى الآخرة، أما اتخاذها مساجد أو اتخاذها محلاً للدعاء والقراءة فلا، هذا لا يجوز وليست محلاً للدعاء ولا للقراءة ولا الصلاة، ولكن يسلم عليهم ويدعو لهم بعرض السلام، ويكفي ذلك كما علمنا الرسول ﷺ وبين لنا وحذرنا من خلاف ذلك، فشد الرحال للقبور منكر ولا يجوز، وهكذا الصلاة عندها واتخاذها مساجد والبناء عليها، واتخاذ القباب عليها كل هذا منكر.\nولا ينبغي لك أيها السائل ولا لغيرك أن يغتر بالناس، فإن أكثر الناس اليوم ليس عندهم بصيرة وإنما تحكمهم العادات وما ورثوه عن الآباء والأجداد، فاتخاذ المساجد على القبور اليوم في بعض الدول الإسلامية واتخاذ القباب عليها كله منكر كله من وسائل الشرك، النبي ﷺ نهى عن هذا قال: لعن اللهه اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، يحذرنا من أعمالهم.\nوكذلك نهى عن تجصيص القبور والقعود عليها والبناء عليها، فلا يجوز أن تجصص ولا أن يبنى عليها قبة ولا غيرها، ولا يتخذ عليها مسجد؛ لأن هذا كله مصادم لما جاء عنه عليه الصلاة والسلام؛ ولأنه أيضاً وسيلة من وسائل الشرك والغلو في القبور.\nفالواجب على رؤساء الدول الإسلامية الواجب عليهم أن يزيلوا ما على القبور من أبنية من قباب ومساجد وأن تكون القبور بارزة ليس عليها قبة وليس عليها مسجد، هذا هو الواجب في جميع الدول الإسلامية، الواجب عليهم جميعاً أن يبرزوا القبور وأن يزيلوا ما عليها من مساجد وقباب وأبنية طاعة للرسول صلى الله عليه وسلم، وامتثالاً لأمره، وعملاً بشرعه عليه الصلاة والسلام.\nوأيضاً في ذلك سد ذرائع الشرك وحسم موادها؛ لأن الناس إذا رأوا قبراً مشيداً معظماً بالقباب والبناء والفرش غلت فيه العامة وظنت أنه ينفع ويضر، وأنه يستجيب الداعي، وأنه يشفي المريض، وأنه يتوسط بينه وبين الله؛ فيقع الشرك بالله نعوذ بالله كما قد وقع لعباد القبور في الزمن الأول، فإنهم عظموا القبور وزعموا أن أهلها شفعاء عند الله، ودعوهم واستغاثوا بهم، وهذا هو الشرك الأكبر نسأل الله العافية.\nوهذا واقع اليوم في كثير من البلاد الإسلامية، واقع فيها هذا الغلو في القبور كما يقع في مصر عند قبر البدوي والحسين وغيرهما، وكما قد يقع في الشام عند قبر ابن عربي وغيره، وكما قد يقع في العراق عند قبر موسى الكاظم وأبي حنيفة وغيرهما، وكما قد يقع من بعض الجهال عند قبر النبي في المدينة عليه الصلاة والسلام، بعض الجهال من الحجاج والزوار، قد يقع منهم الشرك عند قبر النبي ﷺ يقول: يا رسول الله! اشف مريضي.. انصرني.. المدد المدد.. اشفع لي، وهذا لا يجوز، لا مع النبي ولا مع غيره من الأموات عليه الصلاة والسلام، وإنما هذا في حياته، في حياته يقال: اشفع لي يا رسول الله، يعني: ادعوا لنا، وهكذا يوم القيامة إذا قام الناس من قبورهم يأتيه المؤمنون ويسألونه أن يشفع لهم إلى الله، حتى يحكم بينهم وحتى يدخلوا الجنة، أما بعد الموت وقبل البعث في حال البرزح فلا، لا يطلب منه الشفاعة، ولا يجوز أن يطلب منه المدد ولا غوث ولا نصر على الأعداء؛ لأن هذا بيد الله سبحانه وتعالى، ليس بيد الأنبياء ولا غيرهم، بل النصر والشفاء للمرضى والغوث والمدد كله بيد الله سبحانه وتعالى.\nوهكذا قد يقع من بعض الجهلة عند قبر خديجة في المحلاة في مكة المكرمة إلا إذا لوحظوا ووجهوا وبين لهم ما يجب عليهم، فأنت -أيها السائل- ينبغي لك أن تحذر هذه المسائل وأن تكون على بينة، وأن تعلم أن القبور -لا قبر هود ولا غيره- لا يجوز أن تتخذ معابد مصلى مساجد، لا، ولا أن تدعى مع الله، ولا أن يستغاث بأهلها، ولا يطاف بقبورهم، ولا أن يبنى عليها قبة، ولا أن تفرش، ولا أن تطيب، كل هذا لا يجوز؛ لأنه من وسائل الشرك، ودعاء الميت وطلب الغوث منه والمدد وشفاء المريض هذا كله شرك بالله عز وجل. نعم.","link":"https://binbaz.org.sa/fatwas/5467/حكم-زيارة-القبور-والطواف-حولها-ودعاء-اصحابها-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_067/06705.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":7946,"question":"يقول في سؤاله الثالث والأخير: هل في ذكر مشروع عند الذهاب بالجنازة إلى القبر من تهليل أو تكبير، وماذا يلزم تابع الجنازة والحاملين لها أصلحكم الله ودمتم سالمين؟","title":"حكم التهليل والتكبير أثناء اتباع الجنازة","answer":"الجواب: لا أعلم في هذا شيئاً مشروعاً إلا التفكير والنظر في الموت وعواقب الموت وما بعد الموت، يكون التابع للجنازة يفكر في هذه الأمور وأنه صائر إلى ما صار إليه هذا الميت حتى يعد العدة، أما ما يفعله بعض الناس من قول: اذكروا الله.. وحدوا الله هذا لا أصل له، كان عادة السلف عند اتباع الجنائز الصمت والتفكير والنظر في عواقب الأمور ونهاية الإنسان، وأن منتهاه هو منتهى هذا الرجل الذي هو يتبعه، فهذا يوجب التفكير والنظر والعبرة، وأما الكلام فلا يشرع في هذا كلام فيما أعلم، والذي يفعله بعض الناس من قولهم: وحدوه.. اذكروا الله، هذا كله لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/5472/حكم-التهليل-والتكبير-اثناء-اتباع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06803.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7994,"question":"طيب بالنسبة لهذه المناسبة القراءة في المسجد هناك في بعض الدول الإسلامية في يوم الجمعة يقوم شخص على مكان مرتفع ويقرأ القرآن بتجويد والآخرين ينصتون إليه ولا يقرءون، فهل هذا مسنون أم لا؟","title":"حكم قراءة القرآن بصوت مرتفع يوم الجمعة","answer":"الجواب: ما نعلم له أصل، هذا أشبه بالبدع، أقول: هذا أشبه بالبدع، أقول هذا غير مشروع فيما نعلم؛ لأن هذا يمنع الناس من القراءة قد يريد بعض الناس يقرأ قد يريد يصلي يشوش عليه إذا دخل يصلي ركعتين أو أكثر، فالأولى أن كل إنسان يقرأ لنفسه، أما لو كانوا في مكان مخصوص مجتمعين مثلما كان النبي صلى الله عليه وسلم يقرأ عليهم وهم يستمعون له فلا بأس، أو كانت جماعة محدودة في المسجد وأحبوا أنهم يستمعون له حتى يدخل الخطيب فلا بأس، أما واحد يقوم على المنبر يقرأ على الناس فهذا لا وجه ولا ينبغي.\nأو في غير المنبر ... يجهر جهراً يضر غيره، ويشوش على المصلين الداخلين وعلى القراء كل هذا لا يصلح، وليس له أصل فيما نعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5562/حكم-قراءة-القران-بصوت-مرتفع-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07405.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":8123,"question":"كثيرون سماحة الشيخ هم الذين يسألون عن إعادة صلاة الظهر بعد صلاة الجمعة ومن بينهم صاحب هذه الرسالة يقول: ما حكم إعادة صلاة الظهر بعد صلاة الجمعة هل هي واجبة أم مندوبة، لأنه عندنا الإمام يقوم بإعادة صلاة الظهر بعد صلاة الجمعة ويقول: خوفًا من قبول صلاة الجمعة وذلك لعدم توفر جميع أركان الجمعة، أفيدونا أفادكم الله؟","title":"حكم إعادة صلاة الظهر عقب صلاة الجمعة","answer":"الجواب: إعادة صلاة الظهر بعد صلاة الجمعة أمر محدث لم يكن في عهد أصحاب النبي ﷺ ولا في عهد التابعين لهم بإحسان، والجمعة تكفي عن الظهر وهي فرض الوقت، فلا يجوز أن يجمع بينهما، الله فرض علينا خمس صلوات في يوم الجمعة وفي غير يوم الجمعة، في يوم الجمعة خمس: الفجر والجمعة والمغرب والعشاء، هذه خمس، الفجر والجمعة والعصر والمغرب والعشاء خمس فروض، فإذا صلى ظهراً بعد الجمعة فقد زاد سادسة، فلا وجه لذلك فهي بدعة، ونرجو ممن يتعاطى هذا من أهل العلم أن يعيدوا النظر وأن يتبصروا في الأدلة ومتى أعادوا النظر وفقهم الله للبصيرة في هذا، أرجو من إخواني أهل العلم الذين يفعلونها أن يعيدوا النظر، الرسول عليه السلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته من حديث عائشة رضي الله عنها.\nفالواجب على أهل العلم الذين يعيدونها أن يتقوا الله وأن يتركوا هذه الإعادة فإنها بدعة لا وجه لها، ومتى صليت الجمعة أجزأت عن الظهر، وإذا كان عندهم شك في الجمعات ولهم النظر في الموضوع ليس إلى غيرهم فلينظروا، فالجمعة التي لا حاجة إليها تلغى، والجمعة التي لها حاجة تبقى، أما مجرد الظنون والشكوك والأوهام فلا وجه لها، الأصل أن هذه الجمعة إنما أقيمت للحاجة إليها، إما للتباعد وإما لكون الجمعة الموجودة أو إما لكون المسجد الموجود يضيق بالناس ولا يسعهم أو لأسباب أخرى اقتضاها الشرع.\nفالأصل أن هذه الجمعات مجزئة هذا هو الأصل فلا يجوز ظن السوء وحمل الناس على أنهم صلوا جمعة غير صحيحة؛ هذا سوء ظن لا وجه له بل يجب حمل الناس على أحسن المحامل وأن هذه الجمعة إنما أقيمت للحاجة إليها فلا حاجة إلى صلاة الظهر بعدها، والرسول ﷺ قال في الحديث الصحيح: وشر الأمور محدثاتها وكل بدعة ضلالة يقول ﷺ: (أما بعد) -يقول في خطبة الجمعة كما روى مسلم في الصحيح- أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها وكل بدعة ضلالة، فليس للعالم ولا لغير العالم أن يحدث في دين الله ما ليس منه، ولكن الخطر على العالم أكثر لأنه يقتدى به، والواجب أن ينظر وأن يتأمل حتى يحكم فيما فعل على بصيرة ولا شك أن هذه بدعة لا وجه لها، فالواجب تركها على العالم وغير العالم. نعم.\nالمقدم: جزاكم الله خيراً، من أين تسرب هذا الشك سماحة الشيخ؟\nالشيخ: لأنه هناك خلاف بين العلماء في إقامة الجمعة الثانية والثالثة والرابعة، بعض أهل العلم يقول: لابد في المدينة من جمعة واحدة ولا حاجة إلى جمعات وهذا قول خاطئ؛ لأن المدن تختلف فليس كل مدينة يكفيها جمعة واحدة، بعض المدن بين أطرافها مسافات طويلة والمسجد لا يسع من حوله من الناس ولا يسع من بعد عنه ولا يستطيعون المجيء إليه، فلهذا قرر العلماء رحمة الله عليهم إقامة جمعات في بلاد واحدة، اتسعت البلد وتباعدت أطرافها وكثر سكانها يكون في كل حي منها جمعة يكفي أهله، هذا هو الواجب وهذا الذي قد تقرر عند أهل العلم، فإذا وجدت الأسباب كالتباعد أو ضيق المسجد أو صارت البلد فيها قبيلتان أو قبائل بينهم تشاحن ما يستطيعون أن يجتمعوا في مسجد واحد يخشى أن يقع بينهم فتنة جعل لكل قبيلة مسجد يخصهم دفعاً للفتن، هذا كله من الأسباب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5919/حكم-اعادة-صلاة-الظهر-عقب-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10304.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":8172,"question":"سؤاله الأخير: هناك بعض الناس يقولون: إن الدعاء واجب، وهو أن يدعو الإمام ويؤمن المصلون فهل هذا صحيح أم لا؟","title":"حكم دعاء الإمام عقب الصلوات وتأمين المأمومين","answer":"الجواب: الدعاء مشروع وليس بواجب لكنه مشروع، الإنسان يدعو في صلاته وفي غير صلاته يدعو الله ويجتهد في الخير يسأل ربه المغفرة والرحمة وصلاح النية والعمل، يسأل ربه الرزق الحلال، الزوجة الطيبة، الذرية الصالحة، يسأل ربه دخول الجنة والنجاة من النار إلى غير ذلك، لكن يجب أن يقول: ربي اغفر لي عند جمع من أهل العلم، يجب أن يقول: ربي اغفر لي بين السجدتين فقط عند جماعة من أهل العلم، أما بقية الدعاء فهو مستحب، مستحب أن يدعو في آخر الصلاة قبل أن يسلم، يستحب أن يدعو في سجوده، يستحب أن يدعو في خارج الصلاة ويطلب ربه من خير الدنيا والآخرة كل هذا أمر مستحب مطلوب ولا يجب.\nأما ما يفعله بعض الناس من الدعاء بعد السلام إذا سلم من الفريضة دعا الإمام ورفعوا أيديهم وأمنوا جميعاً هذا لا أصل له هذا من البدع ما كان النبي ﷺ وأصحابه إذا أن سلموا يرفعون أيديهم ويدعون ويؤمنون لا، إن شاء يدعو بينه وبين نفسه الإمام يدعو بينه وبين نفسه، المأموم كذلك، النبي ﷺ كان يدعو بعد الصلاة بينه وبين ربه، أما أن يرفع الإمام يديه ويرفعون أيديهم ويدعون جميعاً يدعو الإمام ويؤمنون هذا لا أصل له ولا يجوز بل هو من البدع التي يجب تركها، ولكن يدعو الإنسان لنفسه بعد الذكر بما يسر الله ويدعو الإمام ما يخالف، المنفرد إذا ما صلى مع الجماعة لأسباب فاتته الجماعة أو لأنه مريض أو ما أشبه ذلك يدعو أيضاً بينه وبين نفسه، ولكن الأفضل أن يكون في صلاته في السجود قبل أن يسلم، لأن الرسول عليه السلام لما علمهم التحيات قال: ثم ليتخير من الدعاء أعجبه إليه فيدعو يعني: قبل أن يسلم، وقال عليه الصلاة والسلام: وأما السجود فاجتهدوا في الدعاء،، فقمن أن يستجاب لكم وقال أيضاً عليه الصلاة والسلام أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء.\nفينبغي للمؤمن أن يكثر من الدعاء في سجوده وبين السجدتين وفي آخر الصلاة قبل أن يسلم، وإذا دعا بعد ذلك بعد السلام وبعد الذكر بينه وبين ربه فلا بأس من دون رفع اليدين ومن دون أن يدعو مع الإمام، كل هذا لا أصل له، لكن يدعو بينه وبين ربه لنفسه فقط، من دون رفع اليدين بعد صلاة الفريضة، وهكذا بعد النوافل وإذا رفع يديه في بعض الأحيان بعد النوافل فلا بأس، أو في غير صلاة دعا ربه في أي وقت في غير صلاة دعا ربه ورفع يديه كل هذا مطلوب رفع اليدين من أسباب الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/5975/حكم-دعاء-الامام-عقب-الصلوات-وتامين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10409.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":8182,"question":"أخونا السائل نبيل عبد العزيز علي يحيى لطف يسأل ويقول عندنا في قرية حصن ريمان الناس يذهبون إلى جبل ويأخذون معهم ذبيحة ويذبحونها في الجبل من أجل الله سبحانه وتعالى ولعل الله يرحمهم وينزل عليهم المطر فهل هذا يحل أم لا؟ أفيدونا أفادكم الله، وله سؤال آخر بعد تفضلكم بالإجابة نعرضه إن شاء الله؟","title":"حكم الذهاب إلى جبل لذبح ذبيحة عليه لأجل الاستسقاء","answer":"الجواب: هذا العمل فيه تفصيل فإذا كان الذبح لله وحده وليس هناك مقصود آخر ليس هناك قبر يذبحون عنده وليس هناك اعتقاد آخر في الجبل وإنما فعلوه كذا صدفة من غير قصد فلا حرج والذبيحة لله وحده ولكن لا حاجة إلى مجيء جبل لأن هذا يوهم أن هناك أشياء يذبحونها في بيوتهم أو في أي مكان تذبح فيه الدواب ويكفي لله سبحانه.. تقرباً إلى الله جل وعلا ثم يوزع هذا اللحم على الفقراء والمساكين أو يأكلونه إن كانوا أرادوا الأكلة أو إن كانوا أرادوا الفقراء قسموا بين الفقراء أو أعطوا الفقراء منه ما شاءوا؛ المقصود أن قصدهم الجبل فيه شيء من الإيهام فإذا كان المقصود من الجبل إظهار الذبيحة وأنها تذبح لله على رءوس الأشهاد فلا حاجة إلى قصد الجبل يذبحونها في مكان بارز ويقسمونها بين الفقراء في قريتهم ويكفي ولا يقصدوا الجبل هذا الذي يوهم أنهم أرادوا شيئاً، أما إن كانوا أرادوا في الجبل أن هناك ميتاً مدفوناً هناك أو أن هناك محل لرجال صالحين جلسوا فيه أو غار جلس فيه أناس صالحون فهم يتبركون به هذا لا يجوز فيجب التنبه لهذا وإذا كان المقصود فقط إظهار الذبيحة فإظهارها يكون في أي مكان سواء الجبل ما حاجة إلى الجبل ولو في بيوتهم يذبحونها في محل الذبح أو في حوش عندهم محل الذبح أو في محل حول الطريق يراه الناس ولا يؤذي أحداً من الناس لا بأس، المقصود إظهارها بأي طريق لكن لا يوهم لا يكون إظهاراً يوهم أنه هناك قصداً كقصد جبل معين أو شجرة معينة حتى لا يتهم بالشرك أو ببدعة ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم. سماحة الشيخ! يحكي لنا الآباء عن شيء مثل هذا في منطقتنا قبل أن تنتشر الدعوة من جديد بعد حكم آل سعود يقولون: كانوا يأخذون الأبقار ويلفون بها حول الجبال وحول الأودية وبعد ذلك يذبحون واحدة منها وهم بذلك يريدون الاستسقاء فلعل هذا شبيه بذاك سماحة الشيخ؟\nالشيخ: ما هو ببعيد ليس هذا بعيد وهذا غلط لا أصل له بل هذا من البدع المقصود التقرب إلى الله بصلاة الاستسقاء والدعاء يستغيثون الله ويصلون الصلاة الشرعية وإذا ذبحوا ذبائح وتصدقوا بها أو صاموا أو تصدقوا بنقود أو بأطعمة من الحبوب أو من التمور كل هذا طيب لكن لا يقصد مكاناً يوهم أنهم يتعبدون فيه لأنه قد سكنه رجل صالح أو أقام به رجل صالح أو دفن فيه رجل صالح لا، لا يوهمون هذه الأشياء ولا يقصدون هذه الأشياء، أما كونهم يدورون بهذا الوادي أو في الجبال هذا لا أصل له بل بدعة ولا حاجة إلى هذا، المقصود التقرب إلى الله في أي مكان ذبحوها كفى بقرة أو ناقة أو غنم كل هذا طيب إذا قصدوا به الصدقة والتقرب إلى الله رجاء أن يرحمهم الله كما رحموا الفقراء وأحسنوا فيهم فالصدقة في وقت الاستسقاء مطلوبة، الصدقات أيام الاستسقاء مطلوبة لأن الله جل وعلا يرحم عباده الرحماء، والنبي يقول ﷺ: إنما يرحم الله من عباده الرحماء من لا يرحم لا يرحم.\nفإذا تصدقوا على الفقراء بالنقود أو بالذبائح أو بالملابس أو بالأطعمة وقت الحاجة وقت الجدب هذا من أسباب الرحمة من أسباب رحمة الله لهم لما رحموا عباده.","link":"https://binbaz.org.sa/fatwas/5989/حكم-الذهاب-الى-جبل-لذبح-ذبيحة-عليه-لاجل-الاستسقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10510.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":8190,"question":"سؤاله الثاني يقول: أسأل عن مولد النبي محمد ﷺ، نحن عندنا عندما يموت شخص، وبعد ثلاثة أيام يقومون أهل الميت يعملون مولد للنبي محمد ﷺ، أو بعد شهر يعملون، أو بعد سنة يذبحون بقرة، أو يشترون لحم ويعملون أكل ويوزعونه على القرية، وبعد ذلك يعملون مولد النبي محمد ﷺ، هل هذا جائز أو سنة، أو الأصحاب فعلوا ذلك، أو أحد من السلف، نرجو توضيح ذلك لنا جزاكم الله عن المسلمين خيراً؟","title":"هل يجوز الاحتفال بالموالد؟","answer":"الجواب: الاحتفال بالموالد من البدع المحدثة في الدين، ولا فرق بين مولد النبي عليه الصلاة والسلام وغيره، فإن الرسول ﷺ وهو أفضل الخلق، وهو المعلم، وهو الناصح، لم يحتفل بمولده عليه الصلاة والسلام، وهكذا خلفاؤه الراشدون لم يحتفلوا بالمولد، وهكذا بقية الصحابة رضي الله عنهم وأرضاهم، هم أعلم الناس وهم أكمل حباً منا للنبي ﷺ، هم أعلم بالسنة، ومع هذا لم يحتفلوا بالمولد، فدل ذلك على أنه بدعة، والبدع كلها ضلالة، كما قاله النبي ﷺ: كل بدعة ضلالة، وقد مضت القرون المفضلة الثلاثة ولم يحتفل بالمولد، ولا فعله أحد من السلف الصالح، فعلم بذلك أنه بدعة، وأن هذا مما أحدثه الناس من بعد القرون المفضلة، ويقال: إن أول من أحدثه حكام مصر من العبيدين المعروفين، وهم من الشيعة فيما ذكر جماعة من المؤرخين، أحدثوه في المائة الرابعة، ويقال: إن أول من أحدثه ملك إربل، وبكل حال فهو محدث وبدعة لا أصل له، وقد زعم بعض الناس، في بعض القرون الماضية وفي عصرنا هذا، زعموا أنه سنة، وأنه لا بأس به، وأنه من البدع الحسنة، وهذا قول فاسد لا وجه له بل هو فاسد، وفيه في الحقيقة اعتراض على الرسول صلى الله عليه وسلم وأصحابه، وهم أعلم الناس وأفضل الناس، ولم يفعلوا هذه البدعة، فالواجب ترك ذلك، وفي الإمكان أن تدرس السيرة في الحلقات العلمية، وفي الدروس اليومية والأسبوعية، فيتعلم الناس السنة، سنة النبي ﷺ، وما كان عليه من أعمال وأقوال، كما يتعلمون أحكام الشريعة التي جاء بها عليه الصلاة والسلام، هذا هو المطلوب في الدروس المدرسية، في الحلقات العلمية في المساجد، في الوعظ والتذكير، تعلم فيه السنة والسيرة، ويذكر فيه المولد وما حدث في المولد، كل هذا ممكن، وهو شاف كاف، أما إيجاد موالد يحتفل بها، ويقام فيها موائد الطعام وغير ذلك، هذا لا أصل له، بل هو من البدع المحدثة، وكل بدعة ضلالة، ولا ينبغي لعاقل أن يغتر بفعل الناس، فإن فعل الناس ليس بحجة، وأكثر الناس ليسوا على بصيرة في أمور الدين، قال الله تعالى: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، فالعمدة الحجة والدليل، وقد قال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، وقال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد، والدراسة لأحوال النبي ﷺ وسيرته، وما جرى في مولده وفي هجرته، كل هذا يفعله العلماء في المدارس، وفي الحلقات العلمية، وفي التذكير والمواعظ، من غير حاجة إلى إقامة الموالد التي ابتدعها المبتدعون، ويقع فيها في بعض الأحيان من الشرك والغلو ما لا يعلمه إلا الله، يقع فيها أنواع من الشرك، كذلك يقع فيها أنواع من الشرور في بعض الأحيان، فيجب قفل هذا الباب وسد هذا الباب، وأن يكتفى بالدروس الإسلامية في المساجد، وفي حلقات العلم، وفي التذكير والوعظ في جميع شئون الدين، وفي كل ما يتعلق بالسنة وأحكامها، هذا هو الحق، وما فعله بعض الناس اليوم وقبل اليوم من الاحتفالات بمولد النبي ﷺ، أو بمولد البدوي ، أو الشيخ عبد القادر ، أو فلان، أو فلان كله بدعة، كله لا أصل له، والواجب تركه عملاً بقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد، وبقوله عليه الصلاة والسلام: كل بدعة ضلالة. نعم.","link":"https://binbaz.org.sa/fatwas/5997/هل-يجوز-الاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09203.mp3","categories":["البدع والمحدثات"]},{"id":8289,"question":"سؤالها الآخر تقول: المعروف بالنسبة للنساء في العراق إذا شخص مات تلبس عليه ثوباً أسوداً لمدة سنة كاملة، وإذا لم تلبس يقولون عليها: بأنها فرحت بموت ذلك الشخص، وكلام الناس لا ينتهي ولا يدعون الناس في حالهم، وأنا علمت أن هذا لا يجوز، فماذا تقولون لو تكرمتم في هذا عسى أن يستفيد الناس ويعملوا؟","title":"لبس المعتدة للثوب الأسود سنة كاملة","answer":"الجواب: هذا الذي ذكرت هو مثلما ذكرت لا يجوز، كونها تحاد سنة كاملة في ثوب أسود هذا لا أصل له، هذا من عمل الجاهلية، كانت الجاهلية تحاد المرأة فيهم إذا مات زوجها سنة كاملة، فأبطل ذلك الإسلام وأخبر النبي ﷺ أن هذا من سنة الجاهلية، وأوجب الله على المرأة بدلاً من ذلك أربعة أشهر وعشراً إذا كانت غير حامل، أما إن كانت حبلى فإنها تنتهي من العدة بوضع الحمل، ولو بعد موت زوجها بساعات أو أيام، أما أن تعتد سنة أو في لباس خاص أسود فقط هذا لا أصل له، بل هو من عمل الجاهلية، فلها أن تلبس الأسود والأصفر والأخضر والأزرق، لكن تكون ملابس غير جميلة تكون عادية لا تلفت النظر؛ لأنه ﷺ نهى المحادة أن تلبس شيئاً من الثياب الجميلة المصبوغة، قال: إلا ثوب عصب، فقال أهل العلم: إن ثوب العصب ليس فيه جمال، فالمشروع لها أن تلبس ثياباً ليس فيها جمال؛ لأنها تعرضها للفتنة، تكون ملابسها ملابس عادية لا تلفت النظر، هذا هو المشروع للمحادة، كما أنه يجب عليها أن تتجنب الطيب مدة العدة، وكذلك الحلية من الذهب والفضة ونحوها كاللؤلؤ والماس وأشباه ذلك مدة العدة، وهكذا تجتنب الكحل في عينيها والحناء كل هذا مما تمنع منه الحادة.\nوالحاصل أن الحادة تؤمر بخمسة أمور:\nالأمر الأول: أنها تبقى في بيت زوجها الذي مات وهي ساكنة فيه حتى تنتهي من العدة؛ لقول النبي ﷺ لمحادة: امكثي في بيتكك حتى يبلغ الكتاب أجله هكذا قال عليه الصلاة والسلام: امكثي في بيتك حتى يبلغ الكتاب أجله، لكن لا بأس أن تخرج لحاجة، لحاجة من السوق تشتريها من طعام وغيره، أو إلى الطبيب لحاجتها إلى الطبيب لا بأس بهذا، أما خروجها لغير ذلك كالزيارات ونحو ذلك فلا، بل تبقى في بيتها، ولا تسافر أيضاً لا لحج ولا غيره حتى تنتهي من عدتها.\nالأمر الثاني: أنها لا تلبس الملابس الجميلة، بل تلبس ملابس عادية ليس فيها جمال يلفت النظر، سواءً كانت سوداء أو خضراء أو زرقاء أو حمراء أو غير ذلك.\nالثالث: عدم الحلي من الذهب والفضة ونحوها كاللؤلؤ والماس وأشباه ذلك، لا تلبس هذا؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام.\nالرابع: عدم الطيب؛ لأن الرسول ﷺ قال: لا تمس طيباً يعني: المحادة، فلا تمس الطيب سواءً كان من البخور أو غير ذلك دهن العود والورد وأشباه ذلك، إلا إذا كانت تحيض كالشابة فإنها لها أن تتبخر عند طهرها من حيضها كما أمر بهذا النبي ﷺ وأذن فيه.\nوالخامس: الكحل؛ ليس لها أن تكتحل ولا أن تتعاطى الحناء؛ لأنه جمال، فتجتنب ذلك وما أشبهه.\nهذه الأمور الخمسة هي التي يلزم المحادة أن تراعيها وتعتني بها، أما ما سوى ذلك فهي من جنس بقية النساء، لها أن تغتسل متى شاءت تتروش متى شاءت، تغير ثيابها متى شاءت، تستعمل الدواء فيما عندها من مرض في عينيها أو غيره من أدوية، تطبخ حاجتها في البيت، تخدم بيتها، تصعد إلى السطح في الليل إلى القمر ...... القمر، تخرج إلى الحوش وإلى الحديقة في بيتها، كل هذا لا بأس به، تكلم من شاءت من يكلمها من جيرانها أو من غير جيرانها أو من طريق الهاتف كالتلفون أو غيره، كل هذا لا بأس به إذا كان كلاماً ليس فيه ريبة ولا منكر، فهي من جنس بقية النساء. نعم.","link":"https://binbaz.org.sa/fatwas/6102/لبس-المعتدة-للثوب-الاسود-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10705.mp3","categories":["البدع والمحدثات","قضايا المرأة","العِدَد"]},{"id":8295,"question":"رسالة وصلت إلى البرنامج من البحرين باعثها أخ من هناك يقول: الاسم المستعار (ج. خ. ر) البحرين، أخونا ضمن رسالته تسعة أسئلة:سؤاله الأول: لدينا بستان يبعد عنا حوالي عشرين إلى ثلاثين كيلومتر، أذهب إليه بعد صلاة العصر مع أخي، ونصلي المغرب في البستان، وأكون أنا إمامه، وبعض الأوقات نكون جماعة إذا حضر بعض الإخوان والأصدقاء، ولا أستطيع الذهاب إلى المسجد؛ لأن المساجد التي بقربنا لفئة معينة تعلمونها، ويصلون متأخرين، ولا يمكن الرجوع إلى منطقتنا؛ وذلك لضيق الوقت وخطر الشارع الذي يكون مزدحماً بالأطفال والسيارات، ولو خرجت إلى الصلاة قبل نصف ساعة لأدركت الصلاة في المسجد، ولكن هذا يضيع علي مراقبة العمال، وهم من السيخ ، ليس لهم ذمة -كما يقول- فهل صلاتي صحيحة؟وما حكم العمال الذين على غير دين الإسلام؟ وله أسئلة فرعية، إنما لو تفضلتم شيخ عبد العزيز بالإجابة عن سؤاله الأول فيما يخص الصلاة ...؟","title":"حكم الصلاة في مساجد أهل البدع، واستقدام العمالة الكافرة","answer":"إذا كان الواقع كما ذكرتم فلا حرج عليكم في الصلاة في البستان مع أخيك ومع من حضر معكم، وأما الصلاة مع من ذكرتم من أهل البدع فلا تصلوا معهم؛ لأنهم ليسوا أهلاً لأن يؤموكم، ولا يمكنكم أن تؤموهم، أما لو تيسر أن تؤموهم وتصلوا بهم فلا بأس، لكن كون... الإمام يكون من أهل البدع لا يصلح أن يكون إماماً لـأهل السنة ، ولكن لا حرج عليكم في الصلاة في البستان أنت ومن حضر معك المغرب والعشاء؛ لبعدكم من المساجد مساجد أهل السنة ، وأما وجود السيخ عندكم عمالاً فالواجب عليكم أن تستعملوا المسلمين؛ لأن البحرين من جملة الجزيرة العربية، والنبي ﷺ أوصى بإخراج الكفار منها، فالذي أنصحكم به أن تستقدموا المسلمين، وأن تبعدوا العمال من الكفار من السيخ أو من النصارى أو من الهندوس أو من غيرهم، الواجب إبعاد الكفار وتقريب المسلمين واستقدامهم للعمل في بلاد المسلمين، ولا سيما في الجزيرة العربية؛ لأن الرسول ﷺ أمر بإبعاد الكفار منها، وأوصى عند موته بإخراج الكفار من هذه الجزيرة. فالواجب عليكم أيها الإخوة! في كل مكان أن تستعملوا المسلمين دون الكفار، وهذه ليست خاصة بكم، بل وصيتي هذه لجميع أهل الجزيرة في البحرين وفي المملكة العربية السعودية، وفي قطر، وفي الكويت، وفي دولة الإمارات، وفي كل مكان وفي اليمن، وفي كل مكان من الجزيرة، الواجب إبعاد الكفار وأن يُستقدَم المسلمون للحاجة في الأعمال، وهم أولى بمنفعتكم وأولى بأموالكم من الكفار، لكن من هداه الله من الكفار وأسلم على أيديكم فلا بأس ببقائه إذا أسلم، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6108/حكم-الصلاة-في-مساجد-اهل-البدع-واستقدام-العمالة-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10803.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":8306,"question":"له سؤال ثان في رسالته يقول: أنا أحفظ القرآن الكريم، وكل صباح أقرأ سورة يس والواقعة، وفي الختام أهدي قراءة الفاتحة إلى رسول الله ﷺ وآل بيته، وفاتحة أخرى لجميع النبيين والصديقين والمسلمين، وفاتحة أخرى لوالدي ولكل من له حق علي، وفاتحة لأبنائي وأبناء المسلمين، فهل هذا جائز؟","title":"حكم إهداء قراءة الفاتحة إلى الرسول عليه الصلاة والسلام","answer":"الجواب: ليس لهذا أصل، ولم يكن الصحابة  يفعلون هذا مع نبيهم عليه الصلاة والسلام فليس هذا بمشروع، بل هذا من البدع ولا وجه له، وهو ﷺ غني عن ذلك بأن كل ما نفعله من الخير له مثله؛ لأنه الدال على الخير عليه الصلاة والسلام، وقد قال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله فهو عليه الصلاة والسلام له مثل أجورنا في قراءتنا وصلاتنا وصومنا وغير ذلك، يعطى مثل أجورنا؛ لأنه الدال على الخير والداعي إليه عليه الصلاة والسلام، فليس هناك حاجة إلى أن نهدي له الفاتحة أو غيرها، كل هذا لا أصل له، ولو كان خيراً لسبقنا إليه الصحابة  وأرضاهم، وقد قال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، ولم ينقل هذا عنه ﷺ أنه فعله مع أقاربه المسلمين، ولم ينقل عن الصحابة أنهم فعلوه مع النبي ﷺ ولا مع أقاربهم، فعلم أنه بدعة. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6113/حكم-اهداء-قراءة-الفاتحة-الى-الرسول-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20103.mp3","categories":["البدع والمحدثات"]},{"id":8325,"question":"وأولى رسائل هذه الحلقة جاءتنا من المستمع محمد إبراهيم عبد العليم الشهير بـالطيب ، مصري الجنسية، ويعمل في الخرج في منطقة أصحنة بالدلم كما يقول، سؤاله عن الاحتفال بمولد الرسول ﷺ في شهر ربيع الأول من كل عام، حيث يقول: أنا أعرف أنه بدعة، ولكنني سمعت من يقول بأن هناك بدعة حسنة أو بدعة مستحبة، وهناك من يعملون الحفلات في كل عام هجري في شهر ربيع الأول، فأرجو الإيضاح بارك الله فيكم؟","title":"تفصيل القول في حكم الاحتفال بالمولد النبوي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإن الاحتفال بالمولد النبوي على صاحبه أفضل الصلاة والسلام أمر قد كثر فيه الكلام، وقد كتبنا فيه كتابات متعددة، ونشرت في الصحف مرات كثيرة، ووزعت مرات كثيرة، وكتب فيه غيري من أهل العلم كشيخ الإسلام ابن تيمية رحمه الله في كتابه: اقتضاء الصراط المستقيم، وبين أولئك العلماء أنه بدعة، وأن وجوده من بعض الناس لا يبرر كونه سنة ولا يدل على جوازه وشرعيته.\nوقد نص على ذلك أيضاً الشاطبي رحمه الله في كتابه الاعتصام، وكتب في هذا أيضاً شيخنا العلامة الكبير محمد بن إبراهيم رحمه الله كتابة وافية، وليس في هذا بحمد الله شك عند من عرف الأصول وعرف القاعدة الشرعية في كمال الشريعة والتحذير من البدع، وإنما يشكل هذا على بعض الناس الذين لم يحققوا الأصول، ولم يدرسوا طريقة السلف الصالح دراسة وافية كافية، بل اغتروا بمن فعل المولد من بعض الناس وقلدوه، أو اغتروا بمن قال: إن في الإسلام بدعة حسنة، والصواب في هذا المقام: أن الاحتفال بالموالد كلها بدعة، بمولده عليه الصلاة والسلام وبمولد غيره، كمولد البدوي ، أو الشيخ عبد القادر الجيلاني ، أو غيرهما، لم يفعلها السلف الصالح، ولم يفعل النبي ﷺ احتفالاً بمولده وهو المعلم المرشد عليه الصلاة والسلام، وقد بلغ البلاغ المبين ونصح الأمة، وما ترك سبيلاً يقرب من الله ويدني من رحمته إلا بينه للأمة وأرشدهم إليه، وما ترك سبيلاً يباعد من رحمة الله ويدني من النار إلا بينه للأمة وحذرهم منه، وقد قال الله سبحانه: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3] مضى لسبيله عليه الصلاة والسلام في مكة ثلاثة عشر سنة، في المدينة عشر سنين ولم يحتفل بهذا المولد، ولم يقل للأمة: افعلوا ذلك، ثم صحابته  وأرضاهم لم يفعلوا ذلك لا الخلفاء الراشدون ولا غيرهم من الصحابة، ثم التابعون لهم بإحسان من التابعين وأتباع التابعين من القرون المفضلة، كلهم على هذا السبيل لم يفعلوا شيئاً من هذا لا قولاً ولا عملاً، ثم أتى بعض الناس في القرن الرابع ممن ينسب إلى البدعة من الشيعة الفاطميين المعروفين حكام مصر والمغرب فأحدثوا هذه البدعة، ثم تابعهم غيرهم من بعض أهل السنة جهلاً بالحق، وتقليداً لمن سار في هذا الطريق، أو أخذاً بشبهات لا توصل إلى الحق.\nفالواجب على المؤمن أن يأخذ الحق بدليله، وأن يتحرى ما جاءت به السنة والكتاب حتى يكون حكمه على بينة وعلى بصيرة، وحتى يكون سيره على منهج قويم، والله يقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، ويقول : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59].\nوإذا نظرنا فيما يفعله الناس من الاحتفالات ورددناه إلى القرآن العظيم لم نجد فيه ما يدل عليها، وإذا رددنا ذلك إلى السنة لم نجد فيها ما يدل على ذلك لا فعلاً ولا قولاً ولا تقريراً، فعلم بذلك أن الاحتفال بالمولد النبوي بدعة بلا شك يجب تركها ولا يجوز فعلها، ومن فعل ذلك من الناس فهو بين أمرين: إما جاهل لم يعرف الحق فيعلم ويرشد، وإما متعصب لهوى وغرض فيدعى إلى الصواب ويدعى له بالهداية والتوفيق، وليس واحد منهما حجة لا الجاهل ولا المتعصب، ليس كل منهما حجة، وإنما الحجة فيما قاله الله ورسوله لا في قول غيرهما.\nثم القول بأن البدع تنقسم إلى حسنة وسيئة وإلى محرمة وواجبة قول بلا دليل، وقد رد ذلك أهل العلم واليقين وبينوا خطأ هذا التقسيم، واحتجوا على هذا بقول النبي ﷺ في الحديث الصحيح: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، متفق على صحته، وروى مسلم في صحيحه رحمه الله عن عائشة رضي الله عنها عن النبي ﷺ أنه قال: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، وفي الصحيح عن جابر رضي الله تعالى عنه عن النبي ﷺ أنه كان يخطب يوم الجمعة فيقول: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة ولم يقل البدعة فيها كذا وفيها كذا، بل قال: كل بدعة ضلالة، وقال في حديث العرباض بن سارية: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nوالبدع في أمور الدين في أمور التقرب لا في أمور الدنيا، أما أمور الدنيا في المآكل والمشارب فللناس أن يحدثوا في مآكلهم وطعامهم وشرابهم صناعات خاصة، يصنعون الخبز على طريقة، والرز على طريقة، والأنواع الأخرى على طريقة، لهم أن يتنوعوا في طعامهم ليس في هذا حرج، وإنما الكلام في القربات والعبادات التي يتقرب بها إلى الله، هذا هو محل التبديع، وكذلك الصناعات وآلات الحرب، للناس أن يحدثوا أشياء يستعينوا بها في الحرب من قنابل.. من مدافع.. من غير ذلك، يحدثون مراكب من طائرات.. من سفن فضائية.. من قطارات، ليس في هذا شيء، إنما الكلام فيما يتقرب به إلى الله ويعده الناس قربة وطاعة يرجون ثوابها عند الله هذا هو محل النظر، فما لم يفعله الرسول ﷺ ولا أصحابه، ولم يدل عليه صلى الله عليه وسلم ولم يرشد إليه بل أحدثه الناس وأدخلوه في دين الله فهو بدعة، شاء فلان أو غضب فلان، والحق أحق بالاتباع، ومن هذا الباب ما أحدثه الناس من بناء المساجد على القبور، واتخاذ القباب عليها، هذا من البدع التي وقع بسببها شر كثير، حتى وقع الشرك الأكبر وعبدت القبور من دون الله بأسباب هذه البدع.\nفيجب على المؤمن أن ينتبه لما شرعه الله فيأخذ به، وعليه أن ينتبه لما ابتدعه الناس فيحذره وإن عظمه من يشار إليهم من أهل الجهل أو التقليد الأعمى أو التعصب، فلا عبرة عند الله بأهل التقليد الأعمى ولا بأهل التعصب ولا بأهل الجهل، وإنما الميزان عند الله لمن أخذ بالدليل واحتج بالدليل وأراد الحق بدليله هذا هو الذي يعتبر في الميزان ويرجع إلى قوله، ونسأل الله للجميع الهداية والتوفيق. نعم. الله المستعان.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6136/تفصيل-القول-في-حكم-الاحتفال-بالمولد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20201.mp3","categories":["البدع والمحدثات"]},{"id":8356,"question":"الرسالة التالية وصلت إلى البرنامج من البحرين، وباعثها أحد الإخوة من هناك يقول: (خ. ج. ر) أخونا له تسعة أسئلة فقط، سماحة الشيخ، يسأل في أحد أسئلته ويقول: إذا تلفظت في داخل المسجد وقلت: اللهم إني نويت الوضوء لصلاة العصر مثلاً، أو نويت للصلاة بهذه الطريقة، هل هذا يعتبر بدعة، أفيدونا جزاكم الله خيراً؟","title":"حكم التلفظ بالنية في الصلاة وغيرها","answer":"الجواب: نعم نعم، ليس له التلفظ بالنية لا في الصلاة ولا في الوضوء، النية محلها القلب، فيأتي إلى الصلاة بنية الصلاة ويكفي، يقوم للوضوء بنية الوضوء ويكفي، وليس هناك حاجة إلى أن يقول: نويت أن أتوضأ أو نويت أن أصلي أو نويت أن أصوم أو نويت أن أحج أو ما أشبه ذلك، إنما النية محلها القلب، يقول ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى ولم يكن عليه الصلاة والسلام ولا أصحابه يتلفظون بالنية في الصلاة ولا في الوضوء، وعلينا أن نتأسى بهم في ذلك، ولا نحدث في ديننا ما لم يأذن به الله، يقول عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود.\nوبهذا يعلم أن التلفظ بدعة، التلفظ بالنية بدعة. نعم.","link":"https://binbaz.org.sa/fatwas/6205/حكم-التلفظ-بالنية-في-الصلاة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11313.mp3","categories":["البدع والمحدثات"]},{"id":8382,"question":"رسالة وصلت إلى البرنامج من الخرطوم، السودان، باعثها أحد الإخوة من هناك يقول: عبد الهادي بشير من قوات الشعب المسلحة، أخونا يسأل ويقول: ما حكم الإسلام في الاحتفال بالمولد النبوي الشريف، أفيدونا أفادكم الله؟","title":"حكم الاحتفال بمولد النبي صلى الله عليه وسلم","answer":"الجواب: الاحتفال بالمولد قد كتب فيه العلماء وأوضحوا حكمه، وبينوا أن الاحتفال بالموالد بدعة لا أساس لها في الشرع، وقد كتبنا في هذا كتابات منذ سنوات كثيرة، وبينا أن الاحتفال بالمولد من البدع التي أحدثها الناس، وأول من أحدثها فيما ذكر بعض المؤرخين هم الفاطميون الشيعة الرافضة المعروفون، حكام مصر والمغرب في المائة الرابعة والخامسة، هم أول من أحدثها في المائة الرابعة، أحدثوا احتفالاً بمولد النبي ﷺ، وبمولد فاطمة والحسين والحسن ، وبمولد حاكمهم ،ثم تتابع الناس في ذلك، وأحدثها جماعة من المسلمين في كثير من الدول الإسلامية تقليداً لمن قبلهم، وإلا فالنبي ﷺ لم يفعل ذلك، ولم يأمر به، وهكذا أصحابه  وأرضاهم، الخلفاء الراشدون لم يفعلوه، وهكذا بقية أصحابه  لم يفعلوه، وهكذا أصحاب القرون المفضلة.. القرن الثاني والثالث لم يفعلوه، وإنما حدث في القرن الرابع كما تقدم، والذين أحدثوه هم الشيعة، هم الرافضة ، ليسوا بالقدوة في هذا ولا في غيره، فالذي ينبغي للمؤمن أن يتأسى بأصحاب النبي ﷺ وأن يسير على نهجهم في عدم إحداث البدع، ومن ذلك المولد، فإنه ليس له أصل في الشرع، وحب النبي ﷺ وتذكر سنته أمر مطلوب دائماً، فينبغي للمسلمين دائماً أن يذكروه ﷺ، وأن يتبعوا سنته ويعظموها، ويشجعوا عليها ويدعوا إليها في كل وقت.. في دروسهم، وفي خطبهم، وفي مدارسهم، وفي معاهدهم، وفي غير ذلك، هكذا شرع الله له سبحانه وتعالى.\nوقد رفع الله ذكره، وشرع للعباد اتباع سنته، وتعظيم أمره ونهيه عليه الصلاة والسلام، فهو ينادى بذكره كل يوم خمس مرات، في الأذان وفي الإقامة: أشهد أن محمداً رسول الله، والمسلمون يصلون عليه، ويشهدون له بالرسالة في كل صلاة مرتين، في الظهر، والعصر، والمغرب، والعشاء، مرتين في التشهد الأول والتشهد الأخير، وفي الفجر، وفي الجمعة كذلك، وفي صلواتهم النافلة، يشهدون أنه لا إله إلا الله، وأن محمداً رسول الله، فهو ﷺ مذكور بين المسلمين، في صلواتهم، وفي أذانهم، وفي إقامتهم، وفي غير ذلك، فليس بمنسي حتى يهيأ له مولد، هو مذكور دائماً عليه الصلاة والسلام.\nفالواجب على المسلمين أن يتبعوا سنته، وأن يعظموا أمره ونهيه، وأن يكتفوا بما شرع، وأن يحذروا البدع، فقد قال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد وقال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: مردود، وكان يقول في خطبته يوم الجمعة عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمدد صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلاله ويقول في حديث العرباض بن سارية: إياكم ومحدثاتت الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nفالاحتفال بالموالد، كلها من البدع، ومن جملة ذلك مولده عليه الصلاة والسلام، فينبغي للأمة أن يتركوا هذه البدع، وأن يجتهدوا في اتباع سنته، وتعظيم أمره ونهيه، وأن يسارعوا إلى ما جاء به عليه الصلاة والسلام من الهدى، وأن يبتعدوا عما نهى عنه من الباطل، هكذا يكون حب الرسول ﷺ، وهكذا يكون تعظيمه، وهكذا يكون ذكره الذي ينفع العبد في الدنيا والآخرة، لا بالبدع والخرافات.\nوقد نبه جماعة من أهل العلم على هذه البدعة كـالشاطبي وشيخ الإسلام ابن تيمية ، وجماعة آخرين، نبهوا على هذه البدعة، وبينوا أنها خطأ، وأنها محدثة، فينبغي للمسلمين دائماً ترك البدع والحذر منها، والتواصي بإحياء السنة، والاستقامة عليها، واتباعها والحذر مما خالفها، نسأل الله للجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/6231/حكم-الاحتفال-بمولد-النبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_115/11506.mp3","categories":["البدع والمحدثات"]},{"id":8430,"question":"الرسالة التالية وصلت إلى البرنامج من حضرموت، وصلت من الإخوة: سالم بن علي باعبود باوزير وإخوانه: مبارك صالح بن نبيل والعبد صالح ، إخواننا رسالتهم في صفحة كاملة، وكلها تصور العادات التي عليها الناس بعد وفاة متوفى لديهم، فهم يضطرون حتى إلى أن يستدينوا من أجل الاحتفالات التي تقام، والأكل، والشرب، وما أشبه ذلك، حتى وإن توفي المتوفى وهو فقير ولم يخلف شيء، ماذا يقول سماحة الشيخ لهذه العادات لو تكرمتم؟","title":"حكم إقامة أهل الميت للمآتم والولائم بعد الدفن","answer":"الجواب: قد كتبنا في هذا أجوبة كثيرة، وقد نبهنا في هذا البرنامج مرات كثيرة، على أنه لا يجوز الاحتفال عند الموت بأحد من الناس، ليس لأهل الميت أن يقيموا احتفالاً ...... بذلك، ولا أن يذبحوا ذبائح، ولا أن يصنعوا طعاماً للناس، كل هذا من البدع والجهالات التي كان يفعلها بعض الناس، وهي من أمر الجاهلية.\nثبت عن جرير بن عبد الله البجلي  قال: كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة  فكان من عمل الجاهلية ومن النياحة التي كانوا يفعلونها في الجاهلية.\nفالواجب على المسلمين إذا مات الميت أن يسألوا الله له المغفرة والرحمة، وأن يتركوا هذه الاحتفالات، وهذه الأطعمة التي تقام من أهل الميت، وقد يكون الميت فقيراً، وقد يكون عنده أيتام فيضرونهم، المقصود أنها لا أصل لها حتى ولو كان غنياً، لا أصل لها، ولا ينبغي فعلها، ولا يجوز فعلها، لكن يشرع لجيرانهم وأقاربهم أن يصنعوا لهم طعاماً؛ لأنهم مشغولون بالمصيبة، ولهذا ثبت من حديث عبد الله بن جعفر بن أبي طالب رضي الله تعالى عنهما أن النبي صلى الله عليه وسلم لما جاء نعي جعفر لما قتل في مؤتة، وجاء نعيه إلى المدينة، أمر النبي صلى الله عليه وسلم أهله أن يصنعوا لآل جعفر طعاماً، قال: لأنه أتاهم ما يشغلهم، فإذا صنع لهم طعام من جيرانهم أو أقاربهم وأرسل إليهم؛ لأنهم مشغولون بالمصيبة فهذا مستحب، وهذا سنة، أما أهل الميت فليس لهم صنع الطعام، ولا ينبغي لهم أن يصنعوا للناس الطعام، أما إذا صنعوه لأنفسهم ولأكلهم أو لضيوف نزلوا بهم فلا بأس، أما أن يصنعوا من أجل الميت مأتماً للميت لينوحوا عليه، أو يقيموا عليه الأشعار والمراثي، أو ليدعوا الناس إلى ذلك، كل هذا من البدع، كل هذا من الجهالات ومن أمر الجاهلية لا يجوز، أما كونهم يصنعوا لأنفسهم طعاماً هم ليأكلوا عادتهم فلا بأس، أو نزل بهم ضيف، فصنعوا من أجل الضيف لا من أجل الموت، ولا من أجل النياحة، ولا من أجل جمع الناس، ولكن من أجل الضيف الذي نزل، إذا صنعوا طعاماً ليطعموا الضيف فلا بأس بذلك؛ لأنه جاء من بعيد.\nفالمقصود من هذا كله أن المنكر هو أن يصنعوه للناس، أهل الميت يصنعوا طعاماً ليجمعوا الجيران أو الأقارب ولينوحوا أو ليقرءوا أو غير ذلك هذا هو المنكر، هذا هو الجاهلية.\nأما صنعهم طعاماً لحاجتهم أنفسهم؛ لأكلهم المعتاد؛ أو نزل بهم ضيف فاضطروا إلى أن يصنعوا طعاماً لأجله حتى يكرموه لما جاء من بعيد، فهذا لا حرج في ذلك، ولا ينبغي لأهل الإيمان وأهل الإسلام أن يعتادوا أمر الجاهلية وأن يفعلوا أمر الجاهلية، لا، بل يتواصوا، بل ينبغي التواصي بترك أمر الجاهلية، هكذا ينبغي للمسلمين.\nوأما جيرانهم وأقاربهم فيستحب لهم أن يصنعوا لهم طعاماً ويرسلونه إليهم؛ لأنهم مشغولون بالمصيبة، هذا إذا تيسر فهذا أفضل، وهذا سنة. نعم.","link":"https://binbaz.org.sa/fatwas/6314/حكم-اقامة-اهل-الميت-للماتم-والولاىم-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11907.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":8469,"question":"أخونا يسأل مع مستمع آخر هو: محمد التونسي إخواننا يسألون سماحة الشيخ عن العادات في العزاء، وأيضاً يسأل معهم أحد الإخوة يقول محمد أحمد شوي مقيم في جدة وهو من تشاد، يسألون عن العادات المتبعة لدى البعض في العزاء، من الولائم وقراءة القرآن والأربعينيات والسنويات أيضاً وما شاكل ذلك، ويرجون التوجيه من سماحة الشيخ؟","title":"بدع التعزية","answer":"الجواب: هذه عادات لا أصل لها ولا أساس لها، بل هي من البدع ومن أمر الجاهلية، كونه يقيم وليمة إذا مات الميت يدعو إليها الجيران والأقارب ونحو ذلك، ويقيمونها بالبكاء أو بالقراءة أو نحو ذلك، هذه بدعة لا تجوز، وهكذا إقامتها على رأس الأربعين، أو على رأس الأسبوع أو على رأس الشهر أو على رأس السنة كلها من بدع الجاهلية، كلها مما لم يشرعه الله سبحانه وتعالى.\nوإنما المشروع لأهل الميت الصبر والاحتساب والعزاء يعني: العزاء مما أصابهم أن يتعزوا بالله ويرضوا عما قدر عليهم سبحانه وتعالى، ويحتسبوا الأجر عنده ، ولا مانع من أن يصنعوا لأنفسهم الطعام العادي لأكلهم وحاجاتهم، وهكذا لو نزل بهم ضيف صنعوا له الطعام العادي لا بأس، أما أن يصنعوه من أجل الموت ومن أجل المأتم من أجل إقامة مأتم، يجمعون الناس ليقرءوا القرآن أو ليقرءوا الأحاديث أو الأشعار أو ليبكوا معهم وينوحوا معهم، كل هذا من البدع المحدثة وليس له أصل في الشرع المطهر.\nويشرع لأقاربهم وجيرانهم ونحو ذلك أن يصنعوا لهم طعاماً يرسلونه إليهم؛ لأنهم مشغولون بالمصيبة فإذا صنع لهم جيرانهم أو بعض أقاربهم طعاماً يوم الموت أو اليوم الثاني أو نحوه، وأرسلوه إليهم جبراً لمصابهم وإعانة لهم على المصيبة لأنهم مشغولون، قد لا يتفرغون للطبخ، قد يكسلون عن ذلك لشدة المصيبة هذا أمر مشروع، وقد ثبت عن رسول الله عليه الصلاة والسلام أنه لما أتى نعي جعفر بن أبي طالب رضي الله عنه حين قتل في مؤتة في الشام وجاء خبره إلى المدينة  أمر النبي ﷺ أهله أن يصنعوا طعاماً لأهل جعفر، قال: اصنعوا لهم طعاماً فقد أتاهم ما يشغلهم يعني: بعثوا لهم طعاماً من أهله صلى الله عليه وسلم إلى أهل جعفر لأنه قد أتاهم ما يشغلهم، يعني: يشغلهم عن صنع الطعام، فهذا أمر مشروع وليس فيه بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6485/بدع-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12403.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":8505,"question":"المستمع علي حسن بكري الربعي يسأل عن حكم لفظ: صدق الله العظيم في نهاية قراءة القرآن الكريم، هل هي بدعة، أم هي سنة، أما ماذا حكمها؟ وما الحكم فيمن قال إنها بدعة؟","title":"حكم قول صدق الله العظيم عقب قراءة القرآن","answer":"الجواب: هذه الكلمة حدثت أخيراً بين الناس واشتهرت بين الناس، ولا نعلم لها أصلاً عن السلف الصالح، ولكنها الآن واقعة بين الناس، وربما وقعت بين أهل العلم أيضاً عندما يقرأ عليهم قارئ فالناس يتسامحون فيها كثيراً، والذي يظهر لي أنه لا أصل لها، وأن تركها أولى، والقول بأنها بدعة قول قريب ليس ببعيد؛ لأن القاعدة كل ما حدث مما يتقرب به إلى الله وليس له أصل يقال له: بدعة، لقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد وقال ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد فالتزامها بعد كل قراءة حتى إن بعضهم يقرؤها في الصلاة، هذا لا وجه له.\nوالذي أرى أن الواجب ترك ذلك. أما إذا فعل بعض الأحيان، أو عند وجود أسباب مثل رأى ما يدل على ما أخبر به الرسول ﷺ مما يقع في آخر الزمان فيقول: صدق الله ورسوله، أخبر النبي ﷺ كذا كذا وقد وقع، نعم.\nكما فعل علي  لما رأى المخدج في الخوارج لما قتلهم ورأى المخدج ، الذي هو علامة أخبر بها النبي صلى الله عليه وسلم لما رآه قال: صدق الله ورسوله، يعني هذه علامة ما قاله النبي ﷺ.\nفالحاصل أنه إذا وجد لها أسباب، أما كونه يلزمها عند كل قراءة هذا لا أصل له، والذي ينبغي ترك ذلك، نعم.\nالمقدم: بارك الله فيكم من قالها سماحة الشيخ هل يأثم؟\nالشيخ: يخشى .. يخشى عليه إذا داوم على ذلك، يخشى عليه؛ لأن وصف البدع ينطبق عليها، وصف البدعة ينطبق عليها، نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6573/حكم-قول-صدق-الله-العظيم-عقب-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12705.mp3","categories":["البدع والمحدثات"]},{"id":8507,"question":"سماحة الشيخ عن قراءة الفاتحة عند كل أمر في بدايته خير؟","title":"حكم قراءة الفاتحة بداية أو نهاية كل أمر فيه خير","answer":"الجواب: لا أصل لهذا.\nالمقدم: لا أصل لهذا.\nالشيخ: لا قبله ولا بعده، ما يفعل بعض الناس يقرأ الفاتحة عند البدء أو عند النهاية، عند نهاية الطواف أو السعي أو غير ذلك من العبادات لا أصل لهذا، إنما شرع الله قراءتها في الصلاة، قراءتها مع القرآن كلما ختم عاد وبدأ بها وقرأ طيب، أما أن يخصها بقراءة عند طوافه، أو آخر طوافه، أو في أنواع المعاملات التي يعملوها ليس لهذا أصل، لكن إذا قرأ الحمدلة في أول الدعاء وصلى على النبي ﷺ، وقال: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ [الفاتحة:2-4] أول الفاتحة؛ لأنها حمد وثناء أو تحمد بغير ذلك من أنواع الحمد لا بأس، عند الدعاء عند أول الدعاء ثم يصلي على النبي ﷺ ثم يدعو، هذا لا بأس به قراءة أولها لأنها حمد وثناء، لأنها ثناء على الله وتمجيد له سبحانه وتعالى. نعم.\nالمقدم: إذا قرأ القارئ في مسجد أو في مناسبة معينة آيات من القرآن الكريم وانتهى من ذلك يقول: الفاتحة، كيف توجهون؟\nالشيخ: هذا لا أصل له أيضاً.\nالمقدم: لا أصل له.\nالشيخ: لا أصل له بدعة.\nالمقدم: إذاًَ على المسلم أن يتجنبها ولا يستجيب لهذا النداء؟\nالشيخ: نعم نعم، النبي ﷺ يقول قاعدة شرعية يقول: من عمل عملاً ليس عليه أمرنا فهو رد وهذا في العبادات هذا في الأعمال التي يتعبد بها الناس، أما أمور الدنيا في البيع والشراء والزراعة هذه أمور إلى عادات الناس وعرفهم، أما العبادات التي يتقرب بها الإنسان إلى الله هذا ليس له أن يحدث شيئاً، لا عند الدعاء ولا غيره، نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6581/حكم-قراءة-الفاتحة-بداية-او-نهاية-كل-امر-فيه-خير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12707.mp3","categories":["البدع والمحدثات"]},{"id":8563,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع عبد الرحمن بن عبد الله بن سبتان من الدرعية، يقول في رسالته: أسمع كثيراً من المؤذنين في بعض إذاعات الدول الإسلامية يؤذنون أذاناً مختلفاً كالآتي، في بداية الأذان يكبر تكبيرتين فقط، بعد قوله: (حي على الفلاح، يقول: حي على خير العمل) مرتين فما حكم هذا الأذان؟ وهل ثبت عن أحد من الصحابة رضي الله عنهم؟","title":"حكم قول: (حي على خير العمل) في الأذان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله أصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت في الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام أن الأذان أربع تكبيرات في أوله، ولم يثبت عنه ﷺ أنه يقال فيه: حي على خير العمل، لم يقل هذا بلال ، ولا عبد الله بن أم مكتوم ، ولا أبو محذورة ولا غيره من مؤذنيه عليه الصلاة والسلام، وإنما هو مروي عن علي بن الحسين ويرويه بعضهم عن عبد الله بن عمر ولكنه ليس بثابت عن النبي ﷺ ولا عن مؤذنيه؛ ولهذا فالصواب في هذا أنه بدعة لا يجوز فعله؛ لأنه مخالف للأحاديث الصحيحة الثابتة عن رسول الله عليه الصلاة والسلام، وإنما الثابت أن يقول بعد حي على الصلاة حي على الفلاح: الله أكبر الله أكبر لا إله إلا الله.\nفالأذان خمسة عشر جملة: أربع تكبيرات في أوله، ثم الشهادتان أربع، ثم الحيعلة أربع، ثم الله أكبر الله أكبر، لا إله إلا الله، الجميع خمسة عشر، ومع الترجيع يكون تسعة عشر، والترجيع أن يأتي بالشهادتين بصوت منخفض ثم يأتي بهما بصوت مرتفع، كما في حديث أبي محذورة لما أذن بمكة حين علمه النبي ﷺ الأذان علمه فيه الترجيع، وفي الفجر يزاد فيه: الصلاة خير من النوم.. الصلاة خير من النوم أما (حي على خير العمل) فبدعة.\nالمقدم: ويقول الأخ عبد الرحمن بن سبتان في آخر رسالته، هل يبطل هذا الصلاة التي أذن لها هذا الأذان؟\nالشيخ: لا، لا يبطل الصلاة ولا يبطل الأذان، الأذان صحيح والكلمات الزائدة خطأ، فالأذان صحيح والصلاة صحيحة. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6640/حكم-قول-حي-على-خير-العمل-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20701.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":8599,"question":"نعود في هذه الحلقة لو تكرمتم سماحة الشيخ إلى رسالة الأخ سعيد خميس الصويل من حضرموت جمهورية اليمن الديمقراطية الشعبية منطقة ترس، أخونا عرضنا بعضاً من أسئلته في حلقة مضت وفي هذه الحلقة يسأل ويقول: ما حكم الإسلام فيمن يضيف إلى النداء للصلاة شيئاً من تلاوة القرآن أو بعض الألفاظ الأخرى عبر مكبرات الصوت، حيث أن هذه الظاهرة منتشرة في كثير من المناطق، وأكثر ما تكون في شهر رمضان قبل وقت الفجر وفي أي وقت أرادوه من الليل، وفي مثل هذه الحالة تتكاثر الأصوات من جميع نواحي المنطقة مما يؤثر ذلك على السكان، فهل هذه الأفعال صحيحة أم لا، أفيدونا أفادكم الله؟","title":"حكم الزيادة على الأذان","answer":"الجواب: هذا شيء لم يشرع بل هو بدعة، والواجب على المؤذن أن لا يضيف شيئاً إلى الأذان لا قبله ولا بعده، فلا يقرأ قبل الأذان، ولا يقول كلاماً قبل الأذان، ولا بعد الأذان يرفع صوته بالصلاة على النبي ﷺ أو بغير ذلك لا، بل يؤدي الأذان كاملاً، يبدؤه بقوله: الله أكبر، وينهيه بقوله: لا إله إلا الله، فلا يأت بشيء قبله ولا يأت بشيء بعده؛ لأن ذلك من البدع.\nوقد قال ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود على صاحبه، خرجه مسلم في الصحيح، وعلقه البخاري جازماً به عن عائشة رضي الله عنها، ولقوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني مردود، ولم يكن بلال ولا غيره في عهد النبي ﷺ يأتي بشيء قبل الأذان ولا بعد الأذان، فإذا قال: (لا إله إلا الله) يقفل المكبر ينتهي، وفي الأذان يبدأ.. وفي الأول يبدأ الله أكبر، يبدأ الأذان بهكذا لا يتكلم بشيء قبل الأذان، فلا يقول: صلوا، أو سبحان الله، أو ما أشبه ذلك، أو يقرأ قبل الأذان لا، ولا بعد الأذان إذا قال: (لا إله إلا الله) يقول: اللهم صل وسلم على رسول الله يجهر بذلك في المكبر لا، بل يقفل المكبر ثم يصلي على النبي ﷺ بينه وبين نفسه وإن سمعه من حوله لا بأس لكن يقفل المكبر ليس تابعاً للأذان، بل يقوله بعد الأذان بينه وبين نفسه ولا مانع من أن يسمعه من حوله، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً ﷺالوسيلةة والفضيلة وابعثه المقام المحمود الذي وعدته إنك لا تخلف في الميعاد كما جاء في الحديث، روى البخاري في الصحيح عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة والصلاة القائمة، آت محمداً الوسيلة والفضيلة وابعثه المقام المحمود الذيي وعدته حلت له شفاعتي يوم القيامة زاد البيهقي رحمه الله بإسناد جيد: إنك لا تخلف الميعاد وفي مسلم عن عبد الله بن عمرو بن العاص رضي الله عنهما، عن النبي ﷺ أنه قال: إذا سمعتم المؤذن فقولوا مثلما يقول ثم صلوا علي، فإنه من صلى عليي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو،، فمن سأل لي الوسيلة حلت له الشفاعة.\nهذا هو المشروع للمؤمن لكن بعد قفل الأذان، بعد انتهاء الأذان، يقفل المكبر ثم يأتي بهذا، وهكذا قبله لا يتكلم بشيء.\nوالخلاصة: أن الأذان يبدأ بـ(الله أكبر) وينتهي بـ(لا إله إلا الله)، فمن زاد معه شيء يرفع به صوته أو في المكبر فقد أتى بدعة فينكر عليه ويعلم.\nالمقدم: بارك الله فيكم، إذاً الصلاة على النبي ﷺ برفع الصوت قريباً من الصوت الذي رفع بها الأذان يعتبر هذا..\nالشيخ: بدعة.\nالمقدم: بدعة.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6723/حكم-الزيادة-على-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12904.mp3","categories":["البدع والمحدثات"]},{"id":8601,"question":"سماحة الشيخ! إذا أذنتم لي: بعض الأعمال ظاهرة الفضل وقد يستنكر بعض الناس إذا قلت: إن هذا العمل غير مشروع ولا يجوز وأنه بدعة، كيف نوجه الناس والحالة هذه لو سمحتم؟","title":"الرد على من يقول بفضيلة أمور لم يأمر بها الشرع","answer":"الجواب: قد تقرر في الأصول أن الشرع: هو ما شرعه الله ورسوله، وأن الدين: هو ما جاء به الرسول صلى الله عليه وسلم عن ربه عز وجل، فمن قال قولاً أو ادعى دعوى فعليه البرهان فعليه الدليل، فإذا قال: هذا بدعة أو هذا مشروع فعليه الدليل الذي يدل على شرعية هذا أو بدعة هذا، وليس تقوى للناس حجة إذا لم تستند على نص من كتاب الله أو من سنة رسوله ﷺ أو من إجماع أهل العلم، فإذا قلت -أنا أو غيري-: هذا بدعة فعلي الدليل، وإذا قال -غيري أو أنا-: هذا مشروع فعلي الدليل، فإذا قلنا: إن الأذان عند القبور والإقامة عند القبور والقراءة عند القبور أو الصلاة عندها بدعة؛ فحجتنا أن الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبوراً ولأنه ﷺ لم يفعل ذلك، والله يقول: لَقَدْْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] فلم يقرأ عند قبر لا هو ولا أصحابه، ولم يؤذن عند قبر ولم يقم عند قبر لا هو ولا أصحابه، ونحن مأمورون بالاتباع، الله يقول: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] ويقول سبحانه وتعالى: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ويقول : وَالسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ [التوبة:100] فالمتبع بإحسان هو الذي يسير على نهجهم، ولا يزيد عليهم ولا ينقص بل يتبعهم، ويسير على نهجهم وطريقهم، فعلى من زعم أنه يؤذن في القبر أو يقام أو يقرأ في القبر، أو يلقن الميت عليه الدليل، ونحن بينا أنه لا دليل معه بل الدليل مع خصمه، ولم يثبت أنه صلى الله عليه وسلم لقن الميت ولا أمر بتلقينه، والميت انقطع عمله بعد الممات، الميت ما عاد ينفعه الكلام انقطع عمله، يقول النبي صلى الله عليه وسلم: «إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له» فالقبر ما هو محل عمل هو محل مساءلة ومحل جزاء، فهذه حجة من قال في هذه الأمور: إنها بدعة.\nوإذا قلنا: إنه يشرع للمؤمن أن يصلي على الميت وأن يتبع الجنازة وأن يدعو للميت، وإذا دفنه يدعو له بالمغفرة والثبات؛ لأن الرسول صلى الله عليه وسلم فعل ذلك وأمر بذلك، وكان ﷺ إذا فرغ من دفن الميت يقف عليه، ويقول: استغفروا لأخيكم، واسألوا لهه التثبيت فإنه الآن يسأل عليه الصلاة والسلام.\nفنحن إذا قلنا: يوقف عليه ويستغفر له يدعى له بالثبات هذا حق؛ لأن الرسول فعل ذلك وأمر به عليه الصلاة والسلام.\nفهكذا بقية الأمور كل من ادعى شيئاً أنه مشروع يقال: هات البرهان؛ لأن الله سبحانه وتعالى يقول: قُلْ هَاتُوا بُرْهَانَكُمْ [البقرة:111] ومن ادعى أن هذا بدعة يقال: هات البرهان، هكذا هذا هو الميزان وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].. فَإِنْْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] ولولا هذا لقال كل واحد ما شاء، ولهذا عرفنا أن البناء على القبور القباب واتخاذ المساجد عليها بدعة، لماذا؟ لأن الرسول أنكر هذا عليه الصلاة والسلام، وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال جابر بن عبد الله : نهى رسول الله ﷺ عن تجصيص القبور، والقعود عليها والبناء عليها رواه مسلم في الصحيح، فلهذا نقول: إن البناء على القبور واتخاذ المساجد عليها والقباب من البدع المنكرة؛ لأن الرسول ﷺ لعن من فعل ذلك ونهى عن تجصيص القبور، ونهى عن البناء عليها، فوجب علينا الامتثال، وجب علينا أن نعمل بما وجهنا إليه عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً، إذاً الأعمال وإن كان ظاهرها الفضيلة فلا بد وأن تكون مدعمة بالأدلة من الشريعة الإسلامية حتى تكون عملاً مسنوناً يتبعه الناس ويعملوه؟\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6729/الرد-على-من-يقول-بفضيلة-امور-لم-يامر-بها-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12906.mp3","categories":["البدع والمحدثات"]},{"id":8688,"question":"يقول: ما حكم المسابلة، أي: أن يمر بعض الأشخاص أيديهم إلى من بجانبهم بقصد السلام على بعضهم، بعد الصلاة بحوالي دقيقة، أي: بعد التفات الإمام بقليل، هل هذه تعتبر بدعة أم لا؟","title":"حكم المصافحة بعد السلام من الصلاة","answer":"الجواب: المصافحة بعد السلام من الفريضة لا أصل له، ولكن يشتغل بالذكر إذا سلم، يشتغل بالاستغفار ثلاثاً، يقول: اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام ويذكر الله، ويأتي بالأذكار الشرعية، فإذا سلم عليه بعد ذلك لأنه ما لقيه إلا في الصف، ما سلم عليه قبل ذلك فلا بأس، أما ما يفعل بعض الناس من حين يسلم يبادر ويأخذ بيد الذي حوله هذا لا أصل له، بدعة لا أصل لها، أما بعد الذكر وبعد الفراغ من الأذكار الشرعية إذا سلم على من حوله لكونه ما سلم عليهم قبل، لأنه جاء في الصلاة وهم في الصلاة، أو جاء واشتغل بتحية المسجد أو بالراتبة، ثم دخل في الصلاة قبل أن يصافحهم، إذا صافحهم بعد ذلك لا بأس، لكن ليس من حين يسلم بل يتأخر حتى يفرغ من الذكر؛ لأنه لم يثبت عن النبي ﷺ ولا عن الصحابة فعل هذا من حين ينصرف الإمام من الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6821/حكم-المصافحة-بعد-السلام-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21508.mp3","categories":["البدع والمحدثات"]},{"id":8717,"question":"أختنا تسأل وتقول: قرأت في كتاب درة الناصحين في الوعظ والإرشاد لعالم من علماء القرن التاسع الهجري واسمه عثمان بن حسن بن أحمد الشاكر الخوبري قرأت ما نصه عن جعفر بن محمد عن أبيه عن جده قال: (إن الله تعالى نظر إلى جوهرة فصارت حمراء، ثم نظر إليها ثانية فذابت وارتعدت من هيبة ربها، ثم نظر إليها ثالثة فصارت ماء، ثم نظر إليها رابعة فجمد نصفها، فخلق من النصف العرش ومن النصف الماء ثم تركه على حاله، فمن ثمة يرتعد إلى يوم القيامة)، وعن علي : «إن الذين يحملون العرش أربعة ملائكة لكل ملك أربعة وجوه، أقدامهم في الصخرة التي تحت الأرض السابعة مسيرة خمسمائة عام» أرجو أن تفيدوني عن صحة ما قرأت؟","title":"الكلام على كتاب درة الناصحين","answer":"الجواب: هذا الكتاب لا يعتمد عليه وهو يشمل أحاديث موضوعة وأشياء سقيمة لا يعتمد عليها، ومنها هذان الحديثان فإنهما لا أصل لهما بل هما حديثان موضوعان مكذوبان على النبي ﷺ، فلا ينبغي أن يعتمد على هذا الكتاب وما أشبهه من الكتب التي تجمع الغث والسمين والموضوع والضعيف، فإن أحاديث الرسول عليه الصلاة والسلام قد خدمها العلماء من أئمة السنة وبينوا صحيحها من سقيمها، فينبغي للمؤمن أن يقتني الكتب الجيدة المفيدة مثل الصحيحين، مثل كتب السنن الأربع، مثل منتقى الأخبار لـابن تيمية، مثل رياض الصالحين للنووي، هذه كتب مفيدة ونافعة، بلوغ المرام، عمدة الحديث.\nهذه يستفيد منها المؤمن وهي بعيدة من الأحاديث الموضوعة المكذوبة وما في السنن أو في رياض الصالحين أو في بلوغ المرام من الأحاديث الضعيفة فإن أصحابها بينوا ووضحوا والذي لم يوضح من جهة أصحابها بينه أهل العلم أيضاً ونبهوا عليه في الشروح التي لهذه الكتب وفيما ألف في الموضوعات والضعيف.\nفالحاصل أن هذه الكتب هي المفيدة والنافعة أنفع من غيرها، وما قد يقع في بعضها مثلما قد يقع في البلوغ أو في المنتقى أوفي السنن من بعض الأحاديث التي فيها ضعف يبينها العلماء ويوضحها العلماء الذين شرحوا هذه الكتب أو علقوا عليها فيكون المؤمن على بينة وعلى بصيرة، أما الكتب التي شغف مؤلفوها بالأحاديث الموضوعة والمكذوبة والباطلة فلا ينبغي اقتناؤها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6867/الكلام-على-كتاب-درة-الناصحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_134/13402.mp3","categories":["البدع والمحدثات"]},{"id":8720,"question":"هل يجوز للمسلم أن يرفع يديه عند الدعاء بعد السنة التي بعد الفريضة أم لا، حيث أن بعضاً من الناس ينكر ذلك ويقول: إنه بدعة، ولو رفع يديه للدعاء بعد الفريضة مباشرة هل ينكر على فاعله؟","title":"حكم رفع اليدين عند الدعاء بعد الفريضة والنافلة","answer":"الجواب: لم يثبت عن النبي ﷺ أنه رفع يديه بعد الفريضة بل السنة أنه يذكر الله ويدعو لكن من دون رفع يدين بعد الفرائض الخمس، أما بعد النافلة فلا أعلم بعد التتبع الكثير لا أعلم أنه رفع يديه بعد النافلة عليه الصلاة والسلام، ولكن عموم الأحاديث الدالة على أن رفع اليدين من أسباب الإجابة يقتضي أنه لا مانع من رفعها بعض الأحيان لا يكون دائماً كما يرفعها إذا عنت له حاجة يرفع يديه ويدعو ولو من دون صلاة، فإذا صلى ورفع يديه يطلب المغفرة ويطلب حاجته التي عنت له فلا بأس بذلك، أما اتخاذ هذا عادة كلما صلى رفع يديه فالأولى ترك ذلك.\nوقد ورد في حديث ضعيف لا يتعلق به، ولكن ينبغي أن يكون ذلك تارة وتارة لا يستديم ذلك؛ لأن الرسول ﷺ ما كان يفعل هذا، ولو كان سنة لفعله ﷺ، فلما لم يفعله دل ذلك على أنه ليس بسنة فلا يداوم عليه، وإذا فعله بعض الأحيان للحاجة لطلب ما ينفعه في الدنيا والآخرة، أو فعل رفع اليدين من دون صلاة عندما يدعو، فهذا كله طيب ورفع اليدين من أسباب الإجابة.\nوفي هذا الحديث الصحيح يقول ﷺ: إن ربكم حيي كريم يستحي من العبد إذا رفع يديه إليه أن يردهما صفراً وفي الحديث الآخر يقول ﷺ لما ذكر أن الله تعالى طيب لا يقبل إلا طيباً ذكر الرجل يطيل السفر أشعث أغبر يمد يديه إلى السماء: يا رب ياا رب! ومطعمه حرام ومشربه حرام وملبسه حرام وغذي بالحرام فأنى يستجاب لذلك.\nفدل على أن رفع اليدين والإلحاح في الدعاء من أسباب الإجابة، لكن لما كان هذا الرجل قد تلبس بالحرام صار تعاطيه الحرام في شربه وأكله ولباسه من أسباب منع الإجابة، ولا حول ولا قوة إلا بالله.\nوالخلاصة: أن رفع اليدين من أسباب الإجابة عند الدعاء في المواضع التي رفع فيها النبي ﷺ وفي المواضع التي لم يثبت فيها رفع ولم توجد أسبابها في عهده ﷺ فهذه يرفع فيها أيضاً إذا أراد الدعاء، أما الأسباب التي وجدت في عهده ﷺ ولم يرفع فيها مثل صلاة الفريضة لم يرفع فيها عليه الصلاة والسلام فإنا نترك كما ترك عليه الصلاة والسلام، ومثل خطبة الجمعة لم يرفع فنترك لا نرفع، مثل الدعاء في آخر الصلاة قبل أن يسلم وبعد السلام ما رفع فلا نرفع في صلاة الفريضة، ومثل الدعاء بين السجدتين ما رفع فلا نرفع، بل ندعو واليد على الفخذين أو على الركبتين من غير رفع؛ لأنا نتأسى به ﷺ في ذلك ونقتدي به عليه الصلاة والسلام، فلو كان الرفع مشروعاً في هذه الأمور لرفع عليه الصلاة والسلام.\nأما الدعوات التي رفع فيها مثل الدعاء في خطبة الاستسقاء نرفع؛ لأنه رفع ﷺ، ومثل الدعاء على الصفا والمروة في السعي، ومثل الدعاء في عرفة في مزدلفة نرفع أيدينا؛ لأنه رفع عليه الصلاة والسلام في ذلك يده، كذلك الدعاء عند الجمرة الأولى والثانية في أيام التشريق فإنه لما دعا ﷺ عند الأولى تقدم وجعلها عن يساره ورفع يديه ودعا عليه الصلاة والسلام، ولما رجم الثانية أخذ ذات الشمال وجعلها عن يمينه ورفع يديه واستقبل القبلة ودعا، فهذا كله مشروع؛ لأنه فعله النبي ﷺ، فأما شيء لم يبلغنا عنه أنه رفع أو ترك فنحن مخيرون؛ إن رفعنا فالرفع من أسباب الإجابة وإن تركنا فلا بأس.\nأما الشيء الذي فعله ولم يرفع فيه مثل ما تقدم فهذا الأفضل لا نرفع فيه السنة لا نرفع فيه مثل خطبة الجمعة ومثل الفرائض الخمس إذا سلمنا منها لا نرفع أو في التحيات لا نرفع أو بين السجدتين لا نرفع؛ لأنه لم يرفع عليه الصلاة والسلام فيها، والخير فيما فعله عليه الصلاة والسلام. نعم.\nالمقدم: لكن إذا فعله الإنسان هل يأثم، هل ينكر عليه؟\nالشيخ: بعد النافلة، أما بعد الفريضة ينكر عليه؛ لأنه فعل شيئاً ما فعله الرسول ﷺ وأسبابه موجودة في عهده ﷺ، فلم يفعله، فلو كان سنة لفعله ﷺ، أما النوافل فأمرها أوسع لكن لا نرى المداومة؛ لأن الرسول ﷺ ما داوم، لو داوم لعرف، لو أنه داوم بعد النوافل لنقله الصحابة وبينوه عليه الصلاة والسلام. نعم.\nالمقدم: إذا صلى ثم تنفل الدعاء بعد هذه النافلة التي هي بعد الفريضة؟\nالشيخ: نعم، لم يفعله النبي ﷺ فيما نقل لم يفعله لكن لو فعله بعض الأحيان نرجو أن لا يكون عليه بأس، أما المداومة فالأولى تركها. نعم.\nالمقدم: يعني: مرة ومرة.\nالشيخ: نعم، تارة وتارة.","link":"https://binbaz.org.sa/fatwas/6872/حكم-رفع-اليدين-عند-الدعاء-بعد-الفريضة-والنافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_134/13405.mp3","categories":["البدع والمحدثات"]},{"id":8722,"question":"هذه رسالة وردت إلى البرنامج من فواز محمد علي من العراق محافظة نينوى يقول في رسالته:ما هو الحكم على المسلم الذي يقيم الفرائض ويتوسل بجاه النبي الكريم ﷺ، وهل يجوز رميه بالشرك أفيدونا أفادكم الله؟","title":"حكم التوسل بجاه الأنبياء والأولياء ونحوهم","answer":"الجواب: المسلم الذي يوحد الله يدعوه وحده سبحانه وتعالى ويؤمن بأنه الإله الحق ويعتقد معنى: لا إله إلا الله: وأن معناها: لا معبود حق إلا الله، ويؤمن بمحمد ﷺ وأنه رسول الله حقاً، أرسله الله إلى العالمين إلى الجن والإنس، هذا يقال له: مسلم؛ لأنه أتى بالشهادتين ووحد الله وحده وصدق الرسول ﷺ، فإنه يكون مسلماً، فإذا أتى شيئاً من المعاصي فإن هذا يكون قدحاً في الإيمان ونقصاً في الإيمان كالزنا والسرقة والربا ولم يعتقد حل ذلك، ولكن أطاع الهوى في فعل هذه المعاصي أو بعضها، فهذا يكون نقصاً في إيمانه وضعفاً في إيمانه.\nأما إذا توسل بجاه النبي ﷺ قال: اللهم إني أسألك يارب بجاه محمد أو بحق محمد، فهذا بدعة عند جمهور أهل العلم ونقصاً في الإيمان وضعفاً ولا يكون مشركاً ولا يكون كافراً بل هو مسلم، لكن يكون هذا نقصاً في الإيمان وضعفاً في الإيمان مثل بقية المعاصي والبدع التي لا تخرج من الدين؛ لأن الدعاء ووسائل الدعاء توقيفية ولم يرد في الشرع ما يدل على أن التوسل بجاهه ﷺ من الوسائل الشرعية بل هذا مما أحدثه الناس.\nفالتوسل بجاه النبي ﷺ، أو بجاه الأنبياء أو بحق النبي أو بحق الأنبياء أو بجاه فلان أو بجاه علي أو بجاه أهل البيت، كل هذا من البدع والواجب ترك ذلك، لكن ليس بشرك وإنما هو من وسائل الشرك وليس بشرك ولا يكون صاحبه مشركاً بل هو مسلم ولكن أتى بدعة تنقص الإيمان وتضعف الإيمان عند جمهور أهل العلم؛ لأن الوسائل في الدعاء توقيفية، فالمسلم يتوسل بأسماء الله وصفاته، كما قال الله : وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] ويتوسل بالتوحيد والإيمان كما جاء في الحديث: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت، الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفواً أحد هذا توسل بتوحيد الله.\nوهكذا التوسل بالأعمال الصالحات، كما في حديث أصحاب الغار الذين انطبقت عليهم صخرة لما دخلوا الغار من أجل المطر أو المبيت فانطبقت عليهم صخرة عظيمة فلم يستطيعوا دفعها، فقال بعضهم لبعض: إنه لن ينجيكم من هذه الصخرة إلا أن تدعو الله بصالح أعمالكم، فدعوا الله بصالح أعمالهم، توسل أحدهم ببره لوالديه فانفرجت الصخرة بعض الشيء، ثم توسل الآخر بعفته عن الزنا وأنه كان له بنت عم يحبها كثيراً فأرادها عن نفسها فأبت عليه ثم إنها ألمت بها سنة وحاجة فجاءت إليه تطلبه العون، فقال لها: إلا أن تمكنيني من نفسك فوافقت على أن يعطيها مائة وعشرين ديناراً من الذهب، فلما جلس برجليها قالت: اتق الله ولا تفض الخاتم إلا بحقه، فخاف من الله سبحانه وقام عنها ولم يأت الفاحشة، وقال: اللهم إن كنت تعلم أني فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه فانفرجت الصخرة بعض الشيء ولكن لا يستطيعون الخروج، ثم توسل الثالث بأدائه الأمانة وأنه كان عنده آصع لبعض العمال تركها عنده نماها وعمل فيها حتى صارت مالاً كثيراً من الإبل والبقر والغنم والرقيق، فلما جاء صاحبها أداها إليه كلها كاملة، فقال: يا رب! إن كنت تعلم أني فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة وخرجوا.\nفهذا يدل على أن التوسل بالأعمال الصالحات من أسباب الإجابة.\nأما التوسل بجاه محمد ﷺ أو بجاه فلان أو بجاه علي أو بجاه عمر أو بجاه الصديق أو بجاه أهل البيت أو ما أشبه ذلك، فهذا ليس له أصل، ولكن يتوسل بالإيمان فيقول: اللهم إني أسألك بإيماني بنبيك ، بإيماني بك بمحبتي لك بمحبتي لنبيك عليه الصلاة والسلام، هذا طيب هذه وسيلة طيبة، أو يتوسل بالتوحيد، اللهم إني أسألك بأنك أنت الله لا إله إلا أنت.. بأني أشهد أنك أنت الله لا إله إلا أنت، بأنك الواحد الأحد كل هذا طيب، أو يتوسل إلى الله ببره لوالديه أو بالمحافظة على الصلوات، أو بعفته عن الفواحش كل هذه أعمال صالحة.\nهذا هو الذي قرره أهل العلم وأهل التحقيق من أهل البصيرة.\nأما التوسل بجاهه بنفسه بجاه فلان أو بحق فلان فهذا بدعة والذي عليه جمهور أهل العلم: أنه غير مشروع. نعم\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6871/حكم-التوسل-بجاه-الانبياء-والاولياء-ونحوهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21602.mp3","categories":["البدع والمحدثات"]},{"id":8761,"question":"إذا توفي واحد عندنا عادة بالسودان بعد أربعين تقوم الأسرة بزيارة للقبر، الحريم والأولاد، ويفتحون القبر ومعهم حبوب ذرة ينشرونها على الميت ويرمون -فيما أعتقد- حجارة على جانبي الميت، هل هذا جائز؟ وهل الحريم يزورون القبور؟","title":"حكم فتح القبور لغير الحاجة والضرورة","answer":"الجواب: هذا العمل بدعة لا أصل له في الشرع، فتح القبر ووضع الحبوب عليه، أو الطيب، أو ملابس، أو غير ذلك كله منكر لا أصل له، بل هو من البدع، والقبر لا يفتح بعد ذلك إلا لحاجة كأن ينسى العَمَلة أدواتهم كالمسحاة ونحوها فيفتح لأجل ذلك، أو يسقط من أحدهم شيء له أهمية فيفتح لأجل ذلك، أما يفتح لرؤية الميت أو لإدخال ملابس عليه أو أطياب أو حبوب، كل هذا بدعة لا أصل له،\nوليس للنساء زيارة القبور أيضًا لقول أبي هريرة وابن عباس وغيرهما: لعن رسول الله ﷺ زائرات القبور، فالرسول ﷺ لعن زائرات القبور، روى ذلك أبو هريرة وابن عباس وحسان بن ثابت رضي الله عنهم، وكان أولًا أذن للجميع في الزيارة، ثم نهى النساء وأقر الرجال وقال لهم: زوروا القبور فإنها تذكركم الآخرة، فأقر الرجال ونهى النساء عن الزيارة، والحكمة في ذلك والله أعلم لأنهن فتنة، ولقلة صبرهن، فكان من حكمة الله أن نهاهن عن الزيارة حتى لا يفتتن ولا يفتن غيرهن. نعم.","link":"https://binbaz.org.sa/fatwas/6907/حكم-فتح-القبور-لغير-الحاجة-والضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16209.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":8776,"question":"هذه رسالة وردتنا من المرسلة صباح محمد علي يونس من العراق من محافظة نينوى، تقول: ذكرتم في حلقات سابقة من هذا البرنامج عدم زيارة الأضرحة وأنها من الشرك بالله، فهل زيارة النبي يونس والنبي جرجيس في نينوى تدخل ضمن ذلك؟ وهل الصلاة فيها غير جائزة؟","title":"حكم زيارة الأضرحة","answer":"الجواب: الزيارة قسمان، زيارة القبور قسمان:\nزيارة شرعية، وزيارة بدعية شركية، أما الزيارة الشرعية فهذه مشروعة لقبور الصالحين والمسلمين جميعاً، وإذا عرف قبر من قبور الأنبياء كقبر نبينا ﷺ تشرع له الزيارة من دون شد الرحل، شد الرحل لا يشد الرحال للقبور لا تشد إلا للمساجد الثلاثة: المسجد الحرام، ومسجد النبي صلى الله عليه وسلم، والمسجد الأقصى، هؤلاء الثلاثة تشد لهم الرحال، أما القبور لا تشد لها الرحال، لكن إذا كان الإنسان في البلد قصدها زائراً فهذا سنة؛ قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، واللفظ الآخر: تذكركم الموت، فزيارة القبور سنة وقربى وقد فعلها النبي ﷺوفعلها أصحابه  وأرضاهم، فإذا زار المسلم قبور المسلمين في بلده ودعا لهم واستغفر لهم كان هذا قربة وطاعة، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، هكذا علمهم النبي ﷺ، وكان يزور القبور ﷺ بنفسه ويدعو للموتى ويستغفر لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد، وفي لفظ يقول: نسأل الله لنا ولكم العافية، فعلى المؤمن أن يفعل مثلما فعله النبي ﷺ إذا زار القبور ومثلما علم أصحابه، يسلم عليهم ويدعو لهم بالمغفرة والرحمة ويستغفر لهم يقول: نسأل الله لنا ولكم العافية، هذه الزيارة الشرعية.\nوهكذا إذا زار قبر النبي ﷺ في المدينة إذا زار المسجد ثم زار قبر النبي ﷺ يسلم عليه ويدعو له يقول: صلى الله وسلم عليك وعلى آلك وأصحابك، جزاك الله عن أمتك خيراً.\nوهكذا إذا زار قبور الصالحين في أي مكان يدعو لهم بالمغفرة والرحمة ويستغفر لهم ويسأل الله لهم العافية.\nأما قبر يونس فلا يعلم بنينوى، جميع قبور الأنبياء لا تعلم ولا تعرف، فدعوى أنه موجود في نينوى أو في غيرها أمر باطل لا أصل له، ذكر العلماء أنه لا يوجد قبر معروف من قبور الأنبياء ألبتة إلا قبر نبينا محمد صلى الله عليه وسلم في المدينة وإلا قبر الخليل في الخليل في المغارة المعروفة، هذا هو المعروف، أما قبور بقية الأنبياء فغير معروفة، لا يونس ولا غيرهم من الأنبياء والرسل، قبورهم الآن غير معلومة، ومن ادعى أن قبر يونس موجود أو فلان أو فلان كله كذب لا صحة له، ولا نعلم نبياً يقال له: جرجيس ، ولا يعرف في الأنبياء من يسمى جرجيس .\nفالمقصود أنه ليس هناك قبر نبي معروف غير قبر نبينا محمد ﷺ في المدينة وغير قبر الخليل في بلد الخليل في المغارة المعروفة.\nالمقدم: وهذه الزيارة التي ذكرتم للرجال والنساء؟\nالشيخ: أما هذه الزيارة الشرعية للرجال، أما النساء فلا يشرع لهم الزيارة على الصحيح، النبي صلى الله عليه وسلم لعن زائرات القبور، فدل ذلك على أن النساء لا يزرن القبور وإنما الزيارة للرجال خاصة في أصح قولي العلماء؛ لما جاءت به الأحاديث الصحيحة عن رسول الله ﷺأنه لعن زائرات القبور، جاء هذا من حديث أبي هريرة ، ومن حديث حسان بن ثابت ، ومن حديث ابن عباس ، فلا يشرع لهن الزيارة ولا تجوز لهن الزيارة، ولكن يدعون للموتى المسلمين في بيوتهم في المساجد في البيوت، وإذا زاروا المدينة دعوا للنبي ﷺ وهم في المسجد أو في بيوتهم، صلوا عليه وسلموا عليه في أي مكان عليه الصلاة والسلام، مثلما قال عليه الصلاة والسلام: لا تتخذوا قبري عيداً ولا بيوتكم قبورا، وصلوا علي فإن صلاتكم تبلغني حيث كنتم عليه الصلاة والسلام، فإذا صلى عليه المؤمن والمؤمنة في أي مكان بلغ ذلك، يقول ﷺ: إن لله ملائكة سياحين يبلغوني عن أمتي السلام عليه الصلاة والسلام.\nفالمشروع لك -أيها السائلة- أن تصلي عليه صلى الله عليه وسلم في أي مكان وعلى بقية الأنبياء عليهم الصلاة والسلام، وأما زيارة هذا القبر الذي يقال له: قبر يونس هذا لا أصل له، ثم النساء لا يزرن القبور على الصحيح، ولكن يدعون لموتى المسلمين ويستغفرون لموتى المسلمين في أي مكان. نعم..","link":"https://binbaz.org.sa/fatwas/6937/حكم-زيارة-الاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21910.mp3","categories":["زيارة القبور","نواقض الإسلام","البدع والمحدثات"]},{"id":8844,"question":"سؤاله الثاني يقول: توجد عقيدة في بعض الناس إذا توفي منهم أحد الأسرة يذبحون ذبيحة بعد شهر، ويقصدون بذلك قطع الشهر، وعقيدتهم الثانية: لا يأكل من الذبيحة من أسرة المتوفى أحد، ونرجو التوجيه حول هذه المعتقدات؟","title":"حكم الذبح عن الميت كل شهر","answer":"الجواب: هذه بدعة لا وجه لها ولا أساس لها، والواجب تركها؛ لأن الرسول عليه السلام يقول: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، وكان يخطب ﷺ يوم الجمعة ويقول في خطبته: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلالة فكونه يذبح عن الميت كل شهر أو كل شهرين أو كل سنة أو كل أربعين يومًا هذا لا أساس له، إنما يشرع الضحية، إذا ضحى في أيام عيد النحر عن نفسه وعن أهل بيته وعن أمواته فلا بأس، فقد كان النبي ﷺ يضحي يوم العيد بكبشين أملحين يذبحهما، أحدهما يذبحه عن محمد وآل محمد، والثاني يذبحه عمن وحد الله من أمته، فهذه يقال لها: الضحية، وهي سنة، كان النبي يفعلها ﷺ ويستمر في ذلك كل سنة.\nفالسنة للأمة أن تذبح ذلك، يضحي الإنسان عن نفسه وعن أهل بيته بأضحية واحدة، وإذا ضحى بأكثر فلا بأس، وإن ضحى عن نفسه بواحدة وعن أمه واحدة وعن أبيه واحدة فلا بأس، صدقة.\nأما أن يجعل شيء من أجل الميت يفعل بالشهر أو بالأسبوع أو بالسنة يأكله فلان وفلان، أو لا يأكله فلان ولا فلان، كل هذا لا أصل له، بل هو من البدع ومن أمر الجاهلية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6999/حكم-الذبح-عن-الميت-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16602.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":8865,"question":"أخونا يقول أيضاً: لاحظت بعض المصلين إذا انتهى المؤذن من إقامة الصلاة رفع يديه ودعا وذلك قبل تكبيرة الإحرام، فهل ورد ذلك عن الرسول ﷺ؟","title":"حكم رفع اليدين والدعاء بين الإقامة وتكبيرة الإحرام","answer":"","link":"https://binbaz.org.sa/fatwas/7020/حكم-رفع-اليدين-والدعاء-بين-الاقامة-وتكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13803.mp3","categories":["البدع والمحدثات"]},{"id":8873,"question":"أخونا أيضًا يقول: أسألكم عن قبور الأولياء؛ أولياء الله الصالحين، مثل: مسجد الحسين والسيد البدوي وهم كثيرون جدًا، وكل واحد يقام له الاحتفالات وتنذر له النذور، ولا أحد ينكر على الناس، أرجو من سماحة الشيخ توجيه الناس إلى ما فيه الخير، وإذا أمكن أيضًا أن يكون التوجيه مكتوبًا فلعله يكون مفيدًا.","title":"حكم زيارة القبور والنذر لها والاحتفال بالموالد","answer":"الجواب: لا شك أن هذا الأمر واقع في الناس، وهو من أعظم المصائب من أعظم الكبائر بل هو الشرك الأعظم ولا حول ولا قوة إلا بالله، فإن الغلو في أصحاب القبور ودعاءهم من دون الله والاستغاثة بهم والتقرب إليهم بالطواف بقبورهم كل هذا من الشرك الأكبر، وهكذا الذبح لهم والنذر لهم كله من الشرك الأكبر.\nأما الاحتفالات بمواليدهم فهذه من البدع التي يجب تركها، لكن لو وقع فيها دعاؤهم والاستغاثة بهم صار ذلك من الشرك الأكبر، وكثير من الناس في الاحتفالات قد يدعون المحتفل به ويستغيثون به كما يفعل هذا بعض الناس عند احتفاله بمولد النبي عليه الصلاة والسلام، فالبدع تجر إلى الشرك وهي بريد له، وهي أعظم المنكرات بعد الشرك البدع، فإن المنكرات مراتب أعظمها الشرك بالله  وأنواع الكفر به سبحانه وتعالى ثم يلي ذلك البدع؛ لأنها زيادة في الدين واعتراض على الله، فهي وسيلة إلى الشرك بالله ، فالواجب الحذر منها ومن ذلك البناء على القبور واتخاذ القباب عليها وإقامة الموالد والاحتفال بها كل هذا من وسائل الشرك، فإن القبر متى عظم بالبناء واتخاذ القبة عليه والمسجد فإن العامة يظنون أن هذا يدل على أنه يدعى من دون الله فيستغيثون به وينذرون له ويظنون أنه يقضي حوائجهم وأنه يشفع لهم عند الله بهذا العمل السيئ، وهذا هو عمل المشركين الأولين هو دينهم دين قريش وأشباههم، الغلو في الأموات والاستغاثة بأصحاب القبور ودعاؤهم من دون الله والنذر لهم هذا هو دين قريش كما قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] فرد الله عليهم بقوله سبحانه: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] فبين سبحانه أنه لا يعلم له شريكًا لا في السماء ولا في الأرض وأنكر عليهم عملهم هذا.\nفليس المشركون على حق بل هم على باطل، وليست آلهتهم التي دعوها من دون الله تشفع لهم، قال الله تعالى: فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ [المدثر:48] وهكذا قوله سبحانه في الآية الأخرى: فاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:2-3] يعني: يقولون: ما نعبدهم إلا ليقربونا إلى الله زلفى، فأخبرعن المشركين أنهم اتخذوا آلهتهم التي عبدوها من دون الله يزعمون أنها تقربهم إلى الله زلفى، ولم يزعموا أنها تخلق أو ترزق، لا، وإنما أرادوا تقريبها لهم عند الله وشفاعتها لهم عند الله ومع هذا حكم الله عليهم بالشرك والكفر، قال تعالى في هذه الآية: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّار [الزمر:3] سماهم كذبة في دعواهم أنها تقربهم كفرة في هذا العمل، فالواجب الحذر من هذا الغلو وهذه البدع التي أحدثها الناس عند القبور فإنها شر عظيم وفساد كبير ووقوعها يجر إلى الشرك فإنه متى عكف على القبر وبنى عليه وعظمه بالستور والأطياب فإن ذلك يجره إلى أن يدعوه من دون الله وإلى أن يستغيث به وهذا هو الشرك الأكبر عند جميع أهل العلم.\nفيجب الحذر من هذا البلاء العظيم، ويجب على العلماء أن يبينوا للناس هذه الشركيات وهذه المنكرات وأن يرشدوهم إلى الحق حتى يدعوه.. حتى يدعوا هذا الباطل .. حتى يدعوا هذا الشرك.\nوقد مكث النبي ﷺ في مكة عشر سنين يدعو الناس إلى توحيد الله وينكر عليهم الشرك بالله وعبادة الأوثان والأصنام وأصحاب القبور ثم فرض الله عليه الصلوات الخمس فبقي بعدها في مكة نحو ثلاث سنين يدعو إلى توحيد الله والإخلاص له ثم هاجر إلى المدينة عليه الصلاة والسلام، ولم يزل يدعو إلى الله ويعلم الناس ما شرع الله لهم حتى توفاه الله عليه الصلاة والسلام ونقله إلى الرفيق الأعلى عليه من ربه أفضل الصلاة والتسليم.\nفالواجب على خلفائه وهم العلماء أن يتقوا الله، وأن يبينوا للناس دينهم على الوجه الذي لا خفاء فيه.\nولا ريب أن سكوت العلماء ومن ينسب إلى العلم عن العامة وهم يفعلون هذه الأفعال التي هي التعلق بالأموات والاستغاثة بالأموات، لا شك أن سكوتهم يشجع هؤلاء على هذا الشرك ويعتقدون أن هذا السكوت دليل على أن هذا جائز وأنه لا حرج فيه.\nفالواجب الحذر، والواجب على العامة أن يسألوا أهل العلم المعروفين بالعقيدة الصالحة وتعظيم كتاب الله وسنة رسوله عليه الصلاة والسلام، والواجب على العلماء أن يتقوا الله ويتبصروا وأن ينكروا ما أنكره الله ورسوله من الشرك وسائر المعاصي، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7029/حكم-زيارة-القبور-والنذر-لها-والاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16702.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":8902,"question":"يذكر أن له أهلًا وجيران وأعمام وأخوال ولديهم بدعة يسميها الدستور، ويسأل عن هذا لو تكرمتم ولا سيما وقد عرف قول الرسول ﷺ : أن كل بدعة ضلالة وأن كل ضلالة في النار؟","title":"حكم الابتداع في الدين","answer":"الجواب: لم يشرح لنا هذه البدعة كونها تسمى الدستور ما نعرف هذه البدعة، لكن القاعدة الشرعية: أن كل عبادة أحدثها الناس لم تكن فيما شرعه الله على لسان نبيه عليه الصلاة والسلام، فإنها بدعة سواء سميت دستورًا أو سميت باسم آخر فلا عبرة بالأسماء، الله أكمل الدين وأتمه سبحانه وتعالى، فمن أحدث في الدين ما لم يأذن به الله فبدعته مردودة عليه، قال الله تعالى: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].\nقال تعالى: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمْ الإِسْلامَ دِينًا [المائدة:3] وقال عليه الصلاة والسلام في الحديث الصحيح: من أحدث في أمرنا هذا -يعني: في ديننا هذا - ما ليس منه فهو رد يعني: فهو مردود، متفق على صحته. وقال أيضا عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد يعني: مردود. وكان يقول في خطبة الجمعة عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها وكل بدعة ضلالة خرجه الإمام مسلم في صحيحه، زاد النسائي رحمه الله بإسناد صحيح: وكل ضلالة في النار.\nفهذه الأحاديث وما جاء في معناها كلها تدل على أن جميع البدع يجب اطراحها والحذر منها، ولا عبرة بأسمائها، بل متى صارت بدعة لم يفعلها الرسول ﷺ ولا أصحابه فإنها تتطرح وينهى عنها سواء كانت تتعلق بالصلاة أو بالحج أو بالصيام أو بغير ذلك، مثل بدعة البناء على القبور اتخاذ القباب عليها هذا منكر يجب إزالته، يجب على ولاة الأمور إزالة ذلك، ومثل بدعة الموالد الاحتفال بالموالد مولد الأم أومولد الولد أو مولد النبي ﷺ أو مولد الشيخ عبد القادر الجيلاني ، أو مولد الحسين ، أو مولد البدوي أو غير ذلك.\nهذه الاحتفالات بهذه الموالد لا أصل لها بل هي مما ابتدعه الناس، وأول من ابتدع ذلك الطائفة المعروفة المسماة الفاطميين حكام المغرب ومصر في المائة الرابعة والخامسة، هؤلاء من الرافضة أحدثوا هذه البدع بدعة الموالد، فلا يجوز الاقتداء بهم ولا التأسي بهم في ذلك؛ لأنهم هم أهل بدع فلا يجوز التأسي بهم، ومن تأسى بهم بعدهم فقد غلط، والواجب على المؤمن أن تكون أسوته رسول الله عليه الصلاة والسلام، كما قال الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ثم صحابته رضي الله عنهم وأرضاهم وعلى رأسهم الخلفاء الراشدون، فشيء لم يفعله ﷺ ولا خلفاؤه الراشدون لماذا نفعله؟يجب علينا أن نطرحه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7058/حكم-الابتداع-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16804.mp3","categories":["البدع والمحدثات"]},{"id":8918,"question":"ننتقل بعد هذا إلى رسالة أخرى وصلت إلى البرنامج من خميس البحر، وباعثها أخونا: محمد شيخ عثمان جبريل البوجد ، أخونا سأل مجموعةً من الأسئلة في حلقة مضت، وفي هذه الحلقة يسأل ويقول: إن هناك أناسًا يدعون عقب كل صلاة، الإمام يدعو والجماعة يقولون: آمين آمين، فما حكم ذلك في الشرع بالإجماع -كما يقول-؟","title":"حكم الأذكار والأوراد الجماعية عقب كل صلاة","answer":"الجواب: هذا الذي سألت عنه أيها السائل لا نعلم له أصلًا في الشرع، فلم يكن النبي ﷺ يفعل ذلك إذا صلى الفجر أو الظهر أو العصر أو المغرب أو العشاء، ما كان يفعل هذا الذي سألت عنه، وهو رفع اليدين والدعاء من الإمام والمأمومين، هذا شيء لا أساس له ولا يشرع بل هو بدعة؛ إذ لو كان مشروعًا لنقله الصحابة وبينوه لنا عن النبي عليه الصلاة والسلام، ثم لو كان مشروعًا قد فعله الرسول ﷺ لفعلوه هم الصحابة أيضًا، كالخلفاء الراشدين وغيرهم من الصحابة، ولم يثبت عنه بما نعلم أنهم فعلوا ذلك ولا أنهم نقلوه عن النبي ﷺ فوجب تركه، والإنسان إذا أحب أن يدعو يدعو بينه وبين نفسه من دون رفع اليدين ومن دون اجتماع مع الإمام بل يدعو بينه وبين نفسه كما جاءت به الأحاديث أن الرسول ﷺ دعا بعد السلام ودعا قبل السلام عليه الصلاة والسلام، لكن لم يثبت عنه ﷺ أنه رفع يديه بعد السلام من الفريضة، ولا أنه دعا وأمن عليه المأمومون، والخير في اتباعه عليه الصلاة والسلام، وهذه أمور ظاهرة يعلمها الناس ويراها الناس، فلو فعل شيئًا من هذا لنقله الصحابة وعرفوه رضي الله عنهم وأرضاهم، فالواجب ترك ذلك؛ لأنه لم ينقل عن الرسول ﷺ ولا عن أصحابه والخير في اتباعهم وسلوك سبيلهم ، وصلى الله وسلم على نبيه محمد وعلى آله وأصحابه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7075/حكم-الاذكار-والاوراد-الجماعية-عقب-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_171/17102.mp3","categories":["البدع والمحدثات"]},{"id":8927,"question":"يقال: إن هناك رجالاً من رجال الخطوة وهم يحجون بدون أي وسيلة مواصلات، ويقال: إنهم يحضرون الجنازة في مكة وهم أصلًا موجودون في منطقة بعيدة جدًا، فهل سخرت لهم الريح مثلًا في تنقلاتهم نرجو التوجيه؟","title":"مدى صحة حج بعض الناس بدون وسائل مواصلات","answer":"الجواب: هذه من خرافات الناس وضلالهم، وقد يدعيها بعض الصوفية الذين يزعمون أنهم لهم كرامات يستطيعون بها أن يصلوا إلى مكة من دون سيارات ولا طائرات ولا غير ذلك، هذه من خرافاتهم وضلالاتهم، وقد يكون لبعضهم اتصال بالجن وخدمة للجن وعبادة للجن فتحمله الجن إلى مكة وإلى غيرها كما ذكر ذلك أبو العباس ابن تيمية رحمه الله شيخ الإسلام وغيره.\nهذا قد يقع لبعض عباد الجن وخدمة الجن، وهؤلاء لا عبرة بهم ولا يعول عليهم؛ لأن من عبد الجن هو من المشركين وحجه باطل.\nفالحاصل أن هذه الأخبار إما أن تكون من قبيل الخرافات التي يقولها الصوفية وأشباههم من يزعم أنه ولي وأن له كرامات وهو يكذب، وإما أن يكون من أولياء الشيطان ممن تحمله الشياطين وتنقله من مكان إلى مكان؛ لأنه عبدها وأطاعها، فلما خدمها وعبدها خدمته في نقله من مكان إلى مكان، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/7084/مدى-صحة-حج-بعض-الناس-بدون-وساىل-مواصلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14302.mp3","categories":["البدع والمحدثات"]},{"id":8934,"question":"رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية باعثها أحد الإخوة من هناك يقول جمال عبده أحمد صالح الشعبي أستاذ يمني من مدرسة الفوز الابتدائية ناحية الزهرة لواء الحديدة، أخونا يسأل سؤال ويقول: متى تجوز مقاطعة المبتدع؟ ومتى يجوز البغض في الله، وهل تؤثر المقاطعة في هذا العصر؟","title":"حكم هجر المبتدع","answer":"الجواب: المؤمن ينظر في هذه المقامات بنظر الإيمان ونظر الشرع ونظر التجرد من الهوى، فإذا كان هجره للمبتدع وبعده عنه لا يترتب عليه شر أعظم فإن هجره حق وأقل أحواله أن يكون سنة، وهكذا هجر من أعلن المعاصي وأظهرها أقل أحواله أنه سنة، فإن كان عدم الهجر أصلح؛ لأنه يرى أن دعوة هؤلاء المبتدعين وإرشادهم إلى السنة وتعليمهم ما أوجب الله عليهم أن ذلك يؤثر فيهم وأنه يفيدهم فلا يعجل في الهجر، ومع ذلك يبغضهم في الله كما يبغض الكافر في الله، يبغض العصاة في الله على قدر معاصيهم وعلى قدر البدعة.\nبغض الكافر أشد، وبغض المبتدع على قدر بدعته إذا كانت غير مكفرة على قدرها، وبغض العاصي على قدر معصيته، ويحبه في الله على قدر إسلامه.\nأما الهجر ففيه تفصيل، يقول ابن عبد القوي رحمه الله في قصيدته المشهورة:\nوهجران من أبدى المعاصي سنة وقد قيل أن يردع وأوجب وأكد\nوقيل على الإطلاق ما دام معلنا ولاقـه بوجـه مكفهر مربد\nوقيل: (على الإطلاق). يعني يجب الهجر مطلقاً.\nفالحاصل: أن الأرجح والأولى النظر في المصلحة، فالنبي ﷺ هجر قوماً وترك آخرين لم يهجرهم مراعاة للمصلحة الشرعية الإسلامية، فهجر كعب بن مالك وصاحبيه  لما تخلفوا عن غزوة تبوك بغير عذر هجرهم خمسين ليلة حتى تابوا فتاب الله عليهم، ولم يهجر عبد الله بن أبي بن سلول وجماعة من المتهمين بالنفاق لأسباب شرعية اقتضت ذلك.\nفالمؤمن ينظر في الأصلح وهذا لا ينافي بغض الكافر في الله وبغض المبتدع في الله وبغض العاصي في الله، ومحبة المسلم في الله ومحبة العاصي على قدر إسلامه، ومحبة المبتدع الذي لم يكفر ببدعته على قدر ما معه من الإسلام لا ينافي ذلك.\nأما هجرهم فينظر في المصلحة، فإذا كان هجرهم يرجى فيه الخير لهم يرجى فيه أن يتوبوا إلى الله فيه من البدعة ومن المعصية فإن السنة الهجر، وقد أوجب ذلك جمع من أهل العلم قالوا: يجب.\nوإن كان هجرهم وتركه سواء لا يترتب عليه لا شر ولا خير، فهجرهم أولى أيضاً إظهاراً للأمر المشروع وإبانة لما يجب من إظهار إنكار المنكر، فهجرهم في هذه الحال أولى وأسلم، وحتى يعلم الناس خطأهم وغلطهم.\nوالحالة الثالثة: أن يكون هجرهم يترتب عليه مفسدة وشر أكبر فإنه لا يهجرهم في هذه الحال، إذا كان هذا المبتدع إذا هجر زاد شره على الناس وانطلق في الدعوة إلى البدعة وزادت بدعه وشروره، واستغل الهجر في دعوة الناس إلى الباطل فإنه لا يهجر بل يناقش ويحذر الناس منه، ولا يكون الناس عنه بعيدين حتى يراقبوا عمله، وحتى يمنعوه من التوسع في بدعته، وحتى يحذروا الناس منه، وحتى يكرروا عليه الدعوة لعل الله يهديه حتى يسلم الناس من شره.\nوهكذا العاصي المعلن إذا كان تركه وهجره قد يفضي إلى انتشار شره وتوسع شره وتسلطه على الناس فإنه لا يهجر بل يناقش دائماً وينكر عليه دائماً، ويحذر الناس من شره دائماً حتى يسلم الناس من شره وحتى لا تقع الفتن بمعصيته، نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/7092/حكم-هجر-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14309.mp3","categories":["البدع والمحدثات"]},{"id":8947,"question":"أخونا يسأل ويقول: ما حكم الموالد التي تقام كل عام؟","title":"ما حكم الموالد التي تقام كل عام؟","answer":"الجواب: الموالد يعني الاحتفال بالموالد بدعة لم يفعلها رسول الله ﷺ ولا خلفاؤه الراشدون ، ولا صحابته المرضيون  جميعًا ولا التابعون في القرن الأول والثاني والثالث وهي القرون المفضلة فاتضح أنها بدعة والرسول عليه الصلاة والسلام يقول: من عمل عملًا ليس عليه أمرنا فهو رد رواه مسلم في الصحيح، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: مردود، ويقول عليه الصلاة والسلام في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها وكل بدعة ضلالة خرجه مسلم في الصحيح، زاد النسائي بإسناد صحيح: وكل ضلالة في النار وفي حديث العرباض بن سارية: إياكم ومحدثات الأمور فإن كل محدثة بدعة وكل بدعة ضلالة فهذه الاحتفالات بمولد الرسول ﷺ أو مولد البدوي أو مولد الحسين أو مولد فاطمة أو مولد فلان أو فلان أو الشيخ عبد القادر أو غير هذا كلها من البدع، والواجب على المسلمين تركها والحذر من التشجيع عليها، الواجب علينا اتباع الرسول ﷺ والسير على منهاجه ومنهاج أصحابه  وأرضاهم.\nأما أن يحدث شيئًا ما شرعه الله هذا لا يجوز لنا، الدين كامل الحمد لله، يقول الله سبحانه: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3]، فشيء لم يفعله الرسول ﷺ ولا صحابته ليس لنا أن نفعله، هم أعلم منا وخير منا وأفضل منا وأعلم منا بالشرع، وأحب منا للرسول ﷺ فإذا فعلوا شيئًا تابعناهم فيه.\nوأما أن نحدث لا، ليس لنا أن نحدث، الله يقول: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] فيكفينا الاتباع وعلينا أن نحذر الابتداع، ولهذا يقول الصحابة  وأرضاهم: \"اتبعوا\" الصحابة يوصون التابعين يقولون لهم: «اتبعوا ولا تبتدعوا فقد كفيت » قد كفينا والحمد لله، أرأيت لو أن إنسانًا أحدث صلاة سادسة وقال: أنا قصدي الخير ويجب أن نصلي الساعة عشر بالتوقيت الزوالي ضحى، صلاة أخرى سادسة أو الساعة تسع؛ لأن الوقت طويل بين الفجر وبين الظهر فينبغي أن نجعل صلاة سادسة في هذا الوقت الطويل، هل يكون مأجورًا أو مأزورًا؟ بإجماع أهل العلم أنه مأزور وأنه مبطل وأنه مبتدع مع أنه يقول: صلوا، ما قال: ازنوا ولا قال: اسرقوا، قال: صلوا صلاة سادسة، لماذا؟ لأنه مبتدع؛ لأنه شرع دينًا لم يأذن به الله.\nوهكذا لو قال: علينا أن نحج مرتين بدل مرة في السنة مرة في ذي الحجة ومرة في مثلًا رجب أو في جمادى أو في رمضان لو قال أحد هذا صار مبطلًا عند جميع أهل العلم مع أنه ما دعا إلا إلى حج ما دعا إلا إلى ذكر وطاعة لكنها ليس في محلها بدعة.\nوهكذا لو قال: رمضان ما يكفي، نصوم شهرًا آخر، نصوم مع رمضان شهرًا ثان، ودعا إلى هذا نصوم مثلًا ربيع الآخر أو جمادى الأولى مع رمضان أو المحرم أو صفر؛ لأن هذا مزيد خير وطاعة أو عبادة يكون هذا مبتدع أيضًا، فهكذا إذا قال: علينا أن نحتفل بالرسول ﷺ في مولده، أو نحتفل بيوم الفتح أو يوم بدر أو نحتفل بمولد الصديق أو مولد عمر أو مولد عثمان أو مولد علي أو مولد فاطمة أو مولد هود أو صالح من أنبياء الله أو مولد غير ذلك من الأخيار يقال: هذا بدعة، ما دام الرسول ما فعله ﷺ وهو أنصح الناس وأفضل الناس وأعلم الناس وأتقى الناس وأخشى الناس لله ومع هذا ما فعله ولا دعا إليه ولا قال: إذا جاء يوم مولدي فاحتفلوا بي، وافعلوا كذا وافعلوا كذا، ولا فعله الصديق الأكبر أفضل الخلق بعد الأنبياء، ولا فعله الفاروق عمر ولا فعله عثمان ذو النورين ولا فعله علي  المرتضى أبو الحسن  ولا فعله بقية الصحابة ولا فعله التابعون ولا أتباعهم بإحسان في القرون المفضلة وإنما أول من أحدثه طائفة الفاطميين الذين هم شيعة رافضة أحدثوه، وجعلوا هناك موالد للنبي ﷺ ولحاكمهم ولـفاطمة وللحسين فكيف يقتدى بهؤلاء؟ لا يقتدي بهم من يعقل ولا من يعظم دين الله لكن تابعهم بعض الناس بعد هذا ومن تابعهم ليس بقدوة والواجب التأسي بالرسول ﷺ وبأصحابه وبالمسارعة إلى نهيه، هذا هو الواجب على المسلمين أينما كانوا، فنسأل الله أن يوفق المسلمين للتأسي به ﷺ والسير على منهاجه وأن يوفقهم لترك البدع كلها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7105/ما-حكم-الموالد-التي-تقام-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17209.mp3","categories":["البدع والمحدثات"]},{"id":8951,"question":"الرسالة التالية باعثتها إحدى الأخوات المستمعات تقول: (أ. أ. ع) من الشرقية، أختنا لها مجموعة من الأسئلة بدأت رسالتها تقول: أولًا أشكر البرنامج على ما يقدمه لنا من فتاوى قيمة، وجزى الله العلماء الأفاضل خير الجزاء على تفضلهم بالإجابة على أسئلتنا وجزاكم الله خيرًا.أرجو عرض أسئلتي الآتية على سماحة الشيخ عبدالعزيز بن باز: هل لبس الدبلة للنساء بدعة نصرانية؛ لأنني قرأت بأن دبلة الخطبة أو الزواج للرجل وإن كانت فضة وأيضًا للمرأة بدعة نصرانية، هل هذا صحيح؟","title":"حكم لبس دبلة الخطبة والزواج","answer":"الجواب: الدبلة التي تسأل عنها السائلة لا نعلم لها أصلًا والذي يظهر لنا من ذلك أن فيها تشبهًا بالكفرة؛ لأنها من عادتهم فيما بلغنا فلا ينبغي اتخاذها، فإن الإشارة إلى الزواج تكون بالخطبة والاتفاق بين الخاطب والمخطوب منهم ويكفي ذلك من غير حاجة إلى الدبلة، ومتى تم الأمر بالعقد الشرعي انتهى كل شيء، أما الدبلة فلا حاجة إليها ولا حاجة إلى التشبه بأعداء الله، لا من النصارى ولا من غيرهم، والواجب البعد عن مشابهة أعداء الله في كل شيء. نعم.","link":"https://binbaz.org.sa/fatwas/7108/حكم-لبس-دبلة-الخطبة-والزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17302.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":8966,"question":"نعود إلى رسالة الأخ أحمد الحوري من دمشق أخونا عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة له مجموعة من الأسئلة يقول: قال تعالى في كتابه العزيز: وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا ۝ فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:64-65]، والسؤال هو: إن بعض المسلمين يأخذون بهذه الآية أنه لا حرج على المسلم أن يذهب ويشد الرحل إلى قبر الرسول ﷺ  يسأله أن يستغفر له رسول الله ﷺ  وهو في قبره، فهل هذا العمل صحيح كما قال تعالى؟ وهل معنى (جاءوك) باللغة أنهم جاءوك في حياتك أم في موتك، وهل يرتد المسلم عن الإسلام إذا لم يحكم سنة رسول الله ﷺ، وهل التشاجر هنا على الدنيا أم على الدين؟","title":"حكم شد الرحال إلى قبر النبي وسؤاله المغفرة","answer":"الجواب: هذه الآية الكريمة فيها حث الأمة على المجيء إليه إذا ظلموا أنفسهم بشيء من المعاصي، أو وقعوا فيما هو أكبر من ذلك من الشرك أن يجيئوا إليه تائبين نادمين حتى يستغفر لهم عليه الصلاة والسلام، وهذا المراد به في حياته ﷺ  وهو يدعو المنافقين وغيرهم إلى أن يأتوا إليه ليعلنوا توبتهم ورجوعهم إلى الله عز وجل ويطلبوه عليه الصلاة والسلام أن يسأل الله أن يقبل توبتهم وأن يصلح أحوالهم، ولهذا قال: وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ [النساء:64] طاعة الرسل بإذن الله، من أذن الله وأراد هدايته اهتدى، ومن لم يرد الله هدايته لم يهتد، فالأمر بيده  ما شاء الله كان وما لم يشأ لم يكن، وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:29].\nثم قال: وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنفُسَهُمْ جَاءُوكَ أي: النبي عليه الصلاة والسلام فَاسْتَغْفَرُوا اللَّهَ يعني: تائبين نادمين لا بمجرد القول، وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ يعني: دعا لهم بالمغفرة لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا [النساء:64]، فهو حث لهم، حث للعباد على أن يأتوا إلى النبي ﷺ ليعلنوا عنده توبتهم وليسأل الله لهم، وليس المراد بعد وفاته ﷺ كما يظنه بعض الجهال! لا، بعد موته لا يؤتى لهذا الغرض وإنما يؤتى للسلام عليه لمن كان في المدينة أو وصل إليها من خارجها لقصد الصلاة في المسجد والقراءة فيه ونحو ذلك، فإذا أتى المسجد سلم على النبي ﷺ  وعلى صاحبيه، لكن لا يشد الرحل من أجل زيارة القبر فقط بل من أجل المسجد و تكون الزيارة للقبر الشريف وقبري الصديق و عمر تابعةً لزيارة المسجد؛ لقوله ﷺ : لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، فالقبور لا يشد لها الرحال ولكن متى وصل إلى المسجد وفي نيته السلام على الرسول ﷺ  وعلى صاحبيه، أو ليس في نيته ذلك فإنه يشرع له أن يسلم على النبي ﷺ  وأن يسلم على صاحبيه رضي الله عنهما لكن لا يشد الرحل لأجل الزيارة فقط زيارة القبر فقط للحديث السابق.\nوأما ما يتعلق بالاستغفار والتوبة فهذا كما يكون: في حياته، لا بعد وفاته.\nوالدليل على هذا: أن الصحابة  وأرضاهم لم يفعلوا ذلك، وهم أعلم الناس بالنبي ﷺ  وأفقه الناس، ولأنه ﷺ  لا يملك ذلك بعد وفاته عليه الصلاة والسلام كما قال عليه الصلاة والسلام: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له، وأخبر عليه الصلاة والسلام أن من صلى عليه تعرض صلاته عليه، عليه الصلاة والسلام، هذا شيء خاص فيما يتعلق بالصلاة عليه عليه الصلاة والسلام: من صلى علي صلى الله عليه بها عشرًا، وقال عليه الصلاة والسلام: أكثروا علي من الصلاة يوم الجمعة فإن صلاتكم معروضة علي، قيل: يا رسول الله! وكيف تعرض عليك وقد أرمت -يعني: بليت- قال: إن الله حرم على الأرض أن تأكل أجساد الأنبياء.\nفهذا خاص بالصلاة عليه عليه الصلاة والسلام، وفي اللفظ الآخر: إن لله ملائكة سياحين يبلغونني عن أمتي السلام هذا شيء خاص بالصلاة والسلام عليه عليه الصلاة والسلام أنه يبلغ ذلك.\nوأما أنه يأتي من ظلم نفسه ليتوب عند القبر وليستغفر عند القبر فهذا لا أصل له بل هو منكر ولا يجوز وهو وسيلة إلى الشرك، وسيلة إلى أن يأتي فيسأله الشفاعة ويسأله شفاء المريض أو كذا أو كذا، أو يسأله أن يدعو له وهذا لا يجوز؛ لأن هذا ليس من خصائصه عليه الصلاة والسلام بعد وفاته ولا من خصائص غيره، فكونه ممن مات لا يدعى ولا يطلب منه الشفاعة، لا النبي ولا غيره عليه الصلاة والسلام، وإنما الشفاعة تطلب منه في حياته ﷺ، يقول الرجل: يا رسول الله! اشفع لي أن يغفر الله لي، اشفع لي أن يشفي الله مريضي.. أن يرد غائبي.. أن يعطني كذا وكذا.\nوهكذا يوم القيامة بعد البعث والنشور؛ لأنهم أحياء، فإن المؤمنين يأتون آدم ليشفع لهم حتى يقضى بينهم فيعتذر، ويحيلهم إلى نوح فيعتذر نوح ثم يحيلهم نوح إلى إبراهيم فيعتذر، ثم يحليهم إبراهيم إلى موسى فيعتذر، ثم يحيلهم موسى إلى عيسى فيعتذر عليهم الصلاة والسلام، ثم يحيلهم عيسى عليه الصلاة والسلام إلى محمد ﷺ فيقول: أنا لها، فيتقدم ويسجد تحت العرش عليه الصلاة والسلام ويحمد ربه بمحامد عظيمة، ثم يشفع في أهل الموقف حتى يقضى بينهم.\nوهكذا يشفع في أهل الجنة حتى يدخلوا الجنة؛ لأنه حي قائم موجود، أما في البرزخ بعد وفاته ﷺ فلا يسأل الشفاعة، ولا يسأل أن يستغفر للناس، ولا يسأل شفاء المريض ولا رد الغائب، ولا غير ذلك من الأمور، وهكذا بقية الأموات لا يسألون شيئًا من هذه الأمور بل يدعى لهم ويستغفر لهم إذا كانوا مسلمين. نعم.","link":"https://binbaz.org.sa/fatwas/7124/حكم-شد-الرحال-الى-قبر-النبي-وسواله-المغفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17311.mp3","categories":["البدع والمحدثات","مسائل متفرقة في العقيدة"]},{"id":8987,"question":"هل من ذنب عليك إذا استمعت إلى المولد ملزمًا أو مجبرًا احترامًا لأبيك، وإذا كان لا، فماذا أعمل أفيدوني أفادكم الله؟","title":"حضور المولد اضطرارًا","answer":"الجواب: الاحتفال بالموالد من البدع التي أحدثها الناس في القرن الرابع الهجري، فلا ينبغي لأحد أن يتأسى بمن أحدث البدع، وهكذا ما ذكر عن ملك إربل أنه أحدث ذلك، كل هذا لا يليق بأهل العلم والإيمان أن يتأسوا بمن أحدث البدع ولو كان معروفًا ولو كان كبيرًا كبعض الملوك والأمراء أو بعض ممن يغضب من أهل العلم، فإن القاعدة التي يجب الالتزام بها ويجب السير عليها، أن ما تنازع فيه الناس وما أحدثه الناس يعرض على كتاب الله وعلى سنة رسوله عليه الصلاة والسلام، فما وافقهما قبل وما خالفهما رد، كما قال الله  في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59].\nقال العلماء رحمهم الله: الرد إلى الله هو الرد إلى القرآن العظيم، والرد إلى الرسول عليه الصلاة والسلام هو الرد إليه في حياته وإلى سنته بعد وفاته عليه الصلاة والسلام، وفي الآية الأخرى: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].\nفالواجب على أهل الإيمان عند النزاع وعند الاختلاف وعند إحداث البدع أن يرد ما تنازع فيه الناس وما اختلفوا فيه إلى كتاب ربهم وسنة نبيهم فما شهدا له بالقبول قبل وما لا فإنه يرد.\nوقد نظرنا وسبرنا ما وقع في الناس من هذه الموالد، ودرسنا سيرة النبي ﷺ وسيرة أصحابه فلم نجده ﷺ احتفل بمولده لا في المدينة ولا في مكة، لا قبل الهجرة ولا بعد الهجرة، لا قبل الفتح ولا بعد الفتح. فقولهم: إنه يحضر ويقومون له هذا من المنكر ومن الباطل من التلبيس على العامة، والواجب على أهل الإيمان اتباع سنته وتعظيم أمره ونهيه لا إحداث الموالد، ويش الفائدة من الموالد التي فيها البدع والشر، الله يقول سبحانه: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31]، ويقول : وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، ويقول سبحانه: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، ويقول جل وعلا: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، ويقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] الآية.\nفالذي يحب الرسول ﷺ صادقًا يتبعه، ويستقيم على طريقته في أداء الأوامر وترك النواهي والوقوف عند الحدود، والدعوة إلى سبيله وإلى سنته والذب عنها والتحذير من خلافها، هكذا يكون المؤمن، هكذا يكون طالب النجاة، هكذا يكون المعظم لرسول الله ﷺ، يعظم سنته ويدعو إليها ويستقيم عليها قولًا وعملًا وعقيدة، وينهى الناس عن خلافها وعن الخروج عليها، هكذا المؤمن الصادق وهكذا العالم الموفق يعظم السنة ويدعو إليها ويستقيم عليها ويحافظ عليها ويمثلها بأخلاقه وأعماله، هكذا الحب للرسول ﷺ، وهكذا الحب لله توحيده وطاعته خوفه ورجاؤه والشوق إليه، والمسارعة إلى مراضيه، والحذر من مناهيه، والوقوف عند حدوده، هكذا يكون المؤمن الصادق في حبه لله ورسوله.\nأما إحداث البدع فليست من دلائل الإيمان، ولا من دلائل الصدق، ولكنها من تزيين الشيطان ومن تلبيسه على الناس حتى يحدثوا ما لم يأذن به الله، ولهذا قال سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].\nوالمحب له ﷺ يجتهد في اتباع شريعته واتباع طريقه ليعلم الناس سنته وأخلاقه وأعماله، في المدارس، وفي المساجد، وفي البيوت، وفي السفر، وفي الحضر، وفي الطائرة، وفي السيارة، وفي القطار، وفي كل مكان، هكذا المؤمن الصادق العالم يعتني بالسنة ويعلمها الناس ويعمل بها، وفي غنية عن إحداث البدع، المسلمون في غنية كاملة عن البدع، أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، ويقول سبحانه: ثُمَّ جَعَلْنَاكَ يخاطب النبي ﷺ. ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا وَلا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لا يَعْلَمُونَ ۝ إِنَّهُمْ لَنْ يُغْنُوا عَنكَ مِنَ اللَّهِ شَيْئًا [الجاثية:18-19]، هكذا أمره ﷺ أمر الله نبيه أن يستقيم على الشريعة التي بينت له وأمر بها فهكذا أمته، عليهم أن يستقيموا على الشريعة التي جاء بها عليه الصلاة والسلام، وعليهم أن يلزموها ولا يزيدوا ولا ينقصوا، نعم.","link":"https://binbaz.org.sa/fatwas/7145/حضور-المولد-اضطرارا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_175/175003.mp3","categories":["البدع والمحدثات"]},{"id":9005,"question":"السؤال الثاني في رسالة الأخ: رزق محمد رزق المصري، والأخ: عابد هريسان فهيد، يقولون فيه: ما هو حكم المساجد التي بها قبور بعض الصالحين، هل تصح الصلاة فيها أم لا؟ وهل يصح النذر لهؤلاء المشايخ أفيدونا أفادكم الله، وما هو حكم الشرع في أصحاب الطرق الموجودة حالياً في أكثر الدول الإسلامية أمثال: الصوفية، والبومية، والبهائية، والمعتزلة وغيرها من الطرق، وما حكم ما يذكرونه من الصلوات النارية، والتسبيح بأعداد كبيرة، وقراءة القرآن بأعداد أيضاً أفيدونا أفادكم الله؟","title":"حكم بناء المساجد على القبور، والتعريف ببعض الفرق الضالة","answer":"الجواب: أما المساجد التي تبنى على القبور فحكمها الهدم لا يجوز بقاؤها، ولا يصلى فيها، لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا، متفق على صحته.\nوقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك خرجه مسلم في الصحيح.\nفبين ﷺ أن الله لعن اليهود والنصارى بسبب اتخاذ قبور أنبيائهم مساجد، وبين صلى الله عليه وسلم أن الواجب على المسلمين أن يتجنبوا ذلك، وأن لا يتأسوا بـاليهود والنصارى في هذا الأمر، فدل ذلك على أنه لا يجوز اتخاذ المساجد على القبور، ولا يصلى فيها؛ لأن هذا يسبب ويفضي إلى الشرك بها وعبادتها من دون الله ولا حول ولا قوة إلا بالله.\nومن هذا ما رواه مسلم في الصحيح عن جابر ، عن النبي ﷺ: أنه نهى عن تجصيص القبر، وعن القعود عليه، وعن البناء عليه، فالقبور لا تجصص ولا يبنى عليها لا مساجد ولا غيرها، وما ذاك إلا لأن اتخاذها مساجد والبناء عليها من أسباب الغلو فيها، وعبادة أهلها من دون الله، بالنذر لهم، والذبح لهم ونحو ذلك.\nفلهذا نهى الرسول ﷺ عن اتخاذ المساجد على القبور، وأخبر أن الله لعن اليهود والنصارى بأسباب ذلك.\nفالواجب على المسلمين أن يحذروا هذا، وأن لا يبنوا على القبور مساجد، وأن لا يبنوا عليها شيئاً لا قبة ولا حجرة، ولا مسجد ولا تجصص؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه، صلى الله وسلم عليه وعلى آله وأصحابه.\nأما إن كان المسجد المبني قائم قبل ذلك، ثم دفن فيه ميت فهذا الميت ينبش، إذا كان المسجد موجود ولكن حدث فيه أن دفن فيه ميت أو أموات، فالواجب نبش هذه القبور وجعلها في المقابر العامة، حتى يبقى المسجد سليماً من القبور هذا هو الواجب، وبهذا يصلى فيها، إذا نبشت..... صلي فيه؛ لأنه هو القديم وهو الأصل، أما إذا كانت القبور هي الأصلية ثم حدث المسجد، فالواجب هدمه وإزالته وأن تبقى القبور كسائر القبور ضاحية ليس عليها بناء، كما كان النبي ﷺ فعل ذلك وأصحابه، في البقيع وفي غير البقيع.\nولا يخفى ما يترتب على بناء المساجد على القبور، واتخاذ القباب عليها وفرشها وتنويرها وتطييبها، لا يخفى ما يترتب على هذا من الغلو فيها وتعظيم أهلها وعبادتهم من دون الله، بالنذر لهم ودعائهم وطلب منهم المدد، وهذا شرك أكبر، دعاء الأموات والاستغاثة بالأموات والنذر لهم هذا من الشرك الأكبر عند جميع أهل العلم المعتبرين، وهو مثل دعاء الأصنام ومثل دعاء الأشجار والأحجار، ومثل دعاء الكواكب والاستغاثة بها، كله شرك بالله عز وجل، وتعظيمها ببناء المساجد عليها والقباب وسيلة إلى ذلك، وأما الطرق التي أحدثها الناس، طرق الصوفية والبهائية والقاديانية وغيرها فهي طرق منكرة محدثة يجب أن تعرض على كتاب الله وسنة الرسول ﷺ، فما وافق سنة الرسول ﷺ أو وافق كتاب الله قبل، وما خالف ذلك مما أحدثه الناس فإنه يرد ويطرح، لقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد رواه مسلم، يعني: مردود، وقال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، متفق على صحته، وكان الرسول ﷺ يقول في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه مسلم في الصحيح.\nفالواجب على أهل الإسلام أن يحذروا ما أحدثه الناس، من الطرق التي تخالف شرع الله عز وجل، سواء كانت صوفية أو غير صوفية، الواجب عرض ما أحدثه الناس من الطرق على كتاب الله، وعلى سنة رسوله ﷺ، فما وافقهما أو أحدهما قبل وما خالفهما رد على من أحدثه، قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] فأمر سبحانه برد ما تنازع فيه الناس إلى الله ورسوله معنى: إلى الله: إلى كتابه العظيم، ومعنى إلى الرسول: يعني: إليه في حياته ﷺ وإلى سنته بعد وفاته عليه الصلاة والسلام، هكذا قال أهل العلم رحمة الله عليهم، وهكذا قال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] لكن البهائية طائفة كافرة، معروف كفرها بما لديها من دعوى النبوة للبهاء، وربما ادعوا أنه الله! فهي طائفة كافرة يجب الحذر منها، ويجب على الدول الإسلامية إبعادها والقضاء عليها وعدم إقرارها في البلاد، وهكذا القاديانية طائفة كافرة؛ لأنها تثبت النبوة لـمرزا غلام أحمد القادياني وهذا كفر وضلال؛ لأن محمداً رسول الله صلى الله عليه وسلم هو خاتم الأنبياء عليه الصلاة والسلام، ليس بعده نبي، قال الله : مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40] وقد ثبت عن رسول الله ﷺ وتواتر عنه، أنه قال: أنا خاتم النبيين لا نبي بعدي فدعوى القاديانية: أن مرزا غلام أحمد أنه نبي وأنه يوحى إليه، هذا كفر مستقل وردة كبرى عند أهل العلم، فيجب الحذر منهم وعدم إقرارهم حتى يستجيبوا لله ورسوله حتى يتوبوا من هذه العقيدة، وحتى يرجعوا عن هذا الباطل والمنكر، نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/7159/حكم-بناء-المساجد-على-القبور-والتعريف-ببعض-الفرق-الضالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22302.mp3","categories":["المساجد ومواضع السجود","البدع والمحدثات"]},{"id":9137,"question":"يسأل أخونا أيضًا ويقول: ما رأيكم في الاحتفال بالمولد النبوي الشريف، ولقد تكرر في قول الناس: إن بعض العلماء أجازوه ويقومون به، أفيدونا عن هذا جزاكم الله خيرًا؟","title":"الاحتفال بالمولد النبوي بدعة وليس له أصل","answer":"ولا عبرة بمن يفعله اليوم وكثرتهم؛ لأنهم توارثوا هذا عن أسلافهم، والقاعدة التي درج عليها العامة والكفرة قبل النبي ﷺ إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]، فليس في اتباع الآباء حجة إذا كان عملهم ليس على أساس متين ليس على دليل، كما أن أعمال الكفار ليست حجة، ولهذا أنكر الله عليهم ذلك وأمرهم باتباع النبي ﷺ، ولم يجعل لهم عذرًا في اتباع أسلافهم بل عابهم على ذلك، فأنت أيها المؤمن كذلك، ليس لك أن تتبع أباك ولا جدك ولا أهل بلدك إلا فيما شرعه الله، أما ما نهى الله عنه فليس لك أن تتبعهم ولو كثروا، فلو أن أهل بلدك صاروا يشربون الخمر فليس لك أن تفعله معهم ولو كانوا يزنون كذلك، ولو كانوا يعقون والديهم فليس لك أن تفعل مثلهم، فهكذا إذا فعلوا البدع فليس لك أن تتبعهم بل تدعو لهم بالهداية، تنصحهم توجههم إلى الخير، ولا تفعل معهم ما حرم الله من البدعة، كما أنك لا يسوغ لك أن تفعل معهم الزنا أو الخمر أو العقوق أو الربا أو ما أشبه ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7295/الاحتفال-بالمولد-النبوي-بدعة-وليس-له-اصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17914.mp3","categories":["البدع والمحدثات"]},{"id":9242,"question":"أخيراً يسأل الإخوة أحمد عبدالعزيز وزملائه الذين يعملون بالأردن يقولون: يوجد بقريتنا بمصر ضريح لأحد الأولياء، والناس يأتون إليه ويقدمون إليه النذور والذبائح ويطوفون بالقبر ويتمسحون به ابتغاء البركة، ويقيمون عنده حلقات الذكر، وكل ذلك مع اختلاط النساء بالرجال، ومع ندائهم لصاحب القبر والاستغاثة به، وطلب العون منه، فما الحكم في هؤلاء الناس وفي أفعالهم هذه؟ وما الحكم في المولد لهذا الشيخ ولغيره، أفيدونا أفادكم الله؟","title":"حكم تقديم النذور والذبائح للأولياء ودعائهم والاحتفال بموالدهم","answer":"الجواب: الذي يأتي إلى ضرائح الموتى ويدعوهم، ويسألهم شفاء المرضى أو يطلبهم المدد والعون أو دخول الجنة أو النجاة من النار، أو ينذر لهم أو يذبح لهم أو يطوف بقبورهم يطلب البركة منهم والأجر منهم أو النجاة من النار، أو شفاء المرض، أو سعة الرزق، أو ما أشبه ذلك كله كفر أكبر وشرك أكبر نعوذ بالله، هذا دين المشركين، قال الله جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، قال سبحانه في حق الأصنام والمعبودين من دون الله جميعاً: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] ، سماه: شركاً، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعوة غير الله: كفراً وضلالاً وشركاً.\nوهكذا إقامة الأذكار أو الموالد عند القبر بدعة، فإقامة الحفل عند القبر، بالمولد أو الأذكار أو الحلقات العلمية أو القرآن هذا بدعة، وليس بشرك، أما طلب الحاجات منه، والتمسح بتراب القبر لطلب البركة، أو لطلب شفاء المريض هذا من الكفر الأكبر نسأل الله العافية، ولا حول ولا قوة إلا بالله.\nأما الموالد فكلها بدعة، الاحتفال بالموالد كلها بدعة عند المحققين من أهل العلم؛ لأن الله سبحانه ما شرع لنا ذلك، والرسول ﷺ لم يحتفل بمولده، وهكذا الصحابة رضي الله عنهم لم يحتفلوا بمولد النبي ﷺ، ولا بمولد الصديق ، ولا بمولد عمر ، ولا عثمان ولا علي وهم القدوة، وهم الأخيار فلو كان هذا خيراً لسبقونا إليه.\nفالاحتفال بمولد النبي ﷺ أو المشايخ أو الأمراء أو غيرهم كله بدعة وكله لا يجوز؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ، ولقوله عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود، ولقوله: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nوكان يقول في الخطبة عليه الصلاة والسلام، في خطبة الجمعة، يقول عليه الصلاة والسلام: إن خير الحديث كتاب الله، وخير الهدي هدي محمدٍ صلى الله عليه وسلم ، وشر الأمور محدثاتها، وكل بدعة ضلالة ، فالواجب على أهل الإسلام أن يحذروا هذه البدع، وأن يبتعدوا عنها، وإذا كان فيها اختلاط بين الرجال والنساء صار الأمر أكبر، صارت الفتنة أعظم، صار الإثم أكثر، فإن الاختلاط بين الرجال والنساء عند القبر، أو في أي احتفال منكر، ومن أسباب الزنا والفواحش، ومن أسباب ركوب المحارم، فالواجب الحذر من ذلك حتى في غير الاحتفال، حتى في الولائم الأخرى، لا يجوز أن يجتمع الرجال والنساء في حفلة، ويختلطوا في حفلة عرس، أو في حفلة أي حفلة؛ لأن هذا يسبب فتنة للرجال، من الرجال بالنساء، والنساء بالرجال، الواجب التمييز وأن يكون اجتماع النساء على حدة، واجتماع الرجال على حدة في الولائم، وفي الاحتفالات الجائزة شرعاً من الأعراس وغيرها. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.\nالشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/7406/حكم-تقديم-النذور-والذباىح-للاولياء-ودعاىهم-والاحتفال-بموالدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23505.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9253,"question":"أخيراً يسأل الإخوة أحمد عبدالعزيز وزملائه الذين يعملون بالأردن يقولون: يوجد بقريتنا بمصر ضريح لأحد الأولياء، والناس يأتون إليه ويقدمون إليه النذور والذبائح ويطوفون بالقبر ويتمسحون به ابتغاء البركة، ويقيمون عنده حلقات الذكر، وكل ذلك مع اختلاط النساء بالرجال، ومع ندائهم لصاحب القبر والاستغاثة به، وطلب العون منه، فما الحكم في هؤلاء الناس وفي أفعالهم هذه؟ وما الحكم في المولد لهذا الشيخ ولغيره، أفيدونا أفادكم الله؟","title":"حكم تقديم النذور والذبائح للأولياء ودعائهم والاحتفال بموالدهم","answer":"الجواب: الذي يأتي إلى ضرائح الموتى ويدعوهم، ويسألهم شفاء المرضى أو يطلبهم المدد والعون أو دخول الجنة أو النجاة من النار، أو ينذر لهم أو يذبح لهم أو يطوف بقبورهم يطلب البركة منهم والأجر منهم أو النجاة من النار، أو شفاء المرض، أو سعة الرزق، أو ما أشبه ذلك كله كفر أكبر وشرك أكبر نعوذ بالله، هذا دين المشركين، قال الله جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، قال سبحانه في حق الأصنام والمعبودين من دون الله جميعاً: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] ، سماه: شركاً، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعوة غير الله: كفراً وضلالاً وشركاً.\nوهكذا إقامة الأذكار أو الموالد عند القبر بدعة، فإقامة الحفل عند القبر، بالمولد أو الأذكار أو الحلقات العلمية أو القرآن هذا بدعة، وليس بشرك، أما طلب الحاجات منه، والتمسح بتراب القبر لطلب البركة، أو لطلب شفاء المريض هذا من الكفر الأكبر نسأل الله العافية، ولا حول ولا قوة إلا بالله.\nأما الموالد فكلها بدعة، الاحتفال بالموالد كلها بدعة عند المحققين من أهل العلم؛ لأن الله سبحانه ما شرع لنا ذلك، والرسول ﷺ لم يحتفل بمولده، وهكذا الصحابة رضي الله عنهم لم يحتفلوا بمولد النبي ﷺ، ولا بمولد الصديق ، ولا بمولد عمر ، ولا عثمان ولا علي وهم القدوة، وهم الأخيار فلو كان هذا خيراً لسبقونا إليه.\nفالاحتفال بمولد النبي ﷺ أو المشايخ أو الأمراء أو غيرهم كله بدعة وكله لا يجوز؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ، ولقوله عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود، ولقوله: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nوكان يقول في الخطبة عليه الصلاة والسلام، في خطبة الجمعة، يقول عليه الصلاة والسلام: إن خير الحديث كتاب الله، وخير الهدي هدي محمدٍ صلى الله عليه وسلم ، وشر الأمور محدثاتها، وكل بدعة ضلالة ، فالواجب على أهل الإسلام أن يحذروا هذه البدع، وأن يبتعدوا عنها، وإذا كان فيها اختلاط بين الرجال والنساء صار الأمر أكبر، صارت الفتنة أعظم، صار الإثم أكثر، فإن الاختلاط بين الرجال والنساء عند القبر، أو في أي احتفال منكر، ومن أسباب الزنا والفواحش، ومن أسباب ركوب المحارم، فالواجب الحذر من ذلك حتى في غير الاحتفال، حتى في الولائم الأخرى، لا يجوز أن يجتمع الرجال والنساء في حفلة، ويختلطوا في حفلة عرس، أو في حفلة أي حفلة؛ لأن هذا يسبب فتنة للرجال، من الرجال بالنساء، والنساء بالرجال، الواجب التمييز وأن يكون اجتماع النساء على حدة، واجتماع الرجال على حدة في الولائم، وفي الاحتفالات الجائزة شرعاً من الأعراس وغيرها. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.\nالشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/7406/حكم-تقديم-النذور-والذباىح-للاولياء-ودعاىهم-والاحتفال-بموالدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23505.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9267,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع عبدالله إدريس حماد سوداني مقيم بالرياض وأخونا له مجموعة من الأسئلة في سؤاله الأول يقول: هل يجوز للجماعة إذا صلوا جماعة أن يختاروا أحدهم بأن يدعو لهم ويرفعون أيديهم ويقولون: اللهم آمين، يعني: هو يدعو بالنيابة عنهم ويرددون كلمة: اللهم آمين؟","title":"حكم دعاء الإمام بعد الصلاة وتأمين المأمومين على ذلك","answer":"الجواب: هذا فيه تفصيل، إن كان الدعاء في قنوت الوتر فلا بأس بهذا، أما الدعاء غير ذلك فليس بمشروع، الكل يدعو لنفسه، إذا سلم من صلاته وأتى بالجلوس الشرعي يدعو بينه وبين ربه كل واحد يدعو لنفسه، والإمام لا يرفع ويؤمنوا لا هذا بدعة ليس له أصل، ولكن إذا أحب أن يدعو فالإمام يدعو لنفسه بينه وبين ربه والمأموم كذلك كل واحد يدعو لنفسه هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/7430/حكم-دعاء-الامام-بعد-الصلاة-وتامين-المامومين-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15405.mp3","categories":["البدع والمحدثات"]},{"id":9277,"question":"عندنا في قريتنا بجمهورية مصر العربية عندما تتوفى زوجة الرجل ويتزوج غيرها يذهبون إلى قبرها ليلة زواجه بالزوجة الجديدة ويضعون عليه ماء، فهل هذا من السنة أم بدعة؟","title":"حكم ذهاب الزوج إلى قبر زوجته عند زواجه بالثانية","answer":"الجواب: لا أصل لهذا بدعة، لا أصل لهذا. نعم.","link":"https://binbaz.org.sa/fatwas/7440/حكم-ذهاب-الزوج-الى-قبر-زوجته-عند-زواجه-بالثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15410.mp3","categories":["البدع والمحدثات"]},{"id":9321,"question":"بالنسبة لليلة السابع والعشرين من رجب من كل عام وليلة النصف من شعبان، تعود المسلمون الاحتفال بهما وعمل الأكلات الدسمة وما أشبه ذلك؛ فما رأيكم في هذا؟","title":"حكم الاحتفال بليلة السابع والعشرين من رجب والنصف من شعبان","answer":"الجواب: هاتان بدعتان، الاحتفال بالنصف من شعبان والاحتفال بليلة السابع والعشرين من رجب، كلتاهما بدعة، ليس عليهما دليل، ولم يثبت عنه ﷺ أن ليلة السابع والعشرين من رجب هي ليلة الإسراء والمعراج، وما جاء فيها من بعض الأحاديث فهو غير صحيح عند أهل العلم، ولو ثبت أنها ليلة المعراج لم يجز الاحتفال بها حتى لو ثبتت؛ لأن الرسول ﷺ لم يحتفل بها ولا أصحابه وهم القدوة، والله يقول: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] يعني: في الفعل وفي الترك، فلما ترك نترك، وإذا فعل فعلنا عليه الصلاة السلام، فالاحتفال بليلة النصف من شعبان أو بليلة سبعة وعشرين من رجب لأنها ليلة الإسراء والمعراج، أو بالمولد النبوي في اثنا عشر ربيع الأول، أو بالموالد الأخرى للبدوي أو للحسين أو لـعبد القادر الجيلاني أو لفلان أو فلان كله لا يجوز، وكونه تشبه بـالنصارى واليهود في أعيادهم، وقد نهى الرسول ﷺ عن التشبه بهم، وقال: من تشبه بقوم فهو منهم، فلا يليق بالمسلمين أن يتشبهوا بأعداء الله في هذه الأمور ولا في غيرها.\nولو كان الاحتفال بليلة النصف من شعبان أمرًا مشروعًا؛ لبادر إليه سيد ولد آدم ، وأفضل خلق الله، وخاتم رسل الله عليه الصلاة والسلام، ولشرعه لأمته وعلمهم إياه؛ لأنه أنصح الناس، وهو الناصح الأمين عليه الصلاة والسلام، ما ترك من خير إلا دل عليه، وما ترك من شر إلا نبه عليه وحذر منه كما ثبت في الصحيح عن عبد الله بن عمرو رضي الله عنهما عن النبي ﷺ أنه قال: ما بعث الله من نبي إلا كان حقًا عليه أن يدل أمته على خير ما يعلمه لهم، وينذرهم شر ما يعلمه لهم ونبينا أكملهم وأفضلهم وخاتمهم ليس بعده نبي، فهو أولى بهذا الوصف، فما ترك من خير إلا دلنا عليه، وما ترك من شر إلا حذرنا منه.\nفلو كان الاحتفال بليلة النصف من شعبان أو بالمولد النبوي أو بليلة سبعة وعشرين من رجب أمرًا مشروعًا لبادر إليه عليه الصلاة والسلام قولًا وفعلًا، ولعلمه أمته عليه الصلاة والسلام، ولو فعل لنقله الصحابة فإنهم الأمناء، وهم خير الناس بعد الأنبياء وأفضل الناس بعد الأنبياء، وهم الذين نقلوا لنا القرآن، ونقلوا لنا السنة الصحيحة عنه عليه الصلاة والسلام، فهم الأئمة والقدوة بعد رسول الله عليه الصلاة والسلام، فلا يجوز أن نخالفهم ونحدث شيئًا لم يفعلوه من القربات والطاعات.\nثم التابعون لهم بإحسان لم يفعلوا ذلك، لو كان الصحابة فعلوه لفعله التابعون، ثم أتباع التابعين، فلما لم يفعلوا ذلك، ومضت القرون الثلاثة المفضلة لم يقع فيها احتفال بمولد، ولا بليلة النصف من شعبان، ولا بليلة السابع والعشرين من رجب علم أن ذلك من البدع التي أحدثها الناس، ثم لو أحدث بعض الناس شيئًا من البدع في القرن الثاني أو الثالث لم يكن حجة؛ لأن الحجة فيما فعله الرسول ﷺ، لكن هذه البدعة -بدعة المولد- لم تفعل لا في عهد النبي ﷺ، ولا في عهد القرن الأول، ولا في عهد القرن الثاني ولا الثالث، إنما جاءت في القرن الرابع.\nوهكذا القول في جميع البدع، الواجب تركها والحذر منها ومن جملتها ما تقدم بدعة ليلة المعراج ليلة سبع وعشرين ... بدعة الاحتفال بها، كذلك بدعة الاحتفال بليلة النصف من شعبان، كذلك بدعة يقول لها: بدعة صلاة الرغائب يسمونها صلاة الرغائب، يفعلوها بعض الناس في أول جمعة من رجب أول ليلة جمعة من رجب، وهي بدعة أيضًا، والبدع كثيرة عند الناس، نسأل الله أن يعافي المسلمين منها، وأن يمنحهم الفقه في الدين، وأن يوفقهم للتمسك بالسنة والاكتفاء بها والحذر من البدعة.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7477/حكم-الاحتفال-بليلة-السابع-والعشرين-من-رجب-والنصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18412.mp3","categories":["البدع والمحدثات"]},{"id":9369,"question":"أخ مصري يسأل ويقول: يوجد في بلدتنا رجل متوفى صالح ويبنى له مقام على قبره، وله عادة عندنا في كل عام نذهب مع الناس إليه رجالاً ونساء ويقيمون عنده ثلاثة أيام بالمدح والتهاليل والأذكار، ويستمر في الأوصاف المعروفة سماحة الشيخ ويرجو التوجيه والإرشاد جزاكم الله خيراً؟","title":"حكم زيارة القبور والمكوث فيها للأكل والشرب وقراءة الأذكار","answer":"الجواب: هذا العمل لا يجوز بل هو من البدع التي أحدثها الناس، فلا يجوز أن يقام على قبره بناء سواء سمي مقاماً أو سمي قبة أو سمي غير ذلك، كانت القبور في عهد النبي ﷺ وعهد الصحابة مكشوفة ليس عليها بناء، والنبي ﷺ نهى أن يبنى على القبر وأن يجصص وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، وقال جابر بن عبد الله الأنصاري : نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه فالبناء على القبور منكر وهكذا تجصيصها ووضع الزينات عليها أو الستور كله منكر ووسيلة إلى الشرك، فلا يجوز وضع القباب أو الستور أو المساجد عليها.\nوهكذا زيارتها على الوجه الذي ذكره السائل من الجلوس عندها والتهاليل وأكل الطعام والتمسح بالقبر أو الدعاء عند القبر أو الصلاة عند القبر كل هذا منكر، كله بدعة لا يجوز، إنما المشروع زيارة القبور كونه يزورها ويدعو لهم ثم ينصرف، يمر على القبور ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين. وما أشبه من الدعوات فقط، هذا هو المشروع الذي علمه النبي أصحابه عليه الصلاة والسلام كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وحديث عائشة: يرحم الله المستقدمين منا والمستأخرين، وحديث ابن عباس: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر، هذا المشروع.\nوأما الإقامة عند القبر للأكل والشرب أو للتهاليل أو للصلاة أو لقراءة القرآن كل هذا منكر، يسلم ويذهب، ويدعو للميت ويترحم عليه، أما اتخاذه محل دعاء أو محل قراءة أو محل طواف أو محل تهاليل والجلوس عنده، أو أكل يوم أو يومين أو ثلاثة هذا ماله أصل، هذا بدعة ومن وسائل الشرك فيجب الحذر من ذلك ويجب ترك ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7533/حكم-زيارة-القبور-والمكوث-فيها-للاكل-والشرب-وقراءة-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15608.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":9420,"question":"المستمع علي محمد عبدالرحمن من جدة بعث برسالة وضمنها ثلاثة أسئلة، في سؤاله الأول يقول: هل يكره الدعاء بعد كل صلاة ورفع الأيدي هل هو بدعة؟","title":"حكم الدعاء ورفع الأيدي بعد الصلوات المكتوبة","answer":"الجواب: الدعاء بعد الصلاة لا يكره بل مستحب، كونه يدعو بينه وبين ربه في آخر الصلاة وبعد الصلاة بعد الذكر، كل هذا جاء في الأحاديث عن النبي عليه الصلاة والسلام، فإذا دعا في آخر الصلاة قبل أن يسلم فهذا أفضل، وإن دعا بعد السلام وبعد الذكر فلا بأس بينه وبين ربه.\nأما أن يكون الدعاء جماعيًا من الجماعة أو مع الإمام هذا غير مشروع بل بدعة، أو يكون مع رفع الأيدي هذا بدعة بعد الفرائض، لم يحفظ عنه ﷺ أنه كان يرفع يديه بعد الفرائض الخمس، ولم يحفظ عن أصحابه  فيما بلغنا؛ فليس للناس أن يحدثوا شيئًا لم يفعله المصطفى عليه الصلاة والسلام ولا أصحابه، لكن الدعاء لا بأس به، الدعاء بين الإنسان وبين ربه قبل السلام وبعد السلام لا بأس.\nأما رفع الأيدي من الجماعة أو من الإمام أو من الجميع للدعاء كل هذا بدعة، وهكذا إذا دعوا جميعًا دعاءً جماعيًا أو ذكرًا جماعيًا بدعة، كل يدعو الله في نفسه ويدعو لنفسه من دون لحاجة أن يكون معه آخر يرفع الصوت معه، نسأل الله للجميع الهداية نعم.","link":"https://binbaz.org.sa/fatwas/7585/حكم-الدعاء-ورفع-الايدي-بعد-الصلوات-المكتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19006.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":9424,"question":"هذه رسالة وردت من (س. ع. م) من السودان، والأخ في مقدمة رسالته قدم لنا بعض المعلومات المفيدة، حيث يقول:أولاً: أود أن أذكر لكم معاني بعض الكلمات شائعة الاستخدام في رسائل الإخوة السودانيين حيث يقول: هناك كلمة: النوبة ويقصد نوع من الطبول يستخدمها الصوفية في الذكر والموالد، كلمة: السعوط أو التنباك يقصد بها: الشمة، وهي نوع من أنواع التبغ شائع الاستعمال في السودان ويوضع في الفم، هذه بعض ملاحظات قدمها للإخوة لا أدري لسماحتكم عليها تعليق؟","title":"الصوفية وتعبدهم بأدوات الملاهي كالطبول وغيرها","answer":"الجواب: نعم، نعم، ما يفعله بعض الصوفية من التعبد بالملاهي كالطبول والأغاني وأشياء تدعوهم إلى أن يقع بعضهم مغشياً عليه، كل هذا لا أصل له، ولم يفعله رسول الله ﷺ، ولا أصحابه رضي الله عنهم وأرضاهم. فالواجب على كل مسلم أن يترك ذلك وأن لا يتعبد بما حرم الله عليه، فإن الأغاني وضرب الطبول والتجمع على هذا الأمر أمر منكر، فينبغي لكل مسلم أن يحذر ذلك وأن يذكر الله فيما بينه وبين نفسه في المسجد، في البيت، في أي مكان، وهكذا قراءة القرآن، في بيته في المسجد يتعبد الله بهذا الخير العظيم.\nأما أن يكون لهذا حلقات خاصة وأذكار خاصة، وطبول وأغاني وأشباه ذلك مما يتخذه بعض الصوفية شعاراً لتعبدهم فهذا شيء لا أصل له، ولكن نصيحتي لهم ولكل مسلم أن يتعبدوا بالأذكار الشرعية وبقراءة القرآن كما فعل الرسول ﷺ وكما فعل أصحابه رضي الله عنهم، يقرأ القرآن في بيته، في المسجد مع إخوانه المسلمين، يذكر الله في بيته في الطريق في المسجد كما يفعل إخوانه المسلمون، أما اتخاذ هذه الأشعار أو هذه الأغاني أو الطبول، أو عادات خاصة يتحلقون لها ويفعلونها بمزامير أو بطبول أو دفوف أو غير هذا، كله منكر وكله بدعة ينبغي الحذر منه.\nوقد نبه على هذا جماعة من أهل العلم، منهم العلامة ابن القيم رحمه الله، وآخرون من أهل العلم نبهوا على هذا وبينوا أنه خطأ وأنه غلط، ينبغي تركه. نعم.\nأما ما يتعلق بالتنباك فالتنباك محرم، سواء كان اتخذ شمة، أو سعوطاً، أو على غير ذلك؛ لما فيه من الضرر العظيم، التدخين منكر ومحرم لأضراره الكثيرة وخبثه، والله جل وعلا إنما أباح لنا الطيبات، وليس الدخان وليس القات وليست المسكرات من الطيبات بل هي من الخبائث المحرمة. فالواجب على المؤمن أن يبتعد عن هذه الأشياء التي تضره وتضر دينه وتضر سمعته، والله سبحانه يقول: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ [المائدة:4] قال : قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فبين سبحانه أنه أحل لعباده الطيبات، وليس الدخان سعوطاً أو غيره من الطيبات، بل هو من الخبائث المحرمة، وهكذا جميع المسكرات من الخمور والحشيش والقات وغير هذا، وإن نازع بعض الناس في كون القات يسكر لكنه خبيث مضر، فينبغي للمؤمن ترك ذلك كله، والبعد عن كل ما حرم الله وعن كل مشتبه، فقد قال النبي ﷺ: من اتقى الشبهات فقد استبرأ لدينه وعرضه وقال عليه الصلاة والسلام: دع ما يريبك إلى ما لا يريبكك فالمؤمن هكذا يتباعد عما حرم الله ويتباعد عن المشتبهات؛ لئلا تجره إلى المحرمات، رزق الله الجميع العافية والتوفيق والهداية. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7589/الصوفية-وتعبدهم-بادوات-الملاهي-كالطبول-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25503.mp3","categories":["البدع والمحدثات"]},{"id":9445,"question":"وردت إلى البرنامج رسالة من جماعة المسلمين بمسجد عمر الفاروق في هولندا، تحمل السؤال التالي: ما هو رأي الدين في تلاوة القرآن بصورة جماعية بعد صلاة الصبح والمغرب، حيث أن بعض الإخوة قالوا لنا بأنها بدعة، أفيدونا أفادكم الله؟","title":"حكم تلاوة القرآن بصورة جماعية","answer":"الجواب: تلاوة القرآن الكريم من العبادات التي شرعها الله لعباده وبيَّنها رسوله ﷺ، وكان رسول الله ﷺ يقرأ القرآن وأصحابه يستمعون؛ ليستفيدوا مما يقول لهم ويفسره لهم عليه الصلاة والسلام، وربما أمر بعض أصحابه أن يقرأ القرآن وهو يستمع عليه الصلاة والسلام، ولم يكن من سنته ولا من سنة أصحابه وطريقتهم أن يتلوا القرآن جميعًا بصوت واحد ليس هذا من سنتهم، وليس هذا من فعله عليه الصلاة والسلام.\nفالذين قالوا: إنه بدعة، هم مصيبون؛ لأن هذا لا أصل له.\nلكن ذكر العلماء أن هذا مع الصبيان الصغار والمتعلمين على طريق التعليم حتى يستقيم لسانهم جميعًا، يعفى عنه في طريق التعليم ..... مع الصبيان من يتعلمون في المدارس إذا رأى الأستاذ يتكلمون جميعًا حتى يعتدل الصوت وحتى تستقيم التلاوة من الصبيان الصغار في باب التعلم فهذا نرجو أن لا حرج فيه؛ لما فيه من العناية بالتعليم والحرص على استقامة الأصوات وحسن الأداء.\nأما فيما بين الناس في التلاوة في المساجد أو في غير المساجد، في الصباح أو في المساء أو في أي مكان يتلون القرآن جميعًا فهذا لا نعلم له أصلًا، وقد قال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد فنصيحتي أن لا يفعل ذلك.","link":"https://binbaz.org.sa/fatwas/7607/حكم-تلاوة-القران-بصورة-جماعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19103.mp3","categories":["البدع والمحدثات"]},{"id":9492,"question":"وهذه رسالة وردت إلينا من المرسل (ر. ح. ع) مصري الجنسية مقيم في الخبر، يقول في رسالته أيضاً: يوجد عندنا في مدينة مقبرة داخل مسجد، تسمى هذه المقبرة ضريح السيد البدوي ، ويوجد بنفس المقبرة حجر منقوش عليه خمسة أصابع، والكل يعرف بأن هذه أصابع رسول الله ﷺ، ويوجد في مدينة أخرى حجر منقوش عليه أصابع لقدم، فهل هذه حقيقة أم خرافات، علماً أنني كنت أقبل وأتمسح بهذا الحجر كما كان يفعل الناس عندنا، والحمد لله تبت إلى الله من هذا، وأرجو الله أن يقبل توبتي، لكن أريد أن أعرف هل هذا حقيقة أصابع يد الرسول أو قدمه، أفيدونا أفادكم الله؟","title":"ما صحة وجود آثار أصابع رسول الله في حجر في مصر","answer":"الجواب: كل هذا لا أصل له، ليست أصابع النبي ﷺ وليست أصابع قدمه، كل هذا باطل، فالرسول ﷺ لم يأت إلى مصر ولم يزرها، ولم توجد أصابعه في أي حجر حتى نقلت إلى هناك، كل هذا من الباطل والكذب فلا يجوز التمسح بها ولا التبرك بها بل تجب إزالتها.\nوهكذا المساجد لا تبنى على القبور، لا يجوز أن يبنى مسجد على القبر، ولا يجوز الطواف بالقبور ولا دعاء أهلها من دون الله، ولا التمسح بقبورهم ولا الطواف بها، ولا النذر لأهلها كما يفعل عند البدوي أو غيره، كل هذا منكر عظيم، فبناء المساجد على القبور أنكره النبي ﷺ وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ولما ذكر له بعض الصحابيات في الحبشة كنيسة رأينها في أرض الحبشة وفيها ما فيها من الصور، قال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً، وصوروا فيه تلك الصور، ثم قال: أولئك شرار الخلق عند الله فأخبر أن هؤلاء الذين يبنون المساجد على القبور ويتخذون عليها الصور هم شرار الخلق؛ لأنهم دعاة للنار نعوذ بالله، دعاة للشرك، فيجب الحذر من هذه البلايا وهذه البدع وهذه الشرور التي أحدثها الجهلة، ويجب أن تكون المساجد بعيدة عن القبور تكون مستقلة عن القبور، والقبور مستقلة عن المساجد، أما أن يتخذ المسجد على القبر، أو يدفن في المسجد كل هذا منكر، لا يجوز الدفن في المساجد، تكون المقابر مستقلة والمساجد مستقلة، ولا يبنى المسجد على القبر ولو كان من قبور الأنبياء لا يبنى عليه مسجد.\nأما قبر النبي ﷺ الذي في المدينة، فهذا دفن في بيته ﷺ ما دفن في المسجد، هو وصاحباه أبو بكر وعمر ، كان مدفوناً في البيت في بيت عائشة رضي الله عنها ثم دفن معه أبو بكر ثم دفن معه عمر ، لكن لما وسع المسجد الوليد بن عبد الملك في آخر المائة الأولى أدخل الحجرة في المسجد اجتهاداً منه، وقد غلط، لو تركها على حالها لكان أسلم وأبعد عن الشبهة فإن الناس اغتروا بهذا وظنوا أن اتخاذ المساجد على القبور أمر مطلوب وهذا غلط، فالرسول ﷺ في بيته ما هو في المسجد، دفن في بيته بيت عائشة ، وهكذا صاحباه دفنا معه في البيت ثم أدخلت الحجرة برمتها في المسجد.\nفلا يجوز لعاقل أن يغتر بهذا، فالرسول ﷺ حذر من هذا عليه الصلاة والسلام وأبدى وأعاد في ذلك، فيجب الحذر مما نهى عنه النبي ﷺ، وألا يدفن إنسان في المسجد، وألا يقام مسجد على قبر؛ لأن الرسول ﷺ لعن من فعل ذلك فيجب الحذر، ولأنه وسيلة للشرك. نعم. نسأل الله العافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7660/ما-صحة-وجود-اثار-اصابع-رسول-الله-في-حجر-في-مصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24203.mp3","categories":["البدع والمحدثات"]},{"id":9499,"question":"وهذه رسالة وردت إلينا من المرسل (ر. ح. ع) مصري الجنسية مقيم في الخبر، يقول في رسالته أيضاً: يوجد عندنا في مدينة مقبرة داخل مسجد، تسمى هذه المقبرة ضريح السيد البدوي ، ويوجد بنفس المقبرة حجر منقوش عليه خمسة أصابع، والكل يعرف بأن هذه أصابع رسول الله ﷺ، ويوجد في مدينة أخرى حجر منقوش عليه أصابع لقدم، فهل هذه حقيقة أم خرافات، علماً أنني كنت أقبل وأتمسح بهذا الحجر كما كان يفعل الناس عندنا، والحمد لله تبت إلى الله من هذا، وأرجو الله أن يقبل توبتي، لكن أريد أن أعرف هل هذا حقيقة أصابع يد الرسول أو قدمه، أفيدونا أفادكم الله؟","title":"ما صحة وجود آثار أصابع رسول الله في حجر في مصر","answer":"الجواب: كل هذا لا أصل له، ليست أصابع النبي ﷺ وليست أصابع قدمه، كل هذا باطل، فالرسول ﷺ لم يأت إلى مصر ولم يزرها، ولم توجد أصابعه في أي حجر حتى نقلت إلى هناك، كل هذا من الباطل والكذب فلا يجوز التمسح بها ولا التبرك بها بل تجب إزالتها.\nوهكذا المساجد لا تبنى على القبور، لا يجوز أن يبنى مسجد على القبر، ولا يجوز الطواف بالقبور ولا دعاء أهلها من دون الله، ولا التمسح بقبورهم ولا الطواف بها، ولا النذر لأهلها كما يفعل عند البدوي أو غيره، كل هذا منكر عظيم، فبناء المساجد على القبور أنكره النبي ﷺ وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ولما ذكر له بعض الصحابيات في الحبشة كنيسة رأينها في أرض الحبشة وفيها ما فيها من الصور، قال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً، وصوروا فيه تلك الصور، ثم قال: أولئك شرار الخلق عند الله فأخبر أن هؤلاء الذين يبنون المساجد على القبور ويتخذون عليها الصور هم شرار الخلق؛ لأنهم دعاة للنار نعوذ بالله، دعاة للشرك، فيجب الحذر من هذه البلايا وهذه البدع وهذه الشرور التي أحدثها الجهلة، ويجب أن تكون المساجد بعيدة عن القبور تكون مستقلة عن القبور، والقبور مستقلة عن المساجد، أما أن يتخذ المسجد على القبر، أو يدفن في المسجد كل هذا منكر، لا يجوز الدفن في المساجد، تكون المقابر مستقلة والمساجد مستقلة، ولا يبنى المسجد على القبر ولو كان من قبور الأنبياء لا يبنى عليه مسجد.\nأما قبر النبي ﷺ الذي في المدينة، فهذا دفن في بيته ﷺ ما دفن في المسجد، هو وصاحباه أبو بكر وعمر ، كان مدفوناً في البيت في بيت عائشة رضي الله عنها ثم دفن معه أبو بكر ثم دفن معه عمر ، لكن لما وسع المسجد الوليد بن عبد الملك في آخر المائة الأولى أدخل الحجرة في المسجد اجتهاداً منه، وقد غلط، لو تركها على حالها لكان أسلم وأبعد عن الشبهة فإن الناس اغتروا بهذا وظنوا أن اتخاذ المساجد على القبور أمر مطلوب وهذا غلط، فالرسول ﷺ في بيته ما هو في المسجد، دفن في بيته بيت عائشة ، وهكذا صاحباه دفنا معه في البيت ثم أدخلت الحجرة برمتها في المسجد.\nفلا يجوز لعاقل أن يغتر بهذا، فالرسول ﷺ حذر من هذا عليه الصلاة والسلام وأبدى وأعاد في ذلك، فيجب الحذر مما نهى عنه النبي ﷺ، وألا يدفن إنسان في المسجد، وألا يقام مسجد على قبر؛ لأن الرسول ﷺ لعن من فعل ذلك فيجب الحذر، ولأنه وسيلة للشرك. نعم. نسأل الله العافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7660/ما-صحة-وجود-اثار-اصابع-رسول-الله-في-حجر-في-مصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24203.mp3","categories":["البدع والمحدثات"]},{"id":9507,"question":"يقول أيضاً: ماذا عن الجهر بعد الأذان بالصلاة والسلام على رسول الله ﷺ بصوت كصوت الأذان، وإتباعه بقول المؤذن: يا أول خلق الله، وخاتم رسل الله، فهل يجوز رفع الصوت بهذا كما يرفع الصوت بالأذان، وهل الرسول ﷺ أول خلق الله؟","title":"حكم الجهر بالصلاة على النبي بعد الأذان وما يُقال معها","answer":"الجواب: وهذا أيضاً بدعة ومنكر، رفع الصوت بالصلاة على النبي صلى الله عليه وسلم مع الأذان منكر لا أصل له، ولم يفعله النبي ﷺ، ولا مؤذنوه، ولا الخلفاء الراشدون، ولا غيرهم من أهل العلم والإيمان، بل هذا مما ابتدعه الناس، وإنما السنة أن يصلي على النبي ﷺ بعد الأذان صلاة عادية بينه وبين نفسه يسمعها من حوله لا بأس، أما مع الأذان فلا، النبي ﷺ قال: إذا سمعتم المؤذن فقولوا مثلما يقول، ثم صلوا علي، فإن من صلى علي واحدة صلى الله عليه بها عشراً الحديث.\nفالسنة للمسلمين إذا سمعوا الأذان أن يجيبوا المؤذن، فإذا فرغوا من قول: (لا إله إلا الله) يصلون عليه عليه الصلاة والسلام، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته، إنك لا تخلف الميعاد.\nأما أن يرفع الصوت بالصلاة على النبي ﷺ، أو بقراءة، أو بأي كلام مع الأذان فهذا بدعة، نهاية الأذان لا إله إلا الله، .... يغلق المكبر إن كان في مكبر، ثم يسكت المؤذن إن كان في غير مكبر، ثم يصلي على النبي ﷺصلاة عادية سراً بينه وبين نفسه، ولا مانع أن يسمعها من حوله.\nكذلك قوله: يا أول خلق الله، هذا لا أصل له، ليس الرسول أول خلق الله، بل قبله أمم، وأما حديث: (أنه أول خلق الله)، ما يروى (أنه أول خلق الله) فهو لا أصل له موضوع مكذوب على النبي صلى الله عليه وسلم، وهكذا قول بعضهم: إنه نور الله كذب، هو نور من النور الذي خلقه الله، جعله الله نوراً لتعليمه الناس وهدايته الناس وإرشاده الناس، لكن ليس من نور الله، وبعضهم يقول: يا نور عرش الله، كله باطل، ليس من نور الله، ولا من نور العرش، ولكن الله أعطاه نوراً بالوحي الذي جاءه، كما قال سبحانه: قَدْ جَاءَكُمْ مِنَ اللَّهِ نُورٌ وَكِتَابٌ مُبِينٌ [المائدة:15] وسماه جل وعلا سراجاً منيراً، فهو سراج منير وهو نور بما أعطاه الله من الوحي من القرآن والسنة، وليس من نور الله الذي هو وصفه سبحانه وتعالى، وليس من نور العرش، كل هذا باطل لا أصل له، وليس أول خلق الله، كله باطل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7669/حكم-الجهر-بالصلاة-على-النبي-بعد-الاذان-وما-يقال-معها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24303.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":9523,"question":"هذا سؤال بعث به المستمع عبدالرحمن علي صالح الزهراني من المندق في بلاد زهران يقول: أرى من بعض الأئمة بعدما ينتهي من الصلاة ويتوجه بوجهه إلى المصلين يقول بصوت مرتفع: يغفر الله لنا ولكم. فهل ورد هذا عن النبي ﷺ؟","title":"حكم قول الإمام بعد الصلاة: يغفر الله لنا ولكم","answer":"الجواب: ليس له أصل هذا كونه يلتفت للمصلين ويقول: يغفر الله لنا ولكم هذا ليس له أصل ولم يبلغنا عن النبي صلى الله عليه وسلم مثل هذا فيعتبر بدعة لا وجه لها، بل إذا سلم يقول: (أستغفر الله ثلاثاً، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام). ثم ينصرف إلى الناس في جميع الأوقات الخمسة ينصرف بعد هذا، وإذا انصرف يقول: (لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير)، مرة أو ثلاثاً ويقول: (لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد).\nوالمأموم مثله يقول مثل ذلك، إذا سلم مثل الإمام سواء ويزيد في الفجر والمغرب: (لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير) عشر مرات يزيدها في المغرب والفجر كما جاءت به السنة عن النبي صلى الله عليه وسلم، ثم يستحب أن يقول بعد هذا: (سبحان الله والحمد لله والله أكبر) ثلاثة وثلاثين مرة.. (سبحان الله والحمد لله والله أكبر) ثلاثة وثلاثين مرة، ويقول تمام المائة: (لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير). ثم يقرأ آية الكرسي ثم يقرأ قل هو الله أحد والمعوذتين، هذا هو الأفضل بعد كل صلاة، وفي المغرب والفجر يزيد فيقرأ قل هو الله أحد والمعوذتين ثلاث مرات في الفجر والمغرب في أول الليل وأول النهار كما جاءت به السنة عن النبي ﷺ، هذا هو المشروع بعد كل صلاة، أما أنه يقول للجماعة: يغفر الله لنا ولكم بصوت مرتفع، أو هداكم الله أو تقبل الله منا ومنكم هذا لا أصل له، لكن لو دعا لهم بينه وبين نفسه فيما بينه وبين نفسه دعا لإخوانه المسلمين لا بأس، لكن بصوت مرتفع يتخذه عادة هذا لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/7686/حكم-قول-الامام-بعد-الصلاة-يغفر-الله-لنا-ولكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24405.mp3","categories":["البدع والمحدثات"]},{"id":9527,"question":"يسأل أيضاً ويقول الأخ هاشم مجد الدين: النية في العبادات في الصلاة أو غيرها هل يقول: (نويت أن أصلي الظهر أربع ركعات) بمعنى أن ينطقها أو أن محلها القلب فقط؟","title":"حكم التلفظ بالنية في العبادات وبيان محلها","answer":"الجواب: السنة في النية القلب، هذه السنة، والنطق بها بدعة لا أصل لها، لم ينطق بها النبي ﷺ ولا أصحابه  ولا الأئمة المعروفون من العلماء، ولكن ينوي بقلبه يعلم بقلبه أنه سيتوضأ سيصلي سيصوم سيحج، يكفي عن قول: نويت أن أصلي كذا... ولكن القلب كافٍ والحمد لله، إلا الحج فإنه يتلفظ بالنسك، ما يقول: نويت كذا، يقول: لبيك كذا لبيك حجاً لبيك عمرة، كما فعل النبي عليه الصلاة والسلام وأصحابه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7693/حكم-التلفظ-بالنية-في-العبادات-وبيان-محلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24505.mp3","categories":["البدع والمحدثات"]},{"id":9534,"question":"وهذه رسالة وردتنا من المرسل حاتم ظاهر من الجمهورية العراقية يقول: هل زيارة الإمام أو السيد تعتبر ذنب على الزائر إذا قبل الشباك أو باب الغرفة أو الضريح للإمام؟ وما الحكم في كلام الزائر أثناء هذه الزيارة كأن يقول للإمام: أنا دخيل عليك أن تنقذني من هذه القصة أو غير ذلك أفيدونا أفادكم الله؟","title":"حكم تقبيل الأضرحة عند زيارتها والاستغاثة بأهلها","answer":"الجواب: زيارة القبور سنة مؤكدة للرجال إذا كان المقصود منها الدعاء للميت والترحم عليه والاستغفار له، كما كان النبي يزور القبور عليه الصلاة والسلام وكان أصحابه يزورون القبور، وقال لهم ﷺ: زوروا القبور فإنها تذكركم الآخرة فالزيارة فيها خير عظيم ومصالح تذكر الإنسان الآخرة تذكره الموت يدعو لإخوانه الأموات يستغفر لهم يترحم عليهم هذه الزيارة الشرعية، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون نسأل الله لنا ولكم العافية وفي حديث عائشة: يرحم الله المستقدمين منا والمستأخرين.\nهذه هي الزيارة الشرعية، أما كونه يدعو الميت يقول: أنا دخيلك أو اشفني من مرضي أو خلصني من كذا هذا شرك أكبر.. هذا لا يجوز لا مع أمام ولا مع غير إمام لا مع النبي ولا مع الإمام أبي حنيفة ولا مع غيرهم لا يجوز أن يقال هذا للأموات، لا يقل للميت: أنا في جوارك أن في حسبك اغفر لي أو انصرني أو اشف مريضي أو رد غائبي أو خلصني من هذه الكربة التي أنا فيها أو ما أشبه ذلك هذا لا يقال ولا يجوز، بل هذا من خصاص الله  لا يقال للميت ولا للجماد كالصنم ولا للجن ولا للملائكة بل هذا يطلب من الله ، فالذي يتعاطى هذه الأمور مع أصحاب القبور قد فعل الشرك الأكبر الذي حذر الله منه عباده وأنزل الكتب في حقه وأرسل الرسل لأجل ذلك، قال : كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِنْ لَدُنْ حَكِيمٍ خَبِيرٍ ۝ أَلَّا تَعْبُدُوا إِلَّا الله [هود:1-2] وقال سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال : وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36].\nفالعبادة حق الله سبحانه وتعالى فليس للعبد أن يطلب شفاء المرض أو رد الغائب أو التخليص من الكرب من الأموات أو من الأصنام أو من الكواكب أو من الأشجار والأحجار أو من الجن أو من الملائكة كل هذا لا يجوز بل هو شرك أكبر.\nوإنما الزيارة الشرعية مثل ما تقدم أن يزور القبور ويسلم عليهم ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لا حقون نسأل الله لنا ولكم العافية ويغفر الله لنا ولكم يرحم الله المستقدمين منا والمستأخرين وما أشبه ذلك، دعاء لهم وترحم عليهم وعلى الزائر نفسه هذا هو المشروع.\nوأما تقبيل الشباك أو تقبيل القبر أو التمسح به هذا كله لا يجوز، ولكن يقف عند القبر ويسلم فقط. ولا يجوز البناء على القبور ولا اتخاذ المساجد عليها ولا القباب كل هذا مما أحدثه الناس، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك وقال جابر : نهى النبي ﷺ عن تجصيص القبور والقعود عليها والبناء عليها تجصيص القبور أو البناء عليها أو اتخاذها مساجد كله منكر كله لا يجوز، ومن أسباب الغلو فيها وعبادتها من دون الله.\nفالواجب على الزائر أن يتقيد بالأمر الشرعي وأن يبتعد عما حرم الله عليه، فيزورها كما زارها النبي ﷺوالمسلمون للدعاء للميت والترحم عليه والاستغفار له، أما دعاؤه هو دعاء الميت نفسه والاستغاثة به والنذر له أو التدخل به عن كذا وكذا هذا كله لا يجوز وكله من الشرك بالله ، وهكذا الجلوس عند القبر يدعو الله أو يصلي عند القبر هذا لا يجوز أيضاً بل يجب الحذر من ذلك؛ لأن هذا من وسائل الشرك فدعاء الميت شرك أكبر والاستغاثة به والاستشفاع به ونحو ذلك هذا من الشرك الأكبر، والجلوس عنده للدعاء والصلاة من البدع ومن وسائل الشرك، وهكذا البناء على القبور واتخاذ القباب عليها واتخاذ المساجد كله من البدع وكله من وسائل الشرك ومن ذرائعه، فالواجب على المسلمين أن يحذروا ذلك وأن يعيدوا القبور على حالها الأولى يزيلون ما عليها من مساجد ومن قباب، وعليهم أن يتركوها كما كانت في عهد النبي ﷺ وعهد أصحابه ضاحية تحت الشمس ليس عليها قبة ولا مسجد ولا غير ذلك، هذا هو المشروع وهذا هو الواجب، نسأل الله العافية والسلامة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7696/حكم-تقبيل-الاضرحة-عند-زيارتها-والاستغاثة-باهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24508.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9563,"question":"السؤال الرابع والأخير في رسالة الأخ صبري الجبوري من الجمهورية العراقية يقول فيه: هل يجوز الصلاة على التربة وما فائدتها أثناء الصلاة، أرجو أن تبينوا لنا حكم هذا العمل؟","title":"حكم السجود على تربة كربلاء","answer":"الجواب: كأن السائل يريد التربة التي يعتادها الشيعة وهي حجر يزعمون أنه ... من كربلاء لكي يسجدون عليه، هذا بدعة لا أصل له، ولا يجوز أن يصلى عليه لكن لا تبطل الصلاة ................. لكنه بدعة لا يجوز فعله وهذا مما أحدثته الشيعة، وهذا ... ، الله يهديهم ويعيذنا وإياهم من الشيطان.\nالمقصود أن هذا بدعة وليس للمرء أن ينقل التربة من مكان إلى مكان يصلي عليها بل يصلي على ما تيسر إن كان على الحصباء صلى على الحصباء، وإن كان في الرمل صلى في الرمل إن كان في المسجد الفرش صلى على فراش وليس له أن يحمل حجرًا أو طينًا أو قطعة خشب أو غير ذلك يسجد عليها، لا هذا من البدع فيه زيادة ..... نعم.","link":"https://binbaz.org.sa/fatwas/7728/حكم-السجود-على-تربة-كربلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19304.mp3","categories":["البدع والمحدثات"]},{"id":9658,"question":"وهذه رسالة وردت من (م. ح. د) مصري الجنسية يقيم بالزلفي في المملكة يقول: أنا أعمل بمدرسة في الزلفي، ومعنا جماعة من إخواننا من بنجلادش والباكستان، وبعد صلاة العشاء يبدءون بالتسبيح بالحجارة، وعدد الحجارة ألف حجر وهم يجلسون في المسجد دائرة ويتبادلون الحجارة، وعندما يتبادلونها يقول الواحد منهم: لا إله إلا أنت سبحانك إني كنت من الظالمين، أرجو منكم الإفادة في ذلك وفقكم الله؟","title":"حكم التسبيح بالحصى أو بغيرها","answer":"الجواب: هذا العمل مبتدع، كون الإنسان يجلس مع إخوان له يسبحون ويحمدون ويكبرون بالحصى أو بالحجارة يتساعدون في هذا الأمر هذا لا يجوز، أما إذا كان الواحد بنفسه يسبح بينه وبين نفسه يذكر الله بينه وبين نفسه بأصابعه، أو بحجارة أو بنوى، فلا بأس، لكن الأصابع أفضل، أما كونهم يتحلقون ويجتمعون على هذا الأمر، هذا يقول: سبح كذا، وهذا يقول: احمد كذا، أو كل واحد له عليه قانون معروف إذا فرغ شرع الآخر، هذا هو الذي أنكره عبد الله بن مسعود  فإنه خرج على قوم في مسجد الكوفة وهم متحلقون يقول لهم فلان: سبحوا مائة، افعلوا كذا، فيعدون بالحصى فأنكر عليهم، وقال: إنكم لعلى ملة هي أهدى من ملة محمد، أو مفتتحو باب ضلالة فأنكر عليهم ذلك، وقالوا: يا أبا عبد الرحمن ! ما أردنا إلا خيراً، قال: كم من مريد للخير لم يصبه.\nفالمقصود: أن هذه من البدع التي أحدثها الناس، لكن إذا أحب الإنسان أن يذكر الله بينه وبين نفسه في الصف، في الصف الأول في الصف الثاني بحسب مجيئه إلى الصلاة، في ركن من أركان المسجد، في محل في بيته لا بأس، يذكر الله بينه وبين ربه، يسبح يهلل يستغفر يدعو يعد بأصابعه لا بأس، وإن عد بالنوى وغيرها فلا حرج، لكن الأصابع أفضل. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: تعيد سؤاله أيضاً، تعيده مرة أخرى. نعم.\nالمقدم: أعيد السؤال: يقول: معنا جماعة من البنجلادش وباكستان بعد صلاة العشاء يبدءون بالتسبيح بالحجارة، وعدد الحجارة ألف حجر، يجلسون دائرة في المسجد ويتبادلون الحجارة بينهم، يعني كل واحد يأخذ الحجر فيعطيه لجاره، وعندما يتبادلونها يقول: لا إله إلا أنت سبحانك إني كنت من الظالمين؟\nالشيخ: مثلما تقدم، هذه بدعة، والواجب تركها، وأن كل واحد إذا أراد يسبح يسبح بينه وبين ربه في الصف، اللي صف ... ينتظر الصلاة أو بعد الصلاة، أو في بيته، أو في زاوية من زوايا المسجد، أو على أحد عمد المسجد يجلس يذكر ربه بينه وبين ربه، أما هذا العمل يحلقون ويتبادلون الحجر وألف حجر كل هذا لا أصل له، كل هذا من البدع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7826/حكم-التسبيح-بالحصى-او-بغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25108.mp3","categories":["البدع والمحدثات"]},{"id":9767,"question":"أحد الإخوة المستمعين يسأل سماحتكم ويقول: ما هي البدعة الاعتقادية، وما هي البدعة العملية؟","title":"حقيقة البدعة الاعتقادية والبدعة العملية","answer":"الجواب: كل ما خالف الشرع فهو بدعة، إن كان في الاعتقاد يسمى بدعة، مثل دعاء الأموات، والاستغاثة بالأموات، والاستغاثة بالجن، أو بالملائكة، يظنها ديناً يعتقد أنها دين، يحسب أنها جائزة، هذه بدعة شركية كفر أكبر، ويسمى بدعة؛ لأنه يظن أنها دين -صاحبها-.\nكذلك البناء على القبور واتخاذ المساجد عليها بدعة، لكنها دون الكفر وسيلة للكفر، إذا بنى مسجد على القبر يحسب إنه دين، أو بنى قبة على القبر يحسب أن هذا جائز هذه بدعة منكرة ومن وسائل الشرك، لقول النبي ﷺ: لعن الله اليهود والنصارى ، اتخذوا قبور أنبيائهم مساجد.\nأما دعاء الأموات والاستغاثة بالأموات، والنذر لهم هذه بدعة شركية، يكون صاحبها كافراً كفراً أكبر، ولو زعم أنه جاهل؛ لأن هذا أمر معروف من الدين بالضرورة، معروف بين المسلمين، هو كافر بذلك، فعليه التوبة إلى الله من ذلك، يستتاب فإن تاب وإلا قتل من ولي الأمر -الحاكم الشرعي-.\nوهناك بدع كثيرة مثل بدعة المولد، الاحتفال بمولد النبي ﷺ أو مولد غيره، ومثل بدعة ليلة الإسراء والمعراج سبعة وعشرين رجب الاحتفال بها، هذه بدعة أيضاً عملية، ومنكرة لا تجوز، ولكن ليست من الشرك الأكبر، إلا إذا كان فيها شرك، إذا كان في المولد أو في الاحتفال بليلة الإسراء والمعراج دعاء للنبي صلى الله عليه وسلم واستغاثة به يكون شركاً أكبر.\nأما إذا كان مجرد احتفال على الأكل والشرب والقهوة والشاي ولا فيه دعاء ولا استغاثة بالنبي صلى الله عليه وسلم، هذه بدعة منكرة، يمنعها قول النبي ﷺ: من أحدث في أمرنا هذا -يعني: ديننا- ما ليس منه فهو رد، يعني: فهو مردود، وقوله ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد، وقوله ﷺ: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة، والبدعة: هي الشيء المحدث في الدين، الذي يحدثه الناس يتقربون إلى الله، والرسول ﷺ ما شرعه، ما شرعه الله ولا رسوله يسمى بدعة، مثل الاحتفال بمولد النبي ﷺ، أو باحتفال بمولد الصديق أو عمر أو عثمان أو علي ، أو الحسين أو غيرهم، أو الاحتفال بمولد أبي حنيفة أو الشافعي أو مالك أو الشيخ: عبد القادر الجيلاني ، أو الست نفيسة أو الست زينب أو ما أشبه ذلك، كلها بدع منكرة لا تجوز، ومن وسائل الشرك نعوذ بالله، بعض الناس في المولد يشرك بالله، في مولد النبي ﷺ، يدعو النبي ﷺ ويستغيث به، هذا الشرك الأكبر، وبعضهم في مولد علي يستغيث بـعلي .. يستغيث به وينذر له، ويدعوه من دون الله هذا شرك أكبر.\nوهكذا في الموالد الأخرى، يدعون صاحب المولد يستغيثون به، هذا الشرك الأكبر نعوذ بالله، ربنا يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ( يعني: من دون الله )مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13]، القطمير، اللفافة التي على النواة حقة التمر، إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ( يعني: الأموات، والأصنام ونحوهم : إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ [فاطر:14]، ما عندهم قدرة يعطونك ما طلبت : وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ ... [فاطر:14].\nوهكذا الجلوس عند القبور للدعاء، يرى أن الدعاء أفضل عند القبور للدعاء بدعة، كذلك قول بعضهم: نويت أن أصلي لله أربع ركعات أو ثلاث ركعات بدعة التلفظ بالنية، إذا قام إلى الصلاة ينوي بقلبه ويكفي؛ ينوي بقلبه أنه قام للظهر للعصر للمغرب للعشاء .. وهكذا جميع الصلوات النافلة ينوي بقلبه ويكفي، أما أن يقول بعد وقوفه: نويت أن أصلي لله أربع ركعات، يعني: الظهر أو العصر، أو ثلاث ركعات يعني: المغرب أو ركعتين يعني: الفجر أو الجمعة هذه بدعة، ما كان النبي ﷺ يفعله ولا الصحابة رضي الله عنهم وأرضاهم، ولكن تقف خاشعاً ناوياً بقلبك الصلاة والحمد ... ويكفي، فلا حاجة إلى أن تقول: نويت أن أصلي كذا وكذا، أو نويت أن أطوف، أو أن أسعى، بل تأتي بنية الطواف وتبدأ بالحجر الأسود ناوياً الطواف، وعند السعي كذلك تبدأ بالصفا ناوياً السعي ويكفي، نعم.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7938/حقيقة-البدعة-الاعتقادية-والبدعة-العملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25712.mp3","categories":["البدع والمحدثات"]},{"id":9779,"question":"هذه رسالة وردتنا من السائل أبو سلمان من الخرطوم يقول في رسالته: يوجد عندنا طريقة وهي أنه إذا مات الإنسان يعملون شيء يسمى بالفراش، فيجلس كثير من الناس في هذا الفراش سبعة أيام أو أربعين يوماً، ويأتون بالنوبات والطارات ويرقصون ويصفقون، فما حكم الشرع في ذلك؟","title":"بعض بدع العزاء","answer":"الجواب: هذا العمل منكر، ومن البدع التي ما أنزل الله بها من سلطان، فالفراش والجلوس عليه أيام معدودة أو الرقص أو الغناء أو النياحة كل هذا منكر.\nولكن المشروع بعد الموت الصلاة عليه صلاة الجنازة، والدعاء له بالمغفرة والرحمة، وصنع الطعام لأهله يكون جيرانهم أو أقاربهم يصنعون لهم طعام لأنهم مشغولون بالمصيبة؛ كما فعل النبي ﷺ لما جاءه نعي جعفر ابن عمه لما قتل يوم مؤتة وجاء خبره، أمر ﷺ أهله أن يصنعوا لأهل جعفر طعاماً قال: لأنه قد أتاهم ما يشغلهم فإذا صنع الجيران أو الأقارب طعاماً لأهل الميت حتى يكفوهم مئونة الطعام من أجل المصيبة فلا بأس.\nأما أن ينوحوا عليه أو يتخذوا الفراش المذكور يتناوبون عليه بالجلوس أو بالقراءة أو بغير ذلك أو بضرب الطيران .... والطبول أو ما أشبه ذلك كل هذا من البدع المنكرة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7942/بعض-بدع-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25803.mp3","categories":["البدع والمحدثات"]},{"id":9800,"question":"يقول في استفساره الثالث الأخ أحمد حسن زيد من اليمن: أناس عندنا يقرءون القرآن على الأموات ويأخذون عليه أجرة، فهل يستفيد منه الأموات شيئًا، وإذا مات واحد منهم يقرءون عليه القرآن ثلاثة أيام ويعملون ذبائح وولائم، هل هذا من الشرع؟","title":"حكم أخذ الأجرة على قراءة القرآن على الأموات","answer":"الجواب: هذا بدعة؛ القراءة على الأموات وأخذ الأجرة بدعة ولا يجوز، لا تجوز أجرة وليس له أن يقرأ على الموتى وليس هناك ما يدعو على انتفاعهم به بل هذا منكر وبدعة وهكذا الذبائح والطعام، كونه يصنع أهل الميت طعامًا وذبائح كله منكر وبدعة لا يجوز، يقول جرير بن عبدالله البجلي  الصحابي الجليل: كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة، والنياحة محرمة معلوم.\nفالمقصود أن هذا من البدع والنبي ﷺ قال: من عمل عملًا ليس عليه أمرنا فهو رد، ولم يكن من عمل النبي ﷺ ولا من عمل الصحابة أنه إذا مات الميت يقرءون له القرآن أو يقرءون عليه القرآن أو يذبحون الذبائح أو يقيمون المآتم والأطعمة والحفلات كل هذا منكر، هذا بعد السلف الصالح، فالواجب الحذر من ذلك والواجب تحذير الناس من ذلك، هذا هو الواجب على أهل العلم وعلى ولاة الأمور أن يردعوا الناس عما حرم الله وأن يأخذوا على أيدي الجهلة والسفهاء حتى يستقيموا على الطريق السوي الذي شرعه الله للعباد وبذلك تصلح الأحوال وتصلح المجتمعات ويظهر حكم الإسلام ويختفي أمر الجاهلية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7967/حكم-اخذ-الاجرة-على-قراءة-القران-على-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19616.mp3","categories":["البدع والمحدثات"]},{"id":9888,"question":"أخيراً يقول صاحبنا بدري المصري الذي يعمل بالرياض: عندنا في القرية شيخ له ضريح، ويعمل له الناس مولداً كل عام ويجمعوا بعض المال من المواطنين وأنا ممن يؤخذ منهم المال وأنا غير مقتنع، ولما عارضت قالوا لي: إن هذا ليس حرام، ونحن نشتري بهذا المال ذبائح للناس الذين يحضرون المولد من البلدة وغيرها، فما الحكم في ذلك بارك الله فيكم؟","title":"حكم الاحتفال بمولد صاحب ضريح","answer":"الجواب: هذا بدعة ومنكر، لا يجوز اتخاذ الموالد لا للعالم ولا لشيخ القبيلة، ولا لكبير الحارة ولا لغيرهم، الموالد بدعة، وهكذا الاحتفال بالمولد النبوي على صاحبه أفضل الصلاة والسلام ليس له أصل، وهكذا الاحتفال بموالد الأنبياء أو الصالحين أو العلماء كله لا أصل له، وقد كان النبي ﷺ بين أصحابه في المدينة عشر سنين، ولم يحتفل بمولده ﷺ ولم يأمر بذلك، ولم يفعله أصحابه  وأرضاهم، وهكذا خلفاؤه الراشدون الصديق وعمر وعثمان وعلي لم يحتفلوا به، وهكذا بقية الصحابة لم يحتفلوا به، وهكذا من بعدهم في القرون المفضلة القرن الأول والثاني والثالث لم يحتفلوا بذلك.\nفينبغي للمسلمين أن يدعوا هذا، وإنما المهم أن يحافظوا على طاعته ﷺ، واتباع شريعته وتعظيم أمره ونهيه، والمسارعة إلى ما أمر به وترك ما نهى عنه عليه الصلاة والسلام.\nوأما الشيوخ والعلماء، فمن باب أولى أن لا يجوز اتخاذ موالد لهم، فهذا الضريح الذي عندكم لا يحتفل بصاحبه لا بمولد ولا بغيره، ولكن إذا كان طيباً يدعى له بالمغفرة، إذا كان مسلم يدعى له بالمغفرة والرحمة، ويزار الزيارة الشرعية يمر على قبره ويدعى له.. السلام عليك يا فلان! غفر الله لك ورحمنا وإياك ويكفي، أما أن يدعى من دون الله، يستغاث به هو أو يتمسح بقبره أو يطاف به هذا منكر عظيم، لا يطاف بقبره ولا يدعى من دون الله، لا يقال: يا سيدي فلان، انصرني أو أنا في حسبك أو في جوارك أو اشفع لي أو اشف مريضي، كل هذا منكر لا يجوز، بل هو من المحرمات الشركية، وهكذا لا يطاف بالقبر ولا يتمسح بالتراب ولا بالنصائب، كل هذا من المنكرات العظيمة ومن التبرك المنكر، بل طلب البركة من القبور شرك أكبر نسأل الله العافية. فالواجب على أهل القرية أن يحذروا ما حرم الله عليهم، وأن يدعوا هذا الاحتفال وأن لا يأخذوا أموال الناس بالباطل، وأن يدعوا لهذا الميت إذا كان طيباً مسلماً يدعى له بالمغفرة والرحمة ويكفي والحمد لله.","link":"https://binbaz.org.sa/fatwas/8046/حكم-الاحتفال-بمولد-صاحب-ضريح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26403.mp3","categories":["البدع والمحدثات"]},{"id":9961,"question":"وهذا السائل مصري الجنسية يعمل في الكويت رمز لاسمه بـ (م. س. ع) يقول في رسالة طويلة الحقيقة وقد أفاض فيها، وكثير من الإخوة يحرجوننا بهذه الرسائل؛ لأنها تأخذ من وقت البرنامج، ولا نستطيع عرضها بكاملها، هذا السائل يقول في رسالته:عندنا مقبرة كبيرة بها ثلاثة أضرحة مبني عليها قباب كبيرة، يقال: أنها بنيت منذ مائتي عام، ومما يؤسف له أن هناك امرأة عجوز تذهب لهذه الأضرحة بحجة أنهم أولياء وتقوم بتنظيفها، ويذهب الناس إلى هذه الأضرحة فيذبحون لها وينذرون لها، وهناك فريق يقول: إنه يلزم هدم هذه القباب، وفريق آخر يقول: لا يجوز لنا هدمها لأنها قباب قديمة وبنيت منذ فترة فلا نعرف وضعها، سؤالي ما حكم مثل هذه الأعمال، خدمة المرأة لهذه الأضرحة، الذبح والنذر عندها، وضع الأموال، ثم أين تذهب هذه الأموال، وأين تذهب هذه الذبائح؟! وفقكم الله.","title":"حكم بناء القباب على القبور والذبح والنذر لها","answer":"الجواب: البناء على القبور أمر منكر، لا يجوز اتخاذ القباب عليها ولا اتخاذ المساجد عليها، بل نهى الرسول عن هذا عليه الصلاة والسلام، بل لعن من فعل ذلك، قال عليه الصلاة والسلام: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال جابر : نهى رسول الله ﷺ عن تجصيص القبور والقعود عليها والبناء عليها خرجه مسلم في صحيحه، وهكذا روى النسائي والترمذي وغيرهما: (النهي عن الكتابة على القبور) أيضاً.\nفالحاصل: أن البناء على القبور أمر منكر، نهى عنه الرسول صلى الله عليه وسلم، واتخاذ المساجد عليها كذلك؛ لأنه وسيلة إلى الغلو فيها وعبادتها من دون الله بالدعاء، أو الطواف أو الاستغاثة بها أو الذبح لها، كل هذا يقع من بعض الجهلة، وهذا من الشرك الأكبر، الطواف على القبور تقرباً إلى الموتى بذلك، أو الدعاء للميت أو الاستغاثة بالميت، أو طلبه شفاء المريض أو قضاء الحاجة، أو رد الغائب أو ما أشبه ذلك، هذا من الشرك الأكبر، هذه لا تطلب من الأصنام ولا من الموتى، ولا من الشجر والحجر، ولا من الكواكب، هذه تطلب من الله ، هو الذي يشفي المرضى ويرد الغياب ويقضي الحاجات ويكشف الكربات .\nأما طلب هذا من الموتى أو من الأصنام أو من الأشجار والأحجار أو من الكواكب هذا كله شرك بالله عز وجل، وهكذا الطواف على القبور منكر، الطواف.. يكون بالكعبة، لا يطاف بالقبور، هذا منكر عظيم، بل شرك أكبر إذا قصد به التقرب لصاحب القبر، فهو شرك أكبر، وإذا ظن أنه قربة لله وأنه يتقرب إلى الله بهذا هذه بدعة منكرة ووسيلة إلى الشرك، فلا يطوف لا لله عند قبر ولا للميت، لا يطوف عند القبر أبداً، الطواف من خصائص البيت العتيق الكعبة، القبور لا يطاف بها أبداً، بل هذا منكر وبدعة، وإذا كان فعله لصاحب القبر صار شركاً أكبر، وهكذا دعاء الميت والاستغاثة بالميت، والنذر له، والذبح له، كله من الشرك الأكبر. فالواجب على المسلمين الحذر من ذلك، وعلى أعيان المسلمين منع هؤلاء من هذا العمل، وعلى الحكام والأمراء أن يمنعوا الجهلة من هذا الشيء، هكذا الواجب على حكام المسلمين، لأن الله جل وعلا أقامهم لمنع الأمة مما يضرها ولإلزامها بما أوجب الله عليها، وللنظر في مصالحها، هذا واجب الحكام، الحكام من الأمراء والملوك والسلاطين إنما شرعت ولايتهم ليقيموا أمر الله في أرض الله، لينفذوا أحكام الله.\nفعلى الأمير في القرية، وعلى الحاكم في أي مكان، وعلى السلطان ورئيس الجمهورية وعلى كل من له قدرة أن يساهم في هذا الخير، وذلك بإزالة هذه الأبنية والقباب والمساجد التي بنيت على القبور، وأن تبقى القبور مكشوفة، مثل القبور في البقيع في عهد النبي ﷺ وفي عهدنا الآن في المدينة، القبور تكشف ولا يكون عليها بناء لا مسجد ولا حجرة سقف ولا قبة ولا غير ذلك؛ لأن الرسول ﷺ نهى عن البناء على القبور واتخاذ المساجد عليها وتجصيصها؛ لأن هذا وسيلة إلى أن يغلى فيها، إلى أن تعبد مع الله، وهكذا لا يهدى إليها نقود ولا ذبائح ولا ملابس ولا للسدنة عندها، وهذه العجوز التي تأتي القبر هذه تمنع لا تأتي هذه المقابر، ولا تقوم بتنظيفها؛ لأن هذه دعاية للشرك، ولكن تصان القبور إذا سورت أطراف المقبرة كلها بسور حتى لا تمتهن، حتى لا تتخذ طرق أو للدواب لا بأس.\nأما البناء على القبر لتعظيمه أو لإظهار شرفه وفضله هذا كله منكر، لا يجوز البناء على القبور أبداً، ويمنع وضع السدنة عند القبور لأخذ أموال الناس، أو تغرير الناس ودعوتهم إلى الشرك، كل هذا يجب منعه، وهذا واجب الحكام وواجب الأعيان وواجب أمراء البلاد، أن يسعوا في هذا الخير وأن ينصحوا للعامة والجهال ويعلموهم، كان النبي ﷺ إذا زار القبور يقول كان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، وكان يقول لهم إذا زار البقيع عليه الصلاة والسلام بنفسه: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، أتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد هكذا يدعو لهم، هذا السنة، يدعى للمقبورين بالرحمة والمغفرة، يسلم عليهم ويدعو لهم ثم ينصرف، لا يدعوهم مع الله لا يستغيث بهم، لا يتمسح بقبورهم، لا يقبلها بل يدعو وينصرف، يدعو لهم بالمغفرة والرحمة ثم ينصرف؛ لأن زيارة القبور فيها ذكرى للآخرة، وذكرى للموت، أما أن يجلس عند القبور يقرأ أو يدعو أو يتمسح بالقبر، أو يقبله هذا لا يجوز أو يدعوه من دون الله أو يستغيث به أو ينذر له كل هذا من أعمال الجاهلية، من أعمال المشركين الأولين.\nفيجب الحذر منها، ويجب تعليم الناس وإرشادهم وتوجيههم إلى الخير، وتعليمهم ما ينفعهم، حتى لا يقعوا في الشرك، وحتى لا يكونوا من جنس الجاهلية الأولى، والله المستعان. نعم.\nالمقدم: وفقكم الله.","link":"https://binbaz.org.sa/fatwas/8125/حكم-بناء-القباب-على-القبور-والذبح-والنذر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26504.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9970,"question":"وهذا السائل مصري الجنسية يعمل في الكويت رمز لاسمه بـ (م. س. ع) يقول في رسالة طويلة الحقيقة وقد أفاض فيها، وكثير من الإخوة يحرجوننا بهذه الرسائل؛ لأنها تأخذ من وقت البرنامج، ولا نستطيع عرضها بكاملها، هذا السائل يقول في رسالته:عندنا مقبرة كبيرة بها ثلاثة أضرحة مبني عليها قباب كبيرة، يقال: أنها بنيت منذ مائتي عام، ومما يؤسف له أن هناك امرأة عجوز تذهب لهذه الأضرحة بحجة أنهم أولياء وتقوم بتنظيفها، ويذهب الناس إلى هذه الأضرحة فيذبحون لها وينذرون لها، وهناك فريق يقول: إنه يلزم هدم هذه القباب، وفريق آخر يقول: لا يجوز لنا هدمها لأنها قباب قديمة وبنيت منذ فترة فلا نعرف وضعها، سؤالي ما حكم مثل هذه الأعمال، خدمة المرأة لهذه الأضرحة، الذبح والنذر عندها، وضع الأموال، ثم أين تذهب هذه الأموال، وأين تذهب هذه الذبائح؟! وفقكم الله.","title":"حكم بناء القباب على القبور والذبح والنذر لها","answer":"الجواب: البناء على القبور أمر منكر، لا يجوز اتخاذ القباب عليها ولا اتخاذ المساجد عليها، بل نهى الرسول عن هذا عليه الصلاة والسلام، بل لعن من فعل ذلك، قال عليه الصلاة والسلام: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال جابر : نهى رسول الله ﷺ عن تجصيص القبور والقعود عليها والبناء عليها خرجه مسلم في صحيحه، وهكذا روى النسائي والترمذي وغيرهما: (النهي عن الكتابة على القبور) أيضاً.\nفالحاصل: أن البناء على القبور أمر منكر، نهى عنه الرسول صلى الله عليه وسلم، واتخاذ المساجد عليها كذلك؛ لأنه وسيلة إلى الغلو فيها وعبادتها من دون الله بالدعاء، أو الطواف أو الاستغاثة بها أو الذبح لها، كل هذا يقع من بعض الجهلة، وهذا من الشرك الأكبر، الطواف على القبور تقرباً إلى الموتى بذلك، أو الدعاء للميت أو الاستغاثة بالميت، أو طلبه شفاء المريض أو قضاء الحاجة، أو رد الغائب أو ما أشبه ذلك، هذا من الشرك الأكبر، هذه لا تطلب من الأصنام ولا من الموتى، ولا من الشجر والحجر، ولا من الكواكب، هذه تطلب من الله ، هو الذي يشفي المرضى ويرد الغياب ويقضي الحاجات ويكشف الكربات .\nأما طلب هذا من الموتى أو من الأصنام أو من الأشجار والأحجار أو من الكواكب هذا كله شرك بالله عز وجل، وهكذا الطواف على القبور منكر، الطواف.. يكون بالكعبة، لا يطاف بالقبور، هذا منكر عظيم، بل شرك أكبر إذا قصد به التقرب لصاحب القبر، فهو شرك أكبر، وإذا ظن أنه قربة لله وأنه يتقرب إلى الله بهذا هذه بدعة منكرة ووسيلة إلى الشرك، فلا يطوف لا لله عند قبر ولا للميت، لا يطوف عند القبر أبداً، الطواف من خصائص البيت العتيق الكعبة، القبور لا يطاف بها أبداً، بل هذا منكر وبدعة، وإذا كان فعله لصاحب القبر صار شركاً أكبر، وهكذا دعاء الميت والاستغاثة بالميت، والنذر له، والذبح له، كله من الشرك الأكبر. فالواجب على المسلمين الحذر من ذلك، وعلى أعيان المسلمين منع هؤلاء من هذا العمل، وعلى الحكام والأمراء أن يمنعوا الجهلة من هذا الشيء، هكذا الواجب على حكام المسلمين، لأن الله جل وعلا أقامهم لمنع الأمة مما يضرها ولإلزامها بما أوجب الله عليها، وللنظر في مصالحها، هذا واجب الحكام، الحكام من الأمراء والملوك والسلاطين إنما شرعت ولايتهم ليقيموا أمر الله في أرض الله، لينفذوا أحكام الله.\nفعلى الأمير في القرية، وعلى الحاكم في أي مكان، وعلى السلطان ورئيس الجمهورية وعلى كل من له قدرة أن يساهم في هذا الخير، وذلك بإزالة هذه الأبنية والقباب والمساجد التي بنيت على القبور، وأن تبقى القبور مكشوفة، مثل القبور في البقيع في عهد النبي ﷺ وفي عهدنا الآن في المدينة، القبور تكشف ولا يكون عليها بناء لا مسجد ولا حجرة سقف ولا قبة ولا غير ذلك؛ لأن الرسول ﷺ نهى عن البناء على القبور واتخاذ المساجد عليها وتجصيصها؛ لأن هذا وسيلة إلى أن يغلى فيها، إلى أن تعبد مع الله، وهكذا لا يهدى إليها نقود ولا ذبائح ولا ملابس ولا للسدنة عندها، وهذه العجوز التي تأتي القبر هذه تمنع لا تأتي هذه المقابر، ولا تقوم بتنظيفها؛ لأن هذه دعاية للشرك، ولكن تصان القبور إذا سورت أطراف المقبرة كلها بسور حتى لا تمتهن، حتى لا تتخذ طرق أو للدواب لا بأس.\nأما البناء على القبر لتعظيمه أو لإظهار شرفه وفضله هذا كله منكر، لا يجوز البناء على القبور أبداً، ويمنع وضع السدنة عند القبور لأخذ أموال الناس، أو تغرير الناس ودعوتهم إلى الشرك، كل هذا يجب منعه، وهذا واجب الحكام وواجب الأعيان وواجب أمراء البلاد، أن يسعوا في هذا الخير وأن ينصحوا للعامة والجهال ويعلموهم، كان النبي ﷺ إذا زار القبور يقول كان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، وكان يقول لهم إذا زار البقيع عليه الصلاة والسلام بنفسه: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، أتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد هكذا يدعو لهم، هذا السنة، يدعى للمقبورين بالرحمة والمغفرة، يسلم عليهم ويدعو لهم ثم ينصرف، لا يدعوهم مع الله لا يستغيث بهم، لا يتمسح بقبورهم، لا يقبلها بل يدعو وينصرف، يدعو لهم بالمغفرة والرحمة ثم ينصرف؛ لأن زيارة القبور فيها ذكرى للآخرة، وذكرى للموت، أما أن يجلس عند القبور يقرأ أو يدعو أو يتمسح بالقبر، أو يقبله هذا لا يجوز أو يدعوه من دون الله أو يستغيث به أو ينذر له كل هذا من أعمال الجاهلية، من أعمال المشركين الأولين.\nفيجب الحذر منها، ويجب تعليم الناس وإرشادهم وتوجيههم إلى الخير، وتعليمهم ما ينفعهم، حتى لا يقعوا في الشرك، وحتى لا يكونوا من جنس الجاهلية الأولى، والله المستعان. نعم.\nالمقدم: وفقكم الله.","link":"https://binbaz.org.sa/fatwas/8125/حكم-بناء-القباب-على-القبور-والذبح-والنذر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26504.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9985,"question":"يقول: عندنا في البلدة قبل قيام المؤذن لصلاة الفجر يقول جميع من في المسجد: لا إله إلا الله قبل كل أحد، لا إله إلا الله بعد كل أحد، لا إله إلا الله محمد رسول الله حقًا وصدقًا ويقينًا، فهل هذه الأذكار وردت، ويجوز ذكرها في هذا الوقت؟","title":"حكم الذكر الجماعي بصوت مرتفع قبل القيام لأذان الفجر","answer":"الجواب: هذه الأذكار لا أصل لها في هذا الوقت، بل هي بدعة بهذا الشكل، يعني: برفع الصوت، والمواظبة على ذلك والاعتياد هذا لا أصل له بل هو بدعة، يقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ولم يكن ﷺ ولا أصحابه يفعلون هذا، لا قبل صلاة الفجر ولا قبل صلاة غيرها، لكن إذا ذكر الله بينه وبين نفسه لا حرج عليه، بينه وبين نفسه: لا إله إلا الله وحده لا شريك له، لا إله إلا الله قبل كل أحد وبعد كل أحد، هذا كله لا حرج في ذلك، هو الإله الحق سبحانه قبل الناس وبعد الناس، لكن كونه يقال هذا الذكر عن صوت واعتياد قبل قيام صلاة الفجر هذا لا أصل له بل هو بدعة، فالواجب تركه، الواجب أن ينصحوا حتى يتركوه، أما من ذكر الله في نفسه فلا حرج عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8150/حكم-الذكر-الجماعي-بصوت-مرتفع-قبل-القيام-لاذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33102.mp3","categories":["البدع والمحدثات"]},{"id":9987,"question":"أولى الرسائل وردت من جمهورية السودان من محمد أحمد عبد الحكم من منطقة الكاملين، يقول في رسالته هذه، والتي ضمنها عدداً من الأسئلة: فسر الشيخ النووي رحمه الله في شرحه موضوع البدعة إلى خمسة أقسام: الأول: بدعة واجبة ومثالها نظم أدلة المتكلمين على الملاحدة، الثاني: المندوبة مثالها تصنيف كتب العلم، الثالث: المباحة مثالها التبسط في ألوان الطعام، الرابع والخامس: الحرام والمكروه وهما واضحان،  يقول الرسول ﷺ: كل بدعة ضلالة أرجو توضيح ذلك مع ما يقصده الشيخ النووي رحمه الله، بارك الله فيكم؟","title":"حكم تقسيم البدعة إلى خمسة أقسام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذا الذي نقلته عن النووي في تقسيم البدعة إلى خمسة أقسام قد ذكره جماعة من أهل العلم، وقالوا: إن البدعة تنقسم إلى أقسام خمسة: واجبة، ومستحبة، ومباحة، ومحرمة، ومكروهة.\nوذهب آخرون من أهل العلم إلى أن البدعة كلها ضلالة وليس فيها تقسيم، بل كلها كما قال النبي ﷺ: ضلالة، قال عليه الصلاة والسلام: كل بدعة ضلالة هكذا جاءت الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام، منها ما رواه مسلم في الصحيح عن جابر بن عبد الله الأنصاري رضي الله تعالى عنهما قال: كان النبي ﷺ يخطب يوم الجمعة فيقول في خطبته: أما بعد فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة، وجاء في هذا المعنى عدة أحاديث من حديث عائشة ومن حديث العرباض بن سارية وأحاديث أخرى، وهذا هو الصواب أنها لا تنقسم إلى هذه الأقسام التي ذكر النووي وغيره بل هي كلها ضلالة، والبدعة تكون في الدين لا في الأمور المباحة، فالتنوع في الطعام على وجه جديد لا يعرف في الزمن الأول لا يسمى بدعة من حيث الشرع، وإن كان بدعة من حيث اللغة؛ لأن البدعة في اللغة هو المحدث على غير مثال سابق كما قال : بَدِيعُ السَّمَوَاتِ وَالأَرْضِ [البقرة:117] يعني مبتدعها وموجدها على غير مثال سابق، لكن لا يقال: بدعة إلا لما كان في التعبد في الأعمال الشرعية، فهذا كله يقال فيه: ضلالة، ما يقال فيه: إنها أقسام واجب وسنة إلى آخره، هذا هو الحق وهذا هو الصواب الذي ارتضاه جماعة من أهل العلم وقرروه وردوا على من خالف ذلك، وكذلك تأليف الكتب وتنظيم الأدلة للرد على الملحدين والخصوم ما يسمى بدعة، هذا مما أمر الله به ورسوله، فهو طاعة لله وليس ببدعة، فالكتاب العزيز جاء بالرد على الخصوم، لأعداء الله بآيات عظيمات، وجاءت السنة بذلك أيضاً للرد على خصوم الإسلام، وهكذا المسلمون من عهد الصحابة إلى يومنا هذا اعتنوا بالرد على خصوم الإسلام بما ظهر لهم من كتاب الله وسنة الرسول ﷺ، وأوضحوا الأدلة ونوعوها، وكل هذا لا يسمى بدعة في الشرع بل هو قيام بالواجب وجهاد في سبيل الله وليس ببدعة في حكم الشرع، وهكذا بناء المدارس والربط والقناطر وغير هذا مما ينفع المسلمين لا يسمى بدعة من حيث الشرع، بل هو أمر مأمور به؛ لأن الشرع أمر بالتعليم، فالمدارس تعين على التعليم، وكذلك ما يتعلق بالربط للفقراء أمر بالإحسان إلى الفقراء والمساكين فإذا بني لهم مساكن تسمى الربط فهذا مما أمر الله به، وهكذا القناطر على الأنهار كل هذا مما ينفع المسلمين وليس ببدعة بل هو أمر مشروع، تسميته بدعة إنما يكون من جنس ما تقدم من حيث اللغة العربية، كما قال عمر رضي الله عنه في التراويح لما جمع الناس على إمام واحد يصلي بهم التراويح كل ليلة قال: نعمت البدعة هذه يعني من حيث اللغة، وإلا فالتراويح سنة مؤكدة فعلها النبي ﷺ وحث عليها ورغب فيها فليست بدعة بل هي سنة، ولكن سماها عمر بدعة من حيث اللغة، أنها فعلت على غير مثال سابق؛ لأنهم كانوا في عهد النبي ﷺ يصلون أوزاعًا في المسجد ليسوا على إمام واحد، هذا يصلي مع اثنين، وهذا يصلي مع ثلاثة، وهذا يصلي مع أكثر، وصلى بهم النبي صلى الله عليه وسلم ثلاث ليالٍ ثم ترك، وقال: إني أخشى أن تفرض عليكم صلاة الليل فتركها خوفًا على أمته من أن تفرض عليهم، فالحاصل أن قيام رمضان سنة مؤكدة وليس بدعة من حيث الشرع وإن سماه عمر  بدعة من حيث اللغة.\nوالخلاصة أن الصواب أن كل ما أحدثه الناس في الدين مما لم يشرعه الله فإنه يسمى بدعة وهي بدعة ضلالة ولا يجوز فعلها، ولا يجوز تقسيم البدع إلى واجب وإلى سنة وإلى مباح إلى آخره، هذا خلاف القاعدة التي بينها النبي ﷺ، وفي هذا خطر، كأن القائل يرد على النبي ﷺ، فالنبي ﷺ يقول: كل بدعة ضلالة، وهذا يقول: لا، بل هي أقسام، هذا خطر عظيم.\nفالواجب على أهل العلم أن يتأدبوا مع رسول الله ﷺ، وأن يحذروا الشيء الذي قد يخدش في حق من فعل ما يخالف السنة، وإن كان العلماء رحمة الله عليهم الذين قالوا ذلك لم يقصدوا الرد على الرسول ﷺ، يحميهم الله من ذلك ما قصدوا هذا، ولكن قد يحتج بذلك عليهم من يظن بهم السوء من أعداء الله، وقد يظن ذلك بعض الجهلة.\nفالحاصل أن التقسيم إلى بدعة مستحبة وواجبة إلى آخره ليس هو الصواب بل الصواب خلافه.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8155/حكم-تقسيم-البدعة-الى-خمسة-اقسام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27501.mp3","categories":["البدع والمحدثات"]},{"id":10008,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مصر باعثها مستمع يقول: المرسل أخوكم في الله أسامة عبده، الأخ أسامة يسأل ويقول: بعد الفراغ من الصلاة على الميت يقوم بعض الأشخاص بحمل الجنازة إلى المقبرة ويرددون بصوت جماعي كلمة التوحيد، ويستمر هذا الوضع حتى تصل الجنازة إلى المقبرة، فهل هذا العمل صحيح، جزاكم الله خيرًا؟","title":"حكم رفع الصوت أثناء الجنازة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: هذا العمل ليس مشروعاً بل هو بدعة، كونهم يرفعون أصواتهم بالتوحيد حتى تنتهي الجنازة، كل هذا منكر، ولكن الإنسان في نفسه يفكر وينظر، يتذكر أن مصيره هو هذا المصير الموت، وأن هناك حسابًا وجزاء فيتأمل ويتذكر ويعد العدة لهذا الموقف، أما رفع الصوت بالذكر، أو وحدوه، أو غير ذلك من الأذكار بصوت جماعي حتى تنتهي الجنازة إلى المقبرة هذا ليس له أصل، بل هو من البدع، وقد قال عليه الصلاة والسلام في الحديث الصحيح: من عمل عملًا ليس علينا أمرنا فهو رد يعني: فهو مردود، ولم يثبت عنه ﷺ ولا عن الصحابة أنهم كانوا يفعلون هذا الفعل فصار أمرًا محدثًا ومردودًا.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم!","link":"https://binbaz.org.sa/fatwas/8179/حكم-رفع-الصوت-اثناء-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27601.mp3","categories":["البدع والمحدثات"]},{"id":10013,"question":"أيضًا في باب الجنائز يسأل سماحتكم يحفظكم الله ويقول: بعد دفن الجنازة يذهب أهل الميت لإحضار مقرئ يتلو القرآن الكريم لمدة ثلاثة أيام، وبعد خمسة عشر يومًا من الوفاة يذهب ذوو المتوفى إلى المقبرة وهم يحملون الخبز ويتصدقوا به، فهل هذا العمل صحيح ومشروع، جزاكم الله خيرًا؟","title":"حكم قراءة القرآن في مأتم بعد الوفاة لبضعة أيام","answer":"الجواب: وهكذا ليس مشروعًا فالقراءة على الميت أسبوع ولا يوم ولا أكثر كل هذا من البدع، ولكن يدعى له، يدعى للميت بالمغفرة والرحمة، ويتصدق عنه بما يتيسر في كل وقت ولو بعد موته بسنوات، الصدقة تنفع الميت، والدعاء ينفع الميت، الحج عنه والعمرة كذلك، قضاء دينه كل هذا ينفعه، أما إحضار مقرئ يقرأ أسبوع أو أقل أو أكثر أو عند قبره أو في بيته كل هذا لا أصل له.\nفالواجب تركه لأن الله جل وعلا لم يشرعه، ولو شرعه لبينه الرسول ﷺ وبينه أصحاب النبي عليه الصلاة والسلام، والواجب على أهل الإسلام الاتباع وعدم الابتداع. نعم.\nكذلك الذهاب إلى القبور والصدقة بالطعام أو بالخبز يوزع عند القبور لا أصل له، كل هذا من البدع، فالذهاب إلى القبور؛ تزار القبور للدعاء لهم والترحم عليهم، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وكان إذا زارها يقول ﷺ كذلك: يرحم الله المستقدمين منا والمستأخرين، هكذا السنة، أما زيارتها لتوزيع خبز أو لحوم هذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ حتى ينتهي الناس عن هذه المخالفات في العزاء أو في غيره ما هي كلمتكم يحفظكم الله؟\nالشيخ: الواجب على المسلمين جميعاً أن يتقيدوا بالشرع في كل شيء في الجنائز وغير الجنائز، في صلاة الجنازة وغيرها، في جميع العبادات، لأن الله جل وعلا يقول ذاماً لقوم أحدثوا: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، ويقول جل وعلا: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا [الجاثية:18]، ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، فليس للناس أن يحدثوا عبادات في شرع الله ما أنزل الله بها من سلطان، لا في أمر الجنائز ولا في غير الجنائز، جميع البدع ينهى عنها، والإنسان يتقيد بالشرع، يسأل عما شرع الله يتفقه في الدين، ويسأل عما شرعه الله ويعمل بذلك، كما قال ﷺ: من يرد الله به خيرًا يفقهه في الدين، فالتفقه في الدين مطلوب ويعمل الإنسان بما علم من شرع الله .\nأما كون التعزية مشروعة كونه يزور أخاه يعزيه في البيت أو في الطريق أو في المسجد أو في الدكان أو في المزرعة لا بأس يزوره إخوانه يعزونه بأبيه في أخيه في أمه لا بأس، أما أن يتخذ لذلك طعام -يصنع طعام لهم- أو يتخذ قراء يقرءون للميت أو أشياء أخرى تفعل من أجل الميت عند الموت أو على رأس الأسبوع أو بعد أربعين يوم، أو على رأس السنة، كل هذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8182/حكم-قراءة-القران-في-ماتم-بعد-الوفاة-لبضعة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27602.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":10041,"question":"هل يجوز للمصلي أن يغير من نيته في الصلاة، وأن يحولها إلى صلاة أخرى سواءً كان ذلك في صلاة فرض أو نافلة؟","title":"حكم تغيير النية داخل الصلاة في الفريضة أو النافلة","answer":"الجواب: هذا فيه تفصيل: إذا دخل الفريضة ليس له أن يحول إلى فريضة أخرى، وليس له أن يحول إذا دخل في راتبة الظهر إلى شيء آخر إلى فريضة أو راتبة الفجر أو نحو ذلك، لأنه متى دخل في صلاة بنية؛ يكمّلها، إلا إذا كان هناك مصلحة كأن يدخل في الفريضة وحده ثم يأتي جماعة قد فاتتهم الفريضة؛ فيقلبها نافلة ويسلم، ويصلي معهم الفرض ليدرك فضل الجماعة؛ فهذا تغيير للمصلحة الشرعية. أو يدخل في النافلة[1] يحسب أنهم قد صلوا، ثم يبين أنهم لم يصلوا؛ فيقلبها نافلة ويصلي معهم الفريضة، فإذا كان لهذه المصلحة فإن قَلْبَها مطلوب؛ حتى يدرك الجماعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8209/حكم-تغيير-النية-داخل-الصلاة-في-الفريضة-او-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33209.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":10045,"question":"أولى رسائل هذه الحلقة رسالة المستمع علي حاج محمد من غلمسكو في أثيوبيا، عرضنا بعض أسئلته في حلقة مضت وفي هذه الحلقة يسأل ويقول: إذا انقطع المطر عن البلد يأخذ الفلاحون أصول الخشب اليابس على ظهورهم ويأتون به إلى بيت الحضرة التي يزورونها وهم يرتجزون به، فغالبًا ما يمطرون إثر مجيئهم بهذه الصفة أو يذبحون الشياه الأحمر أو الأسود ويضعون قوائمها أو فرسنها على شجرة يجتمعون تحتها فيأتي طائر كبير من جهة القبلة فيأخذها ويأكلها فيمطرون، فربما لا يأكلها ولا يمطرون فيذبحون أخرى بزعم أنها لم تقبل منهم الأولى، ما رأيكم في هذا جزاكم الله خيرًا؟","title":"بدع الاستسقاء وبيان السنة في طلب السقيا","answer":"الجواب: هذا من البدع لا يجوز .. بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه.\nأما بعد: فهذا من البدع التي لا أصل لها في الشرع وإنما المشروع أن يستغيث المسلمون إذا أجدبوا وأن يدعوا الله  ليسقيهم، تارة في المساجد وتارة في البيوت وتارة بعد خطبة الجمعة، في أثناء خطبة الجمعة يدعو الإمام خطباء المساجد يستغيثون الله  وتارة يخرج أمير وقاضي البلد وأهل البلد إلى المصلى من خارج البلد ويصلي ركعتين ويستغيث بالمسلمين إمامهم سواء كان القاضي أو غيره ويسأل الله الغوث كما فعل النبي ﷺ، فإنه كان ربما استغاث في خطبة الجمعة عليه الصلاة والسلام وربما خرج إلى المصلى وصلى ركعتين وخطب بالناس واستغاث لهم، هذا هو المشروع وربما استغاث في غير صلاة كما وقع في بعض الأحيان في المدينة استغاث لهم في مجلسه عليه الصلاة والسلام ولا مانع أن يستغيث الإنسان في بيته ويدعو الله للمسلمين أو وهو في الطريق يسأل الله أن يغيث المسلمين، كل ذلك لا بأس به، أما أن يأخذ خشب أو أشياء خاصة يحملها أو يذهب إلى حضرة إنسان معين كأمير البلد أو قاضي البلد ويرتجزون، هذا لا أصل له، هذا من البدع والخرافات التي أحدثها الناس أو يذبحون ذبائح يجعلون بعضها عند بعض الشجر أو عند بعض الجبال أو ما أشبه ذلك كلها هذا لا أصل له، لكن يشرع الصدقة كونهم يتصدقون على الفقراء قبل الاستغاثة أو بعدها يعني يتصدق أهل الغنى منهم للفقراء والمساكين بالنقود بالطعام بالملابس هذا طيب ومن أسباب الرحمة، يقول الرسول ﷺ: من لا يرحم لا يرحم، والصدقة تطفئ الخطيئة، والصدقة من أسباب الفرج ومن أسباب الإحسان، كما قال : وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ [البقرة:195]، قال سبحانه: إِنَّ رَحْمَةَ اللَّهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ [الأعراف:56]، فإذا تصدق الموسرون على الفقراء وواسوهم قبل الاستغاثة أو بعدها فكل هذا طيب، ومن أسباب الغيث.\nوهكذا الدعاء والاستغفار والتوبة إلى الله والصدق في ذلك والبكاء من خشيته جل وعلا والإكثار من العبادات والطاعات والحذر من المعاصي، كل هذا من أسباب الغوث، أما أن يحدثوا شيئًا ما شرعه الله من حملهم الأخشاب المعينة أو أشجار معينة أو ذبائح تفعل على وجه معين تجعل رءوسها أو أشياء منها في مكان معين عند بعض الشجر حتى يجيء طائر يأخذها أو عند بعض الجبال أو بالذهاب إلى بعض المشايخ أو غير ذلك، كل هذا لا أصل له بل هو من البدع والخرافات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8214/بدع-الاستسقاء-وبيان-السنة-في-طلب-السقيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33301.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":10065,"question":"يسأل أيضًا ويقول: ما تقولون في قوم يجتمعون في بيت حضرتهم أو تحت الشجرة باسم من مات قبل قرون أو ما رأوها هم ولا آباؤهم وإنما سموها هم وآباؤهم عبدالقادر الجيلاني وشيخ حسين البالي وفلان وفلان وإن أنكر عليهم منكر لا يقبلون عنه بحجة أن العالم الفلاني لم ينكر عليهم، وأن الكافرين الذين هم في زمن للرسول ﷺ كفروا بعدم إيمانهم بالرسول ونحن نؤمن به وبما جاء به عليه السلام، فما تقولون في هذا أيضًا، جزاكم الله خيرًا؟","title":"حكم الاجتماع باسم من مات من الأولياء للدعاء والذكر","answer":"الجواب: هذا الاجتماع باسم الشيخ عبدالقادر أو باسم الشيخ حسين وفلان أو باسم البدوي أو باسم الحسين بن علي أو باسم علي بن أبي طالب أو باسم عمر أو باسم الصديق أو بأسماء أخرى أو باسم حضرتهم، كلمة حضرتهم هذه كلمة مجملة لا نعرف معناها، فإذا كان المقصود رئيس الجماعة أو عالم الجماعة أو ما أشبه ذلك، فكل هذا من البدع لا أصل لهذا كونه يجتمعون باسم الشيخ عبدالقادر يدعون له أو يصلون عليه أو يتوسلون به هذا لا أصل له ما كان الرسول ﷺ يفعل هذا وأصحابه، إنما الدعاء للمسلمين لا بأس يدعو لعلماء المسلمين وإن كانوا ماتوا قديمًا كما تدعو للصحابة وغيرهم تقول: اللهم ارض عنهم، اللهم اغفر لأموات المسلمين، اللهم اغفر للشيخ عبدالقادر، اللهم اغفر للحسين بن علي، اللهم ارض عنه وعن إخوانه، لا بأس كل هذا طيب لكن تجتمع عند شجرة أو عند جبل أو عند الشيخ فلان من أجل الاجتماع للدعاء لفلان أو الترضي عن فلان هذا لا أصل له كونه يخص باجتماع على هذا الوجه، هذا من البدع تدعو له وأنت في الطريق وأنت في المجلس العادي وأنت في بيتك لا بأس تدعو لعلماء المسلمين للشيخ عبدالقادر الجيلاني ، الشيخ عبدالقادر عالم من علماء المسلمين تدعو لـأبي حنيفة تدعو لـمالك ، للشافعي ، لـأحمد بن حنبل ، لـسفيان الثوري ، لأصحاب النبي ﷺ، للتابعين، لغيرهم من المؤمنين لا بأس، لكن تخص واحدًا منهم باجتماع خاص عند شجرة خاصة أو عند جبل خاص أو عند شخص خاص تخصه بهذا الاجتماع في يوم معين أو في شهر معين أو في أسبوع، كل هذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8220/حكم-الاجتماع-باسم-من-مات-من-الاولياء-للدعاء-والذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33302.mp3","categories":["البدع والمحدثات"]},{"id":10164,"question":"يقول: تنتشر عادة في بلدي وهي عند افتراق شخصين للسفر وخلافه، فإنهما يجعلان آخر حديثهما بأن ينطق أحدهما بشهادة: لا إله إلا الله، ويرد عليه الآخر بالنصف الباقي: محمد رسول الله، ظناً منهما أن الله سوف يجمع بهما مرة أخرى، ويفعلون هذا على سبيل التفاؤل أو التبرك بالشهادتين، وأخبرني أحد الإخوة هنا أن هذا الأمر من البدع ويجب تركه، حيث أنه لم يرد عن الرسول ﷺ أو عن أحد من الصحابة والتابعين، وجهونا يحفظكم الله ما هو رأيكم جزاكم الله خيرا؟","title":"حكم قول الشهادتين عند الافتراق وجعلها آخر حديثهما","answer":"الجواب: نعم هذا من البدع لا يصلح، هذا العمل كونه عند الفراق هذا يقرأ شهادة: أن لا إله إلا الله، والثاني يقرأ: شهادة أن محمدًا رسول الله، هذا لا أصل له، ولا يشرع بل هو من البدع المحدثة، عند التفرق كل واحد يقول: في أمان الله أو ما أشبه هذا، عافاك الله، أو في أمان الله، أو في حفظ الله، أو ما أشبهه، أو أستودع الله دينك أو ما أشبه ذلك، نعم، أما أن يقتسما الشهادتين هذا لا أصل له.\nالمقدم: جزاكم الله خيرا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8335/حكم-قول-الشهادتين-عند-الافتراق-وجعلها-اخر-حديثهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27715.mp3","categories":["البدع والمحدثات"]},{"id":10180,"question":"يتحدث عما يحدثه قومه من بدع في العزاء فيقول مثلاً: هل يجوز عند وفاة الميت بعد دفنه تفرقة التمر على من حضر، وقراءة القرآن على القبر، هل ذلك من السنة؟ وذلك بعد موته يقرءون القرآن أيضاً ثلاثة أيام في المسجد في الصباح وفي المساء، وآخر الثلاثة الأيام يفرقون تمر على الذين حاضرين في المسجد مع شرب القهوة، ويقول أهل الميت: هذه صدقة! أفتونا مأجورين عن ذلك، ثم إنهم بعد ثلاثين يوماً أيضاً يقرءون القرآن مع تفرقة التمر والقهوة.","title":"من بدع العزاء","answer":"الجواب: كل هذا بدعة لا أصل له، لا التمر ولا غير التمر، وهي أن يتخذ عادة عند القبر أو في ثلاثة أيام أو بعد عشرين يوم أو بعد شهر أو بعد سنة تفريق تمر أو دراهم أو خبز أو غير ذلك كل هذا من البدع، السنة بعد الدفن أن يوقف عليه ويدعى له، إذا فرغوا من دفنه دعوا له بالمغفرة والثبات ثم انصرفوا، ويعزيهم الناس يعزونهم في الطريق في المقبرة في المسجد في البيت ما في.. تعزية، وإذا جاء المعزي وصبوا له قهوة أو صبوا له شاهي ما يخالف ما يضر، أما أن يتعمد تقسيم تمر أو توزيع خبز أو توزيع لحم في أيام معلومة يوم الموت أو ثلاثة أيام أو على رأس الشهر أو على رأس السنة كل هذا من البدع لا أصل له، وهكذا قراءة القرآن عند القبر أو ثلاثة أيام أو شهر أو أقل أو أكثر للميت كل هذا بدعة لا أصل له، على الناس أن يتقيدوا بما شرع الله، والرسول ﷺ يقول: من عمل عملاً ليس عليه أمرنا فهو رد ولم يكن ﷺ ولا أصحابه إذا مات الميت يقرءون عنده القرآن أو يجتمعون في البيت يقرءون ثلاثة أيام أو أربعة أيام أو عشرة أو أقل أو أكثر، ولم يكونوا يوزعون تمور ولا يوزعون خبز ولا يوزعون حلاوى ولا غير ذلك، الميت إذا مات يعزى أهله ويدعى لهم بالمغفرة يقال: أحسن الله عزاءكم، جبر الله مصيبتكم، في البيت في الطريق في المسجد في محل البيع والشراء في أي مكان، وإذا زاروهم في البيت وصبوا لهم قهوة أو شاهي أو طيبوهم كل هذا طيب، أما أن يتخذ عادة متبعة ثلاثة أيام أو عشرة أيام أو على رأس الشهر أو على رأس السنة ..... فيها توزيع تمر أو توزيع لحوم أو قراءة قرآن هذا لا أصل له، بل هو من البدع. نعم.","link":"https://binbaz.org.sa/fatwas/8353/من-بدع-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30814.mp3","categories":["البدع والمحدثات"]},{"id":10182,"question":"يقول: إنني أنوي للوضوء بحيث أقول بدون تلفظ: اللهم! نويت الوضوء في هذا الماء الطاهر للطهارة للصلاة، وعند الصلاة أنوي بدون تلفظ، أيضاً: نويت أن أصلي صلاة الظهر مثلاً حاضراً لله تعالى، وسؤالي هنا: هل النية صحيحة في هذا؟ وهل التلفظ جائز أو لا؟","title":"محل النية وحكم التلفظ بها","answer":"الجواب: النية لابد منها في العبادات كلها لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى، فالنية بالقلب في الصلاة في الحج في الصيام في جميع العبادات في الصدقة إلى غير ذلك، لكن التلفظ غير مشروع، كونه يقول نويت بلسانه يتكلم: نويت أن أصلي الظهر كذا العصر كذا المغرب كذا هذا غير مشروع ولم يفعله النبي ﷺ ولا أصحابه ولا السلف الصالح، وإنما النية بالقلب، فما يفعله بعض الناس يقول: نويت أن أتوضأ كذا، نويت أن أصلي الظهر أربع ركعات إماماً أو مأموماً.. إلى آخره؛ كل هذا لا أصل له بل هو من البدع، وإنما النية تكون بالقلب لا باللسان. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8343/محل-النية-وحكم-التلفظ-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30804.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":10243,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأردن، باعثها المستمع أيمن عبدالرحمن، الأخ أيمن يقول: هل يجوز التسبيح بعد الصلاة بصورة جماعية، جزاكم الله خيرًا؟","title":"حكم التسبيح عقب الصلاة بصوت جماعي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالتسبيح بعد الصلاة بصورة جماعية بدعة لا يجوز، وإنما السنة أن يسبح كل واحد لنفسه بعد الصلاة، فإذا سلم يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، سواء كان إمامًا أو مأمومًا أو منفردًا، في جميع الصلوات الخمس، ثم يقول بعد هذا: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، مرة أو ثلاثًا في جميع الصلوات الخمس، لكن في الفجر والمغرب يزيد في ذلك عشر مرات لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير، عشر مرات، زيادة في الفجر والمغرب، أما في الظهر والعصر والعشاء فيقول ذلك مرة واحدة أو ثلاثاً، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، ويستحب أن يقول -بعد هذا- سبحان الله والحمد لله، والله أكبر، ثلاثة وثلاثين مرة، ثم يقول بعدها: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، ثم يقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]، ثم يقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] و قُلْ أَعُوذُ بِرَبِّ النَّاسِِ [الناس:1] مرة واحدة بعد الظهر والعصر والعشاء، أما بعد المغرب والفجر فيكررها ثلاثاً، يكرر السور الثلاث ثلاث مرات، قُلْ هُوَ اللَّهُ أَحَدٌقُلْ أَعُوذُ بِرَبِّ الْفَلَقِقُلْ أَعُوذُ بِرَبِّ النَّاسِ بعد الفجر والمغرب، لورود الأحاديث بذلك عن النبي عليه الصلاة والسلام، أما الإتيان بذلك على صفة جماعية، فهذا بدعة. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8413/حكم-التسبيح-عقب-الصلاة-بصوت-جماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27901.mp3","categories":["البدع والمحدثات"]},{"id":10274,"question":"من سلطنة عمان، رسالة بعث بها أحد الإخوة المستمعين هو علي عبد الجليل محمد ، يقول في أحد أسئلته: عندما تقام الصلاة في الظهر مثلاً والعصر يجهر الإمام بصوت مرتفع قبل بدء الصلاة بالدعاء، وكذلك المصلون يدعون خلفه، وعند بدء الصلاة في بعض الأحيان يجهر الإمام أثناء سجوده وفي التشهدين، فما حكم ذلك، جزاكم الله خيراً؟","title":"حكم الجهر بالدعاء قبل الإقامة وفي السجود والتشهد","answer":"الجواب: أما جهره بالدعاء قبل الصلاة ما نعلم له أصلا، وإنما يشرع الدعاء بالاستفتاح بعد الإحرام، إذا كبر للإحرام يأتي بالاستفتاح سراً بينه وبين ربه، يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا نوع من الاستفتاح، الإمام والمنفرد والمأموم بعد التكبيرة الأولى وقبل القراءة، أو يأتي باستفتاحٍ آخر، صح عن النبي ﷺ وهو قوله : اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا أيضاً صحيح، وهناك أنواع من الاستفتاحات صحيحة، إذا أتى بواحدٍ منها، حصلت به السنة.\nأما دعوات قبل ذلك قبل أن يكبر، يرفع بها صوته هو والمأمومون، لا نعلم لهذا أصلاً، بل هو بدعة.\nوهكذا ما يفعله بعد ذلك.\nالسؤال الأخير بعد ..... ؟\nالمقدم: يقول: إنه في بعض الأحيان يجهر الإمام أثناء سجوده في التشهدين؟\nالشيخ: وهكذا كونه يجهر بالدعاء أثناء سجوده غير مشروع هذا، بل يدعو بينه وبين ربه، ولا يجهر، وهكذا المأموم، الدعاء في السجود مستحب، يقول النبي ﷺ : أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ويقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم لكن يكون بينه وبين ربه، لا يجهر جهراً يؤذي من حوله، يشوش على من حوله، المأموم والإمام لا يجهروا، وهكذا المنفرد، الدعاء سر في السجود.\nأما جهر يسير الذي قد يسمعه من حوله لا يضر، لكن الأفضل له أن لا يؤذي من حوله، ولا يشوش على من حوله، إذا كان مأموماً يكون دعاؤه بينه وبين ربه، لا جهر في شيئاً جهراً يشوش على من حوله، هذا هو المشروع. نعم.\nالمقدم: جزاكم الله خيراً، أيضاً يقول: إنه يجهر حتى في التشهدين؟\nالشيخ: كذلك لا يشرع له ذلك، يقرأ التشهدين سراً، ما فيه جهر، هكذا السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8455/حكم-الجهر-بالدعاء-قبل-الاقامة-وفي-السجود-والتشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31111.mp3","categories":["البدع والمحدثات"]},{"id":10284,"question":"من سلطنة عمان، رسالة بعث بها أحد الإخوة المستمعين هو علي عبد الجليل محمد ، يقول في أحد أسئلته: عندما تقام الصلاة في الظهر مثلاً والعصر يجهر الإمام بصوت مرتفع قبل بدء الصلاة بالدعاء، وكذلك المصلون يدعون خلفه، وعند بدء الصلاة في بعض الأحيان يجهر الإمام أثناء سجوده وفي التشهدين، فما حكم ذلك، جزاكم الله خيراً؟","title":"حكم الجهر بالدعاء قبل الإقامة وفي السجود والتشهد","answer":"الجواب: أما جهره بالدعاء قبل الصلاة ما نعلم له أصلا، وإنما يشرع الدعاء بالاستفتاح بعد الإحرام، إذا كبر للإحرام يأتي بالاستفتاح سراً بينه وبين ربه، يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا نوع من الاستفتاح، الإمام والمنفرد والمأموم بعد التكبيرة الأولى وقبل القراءة، أو يأتي باستفتاحٍ آخر، صح عن النبي ﷺ وهو قوله : اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا أيضاً صحيح، وهناك أنواع من الاستفتاحات صحيحة، إذا أتى بواحدٍ منها، حصلت به السنة.\nأما دعوات قبل ذلك قبل أن يكبر، يرفع بها صوته هو والمأمومون، لا نعلم لهذا أصلاً، بل هو بدعة.\nوهكذا ما يفعله بعد ذلك.\nالسؤال الأخير بعد ..... ؟\nالمقدم: يقول: إنه في بعض الأحيان يجهر الإمام أثناء سجوده في التشهدين؟\nالشيخ: وهكذا كونه يجهر بالدعاء أثناء سجوده غير مشروع هذا، بل يدعو بينه وبين ربه، ولا يجهر، وهكذا المأموم، الدعاء في السجود مستحب، يقول النبي ﷺ : أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ويقول ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم لكن يكون بينه وبين ربه، لا يجهر جهراً يؤذي من حوله، يشوش على من حوله، المأموم والإمام لا يجهروا، وهكذا المنفرد، الدعاء سر في السجود.\nأما جهر يسير الذي قد يسمعه من حوله لا يضر، لكن الأفضل له أن لا يؤذي من حوله، ولا يشوش على من حوله، إذا كان مأموماً يكون دعاؤه بينه وبين ربه، لا جهر في شيئاً جهراً يشوش على من حوله، هذا هو المشروع. نعم.\nالمقدم: جزاكم الله خيراً، أيضاً يقول: إنه يجهر حتى في التشهدين؟\nالشيخ: كذلك لا يشرع له ذلك، يقرأ التشهدين سراً، ما فيه جهر، هكذا السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8455/حكم-الجهر-بالدعاء-قبل-الاقامة-وفي-السجود-والتشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31111.mp3","categories":["البدع والمحدثات"]},{"id":10636,"question":"سؤال آخر فحواه السؤال عن بدع العزاء، كاستحداث الصواوين والعزائم والقراءة، ويسأل عنها أخونا أيضاً لو تكرمتم توجهونه، ويقول: إن هذه النفقات تنفق كلها من تركة الميت، وربما يكون الورثة في أمس الحاجة إليها؟","title":"حكم إقامة المآتم عند العزاء","answer":"الجواب: لا يجوز لأهل الميت إقامة عزاء، يعني: إقامة مأتم بإيجاد الطعام، ودعوة الناس للأكل ونحو ذلك على حساب الميت، أو على حساب أيتام الميت، أو على حسابهم هم كل ذلك لا يجوز لأنها من أمر الجاهلية، ولكن يصبرون ويحتسبون.. إنا لله وإنا إليه راجعون، ويستقبلون المعزين لا بأس يستقبلونهم، يصبون لهم قهوة يصبون لهم شاي لا بأس.\nأما أن يقيموا مأتم بالبكاء والنياحة أو بصنع الطعام للناس هذا لا يجوز، بل هو من أمر الجاهلية، وإذا كان بيتهم صغير وجعلوا مكان أوسع لاستقبال المعزين من دون إحداث مأتم ولا شيء، بل مجرد إحداث خيمة أو صالون يسع المعزين فلا حرج في ذلك، إذا كان ليس فيه بدعة، لا مأتم ولا إحداث نياحة ولا شيء مما حرم الله، إنما هو مجرد استقبال وسلام عليهم وصب القهوة والشاي هذا لا يضر، ولا حرج في ذلك إن شاء الله، عند ضيق المكان.\nالمقدم: عند ضيق المكان؟\nالشيخ: نعم.\nالمقدم: لكن إذا أتوا بالقراء وما أشبه ذلك؟\nالشيخ: هذا ما يجوز، هذا بدعة، .... بالقراء أو بصنع الطعام هذا بدعة. نعم، لكن لو جاءهم ضيوف واستحوا أن يتركونهم وصنعوا لهم طعاماً؛ لأنهم ضيوف جاءوا من مكان بعيد فلا بأس، أو دعوهم إلى ما عندهم من الطعام المهدى إليهم، فإن السنة أنه يهدى إلى أهل الميت طعام من جيرانهم وأقاربهم، فإذا وافقه الضيوف وأكلوا معهم فلا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8812/حكم-اقامة-الماتم-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32814.mp3","categories":["البدع والمحدثات"]},{"id":10639,"question":"سؤال آخر فحواه السؤال عن بدع العزاء، كاستحداث الصواوين والعزائم والقراءة، ويسأل عنها أخونا أيضاً لو تكرمتم توجهونه، ويقول: إن هذه النفقات تنفق كلها من تركة الميت، وربما يكون الورثة في أمس الحاجة إليها؟","title":"حكم إقامة المآتم عند العزاء","answer":"الجواب: لا يجوز لأهل الميت إقامة عزاء، يعني: إقامة مأتم بإيجاد الطعام، ودعوة الناس للأكل ونحو ذلك على حساب الميت، أو على حساب أيتام الميت، أو على حسابهم هم كل ذلك لا يجوز لأنها من أمر الجاهلية، ولكن يصبرون ويحتسبون.. إنا لله وإنا إليه راجعون، ويستقبلون المعزين لا بأس يستقبلونهم، يصبون لهم قهوة يصبون لهم شاي لا بأس.\nأما أن يقيموا مأتم بالبكاء والنياحة أو بصنع الطعام للناس هذا لا يجوز، بل هو من أمر الجاهلية، وإذا كان بيتهم صغير وجعلوا مكان أوسع لاستقبال المعزين من دون إحداث مأتم ولا شيء، بل مجرد إحداث خيمة أو صالون يسع المعزين فلا حرج في ذلك، إذا كان ليس فيه بدعة، لا مأتم ولا إحداث نياحة ولا شيء مما حرم الله، إنما هو مجرد استقبال وسلام عليهم وصب القهوة والشاي هذا لا يضر، ولا حرج في ذلك إن شاء الله، عند ضيق المكان.\nالمقدم: عند ضيق المكان؟\nالشيخ: نعم.\nالمقدم: لكن إذا أتوا بالقراء وما أشبه ذلك؟\nالشيخ: هذا ما يجوز، هذا بدعة، .... بالقراء أو بصنع الطعام هذا بدعة. نعم، لكن لو جاءهم ضيوف واستحوا أن يتركونهم وصنعوا لهم طعاماً؛ لأنهم ضيوف جاءوا من مكان بعيد فلا بأس، أو دعوهم إلى ما عندهم من الطعام المهدى إليهم، فإن السنة أنه يهدى إلى أهل الميت طعام من جيرانهم وأقاربهم، فإذا وافقه الضيوف وأكلوا معهم فلا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8812/حكم-اقامة-الماتم-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32814.mp3","categories":["البدع والمحدثات"]},{"id":10710,"question":"أيضاً يقول: إن هناك بعض الأدعية تعلق على الميت، وتعلق في عنقه بالذات لتكون في قبره مذكرة ومعينة على سؤال منكر ونكير، ما حكم مثل هذا؟","title":"حكم تعليق الأدعية في عنق الميت","answer":"الجواب: هذا أيضاً لا أصل له، بل منكر وبدعة، إن مات على استقامة لقنه الله وأجاب منكر ونكير وإن مات على غير الاستقامة ما نفعته هذه الأشياء التي معه، إنما هو تثبيت الله جل وعلا، من ثبته الله بالقول الثابت أجاب، ومن لم يثبت لم يجب، إذا مات على هدى واستقامة أجاب قال: (ربي الله، والإسلام ديني، ومحمد نبيي، وإذا مات على غير هدى، قال: هاه هاه لا أدري، سمعت الناس يقولون شيئاً فقلته، فيضرب بمرزبة من حديد فيصيح صيحة يسمعها كل شيء إلا الإنسان) فليست التعليقات التي تعلق عليه نافعة له، ولا قيمة لها، بل هذا من البدع التي أحدثها الناس، والله المستعان. \nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8888/حكم-تعليق-الادعية-في-عنق-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34303.mp3","categories":["البدع والمحدثات"]},{"id":10712,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول فيه: هل تجوز قراءة القرآن عند قبر الميت، وما هو الوارد شرعاً؟","title":"حكم قراءة القرآن عند قبور الموتى وإهداء ثوابها لهم","answer":"الجواب: وهكذا قراءة القرآن عند القبور لا أصل لها بل من البدع، فلم يشرع الله لنا القراءة عند القبور، ولا الصلاة عند القبور، قال عليه الصلاة والسلام: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبوراً، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة، فدل على أن القبور ما هي بمحل صلاة ولا محل قراءة، القبور تزار للذكرى والعظة، والدعاء للأموات بالمغفرة والرحمة، الرسول ﷺ قال: زوروا القبور؛ فإنها تذكركم الآخرة، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة: يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر، فالزيارة للعظة والذكرى والإحسان للموتى بالدعاء لهم، والترحم عليهم والاستغفار لهم، أما القراءة عند قبورهم ما تفيدهم، انقطعت أعمالهم، يفيدهم الدعاء لهم والصدقة عنهم والحج عنهم، والعمرة عنهم، وقضاء ديونهم هذا الذي ينفعهم، أما القراءة عند قبورهم فلا تشرع بل هي بدعة، حتى القراءة لهم وتثويبها لهم ليس عليه دليل، الصواب أنه لا يشرع أيضاً حتى تثويب القراءة لهم، بعض الناس قد يقرأ ويجعل القراءة لأبيه أو أمه الميت، لا، هذا لا دليل عليه تركه أولى.\nوهكذا الصلاة عنهم، لا يصلى عنهم، ما ورد هذا في الشرع، إنما يدعى لهم، يترحم عليهم، يتصدق عنهم، يحج عنهم، يعتمر لا بأس، أجمع المسلمون على أن الصدقة تنفع الميت والدعاء كذلك، أما كونه يقرأ في المقبرة، أو يصلي في المقبرة هذا من البدع، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8889/حكم-قراءة-القران-عند-قبور-الموتى-واهداء-ثوابها-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34304.mp3","categories":["البدع والمحدثات"]},{"id":10719,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع أحمد عز الدين حزام العماد من اليمن الشمالي قرية العسادي وصاب العالي، أخونا أحمد عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: هل شرع الرسول ﷺ بعد إكمال الأذان أن يقول المؤذن بصوت عالٍ كالأذان: الحمد لله رب العالمين، إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، هل يجوز مثل هذا العمل، جزاكم الله خيرًا؟","title":"حكم قول المؤذن: (إن الله وملائكته يصلون على النبي...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا العمل الذي ذكره السائل منكر بدعة، ليس للمؤذن أن يقول بعد الأذان: الحمد لله مع صوت الأذان في المكبر، أو صلوا على رسول الله، أو يقرأ الآية، كل هذا بدعة، بل متى قال: لا إله إلا الله فإنه يقفل المكبر، ولا يزيد شيئًا، وإذا كان بغير مكبر كذلك لا يزيد شيئًا، لا يبتدع، آخر الآذان (لا إله إلا الله)، هذا آخر الآذان، فمن زاد معها شيء الصلاة على النبي ﷺ أو حمداً لله فقد ابتدع، ولكن يشرع له بعد ذلك من غير رفع صوت مع الأذان، ولا بغير رفع صوت مع المكبر يشرع له أن يصلي على النبي صلى الله عليه وسلم بينه وبين نفسه، ولو سمعه من حوله، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد يشرع له أن يقول هذا المؤذن، وهكذا الناس الذين سمعوا الأذان يستحب لهم أن يجيبوه، يعني: يقولون مثل قول المؤذن إلا في الحيعلة يقول: لا حول ولا قوة إلا بالله، فإذا قال في آخر الأذان: لا إله إلا الله صلى على النبي ﷺ صلاة خفية ليست مع الأذان، بل يصلي على النبي ﷺ مثل ما يصلي غيره، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد .... فالمستمع يقول والمؤذن يقول، وليس لواحد منهم أن يجعلها مع الأذان لا المؤذن ولا غير المؤذن، بل الأذان ينتهي عند قول: لا إله إلا الله، انتهى، فمن أراد أن يصلي على النبي ﷺ يكون بصوت خفي ليس من جنس صوت الأذان، ولا مع الأذان، ولا في مكبر مع الأذان، بل يكون بينه وبين نفسه، أو يسمعه من حوله لا بأس؛ لأن الرسول ﷺ قال: إذا سمعتم المؤذن فقولوا مثل ما يقول ثم صلوا علي، فإنه من صلى علي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة، هذا فضل من الله جل وعلا.\nوقال أيضاً عليه الصلاة والسلام: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة وابعثه مقاماً محموداً الذي وعدته، حلت له شفاعتي يوم القيامة، وهذا فضل من الله جل وعلا، فيشرع للمؤمن والمؤمنة إذا سمع الأذان أن يقول مثل قول المؤذن كل منهما، الرجل والمرأة، إذا قال: الله أكبر، يقول: الله أكبر، قال: أشهد أن لا إله إلا الله، يقول: أشهد أن لا إله إلا الله، إذا قال: أشهد أن محمداً رسول الله يقول: أشهد أن محمداً رسول الله، إذا قال: حي على الصلاة، يقول: لا حول ولا قوة إلا بالله، حي على الفلاح يقول: لا حول ولا قوة إلا بالله، هذا مستثنى لا يقول مثل المؤذن، بل يقول: لا حول ولا قوة إلا بالله، كما أرشد إليه النبي عليه الصلاة والسلام، فإذا قال: الله أكبر الله أكبر، قال: الله أكبر الله أكبر، فإذا قال: لا إله إلا الله، يقول: لا إله إلا الله، ثم يصلي على النبي ﷺ، يصلي على النبي ﷺ، صلاة ليست مع الأذان بل منفصلة عن الأذان، يخفضها ويقفل المكبر سواء كان مؤذناً وهكذا غير المؤذن لا يرفعها رفعاً زائداً كالأذان، بل يأتي بها بصوت عادي، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة والقائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد هذا رواه البخاري في الصحيح، عن جابر إلا بعض كلمات إنك لا تخلف الميعاد فهذه زيادة رواها البيهقي بإسناد حسن.\nولما قيل للرسول ﷺ: يا رسول الله! المؤذنين يغبنوننا، قال: قولوا مثل ما يقولون، ثم صلوا علي فإن من صلى علي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة، هذا خير عظيم وفضل كبير ينبغي لكل مؤمن ولكل مؤمنة عدم التفريط في ذلك بل يحرص عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8886/حكم-قول-الموذن-ان-الله-وملاىكته-يصلون-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34301.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":10722,"question":"أيضاً ما يفعله بعض الناس يقول: إذا سلم الإمام من الصلاة أتى بذكر جماعي هو والمأمومون، يختم الذكر بالفاتحة إلى روح النبي ﷺ، ما رأي سماحتكم في هذا؟","title":"حكم الذكر الجماعي أدبار الصلوات","answer":"الجواب: وهكذا مثل هذا بدعة، كونه يأتي بالذكر جماعياً متعمداً بألفاظ ينطقون بها جميعاً وينتهون منها جميعاً، هذا بدعة، لكن كل واحد يذكر الله، ولو تلاقت الأصوات في المسجد لا يضر ذلك، كل واحد يذكر الله، هذا يبتدي وهذا ينتهي، لا يتقصدون أن تكون ألفاظهم متزنة متوافقة من أولها إلى آخرها جماعياً لا، هذا لا أصل له بدعة، ولكن كل واحد يذكر الله، هذا يقول: أستغفر الله، أستغفر الله، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، وهذا ينتهي منها ويقول: لا إله إلا الله، والآخر يقول: لا إله إلا الله ولا نعبد إلا إياه، كل منهم على حسبه، يتكلم بما يسر الله له من الذكر، من غير أن يراعي اتفاقه مع كلام أخيه حرفياً، بل هذا يذكر الله، وهذا يذكر الله، وكل منهما يبتدي حيث شاء، وينتهي حيث شاء، أما أن يقصد كل واحد أن يكون جماعياً مع أخيه في ألفاظه ابتداءً وانتهاءً هذا لا أصل له، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8903/حكم-الذكر-الجماعي-ادبار-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34406.mp3","categories":["البدع والمحدثات"]},{"id":10736,"question":"نعود في هذه الحلقة إلى رسالة وصلت إلينا من قواد دوكا في السودان، وباعثها مستمع من هناك هو أحمد من الله بابكر، أخونا أحمد عرضنا بعض أسئلة له في حلقة مضت وفي هذه الحلقة يسأل ويقول: هناك أشخاص أحياء يرزقون يذهب إليهم أهلنا البسطاء لأخذ ما يسمى بالطريق وأخذ الفاتحة منهم؛ لأن دعوتهم مستجابة على حد تعبير أهلنا البسطاء، علماً بأن أهلي يركبون العربات لزيارتهم لأن مكانهم بعيد عن القرية، ويكلفهم هذا مبالغ هم في أشد الحاجة لها، أفيدونا جزاكم الله خيراً ووفقكم؟","title":"تحريم شد الرحال إلى الولي الحي وأخذ البدع منه","answer":"الجواب: الطرق الصوفية مما أحدثها الناس، والمتصوفون غالبهم أهل بدع وأهل جهل، وكونهم يشرعون للناس طرقاً خاصة في الأذكار هذا لا أصل له بل هو من البدع.\nفالواجب: أن لا يتصل بهم لهذا الأمر وأن لا يسألوا عن هذا الأمر وأن لا يقتدى بهم، بل الواجب على أهل العلم أن ينبهوهم ويشرحوا لهم الحق ويدلوهم عليه؛ لأن غالبهم جهال مقلدة لغيرهم، فالواجب تعليمهم وإرشادهم وأن البدع أنكرها الله عز وجل بقوله سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] والنبي الكريم عليه الصلاة والسلام قال: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود.\nفالواجب على أهل العلم والعباد أن يتقيدوا بالشريعة وأن لا يشرعوا للناس شيئاً ما شرعه الله ، لا في الأقوال ولا في الأعمال، ومن كان معروفاً بالتصوف لا يقتدى به ولا يعمل بقوله وتوجيهه لأنه ليس عنده علم، بل إنما هي طرق تلقاها بعضهم عن بعض وأحدثوها وساروا عليها، فلا ينبغي أخذها عنهم بل يجب إرشادهم وتوجيههم إلى الخير وتعليمهم ما ينفعهم، وشرح السنة لهم حتى يستقيموا عليها وحتى يدعوا البدع.\nومن ذلك ختمهم الدعوات بالفاتحة أو تعليمهم الفاتحة للتثويب حتى يثوبوها لفلان أو فلان هذا ليس له أصل، الإنسان يقرأ القرآن ويقرأ الفاتحة ليستفيد ويتعلم ويطلب الثواب من الله عز وجل، نعم قال بعض العلماء: أنه لا بأس بالقراءة للموتى وتثويبها للموتى أو الأحياء كونه يقرأ ويجعل ثوابها لفلان لكن ليس عليه دليل، ولم يفعله المصطفى ﷺ ولا أصحابه ما كان النبي ﷺ يقرأ للناس يقرأ ... حتى يثوب لهم، وما كان الصحابة يفعلون هذا .\nفالأولى للمؤمن أن يدع هذا الشيء وأن يكتفي بما درج عليه الصحابة  وتلقوه عن نبيهم عليه الصلاة والسلام، ولكن يدعو لموتاه بالمغفرة والرحمة يتصدق عنهم بالمال يحج عمن لم يحج عن موتاه يعتمر لا بأس، إذا كان قد حج عن نفسه واعتمر عن نفسه.\nأما أن يقرأ لهم قرآناً يثوبه لهم فليس عليه دليل والذي ينبغي ترك ذلك؛ لأن البدع لا خير فيها وشرها عظيم، فكونه يقرأ قراءة يقصد ثوابها لفلان أو فلان هذا ليس عليه دليل، فيخشى عليه أن يكون أتى بدعة منكرة فالأولى له ترك ذلك، وإن قال بعض أهل العلم بجواز ذلك؛ لأن العبرة بالدليل لا بأقوال الناس، والله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، ويقول جل وعلا: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، فإذا قال بعض أهل العلم: إنه يقرأ للموتى، وقال آخرون: لا، ترد المسألة إلى كلام الله وكلام رسوله عليه الصلاة والسلام، وإذا رجعنا إلى كلام الله وإلى كلام رسوله ﷺ لم نجد في ذلك ما يدل على أن القرآن يثوب للموتى أو لغير الموتى، بل الإنسان يقرأ القرآن ليستفيد ويتدبر ويتعقل ويحصل له الثواب من الله ، وإذا دعا لإخوانه المسلمين أو لموتاه المسلمين أو لوالديه المسلمين بالمغفرة والرحمة حال قراءته أو في أوقات أخرى كل هذا لا بأس به، لكنه يقرأ لطلب الثواب من الله لنفسه، وليستفيد من القرآن ويتعلم أحكام الله ويتدبر ويتعقل هذا هو المشروع.\nوفق الله المسلمين لكل خير. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8912/تحريم-شد-الرحال-الى-الولي-الحي-واخذ-البدع-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34503.mp3","categories":["البدع والمحدثات"]},{"id":10763,"question":"يسأل الأخ ويقول: في بعض قرى ومدن محافظة حضرموت إذا مات شخص يقوم أقرب الناس له أو أسرته بعقد عزاء على روحه، وهو قراءة القرآن لمدة يوم أو ثلاثة أيام في المسجد، للرجال، وفي البيت للنساء، ويتم الختام بقراءة الفاتحة إلى روح سيدنا محمد ﷺ وأصحابه أجمعين، وإلى روح الأموات الذي لهم صلة قرابة بالمتوفى، كما يتم خلال ذلك توزيع القهوة والدخون على كل الحاضرين لهذا العزاء، ما حكم عملهم هذا، أفيدونا أفادكم الله؟","title":"حكم العزاء بقراءة القرآن وإهداء الفاتحة","answer":"الجواب: هذا العمل بدعة ليس بمشروع تجمعهم بيوم أو ثلاثة أيام على هذه القراءة، ثم يختموا بالفاتحة للنبي ﷺ كل هذا لا أصل له، ولكن ليأتي المؤمن ويعزيهم يدعو لميتهم بالمغفرة ولهم بالصبر والاحتساب والأجر ويكفي هذا، ولو صبوا له قهوة وطيبوه لا بأس، أما تجمع خاص في يوم أو يومين أو ثلاثة أو أكثر، فيه قراءة خاصة ثم ختم بالفاتحة كل هذا لا أصل له، ما كان يفعل في عهده صلى الله عليه وسلم ولا في عهد أصحابه، بل نص أهل العلم على أن مثل هذا بدعة.\nفالمشروع للمؤمن في مثل هذا أنه يأتي أخاه في البيت أو في الطريق أو في المسجد ويقول: أحسن الله عزاءك وجبر الله مصيبتك، غفر الله لميتك، والآخر يقول: جزاك الله خير، تقبل الله منك ونحو لك، ويكفي هذا والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8939/حكم-العزاء-بقراءة-القران-واهداء-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34709.mp3","categories":["البدع والمحدثات"]},{"id":10796,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: تقوم بعض النساء عندنا بزيارة القبور والمساجد، ومن خلال الزيارة يقمن بجمع الأطفال داخل المسجد، أو على القبور، ويفرقن عليهم خبزًا، وبعض الأشياء، ويقلن: لوجه الله، ثم يقمن بدعاء الولي الذي زرن لأجله، ويقلن: يا ولي عافني، واحفظ أولادي، وكثيرًا من الدعاء، فما رأيكم -يا سماحة الشيخ- في هذا العمل؟","title":"حكم زيارة المرأة للمشاهد والقبور ودعائها الأولياء","answer":"الجواب:  هذا عمل خطير، يجب الحذر منه، النساء ممنوعات من زيارة القبور، وإنما الإذن للرجال، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة ولعن زائرات القبور من النساء؛ لأنهن فتنة، وصبرهن قليل، أما إذا كان مع ذلك دعوة الموتى، والاستغاثة بالموتى صار شركًا أكبر، صار الشرك الأكبر، هكذا الذبح لهم، طلبهم المدد، هذا شرك أكبر من الرجال والنساء جميعًا، فالذي يأتي القبور ليدعوها من دون الله، ويطلبها النصر والمدد والعون، هذا أتى شركًا عظيمًا من الرجال والنساء جميعًا، وهذا شرك المشركين، هذا شرك عباد القبور، كـأبي جهل، وأصحابه من عباد القبور، وهكذا توزيع الصدقات إذا كان يقصد بهذا التقرب إلى الموتى بذلك، وأنه يتصدق، ينوي التقرب بالصدقة لهم، يعتقد أنهم ينفعونه، يتصدق عند قبورهم، وأنهم بهذه الصدقة التي يتقرب بها إليهم ينفعونه؛ مثل لو صلى لهم. وأما إن كان لا، صدقة يطلب من الله ثوابها، ولكن يظن ويعتقد أنها عند القبور أفضل، هذه بدعة، ما هي عند القبور أفضل، الصدقة يتصدق في بيته في أي محل، وإذا كانت عن طريق السر كان أفضل إلا إذا دعت الحاجة إلى الجهر، ولكن ليس محلها القبور؛ في الأسواق.. البيت.. في أي مكان في المسجد لمن سأل لا بأس. والخلاصة أن زيارة النساء للقبور لا تجوز، وكونهن يذبحن للأموات، أو يطلبن منهم المدد، أو الغوث، أو شفاء المرضى، هذا شرك أكبر، سواء وقع من امرأة، أو من الرجل، حتى ولو فعله في بيته، ما هو بعند القبور، يا سيدي فلان! يا عبدالقادر! يا حسين! يا علي! يا رسول الله! ولو في بيته، ولو في أي مكان بعيد عن المدن والقبور فهو شرك أكبر، ولو أنه في الصحراء ما عنده أحد، إذا قال: يا رسول الله! انصرني، أو يا رسول الله! اشف مريضي، أو ما أشبه ذلك فقد عبده من دون الله بهذا الدعاء، أو قال: يا سيدي الحسين! أو يا سيدي الحسن! أو يا سيدي علي! أو يا سيدي عبدالقادر! أو أحمد البدوي، أو ما أشبه ذلك، يطلبه المدد والعون، والغوث، هذا من الشرك الأكبر. وهكذا إذا تقرب له بالذبائح، سواء عند قبره، أو بعيدًا عن قبره، يذبح من أجل التقرب إليه، يرى أنه إذا ذبح له يمده بأشياء، أو يعطيه أشياء، أو يحصل له أشياء، فالذبح لغير الله شرك أكبر، قال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ [الأنعام:162] لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:163] قال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] فأمر بالصلاة والنحر لله . وقال -عليه الصلاة والسلام-: لعن الله من ذبح لغير الله فالذبح عبادة عظيمة كالصلاة، فإذا ذبح لأصحاب القبور، وتقرب إليهم بذلك يرجو شفاعتهم، ويرجو أنهم يقربونه من الله زلفى، أو تصدق يطلب الأجر منهم، والثواب منهم، أو حج لقبورهم، أو ما أشبه ذلك من المقاصد التي يفعلها، يتقرب بها إلى أصحاب القبور، هو يكون بهذا قد عبدهم، وجعلهم آلهة يعبدهم مع الله بصلاته لهم، أو دعائه لهم، أو ذبحه لهم، أو نذره لهم، أو غير ذلك، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8977/حكم-زيارة-المراة-للمشاهد-والقبور-ودعاىها-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35207.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":10802,"question":"الرسالة التالية وصلت إلى البرنامج من مكة المكرمة وباعثها الأخ هاشم معتوق فقيه الأخ هاشم يقول في رسالته: أرجو من سماحتكم أن تبينوا لي حكم صلاة التسابيح، هل هي صحيحة، أم غير ذلك، كما جاء في كتاب وصايا الرسول ﷺ؟ وإذا كانت صحيحة أرجو من سماحتكم توضيح عدد الركعات وعدد السجدات، جزاكم الله خيرًا.","title":"صلاة التسابيح بدعة ليس لها أصل","answer":"الجواب:  صلاة التسبيح قد تأملناها كثيرًا، وتأملناها أيضًا مع اللجنة الدائمة للبحوث العلمية والإفتاء ورأينا جميعًا عدم صحتها، فصلاة التسبيح ليست صحيحة، وطرقها كلها ضعيفة، ومتنها منكر، مخالف للأحاديث الصحيحة، ومخالف لما كان عليه النبي ﷺ في عباداته.  فالواجب عدم التعلق بها، وعدم فعلها؛ لأنها من البدع المحدثة في الدين، وقد صدرت الفتوى ببيان ذلك مني ومن اللجنة الدائمة، في بحوث العلم والإفتاء في المملكة العربية السعودية. والمقصود أن صلاة التسبيح التي سارت بين الناس لا أساس لها من الصحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8987/صلاة-التسابيح-بدعة-ليس-لها-اصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35309.mp3","categories":["البدع والمحدثات"]},{"id":10805,"question":"الرسالة التالية وصلت إلى البرنامج من مكة المكرمة وباعثها الأخ هاشم معتوق فقيه الأخ هاشم يقول في رسالته: أرجو من سماحتكم أن تبينوا لي حكم صلاة التسابيح، هل هي صحيحة، أم غير ذلك، كما جاء في كتاب وصايا الرسول ﷺ؟ وإذا كانت صحيحة أرجو من سماحتكم توضيح عدد الركعات وعدد السجدات، جزاكم الله خيرًا.","title":"صلاة التسابيح بدعة ليس لها أصل","answer":"الجواب:  صلاة التسبيح قد تأملناها كثيرًا، وتأملناها أيضًا مع اللجنة الدائمة للبحوث العلمية والإفتاء ورأينا جميعًا عدم صحتها، فصلاة التسبيح ليست صحيحة، وطرقها كلها ضعيفة، ومتنها منكر، مخالف للأحاديث الصحيحة، ومخالف لما كان عليه النبي ﷺ في عباداته.  فالواجب عدم التعلق بها، وعدم فعلها؛ لأنها من البدع المحدثة في الدين، وقد صدرت الفتوى ببيان ذلك مني ومن اللجنة الدائمة، في بحوث العلم والإفتاء في المملكة العربية السعودية. والمقصود أن صلاة التسبيح التي سارت بين الناس لا أساس لها من الصحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8987/صلاة-التسابيح-بدعة-ليس-لها-اصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35309.mp3","categories":["البدع والمحدثات"]},{"id":10826,"question":"من أحد الإخوة المستمعين رسالة يقول: أخوكم حسن عبدالله سالم يمني يقول: هل يجوز للفرد عند قيام الصلاة أن يذكر الوقت وعدد ركعاته، أو يكتفي بالتكبيرة فقط؟","title":"حكم التلفظ بالنية قبل الشروع في الصلاة","answer":"الجواب:  يكفي التكبير والحمد لله، أما قول: نويت كذا وكذا هذا بدعة، لا أصل له، نويت أن أصلي كذا وكذا ركعة في وقت كذا هذا لا أصل له، وليس من فعل النبي ﷺ ولا من فعل الصحابة -رضي الله عنهم وأرضاهم- بل ذلك من البدع التي أحدثها بعض الناس، ويكفي المؤمن النية في قلبه أنه قام لصلاة الظهر العصر، المغرب العشاء لصلاة الضحى، لصلاة الاستخارة، لصلاة الكسوف، النية كافية فقط، والحمد لله. يقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى والنية محلها القلب، ويقول -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد أي: هو مردود، وليس من عمل النبي ﷺ ولا من سنته، أن يتلفظ بالنية يقول: نويت أن أصلي كذا وكذا، أو نويت أن أتوضأ، أو نويت أن أطوف، هذا لا أصل له. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8998/حكم-التلفظ-بالنية-قبل-الشروع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35409.mp3","categories":["البدع والمحدثات"]},{"id":10874,"question":"المستمع (أ. م. حجابي) و (أ. خ. مصطفى) من السودان بعثا برسالة ضمناها بعض الأسئلة، في أحد أسئلتهم يقولون: عندما يتوفى المرء في بلدنا يجلس الأقارب في بيت المتوفى مدة خمسة أيام، أو أكثر من ذلك لاستقبال المعزين، فيقرؤون الفاتحة ويرفعون أيديهم إلى الوجه، ثم يقولون بصوت جماعي: جبر الله كسرك، ولأهل الميت: عظم الله أجرك، فما حكم الشرع في هذه العادة، وهل هي صحيحة أم أنها بدعة؟ نرجو الإفادة، جزاكم الله خيرًا.","title":"حكم الاجتماع للتعزية ورفع الصوت بالدعاء وقراءة القرآن للميت","answer":"الجواب:  هذه العادة بدعة لا أصل لها في الشرع، ولم يكن الرسول ﷺولا أصحابه يفعلون ذلك، فالواجب على المؤمن الحذر من البدع، فهي شر وبلاء، ولهذا قال -عليه الصلاة والسلام- في الحديث الصحيح: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة وقال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد، يعني: فهو مردود، وكان يقول في خطبة الجمعة -عليه الصلاة والسلام-: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ يعني: السيرة وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه مسلم في صحيحه. فالمصابون يعزون في ميتهم، ويدعى لهم أن الله يجبر مصيبتهم، ويحسن عزاءهم، ويغفر لميتهم إذا كان مسلمًا، أما كونهم يجلسون للعزاء، ويتجمعون على قراءة، وعلى الأكل والشرب، ونحو ذلك، هذا لا أصل له، لكن إذا جلس في بيته الوقت المعتاد الذي يجلسه الناس في بيوتهم، وجاءه الناس يعزونه من دون إحداث شيء، بل الجلوس العادي، وإن صب لهم قهوة، أو صب لهم شاهيًا لا بأس، هذه جلسات عادية، جلسات عادية لا بأس بها. وقد كان النبي ﷺ لما جاءه خبر جعفر بن أبي طالب لما قتل في مؤتة هذا الصحابي جلس واجمًا، أو يظهر عليه أثر الحزن، عليه الصلاة والسلام. فالمقصود أن الجلوس عند المصيبة، وعند روعة المصيبة ليس فيه حرج، لكن كونه يتعمد أن يكون لهذا نظام خاص بإيجاد طعام، أو مأتم حزن، أو جمع قراء، أو قراءة خاصة يفعلونها بينهم، أو دعوات يرفعون فيها أيديهم، ويجتمعون عليها، أو ما أشبه ذلك هذا لا أصل له. أما كونه جلس في بيته الجلوس المعتاد ضحوة أو ظهرًا أو عصرًا أو مغربًا، ومر عليه جيرانه وأقاربه أو عزوه في الطريق، أو في المسجد، أو في المقبرة كله جائز والحمد لله، من دون أن يتخذ لهذا نظامًا خاصًا، نعم. المقدم: قراءة الفاتحة أيضًا سماحة الشيخ؟ الشيخ: كذلك لا أصل لهذا لا الفاتحة ولا غيرها، أما إذا قرؤوا على العادة، إذا اجتمعوا وقرؤوا من القرآن لا لأجل الميت، بل لأنهم مجتمعون، وقرأ واحد يسمعهم كتاب الله لا بأس بهذا، أما يكون لسر المصيبة، لقصد المصيبة هذا لا أصل له. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9048/حكم-الاجتماع-للتعزية-ورفع-الصوت-بالدعاء-وقراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35802.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":11028,"question":"هذا السائل من السودان رمز لاسمه بـ (م. م. أ) يقول: هل يجوز الاحتفال بالمولد النبوي؟ نرجو منكم التوجيه في ضوء هذا السؤال.","title":"لا يجوز الاحتفال بموالد الأنبياء والأخيار","answer":"الجواب:  قد سبق منا جوابات كثيرة في هذا البرنامج، وفي غيره، وكتبنا في ذلك كتابات كثيرة، فهذا الاحتفال به بدعة، الاحتفال بالموالد بدعة عند أهل العلم، عند أهل التحقيق بدعة بمولد النبي ﷺ وغيره، فلا يجوز الاحتفال بالموالد، لا بمولده ﷺ، ولا بغيره من الأنبياء والأخيار، فما يفعله الناس بمولد النبي ﷺ أو البدوي أو الشيخ عبدالقادر، أو الحسن، أو الحسين، أو غيره كله بدعة لا يجوز فعله. والواجب الترضي عنهم واتباع طريقهم الطيب، والإكثار من الصلاة على النبي ﷺ واتباع سبيله، والحث على سنته، وتعليم دينه، والقيام بحقه من طاعة أمره، وترك نهيه، والسير على منهاجه ﷺ هذا هو الواجب على المؤمن، قال تعالى: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي ما قال فاتخذوا مولدًا لي احتفلوا بي، قال: إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ [آل عمران:31] فعلامة المحبة اتباعه، وطاعة أوامره، وترك نواهيه. أما إقامة الموالد والبدع التي ما أنزل الله بها من سلطان، فهذا لا يجوز، بل هو من وسائل الشرك، وكثير من هؤلاء الذين يتخذون الموالد يقعون في الشرك، في دعاء النبي ﷺ، والاستغاثة به، وبعضهم يقع في البدعة، التوسل بجاهه وبحقه، وهذا لا يجوز. أما التوسل بمحبته والإيمان به لا بأس، اللهم إني أسألك بمحبتي لنبيك، وإيماني بنبيك أن تغفر لي، هذا لا بأس به، أما التوسل بجاه النبي أو بحق النبي فهذا بدعة ما عليه دليل، بل هو من البدع، والتوسل بمحبته، والإيمان به، والسير على منهاجه هذا توسل شرعي. فالمقصود: أن الاحتفال بالموالد من البدع، سواء كان مولد النبي ﷺ أو مولد غيره من الأنبياء، أو الصالحين، أو الصحابة، أو غيرهم كله من البدع، وهكذا الاحتفال بليلة النصف من شعبان، أو بليلة سبع وعشرين من رجب يسمونها ليلة الإسراء والمعراج، هذه بدعة، أو الاحتفال بأول ليلة من رجب، أول ليلة جمعة من رجب يسمونها صلاة الرغائب بدعة. المقصود: أن الاحتفال الذي ما شرعه الله ليتقرب به إلى الله هذا من البدع، ما فعلها النبي ﷺ النبي ﷺ هو أصدق الناس، وأنصح الناس، علم الأمة كل خير، ودعاها إلى كل خير، ولم يحتفل بمولده في حياته ﷺ مكث في المدينة عشر سنين، وهو رئيس المؤمنين وأميرهم، ليس له معارض، ولم يحتفل بمولده، عليه الصلاة والسلام. ثم الصديق بعده، ثم عمر ، ثم عثمان ، ثم علي ، ثم الخلفاء بعدهم ما احتفلوا بمولده، ولو كان خيرًا لسبقونا إليه، وجميع القرون المفضلة لم يحتفلوا بالموالد، إنما أحدثه الرافضة في القرن الرابع، بنو عبيد القداح الفاطميون، ثم تابعهم بعض المسلمين جهلًا منهم، وعدم بصيرة. نعم. المقدم: شكر الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9206/لا-يجوز-الاحتفال-بموالد-الانبياء-والاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28710.mp3","categories":["البدع والمحدثات"]},{"id":11032,"question":"هذا السائل من السودان رمز لاسمه بـ (م. م. أ) يقول: بعض المساجد يوجد فيها شخص بعد صلاة الجمعة يرفع يده، ويطلب الله  والبعض من المصلين من حوله يقولون: آمين، هل هذا العمل جائز؟","title":"حكم الدعاء بعد صلاة الجمعة وتأمين الحاضرين","answer":"الجواب: هذا لا أصل له، هذا بدعة، بدعة لا أصل له، نعم، ليس بجائز، كل إنسان يدعو بينه وبين ربه، كل واحد يدعو بينه وبين ربه، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/9210/حكم-الدعاء-بعد-صلاة-الجمعة-وتامين-الحاضرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28714.mp3","categories":["البدع والمحدثات"]},{"id":11089,"question":"هذا السائل رمز لاسمه بـ (أ. أ. م) من السودان يقول: لدينا مؤذن في المسجد كلما جاء ليؤذن وقتًا من الأوقات بدأ بالآية الكريمة، وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، فما حكم ذلك سماحة الشيخ؟","title":"حكم قراءة: {وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ} قبل الأذان","answer":"الجواب: هذا غير مشروع، أقول: غير مشروع، لم يفعله النبي ﷺ ولا أصحابه، يبدأ بـ (الله أكبر)، يبدأ الأذان بـ (الله أكبر). نعم.","link":"https://binbaz.org.sa/fatwas/9267/حكم-قراءة-ومن-احسن-قولا-ممن-دعا-الى-الله-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28915.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":11103,"question":"من بنقلادش السائل عبدالجليل علي أرسل بهذا السؤال يقول: ما هي البدعة، وهل لها أقسام سماحة الشيخ؟","title":"تعريف البدعة وحكمها","answer":"الجواب:  البدعة كل قربة تخالف الشرع يقال لها: بدعة، كل من يتقرب بشيء لم يشرعه الله يقال له: بدعة، مثل: الاحتفال بالموالد، مثل: الاحتفال بليلة الإسراء والمعراج، مثل: الاحتفال بأول ليلة من رجب يسمونها: الرغائب، كل هذه بدع.  وهكذا ما أحدثه الناس من البناء على القبور بدعة، اتخاذ المساجد عليها بدعة، اتخاذ القباب عليها بدعة، منكر، من أسباب الشرك، ومن وسائله، وكلها ضلالة ما فيها أقسام، الصحيح أن كلها ضلالة، يقول النبي ﷺ: كل بدعة ضلالة هذا الصواب، جميع البدع ضلالة. نعم.","link":"https://binbaz.org.sa/fatwas/9281/تعريف-البدعة-وحكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29011.mp3","categories":["البدع والمحدثات"]},{"id":11243,"question":"هذا السائل محمد حسين مصري يقول في هذا  فضيلة الشيخ! هل الموالد التي تقام للأولياء مثل السيد البدوي أو السيدة زينب أو الإمام الحسين  أو الأضرحة التي بالقرى، أو الاحتفال بمولد الرسول ﷺ، وذلك تدار الزفة بالمدن والريف والنجوع وتدق الطبول والمزامير وعلى جميع الأشكال المخلة بالدين، وما تجلبه هذه التجمعات من صبية ورجال واختلاط فما حكم الشرع في نظركم في هذا مأجورين؟","title":"بيان بدعية الموالد ومنكراتها","answer":"الجواب:  هذه الأشياء بدعة ما أنزل الله بها من سلطان ولا تجوز، الاحتفال بالموالد سواءً مولد النبي ﷺ أو مولد البدوي أو الحسين أو غيرها كلها بدعة لا يجوز الاحتفال بها، لم يفعلها النبي ﷺ ولا صحابته ، فهي من البدع وما يقع فيها من آلات الملاهي والطبول واختلاط الرجال بالنساء منكر آخر، منكرات أخرى، كلها يجب منعها. والواجب أن يسع الناس ما وسع النبي ﷺ وأصحابه، فيدعى للميت، يزار ويدعى له من غير احتفال بمولده، تزار القبور، يدعى لأهلها بالمغفرة والرحمة، أما أن يوجد احتفال بالسنة أو بغير سنة أو بالشهر أو بالسنتين بالمولد فهذا كله منكر لا أصل له، بل هو من البدع التي أحدثها الناس، ومن أسباب الشرك، فإن هذه الاحتفالات من أسباب الغلو في المحتفل به حتى يدعى من دون الله، حتى يستغاث به، وربما تمسح الناس بقبره وطافوا به، فهي شر تجر إلى شرور كثيرة نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/9424/بيان-بدعية-الموالد-ومنكراتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29124.mp3","categories":["البدع والمحدثات"]},{"id":11364,"question":"لهم سؤال آخر سماحة الشيخ يقولون: ما حكم الصلاة خلف إمام مبتدع، سواء كانت البدعة في مجال العبادات، أو العقائد؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف المبتدع والعاصي","answer":"الجواب:  لا يجوز أن يتخذ المبتدع إمامًا، لا يجوز أن يتخذ المبتدع إمامًا؛ لأن هذا رفع لشأنه، فلا يجوز أن يتخذ إمامًا بل يتحرى في الإمامة أهل الصلاح والاستقامة والسالمين من البدع، هذا هو الواجب على المسؤولين أن يتحروا للإمامة الرجل الصالح صاحب العلم والفضل البعيد عن البدعة، لكن إذا وجد في المسجد إمام مبتدع بدعته غير مكفرة فالصلاة خلفه صحيحة والواجب إزالته وإبداله بغيره، أما إن كانت بدعته مكفرة كعابد القبور الذي يعبد القبور ويستغيث بالأموات هذا لا تصح الصلاة خلفه، لا تصح صلاته في نفسه لكفره ولا تصح الصلاة خلفه. أما إذا كان مبتدعًا بدعة لا تخرجه من الإسلام بدعة تجعله عاصيًا فقط فالصلاة خلفه صحيحة كالصلاة خلف غيره من الفساق الذين هم مسلمون لكن عندهم بعض المعاصي كالغيبة والنميمة، كشرب المسكر، كحلق اللحى، فالصلاة صحيحة لكن لا ينبغي أن يتخذوا أئمة، ينبغي لولاة الأمور ألا يجعلوا إمامًا يتظاهر بالمعصية، قد صلى بعض الصحابة خلف الحجاج بن يوسف وكان من أفسق الناس، سفاكًا للدماء؛ لأنه مسلم. ومن أمثلة البدع التي لا تخرج من الإسلام مثل بدعة الاحتفال بالمولد إذا لم يكن فيها شرك، مجرد احتفال بالمولد وقراءة دروس أو قصائد ليس فيها شرك، هذه بدعة منكرة، أما إذا كان فيها شرك فيها دعاء النبي ﷺ والاستغاثة به صار ذلك شركًا أكبر. ومثل: بدعة ليلة المعراج، ليلة الإسراء والمعراج الاحتفال بها هذه بدعة لا تكفر إلا إذا كان فيها دعوة لغير الله واستغاثة بغير الله يكون فاعل ذلك كافرًا باستغاثته بغير الله ودعائه الأموات والغائبين، ومثل: نويت أن أصلي كذا وكذا، هذه بدعة لفظية لا تكفر، معصية نقص على المؤمن فالصلاة خلف صاحبها صحيحة، لو قال: نويت أن أصلي الظهر، نويت أن أصلي كذا، فهذا لا يجوز ولكن الصلاة صحيحة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9546/حكم-الصلاة-خلف-المبتدع-والعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29306.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":11645,"question":"هل هناك بدعة حسنة، وبدعة سيئة كما نسمع؟","title":"تقسيم الدين إلى بدعة حسنة وسيئة","answer":"الجواب:  ليس هناك بدعة حسنة، كله البدع ضلالة، يقول النبي ﷺ: وإياكم ومحدثات الأمور؛ فإن كل محدثة بدعة، وكل بدعة ضلالة فالتقسيم إلى بدعة حسنة غلط، بدعة حسنة وسيئة غلط لا يجوز، بل كل البدع ضلالة، والبدع هي ما خالف الشرع، كل عبادة تخالف الشرع؛ فهي بدعة. قول عمر: «نعمت البدعة » يعني: من جهة اللغة، سمى التراويح بدعة من جهة اللغة؛ لأنها حدثت بعد النبي ﷺ، وإلا فهي سنة فعلها النبي ﷺ وفعلها أصحابه، فالعبادات المحدثة كلها بدعة وكل بدعة ضلالة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9817/تقسيم-الدين-الى-بدعة-حسنة-وسيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38904.mp3","categories":["البدع والمحدثات"]},{"id":11656,"question":"يسأل أيضًا ويقول: هل يجوز التلفظ بالنية، أو لا يجوز؟","title":"النية محلها القلب ولا يتلفظ بها","answer":"الجواب:  التلفظ بالنية غير مشروع، بل بدعة، فإذا أراد الصلاة لا يقول: نويت أصلي أن كذا وكذا، ولا نويت أن أطوف، أو أسعى لا، النية محلها القلب، وهكذا عند الوضوء لا يقول: نويت أن أتوضأ، أو نويت أن أغتسل، النية محلها القلب، الأعمال بالنيات محلها القلب، النية هي القصد، قصد القلب، فلا يشرع التلفظ بها. وما ذكره بعض الفقهاء من التلفظ لا دليل عليه، بل هو غلط، والمشروع أن ينوي بقلبه، إذا قام للوضوء نوى بقلبه، إذا قام يصلي نوى، هذه النية، إذا توجه إلى الكعبة ليطوف هذه النية، توجه إلى المسعى ليسعى هذه النية، ، ما يحتاج يقول: نويت أن أفعل كذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9839/النية-محلها-القلب-ولا-يتلفظ-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29808.mp3","categories":["البدع والمحدثات"]},{"id":11713,"question":"يسأل أخونا سؤاله الأخير فيقول: ما هو الحد، أو القول الفصل بين البدعة والأمور الحديثة الجديدة، متطلبات العصر، أو بمعنىً آخر كيف نميز بين الأمور الحديثة الموجودة في عصرنا الحاضر، وبين البدعة التي وردت في الأحاديث الشريفة، بينوا لنا هذا الموضوع -جزاكم الله خيرًا- وكيف نبه الرسول وحذر ﷺ؟","title":"القاعدة العامة في معرفة البدعة","answer":"الجواب:  الأشياء الجديدة الحادثة قسمان: قسم يتعلق بأمور الدنيا من ملابس مآكل مشارب أواني أسلحة، هذه لا بأس بها، ولا تسمى بدعًا، كالطائرات والمدافع والصواريخ وغير ذلك، هذه ما تسمى بدعًا، هذه أمور دنيوية، والملابس والأواني وتنوع الأكل كل هذه ..... البدع ما كان يتعلق بالدين من المحدثات التي يراها أهلها دينًا وقربة وعبادة، مثل إحداث الموالد، الاحتفال بالموالد مثل إحياء ليلة الإسراء والمعراج، مثل إحياء ليلة الرغائب أول ليلة من رجب، ليلة جمعة من رجب، هذه يقال لها: بدع، إحداث أشياء ما شرعها الله، تعبد يتعبد بها مثل إحياء ليلة النصف من شعبان، كل هذه بدع ما أنزل الله بها من سلطان. يعني: التعبد بأشياء ما شرعها الله قولية أو فعلية، هذه هي البدع، لقوله ﷺ: من أحدث في أمرنا يعني: في ديننا هذا ما ليس منه فهو رد ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد. فالمراد به في العبادات، فالذي يحدث من العبادات يسمى بدعة، الذي لا أصل له في الشرع، يسمى بدعة. نعم. المقدم: بارك الله فيكم، إذًا ما يتعلق بمتطلبات العصر كما سماها أخونا ليس فيها بدع، ولا غير ذلك. الشيخ: لا لا هذه أمور دنيا ما تسمى بدعًا، ولو سميت بدعة فهي بدعة لغوية، ما يتعلق بها منع. المقدم: لا يتعلق بها أمر من أمور العبادات؟ الشيخ: لا لا أبدًا، أنواع المآكل والمشارب والأواني والملابس والسلاح كل هذه أمور عادية. نعم. المقدم: بارك الله فيكم، وأحسن إليكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9895/القاعدة-العامة-في-معرفة-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39208.mp3","categories":["البدع والمحدثات"]},{"id":11935,"question":"أحد الإخوة المستمعين يسأل سماحتكم ويقول: ما هي البدعة الاعتقادية؟ وما هي البدعة العملية؟","title":"الفرق بين البدعة الاعتقادية والعملية","answer":"الجواب:  كل ما خالف الشرع؛ فهو بدعة إن كان في الاعتقاد يسمى بدعة مثل دعاء الأموات، والاستغاثة بالأموات، والاستغاثة بالجن، أو بالملائكة، يظنها دينًا، يعتقد أنها دين يحسب أنها جائزة، هذه بدعة شركية، كفر أكبر، ويسمى بدعة؛ لأنه يظن أنها دين صاحبها، كذلك البناء على القبور، واتخاذ المساجد عليها بدعة، لكنها دون الكفر، وسيلة للكفر إذا بنى مسجدًا على القبر يحسب أنه دين، أو بنى قبة على القبر يحسب أن هذا جائز، هذه بدعة منكرة، ومن وسائل الشرك؛ لقول النبي ﷺ: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد. أما دعاء الأموات، والاستغاثة بالأموات، والنذر لهم هذه بدعة شركية، يكون صاحبها كافرًا كفرًا أكبر، ولو زعم أنه جاهل؛ لأن هذا أمر معروف من الدين بالضرورة، معروف بين المسلمين، فهو كافر بذلك، فعليه التوبة إلى الله من ذلك، يستتاب، فإن تاب وإلا قتل من ولي الأمر الحاكم الشرعي. وهناك بدع كثيرة مثل بدعة المولد، الاحتفال بمولد، النبي ﷺ أو مولد غيره، ومثل بدعة ليلة الإسراء والمعراج سبع وعشرين رجب الاحتفال بها هذه بدعة أيضًا، عملية، ومنكرة لا تجوز، ولكن ليست من الشرك الأكبر إلا إذا كان فيها شرك، إذا كان في المولد، أو في الاحتفال بليلة الإسراء والمعراج دعاء للنبي ﷺ واستغاثة به، يكون شرك أكبر، أما إن كان مجرد احتفال على الأكل والشرب، والقهوة، والشاي، ولا فيه دعاء، ولا استغاثة بالنبي ﷺ فهذه بدعة منكرة، يمنعها قول النبي ﷺ: من أحدث في أمرنا هذا -أي: ديننا- ما ليس منه فهو رد أي: فهو مردود، وقوله ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد وقوله ﷺ: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة. والبدعة: هي الشيء المحدث في الدين، الذي يحدثه الناس، يتقربون إلى الله، والله ورسوله ما شرعه، ما شرعه الله، ولا رسوله تسمى بدعة، مثل الاحتفال بمولد النبي ﷺ أو بالاحتفال بمولد الصديق، أو عمر، أو عثمان، أو علي، أو الحسين، أو غيرهم، أو الاحتفال بمولد أبي حنيفة أو الشافعي أو مالك أو الشيخ عبد القادر الجيلاني، أو الست نفيسة، أو الست زينب، أو ما أشبه ذلك، كلها بدع منكرة لا تجوز، ومن وسائل الشرك، نعوذ بالله.  بعض الناس في المولد يشركوا بالله، في مولد النبي ﷺ يدعون النبي ﷺ ويستغيثوا به، هذا الشرك الأكبر، وبعضهم في مولد علي يستغيث بـعلي، يستغيث به، وينذر له، ويدعوه من دون الله، هذا شرك أكبر. وهكذا في الموالد الأخرى يدعون صاحب المولد يستغيثون به هذا الشرك الأكبر -نعوذ بالله- ربنا يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْْ دُونِهِ من دون الله: مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ[فاطر:13] القطمير اللفافة التي على النواة حقت التمر: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ [فاطر:14]، يعني: الأموات والأصنام ونحوهم: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ [فاطر:14]، ما عندهم قدرة يعطونك ما طلبت: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14]، سماه شرك، سمى دعاءهم والاستغاثة بهم شركًا أكبر: وَيَوْمََ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14]، والشرك إذا أطلق فهو الأكبر، وقال سبحانه في آخر سورة المؤمنون: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًاا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعاة غير الله من الأموات والأشجار والأحجار سماهم كفرة قال: إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. والنبي ﷺ حكم على دعاة القبور والأموات والاستغاثة بهم حكم عليهم بأنهم كفار، وقاتلهم، قاتل أهل الطائف الذين يدعون اللات، ويعبدون اللات، وهو قبر، أو صخرة يعبدونها؛ لأنه كانوا يلتوا عليها السويق، وقاتل عباد الشجر عباد العزى، وعباد الحجر، عباد المناة؛ حتى يدعوا ذلك؛ حتى يشهدوا أن لا إله إلا الله، وأن محمدًا رسول الله، وحتى يدعوا الشرك، ويتبرؤوا منه. وهكذا سائر البدع إن كان فيها دعاء غير الله، والاستغاثة بغير الله، أو الذبح لغير الله؛ صارت شركاً أكبر، وإن كان مجرد عمل ما شرعه الله؛ يكون بدعة دون الشرك منكرة، ومن هذا الصلاة عند القبور، كونه يصلي عندها يقول: لعله أفضل يروح جنب القبر، يصلي في المقبرة يقول: لعلها أفضل، هذه بدعة من وسائل الشرك، وهكذا الجلوس عند القبور للدعاء، يرى أن الدعاء أفضل عند القبور للدعاء بدعة.  كذلك قول بعضهم: نويت أن أصلي لله أربع ركعات، أو ثلاث ركعات بدعة النية التلفظ بالنية، إذا قام للصلاة ينوي في قلبه ويكفي، ينوي في قلبه أنه قام للظهر، للعصر للمغرب للعشاء، وهكذا جميع الصلوات النافلة ينوي في قلبه ويكفي، أما أن يقول بعد الوقوف: نويت أن أصلي لله أربع ركعات يعني: للظهر أو العصر أو ثلاث ركعات يعني: المغرب أو ركعتين يعني: الفجر أو الجمعة هذه بدعة، ما كان النبي ﷺ يفعله، ولا الصحابة  ولكن تقف خاشعًا ناويًا بقلبك الصلاة، والحمد لله يكفي، فلا حاجة أن تقول: نويت أن أصلي كذا وكذا، أو نويت أن أطوف، أو أن أسعى، بل تأتي بنية الطواف، وتبدأ بالحجر الأسود ناويًا الطواف، وعند السعي كذلك تبدأ بالصفا ناويًا السعي، ويكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10119/الفرق-بين-البدعة-الاعتقادية-والعملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42712.mp3","categories":["البدع والمحدثات"]},{"id":11961,"question":"ما هو التشدد المنهي عنه في الدين؟","title":"حقيقة التشدد والغلو المنهي عنه في الدين","answer":"الجواب:  التشدد هو الغلو والتنطع، يقول النبي ﷺ: إياكم والغلو في الدين؛ فإنما أهلك من كان قبلكم الغلو في الدين ويقول ﷺ: هلك المتنطعون! هلك المتنطعون! هلك المتنطعون قالها ثلاثًا -عليه الصلاة والسلام- معناه: الزيادة على ما شرعه الله، هذا التشدد يزيد على ما شرعه الله، ومن ذلك: البناء على القبور، واتخاذ المساجد عليها، والصلاة عندها، هذا زيادة على ما شرع الله، شرع الله زيارتها، والدعاء لأهلها بالمغفرة والرحمة، أما كونه يبني عليها مساجد، أو قباب هذا من وسائل الشرك ومحرم، والرسول ﷺ أنكر ذلك، ولعن اليهود والنصارى على فعل ذلك. والصلاة عند القبور من وسائل الغلو فيها والشرك، هكذا الزيادة على ما شرعه الله، كأن يتوضأ أكثر من ثلاث، هذا زيادة على ما شرعه الله، وكذلك كونه يستعمل في صلاته ما لم يشرعه الله غير الزيادة على الوضوء، بل يستعمل أشياء ما شرعها الله في صلاته، بأن يركع ركوعًا يضره، أو يضر المأمومين، أو يسجد سجودًا يضره، أو يضر المأمومين، بل يقتصد ويتحرى الاقتصاد. القصد في العبادة هو المطلوب، وعدم التشديد، لا على المأموم، ولا على نفسه، كذلك كونه يصوم دائمًا، ولا يفطر، يصلي الليل كله، كل هذا من التشدد، والنبي نهى عن هذا -عليه الصلاة والسلام- قال: هلك المتنطعون ونهى عن التبتل، كل ذلك لما في التبتل والتشدد من المضرة العظيمة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10146/حقيقة-التشدد-والغلو-المنهي-عنه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42902.mp3","categories":["البدع والمحدثات"]},{"id":11976,"question":"من الجمهورية العربية السورية أحد المستمعين يقول (ع. ك) يسأل سماحتكم عن حكم الصلاة وراء إمام مبتدع: هل الصلاة وراءه جائزة؟ وما العمل إذا لم يكن بالإمكان إبعاد هذا الإمام عن إمامة المسجد؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف إمام مبتدع","answer":"الجواب: إذا كانت بدعته لا توجب كفره؛ فالصلاة صحيحة، مثل كونه يقول: نويت أن أصلي كذا وكذا، وما أشبه هذا من البدع، إذا كانت البدعة لا تكفره؛ فإن الصلاة خلفه صحيحة، ولكن يلتمس من هو أولى منه، وأفضل منه مع المسؤولين، حتى يعين من هو سليم من البدعة.  أما إذا كانت البدعة تكفره؛ فلا يصلى خلفه، كالمبتدع الذي يقول أن القرآن مخلوق، أو يرون دعاء الأموات والاستغاثة بالأموات؛ فهذا كفرٌ أكبر، أو يسبون الصحابة كالرافضة، أو يغلون في أهل البيت كالرافضة، كأن يغلو في علي، وأهل البيت، هذه بدع مكفرة، نسأل الله العافية، لا يصلى خلفه. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10161/حكم-الصلاة-خلف-امام-مبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42917.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":12002,"question":"يقول: بعد الفراغ من دفن الميت، يقوم أحد أقربائه بقراءة شيء من القرآن على قبره، فهل هذا جائز؟","title":"حكم قراءة القرآن على القبر بعد دفن الميت","answer":"الجواب:  لا، ما له أصل، الدعاء فقط، القرآن ما هو بمشروع، لا يقرأ عند القبور، لكن إذا فرغ؛ يقف عليه ويقول: اللهم اغفر له، اللهم ثبته بالقول الثابت، ونحو ذلك، هو والحاضرون، كان النبي ﷺ إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم، واسألوا لهه التثبيت؛ فإنه الآن يسأل هكذا يقول ﷺ يأمر الناس، يقول: استغفروا لأخيكم، واسألوا له التثبيت؛ فإنه الآن يسأل هذا بعد الدفن، أما قراءة القرآن لا، لا يقرأ عليه القرآن؛ لعدم الدليل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10187/حكم-قراءة-القران-على-القبر-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43116.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":12080,"question":"يقول: نحن نصلي في المسجد، وعندما نفرغ من الصلاة نقرأ آية الكرسي، ونسبح الله، ونحمد الله، ونكبر بصوت جماعي، ثم بعد ذلك يقوم الإمام يدعو بصوت مسموع، والمصلون يؤمنون على دعائه، ثم عندما يفرغ من الدعاء يقول: والرحمة لنا ولكم ولوالدينا وأمواتنا وأمواتكم وإلى أموات المسلمين، هل هذا الأمر جائز؟ جزاكم الله خيرًا.","title":"حكم الذكر الجماعي عقب الصلوات","answer":"الجواب:  هذا بدعة، لا أصل له، وليس بجائز، ولكن يقرأ الإنسان لنفسه، يقرأ آية الكرسي بينه وبين نفسه بعد الصلاة، بينه وبين نفسه، يسبح الله ثلاثًا وثلاثين، يحمده ثلاثًا وثلاثين، يكبره ثلاثًا وثلاثين بنفسه، بغير صوت جماعي، كل واحد بنفسه، سواءً سبق أخاه، أو كان بعد أخيه، لا يتحرى أن يكون الصوت جماعيًا لا في التسبيح، ولا في القراءة، بل يقرأ كل واحد آية الكرسي لنفسه، بينه وبين نفسه، ويسبح الله مع نفسه، وإن جهر بذلك مع الذكر؛ فلا بأس؛ لأنه يشرع الذكر بعد الصلاة، رفع الصوت بالذكر بعد الصلاة مشروع، لكن ليس جماعيًا، كل واحد يرفع الصوت بطريقته الخاصة من دون حاجة إلى مراعاة صوت أخيه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10265/حكم-الذكر-الجماعي-عقب-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43513.mp3","categories":["البدع والمحدثات"]},{"id":12276,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع: أنور محمد عيد من الجمهورية العربية السورية، الأخ أنور عرضنا بعض أسئلته في حلقة مضت، وله في هذه الحلقة سؤال واحد يقول فيه: اعتاد كثير من الناس عندنا أن يعملوا للميت بعد ثلاثة أيام من موته مولدًا نبويًا، ويذبحون الذبائح يقدمونها للناس، هل هذا العمل سنة، أم أنه لا يجوز، ولا يستفيد منه الميت؟ أجيبونا مأجورين جزاكم الله خيرًا.","title":"حكم إقامة الموالد والاحتفال بها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فعمل الإنسان مولدًا لأبيه، أو أخيه، أو غيرهما بعد ثلاثة أيام، أو بعد أربعين يومًا، أو بعد أسبوع، أو بعد سنة، كل ذلك بدعة، لا أصل له في الشرع المطهر. فالاحتفال بالموالد مما أحدثه الناس في الإسلام، وكان أول من أحدث ذلك فيما ذكره جماعة من المؤرخين الفاطميون الذين ملكوا المغرب، ومصر مدةً طويلة في القرن الخامس والسادس، في القرن الرابع والخامس، ثم حدث بعد ذلك من آخرين من الناس، فعملوا موالد للنبي ﷺ وللحسن و للحسين ولـفاطمة ولـعلي -رضي الله عنهم- ولآخرين، وكل ذلك من البدع. فالواجب على أهل الإسلام أن يسيروا على نهج نبيهم ﷺ وعلى نهج أصحابه -رضي الله عنهم- ومن تبعهم بإحسان من التابعين، وأتباعهم في القرون المفضلة، وألا يعملوا مولدًا لا للنبي ﷺ ولا لآبائهم، وأمهاتهم، ولا لغير ذلك من الناس، قال الله -جل وعلا- في كتابه العظيم: لَقَدْ كَانََ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] فلنا في الرسول ﷺ أسوة حسنة لم يعمل مولدًا لنفسه، ولم يعمله خلفاؤه الراشدون لهم ولا لنبيهم ﷺ، ولم يعمله الصحابة لا للنبي ﷺ ولا للخلفاء الراشدين ولا لغيرهم، ولم يعمله التابعون ولا أتباع التابعين في القرون المفضلة. فالواجب تركه؛ لأنه بدعة، وقد قال الله سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُُ [الشورى:21] يذمهم بهذا سبحانه، وقال لنبيه ﷺ: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا وَلا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لا يَعْلَمُونَ [الجاثية:18] وقال النبي ﷺ في الحديث الصحيح في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمدد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه الإمام مسلم في صحيحه، وفي الصحيحين عن عائشة -رضي الله عنها- عن النبي ﷺ أنه قال: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد وخرجه مسلم في صحيحه، فقال: من عمل عملًا ليس عليه أمرنا؛ فهو رد. فالواجب على أهل الإسلام الحذر من هذه البدع، ومنها: الاحتفال بالموالد، سواء كان في اليوم الأول أو الثالث أو العاشر أو غير ذلك، وهكذا الاحتفال بالمولد النبوي، على صاحبه أفضل الصلاة والسلام. وهكذا الاحتفال بالموالد الأخرى كمولد علي أو فاطمة، أو الحسن أو الحسين، أو الشاذلي، أو الشيخ عبدالقادر الجيلاني، أو ابن عربي، أو غير هذا كلها بدعة. وممن نبه على هذا جماعة من أهل العلم كـالشاطبي، وشيخ الإسلام ابن تيمية، وآخرين من أهل العلم، نبهوا على هذه البدع، والمطلوب من المسلمين اتباع النبي ﷺ وتعظيمه بطاعة أوامره، وترك نواهيه، لا بالموالد. المقصود اتباع شريعته، وتعظيم أمره، ونهيه والسير على منهاجه -عليه الصلاة والسلام- والسير على من درج عليه أصحابه -رضي الله عنهم- أما إحداث البدع فهي تغضبه، بل تغضب الله أولًا، وتغضبه -عليه الصلاة والسلام- أيضًا؛ لأنها زيادة في الدين، ليس لها أصل، والله يقول سبحانه: وَالسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ [التوبة:100] فالمتبعون بإحسان هم الذين ساروا على نهجه، ولم يزيدوا، ولم ينقصوا، بل تابعوهم على ما كانوا عليه من العمل الصالح، والعلم النافع. وإذا أراد أحد أن يتصدق لأبيه، أو أمه، أو أقاربه بدراهم يعطيها الفقراء، أو ذبيحة يوزعها بين الفقراء، أو طعام يعطيه الفقراء لا بأس يتصدق، أو بنقود يعطيها بعض الفقراء، كل هذا طيب الصدقة مطلوبة. أما إيجاد مولد احتفال بمولد في أي يوم كان هذا هو المنكر، هذا هو البدعة، سواء كان ذلك المولد للنبي ﷺ أو لغيره. وهكذا الاحتفال بليلة سبع وعشرين من رجب؛ لأنها بزعمهم ليلة الإسراء والمعراج، هذا بدعة أيضًا، لا أصل لها في الشرع المطهر، وليلة الإسراء والمعراج غير معلومة، ولو علمت لم يحتفل بها؛ لأن الرسول ﷺ لم يحتفل بها، وهكذا أصحابه، والشيء الذي لم يفعله ﷺ ولا أصحابه يعتبر بدعة، فلو علمنا ليلة الإسراء والمعراج لم نحتفل بها؛ لأن إمامنا وسيدنا محمد -عليه الصلاة والسلام- لم يحتفل بها، وهو القدوة، وهكذا أصحابه، رضي الله عنهم وأرضاهم.  وكل عمل ليس عليه أمره؛ فهو رد، يعني: فهو مردود، ولا يجوز للعاقل التقليد للناس، يقول: الناس فعلوا وأفعل مثلهم، ولو فعله الأكثرون التقليد لا يجوز، الواجب الأخذ بالحجة والدليل، قال الله وقال رسوله، ومن تبع الناس فيما يفعلون من غير نظر الدليل؛ هلك. فالناس الآن كثير منهم يعبدون الأموات، ويستغيثون بأهل القبور، ويطوفون بقبورهم، هل يتبعون هذا الشرك الأكبر، ويبنون المساجد على القبور، وهذا منكر، فلا يجوز اتباع الناس إلا في طاعة الله ورسوله، الله ذم الجاهلية، وذم قريشًا وأشباههم من الكفرة لما بعث نبيه ﷺ وعارضوه بقولهم: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:22] ذمهم بهذا، فليس للعاقل أن يحتج بالآباء والأسلاف، أو بعمل الناس في الباطل، بل يبحث عن الحق، قال الله، وقال رسوله، ويأخذ بالحق الذي قاله الله ورسوله، وإن خالفه أكثر الخلق، فالحق هو الواجب الاتباع، وإن كنت وحدك، قال حذيفة -رضي الله عنه-: يا رسول الله! كنا في جاهلية وشر، فجاءنا الله بهذا الخير على يديك، فهل بعد هذا الخير من شر؟ قال: نعم فقال حذيفة -رضي الله عنه-: وهل بعد ذلك الشر من خير؟ قال: نعم، وفيه دخن قلت: وما دخنه؟ قال: قوم يهدون بغير هديي ويستنون بغير سنتي تعرف عنهم وتنكر قلت: يا رسول الله! وهل بعد ذلك الخير من شر -يعني: هل بعد الخير الذي فيه دخن هل بعده شر؟- قال: نعم، دعاة على أبواب جهنم، من أجابهم إليها؛ قذفوه فيها قلت: يا رسول الله! صفهم لنا؟ قال: هم من جلدتنا ويتكلمون بألسنتنا -يعني: من العرب- قلت: فما تأمرني يا رسول الله! إن أدركني ذلك؟ قال: تلزم جماعة المسلمين وإمامهم قلت: فإن لم يكن لهم جماعة، ولا إمام؟ قال: فاعتزل تلك الفرق كلها، ولو أن تعض على أصل شجرة؛ حتى يدركك الموت وأنت على ذلك يعني: وأنت على الحق. وقال ابن مسعود -رضي الله عنه-: لـعمرو بن ميمون، عمرو بن ميمون الأودي - قال: يا عمر ! الجماعة ما وافق الحق، وإن كنت وحدك.. الجماعة ما وافق الحق، وإن كنت وحدك. فالحق هو الواجب الاتباع، فلو كنت في بلد ما يصلي فيه أحد، لا تخلي الصلاة؛ صل أنت ولو وحدك، وإذا كنت في بلد لا يصومون رمضان؛ صم أنت ولو وحدك، وإن كنت في بلد لا يزكون؛ زك أنت، ولو كنت وحدك، فالحق واجب الاتباع، ولو كنت في بلد لا يذكرون الله؛ اذكر الله أنت قل: لا إله إلا الله، سبحان الله، والحمد لله، ولو أنكروا عليك، ولو سخروا منك، وإذا كنت في بلد لا يبرون والديهم؛ بر والديك أنت، وهكذا بقية أمور الدين، فالحق يجب اتباعه، ولو كنت وحدك، والله المستعان، نعم. المقدم: الله المستعان، نسأل الله أن يهيئ لهذه الدعوة القبول، وأن يوفق المسلمين لاتباع منهج الإسلام، إنه على كل شيء قدير.  الشيخ: نسأل الله ذلك.. نسأل الله أن يوفق المسلمين لما فيه رضاه، نسأل الله أن يصلح أحوالهم، نسأل الله أن يولي عليهم خيارهم، نسأل الله أن يسهل لهم دعاة الحق حتى يفقهوهم في الدين، يقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين ويقول ﷺ: من دل على خير؛ فله مثل أجر فاعله ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]. فالواجب على العلماء أينما كانوا في البلاد الإسلامية، وفي غيرها، الواجب على علماء الحق، علماء الكتاب والسنة، الواجب عليهم أن يبلغوا رسالة الله، وأن يعلموا الناس دين الله، وأن يبصروهم بالحق، ولا سيما معنى شهادة: أن لا إله إلا الله، وأن محمدًا رسول الله، وأن يعلموهم أن الواجب عليهم إخلاص العبادة لله وحده، وأن لا يعبدوا معه سواه، لا ملكًا مقربًا، ولا نبيًا مرسلًا، وأن يحفظوا الصلوات الخمس، ويدينوا بها، ويستقيموا عليها في أوقاتها، وأن يؤدوا الزكاة كما فرض الله، وأن يصوموا رمضان كما فرض الله، وأن يحجوا البيت مع الاستطاعة كما أوجب الله، هكذا، نسأل الله للمسلمين الهداية والتوفيق، وصلاح النية والعمل. المقدم: اللهم آمين، جزاكم الله خيرًا. الشيخ: الله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/10476/حكم-اقامة-الموالد-والاحتفال-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_451/45101.mp3","categories":["البدع والمحدثات"]},{"id":12494,"question":"يسأل ويقول: في يوم الجمعة بعد أن يسلم الإمام، ونسلم بعده يقرأ آية الكرسي، ثم يسبح الله، ويحمده، ويكبره، ونحن كذلك وراءه، ثم يرفع يديه بالدعاء، ونحن معه، ثم نقرأ سورة الفاتحة، فهل في عملنا هذا شيء، أم يجب أن يختم كل فرد الصلاة بمفرده، ولا يختمها مع الإمام؟ جزاكم الله خيرًا.","title":"حكم تأدية الأذكار بعد صلاة الجمعة بصوت جماعي","answer":"الجواب:  هذا العمل بدعة لا يجوز، وليس من سنة النبي -عليه الصلاة والسلام- كونكم تبدؤون جميعًا بعد السلام بآية الكرسي، ثم تسبحون جميعًا، ثم ترفعون يدكم، كل هذا لا أصل له، هذه بدعة. وإنما السنة إذا سلم الإمام، وهكذا المأموم، وهكذا المنفرد، السنة للجميع بعد السلام أن يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام تباركت يا ذا الجلال والإكرام، هكذا كان النبي يفعل -عليه الصلاة والسلام-يبدأ بهذا، ثم ينصرف إلى الناس -عليه الصلاة والسلام- فيقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد. هذه السنة للإمام والمأموم والمنفرد بعد السلام من الصلوات الخمس، ولا يشرع رفع اليدين في هذه الحال، وكل واحد يذكر الله بنفسه، ما يكون ذكرًا جماعيًا، كل واحد .. الإمام يذكر الله في نفسه، والمأموم كذلك، كل واحد يذكر الله في نفسه كما شرع الله. أما أن يأتي الجميع بذلك بصوت جماعي؛ فهذا من البدع، أو يبدأ بآية الكرسي؛ فهذا خلاف السنة، بل يبدأ بالاستغفار ثلاثًا، ويقول: اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام هكذا ثبت عن النبي ﷺ من حديث ثوبان، وثبت عنه ﷺ من حديث ابن الزبير، ومن حديث المغيرة أنه كان يقول بعد ذلك: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد روى بعض هذه الأذكار ابن الزبير.","link":"https://binbaz.org.sa/fatwas/10691/حكم-تادية-الاذكار-بعد-صلاة-الجمعة-بصوت-جماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40602.mp3","categories":["البدع والمحدثات"]},{"id":12579,"question":"رسالة وصلت إلى البرنامج من المستمع أحمد البابطين من الدمام يسأل في سؤاله الأول: ويقول: بم تنصحونا في كيفية التعامل مع المبتدعة الذين نراهم، ونتكلم معهم، ونتعامل معهم كل يوم تقريبًا؟","title":"كيفية التعامل مع أهل البدع","answer":"الجواب:  الواجب هجرهم على بدعتهم، إذا أظهروا البدعة؛ فالواجب هجرهم بعد النصيحة والتوجيه، فإن المسلم ينصح أخاه، ويحذره مما حرم الله عليه من البدع والمعاصي الظاهرة، فإن تاب وإلا استحق أن يهجر، ولا يعامل؛ لعله يتوب، لعله يندم، لعله يرجع إلى الصواب، إلا إذا كان الهجر يترتب عليه ما لا تحمد عقباه، فإنه يتركه إذا كان تركه أصلح في الدين، وأكثر في الخير، وأقرب إلى النجاح؛ فإنه لا يهجره، بل يداوم نصحه وتحذيره من الباطل، ولا يهجره رجاء أن يهديه الله بسبب ذلك. فالمؤمن كالطبيب إذا رأى العلاج نافعًا؛ فعله، وإذا رأى أنه ليس بنافع؛ تركه، فالهجر من باب العلاج، فإن كان الهجر يؤثر خيرًا وينفع؛ هجر، وكان ذلك من باب العلاج؛ لعله يتوب، ولعله يرجع عن الخطأ إذا رأى من إخوانه أنهم يهجرونه. أما إذا كان الهجر يسبب مزيدًا من الشر، وكثرة أهل الشر وتعاونهم، فإنه لا يهجر، ولكن يديم النصح والتوجيه، وإظهار الكراهة لما عمل، ولا يبين له موافقته على باطله، ولكن يستمر في النصيحة والتوجيه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10789/كيفية-التعامل-مع-اهل-البدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41206.mp3","categories":["البدع والمحدثات"]},{"id":12587,"question":"عادتنا ونحن نصلي جماعة مع الإمام، وبعد صلاة الجماعة، فإننا نذكر الله جميعًا، فهل هذا صحيح؟ وهل الذكر بجماعة أفضل، أم كل على حدة؟","title":"حكم الذكر الجماعي بعد الصلوات المفروضة","answer":"الجواب:  ليس بصحيح، بل هذا بدعة، كل واحد يذكر الله في نفسه، أما أن يذكروا الله ذكرًا جماعيًا بصوت واحد؛ فهذا من البدع، وعلى كل واحد إذا سلم يذكر الله بنفسه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10784/حكم-الذكر-الجماعي-بعد-الصلوات-المفروضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45707.mp3","categories":["البدع والمحدثات"]},{"id":12633,"question":"يقول بعض العامة بعد وفاة قريب لهم بأربعين يومًا يقيمون ما تعارفوا على تسميته بالأربعين، وفي هذه الأربعين يقومون بدعوة الناس، ويقوم المدعوون بقراءة بعض الأذكار، وبعد تناول الطعام يقومون بتلاوة القرآن الكريم، ويدعون بثواب القراءة للميت، فما حكم الشرع في هذا الفعل، هل هو جائز، أم هو محرم؟","title":"حكم الاجتماع بعد وفاة الميت بأربعين يوماً لتلاوة القرآن","answer":"الجواب:  هذا لا يجوز، هذا من المأتم، ومن أعمال الجاهلية، لا يجوز لا في الأربعين، ولا في اليوم الأول، ولا في الأسبوع الثاني، ولا على رأس السنة، كله من البدع والخرافات، ومن أعمال الجاهلية، لا تجوز إقامة هذا العمل، ولكن يدعى للميت، ويتصدق عنه، هذا طيب، أما إقامة مأتم على رأس الأربعين، أو على رأس الأسبوع، أو على رأس الشهر، أو رأس السنة كل هذا لا أصل له. يقول جرير بن عبدالله البجلي : كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة ولما توفي جعفر بن أبي طالب شهيدًا في سبيل الله، وجاء نعيه إلى النبي ﷺ لم يتخذ مأتمًا لا على رأس الأسبوع، ولا في أول يوم، ولا رأس الأربعين .. وهكذا الصحابة  لم يفعلوا ذلك لنبيهم ﷺ ولا للصديق، ولا عمر، ولا عثمان، ولا علي، ولا غيرهم، فالواجب ترك ذلك؛ لأنه من عمل الجاهلية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10842/حكم-الاجتماع-بعد-وفاة-الميت-باربعين-يوما-لتلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41506.mp3","categories":["البدع والمحدثات"]},{"id":12637,"question":"سؤال آخر طويل بعض الشيء سماحة الشيخ تقول فيه: هناك شيء منتشر لدينا، ويسمى الحضرة، ربما لا تفهموا ما هي الحضرة، ولكن سأشرح لكم ما يحدث في هذه الحضرة، ربما تعرفونها بعد ذلك، الحضرة: هي شيخ يأتي ومعه أتباعه، ومعهم بنادير -دف- ويجتمع عليهم الناس من كل حدب وصوب، ويكون في يوم الخميس في الليل، أي اليوم الذي يصبح فيه الجمعة، ثم يشعل نارًا كبيرة، ثم يبدأ ذلك الشيخ بالقرع على الدف هو وأتباعه، ويقول كلامًا غريبًا، ويستنجد بالله، وبالأولياء الصالحين لدينا في ليبيا مثل: سيدي عبدالسلام الأسمر، وسيدي مرعي، وغيرهم، ثم يبدأ بعض الحاضرين بالبدأ -بالمدح- مع الشيخ، ويغمى على كثير من الحاضرين من النساء والرجال، ويبدأ الشيخ بالضرب المبرح على من يغمى عليهم، ويقول له: أخرج من المسلم يا كافر، ويقصد بذلك أنه يكلم الجن الذي سكن الإنسي المغمى عليه، والنساء يمسك المرأة من شعر رأسها، ويبدأ بالضرب على وجهها، وهكذا تبدأ هذه المسرحية وتنتهي!!  هل هذه الأفعال محرمة على من يحضرها؟ الرجاء منكم الإفادة، علمًا بأن الحاضرين كما يقال بالآلاف، ويبنون خيامًا، وكل عائلة تذبح شاة، أو ماعزًا، فالرجاء منكم عرض سؤالي هذا، وتوجيهنا وتوجيه المسلمين الذين توجد عندهم هذه الأحوال، جزاكم الله خيرًا؟","title":"حكم ما يسمى بالحضرة التي يفعلها الصوفية","answer":"الجواب:  هذا العمل منكر عظيم، وهذا من أعمال بعض الصوفية، ولا يجوز حضور هذا العمل، والاستنجاد بالأولياء، والاستغاثة بالأولياء من الشرك الأكبر، ومن عبادة غير الله  وضرب الطبول، أو الدفوف هذه من طرق الصوفية المنكرة المحدثة. فالواجب الحذر من ذلك، والواجب ترك هذا العمل، وعدم حضوره، وإنكاره على من حضر، لما فيه من الشرور الكثيرة، فهو بدعة، وفيه أيضًا: منكر وهو ضرب الدفوف، وفيه منكر أعظم وهو الشرك بالله، والاستنجاد بالأولياء، فهذا كله شر عظيم. فالواجب على المسلمين ترك هذا العمل، والحذر منه، وعدم حضوره، وإنكاره على من فعله؛ لأنه بدعة منكرة، ومشتملة على نوع من الشرك الأكبر، هو الاستنجاد بالأولياء، ودعاؤهم، والاستغاثة بهم، وهذا من الشرك الأكبر، فإذا قال: يا سيدي فلان! يا عبدالسلام! أو يا سيدي الحسين! أو يا سيدي رسول الله! أو يا سيدي الشيخ عبدالقادر! أغثني، أو انصرني، أو اشف مريضي، أو رد غائبي، أو أنا في جوارك وحسبك، أو ما أشبه ذلك، هذا كله من الشرك الأكبر، والله يقول -جل وعلا-: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] ويقول سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. فهؤلاء قد اتخذوا مع الله آلهة أخرى، يندبونهم، ويستغيثون بهم، فوقعوا في الشرك الأكبر مع ما هم فيه من البدع والخرافات الضالة التي لا أساس لها. فالواجب الحذر من ذلك غاية الحذر، والواجب عدم حضور هذا المنكر، وإنكاره على من فعله، مع ما فيه من الشرك الأكبر نعوذ بالله من ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10847/حكم-ما-يسمى-بالحضرة-التي-يفعلها-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41511.mp3","categories":["البدع والمحدثات"]},{"id":12665,"question":"من المستمع ناجي طه حسين رسالة ضمنها جمعًا من الأسئلة من بينها سؤال يقول فيه: بعض العلماء يقولون: إن الموالد ليست صحيحة، فهل هذا صحيح، أم لا؟","title":"هل يصح الاحتفال بالموالد؟","answer":"الجواب:  نعم، الاحتفال بالموالد بدعة، لا يجوز الاحتفال بالموالد لا مولد النبي ﷺ ولا غيره؛ لأن الرسول  قال: إياكم ومحدثات الأمور؛ فإن كل محدثة بدعة، وكل بدعة ضلالة وقال -عليه الصلاة والسلام- في خطبة يوم الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة والاحتفال بالموالد بدعة ما فعله الرسول ﷺ ولا أصحابه، رضي الله عنهم وأرضاهم. ويكفي المؤمن التأسي بسنته ﷺ والسير على منهاجه، وعدم الإحداث، فمحبة النبي ﷺ ليست بالبدع، ولكن باتباع طريقه، وامتثال أوامره، وترك نواهيه، والصلاة عليه، والسلام عليه عند ذكره -عليه الصلاة والسلام- وفي كل وقت، أما إحداث البدع فذلك مما يغضبه -عليه الصلاة والسلام- ومما نهى عنه وأنكره -عليه الصلاة والسلام- وهو مما يغضب الله -عز وجل- والله سبحانه أنكر على أهل البدع، قال سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].  فالواجب على كل مسلم أن يتبع ولا يبتدع، عليه أن يتبع الشريعة، ويكفي والحمد لله، أما الابتداع فهو شر وبلاء، فالدين كامل بحمد الله، الله أكمل الدين، فليس للناس أن يحدثوا شيئًا ما شرعه الله، لا الاحتفال بالموالد، ولا غيرها. ومن ذلك البناء على القبور، واتخاذ المساجد عليها هذه بدعة، ومن وسائل الشرك، ومن ذلك تجصيصها، واتخاذ القباب عليها، والستور هذا بدعة أيضًا، ومن أسباب الشرك ووسائله، فالواجب على أهل الإسلام أن يحذروا البدع، وأن يبتعدوا عنها حتى لا يخالفوا نبيهم -عليه الصلاة والسلام- وحتى يتبعوه فيما أمر به، وفيما نهى عنه -عليه الصلاة والسلام- نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10875/هل-يصح-الاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45817.mp3","categories":["البدع والمحدثات"]},{"id":12775,"question":"بعد هذا رسالة وصلت إلى البرنامج من الجمهورية العربية السورية باعثها المستمع عمر مرعي، الأخ عمر له جمع من الأسئلة، في أحدها يسأل سماحتكم عن التلفظ بالنية، فمثلًا إذا أراد أن يصلي سنة الصبح أن يقول: نويت أن أصلي سنة الصبح، أو نويت أن أصلي فرض كذا، جزاكم الله خيرًا؟","title":"حكم التلفظ بالنية قبل الصلاة","answer":"الجواب:  التلفظ بالنية ليس له أصل في الشرع، بل هو بدعة؛ لقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد ولم يكن النبي ﷺ يتلفظ بالنية، ولا أصحابه، النية محلها القلب، تنوي بقلبك، الصلاة الصيام والوضوء وغير ذلك، ويكفي القلب، والحمد لله، ولا حاجة إلى أن تقول: نويت أن أصلي كذا، أو نويت أن أتوضأ، أو أن أطوف، أن أصوم، النية محلها القلب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10989/حكم-التلفظ-بالنية-قبل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42002.mp3","categories":["البدع والمحدثات"]},{"id":12803,"question":"يسأل ويقول: المديح النبوي مع دق الدفوف، والضرب على البطون بالسيوف والعصي على الطريقة الرفاعية، هل هي حرام، أم حلال؟","title":"حكم مدح النبي عليه الصلاة والسلام مع دق الدفوف","answer":"الجواب:  هذا منكر وحرام وبدعة في الدين، ومن خرافات الصوفية، المديح يكون بالكلام الطيب من دون دفوف، ومن دون ضرب للبطون والرؤوس، بل بالكلام الطيب يقال: هو خاتم النبيين، هو أفضل الأنبياء، هو أعبد الناس، هو أصدق الناس، كلام طيب، أما الزيادة بأن يدعى من دون الله، أو يستغاث به من دون الله هذا شرك أكبر، أو يقال: إنه يعلم الغيب هذا كفر، لكن يمدح بالحق، يمدح بما ثبت عنه أنه أهل له -عليه الصلاة والسلام- من كونه أصدق الناس، من كونه بلغ الرسالة، أدى الأمانة، من كونه أفضل الرسل -عليه الصلاة والسلام- إلى أمثال هذه الأشياء الصادقة. أما أن يمدح بأنه يعلم الغيب، أو أنه يجوز أن يدعى من دون الله، أو أنه خلق من النور، أو من عرش الرحمن، هذا باطل، كذب، خلق من ماء مهين مثل غيره من الناس، ولم يخلق من النور، وليس يعلم الغيب -عليه الصلاة والسلام- ولا يجوز أن يعبد من دون الله، لا أن يدعى من دون الله، ولا يستغاث به، ولا يحلف به -عليه الصلاة والسلام- كل هذا منكر، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11017/حكم-مدح-النبي-عليه-الصلاة-والسلام-مع-دق-الدفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46208.mp3","categories":["البدع والمحدثات"]},{"id":12862,"question":"يسأل سماحة الشيخ عن التسبيح الجماعي، إذ يسبح الإمام والمأمومون يسبحون من بعده؟","title":"حكم التسبيح الجماعي","answer":"الجواب:  هذا بدعة لا أصل له، بل كل واحد يسبح لنفسه، الإمام يسبح لنفسه، وكل واحد منهم كذلك يسبح لنفسه، ويذكر الله لنفسه، أما الجماعي فهذا بدعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11077/حكم-التسبيح-الجماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46512.mp3","categories":["البدع والمحدثات"]},{"id":12873,"question":"المستمع: عيسى عبدالنبي عبدالرحمن من جمهورية مصر العربية محافظة البحيرة بعث برسالة يقول فيها: هل قراءة القرآن على الميت حلال، وهل الذبيحة التي يذبحها أهل الميت قبل خروجه إلى الدفن لها أجر يلحق الميت في قبره، نرجو الإفادة جزاكم الله خيرًا؟","title":"حكم قراءة القرآن على الميت والذبيحة التي تذبح قبل الدفن","answer":"الجواب:  أولًا التسمي بـ (عبدالنبي) لا يجوز، فكون اسم أبيك عبدالنبي هذا خطأ، الأسماء تكون بالله، أجمع العلماء على أنه لا يجوز التعبيد لغير الله، فلا يقال: عبدالنبي، ولا عبدالكعبة، ولا عبدعمر، ولكن يقال: عبدالله، عبدالرحمن، عبداللطيف، وأشباه ذلك من أسماء الله  فالواجب على أبيك إن كان حيًا أن يغيره، فيقول: عبدرب النبي يغير اسمه بعبدرب النبي، أو عبدالله، أو عبدالرحمن يغير. أما قراءة القرآن على الميت فلا أصل لها، لا يقرأ على الميت، ولا عند القبر، كل هذا بدعة، أما قبل الموت في حال كونه محتضرًا؛ هذا لا بأس أن يقرأ عنده سورة يس، أو غيره من القرآن؛ لأنه روي عن النبي ﷺ أنه قال: اقرؤوا على موتاكم يس موتاكم يعني: محتضريكم، المحتضر يقال له: ميت، ومن هذا قول النبي ﷺ: لقنوا موتاكم لا إله إلا الله يعني: من حضره الموت يقال له: قل: لا إله إلا الله؛ حتى يكون آخر كلامه لا إله إلا الله، أما كونه بعد الموت يقرأ عليه لا، غير مشروع، كذلك عند القبر غير مشروع. فينبغي للمؤمن أن يتأدب بالآداب الشرعية، وأن يحرص على التمسك بما شرع الله لعباده، ويتواصى مع إخوانه في ذلك؛ لأن الله -جل وعلا- قال: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]. وهكذا الذبح بعد الموت غير مشروع، كونه يذبح يقيم مأتمًا، أو يتصدق بها عند الموت، هذا لا دليل عليه، لكن إذا تصدق عنه بعد ذلك -لا عند الموت- يتصدق عنه بدراهم يتصدق عنه بطعام، أو ذبيحة يوزعها على الفقراء، لا عند الموت، بل في أوقات أخرى، فلا بأس بذلك؛ لأن الصدقة تنفع الميت، أما اعتقاده أنه يذبح عند الموت ذبيحة؛ فهذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11088/حكم-قراءة-القران-على-الميت-والذبيحة-التي-تذبح-قبل-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46605.mp3","categories":["البدع والمحدثات"]},{"id":12898,"question":"في نهاية هذه الحلقة نعود إلى رسالة المستمع: حسن أسميط من لبنان، يسأل في هذه الحلقة، ويقول: تبنى القبور عندنا من الخفان، والرخام، وتبنى مدافن على شكل بيوت تحت الأرض يوضع فيها الأموات؟ هل هذا العمل جائز؟","title":"حكم البناء على القبور واتخاذ المدافن","answer":"الجواب:  أما البناء على القبور، واتخاذ البنايات عليها والتجصيص، هذا منكر لا يجوز، الرسول ﷺ نهى أن يبنى على القبر، وأن يجصص، وأن يقعد عليه؛ لأن هذا من وسائل الشرك والغلو، ولا يبنى عليها مسجد، ولا قبة أيضًا. أما جعل حفرة في الأرض، يجعل فيها أموات، هذا خلاف السنة، السنة أن يكون كل قبر وحده، كل ميت لوحده في قبر لحاله، يلحد له، ويوضع في قبره على حدة، هذا هو السنة كما فعله النبي ﷺ في المدينة، وفعله المسلمون، كل واحد يحفر له حفرة واحدة، ويلحد له في قبلي القبر، يجعل في اللحد، هذا هو المشروع، لكن إذا دعت الضرورة لكثرة الأموات، ومشقة الدفن، لكل واحد وحده، لا مانع من أن يجمع الاثنان والثلاثة في قبر واحد، كما فعله النبي ﷺ يوم أحد لما كثروا الأموات. فالحاصل: أن السنة أن كل واحد يدفن لوحده بما تيسر في الأرض، واستطاع الناس ذلك، ولا يدفن اثنان جميعًا، ولا ثلاثة جميعًا، ولا أكثر، لكن إذا كان عند الضيق والمشقة؛ فإنه لا مانع أن يدفن الاثنان والثلاثة جميعًا في قبر واحد، ويقدم أفضلهم، يقدم أقرؤهم للقرآن إلى القبلة، كما فعله النبي ﷺ، يقدم الأقرأ، والأكثر قرآنا إلى القبلة. نعم.","link":"https://binbaz.org.sa/fatwas/11113/حكم-البناء-على-القبور-واتخاذ-المدافن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46713.mp3","categories":["البدع والمحدثات"]},{"id":12899,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من لبنان، وباعثها المستمع: حسن الصمريد، الأخ حسن عرضنا جزءًا من أسئلته، وفي هذه الحلقة بقي له مجموعة أخرى، من بين أسئلته في هذه الحلقة يقول: عندما يتوفى مسلم يقرؤون عليه سورة يس على المقبرة، وفي المنزل لمدة أسبوع، ويوم ذكرى مرور أربعين يومًا على وفاته، هل هذا جائز؟ وجهوا الناس حيال هذا الموضوع، فهو منتشر بكثرة؟ جزاكم الله خيرًا.","title":"حكم قراءة يس على الميت بعد موته","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا العمل الذي سأل عنه السائل بدعة، لا أصل له، فلا يشرع أن يقرأ على الميت بعد موته، لا في البيت، ولا في المقبرة، ولا على رأس الأربعين من وفاته، ولا في غير ذلك بهذا القصد، بل هذه من البدع التي أحدثها الناس، وإنما المشروع أن يقرأ عنده حين الاحتضار قبل أن يموت. إذا كان محتضرًا؛ شرع أن يقرأ عنده، وإذا قرئ عنده سورة يس؛ فذلك حسن؛ لأنه ورد فيها بعض الأحاديث: اقرؤوا على موتاكم يس وإن كان في سنده كلام، لكن لا بأس، قد يتعظ بهذا، وقد يستفيد من هذا قبل أن يموت، كما قال ﷺ: لقنوا موتاكم لا إله إلا الله يلقن، يقال له: قل: لا إله إلا الله، حتى يختم له بها، وفي الحديث: من كان آخر كلامه لا إله إلا الله؛ دخل الجنة فذلك من أسباب دخول الجنة إذا مات على التوحيد والإيمان صادقًا مخلصًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11114/حكم-قراءة-يس-على-الميت-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46801.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":12902,"question":"أيضًا يبدو أن أخانا يعرف كثيرًا من بدع القبور، يقول: هل تجوز قراءة القرآن على الميت في المقبرة؟","title":"حكم قراءة القرآن على الميت في المقبرة","answer":"الجواب:  تقدم أنه لا يقرأ على الميت، لا يقرأ في القبور، ولا على الموتى، ما فعل ذلك الرسول الله ﷺ ولا أصحابه، ولكن إذا زارهم؛ يسلم عليهم، يقول: السلام عليكم يا أهل القبور! يغفر الله لنا ولكم، أنتم سلفنا، ونحن بالأثر وإن شاء قال: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هكذا كان النبي يفعل ويعلم أصحابه، عليه الصلاة والسلام.  أما أنه يقرأ على القبور، أو يقرأ عند القبور، أو يصلي عند القبور كل هذا بدعة، أو يطوف عند القبور، ويطوف بأهلها، كل هذا بدعة، وأعظم من ذلك أن يدعوهم، أو يستغيث بهم، كونه يدعو الميت، أو يستغيث به، أو ينذر له، أو يذبح له، كل هذا من الشرك الأكبر، فإذا قال: يا فلان! يا سيدي فلان! أو يا ولي الله! فلان انصرني، أو اشف مريضي، أو المدد المدد، أو ما أشبه ذلك مما يفعله عباد القبور، هذا من الشرك الأكبر -نسأل الله العافية- فيجب الحذر من هذه الأمور نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11117/حكم-قراءة-القران-على-الميت-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46804.mp3","categories":["البدع والمحدثات"]},{"id":12993,"question":"ننتقل إلى رسالة بعث بها السائل صالح أحمد من اليمن يقول: سماحة الشيخ! نسأل عن أولئك الناس عندما يتوجهون إلى الصلاة، وعندما يتوجهون ينتظر حوالي خمس دقائق حتى يكبر تكبيرة الإحرام، فهل هذا صحيح عندما يتوجه يكبر تكبيرة الإحرام حالًا، أم يبدأ يقرأ التوجيه، ثم يكبر تكبيرة الإحرام، نرجو منكم التوجيه؟","title":"عدم ثبوت ذكر قبل تكبيرة الإحرام في الصلاة","answer":"الجواب:  المشروع أنه يعمد الصفوف بالاستواء، يأمرهم يلتفت إليهم، يمينًا وشمالًا، يقول لهم: استووا، تراصوا، أقيموا الصفوف حتى يعتدلوا، فإذا اعتدلوا، واستقاموا؛ كبر، هذا هو السنة، وليس أمام التكبير ذكر مشروع بعد الإقامة، ولكن يلاحظ المصلين، ويأمرهم بالاستواء، وإقامة الصفوف، وعدم تقدم بعضهم على بعض، تكميل الصف الأول فالأول، ثم يكبر كما كان النبي يفعل، عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11210/عدم-ثبوت-ذكر-قبل-تكبيرة-الاحرام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50406.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":13006,"question":"يقول: عندنا عادة وهي: بعد صلاة كل جمعة نقوم بعد الصلاة بصلاة الظهر، وذلك بعد الانتهاء من صلاة الجمعة، فهل يجوز هذا، أم أنه بدعة؟","title":"حكم صلاة الظهر بعد صلاة الجمعة","answer":"الجواب:  صلاة الظهر بعد الجمعة بدعة، لا أصل لها، لم يفعلها سلف الأمة، لا الصحابة، ولا من بعدهم من سلف الأمة، بل هي بدعة ونوع وسوسة، كأنهم يقولون: لا ندري أصحت الجمعة، أم لا، وهذا وسواس لا وجه له، وشك لا وجه له. فالواجب على المؤمن حسن الظن بالله، وحسن الظن بما درج عليه المسلمون قبله، وعدم الشك الذي لا وجه له، ولا موجب له، فصلاة الجمعة كافٍ، والحمد لله، والله ما فرض على العباد إلا خمس صلوات في اليوم والليلة، فإذا صليت الظهر بعد الجمعة؛ جعلتها ستًا، وهذا لا يجوز، فصلاة الظهر بعد الجمعة بدعة، لا تجوز أبدًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11223/حكم-صلاة-الظهر-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47102.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":13015,"question":"مستمع بعث برسالة ضمنها جمعًا من الأسئلة، وهو الأخ أبو أحمد من الجمهورية العربية اليمنية، أبو أحمد يسأل عن الأشياء التالية: يقول: ما حكم الإسلام في الأمور الآتية: احتفال بعض الناس بأعياد ميلادهم، أي: اليوم الذي يولد المرء فيه، وتكرارهم للاحتفال كلما مر على هذا اليوم عام؟","title":"ما حكم الإسلام في احتفال بعض الناس بأعياد ميلادهم؟","answer":"الجواب:  الاحتفالات بالموالد بدعة لا أصل لها، وتشبه بـاليهود والنصارى؛ فلا يجوز ذلك، لا بميلاد الأنبياء كنبينا محمد ﷺ ولا بغيرهم، ولا يجوز للإنسان أن يحتفل بمولده، ولا مولد أبيه، ولا أمه، كل هذا من البدع المنكرة إذا تعبد بها؛ فهي بدعة، وإذا فعلها استحسانًا؛ فقد شابه المشركين من اليهود والنصارى في ذلك، فهي ممنوعة للتعبد وممنوعة للتشبه، وقد قال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد، وقال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا؛ فهو رد يعني: فهو مردود، وليس هذا من عمله ﷺ وليس في دينه، وهو أنصح الناس -عليه الصلاة والسلام- وأكملهم بلاغًا، فلم يقل للناس: احتفلوا بمولدي، ولم يفعله هو ﷺ ولا فعله الخلفاء الراشدون، ولا بقية الصحابة، ولا السلف في القرن الأول والثاني والثالث، فهو بدعة منكرة، ومن أسباب الشرك، فإن بعض الناس إذا احتفل بمولد يدعو النبي ﷺ ويدعو المحتفل به، ويستغيث به، ويطلبه المدد، وهذا شرك أكبر، نسأل الله العافية.  وربما ظن بعضهم أن النبي ﷺ يحضر؛ فيقومون له، ويقولون: حضر النبي ﷺ وهذا أيضًا من الجهل العظيم، والباطل الواضح. فالاحتفال بالموالد إن كان على سبيل التعبد؛ فهو بدعة منكرة، وإن كان على سبيل التشبه بأعداء الله اليهود والنصارى؛ فهو أيضًا منكر، فهو بين أمرين بين بدعة، وتشبه بأعداء الله؛ فلا يجوز مطلقًا، لا بمولدك، ولا بمولد أبيك، ولا أخيك، ولا بمولد الأنبياء، ولا بمولد الصالحين، بل هذا كله من البدع التي أحدثها الناس، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11232/ما-حكم-الاسلام-في-احتفال-بعض-الناس-باعياد-ميلادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47111.mp3","categories":["البدع والمحدثات"]},{"id":13083,"question":"في سؤاله الثاني يقول: ما هي الأسباب التي تؤدي إلى نشر الخرافات، ونشوء الوثنيات بين الناس، وجهونا في هذا السؤال؟","title":"أسباب انتشار الخرافات والوثنيات بين الناس","answer":"الجواب:  الأسباب: قلة العلم، وكثرة الجهال، وقلة الناصحين لله ولعباده، والطمع في المال والشهرة، وما يقع من الحسد والبغضاء بين الناس، كلها أسباب للشر، فالإنسان إذا لم يكن عنده تقوى لله، ودين يحميه؛ فعل ما تهواه نفسه من ظلم وعدوان، ودعوة إلى الباطل، ونشر البدع والخرافات؛ لأنه ليس عنده تقوى تمنعه، وخوف من الله يحجزه، نسأل الله العافية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11300/اسباب-انتشار-الخرافات-والوثنيات-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50715.mp3","categories":["البدع والمحدثات","نواقض الإسلام"]},{"id":13092,"question":"بالنسبة -يا سماحة الشيخ- إلى قراءة القرآن عند الدفن؟","title":"حكم قراءة القرآن عند دفن الميت","answer":"الجواب:  بدعة ما لها أصل، لا يقرأ عند الدفن قرآنًا، القرآن محله المساجد والبيوت ما هو بمحل القبور، ولهذا في الحديث الصحيح يقول ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا؛ فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة دل على أن القبور ما هي بمحل صلاة، ولا محل قراءة، القراءة والصلاة محلها البيوت والمساجد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11309/حكم-قراءة-القران-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50803.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13146,"question":"السائل الذي رمز لاسمه بـ (ع. ع) يقول: هل يجوز الدعاء الجماعي بعد دفن الميت؟","title":"هل يجوز الدعاء الجماعي بعد دفن الميت؟","answer":"الجواب:  أما كون الدافنين الذي يعتمد أحدهم ذلك فيقول: اجتمعوا حتى أدعو وتؤمنوا، هذا لا نعلم له أصلًا، لا أعلم له أصلًا عن السلف الصالح. أما لو دعا على قبر، وقال من حوله: آمين، سمعه يدعو قال: آمين من غير قصد؛ فلا حرج في ذلك، إذا أمن الإنسان على دعاء أخيه عند دفن الميت، اللهم اغفر له، وثبته بالقول الثابت، فقال بعض الحاضرين: آمين آمين؛ فلا بأس، أما قصد ذلك، والاتفاق عليه أن هذا يدعو، وهؤلاء يؤمنون؛ فهذا لا أعلم له أصلًا عن السلف الصالح، فتركه أولى وأحوط. أما إذا أمن من غير قصد، أمن لأنه مشروع أن يدعو للميت، فإذا دعا للميت بعد الدفن، وسمعه بعض إخوانه، وقال: آمين، فلا حرج في ذلك؛ لأنه دعاء بخير، وتأمين على خير، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11400/هل-يجوز-الدعاء-الجماعي-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":13187,"question":"على بركة الله نبدأ هذا اللقاء بسؤال من أحد الإخوة المستمعين يقول في هذا  قال رسول الله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال أيضًا: عليكم بسنتي وسنة الخلفاء الراشدين من بعدي وقد كان في زمان الخليفة عثمان  أذان واحد، ثم زاد الأذان الثاني لصلاة الجمعة، هل هذه الزيادة تعتبر من البدع، أم من السنة؟ وما هي البدع؟ وما هي أقسامها مأجورين؟","title":"الحث على اتباع سنة الخلفاء الراشدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه الأحاديث التي ذكرها السائل أحاديث صحيحة، يقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد متفق على صحته من حديث عائشة -رضي الله عنها- وفي لفظ: يقول ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد أخرجه مسلم في صحيحه، ويقول ﷺ: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة. والبدعة: هي التي يحدثها الناس في الإسلام في الطاعات والقربات، يقال لها: بدعة، ما أحدثه الناس في التعبد يقال له: بدعة، مثل: بدعة الاحتفال بالمولد، مثل: بدعة البناء على القبور، واتخاذ المساجد على القبور والقباب، وما أشبه ذلك مما يحدثه الناس، ومعنى الرد: يعني: مردود. لكن ما فعله عثمان من الأذان الثاني في خلافته، ليس من البدع؛ لأن الرسول ﷺ قال: عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي وهو من الخلفاء الراشدين، وقد أحدث الأذان الثاني، وهو الأول للمصلحة، لمصلحة المسلمين حتى ينتبهوا للجمعة، ولهذا أقره الصحابة في زمانه، وعمل به المسلمون بعده؛ لأنه داخل في قوله ﷺ: عليكم بسنتي، وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ. وهكذا ما فعل في عهده من جمع المصحف، كان الناس يحفظون القرآن في صدورهم، وفي زمانه؛ خافوا على الناس أن يضيع منهم القرآن، فاجتمع رأي من الصحابة على أنه يكتب في المصاحف؛ حتى يبقى بين أيدي المسلمين، وحتى يحفظ، وكان هذا من الأعمال الطيبة التي وفق الله الصحابة لها. وهكذا ما فعله عمر  من جمع الناس على إمام واحد في التراويح في رمضان، وكانوا في عهد النبي ﷺ يصلون أوزاعًا في المسجد، كل يصلي لنفسه، أو يصلي مع اثنين، أو ثلاثة، أو أربعة، أو أكثر، ثم جمعهم عمر على إمام واحد؛ لأنه رأى أن هذا أولى من تفرقهم، وتأسى بالنبي ﷺ حين صلى بالناس في رمضان عدة ليالي جماعة في رمضان، ثم قال: أخاف أن تفرض عليكم صلاة الليل، فأمرهم أن يصلوا في بيوتهم. فلما توفي النبي ﷺ انقطع الوحي، وأمن فرضها؛ فلهذا جمعهم عمر، وصارت سنة أولية جمع الناس على إمام واحد في رمضان في التراويح، والقيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11442/الحث-على-اتباع-سنة-الخلفاء-الراشدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51201.mp3","categories":["البدع والمحدثات","أصول الفقه"]},{"id":13195,"question":"يقول: كيف نعرف البدعة، وعن أقسامها يا سماحة الشيخ؟","title":"كيفية معرفة البدعة وأقسامها","answer":"الجواب:  البدعة ما أحدثه الناس في الشرع يخالف الشرع هذا يقال له: بدعة، ما أحدث في الدين يقال له: بدعة، مثلما مثلنا مثل: بدعة الاحتفال بمولد النبي ﷺ أو الموالد الأخرى، ومثل: بناء المساجد على القبور، واتخاذ القباب عليها، هذه بدعة، كلها بدعة منكرة، ومثل: بدعة الجهمية: نفي الصفات والأسماء، ومثل: بدعة المعتزلة في الصفات، وقول المعتزلة: إن العاصي في المنزلة بين المنزلتين، هذه من البدع التي أحدثها المبتدعة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11460/كيفية-معرفة-البدعة-واقسامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51202.mp3","categories":["البدع والمحدثات"]},{"id":13216,"question":"السائل يقول: اعتاد البعض من النسوة أثناء التعزية في الأموات، وخاصة قبل دفن الجثمان أن يرددن قول: (لا إله إلا الله) بصوت عالي، أي: امرأة تقول والباقي يرددن وراءها، وصوت هذه المرأة مسموع عند الرجال، ويرين بأن هذا أفضل من اللطم، أو العويل، ويهدي من حالة أهل الميت، فما صحة ذلك؟","title":"حكم ترديد بعض النسوة :(لا إله إلا الله) عند العزاء","answer":"الجواب:  الظاهر أن هذا بدعة مطلقًا حتى لو ما سمعها الرجال، كونهن يرددن لا إله إلا الله.... النسوة عند التعزية هذا لا أصل له، التعزية: أحسن الله عزاءكم.. جبر مصيبتكم.. غفر لميتكم، ونحو هذا الكلام، أما أن يرددن لا إله إلا الله، أو سبحان الله بصوت جماعي؛ هذا بدعة، سواء سمعها الرجال، وإلا ما سمعها الرجال، لا ينبغي هذا، بل السنة أن يقال لهم: اتقوا الله، لا تجزعوا، الحمد لله هذه سنة الله في عباده، كل بيموت، ويتحدثن معهن بالوصية والنصيحة، هذه التهدئة، التعزية بالوعد بالخير، والتحذير من الشر. أما يأتين بلا إله إلا الله بصوت جماعي، أو بأشباه ذلك؛ فهذا من البدع؛ لأن البدعة هي ما أحدثه الناس خلاف الشرع، كما قال ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد من أحدث في أمرنا هذا ما ليس منه؛ فهو رد وهذا ليس أمر النبي ﷺ وليس من عمل الصحابة، بل هذا من البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11488/حكم-ترديد-بعض-النسوة-لا-اله-الا-الله-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51215.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":13221,"question":"يقول هذا السائل: أسأل عن قراءة الفاتحة مثلًا على أرواح الموتى، هل هذا جائز؟","title":"حكم قراءة الفاتحة على أرواح الموتى","answer":"الجواب: ما له أصل، ليس له أصل، لا الفاتحة ولا غيرها، لا يقرأ للموتى لا الفاتحة ولا غيرها، القراءة للأموات ليس له أصل، ولكن يدعى لهم بالمغفرة والرحمة، يتصدق عنهم، هذا هو المشروع، يحج عن الميت، ويعتمر عنه، أما يقرأ له القرآن هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11501/حكم-قراءة-الفاتحة-على-ارواح-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51218.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13294,"question":"يقول السائل في ثالث أسئلته: هل يجوز زرع الأشجار على القبور؟","title":"حكم زرع الأشجار على القبور","answer":"الجواب:  لا ينبغي، لا أصل له، كان النبي ﷺ وضع الجريدة على قبرين معذبين، أما نحن لا نعرف عذابهما، فلا يوضع لا جريدًا، ولا غيره، ليس بمشروع، بل بدعة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11579/حكم-زرع-الاشجار-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50923.mp3","categories":["البدع والمحدثات"]},{"id":13321,"question":"هذا السائل من اليمن يقول في هذا  أهل مسجدنا يخرجون جميعًا بعد كل صلاة عيد إلى زيارة القبور جماعة، ما الحكم في هذا مأجورين؟","title":"حكم زيارة القبور بعد صلاة العيد","answer":"الجواب: ليس لهذا أصل، الخروج للقبور صلاة العيد إنما هي عادة لبعض الناس، فإذا زاروا القبور يوم العيد، أو يوم الجمعة، أو في أي يوم ما في يوم مخصوص، تخصيص يوم العيد، أو تخصيص الجمعة، أو تخصيص يوم آخر لا، ليس له أصل، ولكن السنة أن يزوروا القبور دائمًا بين وقت وآخر على حسب التيسير، إذا كان وقتهم يسمح في يوم الجمعة، في يوم العيد، في أوقات أخرى؛ يفعلون، أما أن يظنوا أن لهذا اليوم خصوصية؛ فلا، لكن السنة أن يزوروا القبور عندما يتيسر ذلك؛ لقوله ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة. وكان يزورها -عليه الصلاة والسلام- ويدعو لأهلها، فلا فرق بين يوم العيد، أو الجمعة، أو الخميس، أو غير ذلك، ليس لهذا وقت معروف فيما نعلم، ولكن المؤمن يتحرى الأوقات التي يحصل له فيها فرصة؛ لأن الإنسان قد تشغله المشاغل، فإذا تيسر له فرصة في الجمعة، أو في يوم العيد، أو في غير ذلك؛ فعل ذلك، زار القبور، وسلم عليها. وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا تعليمه لأصحابه -عليه الصلاة والسلام- سواء كانت في الليل، أو في النهار، إذا زرتهم في الليل، أو في النهار، في أول النهار، في وسط النهار، في آخر النهار، في الليل، في أوله، في وسطه، في آخره حسب التيسير، نعم.  أما النساء لا، ليس لهن زيارة القبور، والرسول ﷺ لعن زائرات القبور، لكن يصلين على الميت في المساجد، في المصلى، لا بأس، يصلين مع الرجال على الموتى لا بأس، أما زيارة القبور فقد زجرهن عن ذلك -عليه الصلاة والسلام- ولعن زائرات القبور. والحكمة في ذلك -والله أعلم- لأنهن قليلات الصبر، ولأنهن فتنة، كما قال ﷺ: ما تركت بعدي فتنة أضر على الرجال من النساء. فالواجب عليهن طاعة الله ورسوله، وعدم الزيارة للقبور، لكن الدعاء مطلوب من الجميع، من الرجال والنساء، الدعاء لأموات المسلمين، الدعاء لأقاربهم، وأمواتهم: اللهم اغفر لهم، اللهم ارحمهم، اللهم أنجهم من النار، اللهم ارفع درجاتهم في الجنة.. إلى غير هذا من الدعوات الطيبة، اللهم كفر سيئاتهم، اللهم تقبل حسناتهم، اللهم لا تحرمنا أجرهم، ولا تفتنا بعدهم، الدعاء مطلوب في البيت.. في الطريق.. عند القبر.. كله طيب عند الزيارة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11607/حكم-زيارة-القبور-بعد-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54103.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13371,"question":"يقول هذا السائل: هل يجوز أن نقرأ الفاتحة عند البيع والشراء؟","title":"حكم قراءة الفاتحة أثناء البيع والشراء","answer":"الجواب: هذا ما له أصل، عند البيع والشراء يكثر من ذكر الله، أما يخص الفاتحة لا، يكفي يسبح، ويهلل، ويذكر الله، يأمر بالمعروف، ينهى عن المنكر، أما إذا كان جالسًا ...... وهو يقرأ القرآن؛ طيب، يقرأ القرآن ما يخص الفاتحة، يقرأ القرآن، ما فيه شيء مخصوص، فإذا جاد من يبيع ويشتري ...... منه حاسبه كلمه، أو يقرأ في كتاب يستفيد من الكتاب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11658/حكم-قراءة-الفاتحة-اثناء-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52411.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":13453,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من السائل: محمد الشرباصي، مصري ويعمل بالسعودية، يقول في هذا  هل تجوز التواشيح قبل أذان الفجر مثل قول: يا مليح الوجه .. يا كريم الأخلاق .. يا سيدي يا رسول الله؟ وجهونا في ضوء هذا السؤال سماحة الشيخ؟","title":"حكم التواشيح قبل أذان الفجر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه التواشيح التي ذكرها السائل بدعة لا تجوز، بل السنة للمؤذن في الصبح وغيره أن يبدأ بقوله: الله أكبر، ولا يكون قبله تواشيح ولا قراءة خاصة، ولا كلام خاص، بل الأذان مستقل، يبدؤه بقوله: الله أكبر، وينهيه بـلا إله إلا الله، ولا يكون قبله شيء خاص لا تواشيح، ولا غيرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11753/حكم-التواشيح-قبل-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51701.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":13456,"question":"يقول هذا السائل: هل يجوز قول: صفوا الأقدام في طاعة الرحمن، صفوا الأقدام في طاعة الديان، وذلك قبل إقامة الصلوات؟","title":"حكم ذكر ألفاظ في تسوية الصفوف غير واردة في السنة","answer":"الجواب: هذا لا أصل له، ليس لها أصل لهذا الكلام، ولكن يقول: استووا .. استقيموا، حاذوا بين الأقدام، حاذوا بين المناكب كما قال النبي ﷺ هذا هو السنة بهذه الألفاظ: استووا، تراصوا، اعتدلوا، ساووا بين المناكب، ساووا بين الأقدام، لا بأس، نعم، على ألفاظ النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11759/حكم-ذكر-الفاظ-في-تسوية-الصفوف-غير-واردة-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51704.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":13458,"question":"ننتقل بعد ذلك إلى الأردن، والسائلة: (ع. ع. م) تقول في هذا  أرى أختي عندما تريد الدعاء بعد التشهد في الصلاة، وقبل السلام تسجد، وتدعو بما شاءت، فهل عملها صحيح؟ سماحة الشيخ.","title":"حكم زيادة سجدة في الصلاة للدعاء فيها","answer":"الجواب: هذا منكر بدعة، لا يجوز السجود الزيادة إلا للسهو، أما أن تسجد للدعاء غير السجدتين فهذا باطل.. هذا منكر، فإذا تعمدت هذا؛ تبطل الصلاة، أما إذا كانت جاهلة؛ تعلم ولا تعد إلى هذا الشيء، أما تعمد ذلك وهي تعلم يكون زيادة في الصلاة؛ فتبطل، كمن زاد ركعة متعمدًا، أو زاد ركوعًا متعمدًا، وهو يعلم بالحكم؛ بطلت الصلاة. أما إذا كانت جاهلة؛ فتعلم حتى لا تعود لهذا الشيء، أو كانت ساهية عليها سجود السهو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11761/حكم-زيادة-سجدة-في-الصلاة-للدعاء-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51706.mp3","categories":["البدع والمحدثات"]},{"id":13482,"question":"يقول: لدينا عندما يتوفى أحدنا يقوم أهل الميت بدعوة بعض أئمة المساجد، أو ما يسمى عندنا بالشيوخ، وهم مجموعة لا يقل عددهم عن عشرة، يقومون بتلاوة القرآن ترحمًا على الميت، ولكن يكون هذا المقابل من أهل الميت، يقوم واحد من أهل الميت بتوزيع بعض النقود عليهم جميعًا بعد الانتهاء من ختمة القرآن، فما حكم الإسلام في هذا؟","title":"حكم أخذ الأجرة على قراءة القرآن وتثويب القراءة للميت","answer":"الجواب: هذا غير مشروع، ولا يجوز أخذ الأجرة على تلاوة القرآن، ولا تثويبها للموتى، هذا غير مشروع، وما كان الصحابة يفعلون هذا  أما كونه يقرأ بين الحاضرين إذا اجتمعوا ليستفيدوا من كلام الله  من دون أجرة، لو اجتمع الناس في مجلس يعزون، أو في زيارة، أو في وليمة، وقرأ واحد ليسمعهم القرآن، ويستفيدوا هذا شيء طيب، كان النبي ﷺ في مجالسه يقرأ القرآن، ويستمعون، ويشرح لهم ﷺ ويبين لهم، وربما أمر بعض الصحابة أن يقرأ وهو يستمع، عليه الصلاة والسلام. أما إحضارهم من أجل القراءة للتثويب للميت، وأن يعطوا على هذا أجرة؛ فهذا منكر لا يجوز، وليس من الإسلام، بل هذا بدعة، وقد أجمع العلماء على أنه لا يجوز للمسلم أن يأخذ الأجرة على تلاوة القرآن، إنما يأخذ على التعليم، على تعليم الناس القرآن، الصحيح يجوز أن يعطى أجره على التعليم حتى يتفرغ للتعليم، أما مجرد التلاوة يأتي يتلو ثمنًا، أو ثمنين، أو جزءًا، أو جزأين؛ ليأخذ فلوسًا؛ هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11785/حكم-اخذ-الاجرة-على-قراءة-القران-وتثويب-القراءة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47811.mp3","categories":["البدع والمحدثات","الإجارة"]},{"id":13497,"question":"على بركة الله نبدأ هذا اللقاء بسؤال من الجزائر، السائل الحقيقة له مجموعة من الأسئلة، غالب محمد يقول في هذا  ما حكم أولئك الذين يجمعون المقرئين في بيت الميت بعد دفنه، ويقرؤون ما يتيسر من القرآن، ثم يأكلون ويشربون، وقد يأخذون مبلغًا ماليًا على تلك القراءة؟ وجهونا سماحة الشيخ.","title":"حكم الاجتماع لقراءة القرآن في بيت العزاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا الاجتماع لا أصل له في الشرع، بل هو بدعة، إنما السنة أن يزار أهل الميت للتعزية، والدعاء لميتهم؛ جبرًا لمصابهم، وأما أن يجمعونهم ليقرؤوا، ويطعمونهم هذا بدعة، يقول جرير  جرير بن عبدالله البجلي : \"كنا نعد الاجتماع إلى الميت، وصنعة الطعام بعد الدفن من النياحة\" خرجه الإمام أحمد بإسناد حسن.  فالمقصود: أن كونهم يجمعونهم؛ ليقرؤوا ويأكلوا؛ هذا لا أصل له، بل هو من البدع، أما لو زارهم إنسان يسلم عليهم، ويدعو لهم، ويعزيهم، وقرأ في المجلس قراءة عارضة، ليس بمقصودة، ولا هم مجتمعون، فقرأ آية، أو آيات لفائدة الجميع، ونصيحة الجميع؛ فلا بأس، أما أن أهل الميت يجمعون الناس، أو يجمعون جماعة معينة؛ ليقرؤوا، ويطعموهم، أو يعطوهم فلوسًا؛ هذا بدعة لا أصل له. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11803/حكم-الاجتماع-لقراءة-القران-في-بيت-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53101.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":13505,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية اليمنية حضرموت، وباعثها المستمع عبد الحافظ عبدالرحمن باعباد، أخونا باعباد له سؤال يقول فيه: يوجد عندنا قبور يقال: إنها قبور بعض الصالحين، ويقوم بعض الناس بزيارتها لكي تبعد عنهم الشر، وتجلب لهم الخير، وتشفي مرضهم بزعمهم، ويقولون: إن هذا الصالح له شأن في هذا الشيء، وعند نهاية زيارتهم يضعون بعض النقود على هذا القبر، ما حكم عملهم هذا؟","title":"حكم الاستغاثة بأهل القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد.  فإن الله  شرع لعباده زيارة القبور للذكرى والاستغفار للميتين، والدعاء لهم، كما قال ﷺ: زوروا القبور فإنها تذكركم الآخرة ويقول لأصحابه -عليه الصلاة والسلام- كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، ويقول -عليه الصلاة والسلام- إذا زار البقيع: اللهم اغفر لأهل بقيع الغرقد ويقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون ثم يقول: اللهم اغفر لأهل بقيع الغرقد هذه هي السنة أن يدعى لهم عند الزيارة، ويترحم عليهم؛ لأنهم في حاجة إلى الدعاء. أما زيارتهم لطلب الشفاء، للمرضى، أو لطلب المدد، والنصر على الأعداء، أو ما أشبه ذلك، فهذا من الشرك الأكبر، هذا كفر بالله، هذا لا يجوز، هذه حال عباد الأوثان يرجون الموتى والأصنام والأشجار والأحجار والكواكب، ويسألونهم قضاء الحاجات، تفريج الكروب، شفاء المرضى، ويسألونهم المدد لكل ما يعينهم، هذا كله من الشرك الأكبر، فالواجب الحذر من هذا العمل السيئ. قبور الصالحين تزار للدعاء لهم، والترحم عليهم، لا لدعائهم من دون الله، ولا فرق بين العيدروس، أو ابن علوان، أو غيرهما، جميع القبور حتى قبور الأنبياء حتى قبر النبي ﷺ وقبر الصديق وعمر وأهل البقيع كلهم لا يدعون مع الله، لا يستغاث بهم، لا ينذر لهم حتى النبي ﷺ يقول: (السلام عليك يا رسول الله! ورحمة الله وبركاته، جزاك الله عن أمتك أفضل الجزاء وأحسنه) ولا يدعى من دون الله، ولا يقال له المدد، ولا اشف مرضانا، ولا انصرنا، هذا شرك أكبر. وهكذا عند الصديق، وهكذا عند عمر، هكذا عند عثمان، هكذا عند علي، هكذا عند قبور أهل البيت جميعًا، لا يدعون مع الله، لا يقال: انصرونا، أو اشفوا مرضانا، أو أنتم تعلمون حاجاتنا هذا كله من الكفر الأكبر، والغيب لا يعلمه إلا الله  قال الله : قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] فهو الذي يعلم الغيب -جل وعلا-. ولما سقط عقد لعائشة في بعض الأسفار؛ أناخ النبي الناس -عليه الصلاة والسلام- وطلب العقد، وأرسل من يطلبه ويلتمسه، ولم يعرف أين مكانه -عليه الصلاة والسلام- وهو سيد الخلق، وأفضلهم، لم يعرف أين العق، طلب أن يلتمسوه؛ فلم يجدوه، فلما أقاموا البعير الذي عليه عائشة؛ وجدوه تحته. فلو كان يعلم الغيب؛ لقال: انظروه تحت البعير، ولم يحتج إلى أن يرسل من يطلبه. ولما قذف المنافقون عائشة، وبعض الناس قلدهم وقذفها لم يعلم الحقيقة، وتوقف حتى جاءه الوحي بسلامتها وبراءتها، رضي الله عنها وأرضاها. فالغيب لا يعلمه إلا الله، لا يعلمه نبي، ولا ملك، ولا غيرهما إلا ما علم الله عباده، إلا ما أوحى الله به إلى أنبيائه، وعلمهم إياه. هكذا لا يدعون مع الله، ولا يستغاث بهم، وهم أنبياء قال الله تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] هذا (أحدًا) هذا عام، نكرة في سياق النهي يعم الأنبياء وغيرهم، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. فسمى دعاة غير الله كفره، يعني: دعاة الأموات والأنبياء، ودعاء الأشجار والأصنام، ونحو ذلك، وقال الله لنبيه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين. والمقصود: تحذيره ﷺ وتحذير الأمة فهو ﷺ لا يشرك، قد عصمه الله من هذا، لكن المقصود تحذير الأمة، وبيان أن هذا الأمر خطير، وأنه لا يجوز لأحد أن يفعله.  وهكذا قوله سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] أوحى الله إليه هذا الأمر؛ ليعلم الناس أن الشرك محرم، وأنه أعظم الذنوب، وأنه محرم على الأنبياء، وعلى غيرهم. وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14]  فجعل دعاء غير الله كائنًا من كان من الشرك، وقد أخبر أن المدعوين لا يسمعون دعاء الداعين، وأنهم لو سمعوا ما استجابوا. فالواجب الحذر من هذا الشرك الوخيم، وتحذير الناس من ذلك، والواجب على العلماء في كل مكان أن يبينوا للناس هذا الأمر العظيم، وأن يحذروهم من التعلق على القبور، والتعلق على الأموات، والاستغاثة بهم، والنذر لهم، وطلب منهم المدد، والعون، كل هذا من المحرمات الشنيعة، بل من الشرك الأكبر، وإذا كان هذا لا يجوز مع النبي ﷺ ولا مع الخلفاء الراشدين، فكيف يجوز مع العيدروس، أو مع ابن علوان، أو مع الشيخ عبدالقادر، أو مع علي، أو مع الحسن، أو فاطمة، أو غيرهم، لا يجوز أبدًا مع أحد، العبادة حق الله وحده قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وقال: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] وقال: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] فهو المعبود بالحق وهو المستعان -جل وعلا- فلا يدعى معه أحد، لا ملك، ولا نبي، ولا صنم، ولا شجر، ولا حجر، ولا ميت، العبادة حق الله وحده -سبحانه وتعالى- قال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2] وقال -جل وعلا-: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]. أما الحي فلا بأس يقال له: يا عبدالله! أعني على كذا الحي الحاضر، تقول: أعني على إصلاح سيارتي، أقرضني كذا وكذا حي يسمعك ويقدر، تقول له: أعني على كذا، أعني على تعمير بيتي، على إمساك دابتي، على إصلاح سيارتي، هذا لا بأس، كما قال الله في قصة موسى : فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] لأنه حي قادر، أما الأموات فلا يدعون مع الله، وهكذا الأصنام، هكذا الأشجار والأحجار، هكذا النجوم، كل ذلك من الشرك الأكبر، نسأل الله العافية. فنصيحتي لكل مسلم أن يحذر هذا، وعلى العلماء أن يحذروا الناس من هذا الشرك الوخيم، على العلماء في كل مكان أن يتقوا الله، وأن يعنوا بهذا الأمر، بالكتابة، وفي خطب الجمعة، وفي غير ذلك، وهكذا زيارة القبور حتى ينبه الناس القبر الذي يدعى من دون الله، يزار حتى ينبه أهله، يزوره العالم يقول: يا ناس هذا لا يجوز، سلموا وادعوا له بالمغفرة والرحمة، أما أن تدعوه من دون الله المدد المدد يا سيدي فلان اشفع لنا، انصرنا هذا .... هذا الشرك الأكبر، نعوذ بالله، فيجب الحذر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11818/حكم-الاستغاثة-باهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47901.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13512,"question":"يقول ما هو قولكم فيمن يقول: إن إقامة الموالد، وقراءة القرآن للأموات، وإهداء ثوابه إليهم جائز؟","title":"هل يجوز إقامة الموالد، وقراءة القرآن للأموات، وإهداء الثواب لهم؟","answer":"الجواب: الصواب: أنه بدعة، إقامة الموالد والاحتفال بها بدعة، ما فعله الرسول ﷺ ولا أصحابه، ولا أمر به، ولا دعا إليه، ولا أقره -عليه الصلاة والسلام- ولا فعله السلف الصالح، والقرون المفضلة، فهو بدعة ومن وسائل الشرك، الاحتفال بالموالد بدعة منكرة، ولا فرق بين مولد النبي ﷺ ولا غيره، وهو من وسائل الشرك، فإن بعض الناس إذا احتفل بالمولد يدعو صاحب المولد، يستغيث به كما يفعل بعض الجهال بالنبي، عليه الصلاة والسلام.  وبعضهم يقول: إنه يحضرهم النبي ﷺ يخرج من قبره، يحضرهم هذا من المنكر، النبي -عليه الصلاة والسلام- لا يخرج من قبره إلا يوم القيامة، لكن روحه في الجنة، روحه في أعلى عليين -عليه الصلاة والسلام- وترد إلى جسده إذا شاء الله ذلك عند السلام عليه -عليه الصلاة والسلام- كما في الحديث، يقول ﷺ: ما من أحد يسلم علي إلا رد الله علي روحي حتى أرد عليه السلام. فالمقصود: أن الاحتفال بالموالد، سواءً كانت للأنبياء، أو لبعض الصالحين، أو غيرهم، أو للملوك كله بدعة، لا يجوز الاحتفال بالموالد؛ لأنه محدث، والرسول ﷺ قال: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد يعني: فهو مردود.  وقال -عليه الصلاة والسلام- في خطبة الجمعة: أما بعد! فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة وقال -عليه الصلاة والسلام-: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة وهي أحاديث صحيحة، بعضها في مسلم، وبعضها في الصحيحين، وبعضها في السنن. فالواجب على علماء الإسلام بأن يذاكروا الناس وتعليمهم، والواجب على العامة سؤال أهل العلم عما أشكل عليهم، والتفقه في الدين، والسؤال يكون لأهل العلم، علماء السنة، ما هو بعلماء البدعة، علماء الخرافة، السؤال يكون لعلماء السنة الذين يعرفون سنة الرسول ﷺ ويحكمون القرآن والسنة ويعملون بهما. أما علماء السوء، وعلماء البدع؛ فليسوا محل السؤال، وليسوا أهلًا للسؤال، إنما السؤال يكون لأهل العلم الذين يحكمون كتاب الله، وسنة رسوله ﷺ ويعملون بهما، ويتأسون بالسلف الصالح في اتباع السنة، والحذر من البدعة، نسأل الله للجميع الهداية والتوفيق. نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11828/هل-يجوز-اقامة-الموالد-وقراءة-القران-للاموات-واهداء-الثواب-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47903.mp3","categories":["البدع والمحدثات"]},{"id":13590,"question":"السائل أمين حسن يقول: من عادة الناس في بعض المناطق بعد صلاة الاستسقاء الذبح، والتقرب إلى الله بنزول المطر، هل ورد في السنة عن النبي ﷺ ذلك، أم يعتبر ذلك بدعة؟","title":"حكم الذبح بعد صلاة الاستسقاء","answer":"الجواب: لا أصل لهذا إلا في عيد الضحايا، عيد الأضحية \"الضحية\" وفي أيام منى النحر، أما كونه عيد الفطر ما في ذبح، أما إذا عنده ضيوف، أو دعا أقاربه، ويجعل لهم ضيافة؛ لأجل إن دعاهم للغداء عنده؛ يتغدون معه، أو جاءه ضيوف، لا بأس، أما اتخاذ هذا تعبدًا، يذبح ذبائح بعد عيد الفطر يرى أنها قربة؛ هذا ما له أصل.","link":"https://binbaz.org.sa/fatwas/11944/حكم-الذبح-بعد-صلاة-الاستسقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53318.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":13598,"question":"الأخت (سعاد . ج. م) بعثت برسالة ضمنتها جمعًا من الأسئلة، في أحد أسئلتها تقول: جرت العادة في بلدنا الذبح في المواسم مثل النصف من شعبان، وأول رمضان، وسبعة وعشرين من رجب، فهل يجوز الأكل من مثل هذه الذبائح؟","title":"حكم الأكل مما يذبح في نصف شعبان وغيره من مواسم","answer":"الجواب: أما الذبح في النصف من شعبان أو في ليلة سبع وعشرين من رجب هذه بدعة ما لها أصل، لا ينبغي.. لا يجوز فعلها، ولا الأكل منها؛ لعدم الدليل، بل ذلك من البدع. وأما كون الإنسان يتقرب في رمضان بالذبائح، ويتصدق بها فرمضان شهر مبارك، مشروع فيه التوسع في النفقة، والصدقة على الفقراء، فإذا ذبح ذلك في رمضان، أو في عشر ذي الحجة، أو في غير هذا من الأوقات، وتصدق؛ فهذا كله طيب، أما تخصيص ليلة النصف من شعبان، أو ليلة سبعة وعشرين من رجب -كما يفعل بعض الناس من الاحتفال بهذه الليلة- فهذا لا أصل له، بل هو بدعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11929/حكم-الاكل-مما-يذبح-في-نصف-شعبان-وغيره-من-مواسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48010.mp3","categories":["البدع والمحدثات"]},{"id":13605,"question":"هذا السائلة التي رمزت لاسمها بـ (ف. أ. ط)، تقول في هذا  ما حكم قراءة الفاتحة على الميت عند قبره؟","title":"حكم قراءة الفاتحة على الميت عند قبره","answer":"الجواب: بدعة، لا يقرأ على القبور، إذا زار الميت يسلم عليه يقول: السلام عليك يا فلان، غفر الله لك، رحمنا الله وإياك، السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، وأما القراءة لا، لا يشرع، لا الفاتحة، ولا غيرها، لا يقرأ عند القبور الفاتحة، ولا غيرها، بل ذلك من البدع، ولا يصلي عند القبور أيضًا، ولكن يسلم عليهم يقول: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يغفر الله لنا ولكم، كما علم النبي أصحابه هذا الدعاء، هكذا يعلم أصحابه، عليه الصلاة والسلام. أما الصلاة عند القبور، أو الطواف بها، أو القراءة عندها، فكل هذا لا يجوز، الصلاة عندها بدعة، والقراءة عندها بدعة، والطواف بها إذا أراد بذلك التقرب إلى الميت شرك أكبر. أما إذا ظن أن الطواف بها قربة وطاعة لله؛ يعني فهذا بدعة، مثل الصلاة عندها نسأل الله العافية، أما إذا صلى لصاحب القبر، أو طاف لصاحب القبر، يتقرب إليه بذلك؛ هذا من الشرك الأكبر، نعوذ بالله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11940/حكم-قراءة-الفاتحة-على-الميت-عند-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52723.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13635,"question":"المستمع محمد علي محمد من اليمن الحديدة يقول: يوجد إمام عندما يدخل في الصلاة يتلفظ بالنية قبل تكبيرة الإحرام بصوت مرتفع، يقول مثلًا: أصلي فرض المغرب ثلاث ركعات مستقبلًا القبلة، ثم يكبر تكبيرة الإحرام، ويقول: هذا التلفظ سنة. أرجو منكم توجيهنا جزاكم الله خيرًا.","title":"حكم التلفظ بالنية قبل تكبيرة الإحرام","answer":"الجواب: الصواب أن التلفظ ليس بسنة، بل بدعة، ما كان النبي ﷺ يتلفظ بالنية، ولا أصحابه، بل يقوم بنية الصلاة بقلبه، ثم يكبر، وهكذا فعل الصحابة، فالتلفظ بالنية نويت أن أصلي كذا وكذا عند الإحرام، هذا شيء محدث، وإن قاله بعض الفقهاء، لكنه قول ليس عليه دليل، وأقوال الفقهاء إذا تنازعوا تعرض على الكتاب والسنة، فما وافق الدليل؛ وجب الأخذ به، وما خالفه؛ ترك، قال الله -جل وعلا-: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].  وليس في كتاب الله، ولا في سنة رسوله ﷺ ما يدل على التلفظ بالنية، ولكن المؤمن إذا قام إلى الصلاة ينوي بقلبه أنه يصلي الظهر والعصر والمغرب.. وهكذا المؤمنة من دون حاجة إلى التلفظ. فينبغي إعلام هذا، ونصيحته؛ حتى يعمل بالسنة، وحتى يدع البدعة، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/11966/حكم-التلفظ-بالنية-قبل-تكبيرة-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48020.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":13729,"question":"هل يجوز صيام ليلة النصف من شعبان، وقيام ليلة النصف أيضًا؟","title":"حكم صيام يوم النصف من شعبان وقيام ليلته","answer":"الجواب: ليس عليه دليل، كل الأحاديث التي في هذا ضعيفة، فلا يشرع له صيام يوم النصف، ولا قيام ليلة النصف، كل الأحاديث ضعيفة التي في هذا الباب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12100/حكم-صيام-يوم-النصف-من-شعبان-وقيام-ليلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48114.mp3","categories":["صيام التطوع","البدع والمحدثات"]},{"id":13796,"question":"هل ورد ما يؤكد بأن صلاة الجمعة لا تجزي عن صلاة الظهر وأنه يجب أن يصلى صلاة الظهر بعدها؟","title":"هل يُصلى الظهر بعد الجمعة؟","answer":"الجواب: لا ما في هذا، هذا باطل، الجمعة كافية ولا يجوز هذا الظن، ولا يجوز أن يصلي بعدها ظهر، الله جعلها كافية عن الظهر، والذين أحدثوا صلاة ظهر بعد الجمعة هذه بدعة، من صلى الجمعة كفته عن الظهر والحمد لله. نعم.\nالمقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/12173/هل-يصلى-الظهر-بعد-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53620.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":13833,"question":"في آخر أسئلة هذا السائل يقول سماحة الشيخ: هل وضع الشجرة أو غصن الشجرة على القبر يخفف من العذاب كما وضعه النبي ﷺ؟ أم أنه خاص به ﷺ فقط؟ وضحوا لنا ذلك سماحة الشيخ.","title":"حكم وضع أغصان الشجر على القبر","answer":"الجواب: وضع الجريد على القبور غير مشروع، بل هو بدعة؛ لأن النبي ﷺ لم يفعل ذلك إلا في قبرين خاصين، فاطلع على عذابهما فوضع عليهما جريدتين، ولم يضع جرائد على قبور أهل البقيع ولا على غيرها، فدل ذلك على أن هذا الوضع خاص بالقبرين اللذين أطلعه الله على عذابهما خاصة، ولو كانت سنة لفعلها ﷺ في سائر القبور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12203/حكم-وضع-اغصان-الشجر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53712.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":13836,"question":"في آخر أسئلة هذا السائل يقول سماحة الشيخ: هل وضع الشجرة أو غصن الشجرة على القبر يخفف من العذاب كما وضعه النبي ﷺ؟ أم أنه خاص به ﷺ فقط؟ وضحوا لنا ذلك سماحة الشيخ.","title":"حكم وضع أغصان الشجر على القبر","answer":"الجواب: وضع الجريد على القبور غير مشروع، بل هو بدعة؛ لأن النبي ﷺ لم يفعل ذلك إلا في قبرين خاصين، فاطلع على عذابهما فوضع عليهما جريدتين، ولم يضع جرائد على قبور أهل البقيع ولا على غيرها، فدل ذلك على أن هذا الوضع خاص بالقبرين اللذين أطلعه الله على عذابهما خاصة، ولو كانت سنة لفعلها ﷺ في سائر القبور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12203/حكم-وضع-اغصان-الشجر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53712.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":13859,"question":"من الزلفي هذه رسالة بعث بها أحد الإخوة من هناك هو المستمع (أ. خ. س) مدرسة تحفيظ القرآن الكريم، أخونا يقول: إنني كثيرًا ما أسمع أن قول: صدق الله العظيم عند الانتهاء من قراءة القرآن الكريم بدعة، وقال لي بعض الناس: إنها جائزة، واستدلوا بقوله تعالى: قُلْ صَدَقَ اللَّهُ فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا [آل عمران:95]، وكذلك قال لي بعض المثقفين: إن النبي ﷺ إذا أراد أن يوقف القارئ قال: حسبك، ولا يقول: صدق الله العظيم، وسؤالي هو: هل قول: صدق الله العظيم جائز عند الانتهاء من قراءة القرآن الكريم؟ أرجو أن تتفضلوا بالتفصيل في هذا وفقكم الله وسدد خطاكم.","title":"حكم قول (صدق الله العظيم) بعد قراءة القرآن","answer":"الجواب: اعتياد الناس أن يأتوا بصدق الله العظيم بعد الفراغ من القراءة شيء لا أصل له ولا ينبغي اعتياده، بل هو على القاعدة الشرعية من قبيل البدع إذا اعتقد أحد أنه سنة، فينبغي ترك ذلك وأن لا يعتاد ذلك.\nوأما الآية الكريمة: قُلْ صَدَقَ اللَّهُ فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ [آل عمران:95] فليست في هذا الشأن وإنما أمره الله أن يبين لهم صدق الله فيما بين في كتبه العظيمة من التوراة وغيرها وأنه صادق فيما بين لعباده في التوراة والإنجيل وسائر الكتب المنزلة، كما أنه صادق سبحانه فيما بينه لعباده في كتابه العظيم القرآن، ولكن ليس هذا دليلاً على أنه يستحب لأحد أن يقول ذلك بعد قراءة القرآن أو بعد قراءة آيات أو سورة، وليس هذا ثابتًا ولا معروفًا عن النبي ﷺ ولا عن أصحابه  وأرضاهم. ولما قرأ ابن مسعود على النبي ﷺ أول سورة النساء حتى بلغ قوله تعالى: فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا [النساء:41] قال له النبي ﷺ: حسبك قال ابن مسعود: فالتفت إليه فإذا عيناه تذرفان عليه الصلاة والسلام. يعني يبكي لما تذكر هذا المقام العظيم يوم القيامة، فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ [النساء:41] يعني: يا محمد عَلَى هَؤُلاءِ شَهِيدًا [النساء:41] يعني: على أمته عليه الصلاة والسلام.\nفالمقصود أن اعتياد كلمة صدق الله العظيم ليس له أصل في الشرع، أما لو فعله الإنسان بعض الأحيان من غير قصد لا يضر الله صادق ، لكن اعتياد ذلك بعد كل قراءة كما يفعل كثير من الناس اليوم هذا ليس له أصل، والآية: قُلْ صَدَقَ اللَّهُ [آل عمران:95] ليس فيها العظيم قُلْ صَدَقَ اللَّهُ فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ [آل عمران:95]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12235/حكم-قول-صدق-الله-العظيم-بعد-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60306.mp3","categories":["القرآن وعلومه","البدع والمحدثات"]},{"id":13918,"question":"المستمع أحمد حسين علي من أبو عريش في جيزان بعث برسالة ضمنها جمعًا من الأسئلة في أحدها يقول: ما هو الفرق بين الاتباع والابتداع؟","title":"الفرق بين الاتباع والابتداع","answer":"الجواب: الاتباع: هو اتباع الشرع، اتباع ما جاء به الرسول ﷺ من الأوامر والنواهي، يقال له: اتباع؛ لأن الله قال: اتَّبِعُوا مَا أُنْزِلَ إِلَيْكُمْ مِنْ رَبِّكُمْ وَلا تَتَّبِعُوا مِنْ دُونِهِ أَوْلِيَاءَ [الأعراف:3]، وقال جل وعلا: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ لا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ [الأعراف:158]. فنحن مأمورون باتباع النبي ﷺ وباتباع القرآن، فالتمسك بالقرآن بما قال الله، والتمسك بما قال الرسول ﷺ أو فعل هذا هو الاتباع، السير على منهاج النبي ﷺ وطريقه في الأوامر والنواهي هذا يسمى الاتباع وهو واجب في الواجبات مستحب في المستحبات.\nوأما الابتداع فهو إحداث شيء في الدين لم يأذن به الله، يعني: إحداث عبادة ما شرعها الله، هذه يقال له: ابتداع؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد، ولقوله ﷺ: شر الأمور محدثاتها وكل بدعة ضلالة. فلو أن إنسانًا صلى صلاة زائدة على الخمس قال: نبي نصلي ست حطها ست، إنا ندور الخير نحط ست إذا جاءت الساعة أربع من النهار أو خمس من النهار بعد طلوع الشمس قبل الظهر يصلي سادسة، هذه بدعة وباطلة ولا يجوز له أن يفعلها ولا يدعو الناس إليها بنية إنها فريضة يعني: يدعو الناس إليها، أما بنية إنها صلاة الضحى يصلي الضحى لا بأس مستحبة، أما يجعل سادسة يؤذن لها ويقيم لها ويدعو الناس إليها هذا منكر بدعة. أو يقول: السجدتين ما تكفي نحط سجدة ثالثة في الركعة.. نزيد سجدة ثالثة هذه بدعة إذا تعمدها تبطل الصلاة. أو قال: نحط ركوع ثاني كل ركعة فيها ركوعين، هذا بدعة إلا في صلاة الكسوف فيها ركوعان صلاة الكسوف. وهكذا لو قال: نجعل ليلة من الليالي محل عبادة نصلي فيها عشر ركعات عشرين ركعة ليلة الجمعة أو ليلة الخميس من كل أسبوع هذه بدعة، لا يخص ليلة من الليالي بشيء ما شرعه الله، أو ليالي مولد.. مولد النبي ﷺ أو مولد فاطمة أو الحسين أو البدوي أو الصديق أو عمر نجعله احتفال نصلي فيه نتحدث فيه ونذكر فيه هذه بدعة؛ لأنها ما شرعها الله ورسوله. فالابتداع هو إحداث عبادة ما شرعها الله قولية أو فعلية، يقال لها: بدعة لأن الله ما شرعها . ومن ذلك ما فعله الناس في البناء على القبور واتخاذ المساجد عليها والقباب يزعمون أنها قربة ودين هذه بدعة؛ الرسول ﷺ نهى عن البناء على القبور، فالبناء عليها بدعة من وسائل الشرك، كذلك تجصيصها بدعة، إذا جصصتها يتقرب إلى الله بذلك هذه بدعة؛ لأن الرسول نهى عن تجصيصها عليه الصلاة والسلام؛ لأنها وسيلة للشرك.\nفهكذا كونه يتوسل بأصحاب القبور يقول: أسألك بأصحاب القبور أو أسألك بجاه النبي ﷺ أو بحق النبي ﷺ بدعة، أو أسألك بجاه الصالحين بدعة، أما لو قال: أسألك بحبي لك أو بإيماني بك أو بإيماني برسولك أو بأسمائك الحسنى هذا طيب، ... هذه وسيلة شرعية.\nفالبدع ما أحدثه الناس في الدين وهو ما شرعه الله ولا رسوله، هذا يقال له: بدعة، والاتباع هو السير على المنهج الذي شرعه الله لعباده، وجاء به رسوله ﷺ، هذا يقال له: اتباع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12299/الفرق-بين-الاتباع-والابتداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48204.mp3","categories":["البدع والمحدثات"]},{"id":13926,"question":"المستمع أحمد حسين علي من أبو عريش في جيزان بعث برسالة ضمنها جمعًا من الأسئلة في أحدها يقول: ما هو الفرق بين الاتباع والابتداع؟","title":"الفرق بين الاتباع والابتداع","answer":"الجواب: الاتباع: هو اتباع الشرع، اتباع ما جاء به الرسول ﷺ من الأوامر والنواهي، يقال له: اتباع؛ لأن الله قال: اتَّبِعُوا مَا أُنْزِلَ إِلَيْكُمْ مِنْ رَبِّكُمْ وَلا تَتَّبِعُوا مِنْ دُونِهِ أَوْلِيَاءَ [الأعراف:3]، وقال جل وعلا: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ لا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ [الأعراف:158]. فنحن مأمورون باتباع النبي ﷺ وباتباع القرآن، فالتمسك بالقرآن بما قال الله، والتمسك بما قال الرسول ﷺ أو فعل هذا هو الاتباع، السير على منهاج النبي ﷺ وطريقه في الأوامر والنواهي هذا يسمى الاتباع وهو واجب في الواجبات مستحب في المستحبات.\nوأما الابتداع فهو إحداث شيء في الدين لم يأذن به الله، يعني: إحداث عبادة ما شرعها الله، هذه يقال له: ابتداع؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد، ولقوله ﷺ: شر الأمور محدثاتها وكل بدعة ضلالة. فلو أن إنسانًا صلى صلاة زائدة على الخمس قال: نبي نصلي ست حطها ست، إنا ندور الخير نحط ست إذا جاءت الساعة أربع من النهار أو خمس من النهار بعد طلوع الشمس قبل الظهر يصلي سادسة، هذه بدعة وباطلة ولا يجوز له أن يفعلها ولا يدعو الناس إليها بنية إنها فريضة يعني: يدعو الناس إليها، أما بنية إنها صلاة الضحى يصلي الضحى لا بأس مستحبة، أما يجعل سادسة يؤذن لها ويقيم لها ويدعو الناس إليها هذا منكر بدعة. أو يقول: السجدتين ما تكفي نحط سجدة ثالثة في الركعة.. نزيد سجدة ثالثة هذه بدعة إذا تعمدها تبطل الصلاة. أو قال: نحط ركوع ثاني كل ركعة فيها ركوعين، هذا بدعة إلا في صلاة الكسوف فيها ركوعان صلاة الكسوف. وهكذا لو قال: نجعل ليلة من الليالي محل عبادة نصلي فيها عشر ركعات عشرين ركعة ليلة الجمعة أو ليلة الخميس من كل أسبوع هذه بدعة، لا يخص ليلة من الليالي بشيء ما شرعه الله، أو ليالي مولد.. مولد النبي ﷺ أو مولد فاطمة أو الحسين أو البدوي أو الصديق أو عمر نجعله احتفال نصلي فيه نتحدث فيه ونذكر فيه هذه بدعة؛ لأنها ما شرعها الله ورسوله. فالابتداع هو إحداث عبادة ما شرعها الله قولية أو فعلية، يقال لها: بدعة لأن الله ما شرعها . ومن ذلك ما فعله الناس في البناء على القبور واتخاذ المساجد عليها والقباب يزعمون أنها قربة ودين هذه بدعة؛ الرسول ﷺ نهى عن البناء على القبور، فالبناء عليها بدعة من وسائل الشرك، كذلك تجصيصها بدعة، إذا جصصتها يتقرب إلى الله بذلك هذه بدعة؛ لأن الرسول نهى عن تجصيصها عليه الصلاة والسلام؛ لأنها وسيلة للشرك.\nفهكذا كونه يتوسل بأصحاب القبور يقول: أسألك بأصحاب القبور أو أسألك بجاه النبي ﷺ أو بحق النبي ﷺ بدعة، أو أسألك بجاه الصالحين بدعة، أما لو قال: أسألك بحبي لك أو بإيماني بك أو بإيماني برسولك أو بأسمائك الحسنى هذا طيب، ... هذه وسيلة شرعية.\nفالبدع ما أحدثه الناس في الدين وهو ما شرعه الله ولا رسوله، هذا يقال له: بدعة، والاتباع هو السير على المنهج الذي شرعه الله لعباده، وجاء به رسوله ﷺ، هذا يقال له: اتباع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12299/الفرق-بين-الاتباع-والابتداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48204.mp3","categories":["البدع والمحدثات"]},{"id":13988,"question":"في سؤالها الثاني تقول السائلة فايزة من مصر قنا: اعتاد بعض الناس عند ذهابهم للمقابر أن يقرءوا الفاتحة والإخلاص والمعوذتين، فهل يصل الثواب للأموات؟ وما رأيكم - سماحة الشيخ - في توزيع الخبز والفواكه والخضروات عند القبور؟ وهل يجوز أكل هذا الأشياء؟ جزاكم الله خيرًا.","title":"حكم قراءة القرآن عند القبور، وهل يصل الثواب للميت؟","answer":"الجواب: القراءة عند القبور غير مشروعة بل بدعة، لا يجوز قصد القبور للقراءة عندها لا الفاتحة ولا غيرها، ولهذا قال ﷺ: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة، فدل على أن القبور ما هي بمحل صلاة ولا محل قراءة، البيوت والمساجد هي محل القراءة ومحل الصلاة، المساجد محل صلاة الفريضة ومحل القراءة، والبيوت محل صلاة النافلة والقراءة، أما المقابر فليست محلًا للصلاة ولا محلًا للقراءة، ولكن من زارها يدعو للميتين .. يستغفر لهم .. يترحم عليهم، ويتذكر الآخرة، وأنه صائر إلى ما صاروا إليه حتى يعد العدة للقاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12403/حكم-قراءة-القران-عند-القبور-وهل-يصل-الثواب-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53914.mp3","categories":["البدع والمحدثات"]},{"id":14010,"question":"يقول: بعد تمام الأسبوع الأول من الولادة يخرج به شخص معروف لديهم بالشجاعة والحذاقة وكتمان السر، ووالدة المولود تبقى أربعين يومًا في الحجبة لا تطلع من بيتها بل تبقى بداخل غرفة وحدها في إغلاق حتى تنتهي هذه الأربعين اليوم، ويرجو أيضًا التوجيه حول هذا الأمر.الشيخ: أعد أعد. يقول: إن من العادات الباقية لديهم فيما يتعلق بولادة المولود أن يأخذ المولود شخص معروف بالشجاعة والحذاقة وكتمان السر، ووالدة المولود تبقى أربعين يومًا في الحجبة لا تطلع من بيتها بل تبقى بداخل غرفة وحدها في إغلاق لمدة أربعين يومًا، هل هذه الأفعال كما يقول أخونا: هل هذه الأفعال في نظركم فيها شيء من الدين؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"ما حكم عادة حجب النفساء وحدها أربعين يومًا دون ولدها؟","answer":"الجواب: هذا كالذي قبله كله باطل، كله لا أساس له، لا حمل الولد من جهة إنسان معروف بالشجاعة إلى شيء معين يحمله إلى كذا أو إلى كذا أو يذهب به إلى كذا كله هذا لا أساس له، بل المولود يبقى عند والدته لإرضاعه والعناية به من أول ولادته أو يدفع إلى من تحضنه وتربيه وترضعه إذا كانت أمه لا تستطيع ذلك وليس فيها لبن، وأمه كذلك ليس لها أن تحبس نفسها في غرفة ولا في غيرها بل كسائر النساء يخرجن من محل الوالدة وتذهب إلى حاجاتها ولا تغلق عليها غرفة ولا غيرها بل هذا كله باطل وكله تشديد لا وجه له بل هو من الشيطان. نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12432/ما-حكم-عادة-حجب-النفساء-وحدها-اربعين-يوما-دون-ولدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61102.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":14023,"question":"يسأل أخونا عن حكم رفع اليدين بعد الصلاة المفروضة جمعًا من أجل الدعاء، وكذلك رفع اليدين إذا كان المرء منفردًا.","title":"حكم رفع اليدين بالدعاء عقب الصلاة","answer":"الجواب: رفع اليدين بعد الفريضة لا يجوز؛ لأنه لم يرد عن النبي ﷺ ولا عن أصحابه، ما كان النبي ﷺ يرفع يديه بعد الفريضة لا في الظهر ولا في العصر ولا في المغرب ولا في العشاء ولا في الفجر ولا في الجمعة، فلا يجوز للمسلم أن يرفع؛ لأن هذا حدث بدعة لا جماعيًا ولا فرديًا سواء كان فردًا أو مع الجماعة، وليس للإمام أن يفعل ذلك مع الجماعة بالدعاء الجماعي؛ لأن هذا محدث، والنبي عليه الصلاة والسلام قال: من عمل عملًا ليس عليه أمرنا فهو رد، وقال أيضًا عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد. فالواجب على أهل الإسلام التمسك بالشريعة والحذر من البدع، وكان النبي ﷺ يقول في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلالة. لكن رفع اليدين في الدعاء دعاء الاستغاثة إذا استغاث بالمسلمين استسقى بالمسلمين أو استسقى ولي الأمر في خطبة الجمعة أو في صلاة الاستسقاء أو بعض خطباء المساجد إذا استسقوا دعوا الله يغيث المسلمين فالسنة رفع اليدين، هكذا إذا دعا لنفسه وللمسلمين يدعو ويرفع يديه في دعائه بغير صلاة الفريضة لا بأس؛ لأن هذا من أسباب الإجابة، لكن شيء ما فعله النبي ﷺ لا تفعله، إذا سلمت من الفريضة لا ترفع يديك أو من الجمعة لا ترفع يديك، لكن إذا دعوت في أوقات أخرى أو بعد النافلة لا بأس أن ترفع يديك، وكذلك إذا حدث حادث فدعوت ربك أن الله يرفع هذا الحادث عن المسلمين أو عنك في بيتك أو في أي مكان ترفع يديك كل هذا لا بأس به، كان النبي ﷺ إذا حدث حادث رفع يديه ودعا، وهكذا إذا طلب منه بعض أصحابه أن يدعو فرفع يديه ودعا عليه الصلاة والسلام، ودعا في الاستسقاء ورفع يديه عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12441/حكم-رفع-اليدين-بالدعاء-عقب-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61111.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":14032,"question":"رسالة وصلت إلى البرنامج من قطر الدوحة، باعثها أخ لنا من هناك يقول: أخوكم علي عامر الشمري، أخونا يقول في رسالته: بعض الناس عندما يحلم بميت إذا كان ابن عمه أو من قرائبه؛ يذبح ذبيحة، أسأل عن هذا التصرف هل هو صحيح أم لا؟","title":"حكم الذبح عند رؤية قريب ميت في المنام","answer":"الجواب: ليس لهذا أصل، كونه إذا رأى قريبًا أو غيره يذبح ذبيحة، هذا لا أصل له، إن رأى ما يسره فليحمد الله، وليدع الله لأخيه المسلم، وإن رأى ما يسوءه فهو من الشيطان، فإذا استيقظ؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحدا، هكذا قال النبي ﷺ، يقول عليه الصلاة والسلام: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يسره؛ فليحمد الله، وليخبر بذلك من يحب، وإذا رأى ما يسوءه؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر؛ فإنها لا تضره ولا يخبر بها أحدًا، هذا هو المشروع، أما كونه يذبح ذبيحة أو يتصدق، هذا لا أصل له.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12463/حكم-الذبح-عند-روية-قريب-ميت-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60706.mp3","categories":["البدع والمحدثات"]},{"id":14038,"question":"سؤاله الأخير يقول: هل يجوز أن ينصب للميت بعد دفنه؛ لأن هناك بعض العادات القديمة ينصبون، ويجلسون ثلاثة أيام، والبعض سبعة أيام..الشيخ: أعد.المقدم: هل يجوز أن ينصب للميت بعد دفنه؛ لأن هناك بعض العادات القديمة ينصبون، ويجلسون ثلاثة أيام، والبعض سبعة أيام، وعند ذلك يدفع نقودًا عند العزاء، ويسجلون الأسماء ويحضرون الذبائح، وبعد ذلك يحضر المشايخ والدراويش، ويهللوا ويزغردوا، ويسمونها بالتهليلة على الميت، ويقولون: إن الذي لا يأكل من العزاء لا يحب المرحوم، ما هو المفروض بعد دفن الجثة؟ أفيدونا جزاكم الله خيرا.","title":"حكم إقامة الولائم بعد دفن الميت والتهليل والزغاريد","answer":"الجواب: أما النصب فلم يوضحه السائل ما هو النصب؟ لم يوضحه، والسنة في حق الميت إذا فرغ من دفنه أن يدعى له بالمغفرة والثبات، كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه، وقال:  استغفروا لأخيكم، وسلوا له التثبيت؛ فإنه الآن يسأل، ولا يجوز البناء على قبره، ولا اتخاذ مسجد على قبره، بل يجب أن يترك هكذا في الصحراء ضاحيًا للشمس، ليس عليه بناء، والرسول ﷺ لعن اليهود و النصارى على اتخاذهم المساجد على القبور.\nفالواجب أن تبقى القبور هكذا، ليس عليها بناء، ونهى أن تجصص، وأن يقعد عليها، وأن يبنى عليها، وأما العزاء اتخاذ ذبائح من أهل الميت يدعون لها الناس، ويجتمعون عليها ثلاثة أيام أو أكثر؛ هذي بدعة من أمر الجاهلية لا تجوز.\nأما المستحب فهو أن يبعث لهم طعام، يبعث لأهل الميت طعام من جيرانهم، ومن أقاربهم أيام الموت؛ لأنهم مشغولون بالمصيبة، فلا بأس بذلك.\nوالنبي ﷺ لما جاء نعي جعفر بن أبي طالب ، لما قتل في دومة في الشام، وجاء نعيه إلى المدينة؛ أمر أهل بيته أن يصنعوا طعامًا لأهل جعفر ، قال: اصنعوا لهم طعامًا فإنه قد أتاهم ما يشغلهم، فإذا صنع جيرانهم أو أقاربهم لهم طعامًا وبعثوه إليهم في بيوتهم؛ هذا مشروع لا بأس به، وإذا دعوا إليه من يأكل معهم من جيرانهم؛ لأنه طعام كثير، ودعوا إليه من يأكله معهم فلا بأس.  أما أن يقوم أهل الميت بصناعة الطعام وذبح الذبائح ودعوة الناس، هذا بدعة ومنكر، ومن أمر الجاهلية، وهكذا الزغردة والصياح والكلام الفارغ الذي يفعلونه بمناسبة الميت، لا أصل له، وقد قال جرير بن عبد الله البجلي : \"كنا نعد الاجتماع إلى أهل الميت وصناعة الطعام بعد الدفن من النياحة\" ، رأى أنه يعد من النياحة عند أصحاب النبي عليه الصلاة والسلام.\nفالمشروع لأهل الميت الصبر والاحتساب، وأن يستعملوا ما شرع الله من الصبر والاحتساب، وقول: إنا لله وإنا إليه راجعون، والسنة لأقاربهم وجيرانهم أن يبعثوا لهم طعامًا وقت المصيبة، اليوم الأول أو الثاني أو الثالث.. ليس له حد، ولا مانع أن يدعو بعض جيرانهم أو أقاربهم؛ ليأكلوا معهم مما بعث إليهم من الطعام، أما أن يصنعوا طعامًا هم ويذبحوا ذبائح، أو يحبسوا أنفسهم في البيت من أجل المصيبة لا، هذا ليس من أمر الإسلام، بل هو من أمر الجاهلية، فالمصاب له أن يخرج، وله أن يذهب إلى حاجاته وإلى مزرعته وإلى حاجاته الأخرى، وإذا جلس بعض الوقت المعتاد؛ ليسلم عليه من يزوره للعزاء، فلا بأس بذلك، وإن سلموا عليه في الطريق أو في المقبرة قبل الدفن أو بعد الدفن، كل ذلك لا بأس به يكفي، في الطريق، في المسجد، في المقبرة، قبل الدفن، بعد الدفن، في بيته؛ كل ذلك واسع، ولا يلزمه أن يبقى في البيت أو يشرع له أن يبقى في البيت يحبس نفسه لأجل ذلك، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12473/حكم-اقامة-الولاىم-بعد-دفن-الميت-والتهليل-والزغاريد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60710.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14071,"question":"أحد الإخوة المستمعين من جيزان بعث برسالة يقول فيها: إنه يوجد في القنفذة ناس لديهم عادة متوارثينها من القدم، وهي عندما يولد المولود يقطع سره، ويؤخذ ويدفن في بلاد والده؛ من أجل إذا كبر يحب البلاد، ما هو رأيكم شيخ عبد العزيز؟","title":"حكم نقل سرة المولود ودفنها في بلد والده","answer":"الجواب: هذا باطل، هذه خرافة من الخرافات لا يجوز، هذه خرافة لا تجوز، يقطع سره في محله ولا ينقل إلى بلد أخرى، وهذا الاعتقاد باطل، لا أصل لهذا، بل هذا يعتبر من الخرافات الفاسدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12514/حكم-نقل-سرة-المولود-ودفنها-في-بلد-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60909.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":14078,"question":"أحد الإخوة المستمعين من جيزان بعث برسالة يقول فيها: إنه يوجد في القنفذة ناس لديهم عادة متوارثينها من القدم، وهي عندما يولد المولود يقطع سره، ويؤخذ ويدفن في بلاد والده؛ من أجل إذا كبر يحب البلاد، ما هو رأيكم شيخ عبد العزيز؟","title":"حكم نقل سرة المولود ودفنها في بلد والده","answer":"الجواب: هذا باطل، هذه خرافة من الخرافات لا يجوز، هذه خرافة لا تجوز، يقطع سره في محله ولا ينقل إلى بلد أخرى، وهذا الاعتقاد باطل، لا أصل لهذا، بل هذا يعتبر من الخرافات الفاسدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12514/حكم-نقل-سرة-المولود-ودفنها-في-بلد-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60909.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":14197,"question":"من الجزائر السائل عبد الله يقول: أحييكم بتحية الإسلام وسؤالي هو كالآتي: إخواني في الإسلام! سؤالي هو بأن أحد الأشخاص قال لي في المولد النبوي الشريف: يعتبر هذا غير وارد في ديننا فهل هذا صحيح أم لا؟ أنا أقول له بأن هذا يوم عظيم ويجب أن نحتفل فيه، فما هو رأي الشرع في نظركم في ذلك يا سماحة الشيخ؟","title":"هل الاحتفال بالمولد النبوي جائز؟","answer":"الجواب: الاحتفال بالمولد النبوي غير مشروع، بل هو بدعة، لم يفعله النبي ﷺ ولا أصحابه، وهكذا الموالد الأخرى، لـعلي أو للحسين أو لـعبد القادر الجيلاني أو لغيرهم، الاحتفال بالموالد بدعة غير مشروعة، والرسول ﷺ هو الداعي إلى كل خير، وهو المعلم المرشد للأمة، وقد بعثه الله بشيرًا ونذيرًا وسراجًا منيرًا يدعو إلى كل خير، وقال الله في حقه: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا [سبأ:28]، وقال في حقه: يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا  ۝ وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِ وَسِرَاجًا مُنِيرًا [الأحزاب:45-46]، وقال تعالى: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا [الأعراف:158]. ولم يرشد أمته إلى الاحتفال، ولم يحتفل في حياته بمولده، ولا فعله الصديق ولا عمر ولا عثمان ولا علي ولا غيرهم من الصحابة، ولا في القرون المفضلة القرن الأول والثاني والثالث، وإنما أحدثه الرافضة، ثم تابعهم بعض المنتسبين للسنة. والرسول عليه السلام قال: من عمل عملًا ليس عليه أمرنا فهو رد وقال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد وكان يقول في خطبته عليه الصلاة والسلام: خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة.\nفالراجح والصواب عدم شرعية الاحتفال بالمولد؛ مولد النبي ﷺ وغيره، والله جل وعلا إنما نفع الأمة وهداها ببعثته ما هو بالمولد، إنما نفع الله الأمة وأرشدها وأخرجها من الظلمات إلى النور ببعثه ﷺ والوحي إليه، لما بعثه الله على رأس أربعين سنة وصار نبيًا رسولًا نفع الله به الأمة وأنقذ به الأمة من جهلها وضلالها لا بالمولد، نسأل الله أن يصلي عليه ويسلم عليه صلاة وسلامًا دائمين اللهم صل عليه...\nالمقصود أن الراجح هو أن الاحتفال بالمولد بدعة ولا يجوز فعله، وإن فعله كثير من الناس الآن، فالبدع لا ترجع سنة بفعل الناس، البدع بدع وإن فعلها الناس، ولكن المشروع للمسلمين العناية بأحاديثه وسيرته والسير على منهاجه، وتدريس سنته في المدارس وفي المساجد، تعليم الناس لسنته ودينه في المسجد في المدرسة في أي احتفال في الإذاعة حتى يتعلم الناس دينهم، وحتى يسترشدوا بما بينه لهم عليه الصلاة والسلام هذا هو المشروع. أما الاحتفال بمولده في ربيع الأول من كل سنة بالأكل والشرب والذبائح والخطب هذا لا أصل له، هذا من البدع وهو وسيلة إلى الشرك، كثير من هؤلاء المحتفلين يقع منهم الشرك والغلو في النبي عليه الصلاة والسلام مع البدعة. نسأل الله السلامة.\nالمقدم: جزاكم الله خيرًا على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/12650/هل-الاحتفال-بالمولد-النبوي-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54804.mp3","categories":["البدع والمحدثات"]},{"id":14304,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية باعثها مستمع من هناك، يقول السائل (س. س. ن. د) يسأل ويقول: ما حكم قراءة الفاتحة بعد الصلاة، ذلك أن أحد الأشخاص قال: إننا نتوسل بها إلى الله أن يغفر لنا ولوالدينا ونهديها إلى موتانا ثم إلى روح النبي ﷺ، ما حكم ذلك؟ هل يصل ثوابها إلى روح الموتى؟ وجهونا جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة بعد الصلاة وأهداء ثوابها للموتى","answer":"الجواب: لا نعلم لهذا أصلًا، والعبادات بالتوقيف والأدلة لا بالآراء والأهواء، العبادات توقيفية لا يشرع منها إلا ما شرعه الله ورسوله، ولا نعلم في الأدلة الشرعية شرعية قراءة الفاتحة بعد الصلاة وتثويبها للموتى، ولا الاجتماع على قراءتها لطلب الثواب، كل هذا لا أصل له، وإنما المشروع للمؤمن أن يقرأ القرآن ليتدبر ويتعقل ويستفيد وليحصل له الأجر بذلك. أما أن يخترع شيئًا ما شرعه الله في وقت لم ترد به السنة، هذا ليس بجائز؛ لأن الرسول عليه السلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، ولم يرد عنه فيما نعلم من الشرع أنه شرع للأمة قراءة الفاتحة بعد كل صلاة، أو تثويبها للموتى، أو قراءتها بصفة جماعية في أي وقت من الأوقات كل هذا لم يرد ولم نعرفه من الشرع المطهر.\nوالواجب على أهل الإيمان وأهل الإسلام أن يسعهم ما وسع الرسول ﷺ وأصحابه، وليس لأحد أن يحدث شيئًا لم يشرعه الله.\nولم يرد أيضًا أن القرآن يقرأ للموتى، ويثوب للموتى وإن كان قاله جمع من أهل العلم لكن أقوال العلماء تعرض على الكتاب والسنة، فما وافق النص قبل، وما لا فلا، وقد تأملت هذه المسألة فلم أجد في النصوص ما يدل على قراءة القرآن للموتى وتثويبه للموتى، ولكن المشروع الدعاء لهم بالمغفرة والرحمة بالجنة بالسعادة، بالعفو والمسامحة الصدقة عنهم، الحج عن الميت، العمرة عن الميت، قضاء الدين عن الميت، كل هذا مشروع.\nأما أن يصلى عنه أو يقرأ عنه فليس له أصل، أو يصام عنه تطوع فليس له أصل، أما إذا كان عليه صوم فريضة مات ولم يقضه فإنه يشرع الصيام عنه، كأن يكون عليه صوم من رمضان تساهل فلم يقضه، أو كفارة فإنه يصام عنه كما قال النبي ﷺ: من مات وعليه صيام صام عنه وليه متفق على صحته، وسأله جماعة عليه الصلاة والسلام، وأحدهم يقول: إن أمي ماتت وعليها صوم كذا، والآخر يقول: إن أبي مات وعليه صيام كذا، فيقول لهم ﷺ: أرأيت لو كان على أبيك.. أرأيت لو كان على أمك دين أكنت قاضيته؟ أكنت قاضيه؟ اقضوا الله؛ فالله أحق بالوفاء هذا هو المشروع.\nوالواجب على المؤمن والمؤمنة التقيد بما جاء في الشرع، وعدم إحداث شيء لم يشرعه الله  لا في الصوم ولا في القراءة ولا في الصلاة ولا في غير ذلك. وفق الله الجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12799/حكم-قراءة-الفاتحة-بعد-الصلاة-واهداء-ثوابها-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62209.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":14331,"question":"هذا سائل للبرنامج عبد الحليم عثمان من الجمهورية اليمنية يقول في هذا  هل يجوز قراءة الفاتحة عقب كل صلاة على روح النبي ﷺ أم أن هذا بدعة؟ وكيف نعرف البدع يا سماحة الشيخ؟","title":"حكم قراءة الفاتحة بعد الصلاة على روح النبي ﷺ","answer":"الجواب: هذا بدعة، القراءة على روح النبي ﷺ من البدع ليس له أصل في الشرع، والبدعة: هي فعل شيء ما شرعه الله، هذه البدعة التعبد بشيء ما شرعه الله؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، وقال أيضًا عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، وقال عليه الصلاة والسلام: كل محدثة بدعة وكل بدعة ضلالة فالتعبد بشيء ما شرعه الله يسمى ضلالة.\nومن هذا القراءة للنبي ﷺ قراءة مخصوصة، أو مطلقة، هذا ما شرعه الله، لكن تصلي عليه تقول: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم صل وسلم على نبينا محمد، اللهم صل وسلم على خاتم أنبيائك، اللهم صل وسلم على رسولنا محمد.. وما أشبه ذلك.\nوتقول: اللهم اجزه عنا خيرًا كما أحسن إلينا، تقول: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على إبراهيم .. إلى آخره، هكذا، تكثر من الصلاة عليه، عليه الصلاة والسلام، وتدعو له وتثني عليه وتتبع سنته، تحرص على اتباع السنة والاستقامة على دينه والعمل بشرعه.\nأما القراءة له ما شرع الله القراءة له، لا تقرأ للنبي ﷺ، ولكن تصلي عليه وتسلم عليه وتدعو له، تقول: جزاه الله عنا خيرًا، وضاعف الله مثوبته وأكثر حسناته.. إلى غير هذا من الدعوات الطيبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12806/حكم-قراءة-الفاتحة-بعد-الصلاة-على-روح-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55014.mp3","categories":["البدع والمحدثات","العالم والمتعلم","نصائح وتوجيهات"]},{"id":14332,"question":"يقول في فقرته التالية شيخ عبد العزيز: كيف نعرف بأن هذا العمل بدعة؟","title":"كيف نعرف أن العمل بدعة؟","answer":"الجواب: تعرف بأنه بدعة إذا كان ما هو بمشروع، إذا كان ما فيه دليل على أنه مشروع فالتعبد به يكون بدعة، كل عمل لا تعرف أنه مشروع من القرآن ولا من السنة فالتعبد به بدعة.\nمثل التعبد بالمولد الذي يكون في ربيع أول مولد النبي ﷺ الاجتماع والاحتفال بهذا المولد، مثل صلاة الرغائب التي في أول جمعة من رجب، كونه يصلي صلاة مخصوصة هذه بدعة، مثل الاحتفال بليلة الإسراء والمعراج هذه عبادة محدثة بدعة.\nمثل لو أن إنسانًا دعا إلى صلاة في الضحى جعل صلاة يدعو لها الناس يصلونها جماعة عادة يقول: هذه صلاة سادسة. هذه بدعة.. وما أشبه ذلك، يعني: يخترع عبادة ما شرعها الله، فهذه يقال لها: بدعة.\nأو يقول مثلًا: يشرع للناس أن يجتمعوا على صيام شهر معين كل سنة، يصير شهرًا ثاني يصومون رجب جميعًا يصومون ربيع أول يعني: ما يكفي رمضان يقول للناس: ما يكفيهم رمضان، بل ينبغي أن يصوموا شهرًا ثانيًا، فهذا من البدع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12808/كيف-نعرف-ان-العمل-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55015.mp3","categories":["البدع والمحدثات"]},{"id":14339,"question":"يقول في فقرته الأخيرة السائل عبد الحليم عثمان: هل يجوز الدعاء بعد الفراغ من الصلاة جهرًا أي: الإمام يدعو والمصلون يقولون بعده: آمين؟","title":"حكم دعاء الإمام بعد الصلاة وتأمين المأمومين","answer":"الجواب: هذا من أنواع البدع، كون الإمام يجهر بالدعاء ويؤمن عليه المأمومون هذا من البدع، ولكن يدعو الإنسان بينه وبين نفسه بعد الذكر، ويدعو الآخر بينه وبين نفسه بعد الذكر، أو قبل السلام أفضل يدعو قبل السلام، بعدما يتعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال يدعو بدعوات مما ورد في الشرع، مثل: اللهم إني أعوذ بك من البخل أعوذ بك من الجبن، أعوذ بك أن أرد إلى أرذل العمر، أعوذ بك من فتنة الدنيا ومن عذاب القبر، اللهم أعني على ذكرك وشكرك وحسن عبادتك، اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم، اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم مني أنت المقدم وأنت المؤخر لا إله إلا أنت، اللهم إنك عفو تحب العفو فاعف عني، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي -إذا كانا مسلمين-، وما أشبه ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12813/حكم-دعاء-الامام-بعد-الصلاة-وتامين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55017.mp3","categories":["البدع والمحدثات"]},{"id":14346,"question":"يقول في فقرته الأخيرة السائل عبد الحليم عثمان: هل يجوز الدعاء بعد الفراغ من الصلاة جهرًا أي: الإمام يدعو والمصلون يقولون بعده: آمين؟","title":"حكم دعاء الإمام بعد الصلاة وتأمين المأمومين","answer":"الجواب: هذا من أنواع البدع، كون الإمام يجهر بالدعاء ويؤمن عليه المأمومون هذا من البدع، ولكن يدعو الإنسان بينه وبين نفسه بعد الذكر، ويدعو الآخر بينه وبين نفسه بعد الذكر، أو قبل السلام أفضل يدعو قبل السلام، بعدما يتعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال يدعو بدعوات مما ورد في الشرع، مثل: اللهم إني أعوذ بك من البخل أعوذ بك من الجبن، أعوذ بك أن أرد إلى أرذل العمر، أعوذ بك من فتنة الدنيا ومن عذاب القبر، اللهم أعني على ذكرك وشكرك وحسن عبادتك، اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم، اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم مني أنت المقدم وأنت المؤخر لا إله إلا أنت، اللهم إنك عفو تحب العفو فاعف عني، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي -إذا كانا مسلمين-، وما أشبه ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12813/حكم-دعاء-الامام-بعد-الصلاة-وتامين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55017.mp3","categories":["البدع والمحدثات"]},{"id":14389,"question":"هذا سائل للبرنامج يقول عبدالله أحمد من اليمن: من المعتاد عندنا بأن الناس إذا حملوا الجنازة إلى المقبرة يقومون بذكر: لا إله إلا الله، مكررًا، وبالصوت الجماعي، وعندما يصلون إلى المقبرة يقرؤون سورة يس بصوت جماعي، وجهونا حول هذا العمل من حيث الإجازة، جزاكم الله خيرًا.","title":"حكم رفع الصوت عند الجنازة وقراءة يس أثناء الدفن","answer":"الجواب: رفعهم الصوت عند حملهم الجنازة بصوت جماعي هذا بدعة، ما له أصل، المشروع عند حمل الجنازة الإنسان يتذكر هذا المصير، يتذكر الآخرة والموت، ويكون عنده تذكر وخوف وحذر، أما وحدوه، أو لا إله إلا الله بصوت جماعي هذا بدعة ما له أصل، وهكذا قراءة يس عند القبر بدعة لا أصل لها؛ لأنها تقرأ يس عند المحتضر قبل أن يموت في بيته أو في أي مكان، أما أنها تقرأ في المقابر، أو عند الدفن فهذا بدعة لا أصل له، نعم.","link":"https://binbaz.org.sa/fatwas/12871/حكم-رفع-الصوت-عند-الجنازة-وقراءة-يس-اثناء-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55212.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":14403,"question":"السائل حسن إسماعيل من اليمن يقول: إذا مات الرجل، وأوصى قبل موته أن يذبحوا رأسًا من الغنم أو أكثر أثناء الدفن، وتقسم على الحاضرين، فهل أكلها جائز؟","title":"حكم وصية من أمر بالذبح وتوزيع اللحم أثناء دفنه","answer":"الجواب: هذه بدعة، لا تنفذ، هذه وصية بدعة، ليس لهم تنفيذها، نعم.","link":"https://binbaz.org.sa/fatwas/12885/حكم-وصية-من-امر-بالذبح-وتوزيع-اللحم-اثناء-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55222.mp3","categories":["الوصايا","البدع والمحدثات"]},{"id":14404,"question":"هذا السائل حسن إسماعيل من اليمن، استعرضنا سؤالاً له في حلقة سابقة، بقي له هذا السؤال يقول: سماحة الشيخ في اليوم الثالث من موت الميت تقام محاضرة في بيت الميت، ويحضرها جمع من الناس، هل هذا العمل جائز، أو هو من البدع؟","title":"حكم اعتياد إقامة محاضرة في بيت الميت في اليوم الثالث","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فاعتياد إقامة محاضرة في بيت الميت في اليوم الثالث، أو طعام، أو شبه ذلك، ليس من الشرع في شيء، بل هو بدعة، أما إذا كان عارض استمعوا يسلمون على أهل الميت ويعزونهم، فذكرهم بعض الناس لا بأس شيء عارض، أما اتخاذ هذا عادة وسنة جارية في اليوم الثالث أو الثاني أو الرابع أو الخامس إقامة حفل وموعظة وخطبة أو أكل هذا بدعة، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12886/حكم-اعتياد-اقامة-محاضرة-في-بيت-الميت-في-اليوم-الثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55301.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14426,"question":"يسأل أخونا ويقول: أهل الميت في ليلة الرابع من أيام العزاء يقومون بذبح الأغنام، ويقولون: هي صدقة عن الميت، ولا ندري هل هي من ماله الذي تركه لورثته أم من مال بعض الأقرباء أم أنها مقدمة من بعض من جاء يقدم العزاء من المتأخرين في تقديمه؟ نرجو التفصيل في حكم هذا، جزاكم الله خيرًا.","title":"حكم تخصيص ليلة الرابع بعد الوفاة بالذبح والصدقة","answer":"الجواب: اعتياد هذا لا يجوز، كونه يعتادون اليوم الرابع أو السابع أو الأربعين يذبحون ذبائح، ويتصدقون عن الميت هذا من البدع، لا يجوز هذا، لكن لو جاءهم ضيوف في اليوم الثالث، أو جاءهم ضيوف في اليوم الرابع، أو في الخامس، وذبحوا لهم، أو معهم ذبائح فذبحوا منها لهم لا بأس بذلك لإكرام الضيوف.  أما أن يتخذوه عادة في اليوم الرابع أو الثالث أو الخامس أو العاشر أو السابع، أو غير هذا عادة لا يجوز، بل يجب ترك البدع، والحذر منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12927/حكم-تخصيص-ليلة-الرابع-بعد-الوفاة-بالذبح-والصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62406.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14440,"question":"يسأل أخونا ويقول: أهل الميت في ليلة الرابع من أيام العزاء يقومون بذبح الأغنام، ويقولون: هي صدقة عن الميت، ولا ندري هل هي من ماله الذي تركه لورثته أم من مال بعض الأقرباء أم أنها مقدمة من بعض من جاء يقدم العزاء من المتأخرين في تقديمه؟ نرجو التفصيل في حكم هذا، جزاكم الله خيرًا.","title":"حكم تخصيص ليلة الرابع بعد الوفاة بالذبح والصدقة","answer":"الجواب: اعتياد هذا لا يجوز، كونه يعتادون اليوم الرابع أو السابع أو الأربعين يذبحون ذبائح، ويتصدقون عن الميت هذا من البدع، لا يجوز هذا، لكن لو جاءهم ضيوف في اليوم الثالث، أو جاءهم ضيوف في اليوم الرابع، أو في الخامس، وذبحوا لهم، أو معهم ذبائح فذبحوا منها لهم لا بأس بذلك لإكرام الضيوف.  أما أن يتخذوه عادة في اليوم الرابع أو الثالث أو الخامس أو العاشر أو السابع، أو غير هذا عادة لا يجوز، بل يجب ترك البدع، والحذر منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12927/حكم-تخصيص-ليلة-الرابع-بعد-الوفاة-بالذبح-والصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62406.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14540,"question":"سماحة الشيخ، الصلاة خلف المبتدع ما حكمها؟","title":"ما حكم الصلاة خلف المبتدع؟","answer":"الجواب: الصلاة فيها تفصيل خلف المبتدع: إذا كان المبتدع ابتدع بدعة تكفر كـالجهمي، هذا لا يصلى خلفه، والمعتزلي الذي ينفي صفات الله والخوارج، لا يصلى خلفهم.  أما إذا بدعة خفيفة مثال: يقول: نويت أن أصلي، أو عنده بدعة أخرى غير هذا من البدع الخفيفة التي لا تفضي إلى الشرك، فالأمر في هذا سهل يصلى خلفه، ولكن إذا تيسر إزالته، والتماس إمام من أهل السنة، فهذا هو الواجب، ولكن إذا دعت الضرورة إلى أن يصلى خلفه إذا كانت بدعته لا تكفره كالعاصي كالذي يعرف بالمعاصي يصلى خلفه ما دام مسلم، نعم.","link":"https://binbaz.org.sa/fatwas/13036/ما-حكم-الصلاة-خلف-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55503.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":14592,"question":"هناك عادات عند بعض الناس لا ندري هل هي من الإسلام أم هي بدعة -مثلًا-:في بعض المناطق في الريف هناك بعض الناس يقولون قبل تكبيرة الإحرام للصلاة: نويت أصلي صلاة الظهر مثلًا مقتديًا أو إمامًا الفرض الحاضر، وهلم جرًا، بصوت يسمعه من كان بجانبه، هل هذا صحيح؟ وجهونا، جزاكم الله خيرًا.","title":"هل يجوز التلفظ بالنية قبل الصلاة؟","answer":"الجواب: هذا لا أصل له، بل هو من البدع التي أحدثها بعض الناس، وإن كان قال ذلك بعض أهل العلم المتأخرين، لكنه ليس بمشروع.  والصواب: أنه لا يقول ذلك، ولكن ينوي بقلبه، فلم يكن النبي ﷺ يقول ذلك ولا أصحابه ، ولا الأئمة من العلماء في القرون المفضلة، ولا يعرف ذلك عن واحد منهم، فلا يقول: نويت أن أصلي الظهر كذا، أو العصر كذا، أو المغرب كذا أو العشاء كذا، أو الفجر كذا إمامًا أو مقتديًا أو منفردًا كل هذا لا يقال، التلفظ بالنية ليس بمشروع. وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، وكان يقول في خطبة الجمعة -عليه الصلاة والسلام-: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة. فنصيحتي لجميع إخواني المسلمين في كل مكان أن لا يقولوا هذا اللفظ عند الصلاة، أن لا يتلفظوا بالنية؛ لأنه لا أصل لذلك، ولكن إذا قام إلى الصلاة فقد نوى، إذا سمع الإقامة فقد نوى الصلاة، أو قام في بيته يصلي سنة الضحى أو يتهجد بالليل أو الرواتب إذا قام إلى الصلاة بقلبه ناويًا فقد حصل المقصود، ولا حاجة إلى أن يقول: نويت أن أصلي كذا، لا في المسجد ولا في البيت، لا منفردًا ولا مع الإمام، ولا يقوله الإمام أيضًا، وفق الله الجميع لاتباع السنة، والاستقامة عليها. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13089/هل-يجوز-التلفظ-بالنية-قبل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63512.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":14593,"question":"هناك بعض الناس إذا بدأ قراءة التشهد يبدؤها بقوله: الحمد لله، هل ورد في هذا شيء؟","title":"حكم بدأ التشهد بالحمد لله","answer":"الجواب: لا، ليس بمشروع، يبدؤها بقوله: (التحيات) هذا المشروع، المحفوظ عن النبي ﷺ أنه علمهم أن يقولوا: التحيات لله... هذا أول التشهد، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13090/حكم-بدا-التشهد-بالحمد-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_635013.mp3","categories":["التشهد والتسليم","البدع والمحدثات"]},{"id":14607,"question":"يقول السائل من اليمن: اعتاد البعض من الناس عندنا بعد فراغ الإمام من الصلاة يؤدي كل شخص منا الاستغفار والأذكار الواردة عقب الصلاة في سره، ولكن بعد ذلك يقوم الإمام بالدعاء بصوت مسموع، ويقول المأمومون بالتأمين ورد الدعاء بعد الإمام، فهل هذا العمل صحيح، أم ماذا؟َمأجورين.","title":"حكم جهر الإمام بالدعاء عقب الصلاة","answer":"الجواب: هذا بدعة، ليس له أصل، ما كان النبي ﷺ يفعله، ولا الصحابة -رضي الله عنهم وأرضاهم-، ولكن كل واحد يذكر الله، ويدعو بينه وبين نفسه، يذكر الله الأذكار الشرعية، ويدعو بعد الأذكار بينه وبين نفسه، لا بأس.  والدعاء قبل السلام أفضل، الدعاء قبل السلام أفضل؛ لأن الرسول ﷺ لما علم الصحابة التشهد والصلاة على النبي ﷺ والتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال أمرهم أن يسألوا، فقال: ثم ليختر من الدعاء أعجبه إليه فيدعو، ثم ليختر من المسألة ما شاء فالإنسان يدعو ربه في آخر الصلاة، وإن دعا بعد الذكر بعد السلام فلا بأس. فالسنة للمؤمن إذا سلم من الصلاة الفريضة أن يقول: أستغفر الله، أستغفر الله، أستغفر الله، ثلاث مرات، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام، هكذا كان النبي ﷺ يفعل، كما قال ثوبان : «كان النبي ﷺ إذا انصرف من الصلاة استغفر ثلاثًا، وقال: اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام. وأخبرت عائشة -رضي الله عنها-: «أنه إذا قال: اللهم أنت السلام انصرف إلى الناس» الإمام إذا كان إمامًا، ثم يقول الإمام والمنفرد والجماعة بعد هذا يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، والأفضل أن يكررها ثلاثًا، ثم يقول: لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة وله الفضل، وله الثناء الحسن، لا إله إلا الله، مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد كل هذا ثابت عن النبي ﷺ إذا سلم من الصلاة قال هذا. ويستحب أن يزيد في المغرب والفجر عشر مرات: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير مع الذكر المتقدم، يزيد في الفجر وفي المغرب هذا الذكر: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير عشر مرات. ثم بعد هذا يسبح ويكبر ويحمد ثلاثًا وثلاثين مرة، سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، الجميع تسعة وتسعون، ويختم المائة بقوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير هذا مستحب للرجل والمرأة بعد الفريضة، يعني: الفرائض الخمس الظهر والعصر والمغرب والعشاء والفجر، إذا سلم يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام ربنا هو السلام المسلم لعباده، اسمه السلام، ومنه السلام، هو الذي يسلم لعباده، هو الذي يمن بالسلامة للعباد منه -جل وعلا-، تباركت يا ذا الجلال والإكرام، تباركت: صفة مبالغة ما تصلح إلا لله، تبارك الله ربنا، ما يقال: تباركت يا فلان علينا، لا، هذا وصف لله تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ [الأعراف:54]، تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ [الملك:1]. ثم بعد هذا يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير وإن زاد: يحيي ويميت كذلك طيب لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير جاء هذا وهذا، يكررها ثلاثًا بعد الظهر والعصر والعشاء والمغرب والفجر، ويقول بعدها: لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، لا إله إلا الله، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، ويزيد في المغرب والفجر: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو كل على شيء قدير عشر مرات. ثم يسبح ويحمد ويكبر ثلاثًا وثلاثين مرة بعد الفرائض الخمس: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، هذه تكون تسعة وتسعين، ثم يختم المائة بقوله: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، ويستحب أن يقول بعد هذا آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ... [البقرة:255] ويقرأ: قُلْ هُوَ اللهُ أَحّدٌ [الإخلاص:1]  والمعوذتين أيضًا، هذا مستحب، ويكرر: قُلْ هُوَ اللهُ أَحّدٌ [الإخلاص:1] والمعوذتين بعد المغرب وبعد الفجر ثلاث مرات: قُلْ هُوَ اللهُ أَحّدٌ [الإخلاص:1] وقُلْ أَعُوذُ بِرَبِّ الفَلَقِ [الفلق:1]  وقُلْ أَعُوذُ بِرَبِّ النّاسِ [الناس:1] بعد الفجر والمغرب ثلاث مرات أفضل، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13100/حكم-جهر-الامام-بالدعاء-عقب-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55902.mp3","categories":["البدع والمحدثات"]},{"id":14608,"question":"يقول السائل من اليمن: ما قول العلماء في أناس يتلفظون بالنية في كثير من أعمالهم الدينية، وخاصة في الصوم والصلاة، مثل قول البعض عن الاستعداد للصلاة: أصلي فرض كذا الله أكبر، وهل التلفظ بالنية وارد عن المصطفى ﷺ؟","title":"ما حكم التلفظ بالنية في الأعمال؟","answer":"الجواب: هذا بدعة، ما يجوز.\nالتلفظ بالنية بدعة، ينوي في قلبه، والحمد لله، إذا قام بنية الصلاة كبر فقط، ما يقول: نويت أن أصلي كذا وكذا، ولا نويت أن أطوف، يأتي بالنية إذا قام للصلاة، ينوي الظهر يكبر، إذا قام العصر كبر بنية العصر، المغرب كبر بنية المغرب، وهكذا بالقلب نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13102/ما-حكم-التلفظ-بالنية-في-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55903.mp3","categories":["البدع والمحدثات"]},{"id":14643,"question":"سؤاله الثاني: دخلت أحد المساجد لأداء صلاة الجمعة، وبعد نهاية الصلاة والتسبيح بالباقيات الصالحات سمعت الإمام يقول: يا لطيف، وشرع المصلون في قولها، سألت جاري، فقال لي: قلها مائة مرة، واسمع من أركان المسجد نغمة آمين، يرددها المصلون، فهل هناك دليل على قول: يا لطيف بعد الباقيات الصالحات؟ وما الحكم؟جزاكم الله خيرًا.","title":"حكم قول: (يا لطيف) بعد الصلاة مائة مرة","answer":"الجواب: لا نعلم على هذا دليلًا، بل هو من البدع التي أحدثها الناس، كونه يقول: يا لطيف، مائة مرة، أو عشر مرات أو أقل أو أكثر، على طريقة ثابتة بعد كل صلاة هذا لا أصل له، بل هو من البدع.  أما إذا قالها عارضًا عند قيامه: يا لطيف الطف بنا، أو: يا لطيف اغفر لي، أو يا رحمن اغفر لي، عارض شيء ليس بمعتاد، وإنما هو عند قيامه، أو في حال مشيه، أو في حال ذكره لله، لا بأس بهذا.  أما اتخاذ هذا عادة يقولها بعد كل صلاة، أو يقولها هو والجماعة بعد كل صلاة في السنة الراتبة عشر مرات، أو مائة مرة أو أكثر أو أقل هذا لا أصل له، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13131/حكم-قول-يا-لطيف-بعد-الصلاة-ماىة-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62703.mp3","categories":["البدع والمحدثات"]},{"id":14665,"question":"تقول السائلة أم معاذ من المدينة المنورة: ما حكم صلاة التسبيح؟ وهل هي واردة أم لا؟","title":"عدم مشروعية صلاة التسابيح","answer":"الجواب: صلاة التسبيح غير ثابتة، حديثها ضعيف، ولا يجوز استعمالها؛ لأنها خلاف الصلاة المشروعة الثابتة عن النبي ﷺ، فحديثها غير صحيح، نعم.","link":"https://binbaz.org.sa/fatwas/13156/عدم-مشروعية-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56006.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":14818,"question":"يسأل ويقول: لدى كثير من الناس عادة، وهو أنه عندما يعطس أحد فيقول الشخص الذي يتكلم بعطسة: حلال، هل هذا الكلام صحيح؟","title":"حكم قول المتكلم عندما يعطس شخص: بعطسة حلال","answer":"الجواب: لا أصل لهذا، هذا كلام العامة لا أصل له، ولكن المشروع للمؤمن إذا عطس أن يقول: الحمد لله، ومن سمعه يقول له: يرحمك الله، وهو يقول: يهديكم الله ويصلح بالك، هذا السنة، إذا عطس يقول: الحمد لله، أو الحمد لله رب العالمين، أو الحمد لله على كل حال، ومن سمعه يقول: يرحمك الله، هذا السنة، وهو يقول لمن قال: يرحمك الله، يقول له: يهديكم الله، ويصلح بالكم، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13329/حكم-قول-المتكلم-عندما-يعطس-شخص-بعطسة-حلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64310.mp3","categories":["نواقض الإسلام","البدع والمحدثات","الآداب والأخلاق المحمودة"]},{"id":14887,"question":"هل يجوز للمؤذن أن يقرأ قبل الأذان بضع آيات من القرآن، وعند انتهاء الأذان يأتي بالدعاء الذي بعد الأذان في مكبرات الصوت؟ وأيضًا هل يجوز قراءة القرآن جهرًا في مكبرات الصوت والقارئ لا يجيد القراءة، والمسجد الذي يقرأ فيه هذا القارئ صغير؟","title":"حكم قراءة القرآن قبل أذان الفجر في مكبرات الصوت","answer":"الجواب: لا حاجة إلى هذا، إنما المشروع الأذان في آخر الليل فقط، أما أن يقرأ هذا قد يشق على الناس، وقد يوقظ النوام، فلا ينبغي هذا، ولكن يؤذن الأذان الشرعي قبل الصبح بقليل للتنبيه إذا دعت الحاجة إلى ذلك، وإن ترك الأذان الأول فلا بأس، ما هو لازم، إنما المهم الأذان الأخير على طلوع الفجر، هذا هو المهم، هذا هو الفرض فرض كفاية.  وأما أنه ينبه الناس بالقراءة بالمكبرات بدلًا من الأذان، أو قبل الأذان هذا غير مشروع، إنما يقرأ بينه وبين نفسه في المسجد، أو في البيت من دون أن يقرأ في المكبر؛ لأن هذا قد يشق على الناس، ولم يفعله سلف الأمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13385/حكم-قراءة-القران-قبل-اذان-الفجر-في-مكبرات-الصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63906.mp3","categories":["البدع والمحدثات"]},{"id":14891,"question":"هل يصح الأذان على الميت في القبر أم لا؟ وهل يجوز القنوت بعد دفن الميت؟","title":"حكم الأذان على القبر والقنوت بعد الدفن","answer":"الجواب: كل هذا بدعة، لا يؤذن في القبر، ولا يقنت قنوت الدعاء المعروف، ولكن يدعى له دعاء، الدعاء العادي، إذا فرغوا من الدفن يسألوا الله له التثبيت والمغفرة.  أما القنوت مثل قنوت الصلاة لا، ولكن كل واحد يدعو لأخيه «كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم، واسألوا له التثبيت فإنه الآن يسأل فيقول: اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم ثبته على الحق، ولا يقنت قنوت الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13388/حكم-الاذان-على-القبر-والقنوت-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63908.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":14894,"question":"له سؤال طويل عن البدع؛ البدعة الحسنة وغير الحسنة، يقول فيه: هل توجد بدع حسنة، وبدع سيئة؟ مع أن بعض البدع لا بأس بها، ولا تمس جوهر الدين في شيء، وهل لأصحاب المذاهب آراء في ظهور البدع؟ وهل منهم من أجاز البعض منها؛ لأننا عندما نتحدث إلى شخص ونحاول إقناعه بأن بعض الذي يعمله بدعة وكل بدعة ضلالة فيقول: هذه لا بأس بها؛ لأنها لا تضر بالدين، مع العلم أن هناك من يرى الدعاء بعد الصلاة بالمصلين وهو إمام، وكاد بعض المصلين أن يؤذيه؛ لأنه ترك الدعاء بهم، هذا إلى جانب تفشي كثير من البدع. أرجو توضيح هذه المسألة، جزاكم الله خيرًا، ووفقكم لأداء رسالتكم.والسلام عليكم ورحمة الله وبركاته.","title":"هل توجد بدعة حسنة؟","answer":"الجواب: البدع ليس فيها حسنة، كلها ضلالة، كما قاله النبي ﷺ: وكل بدعة ضلالة هذا كلام عظيم، وقاعدة كلية عظيمة، قالها النبي ﷺ، والبدعة هي التي يحدثها الناس في الدين، عبادات ما شرعها الله يقال لها: بدعة، مثل إحداث شيء ما شرعه الله في الصلاة من رفع اليدين بين السجدتين، أو في آخر الصلاة، أو بعد السلام من الفريضة، هذه بدعة ما شرعها الله -جل وعلا-، مثل إحداث الاحتفالات بالموالد هذه بدعة ما أنزل الله بها من سلطان، مثل إحداث البناء على القبور، اتخاذ المساجد عليها، هذه من البدع أيضًا، وما أشبه ذلك مما أحدثه الناس.  والقاعدة: أن كل ما أحدثه الناس في الدين وسموه طاعة وقربة، وليس له أصل في الشرع يسمى بدعة. أما ما يظن بعض الناس أنه بدعة حسنة، وليس كذلك فهذا ليس من البدع، مثل المساجد بالأسمنت، هذا شيء جديد ولا يسمى بدعة؛ لأن الرسول ﷺ أمر ببناء المساجد، سواء كانت بالطين أو باللبن أو بالحجر أو بالخشب أو بالأسمنت كله ما يسمى بدعة، ومثل المدارس المبنية والربط هذه ما تسمى بدعة ضلالة، وإن سماها الناس بدعة من جهة اللغة، من جهة أنها لم تكن سابقة غير موجودة، لكن الرسول ﷺ أمر بما ينفع الناس، أمر بالتعليم، وأمر بتعمير المساجد، فإذا عمر الناس مسجدًا بالأسمنت أو عمر الناس مدرسة، أو رباطًا للفقراء أو للمهاجرين، أو للغرباء فلا بأس، كل هذا ما يسمى بدعة سيئة، هذه من الأمور الشرعية؛ لأنه نفع المسلمين، والإحسان إليهم، امتثالًا لأمر الله  في الأمر بنفع المسلمين، والإحسان إلى الفقراء، وتعليم الجاهل، سواء كان يعلم في المسجد، أو يعلم في المدرسة ليس هذا من البدع التي حذر منها النبي ﷺ، وإن سميت بدعة من حيث اللغة، كما قال عمر  في التراويح: \"نعمت البدعة\" يعني: من حيث اللغة؛ لأنه رتبهم على إمام واحد في كل ليلة، فسماها بدعة من حيث اللغة؛ لأنها في عهد النبي ﷺ كانوا يصلون أوزاعًا كل جماعة وحدهم، صلى بهم النبي ﷺ ثلاث ليال ثم تركهم، وقال: إني خشيت أن تفرض عليكم صلاة الليل أو قال: إني أخاف أن تفرض صلاة الليل فترك ذلك خوفًا على الأمة من أن يفرض عليهم صلاة الليل، فلما كان في زمن عمر جمع الناس على إمام واحد يصلي بهم التراويح، وقال: «نعمت البدعة» يعني: من حيث اللغة وإلا فهي سنة، التراويح سنة فعلها النبي ﷺ ورغب فيها -عليه الصلاة والسلام-. فهكذا الربط والمدارس التي يفعلها الناس كالتعليم، وهكذا ما يسمى بالمعاهد، وهكذا ما يسمى بالمجامع للناس لتحفيظهم القرآن، أو ما أشبه ذلك على اختلاف الأسماء أو خلوات، أو على حسب اختلاف الناس في الأسماء، كل ذلك مما ينفع الناس، وليس من البدع، بل هو من باب التعاون على البر والتقوى، ومن باب الحرص على تعليم الناس الخير وجمعهم في أماكن تحفظهم وتحفظ أدوات التعليم، وليس هذا من باب البدع. أما قوله ﷺ في الحديث الصحيح: من سن في الإسلام سنة حسنة كان له أجرها وأجر من عمل من بعده لا ينقص من أجورهم شيئًا فهذا معناه: إظهار السنن، يعني: إظهار العبادة التي خفيت وجهلها الناس، فالذي يظهرها للناس، ويسنها للناس له أجر عظيم؛ لأنه أحيا السنن، وليس معناه: أنه يبتدع في الدين ما لم يأذن به الله؛ لأن الله ذم من فعل ذلك، وقال: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ[الشورى:21] وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد فالإحداث منكر، ولكن إحياء السنن وإظهارها بين الناس عند خفائها وعند جهل الناس بها، هذه هي السنة في الإسلام، وهو معنى من سن في الإسلام... ويدل على هذا أن الحديث سببه أن النبي ﷺ لما حرض على الصدقة، وحث الناس على الصدقة جاء إنسان بصرة في يده كادت كفه تعجز عنها فقدمها، فلما رأوه الناس تتابعوا، وجاءوا بالصدقات، فقال النبي ﷺ عند ذلك: من سن في الإسلام سنة حسنة... يعني: أظهر الصدقة، وجاء بالمال، فتتابع الناس، واقتدوا به في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13395/هل-توجد-بدعة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63913.mp3","categories":["البدع والمحدثات"]},{"id":14896,"question":"سماحة الشيخ، لا بد أن هناك حدًا فاصلًا، وحدًا دقيقًا للفرق بين البدعة وبين السنة، بين ما هو في الدين وبين ما هو في الدنيا؟","title":"ما الفرق بين البدعة والسنة؟","answer":"الجواب: أمور الدنيا ما فيها بدع، وإن سميت بدعًا، اختراع الناس السيارات أو الطائرات أو الحاسب الآلي أو شبه ذلك مما اخترعه الناس أو الهاتف أو البرقية، كل ذلك ما يسمى بدعًا، وإن سمي بدع من حيث اللغة، فهو غير داخل في بدع الدين؛ لأن البدعة في اللغة: في الشيء الذي لم يكن له مثال سابق، اخترع يسمى في اللغة بدعة، مثل بديع السماوات، يعني: مخترعهم ، فهذا في اللغة يطلق على ما كان ليس له مثال سابق، وإذا كان في الدنيا ما يسمى بدعة، ما يذم يعني، وإن سمي بدعة من حيث اللغة، لكن ما ينكر؛ لأنه ليس في الدين ليس في العبادات، فإذا سمي مثلًا اختراع السيارة، أو الحاسب الآلي أو الطائرة، أو ما أشبه ذلك سمي بدعة، فهذا من حيث اللغة، وليس بمنكر، ولا ينكر على الناس.  وإنما ينكر من الناس ما أحدثوه في الدين من صلوات مبتدعة أو عبادات أخرى مبتدعة، هذا هو الذي ينكر في الدين؛ لأن الشرع يجب أن ينزه عن البدع، فالشرع ما شرع الله ورسوله، لا ما أحدثه الناس في دين الله من صلاة أو صيام، أو غير ذلك مما لم يشرعه الله ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13397/ما-الفرق-بين-البدعة-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63914.mp3","categories":["البدع والمحدثات"]},{"id":14898,"question":"رسالة وصلت إلى البرنامج من ليبيا، وباعثها مستمع من هناك يقول: (ع. أ. س) بدأ رسالته بقوله: أسرة برنامج نور على الدرب. السلام عليكم ورحمة الله وبركاته. أتوجه إليكم برسالتي هذه، وأشكركم بعد شكر الله  على جهودكم المبذولة في سبيل توضيح الحلول التي تجول في خاطر الكثير المتطلعين لمعرفة أصول دينهم، راجيًا منكم الرد على هذه الرسالة ردًا شافيًا، جزاكم الله خيرًا. أسألكم أولًا عن حكم الدعاء الجماعي بعد الصلاة المكتوبة؟","title":"حكم الدعاء الجماعي بعد الصلاة المكتوبة","answer":"الجواب: الدعاء الجماعي بعد الصلاة المكتوبة، أو في غيرها، بدعة لا أصل له، حتى في غير الصلاة، كونهم يدعون دعاء جماعيًا، ما له أصل، إنما الإنسان يدعو لنفسه، أو يدعو ويؤمن إخوانه كالقنوت، يدعو الإمام ويؤمن المأمومون، أما يدعو بصوت واحد جماعيًا، هذا لا أصل له، ولا سيما عقب الصلاة، كل هذا بدعة.  فالإنسان يدعو لنفسه، بينه وبين ربه في آخر الصلاة قبل أن يسلم، أو بعد السلام بينه وبين ربه، يدعو من دون رفع اليدين، لا بأس بهذا، بينه وبين نفسه، أما أن يدعو الإمام ويرفع يديه وهم يرفعون أيدهم معه ويدعون هذا لا أصل له، وليس من الشرع، وهكذا رفع الصوت بالدعاء جماعيًا بصوت واحد كل هذا لا أصل له، لا في المسجد، ولا في غير المسجد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13394/حكم-الدعاء-الجماعي-بعد-الصلاة-المكتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63912.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":14899,"question":"سماحة الشيخ، متى بدأت البدع؟ وهل هناك من أمل في استئصالها؟","title":"وقت ظهور البدع وكيفية القضاء عليها","answer":"الجواب: من العهد الأول، فهي قديمة الوجود، من القرن الأول، نسأل الله السلامة، نعم. المقدم: الأمل في استئصالها سماحة الشيخ كيف يكون بأي وسيلة؟\nالشيخ: ليس لها طريق إلا الدعوة إلى الله، وتعليم الناس الخير، وقوة ولاة الأمور في إنكارها، وتعزير من يفعلها، فإذا قوي السلطان، والوازع السلطاني في بلد، وبين العلماء حقيقة البدع في الغالب أنها تنتهي في البلد تزول، وإن بقيت في بلاد أخرى، أو في دولة أخرى، فعلى حسب قوة السلطان، وقوة الوازع، وبيان أهل العلم تقل البدع، وإذا قلَّ أهل العلم، أو قلَّ الوازع السلطاني كثرت الخرافات والبدع في البلاد والمناطق، وكلما زادت الجهالة وزاد الخرافيون في البلد، وقلَّ الوازع السلطاني، وقلَّ العلماء تكثر البدع وتنتشر.  فإذا وجد العلماء أهل البصيرة في الدين، ووجد الوازع السلطاني في إنكار البدع قلت البدع، حتى تزول من البلد، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13398/وقت-ظهور-البدع-وكيفية-القضاء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63915.mp3","categories":["البدع والمحدثات"]},{"id":14930,"question":"من جمهورية مصر العربية، المستمع فراج عوض صالح، يسأل ويقول: يوجد لدينا في بلدتنا عندما يتوفى أحد يخرج النساء على القبور بالأكل والمشروبات والحلويات والخضر، ويعطوها لبعض الناس، فهل هذا يجوز أم لا يجوز؟ثم إن أهل المتوفى يفرشون ويحضرون مقرئًا له، ويضعون له ميكرفون، ويعطونه مبلغًا من المال، فما هو رأيكم تجاه هذه الأفعال؟جزاكم الله خيرًا.","title":"حكم توزيع الأطعمة وقراءة القرآن عند القبور","answer":"الجواب: هذه الأفعال من البدع، فلا يجوز فعل ذلك، لا خروجهم بالأطعمة عند القبور، ولا إيجاد قاري، كل هذا من البدع. فالمقصود: أنه لا يقرأ عند القبور، ولا يجتمع عندها للقراءة، ولا يجتمع عندها لتوزيع الأطعمة، الخروج بالأطعمة حتى توزع عند القبور، كل هذا لا أصل له، ليس من فعل السلف الصالح، بل هو من البدع، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من أحدث في أمرنا يعني: في ديننا  هذا ما ليس منه فهو رد متفق على صحته، ومعنى: فهو رد: يعني مردود. وقال -عليه الصلاة والسلام-: من عمل عملاً ليس عليه أمرنا فهو رد رواه مسلم في الصحيح، يعني: فهو مردود. والأحاديث في هذا المعنى كثيرة، والله يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] ويقول سبحانه: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا [الجاثية:18].\nفالواجب على أهل الإسلام اتباع الشريعة التي ثبتت عنه -عليه الصلاة والسلام-، والتقيد بها، والحذر مما يخالفها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13428/حكم-توزيع-الاطعمة-وقراءة-القران-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49207.mp3","categories":["البدع والمحدثات"]},{"id":14969,"question":"المرسل (م. م. س) يقول: نعلم أن في بعض الدول تقام حفلة بمناسبة مولد من الموالد: كمولد النبي أو مولد علي -كرم الله وجهه-، ويقوم موظفو وزارة العدل بإحياء هذه الذكرى، هل إحياؤها يعتبر من البدع؟ وإذا كانت بدع فكيف لهؤلاء أن يصدوا عنها؟وفقكم الله.","title":"حكم الاحتفال بمولد النبي ﷺ أو غيره","answer":"الجواب: الاحتفال بالموالد ليس بمشروع، بل هو من البدع، ولم يثبت عن النبي ﷺ ولا عن أصحابه أنهم احتفلوا بالمولد النبوي، وهكذا في القرون المفضلة: القرن الأول والثاني والثالث لم يوجد في هذه القرون المفضلة من يحتفل بالمولد النبوي، فهو من البدع التي أحدثها الناس.  وقال بعض أهل العلم: إن أول من أحدثها حكام المغرب ومصر، وهم بنو عبيد القداح، المسمون الفاطميون، وهم من الشيعة، قال فيهم شيخ الإسلام ابن تيمية: إن ظاهرهم الرفض، وإن باطنهم الكفر المحض. قال بعض الناس: إنهم أحدثوا الاحتفال بمولد النبي ﷺ، وبمولد علي  والحسين وفاطمة والحاكم الذي يحكمهم، وهؤلاء ليسوا قدوة؛ فلا يقتدى بهم، ثم أحدث ذلك بعد ذلك ملك إربل، وهذا كله لا يجعل هذا الشيء سنة، بل هو حدث وبدعة ولو فعله هؤلاء، وليسوا هؤلاء بقدوة، إنما القدوة النبي ﷺ والخلفاء الراشدون صحابته  وأرضاهم، وهذا لم يقع منهم، والرسول ﷺ يجب أن تعظم سنته، وأن يتأسى به دائمًا دائمًا في جميع الأيام والليالي، لا في ربيع أول فقط، بل الواجب أن يعتنى بـسنته، وأن تدرس في كل زمان، وأن يتعلمها المسلمون، وأن يدرسوا أوامره ونواهيه، وما كان عليه؛ حتى يعملوا بذلك.  أما أن يحتفل بالمولد في ربيع أول في الثاني عشر من ربيع أول أو قبل ذلك، أو بعد ذلك بالطريقة المعروفة: جمع الناس وإقامة الولائم وقراءة المولد، هذا بدعة لا أصل له، والذي يجب تركه. أما تدريس سنته ومولده الدرس المعروف في المساجد، وفي المدارس، هذا طيب سنة ومطلوب حتى يعرف الناس مولده، وما جاء فيه، وسنته وسيرته -عليه الصلاة والسلام-، هذا هو الذي قرره المحققون من أهل العلم، ونبه عليه أبو العباس ابن تيمية -رحمه الله- في كتاب اقتضاء الصراط المستقيم، ونبه عليه أيضًا الإمام الشاطبي -رحمه الله- في كتاب الاعتصام، ونبه عليه آخرون. ثم هذا المولد، وهذا الاحتفال يقع فيه بعض الأحيان -من بعض الناس- أمور شركية، وأمور منكرة، علاوة على أنه بدعة يقع فيه المنكرات، وغلو في بعض الأحيان، وربما وقع فيه شركيات، ودعاءً للرسول ﷺ واستغاثة به، كما في البردة التي ينشدها كثير من الناس في المولد، وهي قصيدة فيها أنواع من الشرك للبوصيري ، فهذا كله من آفات هذا المولد، ومن آفات هذه البدعة، فينبغي للمسلمين تركها، والواجب عليهم عدم هذا الاحتفال، وهكذا بقية الموالد: مثل مولد علي  أو الحسين أو فاطمة أو غيرهم، أو مولد البدوي أو الشيخ عبدالقادر الجيلاني أو غيرهم، كل هذه الموالد لا يجوز إحداثها، ولا الاحتفال بها، وهكذا غيرها من الموالد: كالذي يحتفل بمولد أمه أو أبيه؛ تأسيًا بـالنصارى وغيرهم، كل هذا بدعة لا وجه له ولا يجوز، وفيه تشبه أيضًا بـالنصارى وغيرهم، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13471/حكم-الاحتفال-بمولد-النبي-ﷺ-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65008.mp3","categories":["البدع والمحدثات"]},{"id":14975,"question":"سؤال فلاح السويد من قرية الكوز التالي طويل ومتشعب أيضًا، لكن لا بد من قراءته، يقول فيه: أسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟ وعن مديح المشايخ هل يجوز أم لا؟ وعن المدد أو استمداد من غير الله مثل: مدد يا شيخ الفلاني مثلًا، هل هو من قبره يمدني أم لا؟أفيدونا، إننا غشماء عن هذه، ولا ندري إننا نسب عباد الله الصالحين، يقول أحد الناس: إن من عباد الله الصالحين يغني قسم من هذه الدنيا بكلمة واحدة، هل هذا يجوز القول أم لا حرام؟نرجو أن تجعلونا لله نهتدي إلى الخير بمشيئة الله.الجواب: أعد السؤال. يقول في سؤاله، نأخذه نقطة نقطة، يقول في سؤاله: نسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟","title":"حكم زيارة قبور الصالحين وتقبيل النصائب وطلب المدد","answer":"الجواب: زيارة القبور للصالحين للمسلمين أيضًا عمومًا سنة، قربة، الرسول ﷺ أمر بزيارة القبور، وحث عليها، وقال: إنها تذكر الآخرة، وتزهد في الدنيا، وتذكر الموت قال -عليه الصلاة والسلام-: زوروا القبور، فإنها تذكركم الآخرة وكان يعلم أصحابه -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية وفي حديث عائشة يقول: يرحم الله المستقدمين منا والمستأخرين. فعلينا معشر المسلمين أن نعلم هذا الحكم، ويشرع لنا أن نفعل ذلك؛ أن نزور القبور للذكرى والرغبة في الآخرة والزهد في الدنيا، والإحسان للموتى بالدعاء لهم، الإنسان يزورهم ليدعو لهم بالمغفرة والرحمة والعافية؛ وليتذكر الآخرة، وأنه صائر إلى ما صاروا إليه من هذا الموت حتى يستعد للآخرة. أما تقبيل القبور فلا، لا يقبل النصائب ولا التراب، ولا الجدران إن كان عليها جدران ولا القضبان إن كان هناك قضبان، كل هذا منكر لا يجوز، هذا من الغلو، ولا يجوز البناء على القبور، بل يجب أن تكون مكشوفة ليس عليها بناء، واتخاذ القباب عليها من البدع، وهكذا بناء المساجد عليها من البدع التي أنكرها الرسول ﷺ ونهى عنها، قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال جابر : \"نهى النبي ﷺ عن تجصيص القبور، والقعود عليها، والبناء عليها، والكتابة عليها\". فليس لأحد أن يبني على القبور لا قبابًا ولا مساجد ولا غير ذلك، وليس له أن يقبلها، ولا أن يتبرك بترابها، ولا أن يطلب الشيخ المدد كما يأتي، لا يجوز يقول: يا رسول الله، مدد مدد، ولا يا فلان كالشيخ عبدالقادر، أو يا شيخ البدوي السيد البدوي، أو يا الحسن أو يا سيدي الحسن أو الحسين، أو يا فلان أو يا أبا حنيفة، أو يا أبا فلان، كل هذا لا يجوز، المدد لا يطلب من الميت يطلب من الله -جل وعلا-: يا رب أغثني، يا رب ارحمني، يا رب اشف مريضي، يا رب ارزقني، أما طلب المدد من الموتى فهو من الشرك بالله  من الشرك الأكبر من عمل الجاهلية. فلا يقبل الحجارة، ولا النصائب ولا التراب، ولا يأخذ التراب للبركة، ولا يطلب مدد من المخلوق من الميت، أما الحي الحاضر تقول: يا أخي! ساعدني بكذا، أعني على كذا، وهو حي حاضر قادر لا بأس، الحي الحاضر القادر لا بأس، لكن الميت لا، لا تقل: المدد المدد، ولا تقل: اشف مريضي وانصرني على عدوي انصرنا على المشركين لا يقل هذا للميت، الميت انقطع عمله، وليس له التصرف في الكون، بل التصرف لله وحده  هو المالك لكل شيء، وهو القاهر فوق عباده، وهو النافع الضار، المعطي المانع، المدبر للكون ، وأما الميت فهو مرتهن بعمله ليس له تصرف، قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية مثل الأوقاف التي يوقفها في حياته أو علم ينتفع به كتب ألفها أو طلبة علمهم له أجر ذلك  أو ولد صالح يدعو له. أما كونه يتصرف في الكون، أو يمد هذا، أو ينصر هذا، هذا منكر لا حقيقة له ولا صحة له، بل الاستغاثة بالأموات والنذر لهم، والتقرب إليهم، بالذبائح، وطلبهم المدد والغوث كل هذا من فعل الجاهلية من عمل أهل الشرك، وهو شرك أكبر يجب الحذر منه، ويجب عليك -أيها السائل- أن تبلغ من يفعل هذا أن هذا منكر، وأنه شرك يجب ترك ذلك والتوبة إلى الله من ذلك؛ لأن هذا من عمل الجاهلية، نعم.","link":"https://binbaz.org.sa/fatwas/13482/حكم-زيارة-قبور-الصالحين-وتقبيل-النصاىب-وطلب-المدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66102.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":14978,"question":"السؤال الثاني عند الأخت (س. م. ع) تقول: عندما أقرأ القرآن أقبله أولًا، ثم أقرأ، سمعت بأن هذا بدعة فتركت، ثم رأيت في منامي بأن أبي يأمرني أن أقبل القرآن، ثم أقرأ. أفيدوني عن الطريقة الصحيحة أفادكم الله. وعندما أحمل القرآن ينحني الجالسون للقرآن، فهل في هذا شيء أم لا؟","title":"حكم تقبيل المصحف والانحناء له","answer":"الجواب: التقبيل للقرآن ليس له أصل معتمد، وليس بمشروع، يروى أن عكرمة بن أبي جهل أحد الصحابة \"كان يقبله ويقول: هذا كتاب ربي\" لكن لا أعلم له سندًا صحيحًا ثابتًا عنه  وأرضاه، وبكل حال فتقبيله لا حرج فيه، لكن ليس بمشروع، ولو قبله إنسان لا حرج عليه، لكن ليس هذا بمشروع، ولم ينقل عن أصحاب النبي ﷺ بأسانيد ثابتة، فالأولى ترك ذلك.    وإنما التعظيم يكون بالعمل، تعظيم القرآن يكون بالعمل به، وتدبره، والإكثار من قراءته، والخضوع عند ذلك والخشوع، هذا هو المشروع، الإكثار من تلاوة القرآن بالتدبر والتعقل والعمل والاستفادة والخشوع، هذا هو المشروع كما قال -جل وعلا-: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، فهو  شرع لنا أن نتدبره وأن نكثر من تلاوته وأن نعمل به، هذا هو الواجب علينا وهذا هو المطلوب منا. وأما الانحناء عند القرآن فأيضًا هذا لا أصل له، وإن كان تعظيمًا لله ؛ لأن القرآن كلام الله، لكن هذا لا أصل له، ولم يفعله خير هذه الأمة وأفضلها وهم الصحابة  وأرضاهم، والخير كله في اتباع سلفنا الصالح من أصحاب النبي ﷺ ومن تبعهم بإحسان، فلا ينحنى له، ولا يقبل هذا هو الأصل، لكن لو قبله إنسان فلا حرج عليه إلا أنه غير مشروع، أما الانحناء فهو مكروه لا ينبغي ولا يفعل ولا أصل له، نعم. وهذا قد يفضي إلى الانحناء للملوك والكبراء، وهذا منكر لا يجوز؛ لأنه نوع من الركوع، والركوع لا يجوز إلا لله وحده ، عبادة، فلا ينحني أحد لأحد، نعم.","link":"https://binbaz.org.sa/fatwas/13483/حكم-تقبيل-المصحف-والانحناء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65103.mp3","categories":["البدع والمحدثات","القرآن وعلومه"]},{"id":14983,"question":"فضيلة الشيخ عبدالعزيز، كنا في لقاء ماض قد استعرضنا رسالة وردتنا من المستمع فلاح السويد، قرية الكوز، محافظة الحسكة منطقة المالكية، وبقي له بعض الاستفسارات والأسئلة التي يمكن أن تغطي حلقة كاملة.يقول: يا شيخ عبدالعزيز، في الاستفسار الأول: نسألكم عن مولد النبي الأعظم ﷺ هل هو بدعة؟ وإني قد سمعت في بعض البلدان، ومن بعض العلماء يقولون: إنها بدعة حسنة، والله أعلم. وفقكم الله.","title":"هل الاحتفال بالمولد النبوي بدعة حسنة؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخليله وأمينه على وحيه نبينا وإمامنا محمد بن عبدالله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: الاحتفال بالموالد إنما حدث في القرون المتأخرة بعد القرون المفضلة بعد القرن الأول والثاني والثالث، وهو من البدع التي أحدثها بعض الناس استحسانًا وظنًا منه أنها طيبة، والصحيح والحق الذي عليه المحققون من أهل العلم أنها بدعة، الاحتفالات بالموالد كلها بدعة، ومن جملة ذلك الاحتفال بالمولد النبوي، ولماذا؟ لأن الرسول ﷺ لم يفعله، ولا أصحابه، ولا خلفاؤه الراشدون، ولا القرون المفضلة، كلها لم تفعل هذا الشيء، والخير في اتباعهم لا فيما أحدثه الناس بعدهم، وقد ثبت عنه -عليه الصلاة والسلام- أنه قال: إياكم ومحدثات الأمور وقال -عليه الصلاة والسلام-: وشر الأمور محدثاتها، وكل بدعة ضلالة وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد، من عمل عملًا ليس عليه أمرنا فهو رد يعني: مردود. فالنبي ﷺ وضح الأمر وبين أن الحوادث في الدين منكرة، وأنه ليس لأحد أن يحدث في الدين ما لم يأذن به الله، وقد ذم الله من فعل هذا بقوله سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ[الشورى:21] والاحتفال أمر محدث لم يأذن به الله، ولا رسوله -عليه الصلاة والسلام-، والصحابة أفضل الناس بعد الأنبياء، وأحب الناس للنبي ﷺ وأسرع الناس إلى كل خير، ولم يفعلوا هذا، لا أبو بكر ولا عمر ولا عثمان، ولا علي ولا بقية العشرة ولا بقية الصحابة، وهكذا التابعون، وأتباع التابعين ما فعلوا هذا، وإنما حدث من بعض الشيعة الفاطميين في مصر في المائة الرابعة كما ذكر هذا بعض المؤرخين، ثم حدث في المائة السادسة في آخرها أو في أول السابعة من ملك إربل ظن أن هذا طيب ففعل ذلك، والحق أنه بدعة؛ لأنها عبادة لم يشرعها الله ، والرسول ﷺ قد بلغ البلاغ المبين، ولم يكتم شيئًا مما شرعه الله، بل بلغ كل ما شرعه الله وأمر به، وقال الله سبحانه: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ[المائدة:3]. فالله قد أكمل الدين وأتمه، وليس في ذلك الدين الذي أكمله الله الاحتفال بالموالد، فعلم بهذا أنها بدعة منكرة، لا حسنة، وليس في الدين بدعة حسنة، بل كل البدع ضلالة كلها منكرة، والنبي  قال: كل بدعة ضلالة فلا يجوز لأحد من المسلمين أن يقول: إن في البدع شيئًا حسنًا، والرسول ﷺ يقول: كل بدعة ضلالة لأن هذه مناقضة ومحادة للرسول ﷺ، وقد ثبت عنه أنه قال: كل بدعة ضلالة فلا يجوز لنا أن نقول خلاف قوله -عليه الصلاة والسلام-. وما يظنه بعض الناس أنه بدعة وهو مما جاء به الشرع فليس بدعة مثل كتابة المصاحف، مثل التراويح ليست بدع كل هذه مشروعة، فتسميتها بدعة لا أصل لذلك، وأما ما يروى عن عمر أنه قال في التراويح: «نعمت البدعة» فالمراد بهذا من جهة اللغة لا ليس من جهة الدين، ثم قول عمر لا يناقض ما قاله الرسول ﷺ ولا يخالفه قول الرسول مقدم -عليه الصلاة والسلام- لأنه قال: كل بدعة ضلالة قال: وإياكم ومحدثات الأمور وقال ﷺ في خطبة الجمعة: أما بعد فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة هذا حكمه -عليه الصلاة والسلام-، رواه مسلم في الصحيح. فلا يجوز لمسلم أن يخالف ما شرعه الله، ولا أن يعاند ما جاء به نبي الله -عليه الصلاة والسلام-، بل يجب عليه الخضوع لشرع الله، والكف عما نهى الله عنه من البدع والمعاصي، رزق الله الجميع الهداية، نعم.","link":"https://binbaz.org.sa/fatwas/13480/هل-الاحتفال-بالمولد-النبوي-بدعة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66101.mp3","categories":["البدع والمحدثات"]},{"id":15038,"question":"السائل (ع. م. أ) سوداني، ومقيم بالرياض، يقول في سؤال له: عندنا عادة، وهي: عند وفاة شخص يحضر الناس للمأتم، وعند حضور أي شخص يرفع يديه، ويقول: الفاتحة للمرحوم فلان، ويرفع بقية الجالسين أيديهم أيضًا ويقرؤون.الشيخ: أعد! أعد.المقدم: يقول هذا السائل: عندنا عادة، وهي: عند وفاة شخص يحضر الناس للمأتم، وعند حضور أي شخص يرفع يديه ويقول: الفاتحة للمرحوم فلان، ويرفع بقية الجالسين أيديهم أيضًا ويقرؤون عند رفعها سورة الفاتحة والإخلاص، فما حكم الشرع في نظركم سماحة الشيخ؟","title":"حكم قراءة الفاتحة للميت وحكم المآتم","answer":"الجواب: هذه القراءة، وهذا الرفع بدعة، لا أصل لها، ولا يجوز فعل ذلك؛ لعدم الدليل، الرسول  يقول: من عمل عملًا ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ويقول: كل محدثة بدعة، وكل بدعة ضلالة ولم يكن يفعل هذا هو، ولا أصحابه -رضي الله عنهم-.\nأما المأتم ففيه تفصيل: إن كان مجيئهم للتعزية فقط فلا بأس، أما كونه للطعام يصنعون لهم طعام، ويجتمعون عنده لا؛ هذا لا يجوز، يقول جرير بن عبدالله البجلي: «كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة» أما إذا زاروهم للتعزية فقط، سلموا عليهم وعزوهم، ولو شربوا قهوة أو شاهي ما يخالف، أما يحط مأتم أهل الميت يصنعون طعام للناس، هذا لا يجوز، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13534/حكم-قراءة-الفاتحة-للميت-وحكم-الماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56308.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15123,"question":"الأخت المستمعة فاطمة محمد الناغي، من منطقة مستورة، في طريق المدينة المنورة، بعثت برسالة ضمنتها جمعًا من الأسئلة، في أحدها تقول: هل صحيح أن الحناء لا يجوز في شهر صفر؟","title":"حكم الحناء للمرأة في شهر صفر","answer":"الجواب: هذا باطل، لا أصل له، الحناء يجوز في صفر وفي غير صفر، في كل الشهور، للمرأة تتحنى في صفر، وفي رمضان، وفي شعبان، وفي رجب، وفي كل شهر، وفي كل يوم، سواء طاهرة أو حائض، حتى ولو كانت حائضًا، أو نفساء، لها أن تتحنى، ولو في حال النفاس أو حال الحيض لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13623/حكم-الحناء-للمراة-في-شهر-صفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49507.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15124,"question":"هل صحيح إذا تحنت المرأة أربعين ربوعًا تدخل الجنة؟","title":"هل المرأة إذا تحنت أربعين أربعاءً تدخل الجنة؟","answer":"الجواب: لا، هذا باطل، لا أصل له، الحناء ما له تعلق بالجنة ولا بالنار، الحناء من الأمور المباحة، من زينة المرأة، من الزينة، فإذا حنت يديها للجمال والزينة فهذا طيب، حتى لا تكون مثل الرجل، وإلا ليس بواجب، إنما هو مستحب لها جمال لها، ولا تعلق له بالجنة ولا بالنار، ولم يرد فيه حديث في هذا المعنى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13624/هل-المراة-اذا-تحنت-اربعين-اربعاء-تدخل-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49508.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15125,"question":"هل صحيح أن الكحل والحناء لا يجوزان ليلة الإثنين؟","title":"حكم الكحل والحناء ليلة الإثنين","answer":"الجواب: كل هذا باطل، كل هذه من خرافات العامة، تكتحل ليلة الإثنين، وإلا غير ليلة الإثنين، وتتحنى ليلة الإثنين، وإلا غيره، كله واحد، في جميع الليالي الحناء والكحل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13625/حكم-الكحل-والحناء-ليلة-الاثنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49509.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15128,"question":"ما حكم قراءة الفاتحة على قبر الرسول ﷺ؟إذ أن كثيرًا من الناس عندما يذهب إلى الحج أو العمرة يقول لك بعض الناس: اقرأ لي الفاتحة على قبر الرسول ﷺ.","title":"حكم قراءة الفاتحة على قبر الرسول ﷺ","answer":"الجواب: هذا لا أصل له، هذا بدعة، والقرآن لا يقرأ على القبور، يقرأ في المساجد، وفي البيوت، وفي الطريق ما يخالف، أما على القبور لا، ما يقرأ عند القبور، النبي ﷺ قال: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة دل على أن القبور ما يقرأ عندها، فقراءته في المساجد في البيوت، أما القبور تزار، يسلم عليهم، ويدعى لهم بالمغفرة والرحمة، ولكن لا يجلس عندهم للقراءة، ولا يجلس عندهم للدعاء ولا للصلاة، لا يصلى عندها، ولا يقرأ عندها، ولا تتخذ محلًا للدعاء، ولكن يسلم عليهم، فالزائر يدعو لهم، ويستغفر لهم، ثم ينصرف هذه السنة، كان النبي يزورهم ﷺ يزور القبور في البقيع فيسلم عليهم، ثم ينصرف، وهكذا الصحابة كانوا يزورون القبور، فيسلمون على القبور، ويدعون لهم، ثم ينصرفون، هذه السنة. أما القراءة عند قبر النبي ﷺ أو عند قبر غيره، أو الصلاة عند القبر، أو الجلوس عنده، يتحرى الدعاء عنده؛ لأنه يظن أنه أقرب للإجابة، هذا ما له أصل، هذا من البدع التي أحدثها الناس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13628/حكم-قراءة-الفاتحة-على-قبر-الرسول-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49512.mp3","categories":["البدع والمحدثات"]},{"id":15142,"question":"يطلب من سماحتكم -جزاكم الله خيرًا- يقول: أن ترشدوني إلى بعض الكتب التي تنهى عن البدع والحلف بالأولياء، وهل هناك بدع حسنة؟","title":"كتب تنهى عن البدع ينصح بقراءتها","answer":"الجواب: نعم، نرشد إلى كتاب فتح المجيد، وكتاب التوحيد، كتاب التوحيد للشيخ: محمد عبد الوهاب، وفتح المجيد لحفيده الشيخ: عبدالرحمن بن حسن، والبدع والنهي عنها للشيخ ابن وضاح -رحمه الله-، والاعتصام للشاطبي -رحمه الله-، كل هذه فيها التحذير من البدع.  ويكفي قول النبي ﷺ: خير الكلام كلام الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة ما أحدث الناس في الدين من عبادة لم يشرعها الله اجتنبها واحذرها، ولكن تشتغل بالكتب التي ذكرنا وغيرها من الكتب المعروفة في بيان السنة، وبيان البدعة، وإذا أشكل عليك شيء تسأل أهل العلم من أهل السنة والجماعة. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13639/كتب-تنهى-عن-البدع-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56411.mp3","categories":["البدع والمحدثات","نصائح وتوجيهات"]},{"id":15199,"question":"أما المستمع (ع. خ) من المدينة المنورة، فيقول بعد أن طلب العمر المديد لفضيلة الشيخ عبدالعزيز، وأن يكون هذا العمر معمورًا بطاعة الله، وفائدة المسلمين عامة، يقول:قد عرفنا من كلام سماحة الشيخ عبدالعزيز بن باز أن البناء والقباب على القبور لا يجوز، فما حكم القبة الخضراء على قبر الرسول الكريم ﷺ في المدينة المنورة؟","title":"حكم القبة التي على قبر الرسول ﷺ","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا ريب أن الرسول -عليه الصلاة والسلام- نهى عن البناء على القبور، ولعن اليهود و النصارى على اتخاذ المساجد عليها، فقال -عليه الصلاة والسلام-: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام- فيما رواه عنه مسلم في الصحيح عن جابر \"أنه نهى عن تجصيص القبور، والقعود عليها، والبناء عليها\" وفي رواية للترمذي وغيره: والكتابة عليها. فالبناء على القبور، واتخاذ مساجد عليها من المحرمات التي حذر منها النبي -عليه الصلاة والسلام-، وتلقاها أهل العلم، تلقى أهل العلم ما قاله ﷺ في ذلك بالقبول، ونهى أهل العلم عن البناء على القبور، واتخاذ المساجد عليها تنفيذًا للسنة المطهرة، وعملًا بها، ومع ذلك فقد وجد في الكثير من الدول والبلدان البناء على القبور، واتخاذ المساجد عليها، واتخاذ القباب عليها أيضًا، وهذا كله مخالف لما جاءت به السنة عن الرسول -عليه الصلاة والسلام-، وهو من أعظم الوسائل لوقوع الشرك، والغلو في أصحاب القبور. فلا ينبغي لعاقل، ولا ينبغي لأي مسلم أن يغتر بهؤلاء، وأن يتأسى بهم فيما فعلوا؛ لأن أعمال الناس تعرض على الكتاب والسنة، فما وافق الكتاب والسنة، أو وافق أحدهما قبل، وإلا رد على من أحدثه، كما قال الله سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10] وقال : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ[النساء:59] الآية. أما ما يتعلق بالقبة الخضراء التي على قبر النبي ﷺ فهذا شيء أحدثه بعض الأمراء في المدينة في القرون المتأخرة في القرن التاسع، وما حوله، ولا شك أنه غلط منه، وجهل منه، ولم يكن هذا في عهد النبي ﷺ، ولا في عهد أصحابه، ولا في عهد القرون المفضلة، وإنما حدث في القرون المتأخرة التي كثر فيها الجهل، وقلَّ فيها العلم، وكثرت فيها البدع، فلا ينبغي أن يغتر بذلك، ولا أن يقتدى بذلك. ولعل من تولى المدينة من الملوك والأمراء المسلمين تركوا ذلك خشية الفتنة من بعض العامة، فتركوا ذلك وأعرضوا عن ذلك؛ حسمًا لمادة الفتن؛ لأن بعض الناس ليس عنده بصيرة، فقد يقول: غيروا وفعلوا بقبر النبي ﷺ، وهذا كذا، وهذا كذا، فيثير فتنًا لا حاجة إلى إثارتها، وقد تضر إثارتها. فالأظهر -والله أعلم- أنها تركت لهذا المعنى خشية من رواج فتنة يثيرها بعض الجهلة، ويرمي من أزال القبة بأنه يستهين بالنبي ﷺ، أو بأنه لا يرى حرمته -عليه الصلاة والسلام-، هكذا يدعي عباد القبور، وأصحاب الغلو إذا رأوا من يدعو إلى التوحيد، ويحذر من الشرك والبدع، رموه بأنواع المعايب، واتهموه بأنه يبغض النبي -عليه الصلاة والسلام-، أو بأنه يبغض الأولياء، أو لا يرى حرمته ﷺ، أو ما أشبه هذه الأقاويل الفاسدة الباطلة. وإلا فلا شك أن الذي عملها قد أخطأ، وأتى بدعة، وخالف ما قاله النبي ﷺ في التحذير من البناء على القبور، واتخاذ المساجد عليها، وأما البناء الأول فهو بيت عائشة كان دفن  في بيت عائشة، والصحابة  وأرضاهم خافوا من دفنه في البقيع من الفتنة، فجعلوه في بيت عائشة، ثم دفنوا معه صاحبيه الصديق وعمر -رضي الله عنهما-، ولم يكن في المسجد، بل كان في بيت عائشة، ثم لما وسع المسجد في عهد الوليد بن عبدالملك في آخر القرن الأول أدخل الحجرة في التوسعة، فظن بعض الناس الذين لا يعلمون أن الرسول ﷺ دفن في المسجد، وليس الأمر كذلك، بل هو -عليه الصلاة والسلام- دفن في بيت عائشة، في خارج المسجد، ولم يدفن في المسجد. فليس لأحد الحجة في ذلك، أن يدفن في المساجد، بل يجب أن تكون المساجد خالية من القبور، ويجب أن لا يبنى أي مسجد على قبر؛ لكون الرسول حذر من ذلك -عليه الصلاة والسلام- فقال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد أخرجه الشيخان البخاري ومسلم في الصحيحين، وروى مسلم في صحيحه -رحمه الله- عن جندب بن عبدالله البجلي عن النبي ﷺ أنه سمعه يقول قبل أن يموت بخمس، يقول: إن الله قد اتخذني خليلًا كما اتخذ إبراهيم خليلًا، ولو كنت متخذًا من أمتي خليلًا لاتخذت أبا بكر خليلًا، ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك فذم من اتخذ المساجد قبورًا، ونهى عن ذلك بصيغتين: إحداهما: قوله: فلا تتخذوا القبور مساجد والثانية قوله: فإني أنهاكم عن ذلك وهذه مبالغة في النهي والتحذير منه -عليه الصلاة والسلام- من وجوه ثلاثة: الوجه الأول: ذمًا لمن اتخذ المساجد قبورًا على قبور الأنبياء والصالحين ممن قبلنا. والثاني: أنه نهى عن ذلك بصيغة: لا تتخذوا. والثالث: أنه نهى عنه بصيغة: فإني أنهاكم عن ذلك وهذه مبالغة في التحذير، وسبق في حديث عائشة أنه نهى عنه باللعن قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد هذا يبين لنا، ويبين لكل مسلم، ولكل ذي فهم أن البناء على القبور، واتخاذ القباب عليها، والمساجد أنه مخالف لشريعة الله التي جاء بها نبيه -عليه الصلاة والسلام-، وأنه منكر وبدعة في الدين، وأنه من وسائل الشرك. ولهذا لما رأى العامة والجهلة هذه القبور المعظمة المساجد والقباب وغير ذلك، والفرش ظنوا أنها تنفعهم، وأنها تجيب دعاءهم، وأنها ترد عليهم غائبهم، وتشفي مريضهم، فدعوها واستغاثوا بها، ونذروا لها، ووقعوا في الشرك بسبب ذلك. فالواجب على أهل العلم والإيمان أينما كانوا أن يحذروا الناس من هذه الشرور، وأن يبينوا لهم أن البناء على القبور من البدع المنكرة، وهكذا اتخاذ القباب والمساجد عليها من البدع المنكرة، وأنها من وسائل الشرك حتى يحذر العامة ذلك، وحتى يعلم الخاص والعام أن هذه الأشياء حدثت بعد الرسول ﷺ وبعد أصحابه  وبعد القرون المفضلة، حتى يحذروها، وحتى يبتعدوا عنها. والزيارة الشرعية للقبور هي أن يزوروها للسلام عليهم، والدعاء لهم، والترحم عليهم، لا لدعائهم وسؤالهم قضاء الحاجات، وتفريج الكروب، فإن هذا شرك بالله، ولا يجوز إلا مع الله . ولكن الجهلة والمشركين بدلوا الزيارة الشرعية بالزيارة المنكرة الشركية جهلًا وضلالًا، ومن أسباب هذا التبديل ومن أسباب هذا الشرك والبدع وجود هذه البنايات والقباب والمساجد على القبور، ومن أسباب ذلك سكوت الكثير من العلماء عن ذلك، إما للجهل بالحكم الشرعي في ذلك من بعضهم، وإما ليأسه من قبول العامة، وعدم الفائدة من كلامه معهم لما رأى من إقبالهم عليها، وإنكارهم على من أنكر عليهم، وإما لأسباب أخرى. فالواجب على أهل العلم أينما كانوا أن يوضحوا للناس ما حرم الله عليهم، وأن يبينوا لهم ما أوجب الله عليهم، وأن يحذروهم من الشرك وأسبابه ووسائله، فإن العامة في ذمتهم، والله أوجب عليهم البلاغ والبيان، وحرم عليهم الكتمان، نعم.","link":"https://binbaz.org.sa/fatwas/13693/حكم-القبة-التي-على-قبر-الرسول-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_667/nour_66701.mp3","categories":["البدع والمحدثات"]},{"id":15208,"question":"هذا السائل من تشاد، يقول في هذا  سماحة الشيخ، كنت أقوم بزيارة أهل الخير والعلماء والمشايخ، ولكنني أحيانًا أقوم بزيارة بيوت أهل البدع، وقصدي بذلك أن أدعوهم إلى طريق السعادة وإلى طريق السنة، هل يكون هذا فيه إثم؟ مأجورين.","title":"حكم زيارة أهل البدع من أجل دعوتهم","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فزيارة أهل العلم والإيمان من أهل السنة والجماعة، وزيارة الإخوان في الله قربة وطاعة، أما زيارة أهل البدع فلا تجوز زيارتهم على سبيل المؤانسة والمحبة، ونحو ذلك. أما إذا زارهم طالب العلم للموعظة والتذكير والتحذير من البدعة؛ هذا مشكور ومأجور؛ لأن هذا من باب الدعوة إلى الله، من باب الأمر بالمعروف والنهي عن المنكر، فإذا زرت هؤلاء الذين عندهم شيء من البدع زرتهم للدعوة إلى الله والنصيحة والتوجيه، فأنت مأجور، وينبغي أن لا تدع ذلك إذا كان فيه فائدة، أما إذا أصروا ولم يستجيبوا فدعهم.","link":"https://binbaz.org.sa/fatwas/13707/حكم-زيارة-اهل-البدع-من-اجل-دعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56501.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":15241,"question":"سؤاله الآخر؛ سؤال المستمع (م. ي. هـ. أ. ر. ب) يقول فيه: إني عندما أصلي أقول: نويت أن أصلي فرض صلاة مثل الفجر، الله أكبر، ثم أدعو بالدعاء الذي يقال بعد تكبيرة الإحرام، وهو دعاء الاستفتاح، فقد سمعت من برنامجكم نور على الدرب يقول: لا يجوز قول: نويت أن أصلي فرض كذا أو كذا، فما أدري هل ما سمعته صحيحًا، أم أنه سمع لي؟نرجو أن تجيبونا مرة أخرى، وفقكم الله.","title":"حكم التلفظ بالنية قبل الشروع في الصلاة","answer":"الجواب: نعم -يا أخي- النية محلها القلب، ولا يجوز أن يقال: نويت أن أصلي كذا إمامًا أو مأمومًا، فريضة كذا، أربع ركعات الظهر، أو ثلاث ركعات كالمغرب أو ركعتين كالفجر لا، ينوي بقلبه ويكفي، ولا حاجة إلى أن يقول: نويت أن أصلي كذا وكذا، ولا حاجة أن يقول في الطواف: نويت أن أطوف كذا وكذا، ولا في السعي، ولا في الوضوء نويت أن أتوضأ كذا وكذا، كل هذا لا أصل له، النية محلها القلب، قال النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى،. ولم يكن النبي ﷺ ولا أصحابه ولا أئمة الإسلام المتقدمون يتلفظون بالنية، بل كان أحدهم إذا وقف يقول: الله أكبر، عند دخوله في الصلاة، ولا يقول: نويت أن أصلي كذا وكذا، فالتلفظ بهذا بدعة؛ لقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وهذا ليس عليه أمر النبي ﷺ فيكون مردودًا؛ ولقوله -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود؛ ولقوله -عليه الصلاة والسلام-: وشر الأمور محدثاتها، وكل بدعة ضلالة. فعليك -يا أخي- أن تنوي بقلبك إذا قمت إلى الصلاة كفت النية في قلبك أنك قمت للصلاة، ظهر أو عصر أو مغرب أو عشاء أو فجر أو جمعة أو صلاة عيد أو نوافل صلاة الضحى أو الرواتب، كلها يكفي فيها ما وقع في قلبك، وما تعلمه من قيامك لهذا أو مجيئك لهذا يكفي، وليس لك أن تتلفظ بالنية في الصلاة، وهكذا في الصوم، وهكذا في الوضوء، وهكذا في الغسل، وهكذا في الطواف، والسعي النية في القلب ولا حاجة إلى التلفظ، بل ذلك من المحدثات، نعم.\nالمقدم: أيضًا يقول: بالنسبة للسنة إذا قلت: نويت أن أصلي سنة رسول الله، لله تعالى، هل هو خطأ أم مثل ما قلتم؟\nالشيخ: مثلما سمعت هذا بدعة، تنوي بقلبك أنك تصلي الصلاة التي شرعها الله ورسوله، تنوي بقلبك أنك تصلي الصلاة كما شرع الله، وكما جاء عن رسوله -عليه الصلاة والسلام-، وليس لك أن تقول: نويت أن أصلي كذا وكذا؛ لأن هذا بدعة، لم ينقل عن النبي ﷺ ولا عن الصحابة والخير في اتباعهم والسير على منهاجهم. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13743/حكم-التلفظ-بالنية-قبل-الشروع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_669/nour_66903.mp3","categories":["البدع والمحدثات"]},{"id":15287,"question":"هذه ثلاثة أسئلة، بعث بها المستمع (س. م. س. م) من جمهورية اليمن الديمقراطية، يقول في سؤاله الأول: عندنا عادة نفعلها قبل صلاة الصبح، وقبل صلاة العشاء، وهي ذكر الله وتسبيحه، والصلاة على رسوله ﷺ بصوت جماعي، ويسمون هذا بالراتب، فهل يجوز هذا بهذا الشكل أم لا؟","title":"ما حكم ذكر الله بصوت جماعي قبل الفجر والعشاء؟","answer":"الجواب: هذا بدعة، كون يجتمع جماعة بصوت جماعي، يذكرون الله، أو يقرؤون بعد الفجر وبعد المغرب هكذا بدعة.  أما كون الإنسان يجلس بعد المغرب أو بعد العصر يذكر الله مع نفسه هذا طيب، قربة وطاعة لله ، وهكذا بعد الفجر هذا طيب، كان النبي يجلس بعد الفجر حتى تطلع الشمس -عليه الصلاة والسلام-، يذكر الله، ويثني عليه، هذا كله مشروع، تسبيح الله، والثناء عليه بكرة وعشيًا أمر شرعه الله، لكن كونه يؤدى بصوت جماعي، من جماعة بعد العصر أو بعد المغرب أو بعد الفجر هذا بدعة، والرسول ﷺ قال: من عمل عملًا ليس عليه أمرنا فهو رد وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد وكان يخطب يوم الجمعة ويقول: شر الأمور محدثاتها، وكل بدعة ضلالة. فالواجب على المسلم أن يتقيد بشرع الله، وأن يتأدب بآداب الله، فإذا أراد الجلوس بعد الصبح، أو بعد المغرب، أو بعد العصر لذكر الله، وقراءة القرآن هذا طيب، وهكذا الآخر والآخر كل يذكر الله بينه وبين ربه ويسبحه ويحمده، ويثني عليه ويستغفره، ويقرأ القرآن، وهذا فيه فضل عظيم، وأجر كبير، لكن كونهم ينطقون بصوت واحد: لا إله إلا الله، أو سبحان الله، أو بالآيات، هذا لا أصل له، بل هو من البدع التي أحدثها الناس.  فالواجب ترك ذلك، والتوبة إلى الله مما سلف ، نعم.","link":"https://binbaz.org.sa/fatwas/13790/ما-حكم-ذكر-الله-بصوت-جماعي-قبل-الفجر-والعشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68104.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":15324,"question":"هذه رسالة بعث بها المستمع عبدالرزاق أحمد، من جمهورية السودان الديمقراطية، الإقليم الشمالي، يقول: ما حكم الدعاء بعد كل دبر صلاة بالنسبة للجماعة، حيث يدعو الإمام، ويقول المأمومون جميعًا خلفه: آمين؟","title":"ما حكم دعاء الإمام بعد الصلاة وتأمين المأمومين؟","answer":"الجواب: هذا شيء لا أصل له، الدعاء بعد كل صلاة يدعو الإمام، ويؤمن عليه المأمومون، هذا شيء لا أصل له، بل هو بدعة، فلم يكن النبي ﷺ ولا أصحابه يفعلونه، بل كان إذا سلم من صلاته استغفر ثلاثًا قال: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام ثم ينصرف إلى الناس يعطيهم وجهه الكريم -عليه الصلاة والسلام-، ثم يقول: لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله، مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد هذا ثابت عن النبي ﷺ بعضه ثابت من حديث ثوبان عند مسلم، وبعضه من حديث ابن الزبير عند مسلم، وبعضه في الصحيحين من حديث المغيرة هذه الأذكار التي يقولها إذا سلم -عليه الصلاة والسلام-، ولم يحفظ عنه أنه كان يرفع يديه إذا سلم، ويدعو ويؤمن المأمومون كل هذا محدث لا أساس له، فلا يجوز فعله، بل هو بدعة، نعم. المقدم: نعم.","link":"https://binbaz.org.sa/fatwas/13828/ما-حكم-دعاء-الامام-بعد-الصلاة-وتامين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67704.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":15351,"question":"في آخر أسئلة هذه السائلة تقول سماحة الشيخ: سمعت من إحدى صديقاتي بأنه عند المرور على القبور أنه يستحب للمسلم أن يقرأ سورة الإخلاص إحدى عشر مرة، وآية الكرسي في هذا اليوم، فيرفع عنهم العذاب، وعلى قدر عددهم يغفر الله لهم، هل هذا بدعة؟","title":"حكم قراءة الإخلاص وآية الكرسي عند المرور على القبور","answer":"الجواب: كل هذا باطل، لا أصل له، هذا باطل ليس له أصل، بدعة، بدعة ظاهرة، ليس له أصل، ولكن إذا مر عليهم يسلم عليهم، يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا الرجل، أما المرأة لا تزور القبور، لكن الرجل إذا مر عليها يسلم، أما قراءة قُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] أو آية الكرسي كل هذا لا أصل له، نعم.","link":"https://binbaz.org.sa/fatwas/13854/حكم-قراءة-الاخلاص-واية-الكرسي-عند-المرور-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56624.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":15431,"question":"يقول السائل: يوجد بالقرب من بيتنا مسجد، وأنا مواظب -والحمد لله- على الصلاة وصلاة الجماعة، ولكن هذا المسجد يوجد فيه الكثير من البدع، والأمور المحدثة، فما حكم صلاتي فيه؟ هل أتجنبه؟ أم أصلي في بيتي؟ وكذلك صلاة الجمعة هل تجوز معهم؟ أم أبحث على مسجد آخر بعيد جدًا عن منزلي؟ وجهوني بذلك.","title":"حكم الصلاة في مسجد فيه بدع","answer":"الجواب: نعم، عليك أن تصلي معهم، وتنكر حسب طاقتك، تنكر البدعة حسب طاقتك، إذا كانت البدعة غير مكفرة، فعليك أن تنكر حسب طاقتك، وتنصح الناس، وتصلي معهم الجمعة والجماعة، والحمد لله.  فإن أجابوا فهذا هو الواجب، وإن لم يجيبوا فلك أن تنتقل إلى مسجد آخر، ليس فيه بدعة، لكن صلاتك مع هؤلاء فيها مصالح من الإنكار عليهم، ودعوتهم إلى الخير، وإنكار البدعة عليهم على الإمام والمأمومين الذي يفعل البدعة بالأسلوب الحسن، بالأسلوب الذي يرجى فيه القبول، فإن لم يستجيبوا وأمكنك الانتقال إلى مسجد آخر، فهذا حسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13948/حكم-الصلاة-في-مسجد-فيه-بدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50010.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":15442,"question":"هذا السائل يقول في هذا  يوجد مقابر بجوارها مقام يذبح عند هذا المقام ذبائح نذرت لله، ولكن لا تذبح إلا في هذا المكان، وإذا نهاهم أحد قالوا: إنما نذبح لله، ولكن بجوار الأولياء. علمًا بأنهم يأتون من أماكن متفرقة، وأماكن بعيدة للذبح في هذا المكان، ثم يجلسون لتناول الطعام في نفس المكان، فهل هذا حلال أم حرام؟أفيدونا بذلك.","title":"حكم الذبح عند الأضرحة والمقامات","answer":"الجواب: هذا بدعة، ووسيلة للشرك، مجيئهم للذبح عند القبور بدعة، ولو قالوا: إنها لله، أما إن كان لأصحاب القبور فهو شرك أكبر، والعياذ بالله، قال الله تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ( [الكوثر:1-2] وقال النبي ﷺ: لعن الله من ذبح لغير الله. فإن ذبحوا للأموات يتقربوا للأموات صار شركًا أكبر، كمن يذبح للأولياء يرجو شفاعتهم، أو شفاء المرضى، أو ما أشبه ذلك، أو يدعونهم، أو يستغيثون بهم، أو ينذرون لهم، أو يطوفون بالقبور، كل هذا شرك أكبر، أما إن كان الذبح لله، ولكن يرون أن هذا محل مناسب، وأنه محل مبارك، هذا غلط، هذا بدعة، لا يجوز؛ لأنه وسيلة للشرك، وبدعة في الدين، نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ عبدالعزيز كثيرًا ما تردنا مثل هذه الأسئلة، فهل من توجيه من كلمة للدعاة إلى الله  في نصح مثل هؤلاء؟ الشيخ: نعم، نوصي الدعاة إلى الله والعلماء أن يوجهوهم إلى الخير، وأن يعلموهم ويرشدوهم، حتى يكونوا على بينة على بصيرة، يقول الله -جل وعلا- في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول -جل وعلا-: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108] هكذا أتباع النبي ﷺ يدعون إلى الله على بصيرة، يعلمون الناس، يرشدون الناس لا يغفلون، ويقول ﷺ في حديث علي: لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم ويقول ﷺ: من دل على خير فله مثل أجر فاعله نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/13957/حكم-الذبح-عند-الاضرحة-والمقامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50013.mp3","categories":["البدع والمحدثات","نواقض الإسلام"]},{"id":15528,"question":"هذا السائل عبدالله من مصر، يسأل ويقول: سماحة الشيخ، كلمة زمزم، يرددون كلمة زمزم عند الوضوء، وقول حرمًا بعد الصلاة، هل في هذا بأس؟","title":"حكم قول (زمزم) عند الوضوء و(حرمًا) بعد الصلاة","answer":"الجواب: لا أعلم لهذا أصلًا، لا أصل لهذا، ولا ينبغي فعله، نعم.","link":"https://binbaz.org.sa/fatwas/14062/حكم-قول-زمزم-عند-الوضوء-وحرما-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56921.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":15529,"question":"قول: \"الفاتحة\" بعد الدعاء، هذا شائع بينهم.","title":"حكم قول بعد الدعاء: الفاتحة","answer":"الجواب: كذلك، لا أصل له، كل هذا لا أصل له، ولا ينبغي فعله. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14064/حكم-قول-بعد-الدعاء-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56922.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":15582,"question":"هذا سؤال من السائل عبده محمود حامد، من بور سودان، يقول: في حينا مسجد بناه جماعة من الصوفية، بعد أن أردنا نحن -أهل السنة- بناءه، ولكنهم أصروا على بنائه، وفعلوا، وهو الآن تحت إدارتهم وتصرفهم، ويقومون فيه بأشعار ومدائح، فهل يجوز لنا نحن السنيين أن نصلي فيه معهم، وخلف إمامهم المبتدع، أم ماذا نفعل؟","title":"هل يجوز الصلاة خلف المبتدع؟","answer":"الجواب: إذا كان إمامهم ليس بكافر، وإنما عنده بعض البدع التي لا تخرجه من الإسلام، فلا مانع من الصلاة معهم، ونصيحتهم، وتوجيههم، وإرشادهم بالدعوة إلى الله بعد الصلوات، وفي حلقات العلم في المسجد، حتى يستفيدوا وينتفعوا، ويدعوا ما عندهم من البدع -إن شاء الله-؛ لأن هذا من باب التعاون على البر والتقوى، ومن باب التناصح. أما إن كان إمامهم يتعاطى ما يوجب كفره، كالذي يستغيث بالرسول ﷺ، أو يدعوه من دون الله، أو يستغيث بالأموات، وينذر لهم، ويذبح لهم، هذا كفر وضلال، هذه أمور كفرية، لا يصلى خلفه؛ لأن هذه الأمور من أمور الكفر بالله والشرك بالله . وهكذا إذا كان إمامهم يعتقد اعتقادات كفرية، كأن يعتقد أن غير الله يتصرف في الكون من الأولياء، وأنهم يدبرون هذا العالم من الأولياء، كما يعتقده بعض الصوفية، أو يعتقد ما يعتقده أصحاب وحدة الوجود، من أن الخالق والمخلوق واحد، وأن الخالق هو المخلوق، والعبد هو المعبود، ونحو ذلك من المقالات الخبيثة الملحدة، فهذا كافر، ولا يصلى خلفه، أما إذا كان بدع دون الكفر، فإن هذا يصلى خلفه.\nمثل بدعة المولد، وليس فيها كفر، ومثل بعض البدع الأخرى التي يفعلها الصوفية وليست بكفر، بل دون الكفر، فلا تمنع من الصلاة خلفه.  وأما الأشعار التي يأتي بها، ينظر فيها فإذا كانت أشعارًا كفرية، مثل أشعار صاحب البردة في قوله:","link":"https://binbaz.org.sa/fatwas/14122/هل-يجوز-الصلاة-خلف-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69207.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":15640,"question":"وهذه أول رسالة في حلقتنا اليوم من المستمع (محمود م. ج) مصري يعمل بالمملكة العربية السعودية بعث بعدة أسئلة يقول في سؤاله الأول: نذرت لله تعالى أن أذبح عجلًا لتفضله علي بزيارة الحرمين الشريفين، وفي نيتي وكما هو متبع في بلدنا ولتقارب المستوى المعيشي فلا يوجد الفقير المعدم، ولا الغني المترف، فقصدي أن أذبحه وأولم وليمة، ثم أدعو كل المسلمين في بلدنا، ثم أدعو شيخًا وعالمًا جليلًا معروفًا عندنا يقوم بوعظ المسلمين، وإقامة حلقات الذكر، والاستغفار، والتسبيح، والتحميد لله، والصلاة على رسوله ﷺ، في ليلة محددة، ويتناولون طعام العشاء، ثم نقضي ليلتنا تلك في ذكر الله، والصلاة، والتسبيح، والتحميد، فهل في ذلك شيء يخالف شريعة الله أو لا أكون بذلك قد وفيت بنذري؟","title":"نوى أن يذبح عجلا ويجتمع مع الحاضرين على ذكر الله","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن النذر منهي عنه، قد نهى عنه النبي ﷺ فقال: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل لكن من نذر طاعة لله سبحانه كالصلاة والصوم والذبح لله سبحانه فإنه يوفي بها؛ لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في صحيحه. فعليك -أيها الأخ السائل- أن توفي بنذرك بذبح العجل وتوزيعه وتصلح الوليمة كما نويت، ولا بأس بذلك للفقراء وغيرهم من أقاربك وجيرانك على حسب ما نويت؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وإحضار العالم للتذكير والوعظ بمناسبة اجتماع المسلمين هذا شيء طيب.\nكذلك إذا سبحوا الله، وذكروا الله -جل وعلا-، وكل يذكر الله في نفسه، ويسبح الله في نفسه، كل هذا عمل صالح. أما الاجتماع على أذكار مخصوصة، وتسبيح مخصوص بصوت مخصوص جماعي، فهذا لا دليل عليه، وليس له أصل في الشريعة فيما نعلم، لكن إذا سبح كل واحد، واستغفر كل واحد نفسه، وذكروا الله في أماكنهم، وسبحوا الله في أماكنهم واستغفروه  وشكروه فهذا كله طيب، وإذا كان في اجتماعهم قراءة للأحاديث الصحيحة عن رسول الله ﷺ، أو قراءة للقرآن وهم يستمعون والعالم يفسر لهم معنى الآيات ومعنى الأحاديث فهذا كله طيب. أما الحلقات التي يفعلها الصوفية على أذكار مخصوصة، وأصوات مخصوصة، ونغمات مخصوصة، فهذه لا أصل لها، بل هي من البدع، ولكن اجتماع الناس على العلم وقراءة القرآن واستماعه، وسماع كلامًا لأهل العلم وتذكيرهم ووعظهم وتفسير الآيات للحاضرين كل هذا طيب، نسأل الله للجميع التوفيق والهداية، ويكون هذا في يوم معين أو في وقت معين من الليل لا بأس إلا أن يكون يقصد بذلك تعظيم ليلة مخصوصة، مثل ليلة المولد، فهذا لا يجوز؛ لأن الموالد بدعة، والاحتفال بها من البدع المحدثة في الدين على الصحيح من أقوال العلماء، وقد تنازع العلماء المتأخرون في ذلك فزعم بعضهم أنه سنة، وأن إقامة الأعياد لا بأس بها، ولكنه قول مرجوح وضعيف. والصواب: أن الاحتفال بالموالد بدعة ما أنزل الله بها من سلطان، داخل ذلك في قوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وفي قوله -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد والدليل على هذا مع الحديثين المذكورين أن الرسول ﷺ لم يفعل ذلك في حياته، ولا فعله أصحابه بعد وفاته، لا الصديق  ولا عمر  ولا عثمان ولا علي -رضي الله عنهم-، ولا بقية الصحابة، كذلك ما فعله التابعون ولا أتباع التابعين في مولد النبي ﷺ ولا في مولد غيره، فدل ذلك على أنه بدعة. والخير كله في اتباع السلف الصالح، في السير على منهاج نبينا ﷺ وصحابته، والنبي ﷺ يذكر -والحمد لله- في كل وقت، في الأذان والإقامة خمس مرات في اليوم والليلة، في التشهد الأول والتشهد الثاني، في سائر الأوقات يصلى عليه ويسلم -عليه الصلاة والسلام-، فليس في حاجة إلى هذه البدعة. وهكذا سيرته ﷺ يجب أن تدرس في المدارس والمعاهد والمساجد والكليات حتى تعرف سيرته -عليه الصلاة والسلام-، وحتى يتأسى بأقواله وأفعاله -عليه الصلاة والسلام-، فليس المسلمون في حاجة إلى بدعة المولد. فينبغي لأهل العلم أن ينتبهوا لهذا الأمر، وأن يوضحوا للعامة طريق أهل السنة والجماعة في هذا الباب وغيره، نسأل الله للجميع الهداية والتوفيق وصلاح النية والعمل.\nالمقدم: اللهم آمين، بارك الله فيكم.\nالمقدم: يقول: هل يجوز له أن يأكل هو وأولاده وأهل بيته وأقاربه من هذه الوليمة؟\nالشيخ: لا بأس بذلك ما دام نوى هذه النية أنه يذبحها ويجمع إليها الناس ويأكل هو وأهل بيته لا بأس الأعمال بالنيات. المقدم: يعني: ما لم يحدد؟\nالشيخ: أما إذا ما نوى شيئًا فإنه يعطاها للفقراء خاصة، وما دام نوى أنه يذبحها في البيت، ويجمع عليها العلماء، ويجمع عليها الفقراء وغير الفقراء من أهل بيته وجيرانه فالأعمال بالنيات.","link":"https://binbaz.org.sa/fatwas/14186/نوى-ان-يذبح-عجلا-ويجتمع-مع-الحاضرين-على-ذكر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69701.mp3","categories":["الأيمان والنذور","البدع والمحدثات"]},{"id":15646,"question":"من اليمن رسالة بعث بها المستمع إبراهيم عبده أحمد عياد، يسأل عن قراءة الفاتحة على الأموات في المقابر؟جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة على الأموات في المقابر","answer":"الجواب: هذا شيء لا أصل له، لا تشرع القراءة على القبور، لا الفاتحة ولا غيرها، القراءة على القبور بدعة، أو القراءة عندها كذلك، السنة زيارتها للسلام عليهم، والدعاء لهم؛ لقوله ﷺ: زوروا القبور، فإنها تذكركم الآخرة وكان يعلم أصحابه -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، يغفر الله لنا ولكم هكذا السنة يدعو لهم، يستغفر لهم، يسلم عليهم، أما أن يقرأ فهذا لا أصل له، لا يشرع القراءة للموتى ولا القراءة عند القبور، ولم يفعله المصطفى ﷺ ولا أصحابه ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14182/حكم-قراءة-الفاتحة-على-الاموات-في-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70510.mp3","categories":["البدع والمحدثات"]},{"id":15674,"question":"من رأس المعرة في الجمهورية العربية السورية رسالةٌ بعثها مستمعٌ، يقول السائل رفاعي: عندنا عادةً يسير مع الجنازة الناس أثناء تشييعها إلى المقبرة، ثم يُرددون كلمة: \"لا إله إلا الله، محمدٌ رسول الله ﷺ\" بصوتٍ عالٍ ومرتفعٍ، فهل ورد هذا عن الرسول ﷺ، أو أنه بدعةٌ مُحرمةٌ؟جزاكم الله خيرًا.","title":"حكم رفع الصوت بالذكر عند تشييع الجنازة","answer":"الجواب: هذا بدعةٌ، ما له أصلٌ، كان السلف إذا كانوا مع الجنائز يغضون أصواتهم، يتأملون حال الموت وما بعد الموت، يتذكر الإنسان هذه الأمور العظيمة، أما رفع الصوت بالأذكار مع الجنازة فلا أصلَ له، بل هو من البدع، لكن إذا دُفن الميت، وفرغوا من دفنه، يُشرع الدعاء له؛ كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم، وسلوا له التثبيت، فإنه الآن يُسأل. فالسنة الدعاء للميت: اللهم اغفر له، اللهم ثبته بالقول الثابت. بعد الفراغ من دفنه، اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم أدخله الجنة، ونجِّه من النار. لا بأس، كله طيبٌ، الرسول ﷺ قال: استغفروا لأخيكم، وسلوا له التثبيت، فإذا سأل له المغفرة والثبات هذا طيبٌ، بعد الدفن، أما رفع الأصوات مع الجنازة، أو عند الدفن على طريقةٍ خاصةٍ: \"لا إله إلا الله، محمدٌ رسول الله\"؛ هذا ما له أصلٌ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14218/حكم-رفع-الصوت-بالذكر-عند-تشييع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70605.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":15676,"question":"يقول: أيضًا من العادات الموجودة عندنا إذا مات إنسان بالغ، سواء كان رجلًا أو امرأة، يذبح عليه، ويحتفلون ثلاثة أيام، وكذلك يقرؤون القرآن الكريم، ويقولون: يلحق هذا صدقة، ويعتبر صدقة للميت، ويقولون: لا نعمل غير مذهبنا، سواء كان صدقًا، أو غير صدق، فما هو توجيهكم للناس؟جزاكم الله خيرًا.","title":"حكم الولائم التي تقام بعد الميت","answer":"الجواب: هذا لا يجوز، بل هو من البدع، ومن عمل الجاهلية، ما يصلح، كونه يذبح بعد الموت، ويدعو الناس يومين أو ثلاثة أو عشرة، كل هذا لا أصل له، إنما المشروع الدعاء له، والترحم عليه، والاستغفار له، وإذا صنع جيرانه أو أقاربه طعامًا، وأرسلوه إلى أهل الميت لا بأس؛ لأن النبي ﷺ لما جاء نعي جعفر بن أبي طالب  لما قتل في مؤتة في الشام، وجاء خبره أمر النبي ﷺ أهل بيته أن يصنعوا طعامًا لآل جعفر، وقال: إنه قد أتاهم ما يشغلهم فإذا صنع الجيران طعامًا لهم أو الأقارب لا بأس، أما هم يصنعون طعامًا، ويقيمون وليمة، يدعون الناس، ويحزنون ثلاثة أيام، أو سبعة، هذا لا أصل له، هذا من البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14220/حكم-الولاىم-التي-تقام-بعد-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70607.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15744,"question":"عندما يسمع الأذان نمسح العينين بباطن أنملة السبابتين بعد تقبيلهما، ما هو رأيكم في ذلك؟علمًا بأننا وجدنا في كتاب فقه السنة، وفي كتاب الحاشية حديثًا يحث فيه الرسول ﷺ أبا بكر الصديق على ذلك.","title":"حكم مسح العينين عند سماع الأذان","answer":"الجواب: هذا لا أصل له، لا أصل له، مسح العينين بأطراف السبابتين هذا لا أصل له عند الأذان، بل هذا من البدع، نعم. المقدم: جزاكم الله خيرًا، وما رأيكم في ذلكم الحديث الذي ذكر في فقه السنة؟\nالشيخ: لا صحة له، نعم.\nالمقدم: الحديث غير صحيح؟\nالشيخ: لا صحة له، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14331/حكم-مسح-العينين-عند-سماع-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70704.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":15831,"question":"هذا السائل يقول في هذا  هل بعد فرض صلاة الجمعة يعاد فرض صلاة الظهر؟","title":"حكم إعادة الظهر بعد أداء صلاة الجمعة","answer":"الجواب: لا؛ هذا بدعة، ليس له أصل، من صلى الجمعة فليس عليه صلاة ظهر، وليس له أن يعيد ظهر، بل هذا من التكلف والتنطع والوسوسة، لا يجوز، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14420/حكم-اعادة-الظهر-بعد-اداء-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57523.mp3","categories":["البدع والمحدثات"]},{"id":15855,"question":"هذا السائل من اليمن رمز لاسمه (ع. ع. أ) يقول -سماحة الشيخ-: في بلدنا إذا مات الشخص يقام له في بيته ثلاث أو سبع ليالي تسمى بالتهاليل؛ لأنه يهلل فيها ثلاث دفعات في كل دفعة مائة تهليلة؛ وذلك في كل ليلة من تلك الليالي، وقبل التهليل في الدفعة الأولى فقط تقرأ سورة يس جماعيًا من قبل الحاضرين، وفي نهاية وتمام المائة يقال دعاء طويل، يختم به الفاتحة إلى روح الميت والأولياء والنبي ﷺ، أفيدونا سماحة الشيخ عن هذا العمل؟","title":"حكم الاجتماع في بيت الميت للتهليل وقراءة القرآن","answer":"الجواب: هذا -يا أخي- بدعة، ما يجوز هذا، هذا منكر وبدعة، لا أصل له من الشرع، بل يجب تركه، إذا مات ميت يعزون يدعى لهم بالصبر والاحتساب، ولميتهم بالمغفرة إذا كان مسلمًا، أما هذه الأعمال فهي منكرة، كلها بدعة، لا أصل لها في الشرع، ولم يفعلها الرسول ﷺ ولا أصحابه ، فهي بدعة منكرة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14446/حكم-الاجتماع-في-بيت-الميت-للتهليل-وقراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57617.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15943,"question":"يقول أخيرًا هذا السائل من الأردن: أنا في كل جمعة وبعد صلاة الفريضة أقول: نويت أن أصلي ركعتين طاعة لله  ولرسوله، وتبعث اللهم أجر هذه الصلاة إلى أرواح والدي ووالدتي.","title":"حكم التلفظ بالنية في الصلاة وإهداء ثوابها للموتى","answer":"الجواب: هذا غير مشروع، والتلفظ بالنية بدعة، لا يجوز التلفظ بالنية، النية محلها القلب، تنوي بقلبك الصلاة صلاة نافلة، أو فريضة أو صوم بالنية لا تتلفظ بها، ولا تثوب بالقراءة، أو الصلاة لوالديك ولا غيرهم، ولكن تدعو لوالديك، تستغفر لهم، تترحم عليهم، تتصدق عنهم، كل هذا طيب، تحج أو تعتمر، كل هذا طيب؛ إذا كانا ميتين، أو كانا عاجزين -كبيري السن عاجزين عن الحج والعمرة- لا بأس بالحج عنهما أو العمرة لعجزهما أو لموتهما، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14548/حكم-التلفظ-بالنية-في-الصلاة-واهداء-ثوابها-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57808.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":16032,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المغرب باعثها أحد الإخوة من هناك يقول، شاب يسأل من المغرب، أخونا يقول: توفي رجل، ثم قام الناس بتشيعيه، وهم يقولون: لا إله إلا الله، محمد رسول الله، وبصوت مسموع، ومرتفع، ثم قام أهل الميت بالصدقة عليه، وعندما رجع الناس من دفنه بدؤوا في الأكل والشرب والضحك فيما بينهم، ما رأي سماحتكم في مثل هذه التصرفات؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت عند تشييع الجنازة والضحك وصنع الطعام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فاتباع الجنازة، ورفع الأصوات بالذكر، أو الصلاة على النبي ﷺ لا أعلم له أصلًا في الشرع، بل السنة خفض الصوت في هذه الحالة، وأن الإنسان يحاسب نفسه، ويتذكر مصير هذا الميت، ومصيره هو أيضًا؛ لأن الموت له شأن عظيم، وذكره يحرك القلب إلى الاستعداد للقاء الله، والقيام بحقه، والحذر من معاصيه . فالمسنون لأتباع الجنازة أن يتأملوا مصير هذا الميت ومصيرهم، وأن يعدوا العدة، وأن يخفضوا الأصوات؛ تقديرًا لهول الموقف، وشدة الحاجة إلى الإعداد للآخرة، والتأهب للموت قبل نزوله. وأما صنع الطعام من أهل الميت فهذا فيه تفصيل: أما صنع الطعام من أجل المصيبة، وجمع الناس هذا ليس من المشروع، بل من عمل الجاهلية، أما إذا صنعوه لأجل ضيف نزل بهم، أو لأنفسهم فلا بأس، أو جاءهم طعام من غيرهم، فإنه يسن لجيرانهم وأقاربهم أن يصنعوا لهم طعامًا؛ لأنه قد أتاهم ما يشغلهم، لما ثبت عن النبي ﷺ أنه أمر أهله أن يصنعوا طعامًا لأهل جعفر لما قتل في مؤتة، لما جاء خبره إلى المدينة  جعفر بن أبي طالب، أمر أهله أن يصنعوا لأهل جعفر طعامًا، وقال: إنه قد أتاهم ما يشغلهم. فإذا صنع أقارب الميت لأهل الميت طعامًا، أو جيرانه؛ فهذا مشروع، وإذا دعا أهل الميت من يأكل معهم من.. الطعام، أو قدموه.. لضيفانهم كل هذا لا بأس به. أما رجوعهم بعد الدفن للضحك، واللعب؛ هذا ليس بالمناسب، بل الأفضل لهم أن يتدبروا الأمر، ويظهر عليهم أمارات الحزن والاستعداد، ولهذا لما مات إبراهيم بن النبي ﷺ قال -عليه الصلاة والسلام-: العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي الرب، وإن بك يا إبراهيم ! لمحزونون. ولما حضر الموت ابن بنته -عليه الصلاة والسلام- دعته ﷺ .... حضر، فلما رأى نفس الصبي تقعقع عند الخروج؛ بكى، فسأله بعض الحاضرين عن ذلك، فقال: إنها رحمة، وإنما يرحم الله من عباده الرحماء. فالأفضل لأهل الميت أن لا يشتغلوا بالضحك واللعب، بل يقدروا الموقف، ويظهر عليهم آثار الحزن مع الرضا عن الله، والاسترجاع: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:156] والصبر والاحتساب، أما مقابلة ذلك بالضحك، واللعب فليس من المشروع، وليس من المناسب، بل المناسب إظهار الحزن، وإظهار الدعاء للميت، والاستغفار له، وعدم إظهار اللعب، والضحك، ونحو ذلك مما يدل على عدم المبالاة، وفي التأسي بالنبي ﷺ الخير والبركة، فما كان ﷺ عند الموت يظهر الضحك، بل كان يظهر الحزن والبكاء ويقول: إنها رحمة وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14669/حكم-رفع-الصوت-عند-تشييع-الجنازة-والضحك-وصنع-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71101.mp3","categories":["حمل الميت ودفنه","أحكام التعزية","البدع والمحدثات"]},{"id":16132,"question":"السؤال الأخير لأخينا يقول: هناك بعض الناس يذبحون سنويًا ذبيحة، ويسمونها صدقة البيت، هل هذا العمل مشروع، أو لا؟ جزاكم الله خيرًا.","title":"حكم ذبيحة ما يسمى (صدقة البيت)","answer":"الجواب: لا أعلم لهذا أصلًا، ذبيحة، صدقة البيت ما نعرف لها أصلًا، هذه بدعة ما لها أصل، يتصدق إذا أراد يتصدق على الفقراء من دون صدقة البيت، يرجو بها ما عند الله، إن بغى يذبح كل يوم يعطي الفقراء لا بأس، أما صدقة البيت هذا شيء لا أصل له، هذه خرافة، لا أصل لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14787/حكم-ذبيحة-ما-يسمى-صدقة-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80312.mp3","categories":["البدع والمحدثات"]},{"id":16147,"question":"يقول أخونا: إنه حين يدفن الميت في المقبرة يأتي أناسًا، ويقرؤون على قبر الميت سورة يس وقل هو الله أحد فهل هذا جائز؟","title":"حكم قراءة يس والإخلاص عند دفن الميت","answer":"الجواب: ليس بجائز، إنما تقرأ يس عند المحتضر قبل أن يموت، أما على قبره لا تقرأ يس، ولا غيرها، ولكن يدعى له بعد الدفن، وعند الزيارة، يدعى له بالمغفرة والرحمة، والنجاة من النار، أما أن يقرأ على الميت على قبره يس، أو غيرها هذا غير مشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14815/حكم-قراءة-يس-والاخلاص-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75005.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":16298,"question":"ما حكم الذكر الجماعي في الشريعة داخل المسجد، وبعضهم يقرؤون السور القرآنية بصوت واحد جماعيًا، فما الحكم؟","title":"حكم الذكر الجماعي والقراءة الجماعية للقرآن","answer":"الجواب: الذكر الجماعي بدعة، لا أصل له، وهكذا التلبية الجماعية المقصودة، كونهم يرفعون الصوت جميعًا، ويخفضونه جميعًا، يبدؤون جميعًا وينتهون جميعًا، كما يفعل بعض الناس في التلبية، بعض الناس في الذكر هذا لا أصل له، بل بدعة؛ لأن العبادات توقيفية، العبادات توقيفية، لا يفعل منها إلا ما جاء به الشرع، فالإنسان يلبي، ويكبر من دون حاجة إلى أن يراعي نغمة أخيه، وكلمة أخيه؛ حتى يرفع معه، وينتهي معه، هذا لا أصل له، كل واحد يكبر يذكر الله، يلبي والحمد لله، أما أن يتفقوا على أن يرفعوا التلبية جميعًا، وينهوها جميعًا، أو الذكر هذا شيء لا أصل له، والنبي  قال: من عمل عملًا ليس عليه أمرنا؛ فهو رد وهكذا القراءة، يقرؤون جميعًا هكذا.  أما إذا كان في التعليم -تعليم الأطفال- يقرؤون جميعًا حتى يتمرنوا، ويتعلموا، هذا -من باب التعليم- لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14995/حكم-الذكر-الجماعي-والقراءة-الجماعية-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71310.mp3","categories":["البدع والمحدثات"]},{"id":16380,"question":"أيضًا: بعد موت الميت يقومون بالقراءة لمدة ثلاثة أيام، وبعد ذلك تؤخذ باقة من الورد، وتلقى على قبره، ما هو توجيهكم؟","title":"حكم قراءة القرآن على القبر","answer":"الجواب:  ذلك بدعة، القراءة على القبر لا يوم ولا أيام، كله بدعة، لا يقرأ على القبور، ولا يجتمعون للقراءة للميت، كل هذا من البدع، أما إذا كان في المجلس، وقرأ واحد يسمعهم للفائدة؛ فلا حرج في ذلك، أما أن يجتمعوا ليقرؤوا للميت، ويثوبوا للميت هذا لا أصل له، وهكذا لو اجتمعوا على قبره، أو قام أحد يقرأ على قبره، كل هذا خلاف الشرع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15093/حكم-قراءة-القران-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75415.mp3","categories":["البدع والمحدثات"]},{"id":16386,"question":"أيضًا: بعد موت الميت يقومون بالقراءة لمدة ثلاثة أيام، وبعد ذلك تؤخذ باقة من الورد، وتلقى على قبره، ما هو توجيهكم؟","title":"حكم قراءة القرآن على القبر","answer":"الجواب:  ذلك بدعة، القراءة على القبر لا يوم ولا أيام، كله بدعة، لا يقرأ على القبور، ولا يجتمعون للقراءة للميت، كل هذا من البدع، أما إذا كان في المجلس، وقرأ واحد يسمعهم للفائدة؛ فلا حرج في ذلك، أما أن يجتمعوا ليقرؤوا للميت، ويثوبوا للميت هذا لا أصل له، وهكذا لو اجتمعوا على قبره، أو قام أحد يقرأ على قبره، كل هذا خلاف الشرع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15093/حكم-قراءة-القران-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75415.mp3","categories":["البدع والمحدثات"]},{"id":16387,"question":"يسأل أيضًا ويقول: هل هناك بدعة حسنة، لا إثم علينا إن عملناها؟ أم كل البدع سواء؟ فلقد استشهد لي بعضهم أن سيدنا عمر بن الخطاب  بعد حفظه لسورة البقرة غيبًا ذبح عدة نوق لوجه الله، أو أنه صام عدة أيام، لا أعلم بالضبط أي أنه ابتدع من عنده بدعة، وهذه قال: بدعة حسنة، فإذا فعلنا مثل فعله ووزعنا اللحم لوجه الله؛ نكون عملنا عملًا حسنًا، فهل تكون هذه البدعة ضلالة، والضلالة إلى النار، أجيبونا أفادكم الله؟","title":"رد شبهة من اعتقد أن في الدين بدعة حسنة","answer":"الجواب: البدعة كلها ضلالة، كما قال النبي ﷺ في الحديث الصحيح يقول -عليه الصلاة والسلام- في الحديث الصحيح في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة رواه مسلم في الصحيح. زاد النسائي: وكل ضلالة في النار بإسناد حسن، وفي الحديث الآخر يقول -عليه الصلاة والسلام-: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة ويقول -عليه الصلاة والسلام-: من أحدث في أمرنا هذا يعني: في ديننا ما ليس منه فهو رد يعني: فهو مردود. متفق على صحته، ويقول أيضًا -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد فالبدع كلها مردودة، كلها غير حسنة كلها ضلالة. وما ذكرته عن عمر لا أصل له.. ما فعل عمر ليس له أصل، ولا نعلم رواه أحد يعتمد عليه، نعم ثبت عن عمر  أنه لما رأى الناس أوزاعًا في المسجد بعد موت النبي ﷺ في خلافته يصلون في رمضان أوزاعًا؛ جمعهم على إمام واحد، على أبي بن كعب يصلي بهم، ثم إنه مر عليهم بعض الليالي وهو يصلي بهم فقال: نعمت البدعة هذه سماها بدعة من جهة اللغة؛ لأن البدعة في اللغة ما أحدث على غير مثال سابق، يقال له: بدعة، وإلا فليست بدعة النبي ﷺ فعل التراويح، وصلاها في الناس، فليست بدعة، وكان يقرهم على فعلها في المساجد -عليه الصلاة والسلام- ولهذا جمعهم عمر عليها، واستقر الأمر على ذلك إلى يومنا هذا. فالتراويح في المساجد ليست بدعة، وإن سماها عمر بدعة فهي من جهة اللغة، وإلا فهي سنة، وقربة، وطاعة. أما الصدقة على الميت من أراد أن يتصدق فليس لها حد محدود، ولا وقت معلوم، يتصدق متى شاء، بدراهم، أو بطعام يعطيه الفقراء، أو ذبيحة يذبحها، ويوزعها على الفقراء، كل هذا طيب، لا حرج في ذلك، سواء في رمضان، وإلا في غير رمضان، ليس له حد محدود، ولا كيفية محدودة، بل متى تيسر له صدقة بدراهم، أو بملابس، أو بطعام، أو بلحم كله طيب، ينفع الميت إذا كان الميت مسلمًا ينفعه ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15090/رد-شبهة-من-اعتقد-ان-في-الدين-بدعة-حسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71502.mp3","categories":["البدع والمحدثات"]},{"id":16400,"question":"لها سؤال مطول بعض الشيء تقول فيه: هل قراءة القرآن عند القبور بدعة، وخاصة سورة الفاتحة، وسورة البقرة، علمًا بأني قرأت في كتاب الروح لابن القيم عن قراءة القرآن عند دفن الميت، وقراءة القرآن أيضًا عقيب الدفن، ومثال ذكر على ذلك: أن جماعة من السلف أوصوا بأن يقرأ عند قبورهم وقت الدفن، قال عبدالحق: يروى أن عبدالله بن عمر أمر أن يقرأ عند قبره سورة البقرة، وممن رأى ذلك المعلا بن عبدالرحمن، وكان الإمام أحمد ينكر ذلك أولًا: حيث لم يبلغه فيه أثر، ثم رجع عن ذلك، أفيدونا عن هذا الأمر؟ جزاكم الله خيرًا.","title":"هل قراءة القرآن عند القبور بدعة؟","answer":"الجواب: القراءة عند القبور بدعة، ولا يجوز فعلها، ولا الصلاة عندها؛ لأن الرسول ﷺ لم يفعل ذلك، ولا أرشد إليه، ولا خلفاؤه الراشدون؛ ولأن هذا مما يفعل في المساجد، والبيوت، يقول ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا فدل على أن القبور ما يصلى عندها، ولا يقرأ عندها، إذ هذا من خصائص المساجد والبيوت، إنما يسلم على أهلها، يزارون، ويسلم عليهم، ويدعى لهم، وكان النبي ﷺ: (إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم، وسلوا له التثبيت؛ فإنه الآن يسأل ولم يقرأ عنده، ولم يأمر بالقراءة عنده. وما يروى عن عبدالله بن عمر إن صح عنه لا يعول عليه؛ لأن العبادات تتلقى من الرسول ﷺ أو من القرآن، ولا يحتج فيها بقول صاحب، ولا غيره، ما عدا الخلفاء الراشدين حيث قال فيهم النبي ﷺ: عليكم بسنتي، وسنة الخلفاء الراشدين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ فما جاء عن الخلفاء الراشدين المهديين يعتمد إذا كان لا يخالف سنته -عليه الصلاة والسلام- وأما ما يروى عن ابن عمر، أو غيره من الصحابة، وغيرهم في العبادات؛ فلا يعول عليه؛ لأن العبادة توقيفية، العبادات توقيفية، لا تؤخذ إلا عن القرآن، أو السنة الصحيحة عن رسول الله، عليه الصلاة والسلام. وما ذكره ابن القيم عن بعض العلماء لا يعتمد عليه، الواجب في مثل هذا الباب هو الاعتماد على القرآن والسنة، وما خالفهما من جهة العبادة يكون بدعة، فلا يصلى عند القبور، ولا يقرأ عندها، ولا يطاف بها، ولا تدعى من دون الله، ولا يستغاث بأهلها. فدعاء الميت، والاستغاثة بالميت، والنذر له هذا من الشرك الأكبر، والدعاء عند قبر كونه يدعو الله عند قبر بدعة، وهكذا القراءة عند القبر بدعة، نعم. المقدم: جزاكم الله خيرًا، هل رجع الإمام أحمد فعلًا عن القول بهذا؟ جزاكم الله خيرًا. الشيخ: يروى هذا، ولا أعرف عن صحته، ولو رجع عنها، ولو قاله أحمد، وأحمد يخطي ويصيب مثل غيره من العلماء، ابن عمر أفضل من أحمد، فالعمدة على الكتاب والسنة، يقول الله -جل وعلا- في كتابه العظيم: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] ويقول -جل وعلا-: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، ويقول جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]. فهذه العبادات هذه المسائل العظيمة يتلقاها المسلمون عن القرآن العظيم والسنة المطهرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15104/هل-قراءة-القران-عند-القبور-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81108.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":16409,"question":"يقول: في التراويح حدث عندنا أنه بعد السلام من الركعتين الأوليين يقرأ الإمام الصلاة على النبي ﷺ ويدعو فيها للخلفاء بعد كل ركعتين، فما حكم هذا العمل؟","title":"ما حكم الصلاة والتسليم والدعاء أثناء التراويح؟","answer":"الجواب: هذا الذي ينبغي تركه؛ لأنه لا أصل له، بل هو من البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15121/ما-حكم-الصلاة-والتسليم-والدعاء-اثناء-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75503.mp3","categories":["البدع والمحدثات"]},{"id":16437,"question":"سماحة الشيخ! في آخر أسئلة هذا السائل فضل الله من السودان مقيم في ليبيا يقول: رجل إذا سلم عن يمينه يقول: السلام عليكم ورحمة الله، اللهم إني أسألك الفوز بالجنة، وإذا سلم عن شماله قال: السلام عليكم ورحمة الله، اللهم إني أسألك النجاة من النار، فهل هذا مكروه، أم لا؟ فإن كان مكروهًا فما الدليل على كراهته؟ مأجورين.","title":"حكم إضافة أدعية بعد كل تسلمية في الصلاة","answer":"الجواب: ليس لهذا أصل، بل هذا بدعة، لا يقول شيء إذا سلم إلا ما قاله النبي ﷺ إذا سلم التسليمتين يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام هكذا كان النبي ﷺ يفعل إذا سلم، أما هذا الدعاء بعد التسليمة الأولى، والتسليمة الثانية هذا لا أصل له، هذا من كيسه، بدعة، نعم. المقدم: زيادة السلام عليكم ورحمة الله وبركاته في السلام يا شيخ؟ الشيخ: الأفضل عدمها؛ لأن في صحتها نظر، وخلاف بين أهل العلم، والمحفوظ: السلام عليكم ورحمة الله. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15133/حكم-اضافة-ادعية-بعد-كل-تسلمية-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58129.mp3","categories":["التشهد والتسليم","البدع والمحدثات"]},{"id":16460,"question":"من ليبيا المستمع (س. ف. ك) رسالة ضمنها بعض الأسئلة في أحد أسئلته يقول: عندنا عادة، وهي في اليوم الثاني عشر من ربيع الأول نعمل وجبة إفطار منذ الصباح الباكر، ونقوم بتوزيعها على الجيران، ونحن نهنئ الجيران والأقرباء بعضهم بعضًا بحجة الفرح بالمولد النبوي، فهل لنا أن نستمر في عمل هذه الأطعمة، والأكل منها، ونعمل تلك الاحتفالات؟ جزاكم الله خيرًا.","title":"ما حكم توزيع الأطعمة والتهنئة في يوم المولد؟","answer":"الجواب: هذا العمل ليس مشروعًا، بل هو بدعة، ولو فعله الكثير من الناس؛ لأن النبي ﷺ وأصحابه لم يفعلوا ذلك، فلم يحتفل ﷺ بمولده في حياته، ولم يأمر بذلك، وهو أنصح الناس -عليه الصلاة والسلام- هو أنصح الناس، وأعلم الناس، وأحرص الناس على الخير -عليه الصلاة والسلام- فلو كان هذا العمل مشروعًا، وحسنًا لفعله ﷺ أو أرشد إليه. وهكذا الخلفاء الراشدون، وهم أفضل الناس بعد الأنبياء لم يفعلوه، ولم يأمروا به، وهكذا الصحابة بقية الصحابة -رضي الله عنهم- لم يفعلوه، ولم يأمروا به، وهكذا سلف الأمة في القرون المفضلة لم يفعلوه، وهم خير الناس بعد الأنبياء، كما قال -عليه الصلاة والسلام-: خير الناس قرني، ثم الذين يلونهم، ثم الذين يلونهم. فالواجب عليكم ترك هذه البدعة، والحرص على اتباع النبي ﷺ في أقواله وأعماله، هذا هو الواجب على المسلمين أن يتبعوه، وينقادوا لشرعه، ويعظموا أمره ونهيه، ويسيروا على سنته ونهجه، عليه الصلاة والسلام. أما البدع فلا خير فيها، فهي شر، يقول -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا؛ فهو رد يعني: فهو مردود، ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد متفق على صحته، وفي صحيح مسلم عن جابر  قال: كان النبي ﷺ يقول في الخطبة -خطبة الجمعة- أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة. فهذا العمل الذي فعلتم من إهداء الطعام، أو الاحتفال بغير ذلك، في اليوم الثاني عشر من ربيع أول بالطعام، أو بالصلوات، أو بالتزاور كله بدعة لا أصل له، يقول الرب : قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] فاتباع النبي ﷺ هو حقيقة الحب، وهو دليل الحب الصادق، ويقول -عليه الصلاة والسلام-: من رغب عن سنتي فليس مني. فنوصيكم، وغيركم من إخواننا المسلمين بترك هذه البدعة، وهي الاحتفالات بالمولد النبوي، أو بغير المولد النبوي بالموالد الأخرى، كلها غير مشروعة. ولكن نوصيكم باتباع الرسول ﷺ دائمًا، والتفقه في الدين، وتعليم الناس السنة، والحرص على طاعة الله ورسوله في كل شيء، هذا هو الواجب على جميع المكلفين أن يخلصوا لله العبادة، وأن يعظموه، وأن ينقادوا لشرعه، وأن يسيروا على نهج نبيه ﷺ في القول والعمل، في جميع الأحوال، قال تعالى في كتابه العظيم: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]. وقال -عليه الصلاة والسلام- في الحديث الصحيح: من أطاعني؛ فقد أطاع الله، ومن عصاني؛ فقد عصى الله فالواجب طاعته، واتباع هديه -عليه الصلاة والسلام- والحذر مما خالف هديه -عليه الصلاة والسلام- في كل شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15193/ما-حكم-توزيع-الاطعمة-والتهنىة-في-يوم-المولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81305.mp3","categories":["البدع والمحدثات"]},{"id":16586,"question":"يقول: هل تجوز الصلاة خلف إمام مبتدع، يتوسل في دعائه بجاه الأنبياء، والصالحين، ويقوم بأعمال شركية؟","title":"هل تجوز الصلاة خلف إمام مبتدع؟","answer":"الجواب: هذا ما يترك إمامًا، هذا يرفع أمره إلى الجهة المسؤولة؛ حتى يزال من الإمامة، لا يجوز أن يؤم الناس إلا رجل عدل معروف بالخير، ولا يجوز أن يؤمهم مبتدع مشرك، بجاه فلان، هذا بدعة، من وسائل الشرك، لكن إذا كان عنده أمور أخرى شركية، مثلًا: يدعو الأنبياء.. يستغيث بالنبي.. يستغيث بأهل البيت.. يستغيث بالأولياء.. يسألهم الشفاعة.. يسألهم شفاء المريض، هذا شرك أكبر، هذا ما تصح صلاته، ولا جعله إمامًا. والمقصود: أن الواجب على الجماعة -جماعة المسجد- أن يرفعوا أمر هذا الإمام إلى الجهة المسؤولة، ويطلبوا تغييره بإنسان معروف بالإيمان والعدالة والاستقامة، حتى ولو كان غير مشرك، ما دام مبتدعًا معروفًا بالبدعة أن يزال، ويسعى في إزالته، لكن إن كان مسلمًا؛ صحت الصلاة، إذا كانت بدعته لم تخرجه من الإسلام؛ صحت الصلاة، أما إن كانت بدعته تخرجه من الإسلام كالذي يدعو أهل البيت، ويستغيث بهم، أو يعتقد فيهم أنهم يعلمون الغيب، أو أنهم معصومون، أو يسب الصحابة؛ هذا ما يتخذ إمامًا، ولا يصلى خلفه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15326/هل-تجوز-الصلاة-خلف-امام-مبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75808.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":16588,"question":"المستمع فؤاد (ع.ح) بعث برسالة يقول فيها: أرجو من الله، ثم منكم -حفظكم الله- أن تخبروني عن حكم المولد النبوي؟ وعن حكم من يقوم به، وخاصة إذا كان إمامًا، وخطيبًا لمسجد؟ وهل تجوز الصلاة خلفه؟ حيث أني إذا قلت لأحدهم: إن هذا الأمر بدعة منكرة، انزعج كثيرًا، واحتج بحديث في مسلم في فضل صيام يومي الخميس والإثنين، والشاهد من الحديث وهو يوم ولدت فيه الحديث، فماذا نفعل تجاه هؤلاء الناس، وخاصة أنهم من أصحاب المساجد؟ وإنا لله، وإنا إليه راجعون، وجزاكم الله عنا وعن المسلمين خيرًا.","title":"حكم الاحتفال بمولد النبي ﷺ والصلاة خلف من يحتفل به","answer":"الجواب: الاحتفال بالموالد من البدع التي حدثت في الناس، ومنها مولد النبي ﷺ فالاحتفال به من البدع التي حدثت للمسلمين، ولم يفعله النبي ﷺ ولا أصحابه، لا الخلفاء الراشدون، ولا غيرهم، وهكذا لم يفعله المسلمون في القرون المفضلة الثلاثة، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا؛ فهو رد يعني: فهو مردود، وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد أي: فهو مردود. فالواجب على المسلمين ترك ذلك، وأن يعتنوا بسنته ﷺ واتباع سيرته، والاستقامة على هديه -عليه الصلاة والسلام- أما الاحتفال بالمولد فلا وجه له، بل هو بدعة من البدع التي يجب تركها، والمطلوب من المسلم اتباع الرسول ﷺ وتعظيم شرعه، وتعظيم سنته، والسير على منهاجه كما قال الله : قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] وقال سبحانه: ومَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]. فالواجب محبته، واتباعه، والأخذ بما جاء به، والحذر مما نهى عنه، هذا هو واجب المسلم، أما البدع فلا المولد، وغير المولد لا تجوز البدع في الدين، بل يجب تركها، فالاحتفال بالموالد، والبناء على القبور، واتخاذ المساجد على القبور، والصلاة عند القبور، كل هذه من البدع التي أحدثها الناس. وهكذا بدعة الإسراء، والمعراج في سبعة وعشرين رجب، الاحتفال بها من البدع أيضًا، لا أصل لها في الشرع. وينبغي أن ينصح الإمام الذي يصلي بالناس أن يدع هذا، والصلاة خلفه صحيحة إذا كان ما عنده إلا بدعة المولد، فالصلاة خلفه صحيحة؛ لأنها بدعة، وليست كفرً. لكن إذا كان في المولد يدعون الرسول ﷺ ويستغيثون به، هذا كفر أكبر، إذا كانوا يدعون الرسول ﷺ ويستغيثون به، وينذرون له؛ هذا من الكفر الأكبر، أما مجرد الاحتفال بالمولد، والأكل، وجمع الطعام، والإجماع على الطعام، وتلاوة القصائد التي ما فيها شرك، هذا بدعة، أما القصائد التي فيها الشرك مثل البردة إذا أقروا بما فيها من الشرك مثل قوله:","link":"https://binbaz.org.sa/fatwas/15333/حكم-الاحتفال-بمولد-النبي-ﷺ-والصلاة-خلف-من-يحتفل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81713.mp3","categories":["البدع والمحدثات"]},{"id":16599,"question":"المستمع فؤاد (ع.ح) بعث برسالة يقول فيها: أرجو من الله، ثم منكم -حفظكم الله- أن تخبروني عن حكم المولد النبوي؟ وعن حكم من يقوم به، وخاصة إذا كان إمامًا، وخطيبًا لمسجد؟ وهل تجوز الصلاة خلفه؟ حيث أني إذا قلت لأحدهم: إن هذا الأمر بدعة منكرة، انزعج كثيرًا، واحتج بحديث في مسلم في فضل صيام يومي الخميس والإثنين، والشاهد من الحديث وهو يوم ولدت فيه الحديث، فماذا نفعل تجاه هؤلاء الناس، وخاصة أنهم من أصحاب المساجد؟ وإنا لله، وإنا إليه راجعون، وجزاكم الله عنا وعن المسلمين خيرًا.","title":"حكم الاحتفال بمولد النبي ﷺ والصلاة خلف من يحتفل به","answer":"الجواب: الاحتفال بالموالد من البدع التي حدثت في الناس، ومنها مولد النبي ﷺ فالاحتفال به من البدع التي حدثت للمسلمين، ولم يفعله النبي ﷺ ولا أصحابه، لا الخلفاء الراشدون، ولا غيرهم، وهكذا لم يفعله المسلمون في القرون المفضلة الثلاثة، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا؛ فهو رد يعني: فهو مردود، وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد أي: فهو مردود. فالواجب على المسلمين ترك ذلك، وأن يعتنوا بسنته ﷺ واتباع سيرته، والاستقامة على هديه -عليه الصلاة والسلام- أما الاحتفال بالمولد فلا وجه له، بل هو بدعة من البدع التي يجب تركها، والمطلوب من المسلم اتباع الرسول ﷺ وتعظيم شرعه، وتعظيم سنته، والسير على منهاجه كما قال الله : قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] وقال سبحانه: ومَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]. فالواجب محبته، واتباعه، والأخذ بما جاء به، والحذر مما نهى عنه، هذا هو واجب المسلم، أما البدع فلا المولد، وغير المولد لا تجوز البدع في الدين، بل يجب تركها، فالاحتفال بالموالد، والبناء على القبور، واتخاذ المساجد على القبور، والصلاة عند القبور، كل هذه من البدع التي أحدثها الناس. وهكذا بدعة الإسراء، والمعراج في سبعة وعشرين رجب، الاحتفال بها من البدع أيضًا، لا أصل لها في الشرع. وينبغي أن ينصح الإمام الذي يصلي بالناس أن يدع هذا، والصلاة خلفه صحيحة إذا كان ما عنده إلا بدعة المولد، فالصلاة خلفه صحيحة؛ لأنها بدعة، وليست كفرً. لكن إذا كان في المولد يدعون الرسول ﷺ ويستغيثون به، هذا كفر أكبر، إذا كانوا يدعون الرسول ﷺ ويستغيثون به، وينذرون له؛ هذا من الكفر الأكبر، أما مجرد الاحتفال بالمولد، والأكل، وجمع الطعام، والإجماع على الطعام، وتلاوة القصائد التي ما فيها شرك، هذا بدعة، أما القصائد التي فيها الشرك مثل البردة إذا أقروا بما فيها من الشرك مثل قوله:","link":"https://binbaz.org.sa/fatwas/15333/حكم-الاحتفال-بمولد-النبي-ﷺ-والصلاة-خلف-من-يحتفل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81713.mp3","categories":["البدع والمحدثات"]},{"id":16797,"question":"هل تجوز صلاة فروض بدلًا من التي يمكن أن تكون لم تقبل، فلقد وجدت أختًا تصلي من الفروض التي عسى أن تكون لم تقبل لكثرة سهوها، أو أي شيء آخر؟","title":"هل يجوز إعادة الصلاة مخافة عدم قبولها؟","answer":"الجواب: هذا بدعة لا يجوز، الأصل الإجزاء، فليس لها، ولا للرجل أن يأتي بصلوات احتياطًا؛ مخافة أن الصلاة الأولى ما قبلت، هذا وساوس، وشكوك لا وجه لها، أما إذا علم أن صلاته باطلة؛ لأنه أحدث فيها، أو صلاها بغير طهارة، هذا يعيد، أما مجرد أنه وسوس، هذا من الشيطان، والأصل السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15580/هل-يجوز-اعادة-الصلاة-مخافة-عدم-قبولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82311.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":16805,"question":"هل تجوز صلاة فروض بدلًا من التي يمكن أن تكون لم تقبل، فلقد وجدت أختًا تصلي من الفروض التي عسى أن تكون لم تقبل لكثرة سهوها، أو أي شيء آخر؟","title":"هل يجوز إعادة الصلاة مخافة عدم قبولها؟","answer":"الجواب: هذا بدعة لا يجوز، الأصل الإجزاء، فليس لها، ولا للرجل أن يأتي بصلوات احتياطًا؛ مخافة أن الصلاة الأولى ما قبلت، هذا وساوس، وشكوك لا وجه لها، أما إذا علم أن صلاته باطلة؛ لأنه أحدث فيها، أو صلاها بغير طهارة، هذا يعيد، أما مجرد أنه وسوس، هذا من الشيطان، والأصل السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15580/هل-يجوز-اعادة-الصلاة-مخافة-عدم-قبولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82311.mp3","categories":["الأدعية والأذكار","البدع والمحدثات","مسائل متفرقة في الصلاة"]},{"id":16913,"question":"يقول: هل هناك سنة للجمعة؟ لأن بعض المؤذنين هنا بعد الانتهاء من الأذان الأول يقول: سنة الجمعة، يرحمكم الله.","title":"سنة الجمعة القبلية والبعدية","answer":"الجواب: هذا غلط، هذا المؤذن الذي يقول هكذا؛ ..... غلط، بدعة لا أصل لها، والجمعة ليس لها راتبة قبلها، بل يصلي ما يسر الله، يصلي ثنتين، أو أربع ركعات -تسليمتين- أو ست ركعات -ثلاث تسليمات- أو أكثر، يصلي ما قدر له إذا وصل المسجد، والحمد لله، وليس هناك حد محدود قبل صلاة الجمعة، ولو صلى مائة ركعة قبل أن يدخل الإمام، يسلم من كل ثنتين. أما بعدها، فالأفضل أربع ركعات، النبي  قال: إذا صلى أحدكم الجمعة فليصل بعدها أربعًا وقال: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا فالسنة أن يصلي بعدها أربعا -تسليمتين- سواء في المسجد، أو في البيت، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15687/سنة-الجمعة-القبلية-والبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82607.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":17022,"question":"يقول: عندنا في أغلب المساجد بعد الانتهاء من الصلاة نجد جميع المصلين بصوت واحد مرتفع يقولون: نستغفر الله العظيم الذي لا إله إلا هو الحي القيوم ثلاثًا، ثم يقولون بصوت مرتفع أيضًا ثلاثًا: يا أرحم الراحمين ارحمنا، مع العلم بأن بعض المأمومين بعد تسليم الإمام يقوم لإتمام صلاته بإتيان ما فاته من ركعات، وهم يشوشون عليه بارتفاع أصواتهم، ونقول لهم: الاستغفار يكون في السر، ولكن يقولون: الوارد عن الرسول ﷺ كان يقرؤه جهرًا، أي: قراءة الأذكار دبر الصلاة جهرًا، ما هو توجيهكم؟ وما هو القول الصحيح؟ جزاكم الله خيرًا.","title":"حكم الإتيان بأذكار الصلاة بصورة جماعية","answer":"الجواب: هذا العمل الذي ذكرته هذا لا يشرع، وإنما الاستغفار عند السلام، إذا سلم من الصلاة استغفر ثلاثًا، وقال: اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام، يستغفر ثلاثًا بكلام يسمعه من حوله، كما كان النبي يفعل -عليه الصلاة والسلام- ثم يأتي بالذكر المشروع: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد. هذا هو المشروع يرفع صوته بذلك رفعًا لا يشغل المصلين، بل يكون رفعًا متوسطًا، لقول ابن عباس -رضي الله تعالى عنهما-: \"كان رفع الصوت بالذكر حين ينصرف الناس من المكتوبة على عهد النبي ﷺ\" وقال ابن عباس: \"كنت أعلم إذا انصرفوا بذلك إذا سمعته\" فدل على أنهم يرفعون أصواتهم، لكنه رفع لا يضر المصلين، ولا يشوش عليهم، بل يسمعهم من حول المسجد، ومن يمر بالمسجد حتى يعلم أن الصلاة قد انتهت. ويستحب أيضًا مع ذلك أن يسبح، ويحمد، ويكبر ثلاثًا وثلاثين مرة، كل واحد من المصلين: سبحان الله، والحمد لله، والله أكبر، ثلاثًا وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، هذا مشروع، أوصى به النبي ﷺ وبينه للأمة، وأخبر أنه تكفر به الخطايا. ويستحب أيضًا بعد صلاة الفريضة أن يقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ... [البقرة:255]، الإمام، والمأموم، والمنفرد بينه وبين نفسه، ويقرأ: قل هو الله أحد والمعوذتين، كذلك بعد كل صلاة، ويكرر السور الثلاث في المغرب، والفجر ثلاث مرات، يكرر السور الثلاث في المغرب، والفجر ثلاث مرات كما جاءت بذلك السنة عن النبي -عليه الصلاة والسلام- هذا هو المشروع بعد الصلوات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15813/حكم-الاتيان-باذكار-الصلاة-بصورة-جماعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83006.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":17027,"question":"رسالةٌ وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها جمعًا من الأسئلة، في أحدها يقول: ما حكم صيام يوم النصف من شعبان، وقيام ليلة النصف من شعبان، والدعاء الذي يقال في هذه الليلة؟","title":"حكم صيام يوم النصف من شعبان وقيام ليلته","answer":"الجواب: هذا ضعيفٌ، ليس له أصلٌ، ليس له أصلٌ صحيحٌ، فلا يُستحب صيام يوم النصف، ولا يُستحب قيام ليلة النصف؛ لعدم ثبوت الأحاديث في ذلك، وقد كتبنا في هذا عدة كتاباتٍ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15810/حكم-صيام-يوم-النصف-من-شعبان-وقيام-ليلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83005.mp3","categories":["البدع والمحدثات","صيام التطوع"]},{"id":17034,"question":"السائل يقول: عندنا عادة قديمة، وهي إذا دخل أول خميس من شهر رجب فإن الناس يذبحون ويغسلون الأولاد، وأثناء تغسيلهم للأولاد يقولون: يا خميس أول رجب نجنا من الحصبة والجرب، ويسمون هذا اليوم كرامة رجب، وجهونا في ضوء هذا السؤال؟","title":"حكم الاحتفال بجمعة رجب","answer":"الجواب: هذا منكر لا أصل له، بدعة ولا يجوز، يا خميس! هذا دعاء غير الله، هذا شرك أكبر، دعاء غير الله شرك أكبر، والمقصود أن هذا بدعة لا يجوز، نسأل الله العافية. نعم. المقدم: نسأل الله العفو العافية.","link":"https://binbaz.org.sa/fatwas/15818/حكم-الاحتفال-بجمعة-رجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58712.mp3","categories":["البدع والمحدثات"]},{"id":17035,"question":"هل يجوز الاحتفال بليلة النصف من شعبان، وإحياء هذه الليلة؟","title":"حكم الاحتفال بليلة النصف من شعبان","answer":"الجواب: لا يجوز الاحتفال بليلة النصف من شعبان، وليس له أصل، ولا ليلة سبعة وعشرين من رجب التي يسمونها ليلة الإسراء والمعراج، كلها بدعة، لا يحتفل بليلة النصف من شعبان، ولا ليلة سبعة وعشرين من رجب، كل هذا من البدع التي أحدثها الناس، وهكذا الاحتفال بالمولد النبوي بدعة، لا يجوز الاحتفال بالمولد النبوي، ولا بليلة النصف من شعبان، ولا بليلة سبعة وعشرين من رجب التي يسمونها ليلة الإسراء والمعراج، كل هذا بدعة لم يفعله رسول الله ﷺ ولا خلفاؤه الراشدون، ولا صحابته -رضوان الله عليهم- ولا السلف الصالح في القرون المفضلة الثلاثة، بل هذا مما أحدثه الناس، نسأل الله العافية. نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15824/حكم-الاحتفال-بليلة-النصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58713.mp3","categories":["البدع والمحدثات"]},{"id":17104,"question":"سماحة الشيخ! من أسئلة هذا السائل يقول: هل الشيء الحسن بدعة، مثل: الموالد التي فيها ذكر الله، ومثل إقامة مولد كل سنة لمن مات أبوه، أو قريبه، وكذلك الجلوس في المقبرة ثلاثة أيام يذكرون الله فيها إلى روح الميت؟","title":"بيان أن العبادات تكون بالشرع لا بالاستحسان","answer":"الجواب: العبادات تكون بالشرع ما هو بالرأي والاستحسان، العبادات تكون بشرع الله؛ ما قاله الله ورسوله، وما شرعه الله ورسوله، أما ما أحدثه الناس فهو بدعة، لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وقوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد والله يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] فالاجتماع للموالد بدعة، لا مولد النبي ﷺ ولا غيره، الاجتماع للموالد، والاحتفال بالموالد هذا من البدع التي أحدثها الناس، وهكذا كونه يحيي بدعة لأبيه، مولدًا لأبيه أو لأمه بدعة لا يجوز. وهكذا الجلوس عند القبور للدعاء، أو القراءة بدعة لا يجوز، بل من وسائل الشرك. والقاعدة: أن العبادة ما شرعه الله، توقيفية، لا يكون شيء عبادة إلا إذا شرعه الله، أو شرعه رسوله ﷺ، أما إحداث الناس لا، يقول ﷺ: من أحدث في أمرنا يعني: في ديننا هذا ما ليس منه فهو رد يعني: فهو مردودٌ عليه، ويقول -عليه الصلاة والسلام-: إياكم ومحدثات الأمور .نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15895/بيان-ان-العبادات-تكون-بالشرع-لا-بالاستحسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58903.mp3","categories":["البدع والمحدثات","أصول الفقه"]},{"id":17161,"question":"السائل أحمد سالم استعرضنا بعضًا من أسئلته بقي له هذا السؤال، يقول: عند تشييع الجنازة يا شيخ إلى المقبرة يرددون أذكارًا بصوت جماعي، مثل: لا إله إلا الله محمد رسول الله.. وغير ذلك، وعندما يدخل الميت في القبر يؤذنون ويقيمون، وبعد الدفن يلقنونه، أي: يقولون: يا فلان ابن فلان قل: لا إله إلا الله، قل: ربي الله، وديني الإسلام، ونبيي محمد ﷺ ما رأيكم في مثل هذا العمل؟","title":"حكم رفع الصوت في الجنازة والأذان عند الدفن","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا العمل كله بدعة لا يجوز، رفع الأصوات مع الجنائز ووحدوه، أو لا إله إلا الله، كلها بدعة، السنة مع الجنائز التدبر، والتأمل، والخشوع، وتذكر الموت، والدعاء للميت، أما رفع الأصوات بالأذكار أو وحدوه، كل هذا لا أصل له.  وهكذا الأذان في القبر، أو الإقامة في القبر كله بدعة، وهكذا التلقين، يا فلان اذكر ما خرجت له من الدنيا، كله بدعة، والأحاديث في التلقين كلها غير صحيحة، غير ثابتة عن النبي ﷺ فهذا كله بدع، لا يلقن، ولا ينفعه التلقين، ما ينفعه إلا عمله السابق قبل الموت، أما بعد الموت لا ينفعه، وهكذا الأذان في قبره، أو الإقامة في قبره، أو القراءة، كله بدعة لا تجوز. نعم.","link":"https://binbaz.org.sa/fatwas/15979/حكم-رفع-الصوت-في-الجنازة-والاذان-عند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59001.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":17341,"question":"هذا سائل للبرنامج السائل أحمد عبد الرحمن يقول: بعض من يقرؤون القرآن يا سماحة الشيخ بعد انتهائهم من القراءة يقولون: الفاتحة، هل هذا وارد في السنة؟","title":"ما حكم قراءة الفاتحة جماعيا بعد تلاوة القرآن؟","answer":"الجواب: لا، هذا بدعة، ما له أصل، لا يستعمل، لا يجوز استعماله، هذا من البدع. نعم.","link":"https://binbaz.org.sa/fatwas/16177/ما-حكم-قراءة-الفاتحة-جماعيا-بعد-تلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59320.mp3","categories":["البدع والمحدثات"]},{"id":17342,"question":"يقول السائل في ثاني أسئلته سماحة الشيخ! البعض يقولون: بأن قراءة سورة يس تفرج الكروب، والهموم، ويخصون بذلك هذه السورة سورة يس دون سائر القرآن العظيم، هل هذا صحيح؟","title":"حكم تخصيص قراءة يس لتفريج الكروب","answer":"الجواب: ليس لهذا أصل، بل القرآن كله خير، كله من أسباب الخير، والبركة، قراءة القرآن من أسباب تفريج الهموم، وتفريج الكروب، ومن أسباب الخير العظيم، ومن أسباب مرضات الله، يقرأ، يكثر الإنسان من قراءة القرآن، ويبشر بالخير. أما قراءة يس إنما ورد قراءتها عند المحتضر قبل أن يموت، جاء في بعض الأحاديث -وإن كان فيها بعض الضعف- أنها تقرأ عند المريض إذا احتضر قبل أن يموت. نعم.","link":"https://binbaz.org.sa/fatwas/16179/حكم-تخصيص-قراءة-يس-لتفريج-الكروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59321.mp3","categories":["البدع والمحدثات","القرآن وعلومه"]},{"id":17363,"question":"هذا سائل للبرنامج يقول في هذا  هل يجوز لي يا سماحة الشيخ الاستغفار لشخص من أحد أقاربي مات، وأنا لا أدري أهو مات على حسن الخاتمة، أم لا؟ علمًا بأنه كان يجلل، أو يقدس الأولياء، وأصحاب القبور، والأضرحة، ويعتقد بأن هذا من الدين، وجهوني في سؤالي.","title":"حكم الاستغفار لمن كان يعظم أصحاب القبور","answer":"الجواب: إذا كان ظاهره الشرك، والغلو في الأموات، ودعاء الأموات، والاستغاثة بالأموات لا، لا يدعى له، ولكن إذا كان ظاهره الإسلام، ولا تعلم عنه إلا الإسلام؛ فلا بأس تدعو له، وتستغفر لأخيك، هذا مشروع، المؤمن يدعو لإخوانه، ويستغفر لهم، كما قال أتباع المهاجرين والأنصار بإحسان: رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10]، فأنت تستغفر لإخوانك، تدعو لهم بالرحمة إذا كان ظاهره الإسلام. أما من كان ظاهره الشرك -وهو الغلو في القبور ودعاء الأموات والاستغاثة بالأموات- فهذا لا يدعى له؛ لأن دعاء الأموات، والاستغاثة بالأموات، وطلب الحوائج منهم هذا من الشرك الأكبر، هذا دين المشركين، نسأل الله العافية. وهكذا دعاء الجن .. دعاء الأصنام .. دعاء الكواكب، كل هذا من الشرك الأكبر، يقول الله -جل وعلا-: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113]. ولما مات أبو طالب على دين قومه قال النبي ﷺ: لأستغفرن لك ما لم أُنْهَ عنك فأنزل الله في ذلك هذه الآية: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113] من مات على الشرك فهو من أصحاب الجحيم. فالمقصود: أن من كان معروفًا بدعاء الأموات، والاستغاثة بأهل القبور أو بالأصنام أو بالجن أو بالكواكب، أو بالملائكة، أو بالأنبياء، هذا كله شرك أكبر داخل في قوله -جل وعلا-: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] وداخل في قوله سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] وداخل في قوله سبحانه: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وفي قوله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ ۝ بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:66]، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ[فاطر:13].  القطمير: اللفافة التي على النواة وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] هذا يعم الجميع، يعم الغائبين، ويعم الموتى من الأنبياء، وغيرهم إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا [فاطر:14] ولو قدرنا أنهم سمعوا لم يستجيبوا وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] يعني: ينكرون ويتبرؤون إلى الله يقول سبحانه: تَبَرَّأْنَا إِلَيْكَ مَا كَانُوا إِيَّانَا يَعْبُدُونَ [القصص:63] نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16208/حكم-الاستغفار-لمن-كان-يعظم-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77004.mp3","categories":["إهداء القرب للميت","نواقض الإسلام","البدع والمحدثات"]},{"id":17469,"question":"بعد هذا ننتقل إلى المملكة المغربية عبر رسالة بعث بها مستمع يقول: مولاي حميد البكواري، الأخ البكواري له ثلاثة أسئلة في أحدها يقول: ما حكم الأضرحة في الإسلام؟ وهل تجب الزيارة لغير الأماكن المقدسة، كزيارة ضريح مثلًا، ما حكم الشرع في ذلك؟ جزاكم الله خيرًا.","title":"حكم بناء الأضرحة على القبور","answer":"الجواب: أما الأضرحة ففيها تفصيل، الأضرحة هي القبور، فالسنة أن ترفع عن الأرض قدر شبر؛ حتى يعلم أنها قبور حتى لا تمتهن، ولهذا في حديث سعد بن أبي وقاص : أن قبر النبي ﷺ رفع قدر شبر، وأوصى أن يفعل بقبره كذلك يعني: سعد. أما ما يتعلق بالبناء عليها، واتخاذ المساجد عليها، والقباب هذا لا يجوز، هذا منكر عند أهل العلم، وبدعة، وهو من وسائل الشرك، ولهذا قال النبي الكريم -عليه الصلاة والسلام- في الحديث الصحيح: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد. وفي صحيح مسلم عن جابر  عن النبي ﷺ: أنه نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه. فلا يجوز البناء على القبور، لا مسجد، ولا قبة، ولا غيرهما، ولا يجصص أيضًا؛ لأن هذا من وسائل الشرك، من وسائل أنه يعظم، ويدعى من دون الله، ويستغاث به، فيقع الشرك، فالبناء على القبور، واتخاذ القباب عليها، والمساجد، والسرج من الوسائل المحرمة، من وسائل الشرك، ولهذا حذر منها النبي -عليه الصلاة والسلام- ولعن أهلها. فالواجب على كل مسلم أن يحذر ذلك، وألا يبني على القبر، لا مسجد، ولا غيره، ولا قبة، ولا يجصص، ولا يتخذ عليه سرج، ولا ستور كل هذا لا يجوز، بل ذلك من وسائل الشرك؛ لأن البناء حول الستور، حول السرج، حول المساجد، حول القبة كل هذا من وسائل التعظيم، والشرك. وإذا دعا الميت، وقال: يا سيدي، أو يا فلان، أغثني، أو انصرني، أو اشف مريضي، أو أنا في حسبك، وجوارك، كل هذا من الشرك الأكبر، كل هذا من عمل المشركين الأولين، فالواجب الحذر من ذلك، وهكذا الطواف بالقبور، يطوف عليها، يرجو بركتها، ويرجو فضل أهلها ، ويرجو نفعهم، هذا من الشرك الأكبر. أما إذا كان جاهلًا، يظن أن الطواف سنة مثل الكعبة، يطوف لله، يتقرب إلى الله، هذا بدعة منكر، يكون من وسائل الشرك، أما إذا طاف، يتقرب لصاحب القبر، فهذا هو الشرك الأكبر، مثل لو دعاه، أو استغاث به، أو نذر له، أو ذبح له، كل هذا من الشرك الأكبر. فالواجب على كل مسلم ومسلمة الحذر من ذلك، وإنما الزيارة الشرعية أن يزور القبور للتسليم عليهم، والدعاء لهم، كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، هكذا يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة. فيأتي ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هكذا علم النبي ﷺ الصحابة، علمهم هكذا -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا، والمستأخرين هكذا، هذه الزيارة الشرعية، ثم ينصرف، لا يصلي عند القبر، ولا يقرأ عنده، ولا يطوف به، ولا يسأله قضاء حاجة، كل هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16337/حكم-بناء-الاضرحة-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72506.mp3","categories":["البدع والمحدثات"]},{"id":17488,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين فيما يبدو من خطه أنه سوداني يقول: رقيب محمود محمد علي، يسأل سماحتكم فيقول: بعد الانتهاء من الفريضة المكتوبة، وبعد الانتهاء من الباقيات الصالحات، وختمها بلا إله إلا الله، يقوم الإمام برفع يديه، ويدعو الله، والجميع يقولون من خلفه: آمين، ويقرأ في شيء من القرآن الكريم كفاتحة الكتاب، نرجو أن توجهونا، هل هذا العمل مبتدع؟ أم أنه جائز ؟جزاكم الله خيرًا.","title":"حكم الدعاء بعد الفريضة وتأمين المأمومين عليه","answer":"الجواب: هذا العمل مبتدع، ليس له أصل في الشرع فيما نعلم، فلم يكن النبي ﷺ بعد الصلاة، وبعد التسبيح، والذكر لا تجده يرفع يديه، يدعو والناس يؤمنون، وما كان يقرأ الفاتحة والناس يؤمنون، ولو كان هذا واقعًا لنقله الصحابة  فإنهم نقلوا كل شيء وهم أمناء. فالحاصل: أن هذا بدعة، كون الإمام بعد صلاة الفريضة، أو بعد التكبير يرفع يديه، ويدعو وهم يؤمنون، أو يقرأ الفاتحة ويدعو وهم يؤمنون، هذا ليس له أصل، بل هو بدعة، بل إذا فرغ الإنسان من الذكر يصلي السنة الراتبة التي بعد الظهر، أو بعد المغرب، أو بعد العشاء، أو يتوجه إلى بيته -وهو أفضل- ويصلي النوافل في بيته، وأما عن العمل كونه يرفع يديه بعد الفريضة الإمام، أو المأموم، أو كلاهما يرفعون ذلك للدعاء، هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16390/حكم-الدعاء-بعد-الفريضة-وتامين-المامومين-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72512.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":17491,"question":"يقول: يوجد لدينا في كل ليلة من يوم الخميس، ويوم الإثنين يذكر الله أهل الطرق الصوفية بالطبول إلى ساعات متأخرة من الليل، هل الذكر بالطبل جائز وهل الطرق الصوفية هذه جائزة أم لا؟ جزاكم الله خيرًا.","title":"حكم ذكر الله بالطبل، وحكم الطرق الصوفية","answer":"الجواب: هذه الطرق الصوفية بدعة ومنكرة سواء كان على الطبول أو الدفوف أو العود أو الموسيقى أو التصفيق بالأيدي أو الضرب بالأرجل أو الرقص، التقرب بهذا الأمر هذا من البدع، سواء في ليلة الخميس أو ليلة الإثنين أو في غيرهما في أي وقت، فالواجب على أهل الإسلام التقرب بالقرب التي شرعها الله، التسبيح والتهليل والتحميد والذكر والاستغفار على غير هذا الصنف بغير الطبول وبغير ضرب الأرجل وبغير الصياح والصفير، وبغير الموسيقى والعود وغيره.\nوقد بسط العلامة ابن القيم رحمه الله هذا البحث في كتابه إغاثة اللهفان بسطًا جيدًا، فأنا أنصح بمراجعة إغاثة اللهفان الذي بسط فيها الكلام، على الطرق الصوفية والتحذير منها وهذا منها.\nفالسنة للمؤمن أن يفعل ما فعله النبي ﷺ، إذا فرغ من الصلاة يذكر الله كما فعل النبي ﷺ إذا سلم يستغفر الله ثلاثًا، ويقول: اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، ثم ينصرف إلى الناس إذا كان إمامًا، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كان يفعل هذا بعد كل صلاة عليه الصلاة والسلام، كما روى هذا ابن الزبير في صحيح مسلم، وروى بعضه المغيرة بن شعبة في الصحيحين بعد كل صلاة. والاستغفار ثلاثًا مع قوله: اللهم أنت السلام.. رواه مسلم في صحيحه عن ثوبان ، وروى بعضه مسلم عن عائشة في: اللهم أنت السلام .. ثم ينصرف الإمام إلى الناس هذه السنة.\nثم بعد هذا يقول: سبحان الله والحمد لله والله أكبر ثلاثًا وثلاثين، ويختم المائة بقوله:  لا إله إلا الله، وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، صح هذا عن النبي ﷺ أنه قال: من فعل هذا غفرت له خطاياه وإن كانت مثل زبد البحر، وهذا فضل عظيم، فيستحب للمؤمن بعد الصلوات الخمس أن يأتي بهذا. بعد الأذكار السابقة، تقول: سبحان الله، والحمد لله، والله أكبر ثلاثة وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، وإن شاء قال: يحيي ويميت بيده الخير وهو على كل شيء قدير، كله جاء. ثم يقرآ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ إلى آخرها ..إلى قوله: ..وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]، هذه الآية أعظم آية يستحب أن تقرأ بعد كل صلاة فريضة ثم يقرأ قل هو الله أحد والمعوذتين بعد كل فريضة، بعد الظهر والعصر والمغرب والعشاء والفجر أفضل، لكن يكررها ثلاثًا، هذه السور الثلاث يقرأها ثلاث مرات بعد المغرب، وبعد الفجر وعند النوم، جاءت بذلك السنة عن النبي عليه الصلاة والسلام .... وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16398/حكم-ذكر-الله-بالطبل-وحكم-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72513.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":17492,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من سلطنة عمان، باعثها أحد الإخوة المستمعين، يقول: (ح. س. م)، أخونا له رسالة ضمنها ثمان قضايا، في إحداها يقول: قد نعيش ظاهرةً غريبة بعد دفن الميت، وهي ظاهرة تلقين الميت بعد أن يدفن، حيث يقوم الخطيب، أو الإمام بقراءة بعضٍ من آيات الذكر الحكيم، ثم يتلوها بوصية للميت، ومن بين الكلام الذي يخطب به الميت، يقول: يا عبد الله، لا تنس العهد الذي بيننا وبينك، والذي عشت عليه، إن دينك الإسلام، ونبيك محمد ﷺ، ولا تجزع من الملكين، فهم عباد الله.. إلى آخر مثل ذلك،  هل ذلك ورد عنه ﷺ أو عن صحابته؟ أرجو من سماحتكم توضيح ذلك، مع ذكر الدليل من السنة إن ورد عن رسول الله ﷺ؟ جزاكم الله خيرًا.","title":"حكم تلقين الميت بعد دفنه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد:\nفالتلقين للميت بعد الدفن لم يثبت عن النبي ﷺ، ولا عن أصحابه ، وإنما ورد في حديثٍ موضوع، رواه الطبراني من حديث أبي أمامة الباهلي، وهو ليس بثابت، وليس بصحيح، بل هو موضوع، ويروى عن جماعة من أهل الشام فعل ذلك، والصواب أنه بدعة، لا يشرع، والميت على ما مات عليه، وإنما التلقين قبل خروج الروح، يقول النبي ﷺ: لقنوا موتاكم: لا إله إلا الله، يعني: المحتضرين، يلقن قبل أن يموت هذه الكلمة العظيمة، وهي: (لا إله إلا الله)؛ لأنه ﷺ قال: من كان آخر كلامه:لا إله إلا الله، دخل الجنة فإذا قالها عن صدق، وعن إخلاص، وإيمان بما دلت عليه من توحيد الله والإخلاص له، والبراءة من الشرك وأهله، فإن الله جل وعلا يجعل ذلك من أسباب نجاته وسعادته، إذا لم يكن مصرًا على شيء من الكبائر، وإلا فهو تحت مشيئة الله، من مات على المعاصي فهو تحت مشيئة الله، إن شاء غفر له، وإن شاء عذبه على قدر المعاصي التي مات عليها. ثم بعد التطهير في النار يخرجه الله من النار إلى الجنة إذا كان مات على التوحيد، عند أهل السنة والجماعة، هذا هو الحق، خلافًا للمعتزلة ومن سار على نهجهم، وخلافًا للخوارج؛ فإنهم يقولون: إنه مخلدٌ في النار -العاصي- والخوارج تكفره بذلك، والذي عليه أهل السنة والجماعة وهم أصحاب النبي ﷺ وأتباعهم بإحسان، أن من مات على التوحيد وعنده معاصي لا يكفر عندهم، ولا يخلد في النار إن دخل النار، بل هو تحت مشيئة الله، إن شاء الله جل وعلا غفر له، وعفا عنه بتوحيده، وإيمانه، وأعماله الصالحة، وإن شاء سبحانه عذبه على قدر المعاصي التي مات عليها من الكبائر، من الزنا، أو السرقة، أو عقوق الوالدين، أو قطيعة الرحم، أو أكل الربا، أو نحو ذلك من الكبائر، لقول الله  في كتابه العظيم في آيتين من سورة النساء، يقول سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فأخبر سبحانه أنه لا يغفر لمن مات على الشرك، وأنه يغفر ما دون ذلك لما دون الشرك، لمن يشاء، فدل ذلك على أنه ليس بكافر؛ لأن العاصي الذي مات على شيء من الكبائر ليس بكافر، إذا مات موحدًا مسلمًا، فإذا مات على الزنا، ما تاب من الزنا، أو عقوق الوالدين، أو أحدهما، أو أكل الربا، لم يتب، ولم يستحل ذلك، فهو تحت مشيئة الله، وهكذا صاحب الغيبة والنميمة، وما أشبهه من المعاصي، هو تحت مشيئة الله ، عند أهل الحق، عند أهل السنة والجماعة، خلافًا للخوارج والمعتزلة، ومن سار على نهجهم، للآية الكريمة ولأنه ثبت بالتواتر، عن النبي ﷺ أنه يشفع يوم القيامة لمن دخل النار من المسلمين وهو على التوحيد، فيحد الله له حدًا، فيخرجه من النار، ثم يشفع، ثم يشفع، ثم يشفع، كلما شفع حد الله له حدًا فأخرجه من النار. وهكذا يشفع النبيون، والملائكة، والمؤمنون، والأفراط، ويبقى بقية من أهل التوحيد في النار، يخرجهم الله سبحانه من النار، بفضل رحمته جل وعلا، بعدما جرى تعذيبهم فيها المدة التي شاءها الله ، هذا هو الحق الذي لا ريب فيه، وهو الذي عليه أهل السنة والجماعة من أصحاب النبي ﷺ ومن بعدهم.\nأما التلقين بعد الدفن، هو بدعة، كونه يقف عند القبر عند رأسه ويقول: اذكر كذا.. اذكر كذا هذا لا أصل له في الشرع، وإنما هو من فعل بعض العلماء، ولم يفعله النبي ﷺ ولا أصحابه رضي الله عنهم وأرضاهم. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16402/حكم-تلقين-الميت-بعد-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72601.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":17497,"question":"هذا سائل للبرنامج يستفسر عن مجموعة من الأحاديث يقول: هل ورد حديث عن النبي ﷺ أو عن السلف الصالح بأن الرسول ﷺ كان يحب أن يقرأ سورة إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ[القدر:1] عشر مرات بعد الانتهاء من الوضوء؟","title":"حكم قراءة سورة القدر بعد الوضوء","answer":"الجواب: ليس لهذا أصل لا عن الرسول ﷺ ولا عن الصحابة، هذا باطل. نعم.","link":"https://binbaz.org.sa/fatwas/16410/حكم-قراءة-سورة-القدر-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77403.mp3","categories":["البدع والمحدثات"]},{"id":17498,"question":"يقول: في ليلة العيد والجمعة يؤتى بطعامٍ من كل بيت في المسجد، أو في وسط القرية، يأكلونه، وبعد ذلك يقرأ الإمام من آيات القرآن الكريم، ويختم بالدعاء بطلب الرحمة والمغفرة للأموات، اعتقادًا منهم أن بركة الطعام تصل إلى الأموات، وهذه الوليمة تسمى: الفاتحة، أو الفواتح، والأسئلة حول هذا الموضوع: هل هذه الفاتحة تنفع الميت، وهل تسمى صدقة عندما يأكلها الغني؟ ثم ما هو العمل الذي يجب على أهل الميت القيام به نحو فقيدهم، والذي يصل إليه العمل الصالح؟ جزاكم الله خيرًا.","title":"ما يصل إلى الميت وما لا يصل من القُرَب","answer":"الجواب: هذا الاجتماع على الميت المذكور لا أعلم له أصلًا في الشرع، بل هو من البدع، والرسول عليه السلام يقول: من عمل عملًا ليس عليه أمرنا، فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد. أما الدعاء للأموات، والصدقة عنهم، هذا ينفعهم، الصدقة تنفع الميت، والدعاء ينفع الميت، صلاة الجنازة، الحج عن الميت، والعمرة عن الميت، قضاء دينه، كل هذا ينفع الميت.\nأما القراءة ... قراءة الفاتحة وغير الفاتحة فهذا ليس عليه دليل، وقد ذكر ابن القيم رحمه الله وغيره عن بعض العلماء؛ أنه لا بأس بالقراءة للميت، أنه يقرأ له يثوب له القرآن، ذكر هذا جماعةٌ من أهل العلم، ذكره ابن القيم في كتاب الروح، ولكن لا أعلم عليه دليلًا، تثويب القراءة كونه يقرأ ويثوبه للميت، لا أعلم عليه دليلًا، فتركه أحوط، وأولى، ولكن الدعاء ليس فيه خلاف، الدعاء للميت، الترحم عليه، الدعاء له بالمغفرة، هذا أمر معلوم، متفق عليه بين المسلمين، أنه ينفع الميت، وهكذا الصدقة عنه تنفع الميت. ثبت عن النبي ﷺ أنه سأله رجلٌ، وقال: يا رسول الله! إن أمي ماتت، وأظنها لو تكلمت تصدقت، فهل لها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. فالصدقة تنفع الميت، والدعاء له، وصلاة الجنازة تنفعه، دعاء المسلمين له ينفعه، الحج عنه، العمرة، قضاء الدين، كل هذا أمر معروف.\nأما كونه يقرأ ويثوب له، هذا هو محل النزاع، ولا أعلم دليلًا شرعيًا على استحباب ذلك، وشرعيته، والأصل في العبادة التوقيف، هذا هو الأصل، إلا ما شرعه الله على لسان رسوله عليه الصلاة والسلام، فالأحوط في هذا ترك القراءة للميت، ولكن يدعى له، يترحم عليه، يتصدق عنه، يحج عنه، يعتمر عنه، كل هذا طيب، كله نافع. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16405/ما-يصل-الى-الميت-وما-لا-يصل-من-القرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72602.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":17507,"question":"في آخر أسئلة هذا السائل من ليبيا يقول: أسأل عن ختمة القرآن والتي تعمل للشخص المتوفى من قبل أهله ويعتبرونها صدقة وهي: عبارة عن مجموعة من القراء يختمون القرآن وبعدها يتناولون الطعام - طعام الغداء - وهي ولا شك بأنها صدقة، ويمكن أن يحضرها أي شخص، ما حكم ذلك مأجورين؟","title":"حكم إهداء ختمة القرآن للموتى","answer":"الشيخ: لا أعلم لهذا أصلًا، ختامة القرآن فلان أو فلان لا أعلم له أصلًا، بعض أهل العلم يجيز ذلك لكن لا أعلم له أصلًا، الرسول يقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد، كونه يجتمعون للقراءة لفلان أو لفلان هذا لا أعلم له أصلًا، الإنسان يقرأ لنفسه يطلب الثواب من الله لنفسه، يقرأ القرآن أو اثنين يتدارسون أو ثلاثة يتدارسون لا بأس يطلبوا الثواب من الله جل وعلا، ما هو من أجل فلان أو فلان أو قراءة لفلان، النبي كان يدارس جبرائيل عليه الصلاة والسلام في رمضان كل ليلة.\nفالحاصل: أن المدارسة لا بأس بها، أما اجتماعهم ليقرءوا ختمة لفلان أو فلان هذا ما أعلم له أصلًا في الشرع فالواجب تركه.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16428/حكم-اهداء-ختمة-القران-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77413.mp3","categories":["البدع والمحدثات"]},{"id":17511,"question":"يقول: لدينا عادة إذا دخل الرجل على مخطوبته ليلة الدخلة يقرأ سورة يس، فهل هذا العمل صحيح؟","title":"حكم قراءة سورة يس ليلة الزفاف","answer":"الجواب: لا أعلم له صحة، أقول: لا أعلم له أصلًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16453/حكم-قراءة-سورة-يس-ليلة-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83709.mp3","categories":["البدع والمحدثات"]},{"id":17517,"question":"وأخيرًا يسأل يقول: هل الأفضل أثناء الدعاء في كل وقت غير الاستسقاء، هل الأفضل رفع الأيادي أم عدم رفعها؟","title":"ما حكم رفع اليدين في دعاء الاستسقاء وغيره","answer":"الجواب: الأفضل رفع الأيدي في الدعاء، هذا هو الأفضل، لأنه من أسباب الإجابة، إلا في حالات ما رفع فيها النبي ﷺ فإنا لا نرفع فيها، وما عداها نرفع في المواضع التي رفع فيها ﷺ كصلاة الاستسقاء خطبة الاستسقاء وفي المواضع التي ندعو فيها نرفع أيدينا، لكن المواضع التي ما رفع فيها ﷺ مثل صلاة الفريضة ما أعلم ما رفع فيها بين السجدتين ولا قبل السلام ولا بعد السلام، لو فعله لنقل، لو فعله لنقله الصحابة؛ فإنهم ما تركوا شيئًا  إلا نقلوه، فلما لم ينقلوا أنه كان يرفع يديه بعد الفريضة دل على أنه لا يشرع، وكذلك في خطبة الجمعة ما كان يرفع يديه في خطبة الجمعة ولا في خطبة العيد عليه الصلاة والسلام، فنحن لا نرفع إلا إذا استسقينا في خطبة الجمعة والعيد نرفع أيدينا للاستسقاء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16444/ما-حكم-رفع-اليدين-في-دعاء-الاستسقاء-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83706.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":17523,"question":"أيضًا يسأل أخونا عن كيفية صلاة الاستسقاء؟","title":"صفة صلاة الاستسقاء","answer":"الجواب: صلاة الاستسقاء مثل صلاة العيد، يصلي ركعتين يكبر في الأولى سبعًا وفي الآخرة خمسًا، يكبر تكبيرة الإحرام وستًا بعدها، ثم يستفتح، ثم يقرأ الفاتحة وما تيسر معها، ثم يركع ثم يرفع ثم يسجد سجدتين، ثم يقوم إلى الثانية فيصليها مثل صلاة العيد، يكبر خمس تكبيرات إذا اعتدل ثم يقرأ الفاتحة وما تيسر معها، ثم يقرأ التحيات ويصلي على النبي ﷺ ثم يدعو ثم يسلم، مثل صلاة العيد، النبي صلاها كما كان يصلي في العيد عليه الصلاة والسلام. ثم يقوم فيخطب الناس خطبة يعظهم فيها ويذكرهم، ويحذرهم من أسباب القحط، يحذرهم من المعاصي؛ لأنها أسباب القحط وأسباب حبس المطر وأسباب العقوبات؛ فيحذر الناس من أسباب العقوبات من المعاصي والشرور وأكل أموال الناس بالباطل والظلم وغير ذلك من المعاصي، ويحثهم على التوبة والاستغفار ويقرأ عليهم الآيات الواردة في ذلك والأحاديث. ثم يدعو ربه رافعًا يديه، ويرفع الناس أيديهم يدعون، يسأل ربه الغوث، من ذلك اللهم أغثنا، اللهم أغثنا، اللهم أغثنا ثلاث مرات، اللهم اسقنا غيثًا مغيثًا هنيئًا مريئًا غدقًا مجلًا سحًا طبقًا عامًا نافعًا غير ضار، تحيي به البلاد وتغيث به العباد وتجعله يا رب بلاغًا للحاضر والباد، هذا من الدعاء الذي دعا به النبي ﷺ: اللهم أنبت لنا الزرع، وأدر لنا الضرع، واسقنا من بركاتك، ويلح في الدعاء ويكرر في الدعاء: اللهم اسقنا الغيث ولا تجعلنا من القانطين، مثلما فعل النبي ﷺ. ثم يستقبل القبلة في أثناء الدعاء، يستقبل القبلة وهو رافع يديه يكمل بينه وبين ربه وهو رافع يديه ثم ينزل، والناس كذلك يرفعون أيديهم ويدعون مع إمامهم، وإذا استقبل القبلة كذلك هم يدعون معه .... بينهم وبين أنفسهم ويرفعون أيديهم. والسنة أن يحول رداءه في أثناء الخطبة عندما يستقبل القبلة يحول رداءه تجعل ما على الأيمن على الأيسر إذا كان عليه رداء أو بشت إن كان عليه بشت يقلبه، وإن كان ما عليه شيء كالغترة يقلبها، قال العلماء: تفاؤل بأن الله يحول القحط إلى كسب.. يحول الشدة إلى الرخاء؛ لأنه جاء في حديث مرسل عن محمد بن علي الباقر \"أن النبي ﷺ حول رداءه ليتحول القحط\"، يعني: تفاؤل. وقد ثبت في الصحيحين من حديث عبد الله بن زيد \"أن النبي ﷺ حول رداءه لما خرج .. لما صلى بهم صلاة الاستسقاء\"، والسنة للمسلمين كذلك. أما في خطبة الجمعة فلم يحول رداءه عليه الصلاة والسلام، دعا واستغاث وهو في خطبة الجمعة في ضمن دعائه عليه الصلاة والسلام، والاستغاثة تكون في خطبة الجمعة وتكون في خطبة العيد وتكون في غير ذلك، يستسقي ولو جالسًا في البيت أو في السوق لا بأس، دعاء الاستسقاء مطلوب من الفرد والجماعة. لكن إذا صلى بهم ركعتين خرج بهم إلى الصحراء وصلى بهم ركعتين كالعيد فإنه يخطب بعد ذلك ويدعو ويحول رداءه كما فعله النبي ﷺ عند استقباله القبلة، ويجوز أن يخطب قبل ذلك قبل الصلاة ثم يصلي بعد، جاء هذا وهذا عن النبي ﷺ، جاء أنه خطب قبل الصلاة وجاء أنه خطب بعد الصلاة، وبعد الصلاة كالعيد وقبل الصلاة كالجمعة وكل هذا فعله النبي، فعل هذا وهذا عليه الصلاة والسلام، والمقصود هو الدعاء والضراعة إلى الله ورفع الشكوى إليه جل وعلا في إزالة القحط والشدة وفي إنزال المطر والغوث منه . وقد جاء في بعض الأحاديث أنه ركع ثلاث ركوعات وبعضها أربع ركوعات وبعضها خمس ركوعات، لكن الأصح والأرجح عند المحققين من أهل العلم أنه صلى ركعتين بركوعين فقط، بركوعين وقراءتين وسجدتين هذا هو الأصح، هذا هو أصح ما جاء في هذا كما تقدم، صلى ركعتين... ثم قرأ التحيات وصلى على النبي ﷺ ودعا، ثم لما سلم خطب الناس وذكرهم، وبين لهم أحكام الاستسقاء وبين لهم عقوبات الذنوب والحذر منها، وبين لهم أنه ينبغي لهم الصدقة والإحسان والإكثار من ذكر الله واستغفاره، وهكذا ينبغي لأئمته ...... والخطباء أن يذكروا الناس وينبهوهم كما فعل النبي ﷺ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16441/صفة-صلاة-الاستسقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83704.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":17567,"question":"يقول السائل: يا سماحة الشيخ! هل يجوز التلفظ بالنية للصلاة، وإن لم تكن كذلك فكيف تكون؟","title":"هل يجوز التلفظ بالنية للصلاة؟","answer":"الجواب: النية تكون بالقلب، ينوي بـقلبه الظهر العصر المغرب، ولا يشرع التلفظ بالنية، لا يقول: نويت أن أصلي كذا، لا يجوز هذا هذا بدعة، ولكن بقلبه ينوي بقلبه الظهر العصر المغرب سنة الضحى سنة الراتبة الوتر بالنية بالقلب، الأعمال بالنيات، ومحلها القلب.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16488/هل-يجوز-التلفظ-بالنية-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59406.mp3","categories":["البدع والمحدثات"]},{"id":17568,"question":"يقول: يقوم بعض الناس في مناطقنا، وخاصةً في شهر رمضان المبارك بتأجير قارئٍ يقرأ القرآن عن الأموات، مقابل عشرة ريالات عمانية للختمة الواحدة، هل تجوز المتاجرة بكلام الله ؟ وهل هذا المبلغ حلال؟ وما نصيحتكم لمن يقومون بذلك إن كان هذا الأمر مخالفًا للدين الحنيف؟ نرجو توضيح ذلك، فنحن قد وقعنا في الشبهات؟ ثم هل ذلك ينفع الميت؟ حيث أن البعض يستند إلى الحادثة التي صادفها الرسول ﷺ عندما مر بقبرين وهما يعذبان.ثالثًا: هل قراءة القرآن على الأموات من قبل ذويهم تنفعهم؟ حيث أن ذلك شائعٌ عندنا، خاصةً بعد ثلاثة أيامٍ من دفن الميت، إضافةً إلى ذبح الذبائح بعد موته، يتحول ذلك البيت إلى مناسبة عرس، تنعدم فيه الخشية، والعبرة، أنقذونا من البدع أثابكم الله، فإن مجتمعنا تنص عليه الآية: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]؟","title":"حكم تأجير قارئٍ يقرأ القرآن عن الأموات","answer":"الجواب: سبق الكلام في القراءة للميت، وأنه لا دليل على القراءة للأموات، وأما كونه يستأجر إنسان يتلو آيات، يستأجر حتى يتلو للميت، هذا لا أصل له، ولا يجوز، ولا تحل هذه الأجرة، قد حكى العلماء، حكى بعض أهل العلم الإجماع على تحريم ذلك، كشيخ الإسلام ابن تيمية رحمه الله ذكر الإجماع على أنه لا تجوز أخذ الأجرة على تلاوة القرآن، وأنه محرم بلا نزاع، كونه يقرأ ثمن، أو ثمنين، أو جزء، أو أكثر، أو أقل بمال، يقرأ للأموات، أو لأي سبب، لا يجوز هذا، وإنما تؤخذ الأجرة في التعليم، إن كان يعلم الأولاد، يعلم الناس، يعطى أجرة على التعليم، أما كونه يقرأ آيات، ويأخذ أجرة على هذه الآيات ليسمعها الناس منه، أو أنه يثوبها للميت، هذا لا أصل له، بل حكى مثلما تقدم شيخ الإسلام ابن تيمية الإجماع، وأنه لا نزاع في تحريم ذلك، أخذ الأجرة على مجرد التلاوة.\nأما كونه المعلم يعطى حتى يعلم الأولاد، حتى يعلم الناس القرآن؛ لا بأس بهذا، لقوله ﷺ: إن أحق ما أخذتم عليه أجرًا؛ كتاب الله، يعني: التعليم، والتوجيه، تعليم القرآن للناس؛ لا بأس أن يؤخذ عليه أجرة.\nأما كون أهل الميت يقيمون ذبائح، ولائم بعد الموت، يوم الموت، أو يوم ثالث، أو يوم عاشر، أو على رأس الشهر، أو رأس الأربعين، أو رأس السنة، هذا بدعة، لا يجوز هذا، ولكن يتصدقوا عن الميت، طعام يوزعوه على الفقراء، نيئًا أو مطبوخًا، يوزع على الفقراء، رز....... لا بأس، أم كونهم يصنعون طعام للناس، من شان المأكل، من شان الميت، أو يدعون الناس إليه ليقيمون ولائم، هذا بدعة. أما إذا أحبوا أن يتصدقوا بدراهم، أو بغيرها، في أي وقت، على الفقراء على الميت، هذا ينفع الميت، الصدقة تنفع الميت، هذا خيرٌ عظيم.\nفرقٌ بين الصدقة على الفقراء، والمساكين، وفرقٌ بين إقامة المآتم، كون جمع الناس يأكلون في بيت الميت، ويذبحون لهم الذبائح، هذا لا أصل له، والسنة أن يدفع لهم طعام -أهل الميت، جيرانهم.. أقاربهم، يصنعون لهم طعام، لما ثبت في الحديث أنه ﷺ لما أتى نعي جعفر بن أبي طالب ، يوم مؤتة، حين قتل هناك، لما جاء خبره  إلى المدينة، أمر النبي ﷺ أهله أن يصنعوا طعامًا لأهل جعفر، وقال: إنه أتاهم ما يشغلهم فإذا صنع الجيران، أو الأقارب، طعامًا لأهل الميت؛ لأنهم مشغولون بالمصيبة، هذا مستحب.\nأما كونه هم أهل الميت يصنعون للناس، يدعون الناس، هذا غير مشروع، وإذا جاءهم الطعام من جيرانهم، دعوا عليهم أن يأكلوا؛ لا بأس، جاءهم طعام كثير يزيد على حاجتهم، دعوا جيرانهم، دعوا من يأكل معهم؛ هذا لا بأس به. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16490/حكم-تاجير-قارى-يقرا-القران-عن-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72604.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":17668,"question":"الأخت تقول: سماحة الشيخ! كيف نفرق بين البدعة والاجتهاد في العبادة، من سن سنةً حسنةً فله أجرها وأجر من عمل بها إلى يوم القيامة أو كما قال ﷺ؟","title":"التفريق بين البدعة والاجتهاد في العبادة","answer":"الجواب: البدعة هي إحداث شيء في الدين ما شرعه الله كما قال ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد هذه البدعة، أما الاجتهاد في العبادة والحرص على إكمالها وإتمامها هذا ما هو ببدعة، الاجتهاد في إكمال الصلاة في إكمال الصيام في التحرز مما ينقص من ثواب الصلاة والصيام هذا ليس ببدعة، وأما قوله ﷺ: من سن في الإسلام سنة حسنة يعني: أحياها وأظهرها للناس، ما هو معنها: ابتدع، معناها أحيا السنة وبينها للناس. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16599/التفريق-بين-البدعة-والاجتهاد-في-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59433.mp3","categories":["البدع والمحدثات"]},{"id":17680,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ! في شهر رجب تكثر البدع هل من كلمة من سماحتكم للذين يحدثون بدع وعبادات في هذا الشهر أعني شهر رجب؟","title":"توجيه عما يحدث في رجب من بدع وعبادات","answer":"الجواب: شهر رجب ليس له سنن، لكن لا بأس بالعمرة فيه، من اعتمر في رجب فقد كان السلف يعتمرون في رجب، وثبت عن ابن عمر رضي الله عنهما «أن النبي ﷺ اعتمر في رجب»، فالعمرة في رجب لا بأس بها. أما تخصيصه بعبادات أخرى فلا أصل لذلك ولكن كسائر الشهور، إذا صلى فيه أو صام منه ثلاثة أيام من كل شهر أو صام الإثنين والخميس مثل بقية الشهور لا يخص بشيء. نعم، إلا إذا اعتمر فيه فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16613/توجيه-عما-يحدث-في-رجب-من-بدع-وعبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59509.mp3","categories":["البدع والمحدثات"]},{"id":17715,"question":"هذا السائل من جمهورية مصر العربية أبو أسامة له مجموعة من الأسئلة يقول: ما هي البدعة؟ وما هي أقسامها؟ وهل يجوز أن أصلي خلف إمام مبتدع عنده بعض البدع؟","title":"معنى البدعة وحكم الصلاة خلف صاحبها","answer":"الجواب: البدعة هي العبادة المحدثة التي ما جاء بها الشرع يقال لها: بدعة، وكل البدع ضلالة ما فيها أقسام، كلها ضلالة، لقول النبي ﷺ: كل محدثة بدعة وكل بدعة ضلالة وكان يقول هذا في خطبه، يقول ﷺ: أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها ويقول: كل بدعة ضلالة، ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد، ويقول ﷺ: «من عمل عملاً ليس عليه أمرنا فهو رد. فالبدعة ما أحدثه الناس في الدين من العبادات التي لا أساس لها يقال لها بدعة، وكلها منكرة وكلها ممنوعة.\nأما تقسيم بعض الناس البدعة إلى: واجبة، ومحرمة، ومكروهة، ومستحبة، ومباحة.\nهذا تقسيم غير صحيح، الصواب أن البدع كلها ضلالة كما قاله النبي ﷺ. نعم.\nالمقدم: أحسن الله إليكم، يقول: صلاتنا خلف هذا الإمام المبتدع؟\nالشيخ: إذا كانت بدعة مكفرة لا يصلى خلفه كبدعة الجهمية و المعتزلة وأشباههم، أما إذا كانت بدعة غير مكفرة كرفع الصوت بالنية: نويت أن أصلي، أو ما أشبه ذلك فلا بأس لكن يعلم يوجه إلى الخير، ويعلم لا يرفع صوته بل ينوي بقلبه، والحمد لله نية القلب تكفي، وهكذا بدعة الاجتماع للموالد إذا كان ما فيها شرك هذه غير مكفرة، أما إن كان فيها دعاء النبي ﷺ، أو دعاء صاحب المولد أو الاستغاثة به سواء مولد علي أو مولد الحسن أو الحسين أو النبي ﷺ أو فاطمة إذا كان فيه دعاء لصاحب المولد أو استغاثة أو نذر له أو ذبح له هذا شركًا أكبر، أما إذا كان مجرد الاجتماع لقراءة القرآن أو أكل الطعام هذه بدعة صاحبها لا يكفر. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16674/معنى-البدعة-وحكم-الصلاة-خلف-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77621.mp3","categories":["البدع والمحدثات","صلاة الجماعة"]},{"id":17769,"question":"ما حكم لبس الدبلة الذهب بالنسبة للمرأة لإعلان الخطبة ولبس الدبلة الفضة للرجل لنفس السبب؟","title":"حكم دبلة الخطوبة للرجل والمرأة","answer":"الجواب: لا أعلم لهذا أصلًا، لا أعلم لهذا أصلًا، وإذا كان في بلد اعتادوه فلا أعلم به بأسًا، أما أن ينشئه جديدًا ويسنه للناس فلا أصل له، لكن إذا أوجد في بلد واعتادوه فلا أعلم به بأسًا وإلا فالأصل ترك ذلك؛ لئلا يتشبه بأعداء الله إذا كان من أخلاق أعداء الله، أما إذا كان المسلمون فعلوه واعتادوه في أي بلد في أي قرية زالت المشابهة. نعم.\nالمقدم: أحسن الله إليكم وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16753/حكم-دبلة-الخطوبة-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77803.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":17918,"question":"يقول السائل: بعض الناس أثناء الدفن - دفن الميت - يقولون بعض الكلمات مثل: قراءة الفاتحة، وبعضهم يقول: صلوا على محمد ﷺ، نرجو توضيح السنة في هذا الأمر؟","title":"حكم قراءة الفاتحة والصلاة على النبي ﷺ أثناء دفن الميت","answer":"الجواب: هذا بدعة، كونه يقول لهم: اقرءوا الفاتحة، أو يقرأها عند الدفن هذا بدعة، وإنما يقول عند الدفن: باسم الله وعلى ملة رسول الله. أو يقول: صلوا على النبي، يرى أن هذا قربة في هذا المكان ما يصلح؛ لأن تخصيص بقعة بأن يقال فيها: صلوا على النبي أو عند عمل خاص بغير دليل يكون بدعة. أما تذكيرهم بأن يقول: اتقوا الله، تذكروا الموت، أعدوا للآخرة، النبي ﷺ ذكر أصحابه عند الدفن وهو جالس عند القبر قبل أن يلحد جاء في حديث البراء بن عازب وحديث علي أنه كان جالس عند القبر قبل أن يلحد ينتظر لحده وكان يعظهم ويذكرهم عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/16948/حكم-قراءة-الفاتحة-والصلاة-على-النبي-ﷺ-اثناء-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78012.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":18030,"question":"تسأل أختنا من السودان فتقول: الإحداد في مجتمعنا السوداني:أولاً: لزوم المرأة المعتدة، وافتراشها للأرض طوال المدة المقررة لها.ثانيًا: مواجهة حائط الغرفة.ثالثًا: امتناعها عن الكلام، وخاصة عند شروق الشمس وعند الغروب، في فترة يطلق عليها النساء زمن الحضانة.رابعًا: امتناعها عن الاستحمام وغسل الثياب.فهل هذا من الدين في شيء، ونسبة لكثرة النساء اللائي يتقيدن بهذه الظاهرة؟ أرجو من سماحة الشيخ أن يوجه الجميع، جزاكم الله خيرًا.","title":"من بدع الإحداد المخالفة للشرع","answer":"الجواب: كل هذا لا أصل له في الشرع، الواجب امتثال الشرع، والتقيد بالشرع المطهر، فالمحادة عليها أن تبقى في البيت الذي مات زوجها وهي ساكنة فيه، تبقى المدة أربعة أشهر وعشرًا، إن كانت غير حبلى، أما إن كانت حبلى؛ فإنها تبقى العدة، حتى تضع الحمل، والواجب عليها ترك الطيب والحلي والملابس الجميلة والكحل والحناء، هذه الأشياء التي ترغب فيها وتجعلها محل نظر، هذه يجب تركها، كما جاءت بذلك الأحاديث عن رسول الله عليه الصلاة والسلام. أما ما ذكرته السائلة من كونها تفترش الأرض، ولا تجلس على بساط، هذا لا أصل له، هذا باطل وهذا تعنت وتكلف، كذلك استقبالها الحائط، هذا غلط -أيضًا- تستقبل ما شاءت مثل غيرها من النساء، كذلك كونها -أيش الثالث؟ المقدم: كونها تمتنع عن كلام الناس. الشيخ: كذلك امتناعها عن كلام الناس، هذا غلط -أيضًا- تكلم من شاءت مثل غيرها من النساء، تكلم أقاربها .. تكلم أولادها .. تكلم جيرانها .. تكلم من استأذن عليها بالكلام الذي ليس فيه محذور، لكن لا تخلو بأحد من الرجال مثل غيرها من النساء، أما الكلام فلا بأس مع محارمها وغيرهم في مصالحها وشئونها، على وجه لا ريبة فيه. نعم. الرابع. المقدم: كونها تلتزم الصمت -أيضًا- عند الشروق وعند الغروب في فترة يسمونها الحضانة؟ الشيخ: كذلك هذا باطل، ليس عليها التزام الصمت عند الشروق والغروب، بل تكلم في جميع النهار، وفي جميع الليل، هذه الأشياء الأربعة كلها لا أصل لها ولا أساس لها، بل يجب على المسلمة تجنب ذلك، وأن لا تخضع للبدع والخرافات التي أحدثها الناس، وإنما عليها ما أمرها به الشارع عليه الصلاة والسلام من تجنب الملابس الجميلة، ومن ترك الطيب والحلي؛ لأنها تلفت النظر، وتسبب رغبة الرجال فيها، وهكذا ليس لها أن تكحل عينيها، ولا أن تستعمل الحناء؛ لأن هذا يسبب الفتنة بها، مع بقائها في بيت زوجها إذا تيسر ذلك الذي مات زوجها وهي ساكنة فيه، إذا تيسر، أما إذا خرب البيت أو كان مستأجرًا ولم يسمح أن يقوم بتأجيره، أو كانت وحدها تستوحش، ما عندها من يؤنسها تنتقل إلى بيت أهلها، كل هذا لا بأس به، نسأل الله للجميع التوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا. نقطة مهمة سماحة الشيخ لو تكرمتم، كونها تمتنع عن الاستحمام وغسل الثياب؟ الشيخ: كذلك هذا أيضًا غلط، لها أن تستحم متى شاءت من ليل أو نهار، في أي يوم، يوم الجمعة وفي غيره، ولها أن تمتشط متى شاءت، لكن من دون طيب، ولها أن تغسل الثياب: ثيابها أو ثياب أولادها، كل هذا لا بأس به، كل هذا التكلف لا أصل له، نعوذ بالله من طاعة الشيطان. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17058/من-بدع-الاحداد-المخالفة-للشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59906.mp3","categories":["العِدَد","البدع والمحدثات"]},{"id":18055,"question":"هذا سؤال من المستمع محمد مختار أحمد من السودان، يقول: عندنا بعض العادات في العزاء؛ ومنها: أن يرفع الناس أيديهم لأهل الميت، ويقولون: الفاتحة، ويقرؤون سورة الفاتحة، فهل هذا جائز أم لا؟","title":"حكم قراءة سورة الفاتحة في العزاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالمشروع في العزاء هو الدعاء لأهل الميت بالتوفيق بالصبر والاحتساب وعظيم الأجر وغفران الذنوب للميت، أما رفع الأيدي إليهم وقراءة الفاتحة فليس له أصل. رفع الأيدي ما ندري ما مراده؛ فإن كان المراد به المصافحة عند اللقاء فهذا لا بأس به، هذا مشروع كونه يصافح المعزى إذا كان رجل أو كانت امرأة ذات محرم له كخالته وعمته وأمه ونحو ذلك، فلا بأس أن يصافح المعزى، ويقول: أعظم الله أجرك وأحسن عزاءك وغفر لميتك وجبر مصيبتك. هذا كله طيب، يقال هذا للرجل والمرأة جميعًا، فيصافح الرجل ويصافح المرأة إذا كانت محرمًا له كأخته وعمته وخالته. أما النساء غير المحارم فلا يصافحن، وما يفعله بعض الناس من مصافحة النساء غلط لا يجوز، يقول النبي ﷺ: إني لا أصافح النساءوتقول عائشة رضي الله عنها: «ما مست يد رسول الله يد امرأة قط - يعني: في البيعة- قالت: ما كان يبايعهن إلا بالكلام». فهذا يدلنا على أن المرأة الأجنبية ليس للرجل أن يصافحها، ولكن لا بأس بمصافحة المرأة ذات المحرم كأمه وجدته وخالته وعمته ونحو ذلك، عند العزاء وعند اللقاء لا بأس في ذلك عند المقابلة إذا قابل خالته أو عمته إذا زارها صافحها ودعا لها، أو عند العزاء صافحها ودعا لها، وهكذا إذا قابل الرجل عند اللقاء في الطريق أو زاره في البيت وصافحه كل هذا طيب، وهكذا عند العزاء يصافحه ويدعو له. أما إن كان رفع أيدي على غير هذه الطريق رفع أيدي إلى السماء من غير مصافحة هذا لا أصل له.\nوهكذا قراءة الفاتحة عند لقاء المعزى ليس له أصل بل هو من البدع. نعم. المقدم: كذلك يقول: إنهم يجتمعون ويقرؤون الكتاب على أساس أن ثوابه يمشي للميت، وأيضًا عندما يمرون بالمقابر يرفعون أيديهم ويقرؤون سورة الفاتحة ترحمًا على الأموات فهل هذا جائز ؟ الشيخ: وهكذا اجتماعهم على القراءة وقت العزاء هذا كله لا أصل له إنما يعزي وينصرف يعزي ويدعو لهم وينصرف، أما اجتماعهم عند أهل الميت على قراءة القرآن، أو على قراءة أشياء أخرى، أو للأكل والشرب هذا ليس له أصل، وإنما السنة أن جيران أهل الميت أو أقاربهم يبعثون لهم طعامًا كما فعله النبي ﷺ لما جاء نعي جعفر بن أبي طالب حين قتل في مؤتة في الشام قال النبي ﷺ لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم هذا هو الأفضل وهذا هو السنة. أما كون أهل الميت يصنعون طعامًا ويجمعون الناس على القراءة أو على دعاء أو على غير ذلك فهذا ليس من السنة، قال جرير بن عبد الله البجلي : «كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن كنا نعده من النياحة» فهذا يدل على أن هذا لا يجوز ولا ينبغي وليس من المشروع بل هو خلاف المشروع .نعم. المقدم: بالنسبة لرفع أيديهم وقراءة الفاتحة فوق المقابر؟ الشيخ: كذلك عند المقابر هذا لا يجوز أيضًا وليس له أصل، لا ترفع الأيدي عند المقابر ولا يقرأ القرآن بين القبور، ولا عند زيارة المقابر ليس له أصل هذا، ولكن السنة أن يدعو للموتى ويستغفر لهم، كان النبي ﷺ إذا زار القبور دعا للأموات بالمغفرة والرحمة، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي رواية أخرى: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد يدعو لهم هكذا عليه الصلاة والسلام. فهذا يدلنا على أن السنة في زيارة القبور الدعاء للأموات والترحم عليهم، أما أنه يقرأ لهم القرآن أو يرفعوا الأيدي إلى السماء أو إلى أي إشارة فهذا شيء لا أصل له. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17089/حكم-قراءة-سورة-الفاتحة-في-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90101.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":18112,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع حسين السيد حسن من الأردن محافظة الكرك، أخونا له سؤال مطول، لكنه يناقش مناقشة علمية لو تكرمتم سماحة الشيخ فيقول: قرأت في أحد الكتب: وهو كتاب تربيتنا الروحية قال مؤلفه بعد أن ذكر الحديث الذي أخرجه الشيخان عن أبي هريرة عن رسول الله ﷺ أنه قال: إن لله ملائكة يطوفون في الطرق يلتمسون أهل الذكر فإن وجدوا قومًا يذكرون الله تعالى تنادوا هلموا إلى حاجتكم، فيحفونهم بأجنحتهم إلى السماء الدنيا، فيسألهم ربهم وهو أعلم بهم: ما يقول عبادي؟ قالوا: يقولون: يسبحونك ويكبرونك ويحمدونك ويمجدونك، فيقول: هل رأوني؟ فيقولون: لا والله ما رأوك، فيقول: كيف لو رأوني؟ فيقولون: لو رأوك كانوا أشد لك عبادة وأشد لك تحميدًا وأكثر لك تسبيحًا.. إلى آخر ما جاء في هذا الحديث الشريف.ثم عقب مؤلف هذا الكتاب على هذا الحديث بقوله: من هذا الحديث ندرك أن رسول الله ﷺ حض على الاجتماع على الذكر ورسم لنا الأصل الجامع الذي تقوم عليه حلقات الذكر من تسبيح وتهليل وتكبير وتحميد ودعاء، فلو أن مجموعة اجتمعت على سبحان الله والحمد لله ولا إله إلا الله والله أكبر وختمت جلستها بدعاء واستعاذة، فإنها تكون قد حققت سنة الاجتماع على الذكر كما وردت في الحديث والذي يناقش في سنية ذلك أي: في ثبوته في السنة يخالف الفهم البديهي لهذا الحديث. وإذا كانت سنة الاجتماع على الذكر واردة في مثل هذا الحديث الصحيح، فهناك نصوص أخرى تشير إلى مثل هذا من ذلك ما أخرجه مسلم و الترمذي و النسائي عن أبي سعيد عن معاوية  قال: خرج رسول الله ﷺ على حلقة من أصحابه فقال: ما أجلسكم؟ قالوا: جلسنا نذكر الله ونحمده على ما هدانا للإسلام ومن به علينا»، ومن ذلك ما أخرجه الطبراني في الكبير بإسناد حسن عن رسول الله ﷺ قال: ليبعثن الله أقوامًا يوم القيامة في وجوههم النور..  -وفي آخر الحديث قال: هم المتحابون في الله من قبائل شتى وبلاد شتى يجتمعون على ذكر الله يذكرونه. هل الاستدلال على الاجتماع على الذكر بهذه الصورة صحيح، وإذا كان غير ذلك، فما هو تفسير وشرح سماحتكم لهذه الأحاديث السابقة، وما هي طريقة الذكر المشروعة والمسنونة؟ جزاكم الله خيرًا.","title":"حكم الاجتماع لذكر الله","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن الاجتماع على ذكر الله وقراءة القرآن ودرس العلم الشرعي ونحو ذلك مما يفيد المتجالسين علمًا نافعًا وعملًا صالحًا وفقهًا في الدين أمر مطلوب شرعًا، وقد حث النبي ﷺ على حلق الذكر ورغب فيها عليه الصلاة والسلام، وقال عليه الصلاة والسلام: ما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه فيما بينهم إلا نزلت عليهم السكينة وغشيتهم الرحمة وحفتهم الملائكة وذكرهم الله فيمن عنده، خرجه مسلم في الصحيح، وهكذا حديث: إذا مررتم برياض الجنة فارتعوا، قيل: يا رسول الله، وما رياض الجنة؟ قال: حلق الذكر. فالأحاديث التي جاءت في هذا الباب، منها ما ذكره السائل ومنها غيرها من الأحاديث كلها تدل على فضل الاجتماع على ذكر الله وطلب العلم والتفقه في الدين والمذاكرة فيما ينفع العبد في دينه ودنياه، كل هذا أمر مطلوب شرعًا، لكن ما تفعله الصوفية من الاجتماعات الخاصة بصوت خاص وعوائد خاصة، ليس له أصل في الشرع المطهر، وأحاديث النبي ﷺ تفسر بفعله ﷺ وفعل أصحابه  وأرضاهم، فإذا كان الاجتماع مثلما ورد في الأحاديث: في طلب العلم والمذاكرة في العلم وحمد الله على ما من به من تحصيل العلم ومن الهداية للإسلام فهذا أمر مطلوب وهو الذي ينبغي للمؤمن أن يفعله مع إخوانه كالاجتماع على قراءة كتاب الله ودراسة كتاب الله العظيم أو قراءة قارئ وهم يسمعون ويتفكرون ويتدبرون، هذا أمر مطلوب شرعًا، وهكذا حلقات العلم في دراسة القرآن وتفسيره وفي دراسة الأحاديث كصحيح البخاري وصحيح مسلم إلى غير ذلك للفائدة والعلم والتفقه في الدين، كل هذا أمر مطلوب شرعًا، وبهذا تفسر الأحاديث التي ذكرها السائل وغيرها.  أما أن يجتمع الناس على ذكر بصوت واحد بصوت جماعي يرددونه كما تفعله جماعة الصوفية فهذا لا أصل له في الشرع المطهر، وإنما المشهور أن يجتمعوا للمذاكرة في العلم والبحث في العلم وتسبيح الله وتحميده وتهليله، كل يسبح ربه، كل يحمده على حسب طاقته وعلى حسب ما يتيسر له في مكانه في صفه في حلقته العلمية التي من الله عليه بها مع إخوانه يتذاكرون العلم: ما معنى هذه الآية؟ ما معنى هذا الحديث؟ ما معنى كلام العلماء في كذا وكذا، دروس علمية وحلقات علمية يستفيد بها الجالس ويستفيد بها المستمع ويستفيد منها الباحث.. هكذا كان أهل العلم في حلقات العلم يبحثون ما دلت عليه الآيات ويبحثون ما دلت عليه الأحاديث ويتذاكرون في العلم، هذا هو المطلوب وهو الذي جاءت به الأحاديث ويكون في ذلك تسبيح وتهليل وصلاة على النبي عليه الصلاة والسلام وذكر لله  وثناء عليه عند قراءة الآيات، وعند سماع الآيات وعند سماع الأحاديث عن رسول الله عليه الصلاة والسلام، مع ما في هذا من طلب علم وتفقه في الدين وتواصي بالحق والصبر عليه، هذا هو المشروع لأهل الإيمان، وهذا هو الذي فعله السلف في مساجدهم وفي بيوتهم وفي مدارسهم وفي حلقات العلم التي يقيمونها، كل ذلك مقصوده الفقه في الدين والتبصر في دين الله والتعاون على البر والتقوى والتفقه في معنى كلام الله وكلام رسوله عليه الصلاة والسلام، والتذكير بنعم الله على عباده.. وما يدخل في هذا المعنى. أما أن يكون التسبيح على الطريقة التي يفعلها بعض الصوفية بأصوات جماعية وطريقة خاصة ونظام خاص، هذا لا أصل له، نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، أفضل الأماكن لحلق الذكر يا شيخ عبد العزيز ؟ الشيخ: المساجد، المساجد هي أفضل ما يكون، وإذا فعل في البيت أو في المدرسة كل ذلك طيب. المقدم: معنى هذا أنه لابد أن تكون المساجد مفتوحة حتى يتاح للمسلمين التجمع لذكر الله ودراسة القرآن؟ الشيخ: ينبغي فتحها وتسهيل إقامة حلقات العلم فيها، وإذا كان هناك شيء يخشى عليه يكون من الحرس من يتولى ذلك، من موظفي المساجد من مؤذن أو خادم.. ونحو ذلك، يتولون حراستها عما يخشى منه. المقدم: أما أن تبقى مغلقة هكذا .... تصد الناس عن ذكر الله؟ الشيخ: ليس هذا من عمل أهل الإسلام، بل عمل أهل الإسلام على تسهيل إقامة الحلقات العلمية في المساجد والتعاون على البر والتقوى وتفقيه الجاهل وتعليمه.. إلى غير هذا من وجوه التعليم، ولاسيما حلقات القرآن وحلقات السنة للأولاد والراغبين في تحصيل العلم، نعم. المقدم: بارك الله فيكم، على هذا تتضح رسالة المسجد شيخ عبد العزيز ؟ الشيخ: نعم، نعم وبهذا تعرف جهة المسجد وتحصل كما كانت في عهد السلف الصالح وإنما يخشى الإنسان، يخشى الآن، يخشى الآن فيما حصل في المساجد من الفرش وآلات تكبير الصوت.. ونحو ذلك، فهذا يمكن يعني: تأمين ما يخشى منه بواسطة الحارس من خادم ومن مؤذن حتى لا يقع ما يحذر، نعم. المقدم: طيب.. طيب بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17148/حكم-الاجتماع-لذكر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_851/nour_85101.mp3","categories":["البدع والمحدثات"]},{"id":18151,"question":"أيضًا أختنا تسأل: في يوم المولد النبوي الشريف يتم في بعض مناطق قطرنا توزيع الطعام والحلوى على الناس إحياء لهذا اليوم العزيز، ويقولون: إن توزيع الطعام والحلوى وبالأخص الحلوى لها أجر كبير عند الله ، هل هذا صحيح؟","title":"حكم توزيع الطعام والحلوى في المولد النبوي","answer":"الجواب: الاحتفال بالمولد هذا مما أحدثه الناس وليس مشروعًا، ولم يكن معروفًا عند السلف الصالح، لا في عهد النبي ﷺ ولا في عهد التابعين، ولا في عهد أتباع التابعين، ولا في القرون المفضلة، ولم يكن معروفًا في هذه العصور العظيمة وهي القرون الثلاثة المفضلة، وإنما أحدثه الناس بعد ذلك. وذكر المؤرخون: أن أول من أحدثه هم الفاطميون الشيعة حكام مصر والمغرب، هم أول من أحدث هذه الاحتفالات، الاحتفال بالمولد النبوي وبمولد الحسين ومولد فاطمة والحسن وحاكمهم، جعلوا هناك احتفالات بعدة موالد، منها مولد النبي عليه الصلاة والسلام، هذا هو المشهور أنهم أول من أحدثه في المائة الرابعة من الهجرة، ثم حدث بعد ذلك من الناس الآخرين تأسيًا بغيرهم. والسنة في ذلك عدم فعل هذا المولد؛ لأنه من البدع المحدثة في الدين، والرسول عليه الصلاة والسلام قال: من أحدث في أمرنا هذا ما ليس منه فهو رد، وقال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، والاحتفال قربة وطاعة، فلا يجوز إحداث قربة وطاعة إلا بدليل. وما يفعله الناس اليوم ليس بحجة ما يفعله الناس في كثير من الأمصار في اليوم الثاني عشر من ربيع الأول من الاحتفال بالموالد مولد النبي ﷺ وتوزيع الطعام أو الحلوى أو قراءة السيرة في ذلك اليوم وإقامة الموائد كل هذا ليس له أصل فيما علمنا عن رسول الله ﷺ ولا عن أصحابه ، ولا عن السلف الصالح في القرون المفضلة، وهذا هو الذي علمناه من كلام أهل العلم. وقد نبه على ذلك أبو العباس ابن تيمية رحمه الله شيخ الإسلام، ونبه على ذلك الشاطبي رحمه الله في الاعتصام بالسنة، ونبه على ذلك آخرون من أهل العلم وبينوا أن هذا الاحتفال أمر لا أساس له، وليس من الأمور الشرعية، بل هو مما ابتدعه الناس، فالذي ننصح به إخواننا المسلمين: هو ترك هذه البدعة وعدم التشاغل بها، وإنما حب النبي ﷺ يقتضي اتباعه وطاعة أوامره وترك نواهيه، كما قال الله سبحانه: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31]، فليس العلامة على حبه أن نحدث البدع التي ما أنزل الله بها من سلطان من الاحتفال بالمولد أو الحلف بالنبي ﷺ أو الدعاء والاستغاثة به أو الطواف بقبره.. أو ما أشبه ذلك، كل هذا مما لا يجوز، وليس من حبه ﷺ، بل هو من مخالفة أمره عليه الصلاة والسلام. فحبه يقتضي اتباعه وطاعة أوامره وترك نواهيه والوقوف عند الحدود التي حدها عليه الصلاة والسلام، هكذا يكون المؤمن، كما قال الله : قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31]، قال : وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وقال جل وعلا: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54]. ولو كان الاحتفال بالمولد أمرًا مشروعًا، لم يكتمه النبي ﷺ؛ فإنه ما كتم شيئًا، بل قد بلغ البلاغ المبين عليه الصلاة والسلام، فلم يحتفل بمولده ولم يأمر أصحابه بذلك، ولم يفعله الخلفاء الراشدون  ولا بقية الصحابة ، ولا التابعون وأتباعهم بإحسان في القرون المفضلة، فكيف يخفى عليهم ويعلمه من بعدهم، هذا مستحيل، فعلم بذلك أن إحداثه من البدع التي ما أنزل بها من سلطان.  ومن قال: إنه بدعة حسنة فهذا غلط لا يجوز؛ لأنه ليس في الإسلام بدع حسنة، والرسول عليه السلام قال: كل بدعة ضلالة، قال: كل بدعة ضلالة، وكان يخطب الناس يوم الجمعة ويقول: إن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة، فلا يجوز للمسلم أن يقول فيه: بدعة حسنة، يعني: يناقض النبي ﷺ ويعاكسه هذا لا يجوز للمسلم، بل يجب عليه أن يتأدب مع رسول الله ﷺ ويحذر مخالفة أمره ﷺ ومخالفة شريعته في هذا وغيره، فلما قال ﷺ: كل بدعة ضلالة، هذه الجملة جملة عامة صيغة عامة، تعم الموالد وغير الموالد من البدع. وهكذا ما أحدثه بعض الناس من الاحتفال بليلة الإسراء والمعراج ليلة سبع وعشرين من رجب أو ليلة النصف من شعبان هذه أيضًا من البدع؛ لأن الرسول ﷺ ما فعلها ولا فعلها أصحابه، فتكون بدعة. وهكذا جميع ما أحدثه الناس من البدع في الدين، كلها داخلة في هذا المعنى فليس لأحد من المسلمين أن يحدث شيئًا من العبادات ما شرعها الله، بل يجب على أهل الإسلام الاتباع والتقيد بالشرع أينما كانوا والحذر من البدعة ولو أحدثها من أحدثها من العظماء والكبار فالرسول ﷺ فوقهم، فوق جميع العظماء، وهو سيد ولد آدم، وهو الذي أوجب الله علينا طاعته واتباع شريعته، فليس لأحد أن يقدم على هديه هدي أحد من الناس، ولا طاعة أحد من الناس، ثم الله فوق الجميع ، وهو الواجب الطاعة، وهو الإله الحق ، وهو الذي بعث الرسول ﷺ يعلم الناس ويرشد الناس والرسول ﷺ هو المبلغ عن الله، الرسول ﷺ هو المبلغ عن الله . فلو كان الاحتفال بهذه الأمور مما أمره الله به لم يكتمه، بل يبلغه؛ لأن الرسول ﷺ قد بلغ البلاغ المبين، وهكذا أصحابه لو كان بلغهم وأعلمهم لبلغوا أيضًا، فلما لم يأتنا هذا عنهم، علمنا يقينًا أنه من البدع التي أحدثها الناس، وأن الواجب على أهل الإسلام ألا يوافقوا على البدع، بل عليهم أن يسيروا على النهج الذي سار عليه الرسول ﷺ، وسار عليه أصحابه الكرام ، ثم أتباعهم بإحسان في القرون المفضلة، نسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/17202/حكم-توزيع-الطعام-والحلوى-في-المولد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_853/nour_85304.mp3","categories":["البدع والمحدثات"]},{"id":18160,"question":"من ضمن أسئلة السائلة أم محمد من الرياض تقول: هل هناك صلاة تسمى صلاة التسبيح، وإذا كان الجواب بنعم، ما هي صفة هذه الصلاة، حيث أنني قرأت بأنها أربع ركعات هل هي ركعتان أم أكثر؟ هل هي متصلة مع بعضها أم لا؟ أفتونا مأجورين.","title":"هل صلاة التسابيح مشروعة؟","answer":"الجواب: صلاة التسبيح بدعة، أحاديثها غير صحيحة، فلا يجوز الاشتغال بها، يصلي الإنسان على ما شرع الله كما هو معروف، إذا أحب يتنفل بالصلاة المعروفة، يقرأ بالفاتحة وما تيسر معها ويركع ويسجد، يسلم من كل ركعتين في الليل والنهار هذا هو المشروع، أما صلاة التسبيح فحديثها ضعيف لا يصح. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17205/هل-صلاة-التسابيح-مشروعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78122.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18166,"question":"المستمع فائد إبراهيم حكم من الرياض بعث يسأل ويقول: ما حكم الاحتفال بذكرى الهجرة النبوية الشريفة، وجميع المناسبات الإسلامية العظيمة، كالإسراء والمعراج وليلة القدر وليلة النصف من شعبان؟ أثابكم الله وحفظكم للإسلام والمسلمين.","title":"ما حكم الاحتفال بذكرى الهجرة النبوية؟","answer":"الجواب: القاعدة الشرعية أن العبادات توقيفية، ليس لأحد أن يحدث عبادة لم يأذن بها الشرع، والله جل وعلا يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] ويقول : ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا [الجاثية:18]، ويقول النبي ﷺ: من أحدث في أمرنا هذا يعني: الإسلام ما ليس منه فهو رد يعني: فهو مردود متفق على صحته، ويقول عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد يعني: مردود أخرجه الإمام مسلم في صحيحه، وعلقه البخاري رحمه الله في الصحيح جازماً به. فالاحتفالات يتعبد بها، فلا يجوز منها إلا ما دل عليه الدليل، فالاحتفال بليلة القدر في ليالي العشر من رمضان أمر مشروع شرع الله لنا أن نعظم هذه الليالي، وأن نقيم ليلها بالعبادة والذكر والطاعة والقراءة ونصوم نهارها؛ لأنه من رمضان هذه الليالي العشر تلتمس فيها ليلة القدر، ومشروع للمسلمين أن يعظموها بالصلاة والعبادة في المساجد، وفي البيوت للنساء أيضاً كل هذا أمر مشروع. أما الاحتفال بالمولد النبوي، أو بأي مولد كان كمولد البدوي، أو مولد الحسين، أو مولد علي رضي الله عنهما إلى غير هذا، فهذه الاحتفالات من البدع التي أحدثها الناس، وليست مشروعة وإن فعلها كثير من الناس في كثير من الأمصار فإنها لا تكون سنة بفعل الناس، وليس في الإسلام بدعة حسنة بل كل البدع منكرة كما قال النبي ﷺ: كل بدعة ضلالة وكان يخطب يوم الجمعة عليه الصلاة والسلام يقول: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه الإمام مسلم في صحيحه، زاد النسائي رحمه الله بإسناد صحيح: وكل ضلالة في النار. فالبدع كلها ضلالة، وإن سمى بعض الناس بعض البدع بدعة حسنة فهو قول اجتهادي لا دليل عليه، ولا يجوز أن يعارض قول الرسول ﷺ بقول أحد من الناس، فالرسول ﷺ حكم على البدع بأنها ضلالة، فليس لنا أن نستثني شيئًا من هذا الأمر إلا بدليل شرعي؛ لأن هذه جملة عامة محكمة: كل بدعة ضلالة. وهكذا الاحتفال بليلة الإسراء والمعراج وبليلة النصف من شعبان، والاحتفال بالهجرة النبوية، أو بفتح مكة أو بيوم بدر، كل ذلك من البدع؛ لأن هذه الأمور موجودة على عهد النبي ﷺ ولم يحتفل بها، ولو كانت قربة إلى الله لاحتفل بها عليه الصلاة والسلام، أو أمر بها الصحابة أو فعلها الصحابة بعده، فلما لم يكن شيء من هذا علمنا أنها بدعة وأنها غير مشروعة، هذه الاحتفالات، ولا يبرر فعلها أنه فعلها فلان وفلان أو فعلها أهل البلد الفلاني كل ذلك لا يبرر، إنما الحجة ما قاله الله ورسوله، أو أجمع عليه سلف الأمة، أو فعله الخلفاء الراشدون رضي الله عنهم. وقد ثبت أن هذا الاحتفال إنما حدث في المائة الرابعة -في القرن الرابع- أعني الاحتفال بالمولد النبوي فعله الفاطميون حين ملكوا المغرب ومصر وبعض البلاد الإسلامية وهم شيعة ثم تبعهم بعض الناس بعد ذلك، فلا يليق بأهل الإسلام أن يتأسوا بأهل البدع في بدعهم، بل يجب على أهل الإسلام وأصحاب السنة أن يحاربوا البدع وأن ينكروها وألا يوافقوا على فعلها اقتداءً بالمصطفى عليه الصلاة والسلام وبخلفائه الراشدين وبصحابته المرضيين  ثم بالسلف بعدهم في القرون المفضلة، هذا هو الذي نعتقده وندين به شرعاً وننصح إخواننا المسلمين به ونوصيهم به أينما كانوا. ونسأل الله لنا ولجميع المسلمين التوفيق لما يرضيه، والسلامة من أسباب غضبه، والثبات على السنة، والحذر من البدعة، إنه سميع قريب.","link":"https://binbaz.org.sa/fatwas/17244/ما-حكم-الاحتفال-بذكرى-الهجرة-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85506.mp3","categories":["البدع والمحدثات"]},{"id":18186,"question":"هذا سائل للبرنامج من جمهورية مصر العربية القاهرة السائلة أختكم (هـ. أ. ش) تذكر في سؤالها الأول وتقول: ما الفرق بين البدعة في العبادة، والبدعة في العقيدة؟","title":"ما الفرق بدع العقائد وبدع العبادات؟","answer":"الجواب: كلها بدعة، الشرك في العقيدة بدعة، كأن يحدث الأعياد .. الاجتماع في الأعياد والاحتفال بالأعياد، أو البناء على القبور، واتخاذ المساجد عليها كل هذا بدعة، ويتعلق بالعقيدة أيضًا، ويسبب شرًا كثيرًا. وهكذا البدعة في الصلاة، أو في الصيام، أو في الحج كلها منكرة يقول النبي ﷺ: من أحدث في أمرنا هذا يعني: الإسلام ما ليس منه فهو رد متفق على صحته، ويقول عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد فالاعتقاد في الصالحين أو في أهل القبور ودعاؤهم من دون الله، أو الاستغاثة بهم هذا كفر أكبر في العقيدة، والبناء على القبور، واتخاذ المساجد؛ عليها كذلك بدعة لكنه دون الشرك، وسيلة من وسائل الشرك، وتجصيصها كذلك، ووضع القباب عليها من وسائل الشرك، ومن وسائل اختلال العقيدة. والبدع الأخرى كونه يبتدع صلاة ما شرعها الله، أو اجتماعًا ما شرعه الله كبدعة الموالد الاحتفال بالموالد، أو ما أشبه ذلك من القرب التي يحدثها هذا يسمى بدعة وهو من البدع في الفروع، أو يحدث في الصلاة بدعة، أو في الصوم، أو في الحج. المقصود أن البدع ضابطها أن يأتي بعبادة ما شرعها الله، كأن يصلي مثلًا بثلاث سجدات، الركعة يحط فيها ثلاث سجدات يتعمد، أو ركوعين هذه بدعة منكرة وباطلة، كذلك يحدث صوم ما شرعه الله كأن يقول: الصائم يصوم من الليل كذا، لا يفطر إلا بعد مضي كذا من الليل، أو يتقدم بالصوم جزء من الليل؛ يأخذ قطعة من الليل قبل طلوع الفجر فهذه بدعة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17251/ما-الفرق-بدع-العقاىد-وبدع-العبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78204.mp3","categories":["البدع والمحدثات"]},{"id":18197,"question":"رسالة وصلت إلى البرنامج من أوجلة في ليبيا، باعث الرسالة أحد الإخوة يقول حمد عتيبي، أرجو تقديم أسئلتي إلى سماحة الشيخ عبد العزيز بن عبد الله بن باز .السؤال الأول: بعد دفن أي ميت في بلدتنا ورجوع أهل الميت إلى المنزل، يصحبهم الكثير من أهالي البلدة، فيجتمع القراء في بيت المتوفى، ويقرءون القرآن بطريقة تقسيم القرآن إلى أجزاء، ويتلونه معًا في ساعة واحدة، كل يقرأ جزءًا أو اثنين، ثم يتناولون طعام الصدقة الذي تم إعداده وهو عبارة عن عدة رءوس من الأغنام تم ذبحها قبل دفن الميت، يتم هذا في اليوم الأول والثاني والثالث ثم في يوم الأسبوع، فهل يصل ثواب القراءة والصدقة على هذا النحو للميت، مع العلم أن الذين حضروا وأكلوا من طعام الصدقة ليسوا من المحتاجين؟ أفتونا جزاكم الله عنا وعن المسلمين خير الجزاء.","title":"حكم الاجتماع في بيت الميت لقراءة القرآن وتناول الطعام","answer":"الجواب: هذا العمل لا أعلم له أصلًا في الشرع، وهو من البدع التي أحدثها الناس، فليس من عادة النبي ﷺ ولا من عادة أصحابه الرجوع إلى بيت المتوفى أو غيره بعد الدفن ليجتمعوا على الطعام وعلى قراءة القرآن، ليس هذا من سنة المسلمين فيما نعلم. أما لو كان ذلك من غير قاعدة ومن غير اتباع معين بل صدفة بأن دعاهم، بعدما رجعوا من الدفن دعاهم بعض إخوانهم وقدم لهم طعامًا، أو قرأ أحدهم بعض القراءة من غير أن تكون عادة مستمرة ولا سنة قائمة بل لعارض هذا لا يضر، إذا رجعوا قال بعض إخوانهم: تفضلوا عندي، وأطعمهم ما تيسر أو قرأ أحدهم بعض القراءة لأنفسهم هذا لا بأس. أما أن يتخذوا هذا عادة بعدما يرجعون يرجعون إلى محل الميت أو إلى محل فلان أو فلان قاعدة، ليقرءوا القرآن ويثوبوه ويأكلوا مما أعد قبل الموت هذا لا أصل له، بل هو من البدع، والرسول عليه الصلاة والسلام قال: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته، وقال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد خرجه مسلم في صحيحه عن عائشة رضي الله عنها، وقال أيضًا عليه الصلاة والسلام: إياكم ومحدثات الأمور، فإن كل محدثة بدعة وكان يقول في خطبة الجمعة عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة رواه مسلم في الصحيح، زاد النسائي بإسناد جيد: وكل ضلالة في النار. فنصيحتي لإخواني هؤلاء أن لا يفعلوا هذا، وإذا فرغوا من دفن الميت كل يذهب إلى أهله وإلى رحله ويدعو لميتهم. أما قراءة القرآن للميت فليس لها أصل، وإن قال بذلك جمع من أهل العلم وقالوا: لا بأس لكن ليس له أصل معروف عن النبي ﷺ ولا عن الصحابة، وقد قال الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ [النساء:59]، وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]. وبالنظر في كتاب الله وسنة رسوله ﷺ لا نعلم ما يدل على ذلك عند الرد إليهما، فليس من هدي النبي ﷺ وليس من هدي أصحابه، ثم فيه تكليف لمن يبذل هذه الأموال سواء كان أهل الميت أو غيرهم وشرع دين لم يأذن به الله، والله يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]. فالواجب ترك هذه العادة والاشتغال بما ينفعه من الدعاء للميت في الطريق وفي البيت، الدعاء له الترحم عليه، وإذا أحب أحد يتصدق عنه من غير إلزام لأحد فلا بأس، الصدقة تنفع الميت، أو يتصدق عنه أهله، الصدقة تنفع الميت بأن يعطوا الفقراء صدقة أو ملابس من ملابس أو نقود أو طعام كل هذا طيب من فعله عن الميت، فهو مأجور إذا كان الميت مسلمًا. كذلك بعث الطعام لأهل الميت إذا صنع لهم جيرانهم أو أقاربهم طعامًا وبعثوه إلى أهل الميت لأنهم مشغولون بالمصيبة فهذا مشروع؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه لما أتى خبر موت جعفر بن أبي طالب  في الشام في مؤتة أمر أهله أن يصنعوا لهم طعامًا يصنعوا لأهله طعامًا، قال: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم فأمر ببعث الطعام إلى أهل جعفر ؛ لأن المصيبة قد شغلتهم عن صنع الطعام لأنفسهم، هذا لا بأس به بل هو مشروع. أما أهل الميت فلا، أما أهل الميت لا يقدمون الطعام للناس ولا يصنعونه للناس، ولا يكلفون بذلك، لا من مال الميت ولا من غير مال الميت، لكن لو نزل عليهم ضيف وأطعموه من طعامهم، أو أطعموه بما يناسبه لأنه ضيف، لا من أجل الميت لا من أجل اتخاذ عادة بل من أجل الضيف فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17233/حكم-الاجتماع-في-بيت-الميت-لقراءة-القران-وتناول-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90704.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":18275,"question":"هل صلاة التسابيح سنة أم بدعة؟","title":"الصواب في حكم صلاة التسابيح","answer":"الجواب: الصواب فيها أنها غير صحيحة، وأنها بدعة غير صحيحة، قد استحبها بعض أهل العلم، وظن الحديث فيها صحيحًا، والصواب: أن الحديث ليس بصحيح، بل هو موضوع، ومنكر المتن وضعيف الإسناد لا يصح الإسناد عن النبي ﷺ ولهذا جزم جماعة من أهل العلم من الحفاظ من أئمة الحديث بأنها موضوعة غير صحيحة عن النبي ﷺ وهذا هو المعتمد، أنها غير صحيحة، بل موضوعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17324/الصواب-في-حكم-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91011.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18400,"question":"هذا سائل يقول: سماحة الشيخ! هل كل حكم استند فيه بحديث ضعيف نسميه بدعة؟","title":"حكم العمل المستند إلى حديث ضعيف","answer":"الجواب: العبادات توقيفية، لا يشرع عبادة إلا بدليل؛ فالعبادات التي ما عليها دليل تكون بدعة، أما إذا كان فيما يتعلق بالحرام والحلال هذا الأصل الحلال إلا أن يعلم أنه حرمه الشرع. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17469/حكم-العمل-المستند-الى-حديث-ضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91332.mp3","categories":["البدع والمحدثات"]},{"id":18419,"question":"أخونا يسأل أيضًا ويقول: إنني أعلم أن بناء القباب على القبور لا يجوز، ولكن بعض الناس يقولون: إنها تجوز، ودليلهم قبة الرسول ﷺ، ويقولون: إن محمد بن عبد الوهاب أزال كل القباب ولم يزل تلكم القبة -أي: قبة الرسول ﷺ- فالمفروض أن تزال مادام الناس غير متشككين -فيما يبدو- فكيف نرد على هؤلاء؟ أفيدونا بارك الله فيكم.","title":"الرد على شبهة القبة المبنية على قبر النبي ﷺ","answer":"الجواب: لا شك أن القباب على القبور بدعة ومنكر كالمساجد على القبور كلها بدعة وكلها منكر، لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ولما ثبت عنه عليه الصلاة والسلام أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح. ولما ثبت أيضًا عن جابر بن عبد الله رضي الله عنهما في صحيح مسلم عن النبي عليه الصلاة والسلام أنه نهى عن تجصيص القبور والقعود عليها والبناء عليها، فنص ﷺ على النهي عن البناء على القبور والتجصيص لها أو القعود عليها، ولا شك أن وضع القبة عليها نوع من البناء، وهكذا بناء المسجد عليها نوع من البناء، وهكذا جعل سقوف عليها وحيطان نوع من البناء. فالواجب أن تبقى مكشوفة على الأرض مكشوفة كما كانت القبور في عهد النبي ﷺ في البقيع وغيره مكشوفة، يرفع القبر عن الأرض قدر شبر تقريبًا ليعلم أنه قبر فلا يمتهن، أما أن يبنى عليه قبة أو غرفة أو عريشًا أو غير ذلك فهذا لا يجوز، بل يجب أن تبقى القبور على حالها مكشوفة ولا يزاد عليها غير ترابها فيرفع القبر من ترابه الذي حفر منه، يرفع قدر شبر ويكفي ذلك كما جاء في حديث سعد بن أبي وقاص أنه قال : \"الحدوا لي لحدًا وانصبوا علي اللبن نصباً كما صنع برسول الله ﷺ\"، وقال في الرواية: \"فرفع قبره عن الأرض قدر شبر\" يعني قبر النبي ﷺ. فالحاصل أن القبور ترفع قدر شبر وما يناسب حوله للعلم بأنها قبور ولئلا تمتهن وتوطأ أو يجلس عليها، أما أن يبنى عليها فلا، لا قبة ولا غيرها للأحاديث السابقة حديث جابر وحديث عائشة وغيرهما، وفي حديث جابر التصريح بالنهي عن البناء على القبور وتجصيصها. أما قبة النبي ﷺ فهذه حادثة أحدثها بعض أمراء الأتراك في بعض القرون المتأخرة في القرن التاسع أو الثامن وترك الناس إزالتها لأسباب كثيرة: منها: جهل الكثير ممن يتولى إمرة المدينة، ومنها: خوف الفتنة؛ لأن بعض الناس يخشى الفتنة لو أزالها لربما قام عليه الناس وقالوا: هذا يبغض النبي ﷺ وهذا كيت وكيت، وهذا هو السر في بقاء الدولة السعودية لهذه القبة؛ لأنها لو أزالتها لربما قال الجهال -وأكثر الناس جهال-: إن هؤلاء إنما أزالوها لبغضهم النبي عليه الصلاة والسلام، لا يقولون لأنها بدعة لا، يقولون: لبغضهم للنبي ﷺ، هكذا يقول الجهلة وأشباههم. فالحكومة السعودية الأولى والأخرى إلى وقتنا هذا إنما تركت هذه القبة المحدثة خشية الفتنة وأن يظن بها السوء، وهي لا شك أنها والحمد لله تعتقد تحريم البناء على القبور وتحريم اتخاذ القباب على القبور، والرسول ﷺ دفن في بيت عائشة لئلا تقع الفتنة به لئلا يغلى فيه، بل دفنه الصحابة في بيت عائشة حذرًا من الفتنة، والجدران قائمة من قديم ودفنوه في البيت حماية له من الفتنة عليه الصلاة والسلام لئلا يفتن به الجهلة. وأما هذه القبة فهي موضوعة متأخرة من جهل بعض الأمراء فلو أزيلت فلا بأس بذلك، بل هذا حق، لكن قد لا يتحمل هذا بعض الجهلة وقد يرمون من أزالها بأنه ليس على حق وأنه يبغض النبي عليه الصلاة والسلام، فمن أجل هذا تركت الدولة السعودية هذه القبة على حالها؛ لأنها من عمل غيرها ولا تحب التشويش والفتنة التي قد يتزعمها بعض الناس من عباد القبور وأصحاب الغلو في الأموات من المشركين فيرمونها بما هي بريئة منه من بغضها للنبي ﷺ أو الجفاء في حقه. والعلماء السعوديين منهم الشيخ محمد بن عبد الوهاب رحمه الله وغيره من العلماء كلهم بحمد الله على السنة وعلى طريق أصحاب النبي ﷺ وأتباعهم بإحسان، في توحيد الله والإخلاص له والتحذير من الشرك والبدع، ووسائل الشرك، وهم أشد الناس تعظيمًا للنبي ﷺ ولأصحابه كالسلف الصالح، هم من أشد الناس تعظيمًا للنبي ﷺ ولأصحابه  وأرضاهم مشيًا وسيرًا على طريق السلف الصالح في محبته ﷺ وتعظيم جانبه التعظيم الشرعي الذي ليس فيه غلو ولا بدعة، بل تعظيم يقتضي اتباع شريعته وتعظيم أمره ونهيه والذب عن سنته، ودعوة الناس إلى اتباعه، وتحذيرهم من الشرك به أو بغيره، وتحذيرهم من البدع المنكرة فهم على هذا الطريق أولهم وآخرهم يدعون الناس إلى اتباع الرسول ﷺ وإلى تعظيم سنته وإلى إخلاص العبادة لله وحده، وعدم الشرك به سبحانه، ويحذرون الناس من البدع التي كثرت بين الناس من عصور كثيرة، ومن ذلك بدعة هذه القبة التي وضعت على القبر النبوي وإنما تركت من أجل خوف القالة والفتنة والله ولي التوفيق، ولا حول ولا قوة إلا بالله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17513/الرد-على-شبهة-القبة-المبنية-على-قبر-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86402.mp3","categories":["مسائل متفرقة في العقيدة","البدع والمحدثات"]},{"id":18468,"question":"عندنا في قريتنا يقرءون آية الكرسي بعد الصلوات في كل فرض عمومًا، الإمام والمصلين جهرًا، أفيدونا عن حكم ذلك؟","title":"حكم الجهر بقراءة آية الكرسي بعد الصلاة","answer":"الجواب: هذا غير مشروع، وهذا بدعة، إنما السنة أن يقرأها الإنسان بينه وبين نفسه بعد الصلاة، أما أن يقرأها الإمام والمأمومون جهرة فهذا لا يجوز، وليس من سنة المسلمين، بل هذا من البدع، ولكن يستحب في أصح قولي العلماء أن يقرأها المؤمن بعد الصلاة بينه وبين نفسه، من دون مشاركة الإمام أو المأمومين بأصوات جماعية أو جهرية، كل هذا لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/17570/حكم-الجهر-بقراءة-اية-الكرسي-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86608.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":18477,"question":"عندنا في قريتنا يقرءون آية الكرسي بعد الصلوات في كل فرض عمومًا، الإمام والمصلين جهرًا، أفيدونا عن حكم ذلك؟","title":"حكم الجهر بقراءة آية الكرسي بعد الصلاة","answer":"الجواب: هذا غير مشروع، وهذا بدعة، إنما السنة أن يقرأها الإنسان بينه وبين نفسه بعد الصلاة، أما أن يقرأها الإمام والمأمومون جهرة فهذا لا يجوز، وليس من سنة المسلمين، بل هذا من البدع، ولكن يستحب في أصح قولي العلماء أن يقرأها المؤمن بعد الصلاة بينه وبين نفسه، من دون مشاركة الإمام أو المأمومين بأصوات جماعية أو جهرية، كل هذا لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/17570/حكم-الجهر-بقراءة-اية-الكرسي-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86608.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":18579,"question":"هذا السائل محمد داود يقول في هذا  سؤالي يتعلق بالنية، فمثلاً عندما أقف للصلاة، وأعلم بأنني واقف لأداء الصلاة، فهل يكفي ذلك؟ أو لا بد من النطق بالنية؟ وقد سمعت من بعض الناس عندما يقف للصلاة، وأثناء رفع اليدين لتكبيرة الإحرام يقول: نويتُ أن أصلي صلاة كذا، ويسميها بعدد ركعاتها، وجهونا في ضوء هذا السؤال.","title":"حكم التلفظ بالنية عند أداء الصلاة","answer":"الجواب: النية محلها القلب، والسنة أن ينوي في قلبه فقط، ولا يتكلم بلسانه، فإذا قام يصلي ناويًا صلاة الظهر كفى، صلاة العصر كفى، صلاة المغرب كفى، صلاة الضحى كفى، ولا يحتاج أن يقول: نويتُ، بدعة، يقول: نويتُ أن أصلي كذا وكذا، الظهر أربعًا، العصر أربعًا، المغرب ثلاثًا، هذا بدعة، لا أصل له، والرسول ﷺ يقول: إنما الأعمال بالنيات والنية محلها القلب، وما كان النبي ﷺ يتلفظ بالنية ولا أصحابه  ويقول -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود. فالواجب على كل مسلم أن تكون نيته في القلب، وأن لا يتلفظ به، يقول: نويتُ أن أصلي كذا، أو نويت أن أطوف كذا، أو نويت أن أسعى كذا، لا، النية محلها القلب ويكفي، والحمد لله. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17697/حكم-التلفظ-بالنية-عند-اداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78621.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":18634,"question":"في آخر أسئلة هذا السائل يقول: هل يجوز للمصلين لصلاة الجمعة أن يصلوا الجمعة وبعد ذلك مباشرة يصلون الظهر؟ علمًا بأنهم ناس مستوطنين ومقيمين في هذه المدينة.","title":"حكم أداء صلاة الظهر بعد صلاة الجمعة","answer":"الجواب: صلاة الظهر بعد الجمعة بدعة لا يجوز، الجمعة كافية، ولا يجوز صلاة الظهر صلاتين، الله ما أوجب إلا خمس صلوات، هذا يأتي بصلاة سادسة، لا يجوز هذا، الجمعة كافية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17752/حكم-اداء-صلاة-الظهر-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78717.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":18641,"question":"يسأل أخونا: هل تجب إعادة صلاة الظهر بعد صلاة الجمعة في بلد تعددت فيه المساجد؟","title":"هل يصلى الظهر بعد الجمعة في بلد به عدة مساجد؟","answer":"الجواب: لا، لا يجوز ذلك، بل الواجب أن يتحرى ويصلي الجمعة والحمد لله، وليس له أن يعيد ظهرًا؛ لأن هذه بدعة ليس لها أصل، متى صلى الجمعة فالحمد لله، والتعدد له مسوغات، فحسن الظن بالمسلمين وأنها إنما تعددت لمسوغ شرعي أولى من سوء الظن، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17753/هل-يصلى-الظهر-بعد-الجمعة-في-بلد-به-عدة-مساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91902.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":18693,"question":"يقول السائل في هذا  ما كيفية قلب الرداء في خطبة الاستسقاء، هل هو خلع الرداء، وجعل ذلك إلى الصدر أو إلى الظهر؟ مأجورين.","title":"كيفية قلب الرداء في خطبة الاستسقاء","answer":"الجواب: تحويل الرداء أن يجعل ما على الأيمن على الأيسر، يعني: يحول، يقلب الرداء، ويقلب البشت هذا معناه، يحول ما كان على الأيمن على الأيسر، يعني: يقلب البشت حتى يكون الظاهر هو الباطن، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17798/كيفية-قلب-الرداء-في-خطبة-الاستسقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78807.mp3","categories":["صلاة الاستسقاء","البدع والمحدثات"]},{"id":18742,"question":"أختنا تسأل وتقول: هل صلاة الخامس عشر من شعبان مائة ركعة، ويقرأ في كل ركعة فاتحة الكتاب عشر مرات، وقُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] وتكون ألف مرة في المائة ركعة، أو اثني عشرة ركعة، في كل ركعة ثلاثون مرة، هل هي جائزة أو صحيحة؟ وما رأيكم في ذلك؟ جزاكم الله خيرًا.","title":"حكم صلاة النصف من شعبان","answer":"الجواب: هذه أيضًا بدعة لا أساس لها من الصحة، هذه صلاة لا أساس لها من الصحة، بل هي بدعة لا أساس لها، نعم.","link":"https://binbaz.org.sa/fatwas/17873/حكم-صلاة-النصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87504.mp3","categories":["البدع والمحدثات"]},{"id":18743,"question":"رسالة أخرى وصلت إلى البرنامج من أبها، وبعثت بها إحدى الأخوات من هناك تقول: أختكم السائلة (م.ع) سألت في حلقة مضت بعضًا من الأسئلة، وفي هذه الحلقة تسأل وتقول: قرأت في كتاب تنزيه الشريعة المرفوعة: \"صلاة التسبيح\" وهي أربع ركعات، ويقرأ في كل ركعة الفاتحة، وسورة صغيرة، ثم يسبح في الركعة الأولى خمسًا وسبعين تسبيحة في القيام، وفي الركوع والسجود، وفي الركعة الثانية هكذا، وفي الأربع الركعات ثلاثمائة تسبيحة، هل هذا حديث صحيح؟ وما رأيكم فيما أورده صاحب ذلكم الكتاب؟","title":"ما مدى صح حديث صلاة التسبيح؟","answer":"الجواب: صلاة التسبيح مشهورة عند أهل العلم، وقد تنازع العلماء في صحتها، فمن أهل العلم من عمل بها وصححها؛ لما في ذلك من الأجر العظيم الذي ذكره النبي ﷺ وغفران السيئات، ومن أهل العلم من ضعف الرواية، ولم يصححها، وذكر أنها رواية شاذة، وحديث شاذ مخالف للأحاديث الصحيحة، وهذا القول الثاني هو أصح، أن صلاة التسبيح حديثها شاذ غير صحيح، وأن المعتمد قول من قال: إنها غير صحيحة، وأنها موضوعة لا أساس لها من الصحة، وأسانيدها كلها معلولة، ومتنها شاذ منكر مخالف للأدلة الشرعية الثابتة عن رسول الله -عليه الصلاة والسلام-. فإن صلاته في الليل والنهار محفوظة -عليه الصلاة والسلام- وقد رواها الثقات والأثبات في الصحيحين وغيرهما، ولم يحفظ عنه -عليه الصلاة والسلام- أن صلى هذه الصلاة؛ فوجب على أهل الإيمان أن يردوا ما خالف الأدلة المعروفة إلى الأدلة المعروفة، فالأدلة المعروفة الثابتة دالة على صفة صلاته -عليه الصلاة والسلام- وأن ليس فيها هذه التسبيحات المذكورة، بل هذه انفردت بها هذه الرواية، فالصواب أنها شاذة المتن ضعيفة الأسانيد؛ فلا ينبغي التعويل عليها، ولا العمل بها، وإن صححها بعض المتقدمين، وبعض المتأخرين، لكن العمدة في هذا أن كل متن يخالف الأحاديث الصحيحة -وإن صح سنده- فإنه يعتبر شاذًا، فكيف إذا كان الإسناد معلولًا. قد قال الأئمة في مصطلح الحديث: إن الأحاديث المختلفة يرجع فيها أولًا إلى الجمع -إذا تيسر الجمع- فإذا أمكن الجمع جمع بينها، وقبلت كلها، فإن لم يتيسر الجمع ولم تتوافر شروطه؛ رجع إلى النسخ إذا علم النسخ، إذا علم الناسخ، إذا علم الأخير من المتقدم؛ صار الأخير ناسخًا للمتقدم عند تعذر الجمع، فإذا لم يعلم المتأخر من المتقدم، ولم تتوافر شروط النسخ، ولا شروط الجمع؛ انتقل إلى أمر ثالث، وهو الترجيح. وهذه الصلاة ليس فيها ما يدل على التأريخ، وأنها متأخرة عن غيرها، وليس فيها ما يدل على أنها سنة استعملها النبي ﷺ سابقًا ولاحقًا، وليس فيها ما يقتضي الجمع بينها وبين غيرها؛ فتعين الأمر الثالث وهو: أنها غير صحيحة، وأنها شاذة مخالفة للأحاديث الصحيحة الثابتة عن رسول الله ﷺ، ومخالفة لسنته المعروفة عنه -عليه الصلاة والسلام- في ليله ونهاره مدة حياته -عليه الصلاة والسلام-، فلم يحفظ عنه أنه فعلها مرة واحدة -عليه الصلاة والسلام- ولم يعرف عنه -عليه الصلاة والسلام- ما يدل على أنها سنة متبعة في أحاديث صحيحة؛ فعلم بذلك أنها شاذة، وأنها مختلقة، وأنه لا أساس لها في الأحاديث الصحيحة الثابتة عن رسول الله -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17872/ما-مدى-صح-حديث-صلاة-التسبيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87503.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18783,"question":"رسالة وصلت إلى البرنامج من المستمع أحمد حسن أحمد من الخرج، أخونا بدأ رسالته بقوله:بسم الله الرحمن الرحيم، إنني سوداني مقيم بمدينة الخرج، وتوفي لرحمة مولاه والدي قبل شهرين، ومن العادات التي عندنا بالسودان بدون سند أن يقرأ الابن لوالده المتوفى دبر كل صلاة سورة الإخلاص إحدى عشرة مرة ويهب ثواب ما تلاه لروح المرحوم والده، يا سماحة الشيخ، هل لهذا العمل من دليل؟أفيدونا عنه جزاكم الله خيرًا.","title":"حكم إهداء ثواب سورة الإخلاص للميت","answer":"الجواب: هذا العمل ليس له دليل، بل هو بدعة، ولو اعتاده جماعتهم، فإن البدع لا تبررها العادات، والواجب ترك هذه البدعة، والحذر منها، ويكفي أن تدعو لأبيك، وأن تتصدق عنه، هذا هو المشروع الدعاء، والصدقة، والحج عنه، والعمرة، كل هذا ينفعه بإذن الله. فنوصيك بالاستكثار من الدعاء لوالدك بالمغفرة والرحمة، وهكذا الصدقة عنه بما تيسر ولو بالقليل، والله -جل وعلا- يثيبك، ويخلف عليك ما أنفقت في هذا السبيل الخلف العظيم، ويأجرك على دعواتك لأبيك، وقد قال -عليه الصلاة والسلام-: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فمما يلحق الميت بعد وفاته دعاء الولد، والولد يشمل الذكر والأنثى، البنت والابن كلاهما يقال له: ولد، كما قال تعالى: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] فالأولاد تطلق على الذكور والإناث، والولد يقال للذكر والأنثى، ويقال للذكر: ابن، للأنثى بنت، وقوله ﷺ: أو ولد صالح يدعو له يعني: ذكر أو أنثى. فمن البر للوالد بعد وفاته الدعاء له، وقد سئل -عليه الصلاة والسلام- سأله بعض الصحابة قال: «يا رسول الله، هل بقي من بر أبوي شيء أبرهما بعد وفاتهما؟ قال -عليه الصلاة والسلام-: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما فذكر خمسة أشياء: الصلاة عليهم، يعني: الدعاء الدعاء لهم، ومن الصلاة عليهم صلاة الجنازة أيضًا.  والاستغفار لهما طلب المغفرة لهما.  والثالث: إنفاذ عهدهما من بعدهما إذا أوصيا بشيء تنفذه إذا كانت وصية لا تخالف الشرع تنفذها، والرابع: صلة الرحم التي لا توصل إلا بهما كإكرام أعمامك وعماتك، وأخوالك وخالاتك، والإحسان إليهم، وصلتهم كل هذا من بر والديك.  والخامس: إكرام صديقهما إذا كان لهما صديق تكرمه بما تستطيع من الكلام الطيب، والزيارة، والدعوة إلى البيت لإكرامه بالضيافة، ومواساته إن كان فقيرًا كل هذا من إكرام الصديق، والله المستعان. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17910/حكم-اهداء-ثواب-سورة-الاخلاص-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90603.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":18811,"question":"يوجد عندنا من يقول: الذي يؤذن هو الذي يقيم الصلاة، وتوجد عندنا ظاهرة قراءة آية الكرسي قبل التسبيح الذي بعد الصلاة، ما رأيكم في هذا أفتونا؟جزاكم الله خيرًا.","title":"حكم إقامة غير المؤذن وتقديم آية الكرسي على أذكار الصلاة","answer":"الجواب: الأفضل أنه يتولى الإقامة من يتولى الأذان، هذا هو الأفضل، ولو أقام غيره فلا حرج، لو أقام غيره فلا حرج، ولكن الأفضل هو أن المؤذن هو الذي يقيم، كما كان بلال يؤذن ويقيم  لكن لو أقام غيره بأن شغل المؤذن، أو سمح بأن يقيم غيره، فلا بأس بذلك. وكذلك ظاهرة قراءة آية الكرسي قبل التسبيح لا حرج في ذلك، الرسول ﷺ ندب إلى قراءة آية الكرسي بعد الصلاة، فإن قرأها قبل الذكر فلا بأس، لكن الأفضل أن تكون بعد الذكر؛ لأن الرسول ﷺ كان يذكر الله بعد السلام، فالأفضل أن يبدأ بالذكر ثم يأتي بها سرًّا بعد الأذكار، هذا هو الأفضل. المقدم: جزاكم الله خيرًا، وإن كانت قراءة آية الكرسي جماعية سماحة الشيخ؟ الشيخ: لا، يقرأها سرًا بينه وبين نفسه لا جماعية، يقرأها الإنسان بعد السلام، وبعد الذكر سرًا بينه وبين نفسه، ولا يقرأها جماعية مع الناس، نعم. المقدم: بارك الله فيكم، أعتقد أن أخانا يسأل عن كونها مقروءة جماعة؟ الشيخ: لا، جماعية لا تصلح، بدعة لا يجوز قراءتها جماعية، ولكن تقرأ بينه وبين نفسه بعد الأذكار الشرعية، هذا هو الأفضل. المقدم: كل مصل يقرؤها بينه وبين نفسه. الشيخ: بعدما يفرغ من الأذكار، نعم، وهكذا قراءة قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين يقرأها بينه وبين نفسه بعد كل صلاة، وبعد الفجر ثلاثًا، وبعد المغرب ثلاثًا، قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين ثلاثًا بعد المغرب، ثلاثًا بعد الفجر، أما بعد الظهر والعصر والعشاء فمرة واحدة بينه وبين نفسه، نعم. المقدم: نفع الله بكم.","link":"https://binbaz.org.sa/fatwas/17933/حكم-اقامة-غير-الموذن-وتقديم-اية-الكرسي-على-اذكار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87608.mp3","categories":["الأذان والإقامة","البدع والمحدثات","الأدعية والأذكار"]},{"id":18854,"question":"أخونا يشير إلى ما يشاع بين الناس من أن هناك بدعة حسنة وبدعة سيئة.","title":"حكم تقسيم البدعة إلى حسنة وسيئة","answer":"الجواب: الصواب: أنه ليس هناك بدعة حسنة، كل بدعة ضلالة، كما بينه النبي -عليه الصلاة والسلام-، فإنه قال -عليه الصلاة والسلام- في خطبته في الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة، وهكذا جاء في حديث عائشة، وفي حديث العرباض بن سارية وغيرها، فالبدع كلها ضلالة كما قاله النبي -عليه الصلاة والسلام-. وأما ما رآه بعض العلماء من تقسيم البدعة إلى حسنة وسيئة، فهو اصطلاح جديد، ورأي من بعض العلماء لا يعول عليه.  والصواب: أن كل بدعة ضلالة، وما ظنه بعض العلماء أنه بدعة حسنة، فليس الأمر كذلك، ولكنه مشروع، ولا يقال له: بدعة، وإن قيل: بدعة من جهة اللغة، كما قال عمر  في التراويح: نعمت البدعة هذا من حيث اللغة؛ لأن الرسول ﷺ لم يستمر عليها في حياته، خاف أن تفرض عليهم؛ فصلاها ليالٍ ثم ترك، وقال: إني أخشى أن تفرض عليكم. فلما توفي -عليه الصلاة والسلام-، رأى عمر  وأرضاه أن إقامتها أمر طيب ومشروع؛ لأن افتراضها على الناس قد أمن بموته -عليه الصلاة والسلام-، فلهذا لما أمرهم بذلك، ورآهم يصلون قال: نعمت البدعة هذه يعني: من حيث اللغة؛ لأن البدعة في اللغة: ما فعل على غير مثال سابق، والتراويح لم تكن على مثال سابق، من جهة الاستمرار في ليالي رمضان، وإلا فهي سنة، التراويح سنة وقربة وطاعة لله، ليس بدعة من حيث الشرع. فهكذا ما يسمى بدعة من حيث اللغة؛ لأنه لم يكن موجودًا، كالمدارس المنظمة وأشباه ذلك، هذا إذا قيل له بدعة من حيث اللغة، لا يضر، لكن ليس ببدعة من حيث الشرع، فإن المدارس إنما أوجدت لتعليم كتاب الله وتعليم سنة رسوله -عليه الصلاة والسلام-، وبيان أحكام الشرع، فهي قربة إلى الله مثلما تبنى المساجد لإقامة الصلاة فيها وحلقات العلم، فليست بدعة، فتعمير المساجد بغير الطريقة التي كان عليها النبي ﷺ بأن تعمر بالمسلح، بالأحجار، بالساج، هي قربة وطاعة ومأمور بها، وإن كانت على غير الغرار الذي كان في عهد النبي ﷺ، فقد بنى عثمان  وأرضاه مسجد الرسول ﷺ على غير الطريقة التي بناها عليه النبي ﷺ، بناه بالحجر المنقوش وبالساج؛ تعظيمًا لهذا المسجد، وتشريفًا له، لما رأى الناس غيروا وحسنوا بيوتهم بالبناء؛ فأحب أن يحسن مسجد رسول الله -عليه الصلاة والسلام- اجتهادًا منه  وأرضاه. فهكذا ما يوجد من المساجد بالمسلح أو بالحجر المنقوش أو كذا، لا يقال: بدعة، ولكن يستحب للمسلم عند بناء المساجد أن يخليها من النقوش، ومما يشوش على المصلين، ولكن إذا بنيت ببناء محكم مضبوط؛ فهذا شيء مطلوب لما فيه من الحيطة للمسلمين، أما النقوش في المساجد، من داخل المساجد هذا يكره؛ لما في ذلك من التشويش، وإشغال المصلي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18006/حكم-تقسيم-البدعة-الى-حسنة-وسيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87904.mp3","categories":["البدع والمحدثات"]},{"id":18855,"question":"يسأل أخونا سؤالًا آخر ويقول: رأيت في بعض المساجد أنه بعد أن يقرأ أحد القراء للقرآن بصوت عالٍ يقول: صدق الله العظيم، ثم الفاتحة، أي: يأمر الناس الموجودين في المسجد بقراءة الفاتحة، هل هذا من السنة، أم هو بدعة حسنة، أم هو بدعة سيئة،؟جزاكم الله عنا وعن المسلمين خيرًا.","title":"حكم قول: (صدق الله العظيم) والفاتحة بعد قراءة القرآن","answer":"الجواب: ما يفعله بعض الناس إذا فرغ من قراءة القرآن في المسجد أو غيره، قال: صدق الله العظيم، ليس له أصل، بل هو من البدع، ولا ينبغي اتخاذ ذلك، ولا استعمال ذلك، ولا ينبغي الاغترار بالناس في هذا، فهذا شيء لا أصل له، فلم يكن النبي ﷺ بعد القراءة يقول ذلك، ولا الصحابة يقولون ذلك، وإنما هو شيء أحدثه الناس، فلا يجوز اعتياد ذلك، لكن لو فعله بعض الأحيان لداعٍ دعا إلى ذلك أن يقرأ آية تعجبه، أو يرى آثارها، فيقول: صدق الله العظيم، لقد وجد هذا، ولقد صار هذا، من باب التعجب مما وقع، مثلما قد يقوله النبي ﷺ، أو يقوله بعض الصحابة إذا رأى شيئًا يوافق القرآن والسنة يقول: صدق الله ورسوله، فيما بين وفيما أوضح الله، وفيما أوضح الرسول -عليه الصلاة والسلام-. المقصود: أن اعتياد هذا الأمر بعد القراءة في الصلاة أو خارجها بدعة، وإذا كان مع هذا يقول: اقرؤوا الفاتحة، كذلك؛ بدعة أخرى، فلا أصل لهذا ولا لهذا، وإنما إذا فرغ من القراءة يكتفي بذلك، إن كانت القراءة انتهت باسم من أسماء الله قال:  مثل: فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ [الواقعة:74] أو ما أشبه ذلك، وإلا فلينتهِ، والحمد لله، ولا يشرع له شيء. لكن لو انتهت القراءة على شيء من أسماء الله، شرع له تسبيح الله وتعظيمه، كما في آية التغابن: عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيزُ الْحَكِيمُ [التغابن:18] وما أشبه ذلك، فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ [الواقعة:74] إلى أشباه ذلك؛ لأن السنة للمؤمن إذا مر بآية فيها رحمة سأل، وبآية فيها عذاب تعوذ، وبآية فيها أسماء الله عظمها وسبحه  كان النبي يفعل هذا في التهجد في الليل، ولم يحفظ عنه أنه كان يفعله في الفرائض، بل كان يستمر في قراءته -عليه الصلاة والسلام-، في الفرائض، وإنما فعل هذا في تهجده بالليل، لكن إذا كان في النهاية اسم من أسماء الله في القراءة قبل أن يركع وسبح الله  فلا مانع؛ لأنه في هذه الحالة ليس في حال قراءة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18000/حكم-قول-صدق-الله-العظيم-والفاتحة-بعد-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87903.mp3","categories":["القرآن وعلومه","البدع والمحدثات"]},{"id":18868,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها أخ لنا من هناك يقول: أخوكم في الله مجدي مصطفى زيتون، أخونا يقول: بجوار بيتنا مسجد، وأنا بفضل الله تعالى أقوم بفتح هذا المسجد في صلاة الفجر كل شهور السنة ماعدا شهر رمضان، يوجد شخص آخر يتولى فتح المسجد نظرًا لأنه هو المعين من قبل وزارة الأوقاف.وعندنا في مصر يقرأ القرآن في المساجد قبل صلاة الفجر، وبصوت مرتفع في مكبرات الصوت، بحجة أن ذلك يوقظ الناس للصلاة، وأنا أعلم أن ذلك بدعة من البدع، وإذا لم أقم بتشغيل الراديو على القرآن في المكبر، يقول الناس: إنك متشدد ومتزمت، وغير ذلك من الكلمات التي يطلقونها على المتمسكين بدينهم، أرجو توجيهي في هذا الموضوع.جزاكم الله خيرًا.","title":"حكم قراءة القرآن بمكبرات الصوت قبيل الفجر","answer":"الجواب: أنت مصيب يا أخي، وأنت وافقت السنة، والحمد لله، ولا يضر قول الناس، فإذا طلع الفجر فأذن، والحمد لله، يكفي الأذان، يكفي الأذان، وأما إعلان القراءة من المكبرات قبل الأذان في آخر الليل، فهذا لا أصل له، وقد يؤذي الناس، وقد يشق على النوام ويزعجهم. فالحاصل: أن هذا غير مشروع، ولم يكن يفعله المصطفى ﷺ ولا أصحابه ما كانوا يرفعون أصواتهم بالقرآن كالأذان حتى يوقظوا الناس، إنما كان الأذان كافيًا في عهده ﷺ وعهد أصحابه، إذا طلع الفجر فإن المؤذن أو نائب المؤذن يرفع الأذان بالمكبر حتى يوقظ الناس، وحتى ينبه الناس ويدعوهم إلى الصلاة في المسجد، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18008/حكم-قراءة-القران-بمكبرات-الصوت-قبيل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92210.mp3","categories":["البدع والمحدثات"]},{"id":18914,"question":"لأخينا سؤال آخر يسأل فيه سماحتكم عن رأيكم فيمن يصلي الجمعة، ثم يصلي الظهر أيضًا في يوم الجمعة.","title":"حكم صلاة الظهر عقب أداء صلاة الجمعة","answer":"الجواب: هذا بدعة، ما يفعله بعض الناس من صلاة الظهر بعد الجمعة هذا بدعة لا أصل له، والمشروع للمؤمن إذا صلى الجمعة أن يصلي بعدها أربع ركعات نافلة، كما قال -عليه الصلاة والسلام-: إذا صليتم بعد الجمعة فصلوا بعدها أربعًا -عليه الصلاة والسلام- وكان يصلي في البيت ركعتين -عليه الصلاة والسلام-. فالسنة أن يصلى بعد الجمعة أربع، وإن صلى ركعتين فلا بأس، أما أنه يصلي الظهر هذا بدعة لا أصل له، ولا ينبغي أن يغتر بما يفعله بعض الناس في بعض البلدان، هذا شيء لا أصل له، وهو ناشئ عن الشك، بعضهم يقول: أخشى أن الجمعة غير صحيحة، هذا شيء لا محل له، ولا ينبغي هذا التشكك وهذه الوسوسة، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18055/حكم-صلاة-الظهر-عقب-اداء-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92314.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":19066,"question":"هل قراءة سورة «يس» قبل كل عمل لها فضل في قضاء هذا العمل؟","title":"حكم قراءة سورة «يس» قبل كل عمل","answer":"الجواب: ليس لهذا أصل، ما له أصل هذا، بل بدعة . نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18268/حكم-قراءة-سورة-يس-قبل-كل-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88328.mp3","categories":["البدع والمحدثات"]},{"id":19208,"question":"أخونا اليمني يسأل ويقول: سمعنا أن نية الصلاة يكون محلها القلب ولا يصح التلفظ بها، و هل عندما أقف مستقبل القبلة أتحدث بالنية في قلبي ثم أكبر تكبيرة الإحرام، أما أن ما قمت به من وضوء ووقوف واستقبال القبلة يعتبر ترجمة لنية الصلاة، ولا يلزمني التحدث بها في قلبي، بل أكبر مباشرة، أفيدوني جزاكم الله خيرًا.","title":"حكم التلفظ بالنية عند الشروع في الصلاة","answer":"الجواب: نعم يكفيك ذلك، ما دمت قمت للصلاة التي تعلمها ظهر عصر مغرب إلى غير ذلك، يكفي، ولا حاجة إلى التحدث بها عند الإحرام، أنت جئت لها وجلست لها، وانتظرتها وقمت حين سمعت الإقامة، تقصد الصلاة التي أقيمت، هذا يكفي وهذا هو النية، ولا حاجة إلى سوى ذلك. أما ما يفعله بعض الناس من التلفظ بأن يقول: نويت أن أصلي كذا وكذا، إمامًا أو مأمومًا أو كذا، هذا لا أصل له، بل هو بدعة في أصح قولي العلماء؛ لأن الرسول ﷺ لم يكن يتلفظ بالنية، وهكذا أصحابه  ما كانوا يتلفظون بالنية، وهكذا التابعون وأتباعهم من الأئمة الأربعة وغيرهم ما كانوا يعرفون هذا، فالمشروع للمؤمن أن يكتفي بالقلب، أن يكتفي بالقلب.. فهو بمجيئه للصلاة وجلوسه ينتظر الصلاة، وبقيامه للصلاة حين أقيمت الصلاة، كل هذا يعتبر نية، فلا حاجة بعد ذلك إلى أن يتحدث بها بقلبه، ولا أن يتلفظ بها بلسانه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18396/حكم-التلفظ-بالنية-عند-الشروع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88803.mp3","categories":["البدع والمحدثات","النية في الصلاة"]},{"id":19210,"question":"عندنا عادات أننا نذبح في كل سنة في شهر شعبان ذبيحة لوجه الله، كل حسب استطاعته هل هذا الذبح جائز، مع أن البعض يقولون: هذا سنة عن رسول الله ﷺ ويعتبرون هذا ضمن الفدي؟","title":"حكم تخصيص الذبح في شهر شعبان","answer":"الجواب: تخصيص وقت من الأوقات بالذبح ليس عليه دليل إلا ما شرع الله في أيام النحر، فلا يخصص شعبان ولا غيره بذبح، وإذا اعتاد الناس ذلك فهي عادة سيئة، يجب أن تغير حتى لا يظن الجهلة أنها قربة وطاعة. فالإنسان يتقرب إلى الله بالذبائح في كل وقت، في رمضان .. في شوال .. في شعبان .. في ذي القعدة .. في المحرم .. في ربيع أول .. ربيع ثاني في أي وقت، إذا تقرب لوجه الله متى يسر الله له الذبح، فإذا ذبح في شعبان أو في رمضان أو في شوال أو غيرها إبلًا أو بقرًا أو غنمًا، ليصدق على الفقراء والمحاويج أو على أقاربه وجيرانه أو على ضيفانه ونحوه كل ذلك لا بأس به. أما أن يخص شعبان عن عقيدة أو يخص رمضان عن عقيدة أو يخص غيرهما فلا، أما إذا ذبح في رمضان لأجل فضل الشهر وقصد التقرب إلى الله في هذا الشهر الكريم فهذا لا بأس من أجل فضل الشهر، كما يتقرب إلى الله في أيام النحر؛ لأن الله شرع في ذلك الذبح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18385/حكم-تخصيص-الذبح-في-شهر-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93305.mp3","categories":["البدع والمحدثات"]},{"id":19219,"question":"تسأل عن حفلات أعياد الميلاد شيخ عبد العزيز ، وترجو توجيهكم فيها؟","title":"توجيه حول الاحتفال بأعياد الميلاد","answer":"الجواب: حفلات الميلاد من البدع التي بينها أهل العلم، وهي داخلة في قوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته من حديث عائشة رضي الله عنها. وقال -أيضًا- عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد خرجه الإمام مسلم في صحيحه، وقال عليه الصلاة والسلام في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه مسلم في صحيحه، زاد النسائي بإسناد صحيح وكل ضلالة في النار فالواجب على المسلمين ذكورًا كانوا أو إناثًا الحذر من البدع كلها. والإسلام بحمد الله فيه الكفاية وهو كامل، قال تعالى: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3]. فقد أكمل الله لنا الدين بما شرع من الأوامر والعبادات وما نهى عنه من النواهي فليس الناس في حاجة إلى بدعة يبتدعها أحد لا احتفال الميلاد ولا غيره. فالاحتفالات بميلاد النبي ﷺ أو بميلاد الصديق أو عمر أو عثمان أو علي أو الحسن أو الحسين أو فاطمة أو البدوي أو الشيخ: عبد القادر الجيلاني، أو فلان أو فلان كل ذلك لا أصل له، كله منكر كله منهي عنه، وكله داخل في قوله عليه الصلاة والسلام: وكل بدعة ضلالة. فلا يجوز للمسلمين تعاطي هذه البدع ولو فعلها من فعلها من الناس، فليس فعل الناس تشريعًا للمسلمين، وليس فعل الناس قدوة إلا إذا وافق الشرع، فأفعال الناس وعوائدهم كلها تعرض على الميزان الشرعي كتاب الله وسنة رسوله عليه الصلاة والسلام، فما وافقهما قبل وما خالفهما ترك، كما قال سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]. وفق الله الجميع وهدى الجميع صراطه المستقيم.","link":"https://binbaz.org.sa/fatwas/18393/توجيه-حول-الاحتفال-باعياد-الميلاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93313.mp3","categories":["البدع والمحدثات"]},{"id":19228,"question":"يسأل أخونا ويقول: هل لبس دبلة الخطبة من الكبائر أم من الصغائر؟","title":"حكم لبس دبلة الخطوبة","answer":"الجواب: لا شك أنها مكروهة، ولا أصل لها فيما نعلم، فينبغي تركها، أما كونها من الكبائر أو الصغائر فمحل نظر، لكن بكل حال لا ينبغي تعاطيها؛ لأنها مستوردة من الكفرة، فلا وجه لاستعمالها ولا حاجة إليها، متى تم العقد فالحمد لله ولا يحتاج دبلة يلبسها. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18412/حكم-لبس-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89002.mp3","categories":["الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":19235,"question":"بعد هذا رسالة وصلت إلى البرنامج من اليمن محافظة حضرموت باعثتها إحدى الأخوات تقول: (م. ع. س. باكردر) تسأل وتقول: من عادات أهل قريتنا في اليوم الثاني من الزواج يقومون بتقريب إصبع رجل الزوج مقابلة ومماسًا له إصبع رجل المرأة ويذبحون عليها شاة، فما حكم ذلك؟","title":"حكم الذبح عند قدمي الزوجين عند زواجهما","answer":"الجواب: هذا عمل لا أصل له، بل هو باطل، والواجب تركه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18423/حكم-الذبح-عند-قدمي-الزوجين-عند-زواجهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73807.mp3","categories":["البدع والمحدثات"]},{"id":19236,"question":"ومن العادات أيضًا: أنهم يذبحون كبشًا في محل المكان الذي يقع عليه المولود عند ولادته، ما حكم الشرع في ذلك؟","title":"حكم الذبح في مكان ولادة المولود","answer":"الجواب: كذلك هذا باطل منكر بدعة، يجب تركه؛ لقول النبي ﷺ: من أحدث في أمرنا ما ليس منه فهو رد، يعني: في ديننا، وهذا لا أصل له في الدين أن يذبح في مكان المولود ذبيحة، ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، يعني: فهو مردود. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18427/حكم-الذبح-في-مكان-ولادة-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73808.mp3","categories":["البدع والمحدثات"]},{"id":19295,"question":"نعود في بداية هذه الحلقة إلى رسالة أحد الإخوة المستمعين، يقول المرسل (ي . م . ر)، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: رأيت في أحد المساجد في بعض البلدان الإسلامية عندما ينتهون من كل صلاة فريضة يسبحون الله بشكل جماعي، أي: يقول الإمام: سبحان الله، فيقول المأمومون: سبحان الله، إلى أن ينتهوا إلى ثلاث وثلاثين، ويقول الإمام: الحمد لله، ويقول المأمومون مثل قوله، وهكذا.. أفيدونا عن حكم مثل هذا العمل، جزاكم الله خيرًا.","title":"حكم أداء الذكر بعد الصلاة بصفة جماعية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه؛ نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فهذا العمل الذي ذكره السائل، وهو أن الإمام والمأمومين يسبحون ويحمدون ويكبرون بصفة جماعية بعد كل صلاة هذا لا أصل له، وليس من السنن المشروعة بل هو من البدع. الرسول ﷺ رغب الناس أن يسبحوا ويحمدوا ويكبروا ثلاثًا وثلاثين بعد كل صلاة، ولم يكن يفعل ذلك معهم بصفة جماعية بل كان يذكر الله في نفسه، وكل واحد من الجماعة يذكر الله في نفسه، هذا هو المشروع، فكل واحد يشتغل بنفسه، فالإمام بنفسه، وكل واحد من الجماعة كذلك، فيقول بعد السلام (أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام)، يقوله الإمام والمأموم والمنفرد، هذه السنة، لما ثبت عن ثوبان  مولى النبي ﷺ قال: كان النبي ﷺ إذا انصرف من صلاته استغفر ثلاثًا وقال: اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، وثبت عن عائشة رضي الله عنها في صحيح مسلم أنه: كان الرسول ﷺ إذا فرغ من قوله: اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، انصرف إلى الناس وأعطاهم وجهه الكريم عليه الصلاة والسلام فهذا يدل على أن الإمام يأتي بهذا قبل أن ينصرف، حال كونه مستقبلاً القبلة. ثم ينصرف إلى الناس فيقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير وإن زاد قال: يحيي ويميت، فكل هذا ورد عن النبي عليه الصلاة والسلام، ويقول أيضًا: لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد هذا ثبت من فعل النبي ﷺ بعضه من حديث المغيرة بن شعبة وبعضه من حديث عبد الله بن الزبير رضي الله عن الجميع. وقال عليه الصلاة والسلام: من سبح الله ثلاثًا وثلاثين، وكبر الله ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين فتلك تسع وتسعون، وقال تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير؛ غفرت خطاياه وإن كانت مثل زبد البحر خرجه مسلم في صحيحه، فهذا يدل على شرعية هذا الذكر، وأن كل واحد يقوله بنفسه، ما يحتاج إلى أن يكون معه غيره، فأداء ذلك بصفة جماعية من الجماعة أو من الجماعة مع الإمام كل ذلك لا أصل له، وقد قال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، وقال أيضًا عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، متفق على صحته. فنصيحتي لمن يفعل هذا أن يدع ذلك وأن يسبح كل واحد بنفسه مستقلاً من دون مشاركة غيره، رزق الله الجميع التوفيق واتباع السنة . نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18479/حكم-اداء-الذكر-بعد-الصلاة-بصفة-جماعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89301.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":19339,"question":"يقول أخونا في سؤاله الأخير: عندما يصعد الخطيب فوق المنبر يبدأ الأذان يوم الجمعة بعد الأذن مباشرة يقوم الإمام الخامس ويقول: عن أبي هريرة عن النبي ﷺ قال: إذا قلت لصاحبك يوم الجمعة أنصت والإمام يخطب فقد لغوت، ومن لغا فلا جمعة له أنصتوا يرحمكم الله، أنصتوا يرحمكم الله، أنصتوا يرحمكم الله، بعد إتمام هذا الحديث يجلس ويقوم الإمام لبدء خطبة الجمعة، مع العلم أن هذا يتكرر كل جمعة، أفتونا في هذا؟ جزاكم الله خيرًا.","title":"حكم قول: (أنصتوا يرحمكم الله) عقب أذان الجمعة","answer":"الجواب: هذا العمل ليس له أصل في الشرع، بل هو بدعة كونه يقوم إنسان ويقول: أيها الناس! يتلو الحديث، عن النبي ﷺ أنه قال: إذا قلت لصاحبك أنصت يوم الجمعة، والإمام يخطب؛ فقد لغوت، ومن مس الحصا فقد لغا هذا ليس له أصل، وما كان يفعله المسلمون في عهد النبي ﷺ ولا عهد خلفائه الراشدين، بل هو من البدع، بل إذا أذن المؤذن يوم الجمعة قام الخطيب، وخطب الناس، وليس هناك من ينبه الناس، ويقول لهم: أنصتوا، لا بتلاوة الحديث ولا بغير ذلك، فهذا من المحدثات التي ليس لها أصل. والواجب على من أحدثها أن يدعها، وأن يتوب إلى الله من ذلك، لقول النبي عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، وقوله عليه الصلاة والسلام: من أحدث في أمرنا - يعني: في ديننا - ما ليس منه فهو رد يعني: فهو مردود. وكان عليه الصلاة والسلام في خطبة الجمعة يقول: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها وكل بدعة ضلالة خرجه مسلم في صحيحه. فالواجب على أهل الإسلام التمسك بالسنة في كل شيء، والسير عليها، والتواصي بها، والحذر من البدع التي أحدثها الناس، ومن ذلك ما ذكرته أنه يفعل عندكم قبل الخطبة بأن يقوم إنسان يتلو الحديث، المعروف عن النبي ﷺ: إذا قلت لصاحبك: أنصت يوم الجمعة فقد لغوت ثم يكرر يقول: أنصتوا أنصتوا كل هذا لا أصل له كما سمعت، نسأل الله للجميع الهداية والتوفيق لما فيه اتباع السنة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18546/حكم-قول-انصتوا-يرحمكم-الله-عقب-اذان-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94108.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":19405,"question":"له سؤال آخر عن أولئك الذين يزورون القباب وقبور بعض الصالحين كما يسميهم، ما هو توجيهكم شيخ عبد العزيز ؟","title":"حكم زيارة القباب والقبور","answer":"الجواب: يعلمون الزيارة الشرعية، يعلمون زيارة القبور الزيارة الشرعية، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية. وفي حديث آخر قال: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون غدًا مؤجلون وأتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد، وفي حديث آخر قال عليه الصلاة والسلام: يرحم الله المستقدمين منا والمستأخرين، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر هذا وأشباهه يدعى به للموتى.\nأما وضع القباب على القبور أو المساجد هذا لا يجوز، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ويقول ﷺ لـعلي : لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته وصح عنه عليه الصلاة والسلام من حديث جابر عند مسلم في صحيحه: أنه نهى عليه الصلاة والسلام عن تجصيص القبور، والقعود عليها، والبناء عليها فالقبور لا يبنى عليها بنص النبي عليه الصلاة والسلام، ولا يتخذ عليها مساجد ولا قباب، ولا تجصص ولا يقعد عليها فتمتهن، كل هذا ممنوع، ولا تكسى بالستور كل هذا ممنوع، وإنما يرفع القبر عن الأرض قدر شبر تقريبًا ليعرف أنه قبر حتى لا يمتهن ولا يوطأ. فالمؤمن يبلغ إخوانه ويعلمهم وهكذا طالب العلم، وهكذا العلماء يعلمون الناس ما شرعه الله، والمؤمن يتعلم من العلماء ويعلم من يأتي القبور، يقول لهم: إن الزيارة الشرعية كذا وكذا، أما البناء على القبور أو سؤال الميت أو التبرك بتراب القبر أو تقبيل القبر أو الصلاة عنده كل هذه من البدع، لا يصلى عند القبور، ولا تتخذ محلًا للدعاء تقصد للدعاء عندها ولا القراءة عندها، كل هذا من البدع.\nكذلك طلب البركة منها أو الشفاعة منها أو الشفاء هذا من أنواع الشرك الأكبر، إذا قال: يا سيدي فلان! اشفع لي إلى الله، ويقول للميت: انصرني أو اشف مريضي، هذا لا يجوز؛ لأن الميت انقطع عمله بعد موته إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. أما أنه يطلب منه شفاء المرضى أو النصر على الأعداء أو الشفاعة إلى الله في كذا هذا قد انقطع، لا يجوز طلبهم، بل يطلب من الله  اللهم اشفني .. اللهم أعطني كذا .. اللهم شفع في أنبياءك .. اللهم شفع في نبيك محمد ﷺ .. اللهم شفع في أفراطي، اللهم شفع في الملائكة والمؤمنين، هذا لا بأس به تطلب من الله جل وعلا. فالخلاصة أن المسلمين ينصح بعضهم بعضًا، ويعلم بعضهم بعضًا بأمر الشرع، والعلماء عليهم بيان ذلك وتوجيه العامة لما شرع الله  ومن ذلك أن يعلموا الزيارة الشرعية للقبور التي جاءت في الأحاديث عن رسول الله عليه الصلاة والسلام والتي تقدم بيانها. ويعلمون أنه لا يجوز البناء على القبور لا قباب ولا مساجد ولا أبنية أخرى، ولا تجصص ولا يقعد عليها، ولا تتخذ محلًا للدعاء عندها، أو الصلاة عندها، أو القراءة عندها، هذه من البدع التي هي من وسائل الشرك، الصلاة عندها والقعود عندها للدعاء أو القراءة هذا من وسائل الشرك من البدع، أما دعاء الميت والاستغاثة بالميت والنذر له والذبح له، هذا من الشرك الأكبر نعوذ بالله، من عمل الجاهلية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18631/حكم-زيارة-القباب-والقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93602.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":19417,"question":"مستمع من الطائف بعث برسالة ضمنها عددًا من الأسئلة، يقول أخوكم في الله صالح الحاج جسار الريمي اليماني أخونا يقول في أحد أسئلته: لدينا عادات وتقاليد مخالفة لشريعتنا الإسلامية الغراء، ومن هذه العادات ما يلي: يجتمع الناس يوم الجمعة قبل صلاة الجمعة فيصلون على النبي ﷺ بصوت مرتفع وجماعي، ثم إنهم يستغيثون بالنبي ﷺ وبأولياء الله الصالحين بهذه الألفاظ \"شيء لله يا رسول الله! شي لله يا أولياء الله الصالحين! شيء لله يا رجال الله المؤمنين! أغيثونا أعينونا مدونا بالرعاية\" وكأمثال هذه الألفاظ ويرجو التوجيه؟ جزاكم الله خيرًا.","title":"حكم الاجتماع للصلاة على النبي بصوت مرتفع","answer":"الجواب: أما الاجتماع على الصلاة على النبي ﷺ بصوت جماعي أو بصوت مرتفع هذا بدعة والمشروع للمسلمين أن يصلوا على النبي ﷺ من دون رفع الصوت المستغرب المستنكر ومن دون أن يكون ذلك جماعيًا، كل واحد يصلي بينه وبين نفسه يقول: اللهم صل على رسول الله، اللهم صل وسلم على رسول الله، اللهم صل على محمد وعلى آل محمد إلى آخره، يصلي بينه وبين نفسه؛ لأن يوم الجمعة يشرع فيها الإكثار من الصلاة على النبي ﷺ لأنه أمر بهذا عليه الصلاة والسلام قال: إن خير أيامكم يوم الجمعة، فأكثروا علي من الصلاة فيها، فإن صلاتكم معروضة علي قيل: يا رسول الله! تعرض عليك صلاتنا وقد أرمت -يعني: بليت، قال: إن الله حرم على الأرض أن تأكل أجساد الأنبياء. فالمقصود أنه ﷺ شرع لنا أن نكثر من الصلاة عليه والسلام في يوم الجمعة فيشرع لنا أن نكثر من ذلك في المسجد وفي غيره لكن كل واحد يصلي على النبي ﷺ بينه وبين نفسه، بالصلوات المشروعة المعروفة من دون أن يكون ذلك بصوت مرتفع يشوش على من حوله أو بصوت جماعي يتكلم جماعة جميعًا كل هذا بدعة، ولكن يصلي على النبي ﷺ بينه وبين نفسه في مسجده وفي طريقه وفي بيته وفي كل مكان، وهكذا في بقية الأوقات تشرع الصلاة على النبي ﷺ حتى في غير الجمعة في بقية الأوقات، الله يقول سبحانه: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] اللهم صل عليه وسلم صلاة وسلامًا دائمين إلى يوم الدين، ويقول النبي ﷺ: من صلى علي واحدة صلى الله عليه بها عشرًا. فأنا وأنت والآخر والآخر كل منا مشروع له أن يصلي على النبي ﷺ للرجال والنساء جميعًا، لكن بالطريقة التي درج عليها المسلمون، درج عليها أصحاب النبي ﷺ وأتباعهم بإحسان كل واحد يصلي على النبي ﷺ بينه وبين نفسه من غير حاجة إلى أن يرفع صوته حتى يشغل من حوله ومن غير حاجة أن يكون معه جماعة بصوت جماعي لا. أما الاستغاثة بالأنبياء أو بأهل الخير أو بالأولياء هذا من الشرك الأكبر هذا أعظم وأطم لا يجوز هذا، لا يقول: يا رجال الغيب ... شيء لله أو يا أولياء الله! شيء لله أو يا رسول الله! شيء لله، أو أغيثونا أو أعينونا أو انصرونا كل هذا منكر وشرك أكبر بالله ، يقول الله سبحانه في كتابه العظيم: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] سماه كفر، قال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14] سماه الله شركًا. فالواجب الحذر من هذا والله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول جل وعلا: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]. فالله هو اللي يدعى  هو الذي يسأل وهو الذي يكشف الضر وهو الذي يجلب النفع ، فتقول: يارب! اشفني، يارب! أعني، يا رب! اهدني سواء السبيل يا رب! أصلح قلبي وعملي يا رب! توفني مسلمًا، تدعو ربك وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] ويقول سبحانه: وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ [النساء:32] ويقول جل وعلا: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] ويقول النبي ﷺ: الدعاء هو العبادة. فالواجب على المسلمين رجالًا ونساءً الإكثار من الدعاء والحرص على الدعاء، دعاء الله جل وعلا والضراعة إليه في جميع الحاجات . أما دعاء الأنبياء أو الأولياء أو غيرهم من الناس عند قبورهم أو في أماكن بعيدة عنهم فكل هذا منكر، كله شرك بالله  وكفر أكبر يجب الحذر منه كهذا الذي ذكره السائل، يا عباد الله يا أنبياء الله! يا نبي الله! أعينونا أغيثونا انصرونا هذا كله من الشرك الأكبر، قال الله جل وعلا: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] ويقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] ويقول جل وعلا يخاطب نبيه محمد ﷺ: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] فالأمر عظيم، ويقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]. فالواجب الحذر والواجب على كل مسلم وكل من ينتسب للإسلام وكل مكلف أن يعبد الله وحده وأن يخصه بالعبادة دون كل ما سواه وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] فلا تسأل نبيًا ولا وليًا ولا شجرًا ولا حجرًا ولا صنمًا، ولا غير ذلك لا تسأله حاجة من نصر ولا شفاء مريض ولا غير ذلك، بل اسأل الله سبحانه حاجتك كلها هذا هو توحيد الله، وهذا هو الدين، وهذا هو الإسلام أن توجه إلى الله بسؤالاتك وحاجاتك وأن تعبده وحده بدعائك وصلاتك وصومك وسائر عباداتك. أما المخلوق وإن كان عظيمًا كالأنبياء لا يدعى من دون الله ولا يستغاث به ولا ينذر له ولا يذبح له، فعلى المسلمين أن يفهموا هذا جيدًا، على كل إنسان أن يفهم هذا جيدًا وأن يعلم أن هذا أمره عظيم، وأن أصل دين الإسلام وقاعدة دين الإسلام إخلاص العبادة لله وحده وهذا هو معنى: لا إله إلا الله، فإن معناها لا معبود حق إلا الله، فالله سبحانه هو اللي يدعى يسأل كما قال : وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] إِنَّمَا إِلَهُكُمُ اللَّهُ الَّذِي لا إِلَهَ إِلَّا هُوَ وَسِعَ كُلَّ شَيْءٍ عِلْمًا [طه:98]. فالخطأ في هذا الأمر عظيم جدًّا لا يجوز التساهل به لأنه شرك الجاهلية شرك المشركين الأولين لأنه ضد الإسلام ضد لا إله إلا الله، فالواجب الحذر من هذه الشركيات وعليك أيها السائل! أن تنذر قومك وأن تبلغهم وأن ترشدهم إلى أن يسمعوا هذا البرنامج حتى يستفيدوا لما فيه من الخير العظيم هذا البرنامج نور على الدرب فيه خير عظيم وفوائد كثيرة، فيه التوحيد وفيه أحكام الشريعة، فأنا أوصي وأنصح جميع المسلمين أن يستمعوا هذا البرنامج في كل مكان في هذه المملكة وفي خارجها، أنصح جميع المسلمين وجميع المكلفين، أن يسمعوا هذا البرنامج، وأن يعتنوا به حتى يستفيدوا منه، وحتى يبلغوا غيرهم من إخوانهم من الرجال والنساء حتى يستفيدوا. وهو بحمد الله برنامج من قال الله قال رسوله، ليس من الآراء، برنامج يبين فيه أهل العلم ما قاله الله ورسوله في توحيده وفي أحكام شريعته، نسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/18645/حكم-الاجتماع-للصلاة-على-النبي-بصوت-مرتفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93612.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":19419,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع أخونا في الله صالح الحاج جسار الريمي اليماني، أخونا من مدينة الطائف بعث بعدة أسئلة، وعرضنا جزءًا منها في حلقة مضت، وفي هذه الحلقة يسأل ويقول: هل يجوز الاستغفار بصوت مرتفع، وبعد ذلك يقول الإمام: الفاتحة بقبول الدعاء وقبول الصلاة ثم إلى روح النبي ﷺ؟","title":"حكم الجهر بالذكر عقب الصلاة وقول: الفاتحة إلى روح النبي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفالمشروع للمسلمين بعد الفراغ من صلاة الفريضة أن يقول الإمام والمأموم بعد السلام: أستغفر الله، بصوت يسمعه من حولهم: أستغفر الله، أستغفر الله-ثلاث مرات- اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام! ثم يقول كل واحد بعد ذلك: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد ثبت هذا عن رسول الله عليه الصلاة والسلام بعد كل فريضة، بعضه من حديث ثوبان وبعضه من حديث ابن الزبير وبعضه من حديث المغيرة بن شعبة، هذا السنة للجميع برفع الصوت المناسب الذي ليس فيه إزعاج، وليس فيه خفض الصوت، لكن صوت مناسب يسمعه من حول المسجد من عند الباب حتى يعلموا أن الصلاة انتهت. قال ابن عباس رضي الله تعالى عنهما: «كان رفع الصوت بالذكر حين ينصرف الناس من المكتوبة كان على عهد النبي ﷺ، قال: كنت أعلم إذا انصرفوا بذلك إذا سمعتهم» كان صبي قد لا يحضر، فكان يسمع هذا فيعرف أن الناس قد صلوا. المقدم: قد انصرفوا، نعم. الشيخ: وفي لفظ آخر قال: «ما كنا نعرف انقضاء صلاة رسول الله ﷺ إلا بالتكبير»؛ لأنه مشروع للناس أن يكبروا ثلاثًا وثلاثين يسبحون ثلاثًا وثلاثين ويحمدون ثلاثًا وثلاثين بعد كل صلاة من الصلوات الخمس، فهذا هو المشروع. أما قول الإمام: الفاتحة بقبول الصلاة أو رفع الصوت بالدعاء جماعيًا هذا بدعة لا يجوز، بل كل واحد يذكر الله بنفسه لا بصوت جماعي، ولا يشترط لهم أن يقرءوا الفاتحة لقبول الدعاء، لا، غير مشروع تلاوة الفاتحة بعد كل صلاة، إنما المشروع بعد كل صلاة قراءة: قُُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين بينه وبين نفسه، أما قراءة الفاتحة فلم يرد في الأحاديث الصحيحة ما يدل على ذلك، فقراءتها عند الدعاء لقصد الدعاء ليس له أصل، ولكن يستحب عند الدعاء حمد الله والصلاة على رسوله ﷺ ثم يدعو؛ لأن هذا من أسباب الإجابة، فإذا حمد الله وأثنى عليه قبل أن يدعو ثم صلى على النبي ﷺ في خارج الصلاة أو في داخل الصلاة في آخر التحيات أو في سجوده فلا بأس، إذا أثنى على الله وصلى على النبي ﷺ الصلاة دعاء ثم دعا بعد ذلك كل هذا طيب، أما أن يكون بصوت مرتفع بعد الصلوات بصوت جماعي هذا منكر. فالواجب على أهل الإسلام أن يتمسكوا بالشرع، وأن لا يزيدوا ولا ينقصوا، لا فيما يتعلق بالصلاة ولا فيما يتعلق بالأذكار بعدها ولا في غير ذلك. والعبادات عند أهل العلم توقيفية ليست بالرأي بل العبادات موقوفة على ما جاء عن رسول الله ﷺ، فما جاء عنه وثبت عنه فهو المشروع، وما سوى ذلك فهو بدعة، والواجب على أهل الإسلام التقيد بالسنة والحذر من البدعة، ولهذا كان ﷺ يخطب يوم الجمعة ويقول: أما بعد، فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة يحذرهم من البدعة وهي الإحداث في الدين، يعني: إحداث عبادات ما شرعها الله. ومن هذا قوله ﷺ في الحديث الصحيح المتفق عليه من حديث عائشة رضي الله عنها: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، متفق عليه، ويقول ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد أي: فهو مردود. فالواجب على المسلمين من الرجال والنساء التقيد بالشرع، والتمسك بما جاء في الشرع فقط في الأذكار وغير الأذكار، في الصلاة، وفي الصوم، وفي الحج، وفي الأذكار، وفي جميع العبادات، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18647/حكم-الجهر-بالذكر-عقب-الصلاة-وقول-الفاتحة-الى-روح-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93701.mp3","categories":["البدع والمحدثات","الأدعية والأذكار"]},{"id":19421,"question":"أخونا -أيضًا- يسأل ويقول: إذا مات الإنسان وكان نجمه الحمل فهل يأتي الحمل إلى قبره وينبشه ليحمله؟","title":"الرد على بعض الخرافات في الأنواء","answer":"الجواب: هذه خرافة لا أصل لها ولا عبرة بالأنواء، ولا ينظر في أنواء فلان وفلان ولا النجم الذي ولد فيه، كل هذه خرافات من أمر الجاهلية، لا ينظر في أنواء الإنسان الميت هل ولد في الحمل أو في كذا أو في كذا أو في كذا لا ينظر فيها، هذه أمور لا أساس لها ولا يلتفت إليها، وليس لها تعلق بحياته ولا موته ولا ثوابه ولا عقابه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18651/الرد-على-بعض-الخرافات-في-الانواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93703.mp3","categories":["البدع والمحدثات","مسائل متفرقة في العقيدة"]},{"id":19497,"question":"من أسئلة هذا السائل يقول: بعد وفاة الميت بأسبوع يقوم أهل الميت بعمل وليمة ويسمونها: صدقة، فهل هذا العمل جائز ويصل إلى الميت؟","title":"حكم عمل وليمة بعد الأسبوع الأول من دفن الميت","answer":"الجواب: لا هذا بدعة ما يجوز، هذا مأتم لا يجوز، يقول جرير  ابن عبد الله البجلي الصحابي الجليل: «كنا نعد الاجتماع لأهل الميت وصنعة الطعام بعد الدفن من النياحة»، ما يصلح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18743/حكم-عمل-وليمة-بعد-الاسبوع-الاول-من-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93925.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":19519,"question":"هذا السائل يقول: في قيام رمضان بعد كل أربع ركعات يجلس الإمام ويقرأ سورة الإخلاص حتى ينتهي منها، فيقرأها المصلون بصوت واحد وذلك ثلاث مرات، ما حكم هذا العمل؟","title":"حكم القراءة الجماعية لسورة الإخلاص بين ركعات التراويح","answer":"الجواب: هذه بدعة أقول: هذا من البدع، لا أصل له، نسأل الله العافية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18769/حكم-القراءة-الجماعية-لسورة-الاخلاص-بين-ركعات-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93935.mp3","categories":["البدع والمحدثات"]},{"id":19531,"question":"يقول السائل: ما حكم من يقول بعد الصلاة: الفاتحة، بنية الشفاء لطالب الشفاء؟","title":"حكم طلب قراءة الفاتحة عقب الفريضة بنية الشفاء","answer":"الجواب: هذا بدعة لا أصل له، هذا بدعة، وإنما المشروع يقرأ على المريض إذا قرأ عليه الفاتحة أو غيرها لا بأس، أما يقول: الفاتحة وبس هذا بدعة. نعم.","link":"https://binbaz.org.sa/fatwas/18777/حكم-طلب-قراءة-الفاتحة-عقب-الفريضة-بنية-الشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93939.mp3","categories":["البدع والمحدثات","الطب والتداوي"]},{"id":19600,"question":"من سوريا السائل محمود صالح يقول: ما حكم التلفظ بنية الصلاة، كأن يقول المصلي: نويت أصلي فرض صلاة الظهر أربع ركعات لله تعالى، في لحظة تكبيرة الإحرام؟","title":"حكم التلفظ بالنية في الصلاة","answer":"الجواب: التلفظ بالنية بدعة لا يجوز، ولكن ينوي بقلبه الظهر والعصر والمغرب والعشاء والفجر، ولا يقول: نويت أن أصلي كذا وكذا؛ لأن الرسول ﷺ ما فعل هذا ولا أصحابه ، فالتلفظ بالنية منكر ولكن محلها القلب في جميع العبادات، إلا في الحج والعمرة فيقول: لبيك عمرة أو لبيك حج يصرح، اللهم لبيك عمرة، واللهم لبيك حج، أول ما يحرم، وأما ما سوى الحج والعمرة فإن محلها القلب. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18862/حكم-التلفظ-بالنية-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94914.mp3","categories":["البدع والمحدثات"]},{"id":19665,"question":"تقول في آخر أسئلتها السائلة من اليمن: هناك قبور تزار من قبل بعض الناس، فهل يجوز لهم ذلك، حيث أنهم يذبحون عندها؟ وهل يجوز أن يأكلوا اللحم عند هذه القبور؟","title":"حكم الذبح والدعاء والقراءة عند القبور","answer":"الجواب: الذبح عند القبور لا يجوز، ولا الجلوس عندها للقراءة والدعاء، بل يجب الحذر من ذلك، بل هذا من وسائل الشرك، وإذا ذبح يتقرب إلى أصحاب القبور أو دعاهم أو استغاث بهم أو نذر لهم هذا شرك أكبر، هذا شرك أكبر نعوذ بالله. أما زيارة القبور للسلام عليهم والدعاء لهم لا بأس سنة، يقول النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة فإذا زارها المؤمن ليدعو لهم ويسلم عليهم ويستغفر لهم فلا بأس، أما أن يزورهم للذبح عندهم أو للقراءة عندهم أو للدعاء عند قبورهم هذا منكر لا يجوز ومن وسائل الشرك، فإذا ذبح لهم أو دعاهم أو استغاث بهم أو نذر لهم فقد صار هذا شركًا أكبر نعوذ بالله. أما النساء فلا يزرن القبور، يدعون لأمواتهم وهن في البيوت، لا حاجة إلى زيارة القبور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18954/حكم-الذبح-والدعاء-والقراءة-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95018.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]}]
